package io.droptracker;

import io.droptracker.api.*;
import com.google.inject.Provides;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.util.ArrayList;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;

import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.swing.SwingUtilities;

import io.droptracker.events.*;
import io.droptracker.models.PrivacyMode;
import io.droptracker.models.submissions.Drop;
import io.droptracker.service.*;
import io.droptracker.ui.DropTrackerPanel;
import io.droptracker.ui.overlays.*;
import io.droptracker.util.*;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;
import net.runelite.api.events.*;
import net.runelite.api.gameval.NpcID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.*;
import net.runelite.client.plugins.*;
import net.runelite.client.plugins.loottracker.LootReceived;
import net.runelite.client.ui.*;
import net.runelite.client.ui.overlay.OverlayManager;

import net.runelite.client.util.ImageUtil;


@Slf4j
@PluginDescriptor(
		name = "DropTracker",
		description = "Track your drops, compete in events, and send Discord webhooks!",
		tags = {"droptracker", "drop", "webhook", "events"}
)
public class DropTrackerPlugin extends Plugin {
	@Inject
	private DropTrackerConfig config;
	@Inject
	private DropTrackerApi api;

	private DropTrackerPanel panel;

	private NavigationButton navButton;

	@Inject
	private KCService kcService;

	@Inject
	private RaidLootDeduplicator raidLootDeduplicator;

	/* Event Handlers */
	@Inject
	private DropHandler dropHandler;
	@Inject
	private QuestHandler questHandler;
	@Inject
	public ClogHandler clogHandler;
	@Inject
	public CaHandler caHandler;
	@Inject
	public PbHandler pbHandler;
	@Inject
	public PetHandler petHandler;
	@Inject
	public ExperienceHandler experienceHandler;
	@Inject
	public DeathHandler deathHandler;
	@Inject
	public DiaryHandler diaryHandler;
	@Inject
	public TrawlingHandler trawlingHandler;
	@Inject
	public PyramidPlunderHandler pyramidPlunderHandler;
	@Inject
	public SlayerHandler slayerHandler;
	@Inject
	private ConfigSnapshotHandler configSnapshotHandler;

	@Inject
	public ChatMessageUtil chatMessageUtil;
	@Inject
	private SubmissionManager submissionManager;

	/* Screenshot privacy: hides DMs / chat / the whole chatbox for the captured frame */
	@Inject
	private ScreenshotPrivacyService screenshotPrivacyService;

	@Inject
	private ConfigManager configManager;

	@Inject
	private NearbyPlayerTracker nearbyPlayerTracker;

	/* Clan broadcast relay + Discord chat bridge */
	@Inject
	private ClanRelayService clanRelayService;

	/* Server-controlled reference data: which varps/quest ids to read. Fetched
	 * once per session; every consumer tolerates it being absent. */
	@Inject
	private ManifestService manifestService;

	/* Account state sync: the current-state counterpart to the event
	 * submissions. Off unless the user opts in via syncAccountState. */
	@Inject
	private StateSyncService stateSyncService;
	@Inject
	private StateSyncScheduler stateSyncScheduler;
	@Inject
	private CollectionLogScraper collectionLogScraper;

	/* 3D character export; off unless the user opts in. */
	@Inject
	private PlayerModelService playerModelService;

	/* Event notifications + HUD (EVENT_PLUGIN_NOTIFICATIONS_PLAN P2) */
	@Inject
	private EventNotificationService eventNotificationService;
	/* Clan-chat team badges during an event (suggestion #150) */
	@Inject
	private EventTeamIndicatorService eventTeamIndicatorService;
	@Inject
	private EventToastOverlay eventToastOverlay;

	@Inject
	private EventHudOverlay eventHudOverlay;
	@Inject
	private OverlayManager overlayManager;

	private AtomicBoolean justLoggedIn = new AtomicBoolean(false);

	@Inject
	private ScheduledExecutorService executor;

	@Inject
	private DebugLogger debugLogger;

	@Nullable
	public Drop lastDrop = null;

	private boolean statsLoaded = false; 

	public boolean isTracking = true;
	public int ticksSinceNpcDataUpdate = 0;
	private boolean loginWarningsShown = false;

	private static final BufferedImage PANEL_ICON = ImageUtil.loadImageResource(DropTrackerPlugin.class, "icon.png");


	@Inject
