	@Subscribe
	public void onGameTick(GameTick event) {
		// Keep the raid roster warm even while tracking is paused so that
		// re-enabling mid-raid still produces complete participant lists.
		nearbyPlayerTracker.onGameTick();
		// Character model export: cheap no-op unless the outfit changed and the
		// player has been standing still.
		playerModelService.onTick();
		// Screenshots deferred a tick so late-announcing bosses are captured
		// with their drop message on screen; drained before the tracking check
		// so a mid-flight toggle can't strand one (see SubmissionManager).
		submissionManager.onGameTick();
		// Slayer task state stays current while tracking is paused; the handler
		// only submits when tracking is on.
		slayerHandler.onTick();
		// Watchdog for a capture whose frame never arrives: ticks keep coming
		// when rendering has stopped, and a stalled cycle holds every later
		// capture behind it.
		screenshotPrivacyService.onGameTick();

		if (!isTracking) {
			return;
		}

		// Check if we need to update panel on login and player is now available
		if (needsPanelUpdateOnLogin && client.getLocalPlayer() != null && client.getLocalPlayer().getName() != null) {
			needsPanelUpdateOnLogin = false; // Clear the flag

			// Use SwingUtilities to ensure UI updates happen on EDT
			String playerName = client.getLocalPlayer().getName();
			if (config.lastAccountName() != null && !config.lastAccountName().equals(playerName)) {
				/* In the case that the player has changed from the last time we stored their name/hash, we need to call the reset method on KCService... */
				kcService.reset();
			}
			config.setLastAccountName(playerName);
			config.setLastAccountHash(String.valueOf(client.getAccountHash()));
			// Load persisted submissions for this account
			submissionManager.loadSubmissions(String.valueOf(client.getAccountHash()));

			// Show login warnings once, now that varbits are guaranteed to be loaded
			if (!loginWarningsShown) {
				loginWarningsShown = true;
				if (config.clogEmbeds() && client.getVarbitValue(VarbitID.OPTION_COLLECTION_NEW_ITEM) == 0) {
					chatMessageUtil.warnClogSetting();
				}
				if (!config.useApi() && config.customApiEndpoint().equalsIgnoreCase("")) {
					chatMessageUtil.warnApiSetting();
				}
				// The update check talks to our API, so it only runs once the user
				// has enabled the integration (or pointed us at their own endpoint).
				if (config.useApi() || !config.customApiEndpoint().equalsIgnoreCase("")) {
					executor.submit(this::checkForPluginUpdates);
				}
			}

			SwingUtilities.invokeLater(() -> {
				try {
					if (panel != null) {
						panel.updatePlayerPanel();

						// Also update the home player button since config might now have player name
						panel.updateHomePlayerButton();
						statsLoaded = true;
					}
				} catch (Exception e) {
					log.debug("Couldn't Load Side Panel UI");
					statsLoaded = true;
				}
			});
		}

		/* Call individual event handlers */
		pbHandler.onTick();
		widgetEventHandler.onGameTick(event);
		petHandler.onTick();

		if (config.trackExperience()) {
			experienceHandler.onTick();
		}
	}

