	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged gameStateChanged) {
		GameState newState = gameStateChanged.getGameState();

		// Ahead of the LOADING short-circuit and the same-state guard: the
		// team-badge sprite block has to be claimed at LOGIN_SCREEN and
		// released at STARTING, because the client rebuilds its mod-icon
		// array on a restart.
		eventTeamIndicatorService.onGameStateChanged(newState);
		// Also ahead of it: entering or leaving a house is a LOADING transition.
		widgetEventHandler.onGameStateChanged(newState);

		if (newState == GameState.LOADING) {
			return;
		}

		GameState previousState = gameState.getAndSet(newState);
		if (previousState == newState) {
			return;
		}

		// A login or hop re-sends the slayer varps, so a count reading zero
		// then is not a finished task.
		slayerHandler.onGameStateChanged(newState);
		configSnapshotHandler.onGameStateChanged(newState);

		// Clear per-session handler state so a partially-coalesced PB, pet or
		// collection-log popup from before a logout/hop can't fire stale
		// notifications after the player comes back.
		if (newState == GameState.LOGIN_SCREEN || newState == GameState.HOPPING) {
			pbHandler.reset();
			petHandler.reset();
			clogHandler.reset();
		}

		justLoggedIn.set(newState == GameState.LOGGED_IN);

		if (previousState == GameState.HOPPING) {
			return;
		}

		if (justLoggedIn.get()) {
			return;
		}

		if (!isTracking || !config.trackExperience()) {
			return;
		}
		experienceHandler.onGameStateChanged(gameStateChanged);
	}

	public String getLocalPlayerName() {
		if (client.getLocalPlayer() != null) {
			return client.getLocalPlayer().getName();
		} else {
			return "";
		}
	}

	/**
	 * Best-effort update check against GET /plugin_version (runs on the executor).
	 * Below the server's minimum version: warn every login. Behind the latest
	 * version: prompt once per new version (tracked via lastVersionNotified).
	 */
	private void checkForPluginUpdates() {
		DropTrackerApi.VersionInfo info = api.fetchVersionInfo();
		if (info == null) {
			return;
		}

		if (info.minimumVersion != null && VersionUtil.isOlderThan(pluginVersion, info.minimumVersion)) {
			chatMessageUtil.sendChatMessage("Your DropTracker plugin (v" + pluginVersion
				+ ") is older than the minimum supported version (v" + info.minimumVersion
				+ ") — submissions may be rejected. Please update via the Plugin Hub.");
			if (info.message != null && !info.message.isEmpty()) {
				chatMessageUtil.sendChatMessage(info.message);
			}
			return;
		}

		if (info.latestVersion != null && VersionUtil.isOlderThan(pluginVersion, info.latestVersion)
				&& !info.latestVersion.equals(config.lastVersionNotified())) {
			config.setLastVersionNotified(info.latestVersion);
			chatMessageUtil.sendChatMessage("A new DropTracker version is available (v" + info.latestVersion
				+ ", you have v" + pluginVersion + "). Update via the Plugin Hub for the latest features and fixes.");
			if (info.message != null && !info.message.isEmpty()) {
				chatMessageUtil.sendChatMessage(info.message);
			}
		}
	}

}

package io.droptracker.api;

import lombok.AccessLevel;
import lombok.AllArgsConstructor;
import java.io.IOException;
import java.util.*;
import java.util.concurrent.ScheduledExecutorService;
import java.util.function.BiConsumer;
import java.util.function.Consumer;

import javax.annotation.Nullable;
import javax.inject.*;
import javax.swing.SwingUtilities;

import com.google.gson.*;

import io.droptracker.DropTrackerConfig;
import io.droptracker.models.api.DeathMessages;
import lombok.extern.slf4j.Slf4j;
import okhttp3.*;

/**
 * Reads and saves the logged-in account's own messages of one type: death,
 * clog, drop or pb ({@code GET/POST /player/death_messages}, {@code type}).
 *
 * <p>The same messages the website and Discord's {@code /settings} edit, keyed
 * by account: the server resolves the account hash, which is also all the
 * plugin's other endpoints go on. Every call runs on the injected executor and
 * answers on the Swing thread, because its only caller is the editor dialog.
 */
@Slf4j
@Singleton
@AllArgsConstructor(onConstructor_ = @Inject)
public class DeathMessageApi {

    private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");

    private final DropTrackerConfig config;
    private final DropTrackerApi api;
    private final Gson gson;
    private final OkHttpClient httpClient;
    private final ScheduledExecutorService executor;

    /** What a call came back with: the messages, or a sentence for the player. */
    @AllArgsConstructor(access = AccessLevel.PRIVATE)
    public static final class Result {
        @Nullable
        public final DeathMessages messages;
        @Nullable
        public final String error;

        public static Result ok(DeathMessages messages) {
            return new Result(messages, null);
        }

        public static Result failed(String error) {
            return new Result(null, error);
        }
    }

    /** Loads the account's messages; {@code callback} runs on the Swing thread. */
    public void fetch(@Nullable String playerName, long accountHash, String type, Consumer<Result> callback) {
        executor.execute(() -> {
            Result result = fetchNow(playerName, accountHash, type);
            SwingUtilities.invokeLater(() -> callback.accept(result));
        });
    }

    /** Replaces the account's messages; {@code callback} runs on the Swing thread. */
    public void save(@Nullable String playerName, long accountHash, String type, List<String> messages,
                     Consumer<Result> callback) {
        executor.execute(() -> {
            Result result = saveNow(playerName, accountHash, type, messages);
            SwingUtilities.invokeLater(() -> callback.accept(result));
        });
    }

    /**
     * Reads ({@code changes} null) or saves the privacy switches of the Discord
     * account that owns this one ({@code GET/POST /player/privacy}). Answers on
     * the Swing thread with the switches, or null and a sentence for the player.
     */
    public void privacy(@Nullable String playerName, long accountHash, @Nullable Map<String, Boolean> changes,
                        BiConsumer<Map<String, Boolean>, String> callback) {
        executor.execute(() -> {
            Map<String, Boolean> settings = null;
            String error = API_OFF;
            HttpUrl url = config.useApi() ? HttpUrl.parse(api.getApiUrl() + "/player/privacy") : null;
            if (url != null) {
                Request.Builder request = new Request.Builder().cacheControl(CacheControl.FORCE_NETWORK);
                String name = playerName == null ? "" : playerName;
                if (changes == null) {
                    request.url(url.newBuilder().addQueryParameter("player_name", name)
                        .addQueryParameter("acc_hash", String.valueOf(accountHash)).build());
                } else {
                    Map<String, Object> body = new HashMap<>();
                    body.put("player_name", name);
                    body.put("acc_hash", String.valueOf(accountHash));
                    body.put("settings", changes);
                    request.url(url).post(RequestBody.create(JSON, gson.toJson(body)));
                }
                error = UNREACHABLE;
                try (Response response = httpClient.newCall(request.build()).execute()) {
                    ResponseBody raw = response.body();
                    String text = raw == null ? "" : raw.string();
                    if (response.code() == 200) {
                        JsonObject parsed = gson.fromJson(text, JsonObject.class);
                        settings = new LinkedHashMap<>();
                        for (Map.Entry<String, JsonElement> e : parsed.getAsJsonObject("settings").entrySet()) {
                            settings.put(e.getKey(), e.getValue().getAsBoolean());
                        }
                        error = null;
                    } else {
                        error = errorText(gson, response.code(), text);
                    }
                } catch (IOException | RuntimeException e) {
                    log.debug("Privacy request failed: {}", e.toString());
                    settings = null;
                    error = UNREACHABLE;
                }
            }
            Map<String, Boolean> answer = settings;
            String problem = error;
            SwingUtilities.invokeLater(() -> callback.accept(answer, problem));
        });
    }

    private Result fetchNow(@Nullable String playerName, long accountHash, String type) {
        HttpUrl base = endpoint();
        if (base == null) {
            return Result.failed(API_OFF);
        }
        HttpUrl url = base.newBuilder()
            .addQueryParameter("player_name", playerName == null ? "" : playerName)
            .addQueryParameter("acc_hash", String.valueOf(accountHash))
            .addQueryParameter("type", type)
            .build();
        // FORCE_NETWORK: the injected client has a disk cache shared with the
        // whole of RuneLite, and a stale copy here would undo a save.
        Request request = new Request.Builder().url(url).cacheControl(CacheControl.FORCE_NETWORK).build();
        return execute(request);
    }

    private Result saveNow(@Nullable String playerName, long accountHash, String type, List<String> messages) {
        HttpUrl url = endpoint();
        if (url == null) {
            return Result.failed(API_OFF);
        }
        Map<String, Object> body = new HashMap<>();
        body.put("player_name", playerName == null ? "" : playerName);
        body.put("acc_hash", String.valueOf(accountHash));
        body.put("messages", messages);
        body.put("type", type);
        Request request = new Request.Builder()
            .url(url)
            .post(RequestBody.create(JSON, gson.toJson(body)))
            .build();
        return execute(request);
    }

    private Result execute(Request request) {
        try (Response response = httpClient.newCall(request).execute()) {
            ResponseBody body = response.body();
            return interpret(gson, response.code(), body == null ? "" : body.string());
        } catch (IOException e) {
            log.debug("Death message request failed: {}", e.toString());
            return Result.failed(UNREACHABLE);
        }
    }

    @Nullable
    private HttpUrl endpoint() {
        if (!config.useApi()) {
            return null;
        }
        return HttpUrl.parse(api.getApiUrl() + "/player/death_messages");
    }

    static final String API_OFF = "Turn on \"Use API Connections\" in the plugin settings to change this here.";
    static final String UNREACHABLE = "Couldn't reach the DropTracker. Try again in a moment.";
    static final String NOT_REGISTERED = "This account isn't registered with the DropTracker yet. Submit something first, then try again.";
    static final String TOO_MANY = "That's a lot of saves - wait a minute and try again.";

    /** Turns a response into a {@link Result}. Package-private for the tests. */
    static Result interpret(Gson gson, int code, String body) {
        if (code == 200) {
            try {
                DeathMessages parsed = gson.fromJson(body, DeathMessages.class);
                return parsed != null ? Result.ok(parsed) : Result.failed(UNREACHABLE);
            } catch (JsonSyntaxException e) {
                return Result.failed(UNREACHABLE);
            }
        }
        return Result.failed(errorText(gson, code, body));
    }

    /** The sentence to show for a refused call. */
    static String errorText(Gson gson, int code, String body) {
        if (code == 404) {
            return NOT_REGISTERED;
        }
        if (code == 429) {
            return TOO_MANY;
        }
        if (code == 422 || code == 400 || code == 409) {
            // The server's refusal is written for the player; show it as is.
            try {
                JsonObject error = gson.fromJson(body, JsonObject.class);
                if (error != null && error.has("error") && error.get("error").isJsonPrimitive()) {
                    return error.get("error").getAsString();
                }
            } catch (JsonSyntaxException | IllegalStateException e) {
                // fall through to the generic message
            }
        }
        return UNREACHABLE;
    }
}

package io.droptracker.api;

import com.google.gson.*;
import com.google.gson.annotations.SerializedName;

import io.droptracker.*;
import io.droptracker.models.api.*;
import io.droptracker.models.StateSnapshot;
import io.droptracker.util.DebugLogger;
import lombok.extern.slf4j.Slf4j;
import okhttp3.*;
import net.runelite.api.Client;
import org.jetbrains.annotations.NotNull;

import javax.annotation.Nullable;

import javax.inject.*;
import javax.swing.SwingUtilities;
import java.io.IOException;
import java.util.*;
import java.util.concurrent.*;
import java.util.function.*;

@Slf4j
@Singleton
public class DropTrackerApi {
    private static final int GROUP_CONFIG_REFRESH_INTERVAL_SECONDS = 120;
    private static final int GROUP_CONFIG_RETRY_INTERVAL_SECONDS = 60;
    /** How long an aggregate /panel_data snapshot stays fresh for top-list reads. */
    private static final int PANEL_DATA_TTL_SECONDS = 60;
    /** After an aggregate fetch fails, skip further attempts for this long. */
    private static final int PANEL_DATA_FAILURE_BACKOFF_SECONDS = 300;
    /** Maximum number of uuids sent in one batch POST /check request. */
    private static final int CHECK_BATCH_LIMIT = 100;
    /**
     * Read timeout for long-poll GET /notifications calls. Must exceed the
     * largest {@code wait} the service requests (the server holds the request
     * open that long on an empty inbox) plus headroom for the response itself.
     */
    private static final int LONG_POLL_READ_TIMEOUT_SECONDS = 40;

    /**
     * How this build draws event team badges, sent on /event_state. 2 means
     * the chatbox is decorated as it is drawn and message nodes are left
     * alone. Builds that send nothing rename nodes and must not be given a
     * roster.
     */
    static final int TEAM_BADGE_RENDERER = 2;

    private final DropTrackerConfig config;
    private final Gson gson;
    private final OkHttpClient httpClient;

    /**
     * Client used for lightweight panel-data GETs (searches, top lists, configs, news).
     * Derived from the injected RuneLite client but with tight connect/read timeouts so a
     * slow or unresponsive API never hangs panel loads for minutes. Submission uploads
     * keep using the injected {@link #httpClient}, since those payloads can be large.
     */
    private OkHttpClient panelHttpClient;

    /**
     * Client for long-poll /notifications calls only: same pool as the
     * injected client but with a read timeout that outlasts the server-held
     * wait window, where {@link #panelHttpClient}'s tight 10s timeout would
     * abort every hold.
     */
    private OkHttpClient longPollHttpClient;
    private final DropTrackerPlugin plugin;

    private final Client client;

    public List<GroupConfig> groupConfigs = new ArrayList<>();

    private int lastGroupConfigUpdateUnix = 0;
    private int lastGroupConfigLoadAttemptUnix = 0;
    private boolean isLoadingGroupConfigs = false;
    private long lastGroupConfigAccountHash = -1L;
    private String lastGroupConfigPlayerName = null;

    public int lastCommunicationTime = (int) (System.currentTimeMillis() / 1000);

    /**
     * Latest snapshot from the aggregate GET /panel_data endpoint. Guarded by
     * {@link #panelDataLock}; may be null when the endpoint has never succeeded
     * (e.g. custom API endpoints that predate the route).
     */
    private final Object panelDataLock = new Object();
    private PanelData cachedPanelData;
    private long cachedPanelDataAtMs = 0;
    /** Last time an aggregate fetch failed; used to briefly stop retrying old endpoints. */
    private long lastPanelDataFailureAtMs = 0;

    /** Optional callback invoked after group configs are successfully loaded */
    private Runnable onGroupConfigsLoadedCallback;



    @Inject
    public DropTrackerApi(DropTrackerConfig config, Gson gson, OkHttpClient httpClient, DropTrackerPlugin plugin, Client client) {
            this.config = config;
            this.gson = gson;
            this.httpClient = httpClient;
            this.plugin = plugin;
            this.client = client;
            this.panelHttpClient = httpClient.newBuilder()
                .connectTimeout(5, TimeUnit.SECONDS)
                .readTimeout(10, TimeUnit.SECONDS)
                .build();
            this.longPollHttpClient = httpClient.newBuilder()
                .connectTimeout(5, TimeUnit.SECONDS)
                .readTimeout(LONG_POLL_READ_TIMEOUT_SECONDS, TimeUnit.SECONDS)
                .build();
    }

    private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");

    /** Records a completed round-trip with the API. */
    private void touch() {
        lastCommunicationTime = (int) (System.currentTimeMillis() / 1000);
    }

    /** {@code getApiUrl() + path} as a URL, or null when that doesn't parse. */
    @Nullable
    private HttpUrl apiUrl(String path) {
        return HttpUrl.parse(getApiUrl() + path);
    }

    private static Request getRequest(HttpUrl url) {
        return new Request.Builder().url(url).build();
    }

    private Request postJson(HttpUrl url, Object body) {
        return new Request.Builder().url(url).post(RequestBody.create(JSON, gson.toJson(body))).build();
    }

    /** An API URL carrying the player_name/acc_hash identity params, or null. */
    @Nullable
    private HttpUrl.Builder playerUrl(String path, String playerName, long accountHash) {
        HttpUrl base = apiUrl(path);
        return base == null ? null : base.newBuilder()
            .addQueryParameter("player_name", playerName)
            .addQueryParameter("acc_hash", String.valueOf(accountHash));
    }

    private boolean canIdentify(String playerName, long accountHash) {
        return config.useApi() && playerName != null && !playerName.isEmpty() && accountHash != -1L;
    }

    /**
     * Set a callback to be invoked when group configs are successfully loaded.
     */
    public void setOnGroupConfigsLoadedCallback(Runnable callback) {
        this.onGroupConfigsLoadedCallback = callback;
    }

    /* ===================== Aggregate panel data (GET /panel_data) ===================== */

    /**
     * Response shape of the aggregate GET /panel_data endpoint, which bundles
     * everything the side panel needs to boot in a single round-trip.
     */
    public static class PanelData {
        public List<GroupConfig> configs;
        @SerializedName("player_found")
        public Boolean playerFound;
        @SerializedName("top_groups")
        public PanelCard.Top topGroups;
        @SerializedName("top_players")
        public PanelCard.Top topPlayers;
        public String welcome;
        public String news;
        public VersionInfo version;
    }

    /**
     * Fetches the aggregate panel data snapshot, caching it on success. Both query
     * params are optional; without them the response simply omits player configs.
     * Returns null on any failure (network error, non-200 from an older custom API
     * endpoint that doesn't have the route yet, malformed body) so callers can fall
     * back to the individual endpoints. Performs blocking I/O - never call on the EDT.
     */
    private PanelData fetchPanelData(String playerName, Long accountHash) {
        if (!config.useApi()) {
            return null;
        }
        // Back off briefly after a failure so custom endpoints that predate the
        // route aren't hit with a doomed extra request on every panel load.
        synchronized (panelDataLock) {
            if (lastPanelDataFailureAtMs > 0
                && (System.currentTimeMillis() - lastPanelDataFailureAtMs) < PANEL_DATA_FAILURE_BACKOFF_SECONDS * 1000L) {
                return null;
            }
        }
        HttpUrl base = apiUrl("/panel_data");
        if (base == null) {
            return null;
        }
        HttpUrl.Builder urlBuilder = base.newBuilder();
        if (playerName != null && !playerName.isEmpty()) {
            urlBuilder.addQueryParameter("player_name", playerName);
        }
        if (accountHash != null && accountHash != -1L) {
            urlBuilder.addQueryParameter("acc_hash", String.valueOf(accountHash));
        }

        try (Response response = panelHttpClient.newCall(getRequest(urlBuilder.build())).execute()) {
            touch();
            if (!response.isSuccessful() || response.body() == null) {
                return recordPanelDataFailure("HTTP " + response.code());
            }
            PanelData data = gson.fromJson(response.body().string(), PanelData.class);
            if (data == null) {
                return recordPanelDataFailure("empty body");
            }
            synchronized (panelDataLock) {
                cachedPanelData = data;
                cachedPanelDataAtMs = System.currentTimeMillis();
                lastPanelDataFailureAtMs = 0;
            }
            return data;
        } catch (IOException | JsonSyntaxException e) {
            return recordPanelDataFailure(e.getMessage());
        }
    }

    private PanelData recordPanelDataFailure(String reason) {
        synchronized (panelDataLock) {
            lastPanelDataFailureAtMs = System.currentTimeMillis();
        }
        log.debug("/panel_data fetch failed; falling back to individual endpoints: {}", reason);
        return null;
    }

    /** Cache-only read of the latest aggregate snapshot; safe to call from the EDT. */
    private PanelData getCachedPanelData() {
        synchronized (panelDataLock) {
            return cachedPanelData;
        }
    }

    /**
     * Returns a fresh aggregate snapshot, fetching one if the cache is stale. The
     * fetch happens under the lock so concurrent panel loaders share one request.
     * Returns null when the aggregate endpoint is unavailable. Blocking - off-EDT only.
     */
    private PanelData getPanelDataFreshOrFetch() {
        synchronized (panelDataLock) {
            if (cachedPanelData != null
                && (System.currentTimeMillis() - cachedPanelDataAtMs) < PANEL_DATA_TTL_SECONDS * 1000L) {
                return cachedPanelData;
            }
            return fetchPanelData(null, null);
        }
    }



    /* Group Configs */
    @SuppressWarnings({ "null" })
    public synchronized void loadGroupConfigs(String playerName) throws IOException {
        if (!config.useApi()) {
            return;
        }

        long accountHash = client.getAccountHash();
        if (accountHash == -1 || playerName == null || playerName.isEmpty()) {
            return;
        }

        int nowUnix = (int) (System.currentTimeMillis() / 1000);
        boolean accountOrPlayerChanged = accountHash != lastGroupConfigAccountHash
            || !playerName.equals(lastGroupConfigPlayerName);

        // If we changed account/player, allow an immediate refresh to avoid stale data.
        if (accountOrPlayerChanged) {
            groupConfigs = new ArrayList<>();
            lastGroupConfigUpdateUnix = 0;
        } else {
            int minInterval = lastGroupConfigUpdateUnix > 0
                ? GROUP_CONFIG_REFRESH_INTERVAL_SECONDS
                : GROUP_CONFIG_RETRY_INTERVAL_SECONDS;
            if ((nowUnix - lastGroupConfigLoadAttemptUnix) < minInterval) {
                return;
            }
        }

        // Prevent concurrent loading
        if (isLoadingGroupConfigs) {
            return;
        }

        lastGroupConfigLoadAttemptUnix = nowUnix;
        lastGroupConfigAccountHash = accountHash;
        lastGroupConfigPlayerName = playerName;
        isLoadingGroupConfigs = true;

        CompletableFuture.runAsync(() -> {
            String responseData = null;
            try {
                // Prefer the aggregate /panel_data endpoint: one round-trip refreshes the
                // configs plus the top lists, welcome/news text and version info.
                PanelData panelData = fetchPanelData(playerName, accountHash);
                if (panelData != null) {
                    if (panelData.configs != null && !Boolean.FALSE.equals(panelData.playerFound)) {
                        groupConfigs = new ArrayList<>(panelData.configs);
                        groupConfigsLoaded();
                    } else {
                        // Unknown player: same as the old /load_config 404 - leave
                        // lastGroupConfigUpdateUnix unset so the retry schedule applies.
                        log.debug("/panel_data returned no configs for {}; will retry", playerName);
                    }
                    return;
                }

                // Fallback: the legacy per-purpose /load_config endpoint.
                HttpUrl.Builder url = playerUrl("/load_config", playerName, accountHash);
                if (url == null) {
                    return;
                }

                try (Response response = panelHttpClient.newCall(getRequest(url.build())).execute()) {
                    touch();

                    if (!response.isSuccessful()) {
                        throw new IOException("API request failed with status: " + response.code());
                    }

                    if (response.body() == null) {
                        throw new IOException("Empty response body");
                    }

                    responseData = response.body().string();

                    GroupConfig[] configArray = gson.fromJson(responseData, GroupConfig[].class);
                    List<GroupConfig> parsedConfigs = new ArrayList<>(Arrays.asList(configArray));

                    if (parsedConfigs != null) {
                        groupConfigs = parsedConfigs;
                    }
                    groupConfigsLoaded();
                } catch (Exception e) {
                    log.debug("Couldn't load group config in side panel: " + e);
                }
            } finally {
                isLoadingGroupConfigs = false;
            }
        }).exceptionally(ex -> {
            log.debug(ex.getMessage());
            isLoadingGroupConfigs = false;
            return null;
        });
    }

    /** Stamps a successful config load and notifies the listener, if any. */
    private void groupConfigsLoaded() {
        lastGroupConfigUpdateUnix = (int) (System.currentTimeMillis() / 1000);
        if (onGroupConfigsLoadedCallback != null) {
            try {
                onGroupConfigsLoadedCallback.run();
            } catch (Exception callbackEx) {
                log.debug("Error in group config loaded callback: " + callbackEx.getMessage());
            }
        }
    }

    /**
     * Returns the most recently loaded group configs from memory. This never performs
     * any network I/O, so it is safe to call from the Swing EDT. Callers that want
     * fresher data should invoke {@link #refreshGroupConfigsAsync()} first.
     */
    public List<GroupConfig> getGroupConfigs() {
        if (!config.useApi()) {
            return null;
        }
        return groupConfigs;
    }

    /**
     * Schedules a rate-limited asynchronous refresh of the group configs. The actual
     * network request runs off the calling thread, so this is safe to call from the EDT.
     */
    public void refreshGroupConfigsAsync() {
        if (!config.useApi()) {
            return;
        }
        try {
            loadGroupConfigs(plugin.getLocalPlayerName());
        } catch (IOException e) {
            log.debug("Couldn't refresh group configs " + e);
        }
    }

    /* Submissions */
    public String generateGuidForSubmission() {
        long timestamp = System.currentTimeMillis() / 1000L;
        long accountHash = client != null ? client.getAccountHash() : -1L;
        long randomPart = ThreadLocalRandom.current().nextLong(Long.MAX_VALUE);
        return timestamp + "-" + accountHash + "-" + randomPart;
    }



    /**
     * Blocking GET + JSON parse via {@link #panelHttpClient}. Records the
     * communication time on a completed round-trip and throws IOException on an
     * unsuccessful status, empty body, or malformed JSON. Callers that want a
     * silent fallback catch IOException and return null. Performs blocking I/O -
     * never call on the EDT.
     */
    private <T> T getJson(HttpUrl url, Class<T> type) throws IOException {
        try (Response response = panelHttpClient.newCall(getRequest(url)).execute()) {
            touch();
            if (!response.isSuccessful()) {
                throw new IOException("API request to " + url + " failed with status: " + response.code());
            }
            ResponseBody body = response.body();
            if (body == null) {
                throw new IOException("Empty response body from " + url);
            }
            try {
                return gson.fromJson(body.string(), type);
            } catch (JsonSyntaxException e) {
                throw new IOException("Malformed response from " + url, e);
            }
        }
    }

    /**
     * Fetches the server-controlled manifest. Blocking; call off the client thread.
     *
     * <p>Bypasses the HTTP cache with {@link CacheControl#FORCE_NETWORK}. This is
     * not optional: {@code panelHttpClient} is derived from RuneLite's injected
     * OkHttpClient, which has a persistent <em>disk</em> cache shared by the whole
     * client, and the manifest is served with a {@code max-age}. Without this a
     * client would keep re-reading a cached manifest across restarts for as long
     * as the entry lived — so a server-side fix would appear not to work, which
     * defeats the entire reason the manifest is server-side.
     *
     * @return the manifest, or null if unavailable — callers fall back to their
     *         built-in defaults rather than failing. A manifest that parsed but
     *         had an unreadable section is still returned, minus that section.
     */
    public Manifest getManifest() {
        if (!config.useApi()) {
            return null;
        }
        HttpUrl url = apiUrl("/manifest");
        if (url == null) {
            return null;
        }
        Request request = new Request.Builder()
                .url(url)
                .cacheControl(CacheControl.FORCE_NETWORK)
                .build();
        try (Response response = panelHttpClient.newCall(request).execute()) {
            touch();
            if (!response.isSuccessful()) {
                log.debug("Manifest request failed with status {}", response.code());
                return null;
            }
            ResponseBody body = response.body();
            if (body == null) {
                return null;
            }
            // Manifest.fromJson, not gson.fromJson(.., Manifest.class): the
            // reflective adapter would abandon the whole document over one
            // section whose shape changed, taking every other section with it.
            return Manifest.fromJson(gson, body.string());
        } catch (IOException | JsonSyntaxException e) {
            log.debug("Couldn't fetch the manifest: {}", e.toString());
            return null;
        }
    }

    /**
     * Posts a full account state snapshot to {@code /state/sync}. Blocking; call
     * off the client thread.
     *
     * <p>Sent as plain JSON rather than through the webhook envelope the rest of
     * the plugin uses: a snapshot is maps of thousands of ids, which does not
     * fit the embed-fields shape and would be lossy to squeeze into it.
     *
     * <p>The endpoint is idempotent, so a caller that cannot tell whether a
     * request landed is free to send it again.
     *
     * @return true when the server accepted the snapshot.
     */
    public boolean postStateSnapshot(StateSnapshot snapshot) {
        if (!config.useApi() || snapshot == null) {
            return false;
        }
        HttpUrl url = apiUrl("/state/sync");
        if (url == null) {
            return false;
        }
        try (Response response = panelHttpClient.newCall(postJson(url, snapshot)).execute()) {
            touch();
            if (!response.isSuccessful()) {
                log.debug("State sync rejected with status {}", response.code());
                return false;
            }
            return true;
        } catch (IOException e) {
            log.debug("State sync failed: {}", e.toString());
            return false;
        }
    }

    /**
     * Uploads the player's character model as binary glTF. Blocking; call off
     * the client thread.
     *
     * <p>Keyed by an outfit fingerprint so the server can skip work it has
     * already done: the same character in the same gear renders identically, so
     * one upload per distinct outfit is enough.
     *
     * @return true when the server accepted (or already had) the model.
     */
    public boolean uploadPlayerModel(String fingerprint, byte[] model, @Nullable byte[] petModel) {
        return uploadPlayerModel(fingerprint, model, petModel, false);
    }

    /**
     * @param pin when true, the server records this outfit as the one the
     *            player chose for their profile, so later automatic uploads
     *            of other outfits do not replace it.
     */
    public boolean uploadPlayerModel(String fingerprint, byte[] model, @Nullable byte[] petModel, boolean pin) {
        if (!config.useApi() || model == null || model.length == 0) {
            return false;
        }
        HttpUrl url = apiUrl("/player/model");
        if (url == null) {
            return false;
        }

        // The mesh; the server writes the glTF from it (GlbExporter).
        MediaType mesh = MediaType.parse("application/octet-stream");
        MultipartBody.Builder body = new MultipartBody.Builder()
                .setType(MultipartBody.FORM)
                .addFormDataPart("acc_hash", String.valueOf(client.getAccountHash()))
                .addFormDataPart("fingerprint", fingerprint)
                .addFormDataPart("mesh", "model.dtm", RequestBody.create(mesh, model));
        if (pin) {
            body.addFormDataPart("pin", "1");
        }
        if (petModel != null && petModel.length > 0) {
            body.addFormDataPart("pet_mesh", "pet.dtm", RequestBody.create(mesh, petModel));
        }

        Request request = new Request.Builder().url(url).post(body.build()).build();
        try (Response response = httpClient.newCall(request).execute()) {
            touch();
            if (!response.isSuccessful()) {
                log.debug("Model upload rejected with status {}", response.code());
                return false;
            }
            return true;
        } catch (IOException e) {
            log.debug("Model upload failed: {}", e.toString());
            return false;
        }
    }

    /**
     * Asks whether the server already holds the model for an outfit. Blocking;
     * call off the client thread.
     *
     * <p>The cheap half of {@link #uploadPlayerModel}: a couple of hundred
     * bytes against a model measured in tens of kilobytes, and it spares the
     * client the export as well as the upload. Answering it is also how the
     * server learns which outfit the player is currently wearing, so a switch
     * back into gear it already holds still reaches the profile.
     *
     * @return what the server holds, or null when it could not be asked — an
     *         unreachable or older server must leave the caller sending the
     *         model, which is what it did before this endpoint existed.
     */
    @Nullable
    public ModelStatus checkPlayerModel(String fingerprint) {
        if (!config.useApi() || fingerprint == null || fingerprint.isEmpty()) {
            return null;
        }
        HttpUrl url = apiUrl("/player/model/check");
        if (url == null) {
            return null;
        }

        Map<String, String> body = new HashMap<>();
        body.put("acc_hash", String.valueOf(client.getAccountHash()));
        body.put("fingerprint", fingerprint);

        try (Response response = httpClient.newCall(postJson(url, body)).execute()) {
            touch();
            // 202 is the server saying it does not know this account — a real
            // answer, and the one case where sending the model is pointless.
            if (!response.isSuccessful() && response.code() != 202) {
                return null;
            }
            ResponseBody responseBody = response.body();
            return responseBody == null
                    ? null : gson.fromJson(responseBody.string(), ModelStatus.class);
        } catch (Exception e) {
            log.debug("Model check failed: {}", e.toString());
            return null;
        }
    }

    public PanelCard.Top getTopGroups() {
