    /**
     * A top list from the aggregate snapshot (one /panel_data request serves
     * both), else from its own endpoint. {@code fromPanel} returns null when
     * the snapshot lacks the list.
     */
    private PanelCard.Top topList(Function<PanelData, PanelCard.Top> fromPanel, String path) {
        if (!config.useApi()) {
            return null;
        }
        PanelData panelData = getPanelDataFreshOrFetch();
        PanelCard.Top cached = panelData != null ? fromPanel.apply(panelData) : null;
        if (cached != null && cached.rows() != null) {
            return cached;
        }
        try {
            return getJson(apiUrl(path), PanelCard.Top.class);
        } catch (IOException e) {
            log.debug("Couldn't get " + path + ": " + e);
            return null;
        }
    }

    /**
     * The server-composed detail card for a group ({@code /group_search}) or a
     * player ({@code /player_search}); null when nothing matched.
     */
    @Nullable
    public PanelCard searchCard(String path, String name) throws IOException {
        if (!config.useApi()) {
            return null;
        }
        HttpUrl baseUrl = apiUrl(path);
        if (baseUrl == null) {
            throw new IllegalArgumentException("Invalid URL");
        }
        PanelCard.Search found = getJson(baseUrl.newBuilder().addQueryParameter("name", name).build(),
            PanelCard.Search.class);
        return found != null ? found.card : null;
    }

    public String getApiUrl() {
        String custom = config.customApiEndpoint();
        if (custom == null || custom.trim().isEmpty()) {
            return config.useApi() ? DropTrackerUrls.DEFAULT_API : "";
        }
        String normalized = custom.trim();
        if (!normalized.startsWith("http")) {
            normalized = "http://" + normalized;
        }
        // The website hosts never serve the plugin API; a custom endpoint pointing
        // at them (a stale value in the hidden customApiEndpoint config) makes every
        // API call chase a redirect into the site's 404 page. Fall back to the real
        // API host instead of failing confusingly.
        HttpUrl parsed = HttpUrl.parse(normalized);
        if (parsed != null) {
            String host = parsed.host().toLowerCase();
            if (host.equals("droptracker.io") || host.equals("www.droptracker.io")) {
                log.warn("customApiEndpoint points at the website ({}); using https://api.droptracker.io instead", custom);
                return DropTrackerUrls.DEFAULT_API;
            }
        }
        return normalized;
    }

    /** Version metadata returned by GET /plugin_version. */
    public static class VersionInfo {
        @SerializedName("latest_version")
        public String latestVersion;
        @SerializedName("minimum_version")
        public String minimumVersion;
        public String message;
    }

    /**
     * Fetches the latest/minimum plugin version from the API. Gated on
     * {@link DropTrackerConfig#useApi()} like every other call to our hosts: the
     * endpoint needs no auth, but a user who has not enabled the API integration
     * must not have their client contact us at all, so the check is skipped rather
     * than falling back to the default host. Returns null on any failure — the
     * version check is best-effort and must never break startup.
     */
    public VersionInfo fetchVersionInfo() {
        // Prefer version info already delivered by the aggregate /panel_data snapshot.
        PanelData panelData = getCachedPanelData();
        if (panelData != null && panelData.version != null && panelData.version.latestVersion != null) {
            return panelData.version;
        }
        // Empty means "API off and no user-supplied endpoint" — make no request.
        String apiUrl = getApiUrl();
        if (apiUrl == null || apiUrl.isEmpty()) {
            return null;
        }
        HttpUrl url = HttpUrl.parse(apiUrl + "/plugin_version");
        if (url == null) {
            return null;
        }
        try (Response response = panelHttpClient.newCall(getRequest(url)).execute()) {
            if (!response.isSuccessful() || response.body() == null) {
                return null;
            }
            return gson.fromJson(response.body().string(), VersionInfo.class);
        } catch (Exception e) {
            log.debug("Version check failed: {}", e.getMessage());
            return null;
        }
    }


    /** Whether the API reports this one submission as processed. */
    public boolean checkSubmissionProcessed(String uuid) throws IOException {
        return uuid != null && Boolean.TRUE.equals(
            checkSubmissionsProcessed(Collections.singletonList(uuid)).get(uuid));
    }

    /** One entry in the batch POST /check response. */
    private static class CheckResultEntry {
        String uuid;
        Boolean processed;
        String status;
    }

    /** Response shape of the batch POST /check form. */
    private static class BatchCheckResponse {
        List<CheckResultEntry> results;
    }

    /**
     * Checks up to
     * {@value #CHECK_BATCH_LIMIT} submission uuids in a single POST /check request
     * ({"uuids": [...]}). Returns a map of uuid to processed-state for the uuids the
     * API reported on. "pending" is a normal long-lived state, not an error.
     *
     * @throws IOException when the request fails or the body is unparseable.
     */
    public Map<String, Boolean> checkSubmissionsProcessed(List<String> uuids) throws IOException {
        if (!config.useApi() || uuids == null || uuids.isEmpty()) {
            return Collections.emptyMap();
        }

        List<String> capped = uuids.size() > CHECK_BATCH_LIMIT
            ? new ArrayList<>(uuids.subList(0, CHECK_BATCH_LIMIT))
            : uuids;

        HttpUrl url = apiUrl("/check");
        if (url == null) {
            throw new IllegalArgumentException("Invalid URL");
        }

        try (Response response = panelHttpClient.newCall(postJson(url, Collections.singletonMap("uuids", capped))).execute()) {
            touch();

            if (!response.isSuccessful()) {
                throw new IOException("Batch /check failed with status: " + response.code());
            }
            ResponseBody responseBody = response.body();
            if (responseBody == null) {
                throw new IOException("Empty batch /check response body");
            }

            BatchCheckResponse parsed;
            try {
                parsed = gson.fromJson(responseBody.string(), BatchCheckResponse.class);
            } catch (JsonSyntaxException e) {
                throw new IOException("Malformed batch /check response", e);
            }
            if (parsed == null || parsed.results == null) {
                throw new IOException("Batch /check response missing results");
            }

            Map<String, Boolean> results = new HashMap<>();
            for (CheckResultEntry entry : parsed.results) {
                if (entry == null || entry.uuid == null) {
                    continue;
                }
                boolean processed = Boolean.TRUE.equals(entry.processed)
                    || "processed".equalsIgnoreCase(entry.status);
                results.put(entry.uuid, processed);
            }
            return results;
        }
    }

    private static final String WELCOME_FALLBACK = "Welcome to the DropTracker!";
    private static final String NEWS_FALLBACK =
        "News is temporarily unavailable. Use the refresh button to try again.";

    /**
     * Returns true when a response body looks like an HTML document (e.g. a
     * Cloudflare error/challenge page or a framework 404 page) rather than the
     * plain-text content these endpoints serve. Such bodies must never be
     * rendered in the side panel.
     */
    private static boolean looksLikeHtml(String body) {
        if (body == null) {
            return true;
        }
        String trimmed = body.trim();
        return trimmed.isEmpty() || trimmed.startsWith("<");
    }

    /**
     * Asynchronously fetches the latest welcome string to avoid blocking the EDT.
     * @param callback Function to call with the result when ready
     */
    public void getLatestWelcomeString(Consumer<String> callback) {
        fetchPanelText(p -> p.welcome, "/latest_welcome", "welcome.txt", WELCOME_FALLBACK, callback);
    }

    /**
     * Asynchronously fetches the latest update string to avoid blocking the EDT.
     * @param callback Function to call with the result when ready
     */
    public void getLatestUpdateString(Consumer<String> callback) {
        fetchPanelText(p -> p.news, "/latest_news", "news.txt", NEWS_FALLBACK, callback);
    }

    /**
     * Welcome/news text: from the aggregate snapshot when it has some
     * (cache-only, EDT-safe; the periodic /panel_data refresh keeps it
     * current), else from the API endpoint, or the GitHub Pages file when the
     * API is off. The callback always runs on the EDT, with {@code fallback}
     * on any failure.
     */
    private void fetchPanelText(Function<PanelData, String> fromPanel, String apiPath, String contentFile,
                                String fallback, Consumer<String> callback) {
        HttpUrl endpoint;
        if (config.useApi()) {
            PanelData panelData = getCachedPanelData();
            String cached = panelData != null ? fromPanel.apply(panelData) : null;
            if (cached != null && !cached.isEmpty()) {
                SwingUtilities.invokeLater(() -> callback.accept(cached));
                return;
            }
            endpoint = apiUrl(apiPath);
        } else {
            endpoint = DropTrackerUrls.content(contentFile);
        }
        if (endpoint == null) {
            SwingUtilities.invokeLater(() -> callback.accept(fallback));
            return;
        }

        panelHttpClient.newCall(getRequest(endpoint)).enqueue(new Callback() {
            @Override
            public void onFailure(@NotNull Call call, @NotNull IOException e) {
                SwingUtilities.invokeLater(() -> callback.accept(fallback));
            }

            @Override
            public void onResponse(@NotNull Call call, @NotNull Response response) throws IOException {
                try (Response autoCloseResponse = response; ResponseBody responseBody = response.body()) {
                    // Never render the response body on failure: error pages from
                    // Cloudflare or the web server are full HTML documents, and this
                    // used to paste them into the News panel verbatim.
                    String result = fallback;
                    if (response.isSuccessful() && responseBody != null) {
                        String body = responseBody.string();
                        if (!looksLikeHtml(body)) {
                            result = body;
                        }
                    }
                    final String finalResult = result;
                    SwingUtilities.invokeLater(() -> callback.accept(finalResult));
                }
            }
        });
    }

