    /**
     * Clans opted into clan chat relaying, as {@code hash -> "b"|"t"|"bt"}
     * (server: utils/clan_relay_gate.published_clan_list). Webhook-only
     * clients use it in place of their group configs, which need the API.
     * <p>
     * Deliberately NOT gated on {@link DropTrackerConfig#useApi()}: it is a
     * static file on GitHub Pages, like the server-loot npc list. Returns null
     * on any failure so the caller keeps whatever it had.
     */
    public Map<String, String> fetchClanChatClans() {
        try (Response response = panelHttpClient.newCall(getRequest(DropTrackerUrls.content("clan_chat_clans.txt"))).execute()) {
            if (!response.isSuccessful() || response.body() == null) {
                return null;
            }
            Map<String, String> clans = new HashMap<>();
            for (String line : response.body().string().split("\\n")) {
                int colon = line.indexOf(':');
                if (colon > 0) {
                    clans.put(line.substring(0, colon).trim(), line.substring(colon + 1).trim());
                }
            }
            return clans;
        } catch (Exception e) {
            DebugLogger.log("[DropTrackerApi][clan-chat-clans] failed to load; reason=" + e.getMessage());
            return null;
        }
    }

    private ArrayList<Integer> fetchItemIdList(HttpUrl url, String tag) {
        /* Only use github pages URL, as our API is sometimes not responding fast enough currently... */
        try (Response response = panelHttpClient.newCall(getRequest(url)).execute()) {
            touch();
            if (!response.isSuccessful()) {
                throw new IOException("API request failed with status: " + response.code());
            }
            ResponseBody responseBody = response.body();
            if (responseBody == null) {
                throw new IOException("Empty response body");
            }
            ArrayList<Integer> itemIdList = new ArrayList<>();
            for (String itemIdString : responseBody.string().split(",")) {
                try {
                    String idStripped = itemIdString.replace("\"", "").replace("[", "").replace("]", "");
                    itemIdList.add(Integer.parseInt(idStripped.trim()));
                } catch (NumberFormatException e) {
                    // Handle cases where a part of the string isn't a valid integer
                    DebugLogger.log("[DropTrackerApi][" + tag + "] skipped invalid itemId token=" + itemIdString);
                }
            }
            DebugLogger.log("[DropTrackerApi][" + tag + "] loaded itemId count=" + itemIdList.size());
            return itemIdList;
        } catch (IOException e) {
            DebugLogger.log("[DropTrackerApi][" + tag + "] failed to load from GitHub; reason=" + e.getMessage());
            return null;
        }
    }

    /* ============== Event notifications + HUD state (P2) ============== */

    /** Response of GET /notifications. */
    public static class NotificationsResponse {
        public List<io.droptracker.models.api.EventNotification> notifications;
        @SerializedName("active_event")
        public Boolean activeEvent;
        /**
         * Present (true) only when the server understood a {@code wait}
         * request; its absence marks a legacy server that ignored the param,
         * so the caller must fall back to fixed-interval polling.
         */
        @SerializedName("long_poll")
        public Boolean longPoll;
    }

    /**
     * Builds the GET /notifications call that drains the player's
     * event-notification inbox. {@code waitSeconds > 0} long-polls: the
     * server holds an empty-inbox request open up to that many seconds (it
     * clamps to its own cap) and flags the response with long_poll=true.
     * Returns null when the API is disabled or the identity/URL is unusable.
     * Long-poll calls must go through {@link Call#enqueue} — never block a
     * shared executor thread waiting out the hold.
     *
     * ``clanName`` (optional) is the chat-bridge presence heartbeat: polling
     * with it tells the server this plugin is online in that clan, which is
     * what Discord→game fan-out delivers against.
     */
    @Nullable
    public Call newNotificationsCall(String playerName, long accountHash, int waitSeconds, String clanName,
                                     @Nullable String catchUpHidden) {
        if (!canIdentify(playerName, accountHash)) {
            return null;
        }
        HttpUrl.Builder url = playerUrl("/notifications", playerName, accountHash);
        if (url == null) {
            return null;
        }
        if (waitSeconds > 0) {
            url.addQueryParameter("wait", String.valueOf(waitSeconds));
        }
        if (clanName != null && !clanName.isEmpty()) {
            url.addQueryParameter("clan", clanName);
        }
        if (catchUpHidden != null) {
            // The session's first batch: a stale backlog comes back as one
            // digest per event, minus what the player hid or muted.
            url.addQueryParameter("catchup", "1");
            url.addQueryParameter("hidden", catchUpHidden);
            url.addQueryParameter("progress", config.eventTaskProgressNotifications() ? "1" : "0");
        }
        OkHttpClient callClient = waitSeconds > 0 ? longPollHttpClient : panelHttpClient;
        return callClient.newCall(getRequest(url.build()));
    }

    /**
     * Parses a successful /notifications response body. Returns null on an
     * empty or malformed body. Closing the response stays with the caller.
     */
    @Nullable
    public NotificationsResponse parseNotificationsResponse(Response response) {
        touch();
        try {
            ResponseBody body = response.body();
            if (!response.isSuccessful() || body == null) {
                return null;
            }
            return gson.fromJson(body.string(), NotificationsResponse.class);
        } catch (IOException | JsonSyntaxException e) {
            log.debug("/notifications parse failed: {}", e.getMessage());
            return null;
        }
    }

    /**
     * Fetches the HUD / Events-tab state for every active event the player
     * is in. Returns null on any failure. Blocking — off-EDT only.
     *
     * Sends {@code badges}: this build badges chat lines as they are drawn and
     * never renames a MessageNode. Builds before it (6.0.3-6.0.8) renamed
     * nodes, which hid friends' PMs, so the server can withhold
     * roster_version, and with it every badge, from any client that does not
     * send this.
     */
    @Nullable
    public EventState fetchEventState(String playerName, long accountHash) {
        return fetchForPlayer("/event_state", playerName, accountHash, true, EventState.class);
    }

    /**
     * Team membership for the clan-chat badges. Roster-gated server-side: only
     * events this account is on a team of come back, so there is nothing to
     * filter here.
     *
     * Called only when /event_state's roster_version changes, never on a timer
     * — this carries a whole event's membership, unlike the state poll.
     */
    public EventRoster fetchEventRoster(String playerName, long accountHash) {
        return fetchForPlayer("/event_roster", playerName, accountHash, false, EventRoster.class);
    }

    @Nullable
    private <T> T fetchForPlayer(String path, String playerName, long accountHash, boolean badges, Class<T> type) {
        if (!canIdentify(playerName, accountHash)) {
            return null;
        }
        HttpUrl.Builder url = playerUrl(path, playerName, accountHash);
        if (url == null) {
            return null;
        }
        if (badges) {
            url.addQueryParameter("badges", String.valueOf(TEAM_BADGE_RENDERER));
        }
        try (Response response = panelHttpClient.newCall(getRequest(url.build())).execute()) {
            touch();
            if (!response.isSuccessful() || response.body() == null) {
                return null;
            }
            return gson.fromJson(response.body().string(), type);
        } catch (IOException | JsonSyntaxException e) {
            log.debug(path + " fetch failed: {}", e.getMessage());
            return null;
        }
    }

    /** The events this account may open in the event window (its own, then its groups'). */
    @Nullable
    public EventView.Listing fetchEventList(String playerName, long accountHash) {
        return fetchForPlayer("/plugin/events", playerName, accountHash, false, EventView.Listing.class);
    }

    /** One page of the event window, composed by the server. */
    @Nullable
    public EventView fetchEventView(int eventId, String page, String playerName, long accountHash) {
        return fetchForPlayer("/plugin/events/" + eventId + "/view?page=" + page, playerName, accountHash, false, EventView.class);
    }

    /**
     * URL of the server-rendered board image for an event (optionally one
     * team's view). The identity params ride along because the endpoint is
     * roster-gated (private events stay hidden without them).
     */
    public HttpUrl eventBoardImageUrl(int eventId, Integer teamId, String playerName, long accountHash) {
        HttpUrl.Builder builder = playerUrl("/events/" + eventId + "/board.png", playerName, accountHash);
        if (builder == null) {
            return null;
        }
        if (teamId != null) {
            builder.addQueryParameter("team_id", String.valueOf(teamId));
        }
        return builder.build();
    }

    /** True when any loaded group config reports a live event tracking this player. */
    public boolean hasActiveEvent() {
        List<GroupConfig> configs = groupConfigs;
        if (configs == null) {
            return false;
        }
        for (GroupConfig groupConfig : configs) {
            if (groupConfig != null && groupConfig.isActiveEvent()) {
                return true;
            }
        }
        return false;
    }
}

package io.droptracker.api;

import java.util.regex.Pattern;

import javax.annotation.Nullable;

import okhttp3.HttpUrl;

/**
 * Every host this plugin is capable of connecting to, as compile-time constants.
 *
 * <p>The Plugin Hub requires that all URLs a plugin talks to are either hardcoded
 * in the plugin or typed by the user, so that the set of domains can be reviewed
 * exhaustively. The API therefore hands us <em>paths</em> (for example
 * {@code "itemdb/4151.png"}), never URLs, and this class anchors them onto one of
 * the bases below. A server response can influence which file we ask for; it can
 * never influence which host we ask.
 *
 * <p>The only address not listed here is the API base itself, which is resolved by
 * {@link DropTrackerApi#getApiUrl()} — either the {@link #DEFAULT_API} constant or
 * the endpoint the user typed into the hidden {@code customApiEndpoint} setting.
 */
public final class DropTrackerUrls {

	/** Website root: panel links, and the parent of {@link #IMAGES}. */
	public static final HttpUrl WEB = HttpUrl.get("https://www.droptracker.io/");

	/** Everything the plugin renders: item/npc icons, lootboards, submission screenshots. */
	public static final HttpUrl IMAGES = HttpUrl.get("https://www.droptracker.io/img/");

	/** Static published content: the webhook list, its key, and the item-id lists. */
	public static final HttpUrl CONTENT = HttpUrl.get("https://droptracker-io.github.io/content/");

	/** RuneLite's item cache, used to resolve item names to ids. */
	public static final HttpUrl ITEM_CACHE = HttpUrl.get("https://static.runelite.net/cache/item/");

	/** Discord webhook delivery. Submissions are POSTed to {@code base + id + token}. */
	public static final HttpUrl DISCORD_WEBHOOK = HttpUrl.get("https://discord.com/api/webhooks/");

	/** Discord invite links opened in the user's browser from the group panel. */
	public static final HttpUrl DISCORD_INVITE = HttpUrl.get("https://discord.gg/");

	/** API base used unless the user has typed their own endpoint. */
	public static final String DEFAULT_API = "https://api.droptracker.io";

	/**
	 * Characters no server-supplied path may contain: {@code :} (so nothing
	 * resembling a scheme survives), {@code %} (so nothing arrives pre-encoded and
	 * gets decoded twice), {@code ?} and {@code #} (so nothing can append a query or
	 * fragment), {@code \} and control characters.
	 *
	 * <p>Everything else is allowed and percent-encoded on the way out. Real
	 * screenshot paths contain apostrophes and parentheses ({@code Kree'arra},
	 * {@code Dagannoth_Rex_(hard)}), and it is {@code addPathSegment} — which
	 * encodes {@code /} too — that makes the host unreachable from a path, not the
	 * character set.
	 */
	private static final Pattern FORBIDDEN = Pattern.compile("[\\\\%?#:\\p{Cntrl}]");

	private static final int MAX_PATH_LENGTH = 512;
	private static final int MAX_SEGMENT_LENGTH = 128;

	private static final Pattern WEBHOOK_ID = Pattern.compile("[0-9]{5,32}");
	private static final Pattern WEBHOOK_TOKEN = Pattern.compile("[A-Za-z0-9._-]{16,200}");
	private static final Pattern INVITE_CODE = Pattern.compile("[A-Za-z0-9-]{1,64}");

	private DropTrackerUrls() {
	}

	/**
	 * Anchors a server-supplied relative path onto a compile-time base, or returns
	 * null if the path is anything other than a plain relative path.
	 *
	 * <p>Rejects absolute URLs, absolute paths, {@code .} / {@code ..} traversal,
	 * empty segments, and any {@link #FORBIDDEN} character. Callers treat null the
	 * same as "no image", so a rejected path simply renders nothing.
	 */
	@Nullable
	public static HttpUrl underBase(HttpUrl base, @Nullable String relativePath) {
		if (relativePath == null) {
			return null;
		}
		String path = relativePath.trim();
		if (path.isEmpty() || path.length() > MAX_PATH_LENGTH
				|| path.startsWith("/")
				|| FORBIDDEN.matcher(path).find()) {
			return null;
		}
		HttpUrl.Builder builder = base.newBuilder();
		for (String segment : path.split("/")) {
			if (segment.isEmpty() || segment.length() > MAX_SEGMENT_LENGTH
					|| ".".equals(segment) || "..".equals(segment)) {
				return null;
			}
			builder.addPathSegment(segment);
		}
		return builder.build();
	}

	/** {@code https://www.droptracker.io/img/<relativePath>} — item icons, lootboards, screenshots. */
	@Nullable
	public static HttpUrl image(@Nullable String relativePath) {
		return underBase(IMAGES, relativePath);
	}

	/**
	 * A page on the website, for opening in the user's browser.
	 *
	 * <p>Unlike {@link #underBase} this encodes rather than rejects, because some
	 * segments are legitimately free-form (a player name may contain spaces).
	 * {@code addPathSegment} percent-encodes {@code /} as well, so no segment can
	 * add depth or escape the host.
	 */
	public static HttpUrl web(String... segments) {
		HttpUrl.Builder builder = WEB.newBuilder();
		for (String segment : segments) {
			builder.addPathSegment(segment);
		}
		return builder.build();
	}

	/** {@code https://droptracker-io.github.io/content/<fileName>}. */
	@Nullable
	public static HttpUrl content(@Nullable String fileName) {
		return underBase(CONTENT, fileName);
	}

	/** {@code https://static.runelite.net/cache/item/<fileName>}. */
	@Nullable
	public static HttpUrl itemCache(@Nullable String fileName) {
		return underBase(ITEM_CACHE, fileName);
	}

	/**
	 * {@code https://discord.com/api/webhooks/<id>/<token>}. The id and token are
	 * opaque credentials published by the backend; the host is ours to decide.
	 */
	@Nullable
	public static HttpUrl discordWebhook(@Nullable String id, @Nullable String token) {
		if (id == null || token == null
				|| !WEBHOOK_ID.matcher(id).matches()
				|| !WEBHOOK_TOKEN.matcher(token).matches()) {
			return null;
		}
		return DISCORD_WEBHOOK.newBuilder()
			.addPathSegment(id)
			.addPathSegment(token)
			.build();
	}

	/** {@code https://discord.gg/<code>} for a group's public invite. */
	@Nullable
	public static HttpUrl discordInvite(@Nullable String code) {
		if (code == null || !INVITE_CODE.matcher(code.trim()).matches()) {
			return null;
		}
		return DISCORD_INVITE.newBuilder().addPathSegment(code.trim()).build();
	}
}

package io.droptracker.api;

import javax.crypto.*;
import javax.crypto.spec.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

import javax.inject.*;
import lombok.extern.slf4j.Slf4j;

@Slf4j
@Singleton
public class FernetDecrypt {
    public static String ENCRYPTION_KEY = "";

    @Inject
    public FernetDecrypt() {
    }

    public static String decryptWebhook(String webhookHash) throws Exception {
        try {
            // First decode - get the Fernet token
            String fernetToken = new String(Base64.getUrlDecoder().decode(webhookHash), StandardCharsets.UTF_8);

            // Second decode - get the encrypted data
            byte[] token = Base64.getUrlDecoder().decode(fernetToken);

            // Decode the key
            byte[] keyBytes = Base64.getUrlDecoder().decode(ENCRYPTION_KEY);
            byte[] signingKey = Arrays.copyOfRange(keyBytes, 0, 16);
            byte[] encryptionKey = Arrays.copyOfRange(keyBytes, 16, 32);

            // Extract components according to Fernet spec:
            // Version (1 byte) + Timestamp (8 bytes) + IV (16 bytes) + Ciphertext + HMAC (32 bytes)
            if (token.length < 57) { // Minimum size: 1+8+16+0+32
                throw new IllegalArgumentException("Token too short: " + token.length);
            }

            byte version = token[0];

            // Skip timestamp (bytes 1-8) - not needed for decryption

            // Extract IV (bytes 9-24)  
            byte[] iv = Arrays.copyOfRange(token, 9, 25);

            // Get the HMAC (last 32 bytes)
            byte[] hmac = Arrays.copyOfRange(token, token.length - 32, token.length);
            byte[] message = Arrays.copyOfRange(token, 0, token.length - 32);

            // Verify HMAC
            Mac mac = Mac.getInstance("HmacSHA256");
            mac.init(new SecretKeySpec(signingKey, "HmacSHA256"));
            byte[] calculatedHmac = mac.doFinal(message);

            if (!Arrays.equals(hmac, calculatedHmac)) {
                throw new SecurityException("Invalid HMAC");
            }

            // Get ciphertext (everything between IV and HMAC)
            // Start at byte 25 (after version + timestamp + IV)
            byte[] ciphertext = Arrays.copyOfRange(token, 25, token.length - 32);
            // Decrypt
            Cipher cipher = Cipher.getInstance("AES/CBC/PKCS5Padding");
            cipher.init(Cipher.DECRYPT_MODE, 
                       new SecretKeySpec(encryptionKey, "AES"),
                       new IvParameterSpec(iv));

            byte[] decryptedBytes = cipher.doFinal(ciphertext);
            String result = new String(decryptedBytes, StandardCharsets.UTF_8);

            // Post-process the result to fix common issues
            result = postProcessDecrypted(result);

            return result;
        } catch (Exception e) {
            log.error("Decryption failed for webhook hash: {}", webhookHash.substring(0, Math.min(20, webhookHash.length())) + "...", e);
            throw e;
        }
    }

    /**
     * Strips the leading non-printable bytes that occasionally survive decryption.
     *
     * <p>This used to also synthesise {@code "https://discord.com" + path} when the
     * plaintext looked like a webhook. It no longer does: the plaintext is a
     * credential, not an address, and the host is decided by
     * {@link DropTrackerUrls#DISCORD_WEBHOOK}. See
     * {@link UrlManager#parseEndpoint(String)}.
     */
    private static String postProcessDecrypted(String decrypted) {
        if (decrypted == null || decrypted.isEmpty()) {
            return decrypted;
        }
        return decrypted.replaceAll("^[\\p{Cntrl}\\p{So}\\p{Cn}]+", "");
    }
}

package io.droptracker.api;

import java.io.IOException;
import java.lang.reflect.Type;
import java.util.*;
import java.util.concurrent.ScheduledExecutorService;
import java.util.function.Consumer;

import javax.annotation.Nullable;
import javax.inject.*;
import javax.swing.SwingUtilities;

import com.google.gson.*;

import io.droptracker.DropTrackerConfig;
import io.droptracker.models.api.GroupAdmin;
import lombok.AllArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;
import okhttp3.*;

/**
 * Group administration from the plugin ({@code /plugin/admin/...}).
 *
 * <p>Two factors stand behind every call. The account (name + hash, like every
 * other endpoint) must belong to a site user who owns or administers the group,
 * and the request must carry a device session for that group, which the server
 * only issues in exchange for the group's verification code. The code is sent
 * once and never stored; the session is stored per RuneScape profile and is
 * revoked server-side whenever the owner resets the code.
 *
 * <p>Every call runs on the injected executor and answers on the Swing thread.
 */
@Slf4j
@Singleton
@AllArgsConstructor(onConstructor_ = @Inject)
public class GroupAdminApi {

    private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");
    private static final String TOKEN_KEY = "groupAdminSession.";

    private final DropTrackerConfig config;
    private final DropTrackerApi api;
    private final Gson gson;
    private final OkHttpClient httpClient;
    private final ScheduledExecutorService executor;
    private final ConfigManager configManager;

    /** What a call came back with: a value, or a sentence for the leader. */
    @AllArgsConstructor
    public static final class Result<T> {
        @Nullable
        public final T value;
        @Nullable
        public final String error;
        /** The group needs its verification code (again) before this works. */
        public final boolean needsCode;

        static <T> Result<T> ok(T value) {
            return new Result<>(value, null, false);
        }

        static <T> Result<T> failed(String error) {
            return new Result<>(null, error, false);
        }
    }

    public void groups(String playerName, long accountHash, Consumer<Result<GroupAdmin.Groups>> callback) {
        run(callback, () -> call("GET", "/plugin/admin/groups", playerName, accountHash, 0, null,
            GroupAdmin.Groups.class));
    }

    /** Exchanges the group's verification code for a device session, and stores it. */
    public void link(String playerName, long accountHash, int groupId, String code,
                     Consumer<Result<GroupAdmin.Link>> callback) {
        Map<String, Object> body = new HashMap<>();
        body.put("group_id", groupId);
        body.put("code", code);
        run(callback, () -> {
            Result<GroupAdmin.Link> result = call("POST", "/plugin/admin/link", playerName, accountHash, 0, body,
                GroupAdmin.Link.class);
            if (result.value != null && result.value.getToken() != null) {
                configManager.setRSProfileConfiguration(DropTrackerConfig.GROUP, TOKEN_KEY + groupId,
                    result.value.getToken());
            }
            return result;
        });
    }

    /** Ends this device's session for the group, here and on the server. */
    public void unlink(String playerName, long accountHash, int groupId, Consumer<Result<JsonObject>> callback) {
        run(callback, () -> {
            Result<JsonObject> result = call("POST", "/plugin/admin/groups/" + groupId + "/unlink", playerName,
                accountHash, groupId, new HashMap<>(), JsonObject.class);
            forget(groupId);
            return result;
        });
    }

    public void overview(String playerName, long accountHash, int groupId,
                         Consumer<Result<GroupAdmin.Overview>> callback) {
        run(callback, () -> call("GET", "/plugin/admin/groups/" + groupId + "/overview", playerName, accountHash,
            groupId, null, GroupAdmin.Overview.class));
    }

    public void settings(String playerName, long accountHash, int groupId,
                         Consumer<Result<GroupAdmin.Settings>> callback) {
        run(callback, () -> call("GET", "/plugin/admin/groups/" + groupId + "/settings", playerName, accountHash,
            groupId, null, GroupAdmin.Settings.class));
    }

    /** Saves changed settings. A refusal comes back as {@link GroupAdmin.Settings#getErrors()}. */
    public void save(String playerName, long accountHash, int groupId, Map<String, Object> changes,
                     Consumer<Result<GroupAdmin.Settings>> callback) {
        Map<String, Object> body = new HashMap<>();
        body.put("changes", changes);
        run(callback, () -> call("PATCH", "/plugin/admin/groups/" + groupId + "/settings", playerName,
            accountHash, groupId, body, GroupAdmin.Settings.class));
    }

    public void members(String playerName, long accountHash, int groupId, String query, int page,
                        Consumer<Result<GroupAdmin.Members>> callback) {
        String path = "/plugin/admin/groups/" + groupId + "/members?page=" + page + "&q="
            + java.net.URLEncoder.encode(query, java.nio.charset.StandardCharsets.UTF_8);
        run(callback, () -> call("GET", path, playerName, accountHash, groupId, null, GroupAdmin.Members.class));
    }

    /** Shows or hides a member on the group's boards. */
    public void setHidden(String playerName, long accountHash, int groupId, int playerId, boolean hidden,
                          Consumer<Result<JsonObject>> callback) {
        Map<String, Object> body = new HashMap<>();
        body.put("hidden", hidden);
        run(callback, () -> call("POST", "/plugin/admin/groups/" + groupId + "/members/" + playerId + "/hidden",
            playerName, accountHash, groupId, body, JsonObject.class));
    }

    public void womSync(String playerName, long accountHash, int groupId, Consumer<Result<GroupAdmin.Notice>> callback) {
        run(callback, () -> call("POST", "/plugin/admin/groups/" + groupId + "/wom-sync", playerName, accountHash,
            groupId, new HashMap<>(), GroupAdmin.Notice.class));
    }

    /** Starts registering a group: a WiseOldMan id, or (null) the clan roster to make one from. */
    public void register(String playerName, long accountHash, String name, @Nullable Integer womId,
                         List<Map<String, String>> roster, Consumer<Result<GroupAdmin.Registration>> callback) {
        Map<String, Object> body = new HashMap<>();
        body.put("name", name);
        body.put("wom_id", womId);
        body.put("roster", roster);
        run(callback, () -> call("POST", "/plugin/register", playerName, accountHash, 0, body,
            GroupAdmin.Registration.class));
    }

    /** Polls a registration; once done, keeps the new group's session like {@link #link}. */
    public void registration(String playerName, long accountHash, String id,
                             Consumer<Result<GroupAdmin.RegistrationStatus>> callback) {
        run(callback, () -> {
            Result<GroupAdmin.RegistrationStatus> result = call("GET", "/plugin/register/status?id=" + id, playerName,
                accountHash, 0, null, GroupAdmin.RegistrationStatus.class);
            if (result.value != null && result.value.getToken() != null) {
                configManager.setRSProfileConfiguration(DropTrackerConfig.GROUP, TOKEN_KEY + result.value.getGroupId(),
                    result.value.getToken());
            }
            return result;
        });
    }

    public boolean hasSession(int groupId) {
        return token(groupId) != null;
    }

    @Nullable
    private String token(int groupId) {
        String token = configManager.getRSProfileConfiguration(DropTrackerConfig.GROUP, TOKEN_KEY + groupId);
        return token == null || token.isEmpty() ? null : token;
    }

    private void forget(int groupId) {
        configManager.unsetRSProfileConfiguration(DropTrackerConfig.GROUP, TOKEN_KEY + groupId);
    }

    private <T> void run(Consumer<Result<T>> callback, java.util.function.Supplier<Result<T>> work) {
        executor.execute(() -> {
            Result<T> result = work.get();
            SwingUtilities.invokeLater(() -> callback.accept(result));
        });
    }

    private <T> Result<T> call(String method, String path, String playerName, long accountHash, int groupId,
                               @Nullable Map<String, Object> body, Type type) {
        if (!config.useApi()) {
            return Result.failed(API_OFF);
        }
        HttpUrl base = HttpUrl.parse(api.getApiUrl() + path);
        if (base == null) {
            return Result.failed(UNREACHABLE);
        }
        Request.Builder request = new Request.Builder().cacheControl(CacheControl.FORCE_NETWORK);
        if (body == null) {
            request.url(base.newBuilder()
                .addQueryParameter("player_name", playerName)
                .addQueryParameter("acc_hash", String.valueOf(accountHash))
                .build());
            request.method(method, null);
        } else {
            body.put("player_name", playerName);
            body.put("acc_hash", String.valueOf(accountHash));
            request.url(base).method(method, RequestBody.create(JSON, gson.toJson(body)));
        }
        String token = groupId > 0 ? token(groupId) : null;
        if (groupId > 0 && token == null) {
            return new Result<>(null, null, true);
        }
        if (token != null) {
            request.header("Authorization", "Bearer " + token);
        }
        try (Response response = httpClient.newCall(request.build()).execute()) {
            ResponseBody responseBody = response.body();
            Result<T> result = interpret(gson, response.code(), responseBody == null ? "" : responseBody.string(), type);
            if (result.needsCode && groupId > 0) {
                forget(groupId);
            }
            return result;
        } catch (IOException e) {
            log.debug("Group admin request failed: {}", e.toString());
            return Result.failed(UNREACHABLE);
        }
    }

    static final String API_OFF = "Turn on \"Use API Connections\" in the plugin settings to manage your group here.";
    static final String UNREACHABLE = "Couldn't reach the DropTracker. Try again in a moment.";
    static final String WRONG_CODE = "That code isn't right. Check it with your group's owner.";
    static final String NO_CODE = "This group has no verification code yet. Its owner can create one under "
        + "Roles & access on droptracker.io.";
    static final String THROTTLED = "Too many tries. Wait a few minutes and try again.";
    static final String NOT_ADMIN = "This account isn't an owner or admin of that group. Claim your RSN on "
        + "droptracker.io with the Discord account that manages it.";

    /** Turns a response into a {@link Result}. Package-private for the tests. */
    static <T> Result<T> interpret(Gson gson, int status, String body, Type type) {
        JsonObject error = null;
        if (status != 200) {
            try {
                JsonElement parsed = gson.fromJson(body, JsonElement.class);
                error = parsed != null && parsed.isJsonObject() ? parsed.getAsJsonObject() : null;
            } catch (JsonSyntaxException e) {
                // not JSON: the generic sentence below
            }
        }
        String code = text(error, "code");
        if (status == 200 || (status == 422 && type == GroupAdmin.Settings.class)) {
            try {
                T value = gson.fromJson(body, type);
                return value != null ? Result.ok(value) : Result.failed(UNREACHABLE);
            } catch (JsonSyntaxException e) {
                return Result.failed(UNREACHABLE);
            }
        }
        if (status == 401 && !"wrong_code".equals(code)) {
            // The session expired or the owner reset the code.
            return new Result<>(null, "Your session for this group has ended. Enter the code again.", true);
        }
        String fallback;
        if ("wrong_code".equals(code)) {
            fallback = WRONG_CODE;
        } else if ("no_code".equals(code) || status == 409) {
            fallback = NO_CODE;
        } else if (status == 429) {
            fallback = THROTTLED;
        } else if (status == 403) {
            fallback = NOT_ADMIN;
        } else if (status == 422) {
            fallback = UNREACHABLE;
        } else {
            return Result.failed(UNREACHABLE);
        }
        // The server's sentence is written for the leader; prefer it.
        String message = text(error, "error");
        return Result.failed(message != null ? message : fallback);
    }

    @Nullable
    private static String text(@Nullable JsonObject object, String key) {
        if (object == null || !object.has(key) || !object.get(key).isJsonPrimitive()) {
            return null;
        }
        return object.get(key).getAsString();
    }
}

package io.droptracker.api;

import lombok.AccessLevel;
import lombok.AllArgsConstructor;
import java.io.IOException;
import java.time.LocalDate;
import java.time.format.DateTimeFormatter;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.regex.Pattern;

import javax.annotation.Nullable;
import javax.inject.Inject;

import com.google.gson.*;

import lombok.extern.slf4j.Slf4j;
import net.runelite.client.callback.ClientThread;
import io.droptracker.util.ChatMessageUtil;
import okhttp3.*;

import io.droptracker.*;

/* Helps determine what URL to send submissions to, populates the list on startup, etc. */
@Slf4j
public class UrlManager {

    private final DropTrackerConfig config;


    @Inject
    private DropTrackerPlugin plugin;

    @Inject
    private ClientThread clientThread;

    @Inject
    private ChatMessageUtil chatMessageUtil;

    @Inject
    private ScheduledExecutorService executor;

    @Inject
    private OkHttpClient httpClient;

    @Inject
    private Gson gson;

    private static final Random RANDOM = new Random();

    /** How many times the initial endpoint load has failed; retried with backoff. */
    private final AtomicInteger loadAttempts = new AtomicInteger(0);

    private static final int MAX_LOAD_ATTEMPTS = 5;

    @Inject
    public UrlManager(DropTrackerConfig config, DropTrackerPlugin plugin, ClientThread clientThread, ChatMessageUtil chatMessageUtil) {
        this.config = config;
        this.plugin = plugin;
        this.clientThread = clientThread;
        this.chatMessageUtil = chatMessageUtil;
    }


    private static CompletableFuture<Void> endpointUrlsLoaded = new CompletableFuture<>();

    public static List<WebhookEndpoint> endpoints = new ArrayList<>();

    private static int webhookResetCount = 0;

	public static List<WebhookEndpoint> backupEndpoints = new ArrayList<>();

	public static Boolean usingBackups = false;

	/** Everything after {@code /api/webhooks/} in a published entry, if it is written as a URL. */
	private static final Pattern WEBHOOK_PATH = Pattern.compile(".*?/api/webhooks/", Pattern.DOTALL);

	/**
	 * A Discord webhook as the two opaque credentials it actually is. The host is
	 * never taken from the published list — see {@link #url()}.
	 */
	@AllArgsConstructor(access = AccessLevel.PACKAGE)
	public static final class WebhookEndpoint {
		private final String id;
		private final String token;

		/** Always under the hardcoded {@link DropTrackerUrls#DISCORD_WEBHOOK} base. */
		public HttpUrl url() {
			return DropTrackerUrls.discordWebhook(id, token);
		}
	}

	/**
	 * Turns one decrypted list entry into a webhook credential pair, or null if it
	 * is not one.
	 *
	 * <p>Accepts both the legacy format (a full {@code https://discord.com/api/webhooks/<id>/<token>}
	 * URL) and the current one (a bare {@code <id>/<token>} pair), so the plugin works
	 * against a list published either way. In both cases only the last two path
	 * segments are read — whatever host the entry may claim is discarded, never
	 * parsed, and never connected to.
	 */
	@Nullable
	static WebhookEndpoint parseEndpoint(@Nullable String plaintext) {
		if (plaintext == null) {
			return null;
		}
		String candidate = plaintext.trim();
		// Drop any host/prefix a legacy entry carries, plus any query or fragment.
		candidate = WEBHOOK_PATH.matcher(candidate).replaceFirst("");
		int cut = candidate.indexOf('?');
		if (cut < 0) {
			cut = candidate.indexOf('#');
		}
		if (cut >= 0) {
			candidate = candidate.substring(0, cut);
		}
		String[] parts = candidate.split("/");
		if (parts.length != 2) {
			return null;
		}
		// discordWebhook() is the validator: it returns null unless both parts are
		// well-formed credentials, which is exactly the condition for accepting one.
		if (DropTrackerUrls.discordWebhook(parts[0], parts[1]) == null) {
			return null;
		}
		return new WebhookEndpoint(parts[0], parts[1]);
	}

    /**
	 * Grabs a random webhook endpoint from the preloaded list.
	 * If not loaded yet, throws.
	 */
	public static HttpUrl getRandomEndpoint() throws IllegalStateException {
		// Wait for endpoints to be loaded, but don't block the main thread
		if (!endpointUrlsLoaded.isDone()) {
			throw new IllegalStateException("Endpoints are not yet loaded; cannot submit...");
		}
		if (endpoints.isEmpty()) {
			throw new IllegalStateException("No valid endpoints were loaded - check logs for loading errors");
		}
		return endpoints.get(RANDOM.nextInt(endpoints.size())).url();
	}

    /* Determine whether the given URL is a properly-formatted Discord webhook URL or not */
    public boolean isValidDiscordWebhookUrl(HttpUrl url) {
		if (config.useApi() && (url.host().equals("api.droptracker.io") || !config.customApiEndpoint().equals(""))) {
			return true;
		}
		// Ensure that any webhook URLs returned from the GitHub page are actual Discord webhooks
		// And not external connections of some sort
		if (!"discord.com".equals(url.host()) && !url.host().endsWith(".discord.com")) {
			if(!"discordapp.com".equals(url.host()) && !url.host().endsWith(".discordapp.com")){
				return false;
			}
		}
		List<String> segments = url.pathSegments();
		if (segments.size() >= 4 && "api".equals(segments.get(0)) && "webhooks".equals(segments.get(1))) {
			return true;
		}
		return false;
	}

    /* Fetch a new list of webhook URLs from the GitHub page */
    public void fetchNewList() throws IOException {
		if (UrlManager.webhookResetCount > 10) {
			// At this point we just stop attempting to fetch new webhooks
			// Assuming that something on the backend is broken and they're not replenishing properly
			plugin.isTracking = false;
			// isTracking prevents all event processing
			return;
		}
		// Attempt to obtain a new list
		 if (backupEndpoints.isEmpty()) {
			String dateString = today();
			HttpUrl url = usingBackups
					? DropTrackerUrls.content(dateString + ".json")
					: DropTrackerUrls.content(dateString + "-1.json");

			decryptInto(gson.fromJson(httpGetString(url), JsonArray.class), backupEndpoints,
				"[DropTracker] Decrypted entry is not a webhook credential; skipping");
			if (!backupEndpoints.isEmpty()) {
				// COPY the freshly fetched list, then clear the backing one.
				// Assigning the reference made both fields the same ArrayList,
				// so the clear() below emptied the list we had just installed:
				// every webhook submission after the first refresh threw
				// IllegalStateException ("no urls") and was silently dropped,
				// and the recovery path could never repopulate because
				// backupEndpoints was permanently the same (empty) object. Ten
				// rounds of that flipped isTracking off entirely.
				endpoints = new ArrayList<>(backupEndpoints);
				backupEndpoints.clear();
				clientThread.invokeLater(() -> {
					chatMessageUtil.sendChatMessage("We are currently having some trouble transmitting your drops to our server...");
					chatMessageUtil.sendChatMessage("Please consider enabling our API in the plugin configuration to continue tracking seamlessly.");
				});

				UrlManager.webhookResetCount++;
				// toggle whether the current set of webhooks is from the backup endpoint or the main one
				// incase we need to grab a new set before the client restarts again.
				usingBackups = !usingBackups;
			}

		}

	}


	/* Load webhook credentials in the background from the GitHub pages site */
	public void loadEndpoints() {
		try {
			if (endpoints.isEmpty()) {

			    String dateString = today();
				// Get the encryption key first from github (first line only, matching the prior readLine())
				String keyBody = httpGetString(DropTrackerUrls.content(dateString + "-k.txt"));
				String loadedKey = keyBody.split("\\R", 2)[0].trim();
				if (!loadedKey.isEmpty()) {
					FernetDecrypt.ENCRYPTION_KEY = loadedKey;
				} else {
					// Treat a missing key like any other load failure so the retry
					// logic below runs instead of leaving the future forever pending.
					throw new IOException("Encryption key endpoint returned no content");
				}

				String responseBody = httpGetString(DropTrackerUrls.content(dateString + ".json"));
				decryptInto(gson.fromJson(responseBody, JsonArray.class), endpoints,
					"Decrypted entry is not a Discord webhook credential; skipping");
			}
			log.debug("Successfully loaded {} webhook endpoints from GitHub", endpoints.size());
			endpointUrlsLoaded.complete(null);
		} catch (Exception e) {
			// A transient network failure at client startup used to permanently
			// disable webhook-mode submissions (the future completed exceptionally
			// and nothing ever retried). Retry with linear backoff instead.
			int attempt = loadAttempts.incrementAndGet();
			if (attempt < MAX_LOAD_ATTEMPTS) {
				long delaySeconds = 30L * attempt;
				log.warn("Failed to load webhook endpoints from GitHub (attempt {}/{}); retrying in {}s",
					attempt, MAX_LOAD_ATTEMPTS, delaySeconds, e);
				executor.schedule(this::loadEndpoints, delaySeconds, TimeUnit.SECONDS);
			} else {
				log.error("Failed to load webhook endpoints from GitHub after {} attempts; giving up", attempt, e);
				endpointUrlsLoaded.completeExceptionally(e);
			}
		}
	}

	/** Today as YYYYMMDD, the date stamp on the published endpoint lists. */
	private static String today() {
		return LocalDate.now().format(DateTimeFormatter.ofPattern("yyyyMMdd"));
	}

	/** Decrypts each published entry into {@code into}, skipping (and logging) bad ones. */
	private void decryptInto(JsonArray jsonArray, List<WebhookEndpoint> into, String notWebhook) {
		for (JsonElement element : jsonArray) {
			try {
				String encrypted = element.getAsString();
				try {
					WebhookEndpoint endpoint = parseEndpoint(FernetDecrypt.decryptWebhook(encrypted));
					if (endpoint != null) {
						into.add(endpoint);
					} else {
						log.error(notWebhook);
					}
				} catch (Exception e) {
					log.error("Decryption failed: {}", e.getMessage());
				}
			} catch (Exception e) {
				log.error("Error processing element: {}", e.getMessage());
			}
		}
	}

	/** Blocking GET returning the response body as a String, via the injected shared OkHttpClient. */
	private String httpGetString(@Nullable HttpUrl url) throws IOException {
		if (url == null) {
			throw new IOException("Refusing to fetch a rejected content URL");
		}
		Request request = new Request.Builder().url(url).build();
		try (Response response = httpClient.newCall(request).execute()) {
			if (!response.isSuccessful()) {
				throw new IOException("Request to " + url + " failed: HTTP " + response.code());
			}
			ResponseBody body = response.body();
			if (body == null) {
				throw new IOException("Empty response body from " + url);
			}
			return body.string();
		}
	}
}

package io.droptracker.events;

import com.google.inject.Inject;
import io.droptracker.*;
import io.droptracker.api.DropTrackerApi;
import io.droptracker.models.CustomWebhookBody;
import io.droptracker.models.submissions.SubmissionType;
import io.droptracker.service.SubmissionManager;
import io.droptracker.util.*;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;

import javax.annotation.Nullable;
import java.util.concurrent.ScheduledExecutorService;
import java.util.Map;

/**
 * Base abstract class for all event handlers
 * Provides common dependencies, shared logic, and standardized methods for webhook creation and data transmission.
 */
@Slf4j
public abstract class BaseEventHandler {

    @Inject
    protected DropTrackerPlugin plugin;

    @Inject
    protected Client client;

    @Inject
    protected ConfigManager configManager;

    @Inject
    protected ClientThread clientThread;

    @Inject
    protected DropTrackerApi api;

    @Inject
    protected DropTrackerConfig config;

    @Inject
    protected SubmissionManager submissionManager;

    // Optional dependency - not all handlers use the executor
    @Inject(optional = true)
    protected ScheduledExecutorService executor;

    /**
     * Determines if this event handler is currently enabled.
     * Override this method in subclasses to implement specific enable/disable logic.
     * 
     * @return true if the handler is enabled, false otherwise
     */
    public boolean isEnabled() {
        return true;
    }

    /**
     * Resolves the RSN to submit this event under.
     *
     * <p>See {@link PlayerIdentity} for why this never falls back to a made-up
     * name, and what it does fall back to instead.
     *
     * @return the RSN, or {@code null} when it cannot be established — callers
     *         must skip the submission entirely rather than send it nameless
     */
    @Nullable
    protected String getPlayerName() {
        String name = PlayerIdentity.resolve(
            plugin != null ? plugin.getLocalPlayerName() : null,
            getAccountHash(),
            config != null ? config.lastAccountName() : null,
            config != null ? config.lastAccountHash() : null);
        if (name == null) {
            DebugLogger.log("[" + getClass().getSimpleName() + "] no resolvable player name; not submitting");
        }
        return name;
    }

    /**
     * Gets the account hash as a string.
     * 
     * @return the account hash, or "0" if client is null
     */
    protected String getAccountHash() {
        return client != null ? String.valueOf(client.getAccountHash()) : "0";
    }

    /**
     * Adds common fields that are present in all webhook embeds.
     * This includes player_name, acc_hash, p_v, and any global fields.
     * 
     * @param embed the embed to add fields to
     */
    protected void addCommonFields(CustomWebhookBody.Embed embed) {
        if (embed == null) {
            log.warn("Attempted to add common fields to null embed");
            return;
        }

        String playerName = getPlayerName();
        String accountHash = getAccountHash();
        String pluginVersion = plugin != null && plugin.pluginVersion != null ? plugin.pluginVersion : "unknown";
        String guid = api != null ? api.generateGuidForSubmission() : "unknown";

        /* Handlers are expected to bail before building an embed they have no
           identity for. If one ever forgets, an empty name is what makes the
           submission fail SubmissionManager's identity check instead of going
           out under a made-up one. */
        if (playerName == null) {
            playerName = "";
        }

        embed.addField("player_name", playerName, true);
        embed.addField("acc_hash", accountHash, true);
        embed.addField("p_v", pluginVersion, true);
        embed.addField("guid", guid, true);
        /* The server's "Drop processed" confirmation obeys this over the
           player's website setting, which only covers builds without it. */
        if (config != null) {
            boolean confirm = config.receiveInGameMessages() && config.dropConfirmations();
            embed.addField("drop_confirm", String.valueOf(confirm), true);
        }
    }

    /**
     * Creates a new webhook body with basic setup.
     * 
     * @param content the main content message for the webhook
     * @return a new CustomWebhookBody instance
     */
    protected CustomWebhookBody createWebhookBody(String content) {
        CustomWebhookBody webhook = new CustomWebhookBody();
        webhook.setContent(content != null ? content : "DropTracker Event");
        return webhook;
    }

    /**
     * Creates a new embed with the specified title and type, and automatically adds common fields.
     * 
     * @param title the title for the embed
     * @param type the type of the embed (e.g., "drop", "combat_achievement", "collection_log", "npc_kill")
     * @return a new CustomWebhookBody.Embed instance with common fields already added
     */
    protected CustomWebhookBody.Embed createEmbed(String title, String type) {
        CustomWebhookBody.Embed embed = new CustomWebhookBody.Embed();
        if (title != null && !title.trim().isEmpty()) {
            embed.setTitle(title);
        } else {
            embed.setTitle("DropTracker Event");
        }
        if (type != null && !type.trim().isEmpty()) {
            embed.addField("type", type, true);
        }
        addCommonFields(embed);
        return embed;
    }

    /**
     * Creates a new embed with the specified title (no type field).
     * 
     * @param title the title for the embed
     * @return a new CustomWebhookBody.Embed instance
     */
    protected CustomWebhookBody.Embed createEmbed(String title) {
        return createEmbed(title, null);
    }

    /**
     * Adds multiple fields to an embed from a map of field data.
     * 
     * @param embed the embed to add fields to
     * @param fieldData map of field names to values
     */
    protected void addFields(CustomWebhookBody.Embed embed, Map<String, Object> fieldData) {
        addFields(embed, fieldData, true);
    }

    /**
     * Adds multiple fields to an embed from a map of field data.
     * 
     * @param embed the embed to add fields to
     * @param fieldData map of field names to values
     * @param inline whether the fields should be inline
     */
    protected void addFields(CustomWebhookBody.Embed embed, Map<String, Object> fieldData, boolean inline) {
        if (embed == null) {
            log.warn("Attempted to add fields to null embed");
            return;
        }
        if (fieldData == null) {
            log.warn("Attempted to add null fieldData to embed");
            return;
        }

        for (Map.Entry<String, Object> entry : fieldData.entrySet()) {
            String fieldName = entry.getKey();
            if (fieldName == null || fieldName.trim().isEmpty()) {
                log.debug("Skipping field with null/empty name");
                continue;
            }

            String value;
            Object rawValue = entry.getValue();
            if (rawValue == null) {
                value = "N/A";
            } else if (rawValue instanceof String && ((String) rawValue).trim().isEmpty()) {
                value = "N/A";
            } else {
                value = String.valueOf(rawValue);
            }

            embed.addField(fieldName, value, inline);
        }
    }

    /**
     * Sends webhook data to the DropTracker API with a string type identifier.
     * Used for events like combat achievements, collection logs, and kills.
     * 
     * @param webhook the webhook body to send
     * @param type the event type identifier
     */
    protected void sendData(CustomWebhookBody webhook, SubmissionType type) {
        DebugLogger.log("[BaseEventHandler][send] " + type + " " + webhook);
        if (webhook == null) {
            log.warn("Attempted to send null webhook data");
            return;
        }
        if (webhook.getEmbeds() == null || webhook.getEmbeds().isEmpty()) {
            log.warn("Attempted to send webhook with no embeds");
            return;
        }
        if (type == null) {
            log.warn("Attempted to send webhook with null submission type");
            return;
        }
        if (submissionManager == null) {
            log.error("SubmissionManager is null, cannot send webhook data");
            return;
        }

        try {
            submissionManager.sendDataToDropTracker(webhook, type);
        } catch (Exception e) {
            log.error("Failed to send webhook data: {}", e.getMessage(), e);
        }
    }

    /**
     * Sends webhook data to the DropTracker API with a numeric value.
     * Used for drops where the value is the total drop value.
     * 
     * @param webhook the webhook body to send
     * @param value the total value of the event
     * @param singleValue the value of individual items (for stacked item checking)
     */
    protected void sendData(CustomWebhookBody webhook, long value, long singleValue, boolean valueModified) {
        if (webhook == null) {
            log.warn("Attempted to send null webhook data");
            return;
        }
        if (webhook.getEmbeds() == null || webhook.getEmbeds().isEmpty()) {
            log.warn("Attempted to send webhook with no embeds");
            return;
        }
        if (submissionManager == null) {
            log.error("SubmissionManager is null, cannot send webhook data");
            return;
        }

        try {
            submissionManager.sendDataToDropTracker(webhook, value, singleValue, valueModified);
        } catch (Exception e) {
            log.error("Failed to send webhook data: {}", e.getMessage(), e);
        }
    }

    /**
     * Gets the kill count for a specific boss from the configuration.
     * 
     * @param bossName the name of the boss
     * @return the kill count, or 0 if not found
     */
    protected int getKillCount(String bossName) {
        if (bossName == null) {
            return 0;
        }
        Integer killCount = configManager.getRSProfileConfiguration("killcount", bossName.toLowerCase(), int.class);
        return killCount != null ? killCount : 0;
    }


}

package io.droptracker.events;

import io.droptracker.models.CustomWebhookBody;
import io.droptracker.models.submissions.*;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.annotations.Varbit;
import org.apache.commons.lang3.tuple.Pair;
import org.jetbrains.annotations.VisibleForTesting;

import java.util.*;
import java.util.regex.*;


@Slf4j
public class CaHandler extends BaseEventHandler {
    private static final Pattern ACHIEVEMENT_PATTERN = Pattern.compile("Congratulations, you've completed an? (?<tier>\\w+) combat task: (?<task>.+)\\.");
    private static final Pattern TASK_POINTS = Pattern.compile("\\s+\\(\\d+ points?\\)$");

    /**
     * Jagex's {@code @token@} chat markup. Since the 2026-08-26 update the
     * completion message wraps the task name in {@code @ach_comp@} (the token
     * that makes it click-through in game), so the raw capture reads
     * "@ach_comp@Smite Fight". The client consumes these tokens rather than
     * rendering them — the player never sees them — so they must not travel
     * with the name: the panel would show the token, and the server keys a
     * completion on the name, so a marked-up one reads as a task nobody has
     * ever done.
     * <p>
     * Bounded length so a stray pair of {@code @} cannot swallow the name. No
     * real task name contains {@code @}, which is what makes a generic pattern
     * safe here.
     */
    private static final Pattern CHAT_TOKEN = Pattern.compile("@[A-Za-z][A-Za-z0-9_]{0,15}@");
    @Varbit
    public static final int COMBAT_TASK_REPEAT_POPUP = 12456;

    @Varbit
    public static final int TOTAL_POINTS_ID = 14815;
    @Varbit
    public static final int GRANDMASTER_TOTAL_POINTS_ID = 14814;

    public void onGameMessage(String message) {
        if (!isEnabled()) return;
        parseCombatAchievement(message).ifPresent(pair -> processCombatAchievement(pair.getLeft(), pair.getRight()));
    }

    private void processCombatAchievement(CombatAchievement tier, String task) {
        // delay notification for varbits to be updated
        clientThread.invokeAtTickEnd(() -> {
            int taskPoints = tier.getPoints();
            int totalPoints = client.getVarbitValue(TOTAL_POINTS_ID);

            String player = getPlayerName();
            if (player == null) {
                return;
            }
            CustomWebhookBody combatWebhook = createWebhookBody(player + " has completed a new combat task:");
            CustomWebhookBody.Embed combatAchievementEmbed = createEmbed(null, "combat_achievement");

            Map<String, Object> fieldData = new HashMap<>();
            fieldData.put("tier", tier.toString());
            fieldData.put("task", task);
            fieldData.put("points", taskPoints);
            fieldData.put("total_points", totalPoints);

            addFields(combatAchievementEmbed, fieldData);

            combatWebhook.getEmbeds().add(combatAchievementEmbed);
            sendData(combatWebhook, SubmissionType.COMBAT_ACHIEVEMENT);
        });
    }

    @VisibleForTesting
    static Optional<Pair<CombatAchievement, String>> parseCombatAchievement(String message) {
        Matcher matcher = ACHIEVEMENT_PATTERN.matcher(message);
        if (!matcher.find()) return Optional.empty();
        String task = cleanTaskName(matcher.group("task"));
        // Nothing but markup matched: there is no task here to submit, and an
        // empty name would reach the server as a completion of "".
        if (task.isEmpty()) return Optional.empty();
        return Optional.of(matcher.group("tier"))
                .map(CombatAchievement.TIER_BY_LOWER_NAME::get)
                .map(tier -> Pair.of(tier, task));
    }

    /** Task name with the points suffix and any chat markup removed. */
    @VisibleForTesting
    static String cleanTaskName(String task) {
        if (task == null) return "";
        // Markup first: the points suffix anchors on end-of-string, so a
        // trailing token would hide it.
        String cleaned = CHAT_TOKEN.matcher(task).replaceAll("");
        cleaned = TASK_POINTS.matcher(cleaned).replaceFirst("");
        return cleaned.trim();
    }
}

package io.droptracker.events;

import com.google.inject.Inject;
import io.droptracker.models.CustomWebhookBody;
import io.droptracker.models.submissions.*;
import io.droptracker.service.*;
import io.droptracker.util.*;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;
import net.runelite.api.gameval.*;
import net.runelite.client.game.ItemStack;
import net.runelite.http.api.loottracker.LootRecordType;
import org.jetbrains.annotations.Nullable;

import java.time.*;
import java.util.*;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.regex.*;


@Slf4j
public class ClogHandler extends BaseEventHandler {
    private final Rarity rarity;
    private final KCService kcService;
    private final ItemIDSearch itemIDFinder;
    /* State sync: a newly unlocked slot should reach the website promptly,
     * rather than waiting out the periodic sync interval. */
    private final StateSyncService stateSyncService;
    private final StateSyncScheduler stateSyncScheduler;
    /* Which ids the collection log actually has slots for, so the id we record
     * for an unlock is the log's, not the first item to share its name. */
    private final CollectionLogSlots collectionLogSlots;

    private final AtomicBoolean popupStarted = new AtomicBoolean(false);

    private static final Duration RECENT_DROP = Duration.ofSeconds(30L);

    @Inject
    public ClogHandler(ItemIDSearch itemIDFinder, Rarity rarity, KCService kcService,
                       StateSyncService stateSyncService, StateSyncScheduler stateSyncScheduler,
                       CollectionLogSlots collectionLogSlots) {
        this.stateSyncService = stateSyncService;
        this.stateSyncScheduler = stateSyncScheduler;
        this.collectionLogSlots = collectionLogSlots;
        this.itemIDFinder = itemIDFinder;
        this.rarity = rarity;
        this.kcService = kcService;
    }


    static final Pattern COLLECTION_LOG_REGEX = Pattern.compile("New item added to your collection log: (?<itemName>(.*))");
    private static final int POPUP_PREFIX_LENGTH = "New item:".length();



    @Override
    public boolean isEnabled() {
        return config.clogEmbeds();
    }


    public void onChatMessage(String chatMessage) {
        if (client.getVarbitValue(VarbitID.OPTION_COLLECTION_NEW_ITEM) != 1 || !this.isEnabled()) {
            // require notifier enabled without popup mode to use chat event
            return;
        }
        Matcher collectionMatcher = COLLECTION_LOG_REGEX.matcher(chatMessage);
        if (collectionMatcher.find()) {
            String itemName = collectionMatcher.group("itemName");
            clientThread.invokeLater(() -> processCollection(itemName));
        }
    }

    public void reset() {
        popupStarted.set(false);
    }

    public void onScript(int scriptId) {
        if (scriptId == ScriptID.NOTIFICATION_START) {
            popupStarted.set(true);
        } else if (scriptId == ScriptID.NOTIFICATION_DELAY) {
            String topText = client.getVarcStrValue(VarClientStr.NOTIFICATION_TOP_TEXT);
            if (popupStarted.getAndSet(false) && "Collection log".equalsIgnoreCase(topText) && this.isEnabled()) {
                String bottomText = submissionManager.sanitize(client.getVarcStrValue(VarClientStr.NOTIFICATION_BOTTOM_TEXT));
                processCollection(bottomText.substring(POPUP_PREFIX_LENGTH).trim());
            }
        }
    }




    private void processCollection(String itemName) {
        if (!this.isEnabled()) {
            log.debug("Collection log processing disabled");
            return;
        }

        if (itemName == null || itemName.trim().isEmpty()) {
            log.debug("Cannot process collection log with null/empty item name");
            return;
        }

        try {
            int completed = 0;
            int total = 0;

            if (client != null) {
                completed = client.getVarpValue(VarPlayerID.COLLECTION_COUNT);
                total = client.getVarpValue(VarPlayerID.COLLECTION_COUNT_MAX);
            }

            boolean varpValid = total > 0 && completed > 0;
            if (!varpValid) {
                // This occurs if the player doesn't have the character summary tab selected
                log.debug("Collection log progress varps were invalid ({} / {})", completed, total);
            }

            Integer itemId = null;
            if (itemIDFinder != null) {
                try {
                    itemId = itemIDFinder.findItemId(itemName);
                } catch (Exception e) {
                    log.debug("Error finding item ID for {}: {}", itemName, e.getMessage());
                }
            }

            // Feed the state snapshot too: one new slot is cheap to record and
            // means the profile page updates now instead of at the next
            // scheduled sync. Additive only - this never implies the rest of
            // the log was read.
            //
            // The id has to be the *collection log's*, which is not always the
            // one a name resolves to: ItemIDSearch answers with the earliest
            // item sharing the name, so "Coal bag" gives 764 where the log
            // holds 25627. A wrong id leaves the slot looking unfilled and puts
            // a non-slot into the account's item map, so an id the log does not
            // define is dropped rather than recorded - a full read of the log
            // reports the slot properly soon enough.
            Integer slotId = collectionLogSlots != null
                    ? collectionLogSlots.resolve(itemId, itemName)
                    : itemId;
            if (slotId != null && stateSyncService != null && stateSyncService.isEnabled()) {
                stateSyncService.storeItem(slotId, 1);
                stateSyncScheduler.scheduleRapid("clog-item");
            }

            Drop loot = itemId != null ? getLootSource(itemId) : null;
            Integer killCount = 0;
            if (loot != null && kcService != null) {
                try {
                    killCount = kcService.getKillCountWithStorage(loot.getCategory(), loot.getSource());
                } catch (Exception e) {
                    log.debug("Error getting kill count: {}", e.getMessage());
                }
            }

            OptionalDouble itemRarity = OptionalDouble.empty();
            if (loot != null && loot.getCategory() == LootRecordType.NPC && itemId != null && rarity != null) {
                try {
                    itemRarity = rarity.getRarity(loot.getSource(), itemId, 1);
                } catch (Exception e) {
                    log.debug("Error calculating rarity: {}", e.getMessage());
                }
            }

            String player = getPlayerName();
            if (player == null) {
                return;
            }
            CustomWebhookBody collectionLogBody = createWebhookBody(player + " received a collection log:");
            CustomWebhookBody.Embed collEmbed = createEmbed(player + " received a collection log:", "collection_log");

            Map<String, Object> fieldData = new HashMap<>();
            fieldData.put("source", loot != null && loot.getSource() != null ? loot.getSource() : "unknown");
            fieldData.put("item", itemName);
            fieldData.put("kc", killCount);
            fieldData.put("rarity", itemRarity.isPresent() ? itemRarity.getAsDouble() : "unknown");
            fieldData.put("item_id", itemId);
            fieldData.put("slots", varpValid ? completed + "/" + total : "unknown");

            addFields(collEmbed, fieldData);

            if (collectionLogBody != null && collEmbed != null) {
                collectionLogBody.getEmbeds().add(collEmbed);
                sendData(collectionLogBody, SubmissionType.COLLECTION_LOG);
            } else {
                log.warn("Failed to create webhook or embed for collection log");
            }
        } catch (Exception e) {
            log.error("Error processing collection log for item {}: {}", itemName, e.getMessage(), e);
        }
    }

    @Nullable
    private Drop getLootSource(int itemId) {
        if (plugin == null) {
            return null;
        }

        Drop drop = plugin.lastDrop;
        if (drop == null || drop.getTime() == null) {
            return null;
        }

        try {
            if (Duration.between(drop.getTime(), Instant.now()).compareTo(RECENT_DROP) > 0) {
                return null;
            }

            if (drop.getItems() == null) {
                return null;
            }

            for (ItemStack item : drop.getItems()) {
                if (item != null && item.getId() == itemId) {
                    return drop;
                }
            }
        } catch (Exception e) {
            log.debug("Error checking loot source for item {}: {}", itemId, e.getMessage());
        }

        return null;
    }

}

package io.droptracker.events;

import com.google.gson.*;
import io.droptracker.DropTrackerConfig;
import io.droptracker.models.CustomWebhookBody;
import io.droptracker.models.submissions.SubmissionType;
import io.droptracker.util.DebugLogger;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.GameState;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.RuneLiteProperties;
import net.runelite.client.config.RuneLiteConfig;

import javax.annotation.Nullable;
import javax.inject.*;
import java.nio.charset.StandardCharsets;
import java.security.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.function.*;

/**
 * Sends the player's DropTracker settings to the server, so group leaders and
 * staff can see how a plugin is configured when they are helping debug it
 * ("why didn't my pet post?" is very often "pet notifications are off").
 *
 * <p>The snapshot is JSON in the embed's description: some 45 settings would
 * blow Discord's 25-field embed limit, and the description holds 4096
 * characters against a snapshot of about 2 KB. It rides the normal
 * submission transport (API or webhook, whichever the player uses).
 *
 * <p>Sent a little after each login, then again 60s after the settings stop
 * changing, and only when the content differs from what this client last
 * sent for the account.
 *
 * <p>What is sent is the explicit {@link #SETTINGS} list: a setting added to
 * {@link DropTrackerConfig} is not sent until it is listed there, so internal
 * state and anything private (account names, endpoints, any text setting)
 * stays out by default. The list is read through the config proxy rather than
 * discovered by reflection, which the Plugin Hub does not allow.
 */
@Slf4j
@Singleton
public class ConfigSnapshotHandler extends BaseEventHandler {
    static final int FORMAT_VERSION = 1;
    /** Discord's cap on an embed description. */
    static final int MAX_DESCRIPTION = 4096;
    private static final long LOGIN_DELAY_SECONDS = 20;
    private static final long CHANGE_DEBOUNCE_SECONDS = 60;

    /** Bookkeeping the plugin keeps in its config group; not settings. */
    static final Set<String> EXCLUDED = Set.of(
        "pinnedEventId", "lastVersionNotified", "lastAccountName",
        "customApiEndpoint", "lastAccountHash");

    /** One setting in the snapshot: its section, key, and how to read it. */
    static final class Setting {
        final String section;
        final String key;
        final Function<DropTrackerConfig, Object> read;

        Setting(String section, String key, Function<DropTrackerConfig, Object> read) {
            this.section = section;
            this.key = key;
            this.read = read;
        }
    }

    private static Setting setting(String section, String key, Function<DropTrackerConfig, Object> read) {
        return new Setting(section, key, read);
    }

    /**
     * Every setting the snapshot carries, in panel order, grouped by config
     * section ("Hidden" for settings not shown in the panel). Text settings
     * and the {@link #EXCLUDED} bookkeeping keys are deliberately absent;
     * {@code ConfigSnapshotHandlerTest} fails when a new boolean, number or
     * enum setting is added to {@link DropTrackerConfig} but not listed here.
     */
    static final List<Setting> SETTINGS = List.of(
        setting("Tracking", "lootEmbeds", DropTrackerConfig::lootEmbeds),
        setting("Tracking", "pbEmbeds", DropTrackerConfig::pbEmbeds),
        setting("Tracking", "clogEmbeds", DropTrackerConfig::clogEmbeds),
        setting("Tracking", "caEmbeds", DropTrackerConfig::caEmbeds),
        setting("Tracking", "petEmbeds", DropTrackerConfig::petEmbeds),
        setting("Tracking", "levelEmbed", DropTrackerConfig::levelEmbed),
        setting("Tracking", "xpMilestoneEmbeds", DropTrackerConfig::xpMilestoneEmbeds),
        setting("Tracking", "questsEmbed", DropTrackerConfig::questsEmbed),
        setting("Tracking", "deathEmbeds", DropTrackerConfig::deathEmbeds),
        setting("Tracking", "diaryEmbeds", DropTrackerConfig::diaryEmbeds),
        setting("Tracking", "slayerEmbeds", DropTrackerConfig::slayerEmbeds),
        setting("Tracking", "trackActivities", DropTrackerConfig::trackActivities),
        setting("Tracking", "clanChatSync", DropTrackerConfig::clanChatSync),

        setting("Screenshots", "screenshots", DropTrackerConfig::screenshots),
        setting("Screenshots", "screenshotValue", DropTrackerConfig::screenshotValue),
        setting("Screenshots", "screenshotUntradeables", DropTrackerConfig::screenshotUntradeables),
        setting("Screenshots", "minLevelToScreenshot", DropTrackerConfig::minLevelToScreenshot),
        setting("Screenshots", "privacyMode", DropTrackerConfig::privacyMode),
        setting("Screenshots", "compressImages", DropTrackerConfig::compressImages),
        setting("Screenshots", "screenshotCompressionKb", DropTrackerConfig::imageCompressionThresholdKb),

        setting("Events", "eventNotifications", DropTrackerConfig::eventNotifications),
        setting("Events", "eventDisplayMode", DropTrackerConfig::eventDisplayMode),
        setting("Events", "eventTaskProgressNotifications", DropTrackerConfig::eventTaskProgressNotifications),
        setting("Events", "eventHudDetail", DropTrackerConfig::eventHudDetail),
        setting("Events", "eventTeamIndicators", DropTrackerConfig::eventTeamIndicators),
        setting("Events", "eventTeamIndicatorColorNames", DropTrackerConfig::eventTeamIndicatorColorNames),
        setting("Events", "eventTeamIndicatorsPublicChat", DropTrackerConfig::eventTeamIndicatorsPublicChat),

        setting("Advanced", "useApi", DropTrackerConfig::useApi),
        setting("Advanced", "inGameMessages", DropTrackerConfig::receiveInGameMessages),
        setting("Advanced", "dropConfirmations", DropTrackerConfig::dropConfirmations),
        setting("Advanced", "receiveDiscordChat", DropTrackerConfig::receiveDiscordChat),
        setting("Advanced", "syncAccountState", DropTrackerConfig::syncAccountState),
        setting("Advanced", "uploadCharacterModel", DropTrackerConfig::uploadCharacterModel),
        setting("Advanced", "showSidePanel", DropTrackerConfig::showSidePanel),
        setting("Advanced", "debugLogging", DropTrackerConfig::debugLogging),

        setting("Hidden", "hideWhispers", DropTrackerConfig::hideDMs),
        setting("Hidden", "trackExperience", DropTrackerConfig::trackExperience),
        setting("Hidden", "trackTrawling", DropTrackerConfig::trackTrawling),
        setting("Hidden", "sendLoadoutWithPbs", DropTrackerConfig::sendLoadoutWithPbs),
        setting("Hidden", "eventImportantPopupsOnly", DropTrackerConfig::eventImportantPopupsOnly),
        setting("Hidden", "pollUpdates", DropTrackerConfig::pollUpdates)
    );

    @Inject
    private Gson gson;

    /** Last snapshot hash sent this session, per account hash. */
    private final Map<Long, String> lastSent = new HashMap<>();
    @Nullable
    private ScheduledFuture<?> pending;

    /** Game state hook: a snapshot shortly after each login. */
    public void onGameStateChanged(GameState state) {
        if (state == GameState.LOGGED_IN) {
            schedule(LOGIN_DELAY_SECONDS);
        }
    }

    /** Config hook: a snapshot once the player stops changing settings. */
    public void onConfigChanged(String group, String key) {
        if (DropTrackerConfig.GROUP.equals(group) && !EXCLUDED.contains(key)) {
            schedule(CHANGE_DEBOUNCE_SECONDS);
        } else if (RuneLiteConfig.GROUP_NAME.equals(group) && "loottrackerplugin".equals(key)) {
            schedule(CHANGE_DEBOUNCE_SECONDS);
        }
    }

    public synchronized void reset() {
        if (pending != null) {
            pending.cancel(false);
            pending = null;
        }
        lastSent.clear();
    }

    private synchronized void schedule(long delaySeconds) {
        if (executor == null) {
            return;
        }
        if (pending != null) {
            pending.cancel(false);
        }
        pending = executor.schedule(() -> clientThread.invokeLater(this::sendIfChanged),
            delaySeconds, TimeUnit.SECONDS);
    }

    /** Client thread: reads the chatbox varbit and the local player. */
    private void sendIfChanged() {
        if (client.getGameState() != GameState.LOGGED_IN || client.getLocalPlayer() == null) {
            return;
        }
        long account = client.getAccountHash();
        String playerName = getPlayerName();
        if (account == -1 || playerName == null || playerName.isEmpty()) {
            return;
        }
        JsonObject env = new JsonObject();
        env.addProperty("runelite_version", RuneLiteProperties.getVersion());
        env.addProperty("resizable", client.isResized());
        env.addProperty("chatbox_transparent",
            client.isResized() && client.getVarbitValue(VarbitID.CHATBOX_TRANSPARENCY) == 1);
        env.addProperty("loot_tracker_enabled",
            !"false".equals(configManager.getConfiguration(RuneLiteConfig.GROUP_NAME, "loottrackerplugin")));
        env.addProperty("custom_api_endpoint", !config.customApiEndpoint().isEmpty());

        JsonObject snapshot = build(config,
            key -> configManager.getConfiguration(DropTrackerConfig.GROUP, key) != null, env);
        String hash = sha256(gson.toJson(snapshot));
        synchronized (this) {
            if (hash.equals(lastSent.get(account))) {
                return;
            }
            lastSent.put(account, hash);
        }
        snapshot.addProperty("hash", hash.substring(0, 16));
        String json = gson.toJson(snapshot);
        if (json.length() > MAX_DESCRIPTION) {
            // Can't happen with today's ~2 KB; the test pins the headroom.
            log.warn("Config snapshot too large to send ({} chars)", json.length());
            return;
        }

        CustomWebhookBody webhook = createWebhookBody(playerName + " plugin configuration");
        CustomWebhookBody.Embed embed = createEmbed("Plugin configuration", "config_snapshot");
        embed.setDescription(json);
        webhook.getEmbeds().add(embed);
        DebugLogger.log("[ConfigSnapshot] sending snapshot hash=" + hash.substring(0, 16)
            + " size=" + json.length());
        sendData(webhook, SubmissionType.CONFIG_SNAPSHOT);
    }

    /**
     * The snapshot body: settings grouped by config section (hidden ones under
     * "Hidden"), the keys the player has changed from their defaults, and
     * the client environment. Values come through the config proxy, so a
     * setting the player never touched reports its default.
     */
    static JsonObject build(DropTrackerConfig config, Predicate<String> customized, JsonObject env) {
        Map<String, JsonObject> sections = new LinkedHashMap<>();
        for (String section : new String[]{"Tracking", "Screenshots", "Events", "Advanced", "Hidden"}) {
            sections.put(section, new JsonObject());
        }
        JsonArray changed = new JsonArray();
        for (Setting setting : SETTINGS) {
            Object value;
            try {
                value = setting.read.apply(config);
            } catch (RuntimeException e) {
                continue;
            }
            JsonObject target = sections.computeIfAbsent(setting.section, s -> new JsonObject());
            if (value instanceof Boolean) {
                target.addProperty(setting.key, (Boolean) value);
            } else if (value instanceof Number) {
                target.addProperty(setting.key, (Number) value);
            } else if (value instanceof Enum) {
                target.addProperty(setting.key, ((Enum<?>) value).name());
            } else if (value != null) {
                target.addProperty(setting.key, value.toString());
            }
            if (customized.test(setting.key)) {
                changed.add(setting.key);
            }
        }
        JsonObject settings = new JsonObject();
        sections.forEach((name, values) -> {
            if (values.size() > 0) {
                settings.add(name, values);
            }
        });
        JsonObject snapshot = new JsonObject();
        snapshot.addProperty("v", FORMAT_VERSION);
        snapshot.add("settings", settings);
        snapshot.add("customized", changed);
        snapshot.add("env", env);
        return snapshot;
    }

    private static String sha256(String text) {
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256").digest(text.getBytes(StandardCharsets.UTF_8));
            StringBuilder out = new StringBuilder(digest.length * 2);
            for (byte b : digest) {
                out.append(String.format("%02x", b));
            }
            return out.toString();
        } catch (NoSuchAlgorithmException e) {
            return Integer.toHexString(text.hashCode());
        }
    }
}

package io.droptracker.events;

import lombok.AccessLevel;
import lombok.AllArgsConstructor;
import java.lang.ref.WeakReference;
import java.util.*;
import java.util.function.Predicate;

import javax.annotation.Nullable;
import javax.inject.Inject;

import io.droptracker.models.CustomWebhookBody;
import io.droptracker.models.submissions.SubmissionType;
import io.droptracker.service.RecentCombatTracker;
import io.droptracker.util.*;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.*;
import net.runelite.api.gameval.*;
import net.runelite.api.widgets.Widget;
import net.runelite.client.game.*;
import org.apache.commons.lang3.*;
import org.jetbrains.annotations.VisibleForTesting;

/**
 * Tracks local player deaths and submits them to the DropTracker.
 *
 * Invoked manually from DropTrackerPlugin's event subscriptions (handlers in
 * this package are not registered on the RuneLite event bus).
 */
@Slf4j
public class DeathHandler extends BaseEventHandler {

    /** Suppress duplicate submissions if the client fires multiple death events. */
    private static final long DUPLICATE_WINDOW_MS = 5_000;

    private static final String ATTACK_OPTION = "Attack";

    private static final String KILLER_NPC = "npc";
    private static final String KILLER_PLAYER = "player";
    private static final String KILLER_UNKNOWN = "unknown";

    @Inject
    private NPCManager npcManager;

    @Inject
    private ItemManager itemManager;

    @Inject
    private RegionNameRegistry regionNames;

    private long lastDeathAtMs = 0;

    /**
     * The last actor the local player interacted with.
     *
     * Reading {@code localPlayer.getInteracting()} on the death tick is not
     * enough on its own: the interaction is frequently already cleared by then,
     * and it answers the wrong question anyway (who we were attacking, not who
     * was attacking us). Tracking the target as it changes gives a candidate
     * that survives the death tick.
     *
     * Weakly held so a despawning actor can still be collected; the referent
     * may be null.
     */
    private WeakReference<Actor> lastTarget = new WeakReference<>(null);

    /**
     * The engagements of the last few ticks, in both directions.
     *
     * <p>The live scan below can only ever find an actor that is still targeting
     * us on the death tick, and on a great many deaths nothing is: the game drops
     * an NPC's target as soon as that target dies, instanced bosses despawn with
     * the instance, and in a group the boss has already moved on to whoever is
     * still alive. This is the memory that lets those deaths still be attributed.
     */
    @VisibleForTesting
    final RecentCombatTracker recentCombat = new RecentCombatTracker();

    @Override
    public boolean isEnabled() {
        return config.deathEmbeds();
    }

    public void onInteractingChanged(InteractingChanged event) {
        Player localPlayer = client.getLocalPlayer();
        if (localPlayer == null) {
            return;
        }

        Actor source = event.getSource();
        Actor target = event.getTarget();
        int tick = client.getTickCount();

        if (source == localPlayer) {
            // Outbound: what we are attacking.
            if (target != null) {
                if (target.getCombatLevel() > 0) {
                    lastTarget = new WeakReference<>(target);
                }
                recentCombat.recordAttacking(target, tick);
            } else {
                recentCombat.endAttacking(null, tick);
            }
            return;
        }

        // Inbound: what is attacking us. This half of the signal used to be
        // thrown away, even though it is the one that actually answers "who
        // killed me" — the outbound target only says who we were fighting.
        if (target == localPlayer) {
            recentCombat.recordAttackedBy(source, tick);
        } else if (source != null) {
            // It turned away from us (or onto someone else). Remembering *when*
            // it disengaged is what makes a boss that dropped its target on the
            // death tick rank ahead of every older candidate.
            recentCombat.endAttackedBy(source, tick);
        }
    }

    public void onActorDeath(ActorDeath event) {
        Player localPlayer = client.getLocalPlayer();
        boolean self = localPlayer != null && event.getActor() == localPlayer;

        try {
            if (!self || !isEnabled() || !plugin.isTracking) {
                return;
            }

            long now = System.currentTimeMillis();
            if (now - lastDeathAtMs < DUPLICATE_WINDOW_MS) {
                return;
            }
            lastDeathAtMs = now;

            submitDeath(localPlayer);
        } finally {
            // Clear the tracked target once it is dead — ours or theirs — so a
            // later death cannot be attributed to a corpse.
            if (self || event.getActor() == lastTarget.get()) {
                lastTarget = new WeakReference<>(null);
            }
            if (self) {
                // Respawning starts a new fight; nothing before the death can
                // explain the next one.
                recentCombat.clear();
            } else {
                recentCombat.forget(event.getActor());
            }
        }
    }

    private void submitDeath(Player localPlayer) {
        WorldPoint location = currentLocation(localPlayer);
        Killer killer = identifyKiller(localPlayer, location);
        boolean pk = killer != null && killer.isPlayer();
        boolean npc = killer != null && killer.isNpc();

        String playerName = getPlayerName();
        if (playerName == null) {
            return;
        }
        CustomWebhookBody webhook = createWebhookBody(playerName + " has died!");
        CustomWebhookBody.Embed embed = createEmbed(playerName + " has died!", "death");

        // LinkedHashMap: field order is the order they appear in the embed, and
        // addFields turns a null or blank value into the literal "N/A", so a
        // value we do not have must be left out rather than added empty.
        Map<String, Object> fieldData = new LinkedHashMap<>();

        String killerName = killer != null
                ? NpcUtilities.canonicalizeSpecialSource(killer.getName())
                : null;
        if (killerName != null) {
            fieldData.put("source", killerName);
        }
        fieldData.put("killer_type", pk ? KILLER_PLAYER : npc ? KILLER_NPC : KILLER_UNKNOWN);
        fieldData.put("is_pvp", pk);

        if (killer != null) {
            if (npc && killer.getNpcId() != null) {
                fieldData.put("killer_npc_id", killer.getNpcId());
            }
            if (killer.getCombatLevel() > 0) {
                fieldData.put("killer_combat_level", killer.getCombatLevel());
            }
        }

        if (location != null) {
            int regionId = location.getRegionID();
            fieldData.put("region_id", regionId);

            RegionNameRegistry.Area area = regionNames.lookup(regionId);
            if (area != null) {
                fieldData.put("region_name", area.getName());
                if (area.getType() != null) {
                    fieldData.put("region_type", area.getType());
                }
                // "location" is what the notification embed renders and what
                // the custom-embed {location} token has always been documented
                // to be ("Catacombs of Kourend"). Leaving it out when the
                // region is unnamed lets the server fall back to showing the
                // bare region id rather than printing coordinates at people.
                fieldData.put("location", area.getName());
            }

            // The raw point still travels, just no longer as "location".
            fieldData.put("coordinates", location.getX() + "," + location.getY() + "," + location.getPlane());
            fieldData.put("plane", location.getPlane());
            fieldData.put("instanced", isInstance(localPlayer));
        }

        // The server decides whether the death cost anything and what it cost
        // (utils/death_regions, utils/death_valuation), from what only the
        // client can see. Read on the death tick, while the containers still
        // hold what the player died with.
        fieldData.put("account_type_id", client.getVarbitValue(VarbitID.IRONMAN));
        Widget pestControl = client.getWidget(InterfaceID.PestStatusOverlay.PEST_STATUS_PORT2);
        fieldData.put("pest_control", pestControl != null && !pestControl.isHidden());
        fieldData.put("skulled", localPlayer.getSkullIcon() != SkullIcon.NONE);
        fieldData.put("protect_item", client.isPrayerActive(Prayer.PROTECT_ITEM)
                || client.isPrayerActive(Prayer.RP_PROTECT_ITEM));
        fieldData.put("carried_inv", carried(net.runelite.api.gameval.InventoryID.INV));
        fieldData.put("carried_worn", carried(net.runelite.api.gameval.InventoryID.WORN));

        addFields(embed, fieldData);
        webhook.getEmbeds().add(embed);

        sendData(webhook, SubmissionType.DEATH);
    }

    /**
     * A container as {@code id:quantity:unitPrice,...}. The price is RuneLite's
     * GE price, else the store price untradeables are protected by.
     */
    private String carried(int containerId) {
        ItemContainer container = client.getItemContainer(containerId);
        StringBuilder out = new StringBuilder();
        for (Item item : container != null ? container.getItems() : new Item[0]) {
            if (item.getId() < 0 || item.getQuantity() <= 0) {
                continue;
            }
            long price;
            try {
                price = itemManager.getItemPrice(item.getId());
                if (price <= 0) {
                    price = Math.max(0, itemManager.getItemComposition(item.getId()).getPrice());
                }
            } catch (RuntimeException e) {
                price = 0;
            }
            out.append(out.length() > 0 ? "," : "").append(item.getId()).append(':')
                .append(item.getQuantity()).append(':').append(price);
        }
        return out.toString();
    }

    /**
     * The local player's position, corrected for instances.
     *
     * Inside an instance {@code getWorldLocation()} returns a point in template
     * space, whose region id belongs to whichever chunk the instance was built
     * from — so every raid, Gauntlet, Inferno and Nightmare death used to
     * report a region that had nothing to do with where it happened.
     */
    @Nullable
    private WorldPoint currentLocation(Player localPlayer) {
        if (localPlayer == null) {
            return null;
        }
        WorldView worldView = localPlayer.getWorldView();
        if (worldView != null && worldView.isInstance()) {
            return WorldPoint.fromLocalInstance(client, localPlayer.getLocalLocation(), worldView.getPlane());
        }
        return localPlayer.getWorldLocation();
    }

    private boolean isInstance(Player localPlayer) {
        WorldView worldView = localPlayer != null ? localPlayer.getWorldView() : null;
        return worldView != null && worldView.isInstance();
    }

    @Nullable
    private static String actorName(@Nullable Actor actor) {
        return actor != null ? RecentCombatTracker.cleanName(actor.getName()) : null;
    }

    /**
     * @return who most likely killed us, or null when the death cannot be
     *         attributed at all (poison, falling damage, an attacker we never
     *         saw engage us).
     */
    @Nullable
    @VisibleForTesting
    Killer identifyKiller(Player localPlayer, @Nullable WorldPoint location) {
        boolean pvpEnabled = isPvpEnabled(location);

        Actor live = findLiveKiller(localPlayer, pvpEnabled);
        if (live != null) {
            return Killer.of(live);
        }

        // Nothing is targeting us any more. Fall back to who was, moments ago:
        // by the time ActorDeath fires the interaction is usually already gone,
        // which is exactly how a death ends up with no source on it at all.
        return recentCombat.mostLikelyKiller(client.getTickCount(), pvpEnabled)
                .map(Killer::of)
                .orElse(null);
    }

    /** The Dink-style scan: an actor that is still targeting us right now. */
    @Nullable
    private Actor findLiveKiller(Player localPlayer, boolean pvpEnabled) {
        Predicate<Actor> interactingWithUs = actor -> isInteractingWith(localPlayer, actor);

        // Fast path: whatever we were last engaged with, if it is still a
        // plausible killer.
        Actor recentTarget = lastTarget.get();
        if (isLikelyKiller(localPlayer, recentTarget, pvpEnabled)) {
            return recentTarget;
        }

        WorldView worldView = worldView(localPlayer);
        if (worldView == null) {
            return null;
        }

        // A player can only have killed us where PvP is possible. Prefer one
        // who is not a friend/clanmate, since those are usually bystanders.
        if (pvpEnabled) {
            Optional<? extends Player> pker = worldView.players().stream()
                    .filter(interactingWithUs)
                    .min(pkComparator(localPlayer));
            if (pker.isPresent()) {
                return pker.get();
            }
        }

        // Otherwise the best-ranked NPC currently attacking us.
        return worldView.npcs().stream()
                .filter(interactingWithUs)
                .filter(npc -> isValidKiller(npc.getTransformedComposition()))
                .min(npcComparator(localPlayer))
                .orElse(null);
    }

    /**
     * The world view to search for candidates.
     *
     * <p>The local player's own view rather than the top level one: content that
     * runs in a nested world view keeps its NPCs there, and scanning the top
     * level would find none of them.
     */
    @Nullable
    private WorldView worldView(@Nullable Player localPlayer) {
        WorldView own = localPlayer != null ? localPlayer.getWorldView() : null;
        return own != null ? own : client.getTopLevelWorldView();
    }

    private boolean isPvpEnabled(@Nullable WorldPoint location) {
        // LMS, Castle Wars, Soul Wars, Clan Wars and the PvP Arena: the other
        // players are the opponents there, outside the Wilderness too.
        if ((location != null && DeathRegions.isPvpMinigame(location.getRegionID()))
                || client.getWorldType().contains(WorldType.PVP_ARENA)) {
            return true;
        }
        if (isPvpSafeZone()) {
            // Bank/lobby areas of PvP worlds and Deadman — nobody can be
            // attacked here, so no bystander should be blamed.
            return false;
        }
        return client.getVarbitValue(VarbitID.INSIDE_WILDERNESS) > 0
                || client.getWorldType().contains(WorldType.PVP)
                || client.getWorldType().contains(WorldType.DEADMAN);
    }

    private boolean isPvpSafeZone() {
        // PVPW_SAFE, not SAFEZONE: SAFEZONE is shown all over the Wilderness,
        // which stopped every player kill being attributed from 6.0.3.
        Widget widget = client.getWidget(InterfaceID.PvpIcons.PVPW_SAFE);
        return widget != null && !widget.isHidden();
    }

    /** Whether the actor is alive and targeting the local player. */
    private static boolean isInteractingWith(Player localPlayer, @Nullable Actor actor) {
        return actor != null
                && actor != localPlayer
                && !actor.isDead()
                && actor.getInteracting() == localPlayer;
    }

    /** Whether an NPC is a plausible killer rather than scenery or a pet. */
    private static boolean isValidKiller(@Nullable NPCComposition composition) {
        return composition != null
                && composition.isInteractible()
                && !composition.isFollower()
                && composition.getCombatLevel() > 0;
    }

    private static boolean isLikelyKiller(Player localPlayer, @Nullable Actor actor, boolean pvpEnabled) {
        if (!isInteractingWith(localPlayer, actor)) {
            return false;
        }

        if (actor instanceof Player) {
            Player other = (Player) actor;
            return pvpEnabled && !other.isClanMember() && !other.isFriend() && !other.isFriendsChatMember();
        }

        if (actor instanceof NPC) {
            NPCComposition composition = ((NPC) actor).getTransformedComposition();
            return isValidKiller(composition) && ArrayUtils.contains(composition.getActions(), ATTACK_OPTION);
        }

        return false;
    }

    /**
     * Orders candidate NPCs by how likely each is to be the killer, best first
     * (so {@code Stream#min} picks the winner).
     */
    private Comparator<NPC> npcComparator(Player localPlayer) {
        return Comparator
                .comparing(
                        NPC::getTransformedComposition,
                        Comparator.nullsFirst(
                                Comparator
                                        // named in the hitpoints UI — i.e. something the game
                                        // itself treats as a notable opponent
                                        .comparing((NPCComposition c) -> c.getStringValue(ParamID.NPC_HP_NAME),
                                                Comparator.comparing(StringUtils::isNotEmpty))
                                        .thenComparing(c -> ArrayUtils.contains(c.getActions(), ATTACK_OPTION))
                                        .thenComparingInt(NPCComposition::getCombatLevel)
                                        .thenComparingInt(NPCComposition::getSize)
                                        .thenComparing(NPCComposition::isMinimapVisible)
                                        .thenComparing(c -> npcManager != null ? npcManager.getHealth(c.getId()) : null,
                                                Comparator.nullsFirst(Comparator.naturalOrder()))))
                .thenComparingInt(npc -> -distanceTo(localPlayer, npc))
                .reversed();
    }

    /**
     * Orders candidate players by how likely each is to be the killer, best
     * first. Friends and clanmates rank last; a similar combat level and
     * proximity rank higher.
     */
    private static Comparator<Player> pkComparator(Player localPlayer) {
        return Comparator
                .comparing(Player::isClanMember)
                .thenComparing(Player::isFriend)
                .thenComparing(Player::isFriendsChatMember)
                .thenComparingInt(p -> Math.abs(localPlayer.getCombatLevel() - p.getCombatLevel()))
                .thenComparingInt(p -> -p.getCombatLevel())
                .thenComparing(p -> p.getOverheadIcon() == null)
                .thenComparing(p -> p.getTeam() == localPlayer.getTeam())
                .thenComparingInt(p -> distanceTo(localPlayer, p));
    }

    private static int distanceTo(Player localPlayer, Actor other) {
        if (localPlayer.getLocalLocation() == null || other.getLocalLocation() == null) {
            return Integer.MAX_VALUE;
        }
        return localPlayer.getLocalLocation().distanceTo(other.getLocalLocation());
    }

    /**
     * Who killed us, as a snapshot rather than a live scene reference.
     *
     * <p>The fallback path names actors that have already despawned by the time
     * the submission is built, so the attribution cannot be an {@link Actor}.
     */
    @VisibleForTesting
    @AllArgsConstructor(access = AccessLevel.PRIVATE)
    static final class Killer {

        private final String name;
        private final Integer npcId;
        private final int combatLevel;
        private final boolean player;
        private final boolean npc;

        static Killer of(Actor actor) {
            if (actor instanceof NPC) {
                NPC killerNpc = (NPC) actor;
                String name = actorName(killerNpc);
                if (name == null) {
                    // Some instanced NPCs report no name until their composition
                    // is transformed; without this the embed would carry an NPC
                    // id and no source at all.
                    NPCComposition composition = killerNpc.getTransformedComposition();
                    name = composition != null ? RecentCombatTracker.cleanName(composition.getName()) : null;
                }
                return new Killer(name, killerNpc.getId(), killerNpc.getCombatLevel(), false, true);
            }
            return new Killer(actorName(actor), null, actor.getCombatLevel(), actor instanceof Player, false);
        }

        static Killer of(RecentCombatTracker.Engagement engagement) {
            return new Killer(engagement.getName(), engagement.getNpcId(), engagement.getCombatLevel(),
                    engagement.isPlayer(), engagement.isNpc());
        }

        @Nullable
        String getName() {
            return name;
        }

        @Nullable
        Integer getNpcId() {
            return npcId;
        }

        int getCombatLevel() {
            return combatLevel;
        }

        boolean isPlayer() {
            return player;
        }

        boolean isNpc() {
            return npc;
        }
    }
}

package io.droptracker.events;

import java.util.*;
import java.util.regex.*;

import io.droptracker.models.CustomWebhookBody;
import io.droptracker.models.submissions.SubmissionType;
import lombok.extern.slf4j.Slf4j;

/**
 * Tracks achievement diary completions via the game-message announcement, e.g.
 * "Congratulations! You have completed all of the easy tasks in the Ardougne area."
 *
 * Invoked manually from DropTrackerPlugin's event subscriptions (handlers in
 * this package are not registered on the RuneLite event bus).
 */
@Slf4j
public class DiaryHandler extends BaseEventHandler {

    private static final Pattern DIARY_COMPLETION_PATTERN = Pattern.compile(
        "Congratulations! You have completed all of the (?<tier>easy|medium|hard|elite) tasks in (?:the )?(?<area>.+?) area",
        Pattern.CASE_INSENSITIVE
    );

    @Override
    public boolean isEnabled() {
        return config.diaryEmbeds();
    }

    public void onGameMessage(String message) {
        if (!isEnabled() || !plugin.isTracking || message == null) {
            return;
        }

        Matcher matcher = DIARY_COMPLETION_PATTERN.matcher(message);
        if (!matcher.find()) {
            return;
        }

        String tier = ucFirst(matcher.group("tier"));
        String area = matcher.group("area").trim();

        String playerName = getPlayerName();
        if (playerName == null) {
            return;
        }
        CustomWebhookBody webhook = createWebhookBody(playerName + " completed an achievement diary!");
        CustomWebhookBody.Embed embed = createEmbed(playerName + " completed the " + tier + " " + area + " diary!", "diary");

        Map<String, Object> fieldData = new HashMap<>();
        fieldData.put("diary_name", area);
        fieldData.put("diary_tier", tier);
        addFields(embed, fieldData);
        webhook.getEmbeds().add(embed);

        sendData(webhook, SubmissionType.DIARY);
    }

    private static String ucFirst(String text) {
        if (text == null || text.isEmpty()) {
            return text;
        }
        return Character.toUpperCase(text.charAt(0)) + text.substring(1).toLowerCase();
    }
}

package io.droptracker.events;

import java.util.*;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.*;

import javax.inject.Inject;

import com.google.common.cache.*;

import io.droptracker.models.CustomWebhookBody;
import io.droptracker.models.submissions.Drop;
import io.droptracker.service.*;
import io.droptracker.util.*;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.events.*;
import net.runelite.client.game.*;
import net.runelite.client.plugins.loottracker.LootReceived;
import net.runelite.http.api.loottracker.LootRecordType;

@Slf4j
public class DropHandler extends BaseEventHandler {

    @Inject
    private KCService kcService;

    @Inject
    private ItemManager itemManager;

    @Inject
    private EventNotificationService eventNotificationService;

    /** One in-flight untradeable-list reload at a time: a busy player killing
     *  through an outage would otherwise queue a fetch per drop. */
    private final AtomicBoolean untradeableReloadInFlight = new AtomicBoolean(false);

    /**
     * Short-lived record of boss loot already submitted, keyed by
     * accountHash|canonicalSource|itemSignature. RuneLite fires more than one
     * loot event for multi-part / server-loot bosses (e.g. a granular
     * NpcLootReceived AND a generic LootReceived for Grotesque Guardians), so
     * the same kill reaches processDropEvent twice with identical items. We
     * submit the first and drop the rest within the window. The window is far
     * shorter than the minimum time to re-kill any of these bosses, and this is
     * scoped to boss sources only (isMultiPathLootSource), so ordinary NPCs that
     * are legitimately multi-killed in one tick are never de-duplicated.
     */
    private static final Cache<String, Boolean> recentBossLoot = CacheBuilder.newBuilder()
            .expireAfterWrite(5, TimeUnit.SECONDS)
            .maximumSize(256L)
            .build();

    /** RuneLite's name for opened PvP loot keys; the server files these as PvP loot. */
    static final String LOOT_CHEST = "Loot Chest";

    /** Loot keys already sent, by container and contents: reopening the chest shows the
     *  same unclaimed keys again. Five keys at most are held, so a few openings' worth. */
    private final Cache<String, Boolean> sentLootKeys = CacheBuilder.newBuilder()
            .maximumSize(25L)
            .build();

    /*
     * NOTE: These handlers are NOT registered on the RuneLite event bus — they are
     * invoked manually by DropTrackerPlugin's own @Subscribe methods, which also
     * dispatch KCService. Do not call KCService from here, or kill counts get
     * incremented twice per event.
     */
	public void onNpcLootReceived(NpcLootReceived event) {
		if (!plugin.isTracking) {
			return;
		}
		NPC npc = event.getNpc();
		Collection<ItemStack> items = event.getItems();
		processDropEvent(npc.getName(), "npc", LootRecordType.NPC, items);
	}

	public void onPlayerLootReceived(PlayerLootReceived playerLootReceived) {
		if (!plugin.isTracking) {
			return;
		}
		Player victim = playerLootReceived.getPlayer();
		processDropEvent(victim.getName(), "pvp", LootRecordType.PLAYER, playerLootReceived.getItems(), pvpContext(victim));
	}

	/**
	 * The Wilderness loot chest opened (interface 742): one item container per held
	 * loot key, 558-562. RuneLite's own "Loot Chest" event only fires with its Loot
	 * Tracker plugin on, and not at all while any key is left in the inventory, so
	 * about half of PKers never sent their key loot. Each key's contents go once.
	 */
	public void onLootChestOpened() {
		if (!plugin.isTracking) {
			return;
		}
		for (List<ItemStack> key : unsentLootKeys()) {
			processDropEvent(LOOT_CHEST, "pvp", LootRecordType.EVENT, key);
		}
	}

	/** The chest's keys not sent yet, each marked sent. */
	List<List<ItemStack>> unsentLootKeys() {
		List<List<ItemStack>> keys = new ArrayList<>();
		for (int id = 558; id <= 562; id++) {
			ItemContainer container = client.getItemContainer(id);
			if (container == null) {
				continue;
			}
			List<ItemStack> items = new ArrayList<>();
			for (Item item : container.getItems()) {
				if (item.getId() > 0 && item.getQuantity() > 0) {
					items.add(new ItemStack(item.getId(), item.getQuantity()));
				}
			}
			String key = id + "|" + ItemStacks.signature(items);
			if (!items.isEmpty() && sentLootKeys.getIfPresent(key) == null) {
				sentLootKeys.put(key, Boolean.TRUE);
				keys.add(items);
			}
		}
		return keys;
	}

	/** Whom and where, sent with every item of a PvP kill so the server can file it (6.1.9). */
	private Map<String, Object> pvpContext(Player victim) {
		Map<String, Object> fields = new HashMap<>();
		fields.put("victim_combat_level", victim.getCombatLevel());
		fields.put("world", client.getWorld());
		Player local = client.getLocalPlayer();
		WorldPoint point = local != null ? local.getWorldLocation() : null;
		if (point != null) {
			fields.put("region_id", point.getRegionID());
			if (client.getVarbitValue(VarbitID.INSIDE_WILDERNESS) > 0) {
				fields.put("wilderness_level", wildernessLevel(point.getY()));
			}
		}
		return fields;
	}

	/** Eight tiles per level: the surface from y=3520, the dungeons below it from y=9920. */
	static int wildernessLevel(int y) {
		return Math.max(1, ((y > 6400 ? y - 9920 : y - 3520) / 8) + 1);
	}

	public void onServerNpcLoot(ServerNpcLoot event) {
		if (!plugin.isTracking) {
			return;
		}
		var comp = event.getComposition();
		log.debug("onServerNpcLoot: processing {} (npcId={})", comp.getName(), comp.getId());
		processDropEvent(comp.getName(), "npc", LootRecordType.NPC, event.getItems());
	}

	public void onLootReceived(LootReceived lootReceived) {
		if (!plugin.isTracking) {
			return;
		}
		/* Opened loot keys are read off the chest itself (onLootChestOpened) */
		if (LOOT_CHEST.equals(lootReceived.getName())) {
			return;
		}
		/* A select few npc loot sources will arrive here, instead of npclootreceived events */
		String npcName = NpcUtilities.getStandardizedSource(lootReceived, plugin);
		if (lootReceived.getType() == LootRecordType.NPC && NpcUtilities.SPECIAL_NPC_NAMES.contains(npcName)) {
			// Remap sub-NPC names to the canonical encounter name. processDropEvent
			// also canonicalises, but doing it here keeps the pre-canonical name
			// out of downstream logic and mirrors the historical behaviour.
			npcName = NpcUtilities.canonicalizeSpecialSource(npcName);

			processDropEvent(npcName, "npc", LootRecordType.NPC, lootReceived.getItems());
			return;
		}
		if (lootReceived.getType() != LootRecordType.EVENT && lootReceived.getType() != LootRecordType.PICKPOCKET) {
			return;
		}
		processDropEvent(npcName, "other", lootReceived.getType(), lootReceived.getItems());
	}

	/**
	 * Entry point for activity loot that never fires a RuneLite loot event
	 * (deep sea trawling catches, Pyramid Plunder sceptres).
	 * The source name must exist in the server's npc_list, or the submission
	 * is rejected server-side.
	 */
	public void onActivityLoot(String sourceName, Collection<ItemStack> items) {
		if (!plugin.isTracking || items.isEmpty()) {
			return;
		}
		processDropEvent(sourceName, "other", LootRecordType.EVENT, items);
	}

    private void processDropEvent(String rawNpcName, String sourceType, LootRecordType lootRecordType, Collection<ItemStack> items) {
		processDropEvent(rawNpcName, sourceType, lootRecordType, items, null);
	}

    private void processDropEvent(String rawNpcName, String sourceType, LootRecordType lootRecordType, Collection<ItemStack> items, Map<String, Object> extraFields) {
		final Collection<ItemStack> finalItems = new ArrayList<>(items);
		if (!plugin.isTracking) {
			return;
		}
		// Collapse every loot path to one canonical boss name (e.g. "Dusk" ->
		// "Grotesque Guardians") so the record, the KC lookup and the dedup key
		// all agree regardless of which RuneLite event delivered the kill.
		final String npcName = NpcUtilities.canonicalizeSpecialSource(rawNpcName);
		// Cross-handler de-duplication: a multi-part / server-loot boss fires
		// more than one loot event per kill, so the same items reach here twice.
		// Submit the first, drop identical repeats within the window. Scoped to
		// boss sources only, so normal per-death AoE multi-kills are unaffected.
		if (NpcUtilities.isMultiPathLootSource(npcName)) {
			String dedupKey = getAccountHash() + "|" + npcName + "|" + ItemStacks.signature(finalItems);
			if (recentBossLoot.getIfPresent(dedupKey) != null) {
				log.debug("Suppressing duplicate loot submission for {} (already submitted this kill)", npcName);
				return;
			}
			recentBossLoot.put(dedupKey, Boolean.TRUE);
		}
		if (NpcUtilities.LONG_TICK_NPC_NAMES.contains(npcName)){
			plugin.ticksSinceNpcDataUpdate -= 30;
		}
        plugin.lastDrop = new Drop(npcName, lootRecordType, finalItems);
		/* These lists are normally loaded off-thread at startup. When that
		   failed, this used to fetch them INLINE — but processDropEvent runs
		   on the game client thread (straight off @Subscribe), and the fetch is
		   a synchronous OkHttp call with a 5s connect / 10s read timeout. So
		   the one situation where the list is missing (the server was
		   unreachable at startup, and probably still is) froze the client for
		   up to 15 seconds on EVERY drop — and since a failed fetch returns
		   null, the guard never cleared and it happened again on the next one.
		   Kick a reload off-thread instead; the consumer loop below already
		   null-guards both lists, so this drop simply goes un-flagged. */
		if ((plugin.valuedItemIds == null || plugin.untradeableItemIds == null)
				&& executor != null && untradeableReloadInFlight.compareAndSet(false, true)) {
			executor.submit(() -> {
				try {
					if (plugin.valuedItemIds == null) {
						plugin.valuedItemIds = api.getValuedUntradeables();
					}
					if (plugin.untradeableItemIds == null) {
						plugin.untradeableItemIds = api.getNotableUntradeables();
					}
				} catch (Exception e) {
					log.debug("Untradeable list reload failed: {}", e.getMessage());
				} finally {
					untradeableReloadInFlight.set(false);
				}
			});
		}
		/* Items required by one of the player's active events (from the last
		/event_state snapshot) are always screenshotted for proof — this
		overrides the "Screenshot untradeables" toggle. API users only:
		webhook-only clients never poll event state, so their coverage is
		whatever the toggle + notable-untradeables list provide. */
		final Set<Integer> eventItemIds = config.useApi()
			? eventNotificationService.getEventScreenshotItemIds()
			: Collections.emptySet();
		final AtomicReference<Boolean> untradeableScreenshot = new AtomicReference<>(false);
		clientThread.invokeLater(() -> {
			// Gather all game state info needed
			List<ItemStack> stackedItems = new ArrayList<>(ItemStacks.stack(finalItems));
			String localPlayerName = getPlayerName();
			if (localPlayerName == null) {
				/* No identity, no submission: the drop cannot be attributed to
				   anyone, and this bails before the screenshot work below. */
				return;
			}
			AtomicLong totalValue = new AtomicLong(0);
			List<CustomWebhookBody.Embed> embeds = new ArrayList<>();
			AtomicLong singleValue = new AtomicLong(0);

			for (ItemStack item : stackedItems) {
				int itemId = item.getId();
				/* Check if the itemId exists in the valued list we obtained */
				if (plugin.valuedItemIds != null && plugin.valuedItemIds.contains(itemId)) {
					untradeableScreenshot.set(true);
				} else if (config.screenshotUntradeables() && plugin.untradeableItemIds != null
						&& plugin.untradeableItemIds.contains(itemId)) {
					/* Notable untradeable (0gp) drop — toggle-gated screenshot */
					untradeableScreenshot.set(true);
				} else if (eventItemIds.contains(itemId)) {
					/* Event-required item — forced for proof, regardless of toggles */
					untradeableScreenshot.set(true);
				}
				int qty = item.getQuantity();
				long price = itemManager.getItemPrice(itemId);
				ItemComposition itemComposition = itemManager.getItemComposition(itemId);
				totalValue.addAndGet(qty * price);
				singleValue.addAndGet(price);
				CustomWebhookBody.Embed itemEmbed = createEmbed(localPlayerName + " received some drops:", "drop");
				itemEmbed.setImage(plugin.itemImageUrl(itemId));
				Map<String, Object> fieldData = new HashMap<>();
				fieldData.put("source_type", sourceType);
				fieldData.put("item", itemComposition.getName());
				fieldData.put("id", itemComposition.getId());
				fieldData.put("quantity", qty);
				fieldData.put("value", price);
				fieldData.put("source", npcName);

				if (npcName != null) {
					Integer killCount = kcService.getKillCountWithStorage(lootRecordType, npcName);
					fieldData.put("killcount", killCount != null ? killCount : 0);
				}
				if (extraFields != null) {
					fieldData.putAll(extraFields);
				}

				addFields(itemEmbed, fieldData);
				embeds.add(itemEmbed);
			}

			// Now do the heavy work off the client thread
			executor.submit(() -> {
				try {
					CustomWebhookBody customWebhookBody = createWebhookBody(localPlayerName + " received some drops:");
					customWebhookBody.getEmbeds().addAll(embeds);

					if (!customWebhookBody.getEmbeds().isEmpty()) {
						long valueToSend = totalValue.get();
						Boolean valueModified = untradeableScreenshot.get();
						sendData(customWebhookBody, valueToSend, singleValue.get(), valueModified);
					}
				} catch (Exception e) {
					log.error("Error processing drop event", e);
				}
			});
		});
	}

}

package io.droptracker.events;

import com.google.common.collect.ImmutableSet;
import com.google.gson.Gson;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;
import net.runelite.api.events.*;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.util.QuantityFormatter;
import org.jetbrains.annotations.VisibleForTesting;

import io.droptracker.models.CustomWebhookBody;
import io.droptracker.models.api.GroupConfig;
import io.droptracker.models.submissions.SubmissionType;

import javax.inject.*;
import java.util.*;
import java.util.concurrent.*;

import static net.runelite.api.Experience.MAX_REAL_LEVEL;

@Slf4j
@Singleton
public class ExperienceHandler extends BaseEventHandler {
    public static final int LEVEL_FOR_MAX_XP = Experience.MAX_VIRT_LEVEL + 1; // 127
    static final @VisibleForTesting int INIT_GAME_TICKS = 16; // ~10s
    private static final Set<WorldType> SPECIAL_WORLDS = EnumSet.of(WorldType.PVP_ARENA, WorldType.QUEST_SPEEDRUNNING, WorldType.BETA_WORLD, WorldType.NOSAVE_MODE, WorldType.TOURNAMENT_WORLD, WorldType.DEADMAN, WorldType.SEASONAL, WorldType.HARDCORE_MAIN);
    private static final int SKILL_COUNT = Skill.values().length;
    private static final String COMBAT_NAME = "Combat";
    private static final Set<String> COMBAT_COMPONENTS;

    // Configuration constants
    private static final int XP_INTERVAL_MILLIONS = 1; // Track every 1M XP milestone
    private static final int LEVEL_MIN_VALUE = 1; // Minimum level to track
    private static final int LEVEL_INTERVAL = 1; // Track every level
    private static final boolean TRACK_VIRTUAL_LEVELS = true; // Track levels above 99
    private static final boolean TRACK_COMBAT_LEVEL = true; // Track combat level increases

    // How often (in game ticks) to submit a full XP snapshot while an active
    // event is tracking this player's experience (~2 minutes)
    private static final int PERIODIC_SNAPSHOT_TICKS = 200;

    private final BlockingQueue<String> levelledSkills = new ArrayBlockingQueue<>(SKILL_COUNT + 1);
    private final Set<Skill> xpReached = EnumSet.noneOf(Skill.class);
    private final Map<String, Integer> currentLevels = new HashMap<>();
    private final Map<Skill, Integer> currentXp = new EnumMap<>(Skill.class);
    private final Map<String, Integer> previousLevels = new HashMap<>(); // Track previous levels for level increase calculation
    private final Map<Skill, Integer> lastSnapshotXp = new EnumMap<>(Skill.class);

    private int ticksWaited = 0;
    private int initTicks = 0;
    private int ticksSinceSnapshot = 0;
    private boolean loginSnapshotSent = false;
    private Set<WorldType> specialWorldType = null;

    @Inject
    private ClientThread clientThread;

    @Inject
    private Gson gson;


    @Override
    public boolean isEnabled() {
        return config.trackExperience();
    }

    private void initLevels() {
        for (Skill skill : Skill.values()) {
            int xp = client.getSkillExperience(skill);
            int level = client.getRealSkillLevel(skill); // O(1)
            if (level >= MAX_REAL_LEVEL) {
                level = getLevel(xp);
            }
            currentLevels.put(skill.getName(), level);
            currentXp.put(skill, xp);
        }
        currentLevels.put(COMBAT_NAME, calculateCombatLevel());
        this.initTicks = 0;
        this.specialWorldType = getSpecialWorldTypes();
        log.debug("Initialized current skill levels: {}", currentLevels);

        if (!loginSnapshotSent) {
            loginSnapshotSent = true;
            sendXpSnapshot("login");
        }
    }

    public void reset() {
        levelledSkills.clear();
        clientThread.invoke(() -> {
            this.initTicks = 0;
            this.ticksWaited = 0;
            this.ticksSinceSnapshot = 0;
            this.loginSnapshotSent = false;
            xpReached.clear();
            currentXp.clear();
            currentLevels.clear();
            previousLevels.clear();
            lastSnapshotXp.clear();
            this.specialWorldType = null;
        });
    }

    public void onTick() {
        if (this.initTicks > INIT_GAME_TICKS) {
            initLevels();
            return;
        }

        if (currentLevels.size() < SKILL_COUNT) {
            this.initTicks++;
            return;
        }

        // Periodic full-XP snapshot while an active event tracks this player's
        // experience, so xp_target tasks progress without requiring level-ups
        if (++this.ticksSinceSnapshot >= PERIODIC_SNAPSHOT_TICKS) {
            this.ticksSinceSnapshot = 0;
            if (config.useApi()) {
                // rate-limited internally; picks up events activated mid-session
                api.refreshGroupConfigsAsync();
                if (isXpEventTrackingActive()) {
                    sendXpSnapshot("periodic");
                }
            }
        }

        // Handle level ups and XP milestones
        if (!levelledSkills.isEmpty() || !xpReached.isEmpty()) {
            // We wait a couple extra ticks so we can ensure that we process all the levels of the previous tick
            if (++this.ticksWaited > 2) {
                this.ticksWaited = 0;
                // ensure notifier was not disabled during ticks waited
                if (isEnabled()) {
                    attemptNotify();
                } else {
                    levelledSkills.clear();
                    xpReached.clear();
                }
            }
        }
    }

    public void onStatChanged(StatChanged statChange) {
        this.handleStatChange(statChange.getSkill(), statChange.getLevel(), statChange.getXp());
    }

    public void onGameStateChanged(GameStateChanged gameStateChanged) {
        if (gameStateChanged.getGameState() == GameState.LOGIN_SCREEN) {
            // flush session gains before the cached state is cleared
            sendXpSnapshot("logout");
            this.reset();
        } else if (gameStateChanged.getGameState() == GameState.HOPPING) {
            sendXpSnapshot("world_hop");
        } else if (gameStateChanged.getGameState() == GameState.LOGGED_IN && !getSpecialWorldTypes().equals(this.specialWorldType)) {
            // world switched where player may have different level profiles; re-initialize
            this.reset();
        }
    }

    private void handleStatChange(Skill skill, int level, int xp) {
        if (xp <= 0 || level <= 1 || !isEnabled()) return;

        Integer previousXp = currentXp.put(skill, xp);
        if (previousXp == null) {
            return;
        }

        String skillName = skill.getName();
        int virtualLevel = level < MAX_REAL_LEVEL ? level : getLevel(xp); // avoid log(n) query when not needed
        Integer previousLevel = currentLevels.put(skillName, virtualLevel);

        if (previousLevel == null) {
            this.initTicks = INIT_GAME_TICKS; // force init on next tick
            return;
        }

        if (virtualLevel < previousLevel || xp < previousXp) {
            // base skill level should never regress; reset notifier state
            reset();
            return;
        }

        // Check normal skill level up
        checkLevelUp(true, skillName, previousLevel, virtualLevel);

        // Check if xp milestone reached (config-gated; the backend applies each
        // group's own post99_xp_interval on top of this 1M reporting granularity)
        int xpInterval = XP_INTERVAL_MILLIONS * 1_000_000;
        if (config.xpMilestoneEmbeds() && xpInterval > 0 && level >= MAX_REAL_LEVEL && xp > previousXp) {
            int remainder = xp % xpInterval;
            if (remainder == 0 || xp - remainder > previousXp || xp >= Experience.MAX_SKILL_XP) {
                log.debug("Observed XP milestone for {} to {}", skill, xp);
                xpReached.add(skill);
                this.ticksWaited = 0;
            }
        }

        // Skip combat level checking if no level up has occurred
        if (virtualLevel <= previousLevel) {
            // only return if we don't need to initialize combat level for the first time
            if (currentLevels.containsKey(COMBAT_NAME))
                return;
        }

        // Check for combat level increase
        if (COMBAT_COMPONENTS.contains(skillName) && currentLevels.size() >= SKILL_COUNT) {
            int combatLevel = calculateCombatLevel();
            Integer previousCombatLevel = currentLevels.put(COMBAT_NAME, combatLevel);
            checkLevelUp(TRACK_COMBAT_LEVEL, COMBAT_NAME, previousCombatLevel, combatLevel);
        }
    }

    private void checkLevelUp(boolean configEnabled, String skill, Integer previousLevel, int currentLevel) {
        if (previousLevel == null || currentLevel <= previousLevel) {
            log.trace("Ignoring non-level-up for {}: {}", skill, currentLevel);
            return;
        }

        if (!configEnabled) {
            log.trace("Ignoring level up of {} to {} due to disabled config setting", skill, currentLevel);
            return;
        }

        if (!checkLevelInterval(previousLevel, currentLevel, COMBAT_NAME.equals(skill))) {
            log.trace("Ignoring level up of {} from {} to {} that does not align with config interval", skill, previousLevel, currentLevel);
            return;
        }

        if (levelledSkills.offer(skill)) {
            log.debug("Observed level up for {} to {}", skill, currentLevel);

            // Track previous level for level increase calculation
            previousLevels.put(skill, previousLevel);

            // allow more accumulation of level ups into single notification
            this.ticksWaited = 0;
        }
    }

    private void attemptNotify() {
        notifyLevels();
        notifyXp();
    }

    /**
     * True when any of the player's groups has an active event with XP-based
     * tasks, per the API-provided group configs. Requires the API integration.
     */
    private boolean isXpEventTrackingActive() {
        if (!config.useApi() || api == null || api.groupConfigs == null) {
            return false;
        }
        for (GroupConfig groupConfig : api.groupConfigs) {
            if (groupConfig != null && groupConfig.isTrackXpEvents()) {
                return true;
            }
        }
        return false;
    }

    /**
     * Submits a full snapshot of the player's current XP and levels across all
     * skills as an {@code experience_update}. The backend uses these to update
     * stored experience and advance event XP baselines/deltas; they never
     * produce Discord notifications. Sent on login, logout and world-hop, and
     * periodically while an event is tracking this player's XP. Skipped when
     * nothing changed since the last snapshot.
     */
    private void sendXpSnapshot(String reason) {
        if (!isEnabled() || currentXp.size() < SKILL_COUNT) {
            return;
        }
        if (specialWorldType != null && !specialWorldType.isEmpty()) {
            // temporary level profiles (deadman, speedrunning, ...) are not synced
            return;
        }
        if (currentXp.equals(lastSnapshotXp)) {
            return;
        }
        /* Before any state is consumed below: skipping without a name has to
           leave the snapshot pending, not swallow it. The login snapshot is the
           one most likely to land here, since it fires while the RSN may still
           be loading. */
        String playerName = getPlayerName();
        if (playerName == null) {
            return;
        }

        Map<String, List<Integer>> skillsData = new LinkedHashMap<>();
        long totalXp = 0;
        int totalLevel = 0;
        for (Skill skill : Skill.values()) {
            Integer xp = currentXp.get(skill);
            Integer level = currentLevels.get(skill.getName());
            if (xp == null || level == null) {
                return; // not fully initialized yet; a later snapshot will cover it
            }
            skillsData.put(skill.getName().toLowerCase(), Arrays.asList(xp, level));
            totalXp += xp;
            totalLevel += Math.min(level, MAX_REAL_LEVEL);
        }

        Integer combatLevel = currentLevels.get(COMBAT_NAME);

        CustomWebhookBody webhook = createWebhookBody(playerName + " experience update");
        CustomWebhookBody.Embed embed = createEmbed("Experience Update", "experience_update");
        embed.addField("snapshot_reason", reason, true);
        embed.addField("total_level", String.valueOf(totalLevel), true);
        embed.addField("total_xp", String.valueOf(totalXp), true);
        embed.addField("combat_level", String.valueOf(combatLevel != null ? combatLevel : calculateCombatLevel()), true);
        embed.addField("skills_data", gson.toJson(skillsData), false);
        webhook.getEmbeds().add(embed);

        lastSnapshotXp.clear();
        lastSnapshotXp.putAll(currentXp);
        this.ticksSinceSnapshot = 0;

        log.debug("Sending XP snapshot (reason={}, totalXp={})", reason, totalXp);
        sendData(webhook, SubmissionType.EXPERIENCE_UPDATE);
    }

    /**
     * Creates a simplified field data map for level-up submissions.
     * 
     * @param skillsTrainedList list of skill names that were trained
     * @param skillsLeveledList list of skill names that leveled up
     * @param experienceData map containing experience data for relevant skills
     * @return a map containing only the essential fields
     */
    private Map<String, Object> createLevelUpFieldData(List<String> skillsTrainedList, 
                                                      List<String> skillsLeveledList,
                                                      Map<String, Object> experienceData) {
        Map<String, Object> fieldData = new HashMap<>();

        // General player stats
        fieldData.put("total_level", client.getTotalLevel());
        fieldData.put("total_xp", client.getOverallExperience());
        fieldData.put("combat_level", currentLevels.get(COMBAT_NAME));

        // Skills data - flatten to simple fields
        fieldData.put("skills_trained", String.join(",", skillsTrainedList));
        fieldData.put("skills_leveled", String.join(",", skillsLeveledList));

        // Experience data - flatten to individual fields
        for (Map.Entry<String, Object> entry : experienceData.entrySet()) {
            String key = entry.getKey();
            Object value = entry.getValue();

            if (value instanceof Map) {
                @SuppressWarnings("unchecked")
                Map<String, Object> skillData = (Map<String, Object>) value;
                for (Map.Entry<String, Object> skillEntry : skillData.entrySet()) {
                    fieldData.put(key + "_" + skillEntry.getKey(), skillEntry.getValue());
                }
            } else {
                fieldData.put(key, value);
            }
        }

        return fieldData;
    }

    private void notifyXp() {
        final int n = xpReached.size();
        if (n == 0) return;

        // Bail before xpReached is cleared, so the milestone survives to the
        // next attempt rather than being lost with the submission.
        String playerName = getPlayerName();
        if (playerName == null) {
            return;
        }

        int interval = XP_INTERVAL_MILLIONS * 1_000_000;
        List<String> milestones = new ArrayList<>(n);

        StringBuilder skillMessage = new StringBuilder();
        boolean first = true;

        for (Skill skill : xpReached) {
            int xp = currentXp.getOrDefault(skill, 0);
            xp -= xp % interval;
            milestones.add(skill.getName());

            if (!first) {
                skillMessage.append(", ");
            }
            first = false;

            skillMessage.append(skill.getName())
                       .append(" to ")
                       .append(QuantityFormatter.formatNumber(xp))
                       .append(" XP");
        }

        Map<String, Object> experienceData = new HashMap<>();
        experienceData.put("xp_milestone_interval", interval);

        for (Skill skill : xpReached) {
            int xp = currentXp.getOrDefault(skill, 0);
            xp -= xp % interval; // Get the milestone XP amount
            String skillName = skill.getName().toLowerCase();
            Map<String, Object> skillData = new HashMap<>();
            skillData.put("xp_milestone", xp);
            skillData.put("xp_total", currentXp.get(skill));
            // Virtual level for nicer embeds server-side (99+ skills only).
            Integer level = currentLevels.get(skill.getName());
            if (level != null) {
                skillData.put("new_level", level);
            }
            experienceData.put(skillName, skillData);
        }

        List<String> skillsLeveled = new ArrayList<>(); // No level ups for XP milestones
        Map<String, Object> fieldData = createLevelUpFieldData(milestones, skillsLeveled, experienceData);

        CustomWebhookBody webhook = createWebhookBody(playerName + " reached an XP milestone!");
        CustomWebhookBody.Embed embed = createEmbed("XP Milestone Reached", "experience_milestone");

        addFields(embed, fieldData);
        webhook.getEmbeds().add(embed);

        xpReached.clear();

        sendData(webhook, SubmissionType.EXPERIENCE_MILESTONE);
    }

    private void notifyLevels() {
        /* For level ups specifically  */
        int n = levelledSkills.size();
        if (n == 0) return;

        // Bail before levelledSkills is drained, for the same reason as notifyXp.
        String playerName = getPlayerName();
        if (playerName == null) {
            return;
        }

        // Prepare level state
        List<String> levelled = new ArrayList<>(n);
        int count = levelledSkills.drainTo(levelled);
        if (count == 0) return;

        Map<String, Integer> lSkills = new HashMap<>(count);
        Map<String, Integer> currentLevels = new HashMap<>(this.currentLevels);

        // Build skill message and collect skills involved
        Set<Skill> skillsInvolved = EnumSet.noneOf(Skill.class);
        StringBuilder skillMessage = new StringBuilder();

        for (int index = 0; index < count; index++) {
            String skill = levelled.get(index);
            if (index > 0) {
                if (count > 2) {
                    skillMessage.append(",");
                }
                skillMessage.append(" ");
                if (index + 1 == count) {
                    skillMessage.append("and ");
                }
            }
            Integer level = currentLevels.get(skill);
            skillMessage.append(skill)
                        .append(" to ")
                        .append(level < LEVEL_FOR_MAX_XP ? level : "Max XP (200M)");
            lSkills.put(skill, level);

            // Add skill to involved skills if it's not combat
            if (!COMBAT_NAME.equals(skill)) {
                for (Skill s : Skill.values()) {
                    if (s.getName().equals(skill)) {
                        skillsInvolved.add(s);
                        break;
                    }
                }
            }
        }

        // Check for combat level increase
        Boolean combatLevelUp = lSkills.remove(COMBAT_NAME) != null;
        Integer combatLevel = currentLevels.get(COMBAT_NAME);
        if (combatLevel == null) {
            combatLevel = calculateCombatLevel();
        }

        // Create skills leveled list and experience data
        List<String> skillsLeveledList = new ArrayList<>();
        List<String> skillsTrainedList = new ArrayList<>();
        Map<String, Object> experienceData = new HashMap<>();

        for (String skill : levelled) {
            if (!COMBAT_NAME.equals(skill)) {
                skillsTrainedList.add(skill);
                skillsLeveledList.add(skill);

                Integer previousLevel = previousLevels.get(skill);
                Integer currentLevel = currentLevels.get(skill);
                if (previousLevel != null && currentLevel != null) {
                    String skillName = skill.toLowerCase();
                    Map<String, Object> skillData = new HashMap<>();
                    skillData.put("level_gained", currentLevel - previousLevel);
                    skillData.put("new_level", currentLevel);

                    // Add XP data if available
                    for (Skill s : Skill.values()) {
                        if (s.getName().equals(skill)) {
                            Integer skillXp = currentXp.get(s);
                            if (skillXp != null) {
                                skillData.put("xp_total", skillXp);
                            }
                            break;
                        }
                    }

                    experienceData.put(skillName, skillData);
                }
            }
        }

        // Handle combat level separately
        if (combatLevelUp != null && combatLevelUp) {
            skillsLeveledList.add("Combat");
            Map<String, Object> combatData = new HashMap<>();
            combatData.put("level_gained", 1); // Assume +1 for combat level increases
            combatData.put("new_level", combatLevel);
            experienceData.put("combat", combatData);
        }

        Map<String, Object> fieldData = createLevelUpFieldData(skillsTrainedList, skillsLeveledList, experienceData);

        // Update combat level if it leveled up
        if (combatLevelUp != null && combatLevelUp) {
            fieldData.put("combat_level", combatLevel);
        }

        CustomWebhookBody webhook = createWebhookBody(playerName + " leveled up!");
        CustomWebhookBody.Embed embed = createEmbed("Level Up!", "level_up");

        addFields(embed, fieldData);
        webhook.getEmbeds().add(embed);

        sendData(webhook, SubmissionType.LEVEL_UP);
    }

    private boolean checkLevelInterval(int previous, int level, boolean skipVirtualCheck) {
        if (level < LEVEL_MIN_VALUE)
            return false;

        if (!skipVirtualCheck && level > MAX_REAL_LEVEL && !TRACK_VIRTUAL_LEVELS)
            return false;

        int interval = LEVEL_INTERVAL;
        if (interval <= 1 || level == MAX_REAL_LEVEL || level == LEVEL_FOR_MAX_XP)
            return true;

        // Check levels in (previous, current] for divisibility by interval
        // Allows for firing notification if jumping over a level that would've notified
        int remainder = level % interval;
        return remainder == 0 || (level - remainder) > previous;
    }

    private int calculateCombatLevel() {
        return Experience.getCombatLevel(
            getRealLevel(Skill.ATTACK),
            getRealLevel(Skill.STRENGTH),
            getRealLevel(Skill.DEFENCE),
            getRealLevel(Skill.HITPOINTS),
            getRealLevel(Skill.MAGIC),
            getRealLevel(Skill.RANGED),
            getRealLevel(Skill.PRAYER)
        );
    }

    private int getRealLevel(Skill skill) {
        Integer cachedLevel = currentLevels.get(skill.getName());
        return cachedLevel != null
            ? Math.min(cachedLevel, MAX_REAL_LEVEL)
            : client.getRealSkillLevel(skill);
    }

    private int getLevel(int xp) {
        // treat 200M XP as level 127
        if (xp >= Experience.MAX_SKILL_XP)
            return LEVEL_FOR_MAX_XP;

        // log(n) operation to support virtual levels
        return Experience.getLevelForXp(xp);
    }

    private Set<WorldType> getSpecialWorldTypes() {
        var world = client.getWorldType().clone();
        world.retainAll(SPECIAL_WORLDS); // O(1)
        return world;
    }

    static {
        COMBAT_COMPONENTS = ImmutableSet.of(
            Skill.ATTACK.getName(),
            Skill.STRENGTH.getName(),
            Skill.DEFENCE.getName(),
            Skill.HITPOINTS.getName(),
            Skill.MAGIC.getName(),
            Skill.RANGED.getName(),
            Skill.PRAYER.getName()
        );
    }
}

package io.droptracker.events;

import com.google.gson.Gson;
import com.google.inject.Inject;
import io.droptracker.models.CustomWebhookBody;
import io.droptracker.models.submissions.SubmissionType;
import io.droptracker.service.*;
import io.droptracker.util.*;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;
import net.runelite.api.gameval.VarbitID;

import java.util.*;
import java.util.regex.*;

/**
 * Kill times and personal bests. The plugin does not read these messages
 * itself: it forwards the candidate chat lines of one kill, with the game
 * facts only the client can see (raid party sizes, precise timing, loadout),
 * and the server parses them exactly as this class used to
 * (data/submissions/pb_lines.py).
 *
 * <p>A kill is sent on the tick its lines hold both a count line and a time,
 * or a timed delve level (a delve level is a whole kill on its own) — the
 * tick the parser here used to finish it on. Lines that never complete a
 * kill are dropped after ten seconds, as partial kills always were.
 */
@Slf4j
public class PbHandler extends BaseEventHandler {

    /** A message the server's parser could use: a time, a count or a delve level. */
    private static final Pattern CANDIDATE = Pattern.compile("\\d:\\d\\d| count is|Delve level");
    private static final Pattern TIME = Pattern.compile("\\d:\\d\\d");
    /** The wall-clock total, never a kill time (except the Fractured Archive's). */
    private static final Pattern TOTAL = Pattern.compile(
        "(?<!Fractured Archive: )total completion time", Pattern.CASE_INSENSITIVE);
    /* Discord caps an embed field at 1024 characters and an embed at 6000. */
    private static final int MAX_LINES = 8;
    private static final int MAX_LINE_CHARS = 900;
    private static final long EXPIRY_MS = 10_000;

    @Inject
    protected NearbyPlayerTracker nearbyPlayerTracker;

    /* Gear and inventory at the moment of the kill; see LoadoutCapture. */
    @Inject
    protected LoadoutCapture loadoutCapture;

    /* Which uploaded character model the kill was made in; see PlayerModelService. */
    @Inject
    protected PlayerModelService playerModelService;

    @Inject
    protected Gson gson;

    private final List<Map<String, Object>> lines = new ArrayList<>();
    private long lastLineAt;

    @Override
    public boolean isEnabled() {
        return config.pbEmbeds();
    }

    public synchronized void onGameMessage(String message) {
        if (!isEnabled() || !CANDIDATE.matcher(message).find()
                || message.startsWith("Preparation") || message.contains("target time")) {
            return;
        }
        if (lines.size() >= MAX_LINES) {
            lines.remove(0);
        }
        Map<String, Object> line = new LinkedHashMap<>();
        line.put("m", message.length() > MAX_LINE_CHARS ? message.substring(0, MAX_LINE_CHARS) : message);
        line.put("t", client.getTickCount());
        line.put("p", party());
        lines.add(line);
        lastLineAt = System.currentTimeMillis();
    }

    public void onFriendsChatNotification(String message) {
        if (message.startsWith("Congratulations - your raid is complete!")) {
            onGameMessage(message);
        }
    }

    public synchronized void onTick() {
        if (lines.isEmpty()) {
            return;
        }
        boolean count = false;
        boolean time = false;
        boolean delve = false;
        for (Map<String, Object> line : lines) {
            String message = (String) line.get("m");
            boolean timed = has(message, null);
            count |= message.contains(" count is");
            time |= timed;
            delve |= timed && message.contains("Delve level");
        }
        if ((count && time) || delve) {
            send(new ArrayList<>(lines));
            reset();
        } else if (System.currentTimeMillis() - lastLineAt > EXPIRY_MS) {
            reset();
        }
    }

    private void send(List<Map<String, Object>> batch) {
        String player = getPlayerName();
        if (player == null || !isEnabled()) {
            return;
        }
        DebugLogger.log("[PbHandler][send] " + batch);
        Map<String, Object> fieldData = new LinkedHashMap<>();
        boolean pb = false;
        for (int i = 0; i < batch.size(); i++) {
            String message = (String) batch.get(i).get("m");
            pb |= has(message, "(new personal best)");
            if (message.contains(" count is")) {
                // Names the boss for the raid roster and the screenshot delay.
                fieldData.put("source", message);
            }
            fieldData.put("chat_line_" + (i + 1), gson.toJson(batch.get(i)));
        }
        // With precise timing off the game prints whole seconds; the server
        // credits those as approximate, so it needs to know which it got.
        fieldData.put("precise_timing", client.getVarbitValue(11866) > 0);
        // Decides the screenshot here; the server reads the real flag.
        fieldData.put("is_pb", pb);

        // Loadout at the moment of the kill. The outfit fingerprint pairs this
        // time with the character model filed under the same key, so the
        // leaderboard shows the model as worn for the kill. Same consent.
        if (loadoutCapture != null && loadoutCapture.isEnabled()) {
            fieldData.put("equipment", loadoutCapture.captureEquipment());
            fieldData.put("inventory", loadoutCapture.captureInventory());
            fieldData.put("model_fingerprint",
                playerModelService != null ? playerModelService.currentFingerprint() : null);
            fieldData.values().removeIf(Objects::isNull);
        }

        CustomWebhookBody webhook = createWebhookBody(player + " has killed a boss:");
        CustomWebhookBody.Embed embed = createEmbed(player + " has killed a boss:", "npc_kill");
        addFields(embed, fieldData);
        webhook.getEmbeds().add(embed);
        sendData(webhook, SubmissionType.KILL_TIME);
    }

    /** Whether a line of the message, other than a wall-clock total, holds
     *  {@code text} (or a time, when null). */
    private static boolean has(String message, String text) {
        for (String line : message.split("\n")) {
            if (!TOTAL.matcher(line).find() && (text == null ? TIME.matcher(line).find() : line.contains(text))) {
                return true;
            }
        }
        return false;
    }

    public synchronized void reset() {
        lines.clear();
    }

    /**
     * Raid party sizes the server reads team size from when a message does not
     * state it: [ToB, ToA, TFA, Royal Titans]. The raids prefer the
     * accumulated roster over the health-orb varbits, which clear at
     * completion; Royal Titans counts the players in view.
     */
    @SuppressWarnings("deprecation")
    private int[] party() {
        return new int[] {
            raidSize(NearbyPlayerTracker.RAID_TOB, Varbits.THEATRE_OF_BLOOD_ORB1, Varbits.THEATRE_OF_BLOOD_ORB2,
                Varbits.THEATRE_OF_BLOOD_ORB3, Varbits.THEATRE_OF_BLOOD_ORB4, Varbits.THEATRE_OF_BLOOD_ORB5),
            raidSize(NearbyPlayerTracker.RAID_TOA, Varbits.TOA_MEMBER_0_HEALTH, Varbits.TOA_MEMBER_1_HEALTH,
                Varbits.TOA_MEMBER_2_HEALTH, Varbits.TOA_MEMBER_3_HEALTH, Varbits.TOA_MEMBER_4_HEALTH,
                Varbits.TOA_MEMBER_5_HEALTH, Varbits.TOA_MEMBER_6_HEALTH, Varbits.TOA_MEMBER_7_HEALTH),
            raidSize(NearbyPlayerTracker.RAID_TFA, VarbitID.TFA_CLIENT_P0, VarbitID.TFA_CLIENT_P1,
                VarbitID.TFA_CLIENT_P2, VarbitID.TFA_CLIENT_P3, VarbitID.TFA_CLIENT_P4,
                VarbitID.TFA_CLIENT_P5, VarbitID.TFA_CLIENT_P6, VarbitID.TFA_CLIENT_P7),
            client.getPlayers().size()
        };
    }

    private int raidSize(String raid, int... varbits) {
        int filled = 0;
        for (int varbit : varbits) {
            filled += Math.min(client.getVarbitValue(varbit), 1);
        }
        return Math.max(nearbyPlayerTracker != null ? nearbyPlayerTracker.raidRosterSize(raid) : 0, filled);
    }
}

package io.droptracker.events;

import lombok.*;
import net.runelite.api.gameval.VarbitID;
import net.runelite.http.api.loottracker.LootRecordType;
import org.apache.commons.lang3.StringUtils;
import org.jetbrains.annotations.VisibleForTesting;

import javax.inject.*;

import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.regex.*;

import io.droptracker.service.KCService;
import io.droptracker.util.ItemIDSearch;
import io.droptracker.models.*;
import io.droptracker.models.api.Manifest;
import io.droptracker.models.submissions.SubmissionType;
import lombok.extern.slf4j.Slf4j;

@Slf4j
@Singleton
public class PetHandler extends BaseEventHandler {

    public static final String UNTRADEABLE_WARNING = "Pet Notifier cannot reliably identify pet names unless you enable the game setting: Untradeable loot notifications";

    @VisibleForTesting
    static final Pattern PET_REGEX = Pattern.compile("You (?:have a funny feeling like you|feel something weird sneaking).*");

    @VisibleForTesting
    static final Pattern CLAN_REGEX = Pattern.compile("\\b(?<user>[\\w\\s]+) (?:has a funny feeling like .+ followed|feels something weird sneaking into .+ backpack): (?<pet>.+) at (?<milestone>.+)");

    private static final Pattern UNTRADEABLE_REGEX = Pattern.compile("Untradeable drop: (.+)");
    private static final Pattern COLLECTION_LOG_REGEX = Pattern.compile("New item added to your collection log: (.+)");

    /**
     * The maximum number ticks to wait for milestone to be populated,
     * before firing notification with only the petName.
     */
    @VisibleForTesting
    static final int MAX_TICKS_WAIT = 5;

    /**
     * Tracks the number of ticks that occur where milestone is not populated
     * while petName is populated.
     */
    private final AtomicInteger ticksWaited = new AtomicInteger();

    @Inject
    private ItemIDSearch itemSearcher;

    @Inject
    private KCService kcService;

    @Inject
    private io.droptracker.service.ManifestService manifestService;

    @Setter(AccessLevel.PRIVATE)
    private volatile String petName = null;

    private volatile String milestone = null;

    private volatile boolean duplicate = false;

    private volatile boolean backpack = false;

    private volatile boolean collection = false;

    /**
     * Stores a pet name detected from an untradeable-drop or collection-log message that
     * arrived *before* the "You have a funny feeling…" game message.  For first-time pet
     * drops the game sometimes sends the item-name notification ahead of the pet message,
     * so we cache it here and consume it when PET_REGEX eventually fires.
     */
    private volatile String pendingPetName = null;
    private volatile boolean pendingCollection = false;

    private static final String PRIMED_NAME = "";

    @Override
    public boolean isEnabled() {
        return true; // Always track pets
    }

    public void onGameMessage(String chatMessage) {
        if (!isEnabled()) return;

        if (petName == null) {
            // Pre-capture pet name from untradeable-drop or collection-log messages.
            // For first-time pet drops the game can send these item-name notifications
            // *before* "You have a funny feeling…", so we store any matching name here
            // and consume it when PET_REGEX fires below.
            parseItemFromGameMessage(chatMessage)
                    .filter(this::isPet)
                    .ifPresent(parseResult -> {
                        this.pendingPetName = parseResult.itemName;
                        this.pendingCollection = parseResult.collectionLog;
                    });

            if (PET_REGEX.matcher(chatMessage).matches()) {
                // If we already captured the name from a preceding message, use it
                // directly; otherwise prime the notifier to wait for the next message.
                if (pendingPetName != null) {
                    this.petName = pendingPetName;
                    this.collection = pendingCollection;
                } else {
                    this.petName = PRIMED_NAME;
                }
                this.duplicate = chatMessage.contains("would have been");
                this.backpack = chatMessage.contains(" backpack");
                this.pendingPetName = null;
                this.pendingCollection = false;
            }
        } else if (PRIMED_NAME.equals(petName) || !collection) {
            parseItemFromGameMessage(chatMessage)
                    .filter(this::isPet)
                    .ifPresent(parseResult -> {
                        this.petName = parseResult.itemName;
                        if (parseResult.collectionLog) {
                            this.collection = true;
                        }
                    });
        }
    }

    public void onClanChatNotification(String message) {
        if (petName == null) {
            // We have not received the normal message about a pet drop, so this clan message cannot be relevant to us
            return;
        }

        Matcher matcher = CLAN_REGEX.matcher(message);
        if (matcher.find()) {
            String user = matcher.group("user").trim();
            if (user.equals(getPlayerName())) {
                this.petName = matcher.group("pet");
                this.milestone = StringUtils.removeEnd(matcher.group("milestone"), ".");
            }
        }
    }

    public void onTick() {
        if (petName == null) return;

        if (milestone != null || ticksWaited.incrementAndGet() > MAX_TICKS_WAIT) {
            // ensure notifier was not disabled during wait ticks
            if (isEnabled()) {
                this.handleNotify();
            }
            this.reset();
        }
    }

    public void reset() {
        this.petName = null;
        this.milestone = null;
        this.duplicate = false;
        this.backpack = false;
        this.collection = false;
        this.ticksWaited.set(0);
        this.pendingPetName = null;
        this.pendingCollection = false;
    }

    private void handleNotify() {
        Boolean previouslyOwned;
        if (duplicate) {
            previouslyOwned = true;
        } else if (client.getVarbitValue(VarbitID.OPTION_COLLECTION_NEW_ITEM) % 2 == 1) {
            // when collection log chat notification is enabled, presence or absence of notification indicates ownership history
            previouslyOwned = !collection;
        } else {
            previouslyOwned = null;
        }

        String gameMessage;
        if (backpack) {
            gameMessage = "feels something weird sneaking into their backpack";
        } else if (previouslyOwned != null && previouslyOwned) {
            gameMessage = "has a funny feeling like they would have been followed...";
        } else {
            gameMessage = "has a funny feeling like they're being followed";
        }

        String playerName = getPlayerName();
        if (playerName == null) {
            return;
        }

        CustomWebhookBody webhook = createWebhookBody(playerName + " received a pet!");
        CustomWebhookBody.Embed embed = createEmbed("Pet Drop!", "pet");

        Map<String, Object> fieldData = new HashMap<>();
        fieldData.put("pet_name", petName != null && !petName.isEmpty() ? ucFirst(petName) : "Unknown Pet");
        fieldData.put("game_message", gameMessage);
        fieldData.put("duplicate", duplicate);

        if (milestone != null) {
            fieldData.put("milestone", milestone);
        }

        if (previouslyOwned != null) {
            fieldData.put("previously_owned", previouslyOwned);
        }

        // Try to get KC information for the pet source.
        // getKillCountWithStorage checks the in-memory cache AND falls back to data
        // stored by the RuneLite Chat Commands / Loot Tracker plugins, so it works
        // even on the very first kill of a session (when the cache is cold).
        String pet = petName != null ? petKey(pets(), petName) : null;
        String source = pet != null ? pets().get(pet) : null;
        if (source != null) {
            Integer kc = kcService.getKillCountWithStorage(LootRecordType.UNKNOWN, source);
            if (kc != null && kc > 0) {
                fieldData.put("source", source);
                fieldData.put("killcount", kc);
            }
        }

        fieldData.put("timestamp", System.currentTimeMillis() / 1000);

        addFields(embed, fieldData);

        // Try to set pet image
        if (pet != null && !pet.isEmpty()) {
            Integer itemId = itemSearcher.findItemId(pet);
            if (itemId != null) {
                embed.setImage(plugin.itemImageUrl(itemId));
            }
        }

        webhook.getEmbeds().add(embed);

        sendData(webhook, SubmissionType.PET); 
    }

    private static Optional<ParseResult> parseItemFromGameMessage(String message) {
        Matcher untradeableMatcher = UNTRADEABLE_REGEX.matcher(message);
        if (untradeableMatcher.find()) {
            return Optional.of(new ParseResult(untradeableMatcher.group(1), false));
        }

        Matcher collectionMatcher = COLLECTION_LOG_REGEX.matcher(message);
        if (collectionMatcher.find()) {
            return Optional.of(new ParseResult(collectionMatcher.group(1), true));
        }

        return Optional.empty();
    }

    @AllArgsConstructor(access = AccessLevel.PACKAGE)
    private static class ParseResult {
        final String itemName;
        final boolean collectionLog;

    }

    /**
     * Converts text into "upper case first" form, as is used by OSRS for item names.
     *
     * @param text the string to be transformed
     * @return the text with only the first character capitalized
     */
    private static String ucFirst(String text) {
        if (text == null || text.isEmpty()) return text;
        if (text.length() < 2) return text.toUpperCase();
        return Character.toUpperCase(text.charAt(0)) + text.substring(1).toLowerCase();
    }

    /** Pets by name, each with its kill-count boss (or null), from the server's manifest. */
    private Map<String, String> pets() {
        Manifest manifest = manifestService.getManifest();
        return manifest == null ? Collections.emptyMap() : manifest.getPets();
    }

    /** The manifest's spelling of a pet's name, matched ignoring case, or null. */
    @VisibleForTesting
    static String petKey(Map<String, String> pets, String itemName) {
        for (String name : pets.keySet()) {
            if (name.equalsIgnoreCase(itemName)) {
                return name;
            }
        }
        return null;
    }

    /** A pet's name in a chat line. Without a manifest, the collection log line is the pet's. */
    private boolean isPet(ParseResult item) {
        Map<String, String> pets = pets();
        return item.itemName.startsWith("Pet ") || petKey(pets, item.itemName) != null
            || (pets.isEmpty() && item.collectionLog);
    }
}

package io.droptracker.events;

import lombok.AllArgsConstructor;
import java.util.Collections;
import java.util.regex.Pattern;

import com.google.common.annotations.VisibleForTesting;
import com.google.inject.Inject;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.game.ItemStack;

/**
 * Tracks Pharaoh's sceptres found in Pyramid Plunder. The sceptre comes from
 * a golden chest or sarcophagus and never fires a RuneLite loot event
 * (runelite/runelite#11670), so the game message is the only signal:
 *
 *   "You have found a Pharaoh's sceptre!"                         (inventory)
 *   "You have found a Pharaoh's sceptre! It fell on the floor."   (full inventory)
 *
 * The floor variant is confirmed from an in-game screenshot (Dink #741); the
 * inventory variant is the same line without the suffix. Both are red
 * GAMEMESSAGEs, which players cannot send, so no region check is needed (the
 * player is ejected from the pyramid as the message arrives anyway).
 *
 * Invoked manually from DropTrackerPlugin's event subscriptions (handlers in
 * this package are not registered on the RuneLite event bus).
 */
@Slf4j
@AllArgsConstructor(onConstructor_ = @Inject)
public class PyramidPlunderHandler extends BaseEventHandler {

    public static final String SOURCE_NAME = "Pyramid Plunder";

    private static final Pattern SCEPTRE_PATTERN = Pattern.compile(
        "^You have found (?:a|the) Pharaoh['’]s sceptre!(?: It fell on the floor\\.?)?$",
        Pattern.CASE_INSENSITIVE
    );

    private final DropHandler dropHandler;

    @Override
    public boolean isEnabled() {
        return config.trackActivities();
    }

    public void onGameMessage(String message) {
        if (!isEnabled() || !plugin.isTracking || message == null) {
            return;
        }
        if (!isSceptreMessage(message)) {
            return;
        }
        dropHandler.onActivityLoot(SOURCE_NAME,
            Collections.singletonList(new ItemStack(ItemID.PHARAOHS_SCEPTRE, 1)));
    }

    @VisibleForTesting
    static boolean isSceptreMessage(String message) {
        return SCEPTRE_PATTERN.matcher(message.trim()).matches();
    }
}

package io.droptracker.events;

import java.util.*;
import java.util.regex.*;

import javax.annotation.Nullable;
import javax.inject.Singleton;

import org.apache.commons.lang3.StringUtils;

import com.google.common.collect.ImmutableList;

import io.droptracker.models.CustomWebhookBody;
import io.droptracker.models.submissions.SubmissionType;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.VarPlayer;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;

@Slf4j
@Singleton
public class QuestHandler extends BaseEventHandler {

    private static final Pattern QUEST_PATTERN_1 = Pattern.compile(".+?ve\\.*? (?<verb>been|rebuilt|.+?ed)? ?(?:the )?'?(?<quest>.+?)'?(?: [Qq]uest)?[!.]?$");
    private static final Pattern QUEST_PATTERN_2 = Pattern.compile("'?(?<quest>.+?)'?(?: [Qq]uest)? (?<verb>[a-z]\\w+?ed)?(?: f.*?)?[!.]?$");
    private static final Collection<String> RFD_TAGS = ImmutableList.of("Another Cook", "freed", "defeated", "saved");
    private static final Collection<String> WORD_QUEST_IN_NAME_TAGS = ImmutableList.of("Another Cook", "Doric", "Heroes", "Legends", "Observatory", "Olaf", "Waterfall");
    private static final Map<String, String> QUEST_REPLACEMENTS = Map.of(
        "Lumbridge Cook... again", "Another Cook's",
        "Skrach 'Bone Crusher' Uglogwee", "Skrach Uglogwee"
    );

    /* VarbitIDs for quest tracking */
    private static final int VARBIT_QUESTS_COMPLETED_COUNT = 6347;
    private static final int VARBIT_QUESTS_TOTAL_COUNT = 11877;
    private static final int VARBIT_QP_MAX = 1782;


    @Override
    public boolean isEnabled() {
        return config.questsEmbed();
    }

    public void onWidgetLoaded(WidgetLoaded event) {
        if (event.getGroupId() == InterfaceID.QUESTSCROLL && isEnabled()) {
            Widget questTitle = client.getWidget(InterfaceID.Questscroll.QUEST_TITLE); // Quest title widget
            if (questTitle != null) {
                String questText = questTitle.getText();
                // 1 tick delay to ensure relevant varbits have been processed by the client
                clientThread.invokeLater(() -> handleQuestCompletion(questText));
            }
        }
    }

    @SuppressWarnings("deprecation")
    private void handleQuestCompletion(String questText) {
        // Get quest completion stats
        int completedQuests = client.getVarbitValue(VARBIT_QUESTS_COMPLETED_COUNT);
        int totalQuests = client.getVarbitValue(VARBIT_QUESTS_TOTAL_COUNT);
        boolean validQuests = completedQuests > 0 && totalQuests > 0;

        // Get quest points
        int questPoints = client.getVarpValue(VarPlayer.QUEST_POINTS);
        int totalQuestPoints = client.getVarbitValue(VARBIT_QP_MAX);
        boolean validPoints = questPoints > 0 && totalQuestPoints > 0;

        // Parse the quest name
        String parsedQuestName = parseQuestWidget(questText);
        if (parsedQuestName == null) {
            return;
        }

        String playerName = getPlayerName();
        if (playerName == null) {
            return;
        }

        CustomWebhookBody webhook = createWebhookBody(playerName + " completed a quest!");
        CustomWebhookBody.Embed embed = createEmbed("Quest Completed!", "quest");

        Map<String, Object> fieldData = new HashMap<>();
        fieldData.put("quest_name", parsedQuestName);

        if (validQuests) {
            fieldData.put("quests_completed", completedQuests);
            fieldData.put("total_quests", totalQuests);
            fieldData.put("completion_percentage", String.format("%.1f%%", (completedQuests * 100.0) / totalQuests));
        }

        if (validPoints) {
            fieldData.put("quest_points", questPoints);
            fieldData.put("total_quest_points", totalQuestPoints);
            fieldData.put("qp_percentage", String.format("%.1f%%", (questPoints * 100.0) / totalQuestPoints));
        }

        fieldData.put("timestamp", System.currentTimeMillis() / 1000);

        addFields(embed, fieldData);
        webhook.getEmbeds().add(embed);

        sendData(webhook, SubmissionType.QUEST_COMPLETION);
    }

    /* Helper methods */

    @Nullable
    private String parseQuestWidget(final String text) {
        if (text == null || text.isEmpty()) {
            return null;
        }

        // Try to match the quest completion text
        Matcher matcher = getMatcher(text);
        if (matcher == null) {
            // If no pattern matches, try to extract quest name directly
            // Some quests might just show the name without additional text
            return cleanQuestName(text);
        }

        String quest = matcher.group("quest");
        quest = QUEST_REPLACEMENTS.getOrDefault(quest, quest);

        String verb = StringUtils.defaultString(matcher.group("verb"));

        if (verb.contains("kind of")) {
            return null;
        } else if (verb.contains("completely")) {
            quest += " II";
        }

        // Handle Recipe for Disaster subquests
        if (RFD_TAGS.stream().anyMatch((quest + verb)::contains)) {
            quest = "Recipe for Disaster - " + quest;
        }

        // Add "Quest" to certain quest names that need it
        if (WORD_QUEST_IN_NAME_TAGS.stream().anyMatch(quest::contains)) {
            quest += " Quest";
        }

        return quest;
    }

    @Nullable
    private Matcher getMatcher(String text) {
        if (text == null || text.isEmpty()) {
            return null;
        }


        // "You have completed The Corsair Curse!"
        Matcher questMatch1 = QUEST_PATTERN_1.matcher(text);
        if (questMatch1.matches()) {
            return questMatch1;
        }

        // "'One Small Favour' completed!"
        Matcher questMatch2 = QUEST_PATTERN_2.matcher(text);
        if (questMatch2.matches()) {
            return questMatch2;
        }

        return null;
    }

    private String cleanQuestName(String text) {
        // Remove common prefixes/suffixes
        String cleaned = text;
        cleaned = cleaned.replaceAll("^You have completed ", "");
        cleaned = cleaned.replaceAll("^Congratulations! You've completed ", "");
        cleaned = cleaned.replaceAll("[!.]$", "");
        cleaned = cleaned.trim();
        // If it's still empty or too short, return null
        if (cleaned.isEmpty() || cleaned.length() < 3) {
            return null;
        }

        return cleaned;
    }
}

package io.droptracker.events;

import lombok.AccessLevel;
import lombok.RequiredArgsConstructor;
import java.util.*;
import java.util.regex.*;

import javax.annotation.Nullable;
import javax.inject.Singleton;

import org.jetbrains.annotations.VisibleForTesting;

import io.droptracker.models.CustomWebhookBody;
import io.droptracker.models.submissions.SubmissionType;
import io.droptracker.util.DebugLogger;
import lombok.Value;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.GameState;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.*;

/**
 * Slayer task completions, for event goals that count them ("25 tasks, no
 * Turael skipping", "10 tasks from Duradel").
 *
 * <p>A completion needs two signals, landing within {@value #WINDOW_TICKS}
 * ticks of each other:
 * <ol>
 *   <li>the game's completion line, "You have completed your task! You killed
 *       245 Cave Kraken. You gained 62,475 xp.", and</li>
 *   <li>the kills-remaining varp ({@code SLAYER_COUNT}) dropping from above
 *       zero to zero.</li>
 * </ol>
 * Neither is enough alone. Cancelling a task zeroes the count without the
 * line, and the line is only text: another plugin can print one.
 *
 * <p>What the task was (assignment, boss, master, area, starting amount) is
 * read the way RuneLite's own slayer plugin reads it, from varps and the
 * cache's slayer tables, never from chat. It is snapshotted while the task is
 * live, because finishing the task zeroes the count those reads depend on.
 *
 * <p>Every completion goes out with the raw {@code SLAYER_MASTER} value. Which
 * masters count toward a goal is the event task's own config, decided on the
 * server; the plugin never filters. The ids match the cache's
 * {@code slayer_master_task} rows (1 Turael ... 10 Mortimer).
 *
 * <p>Invoked from DropTrackerPlugin's subscriptions; handlers in this package
 * are not registered on the RuneLite event bus.
 */
@Slf4j
@Singleton
public class SlayerHandler extends BaseEventHandler {

    /** Most ticks allowed between the completion line and the count drop. */
    @VisibleForTesting
    static final int WINDOW_TICKS = 2;

    /**
     * {@code SLAYER_TARGET} for a boss task; which boss is in
     * {@code SLAYER_TARGET_BOSSID}. From [proc,helper_slayer_current_assignment].
     */
    @VisibleForTesting
    static final int BOSS_TASK_ID = 98;

    /* Masters whose streak lives in its own var (RuneLite's SlayerPlugin). */
    private static final int KRYSTILIA = 7;
    private static final int MORTIMER = 10;

    /** {@code slayer_modifiers} row 2: the kill count was changed at assignment. */
    private static final int MODIFIER_QUANTITY_CHANGE = 2;

    /** The server keeps this much of the raw lines. */
    private static final int MAX_MESSAGE_LENGTH = 255;

    @VisibleForTesting
    static final Pattern TASK_LINE = Pattern.compile(
        "You have completed your task! You killed (?<killed>[\\d,]+) (?<name>[^.]+)\\."
            + "(?:.*?You gained (?<xp>[\\d,]+) xp)?");

    /**
     * Precedes the completion line on a boss task, which itself only says
     * "You killed 11 Bosses". The cache name wins; this is the fallback.
     */
    @VisibleForTesting
    static final Pattern BOSS_LINE = Pattern.compile(
        "for completing your boss task against (?<name>.+?)\\.?$");

    /**
     * Follows the completion line. Three endings: points awarded, the points
     * cap reached, or a master that awards none (Turael/Aya, Spria).
     */
    @VisibleForTesting
    static final Pattern STREAK_LINE = Pattern.compile(
        "You've completed (?:at least )?(?<streak>[\\d,]+) (?:Wilderness |Mortimer )?tasks?"
            + "(?: and received (?<points>[\\d,]+) points?, giving you a total of (?<total>[\\d,]+)"
            + "| and reached the maximum amount of Slayer points \\((?<cap>[\\d,]+)\\)"
            + "|(?<nopoints>\\. ?You'll be eligible to earn reward points))?");

    /** The task the game has live right now; null when there is none. */
    private LiveTask liveTask;
    /** The task whose count just dropped to zero, and the tick it did. */
    private LiveTask zeroedTask;
    private int zeroedTick;
    /** The chat half of a completion, waiting on the count. */
    private PendingChat chat;
    /** A boss-task reward line, waiting on the completion line after it. */
    private String bossLineName;
    private int bossLineTick;
    /**
     * Varps arriving now are a login or world-hop sync, not changes, so a count
     * reading zero is not a task ending. RuneLite's {@code loginFlag}.
     */
    private boolean syncing;

    @Override
    public boolean isEnabled() {
        return config.slayerEmbeds();
    }

    /**
     * Enabling the plugin mid-task fires no varp change, so read the live task
     * directly. Task state is kept whatever the config says: turning the option
     * on mid-task must not lose the task it is on.
     */
    public void startUp() {
        clientThread.invokeLater(this::syncIfLoggedIn);
    }

    @VisibleForTesting
    void syncIfLoggedIn() {
        if (client.getGameState() == GameState.LOGGED_IN) {
            syncing = true;
            refreshTask();
        }
    }

    public void reset() {
        liveTask = null;
        zeroedTask = null;
        chat = null;
        bossLineName = null;
        syncing = false;
    }

    public void onGameStateChanged(GameState state) {
        switch (state) {
            case LOGIN_SCREEN:
                // The next login may be another account.
                reset();
                break;
            case HOPPING:
            case LOGGING_IN:
            case CONNECTION_LOST:
                syncing = true;
                break;
            default:
                break;
        }
    }

    public void onVarbitChanged(VarbitChanged event) {
        int varp = event.getVarpId();
        int varbit = event.getVarbitId();
        if (varp == VarPlayerID.SLAYER_COUNT
            || varp == VarPlayerID.SLAYER_TARGET
            || varp == VarPlayerID.SLAYER_AREA
            || varp == VarPlayerID.SLAYER_COUNT_ORIGINAL
            || varbit == VarbitID.SLAYER_TARGET_BOSSID
            || varbit == VarbitID.SLAYER_MASTER
            || varbit == VarbitID.SLAYER_MODIFIER_ID
            || varbit == VarbitID.SLAYER_MODIFIER_VALUE
            || varbit == VarbitID.SLAYER_MODIFIER_NEGATIVE) {
            afterVarps(this::refreshTask);
        }
    }

    /**
     * Reads once the whole batch of var updates has landed, so a new assignment
     * is never snapshotted half-written (the count from the new task, the master
     * from the old one).
     */
    @VisibleForTesting
    void afterVarps(Runnable read) {
        clientThread.invokeLater(read);
    }

    public void onGameMessage(String message) {
        // All three lines say "task"; most game messages don't.
        if (message == null || !message.contains("task")) {
            return;
        }
        int tick = client.getTickCount();

        Optional<TaskLine> taskLine = parseTaskLine(message);
        if (taskLine.isPresent()) {
            String bossName = bossLineName != null && tick - bossLineTick <= WINDOW_TICKS ? bossLineName : null;
            chat = new PendingChat(taskLine.get(), bossName, tick);
            bossLineName = null;
            return;
        }

        Optional<StreakLine> streakLine = parseStreakLine(message);
        if (streakLine.isPresent()) {
            if (chat != null && chat.streak == null && tick - chat.tick <= WINDOW_TICKS) {
                chat.streak = streakLine.get();
            }
            return;
        }

        Optional<String> bossName = parseBossLine(message);
        if (bossName.isPresent()) {
            bossLineName = bossName.get();
            bossLineTick = tick;
        }
    }

    public void onTick() {
        if (syncing) {
            refreshTask();
            syncing = false;
        }
        int now = client.getTickCount();

        if (chat != null) {
            boolean countDropped = zeroedTask != null && Math.abs(zeroedTick - chat.tick) <= WINDOW_TICKS;
            // The streak line normally lands on the completion line's tick;
            // one tick later, go without it rather than lose the completion.
            if (countDropped && (chat.streak != null || now - chat.tick >= 1)) {
                Completion completion = complete(chat, zeroedTask);
                chat = null;
                zeroedTask = null;
                if (isEnabled() && plugin.isTracking) {
                    submit(completion);
                }
                return;
            }
            if (now - chat.tick > WINDOW_TICKS) {
                DebugLogger.log("[SlayerHandler] completion line with no task count drop; not submitted: "
                    + chat.taskLine.getRaw());
                chat = null;
            }
        }
        // A count drop no line followed (a cancelled task) needs no clean-up:
        // the window check above keeps it from pairing with a later line.
    }

    @VisibleForTesting
    void refreshTask() {
        int remaining = client.getVarpValue(VarPlayerID.SLAYER_COUNT);
        if (remaining > 0) {
            liveTask = readTask();
            return;
        }
        LiveTask ended = liveTask;
        liveTask = null;
        if (ended != null && !syncing) {
            zeroedTask = ended;
            zeroedTick = client.getTickCount();
        }
    }

    private LiveTask readTask() {
        int taskId = client.getVarpValue(VarPlayerID.SLAYER_TARGET);
        int bossId = taskId == BOSS_TASK_ID ? client.getVarbitValue(VarbitID.SLAYER_TARGET_BOSSID) : 0;

        int initial = client.getVarpValue(VarPlayerID.SLAYER_COUNT_ORIGINAL);
        if (client.getVarbitValue(VarbitID.SLAYER_MODIFIER_ID) == MODIFIER_QUANTITY_CHANGE) {
            int change = client.getVarbitValue(VarbitID.SLAYER_MODIFIER_VALUE);
            initial += client.getVarbitValue(VarbitID.SLAYER_MODIFIER_NEGATIVE) == 1 ? -change : change;
        }

        return new LiveTask(
            taskId,
            bossId,
            lookUpTaskName(taskId, bossId),
            client.getVarpValue(VarPlayerID.SLAYER_AREA),
            initial,
            client.getVarbitValue(VarbitID.SLAYER_MASTER));
    }

    /**
     * The assignment's name as the cache spells it ("Cave Kraken", "The
     * Alchemical Hydra"), the same lookup RuneLite's slayer plugin makes. Null
     * when the tables have no row for it; the chat line then names the task.
     */
    @Nullable
    private String lookUpTaskName(int taskId, int bossId) {
        try {
            int taskRow;
            if (taskId == BOSS_TASK_ID) {
                List<Integer> bossRows = client.getDBRowsByValue(
                    DBTableID.SlayerTaskSublist.ID, DBTableID.SlayerTaskSublist.COL_TASK_SUBTABLE_ID, 0, bossId);
                if (bossRows == null || bossRows.isEmpty()) {
                    return null;
                }
                Object[] task = client.getDBTableField(bossRows.get(0), DBTableID.SlayerTaskSublist.COL_TASK, 0);
                if (task == null || task.length == 0 || !(task[0] instanceof Integer)) {
                    return null;
                }
                taskRow = (Integer) task[0];
            } else {
                List<Integer> taskRows = client.getDBRowsByValue(
                    DBTableID.SlayerTask.ID, DBTableID.SlayerTask.COL_ID, 0, taskId);
                if (taskRows == null || taskRows.isEmpty()) {
                    return null;
                }
                taskRow = taskRows.get(0);
            }
            Object[] name = client.getDBTableField(taskRow, DBTableID.SlayerTask.COL_NAME_UPPERCASE, 0);
            if (name == null || name.length == 0 || !(name[0] instanceof String)) {
                return null;
            }
            String text = ((String) name[0]).trim();
            return text.isEmpty() ? null : text;
        } catch (RuntimeException e) {
            log.debug("Slayer task lookup failed (task {}, boss {})", taskId, bossId, e);
            return null;
        }
    }

    private Completion complete(PendingChat chat, LiveTask task) {
        TaskLine line = chat.taskLine;
        StreakLine streak = chat.streak;

        String name = task.getTaskName();
        if (name == null && task.getTaskId() == BOSS_TASK_ID) {
            name = chat.bossName;
        }
        if (name == null) {
            name = line.getName();
        }

        Integer streakCount = streak != null ? streak.getStreak() : null;
        if (streakCount == null) {
            streakCount = readStreak(task.getMasterId());
        }
        Integer pointsTotal = streak != null ? streak.getPointsTotal() : null;
        if (pointsTotal == null) {
            pointsTotal = client.getVarbitValue(VarbitID.SLAYER_POINTS);
        }

        String message = streak != null ? line.getRaw() + " " + streak.getRaw() : line.getRaw();
        if (message.length() > MAX_MESSAGE_LENGTH) {
            message = message.substring(0, MAX_MESSAGE_LENGTH);
        }

        return new Completion(
            name,
            task.getTaskId(),
            task.getBossId(),
            task.getMasterId(),
            task.getAreaId(),
            task.getAmountInitial(),
            line.getKilled(),
            line.getXp(),
            streakCount,
            streak != null ? streak.getPointsAwarded() : null,
            pointsTotal,
            message);
    }

    private int readStreak(int masterId) {
        switch (masterId) {
            case KRYSTILIA:
                return client.getVarbitValue(VarbitID.SLAYER_WILDERNESS_TASKS_COMPLETED);
            case MORTIMER:
                return client.getVarpValue(VarPlayerID.SLAYER_MORTIMER_TASKS_COMPLETED);
            default:
                return client.getVarbitValue(VarbitID.SLAYER_TASKS_COMPLETED);
        }
    }

    @VisibleForTesting
    void submit(Completion completion) {
        String playerName = getPlayerName();
        if (playerName == null) {
            return;
        }
        CustomWebhookBody webhook = createWebhookBody(playerName + " completed a slayer task!");
        CustomWebhookBody.Embed embed = createEmbed(completion.getTaskName(), "slayer_task");
        addFields(embed, fields(completion, System.currentTimeMillis() / 1000));
        webhook.getEmbeds().add(embed);
        sendData(webhook, SubmissionType.SLAYER_TASK);
    }

    /**
     * The submission's fields. Unknowns are left out rather than sent as
     * {@code addFields}' "N/A", which the server would store as text.
     */
    @VisibleForTesting
    static Map<String, Object> fields(Completion completion, long timestamp) {
        Map<String, Object> fields = new LinkedHashMap<>();
        fields.put("task_name", completion.getTaskName());
        fields.put("task_id", completion.getTaskId());
        fields.put("is_boss", completion.isBoss());
        if (completion.isBoss() && completion.getBossId() > 0) {
            fields.put("boss_id", completion.getBossId());
        }
        fields.put("master_id", completion.getMasterId());
        if (completion.getAreaId() > 0) {
            fields.put("area_id", completion.getAreaId());
        }
        if (completion.getAmountInitial() > 0) {
            fields.put("amount_initial", completion.getAmountInitial());
        }
        fields.put("amount_killed", completion.getAmountKilled());
        putIfKnown(fields, "xp_gained", completion.getXpGained());
        putIfKnown(fields, "streak", completion.getStreak());
        putIfKnown(fields, "points_awarded", completion.getPointsAwarded());
        putIfKnown(fields, "points_total", completion.getPointsTotal());
        fields.put("completion_message", completion.getCompletionMessage());
        fields.put("timestamp", timestamp);
        return fields;
    }

    private static void putIfKnown(Map<String, Object> fields, String key, @Nullable Integer value) {
        if (value != null) {
            fields.put(key, value);
        }
    }

    // --- chat parsing ---------------------------------------------------

    @VisibleForTesting
    static Optional<TaskLine> parseTaskLine(String message) {
        Matcher m = TASK_LINE.matcher(message);
        if (!m.find()) {
            return Optional.empty();
        }
        Integer killed = parseNumber(m.group("killed"));
        String name = m.group("name").trim();
        if (killed == null || name.isEmpty()) {
            return Optional.empty();
        }
        return Optional.of(new TaskLine(killed, name, parseNumber(m.group("xp")), message.trim()));
    }

    @VisibleForTesting
    static Optional<StreakLine> parseStreakLine(String message) {
        Matcher m = STREAK_LINE.matcher(message);
        if (!m.find()) {
            return Optional.empty();
        }
        Integer streak = parseNumber(m.group("streak"));
        if (streak == null) {
            return Optional.empty();
        }
        Integer awarded = parseNumber(m.group("points"));
        Integer total = parseNumber(m.group("total"));
        Integer cap = parseNumber(m.group("cap"));
        if (m.group("nopoints") != null) {
            // Turael/Aya and Spria: nothing awarded. The total is untouched and
            // not in the line; the caller reads it from the varbit.
            awarded = 0;
        } else if (cap != null) {
            // Capped: the line gives the new total but not what was added.
            total = cap;
        }
        return Optional.of(new StreakLine(streak, awarded, total, message.trim()));
    }

    /**
     * The boss's name as the reward line gives it, capitalised the way the cache
     * spells boss tasks ("the Cave Kraken boss" becomes "The Cave Kraken boss").
     */
    @VisibleForTesting
    static Optional<String> parseBossLine(String message) {
        Matcher m = BOSS_LINE.matcher(message);
        if (!m.find()) {
            return Optional.empty();
        }
        String name = m.group("name").trim();
        if (name.isEmpty()) {
            return Optional.empty();
        }
        return Optional.of(Character.toUpperCase(name.charAt(0)) + name.substring(1));
    }

    @Nullable
    private static Integer parseNumber(@Nullable String digits) {
        if (digits == null) {
            return null;
        }
        try {
            return Integer.parseInt(digits.replace(",", ""));
        } catch (NumberFormatException e) {
            return null;
        }
    }

    // --- values ---------------------------------------------------------

    /** A task as the varps describe it, captured while it is live. */
    @Value
    @VisibleForTesting
    static class LiveTask {
        int taskId;
        int bossId;
        @Nullable
        String taskName;
        int areaId;
        int amountInitial;
        int masterId;
    }

    /** "You have completed your task! You killed N name. You gained X xp." */
    @Value
    @VisibleForTesting
    static class TaskLine {
        int killed;
        String name;
        @Nullable
        Integer xp;
        String raw;
    }

    /** "You've completed N tasks and received P points, giving you a total of T..." */
    @Value
    @VisibleForTesting
    static class StreakLine {
        int streak;
        @Nullable
        Integer pointsAwarded;
        @Nullable
        Integer pointsTotal;
        String raw;
    }

    @RequiredArgsConstructor(access = AccessLevel.PRIVATE)
    private static final class PendingChat {
        private final TaskLine taskLine;
        @Nullable
        private final String bossName;
        private final int tick;
        @Nullable
        private StreakLine streak;

    }

    /** One completed task, as it is submitted. */
    @Value
    @VisibleForTesting
    static class Completion {
        String taskName;
        int taskId;
        int bossId;
        /** Raw {@code SLAYER_MASTER}; the server names it. */
        int masterId;
        int areaId;
        int amountInitial;
        int amountKilled;
        @Nullable
        Integer xpGained;
        @Nullable
        Integer streak;
        @Nullable
        Integer pointsAwarded;
        @Nullable
        Integer pointsTotal;
        String completionMessage;

        boolean isBoss() {
            return taskId == BOSS_TASK_ID;
        }
    }
}

package io.droptracker.events;

import lombok.AllArgsConstructor;
import java.util.*;
import java.util.regex.*;

import com.google.common.annotations.VisibleForTesting;
import com.google.inject.Inject;

import lombok.Value;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.game.ItemStack;

/**
 * Tracks deep sea trawling (Sailing) catches. Trawled fish never fire a
 * RuneLite loot event — they land in the ship's shared trawling net and are
 * only later collected into the inventory or cargo hold (where they turn into
 * fish crates, losing item identity). We therefore count the per-catch game
 * message ("You catch 2 raw haddock!"), which also attributes each fish to
 * the player who caught it rather than whoever empties the net.
 *
 * Ordinary fishing produces "You catch a ..." messages too, so only species
 * from the static trawling map are ever submitted — never a generic
 * name-to-id lookup. Crewmate catches ("<name> catches ..."), "Trawler's
 * trust" bonus lines and net-empty/collection messages are ignored. Prior
 * art for the message formats: github.com/CarelessEsper/deepSeaTrawling.
 *
 * Invoked manually from DropTrackerPlugin's event subscriptions (handlers in
 * this package are not registered on the RuneLite event bus).
 */
@Slf4j
@AllArgsConstructor(onConstructor_ = @Inject)
public class TrawlingHandler extends BaseEventHandler {

    public static final String SOURCE_NAME = "Deep Sea Trawling";

    /* "You catch a raw halibut!" / "You catch 2 raw giant krill!" */
    private static final Pattern CATCH_PATTERN = Pattern.compile(
        "^You catch (?<qty>an?|\\d+) (?<fish>.+?)[!.]?$"
    );

    /* Trawling-only species, keyed by lowercase item name without the "raw "
     * prefix. Acts as both the id map and the allowlist that keeps ordinary
     * fishing catches out. Trophy fish are included in case their
     * announcement arrives as a catch-style message. */
    private static final Map<String, Integer> FISH_IDS;
    static {
        Map<String, Integer> ids = new HashMap<>();
        ids.put("giant krill", ItemID.RAW_GIANT_KRILL);
        ids.put("haddock", ItemID.RAW_HADDOCK);
        ids.put("yellowfin", ItemID.RAW_YELLOWFIN);
        ids.put("halibut", ItemID.RAW_HALIBUT);
        ids.put("bluefin", ItemID.RAW_BLUEFIN);
        ids.put("marlin", ItemID.RAW_MARLIN);
        ids.put("giant blue krill", ItemID.POH_TROPHYDROP_GIANT_KRILL);
        ids.put("golden haddock", ItemID.POH_TROPHYDROP_HADDOCK);
        ids.put("orangefin", ItemID.POH_TROPHYDROP_YELLOWFIN);
        ids.put("huge halibut", ItemID.POH_TROPHYDROP_HALIBUT);
        ids.put("purplefin", ItemID.POH_TROPHYDROP_BLUEFIN);
        ids.put("swift marlin", ItemID.POH_TROPHYDROP_MARLIN);
        FISH_IDS = Collections.unmodifiableMap(ids);
    }

    private final DropHandler dropHandler;

    @Override
    public boolean isEnabled() {
        return config.trackActivities() && config.trackTrawling();
    }

    public void onGameMessage(String message) {
        if (!isEnabled() || !plugin.isTracking || message == null) {
            return;
        }

        ParsedCatch parsed = parseCatch(message);
        if (parsed == null) {
            return;
        }

        Integer itemId = resolveFishId(parsed.getFishName());
        if (itemId == null) {
            /* Ordinary fishing catch, or a species we don't know yet */
            return;
        }

        dropHandler.onActivityLoot(SOURCE_NAME,
            Collections.singletonList(new ItemStack(itemId, parsed.getQuantity())));
    }

    /** Parses a "You catch ..." message; null for everything else. */
    @VisibleForTesting
    static ParsedCatch parseCatch(String message) {
        /* The "Trawler's trust" bonus line duplicates fish that already had
         * their own catch message, so it must never be counted. */
        if (message.contains("Trawler's trust")) {
            return null;
        }
        Matcher matcher = CATCH_PATTERN.matcher(message);
        if (!matcher.matches()) {
            return null;
        }
        String qtyToken = matcher.group("qty");
        int quantity = qtyToken.startsWith("a") ? 1 : Integer.parseInt(qtyToken);
        if (quantity <= 0) {
            return null;
        }
        return new ParsedCatch(matcher.group("fish").trim(), quantity);
    }

    /** Maps a message fish name to a trawling item id, or null when unknown. */
    @VisibleForTesting
    static Integer resolveFishId(String fishName) {
        String name = fishName.toLowerCase(Locale.ROOT).trim();
        if (name.startsWith("raw ")) {
            name = name.substring(4);
        }
        Integer id = FISH_IDS.get(name);
        if (id == null && name.endsWith("s")) {
            /* Multi-catch messages may pluralize ("2 raw haddocks") */
            id = FISH_IDS.get(name.substring(0, name.length() - 1));
        }
        return id;
    }

    @Value
    @VisibleForTesting
    static class ParsedCatch {
        String fishName;
        int quantity;
    }
}

