import net.runelite.api.gameval.InterfaceID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;
import io.droptracker.service.SubmissionManager;
import io.droptracker.util.BossNameRegistry;
import net.runelite.client.util.*;
import org.apache.commons.text.WordUtils;

import java.awt.image.BufferedImage;
import java.util.*;
import java.util.regex.*;
import java.util.stream.Collectors;

public class WidgetEventHandler {


    @Inject
    protected Client client;

    @Inject
    private ConfigManager configManager;

    @Inject
    private ItemManager itemManager;

    @Inject
    private Gson gson;

    @Inject
    private SubmissionManager submissionManager;

    @Inject
    private BossNameRegistry bossNameRegistry;

    private int petsIconIdx = -1;
    private int[] pets;


    private boolean advLogLoaded = false;
    private boolean bossLogLoaded = false;
    private boolean scrollInterfaceLoaded = false;
    private String pohOwner;

    private static final String TEAM_SIZES = "(?<teamsize>[^)]+)";

    private static final Pattern ADVENTURE_LOG_TITLE_PATTERN = Pattern.compile("The Exploits of (.+)");
    private static final Pattern ADVENTURE_LOG_PB_PATTERN = Pattern.compile(
        "Fastest (?:kill|run|Room time|Overall time)(?: - \\(Team size: " + TEAM_SIZES + "\\))?:\\s*(?<time>[0-9:]+(?:\\.[0-9]+)?)?"
    );
    private static final Pattern ADVENTURE_LOG_PB_TIME_ONLY_PATTERN = Pattern.compile("^(?<time>[0-9:]+(?:\\.[0-9]+)?)$");

    // The adventure log opens in one of two menu interfaces, depending on the
    // player's interface style setting. Newer style first, then the original.
    private static final int[] ADVENTURE_LOG_TITLE_CONTAINERS = {
        InterfaceID.MenuNew.TITLE, InterfaceID.Menu.LJ_LAYER2
    };

    @AllArgsConstructor
    private static class BossPB {
        private final String bossName;
        private final String teamSize;
        private final double time;


        public String getBossName() {
            return bossName;
        }

        public String getTeamSize() {
            return teamSize;
        }

        public double getTime() {
            return time;
        }
    }


    public void onWidgetLoaded(WidgetLoaded widget)
    {
        switch (widget.getGroupId())
        {
            case InterfaceID.MENU:
            case InterfaceID.MENU_NEW:
                advLogLoaded = true;
                break;
            case InterfaceID.KILL_LOG:
                bossLogLoaded = true;
                break;
            case InterfaceID.JOURNALSCROLL:
                scrollInterfaceLoaded = true;
                break;
        }
    }

    /** Entering or leaving a house (or hopping) means a new adventure log owner. */
    public void onGameStateChanged(GameState state)
    {
        if (state == GameState.LOADING || state == GameState.HOPPING)
        {
            pohOwner = null;
        }
    }

    /**
     * The adventure log owner, or null when the loaded menu is not an adventure
     * log. The title sits at a different child index in each menu interface, so
     * each container is scanned for it rather than indexed.
     */
    @VisibleForTesting
    String readAdventureLogOwner()
    {
        for (int componentId : ADVENTURE_LOG_TITLE_CONTAINERS)
        {
            Widget container = client.getWidget(componentId);
            if (container == null)
            {
                continue;
            }
            String owner = matchAdventureLogOwner(container.getText());
            Widget[] children = container.getChildren();
            for (int i = 0; owner == null && children != null && i < children.length; i++)
            {
                owner = children[i] == null ? null : matchAdventureLogOwner(children[i].getText());
            }
            if (owner != null)
            {
                return owner;
            }
        }
        return null;
    }

    @VisibleForTesting
    static String matchAdventureLogOwner(String text)
    {
        if (text == null)
        {
            return null;
        }
        Matcher matcher = ADVENTURE_LOG_TITLE_PATTERN.matcher(Text.removeTags(text));
        return matcher.find() ? matcher.group(1) : null;
    }

    @SuppressWarnings({ "deprecation", "null" })
    @Subscribe
    public void onGameTick(GameTick event)
    {
        if (client.getLocalPlayer() == null)
        {
            return;
        }

        if (advLogLoaded)
        {
            advLogLoaded = false;

            String owner = readAdventureLogOwner();
            if (owner != null)
            {
                pohOwner = owner;
            }
        }

        if (bossLogLoaded && (pohOwner == null || pohOwner.equals(client.getLocalPlayer().getName())))
        {
            bossLogLoaded = false;

            Widget title = client.getWidget(ComponentID.KILL_LOG_TITLE);
            Widget bossMonster = client.getWidget(ComponentID.KILL_LOG_MONSTER);
            Widget bossKills = client.getWidget(ComponentID.KILL_LOG_KILLS);

            if (title == null || bossMonster == null || bossKills == null
                || !"Boss Kill Log".equals(title.getText()))
            {
                return;
            }

        }

        // Adventure log - Counters
        if (scrollInterfaceLoaded)
        {
            scrollInterfaceLoaded = false;

            collectAndSendAdventureLogPBs();
        }
    }



    // Method to collect all PBs from the adventure log
    @SuppressWarnings({ "null", "deprecation" })
    private void collectAndSendAdventureLogPBs() {
        if (client.getLocalPlayer() == null || client.getLocalPlayer().getName() == null || pohOwner == null) {
            return;
        }
        // Only process if we're in our own POH
        if (!client.getLocalPlayer().getName().equals(pohOwner)) {
            return;
        }

        List<BossPB> personalBests = new ArrayList<>();

        Widget parent = client.getWidget(ComponentID.ACHIEVEMENT_DIARY_SCROLL_TEXT);
        if (parent == null) {
            return;
        }

        // Each line is a separate static child
        Widget[] children = parent.getStaticChildren();
        String[] text = Arrays.stream(children)
            .map(Widget::getText)
            .map(Text::removeTags)
            .toArray(String[]::new);

        for (int i = 0; i < text.length; ++i) {
            String bossHeader = text[i] == null ? "" : text[i].trim();
            if (bossHeader.isEmpty()) {
                continue;
            }

            String boss = longBossName(bossHeader);
            String pendingTeamSize = null;

            for (i = i + 1; i < text.length; ++i) {
                String line = text[i] == null ? "" : text[i].trim();
                if (line.isEmpty()) {
                    break;
                }

                Matcher descriptorMatcher = ADVENTURE_LOG_PB_PATTERN.matcher(line);
                if (descriptorMatcher.find()) {
                    String normalizedTeamSize = normalizeTeamSize(descriptorMatcher.group("teamsize"));
                    String inlineTime = descriptorMatcher.group("time");

                    if (inlineTime != null && !inlineTime.isEmpty()) {
                        final double seconds = timeStringToSeconds(inlineTime);
                        personalBests.add(new BossPB(boss, normalizedTeamSize, seconds));
                        pendingTeamSize = null;
                    } else {
                        pendingTeamSize = normalizedTeamSize;
                    }
                    continue;
                }

                Matcher timeOnlyMatcher = ADVENTURE_LOG_PB_TIME_ONLY_PATTERN.matcher(line);
                if (timeOnlyMatcher.find() && pendingTeamSize != null) {
                    final double seconds = timeStringToSeconds(timeOnlyMatcher.group("time"));
                    personalBests.add(new BossPB(boss, pendingTeamSize, seconds));
                    pendingTeamSize = null;
                }
            }
        }

        if (!personalBests.isEmpty()) {
            sendPersonalBestsWebhook(pohOwner, personalBests);
        }
    }
    private void sendPersonalBestsWebhook(String playerName, List<BossPB> personalBests) {
        if (personalBests.isEmpty()) {
            return;
        }

        CustomWebhookBody customWebhookBody = new CustomWebhookBody();
        customWebhookBody.setContent(playerName + "'s Personal Best Times:");

        // Create a main embed for the PBs
        CustomWebhookBody.Embed pbEmbed = new CustomWebhookBody.Embed();
        pbEmbed.title = playerName + "'s Personal Best Times";

        // Add player info fields
        String accountHash = String.valueOf(client.getAccountHash());
        pbEmbed.addField("type", "adventure_log", true);
        pbEmbed.addField("player", playerName, true);
        pbEmbed.addField("acc_hash", accountHash, true);

        // Group PBs into batches (5 PBs per field)
        int pbsPerField = 5;
        int fieldCount = (int) Math.ceil(personalBests.size() / (double) pbsPerField);

        List<Integer> playerPets = getPetList();

        for (int i = 0; i < fieldCount; i++) {
            StringBuilder fieldContent = new StringBuilder();
            int startIdx = i * pbsPerField;
            int endIdx = Math.min(startIdx + pbsPerField, personalBests.size());

            for (int j = startIdx; j < endIdx; j++) {
                BossPB pb = personalBests.get(j);
                String formattedTime = formatTime(pb.getTime());

                // Format each PB as with "`boss name` - `team_size` : `time`" for easy parsing
                fieldContent.append("`" + pb.getBossName() + "`")
                           .append(" - ")
                           .append("`" + pb.getTeamSize() + "`")
                           .append(" : ")
                           .append("`" + formattedTime + "`");

                // Add a newline between entries (except the last one)
                if (j < endIdx - 1) {
                    fieldContent.append("\n");
                }
            }

            // Add the field with a batch number
            pbEmbed.addField("" + (i + 1), fieldContent.toString(), false);
        }
        pbEmbed.addField("Pets", playerPets.toString(), false);

        customWebhookBody.getEmbeds().add(pbEmbed);

        // Use the main plugin class' sendWebhook method
        submissionManager.sendDataToDropTracker(customWebhookBody, SubmissionType.ADVENTURE_LOG);
    }
    /**
     * Formats a time in seconds to a string in the format mm:ss or h:mm:ss
     */
    private String formatTime(double seconds)
    {
        int hours = (int) (seconds / 3600);
        int minutes = (int) ((seconds % 3600) / 60);
        double secs = seconds % 60;

        if (hours > 0)
        {
            return String.format("%d:%02d:%05.2f", hours, minutes, secs);
        }
        else
        {
            return String.format("%d:%05.2f", minutes, secs);
        }
    }

    private String longBossName(String boss)
    {
        return bossNameRegistry.canonicalName(boss, WordUtils::capitalize);
    }

    private void loadPets()
    {
        assert petsIconIdx == -1;

        // !pets requires off thread pets access, so we just store a copy
        EnumComposition petsEnum = client.getEnum(EnumID.PETS);
        pets = new int[petsEnum.size()];
        for (int i = 0; i < petsEnum.size(); ++i)
        {
            pets[i] = petsEnum.getIntValue(i);
        }

        final IndexedSprite[] modIcons = client.getModIcons();
        assert modIcons != null;

        final IndexedSprite[] newModIcons = Arrays.copyOf(modIcons, modIcons.length + pets.length);
        petsIconIdx = modIcons.length;

        client.setModIcons(newModIcons);

        for (int i = 0; i < pets.length; i++)
        {
            final int petId = pets[i];

            final AsyncBufferedImage abi = itemManager.getImage(petId);
            final int idx = petsIconIdx + i;
            abi.onLoaded(() ->
            {
                final BufferedImage image = ImageUtil.resizeImage(abi, 18, 16);
                final IndexedSprite sprite = ImageUtil.getImageIndexedSprite(image, client);
                client.getModIcons()[idx] = sprite;
            });
        }
    }

    /**
     * Looks up the list of owned pets for the local player
     */
    private List<Integer> getPetList()
    {
        String petListJson = configManager.getRSProfileConfiguration("chatcommands", "pets2",
                String.class);

        List<Integer> petList;
        try
        {
            // CHECKSTYLE:OFF
            petList = gson.fromJson(petListJson, new TypeToken<List<Integer>>(){}.getType());
            // CHECKSTYLE:ON
        }
        catch (JsonSyntaxException ex)
        {
            return Collections.emptyList();
        }

        return petList != null ? petList : Collections.emptyList();
    }

    @VisibleForTesting
    static double timeStringToSeconds(String timeString)
    {
        String[] s = timeString.split(":");
        if (s.length == 2) // mm:ss
        {
            return Integer.parseInt(s[0]) * 60 + Double.parseDouble(s[1]);
        }
        else if (s.length == 3) // h:mm:ss
        {
            return Integer.parseInt(s[0]) * 60 * 60 + Integer.parseInt(s[1]) * 60 + Double.parseDouble(s[2]);
        }
        return Double.parseDouble(timeString);
    }

    private static String normalizeTeamSize(String rawTeamSize)
    {
        if (rawTeamSize == null)
        {
            return "Solo";
        }

        String teamSize = rawTeamSize.toLowerCase().trim();
        if (teamSize.isEmpty())
        {
            return "Solo";
        }
        if (teamSize.contains("solo"))
        {
            return "Solo";
        }

        // Handles values like "3 player hard mode", "4 players expert mode", "6+ players".
        teamSize = teamSize
            .replace("hard mode", "")
            .replace("entry mode", "")
            .replace("expert mode", "")
            .replace("player", "")
            .replace("players", "")
            .trim();

        if ("1".equals(teamSize))
        {
            return "Solo";
        }

        return teamSize.isEmpty() ? "Solo" : teamSize;
    }
    @Subscribe
    public void onGameStateChanged(GameStateChanged event)
    {
        switch (event.getGameState())
        {
            case LOADING:
            case HOPPING:
                pohOwner = null;
                break;
            case STARTING:
                petsIconIdx = -1;
                pets = null;
                break;
            case LOGIN_SCREEN:
                if (petsIconIdx == -1)
                {
                    loadPets();
                }
                break;
            default:
                break;
        }
    }

}

/*
 * Adapted from RuneProfile (github.com/ReinhardtR/runeprofile-plugin),
 * Copyright (c) 2022, Reinhardt Rijna, BSD 2-Clause License (see LICENSE). Exports a game Model as binary glTF so the player's
 * character - equipment included, since the local player's model is composed
 * from what they are wearing - can be rendered outside the client.
 */
package io.droptracker.modelexport;

import lombok.*;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;

import javax.annotation.Nullable;
import javax.imageio.ImageIO;
import java.awt.image.BufferedImage;
import java.io.*;
import java.util.*;

/**
 * Reads game textures out of the client as PNGs, along with the scroll rate
 * that makes animated ones (an inferno cape's fire, lava, water) move.
 * <p>
 * Encoded PNGs are cached for the life of the client: there are only a couple
 * of hundred textures in the game and a player uses a handful, but a profile
 * sync would otherwise re-encode the same cape every time.
 */
@Slf4j
@AllArgsConstructor
public final class GameTextures {
    /**
     * The client advances texture animation once per client tick, and shifts
     * UVs by speed/128 each time. Client ticks are 20ms, so this converts the
     * game's per tick step into UV units per second for a renderer that works
     * in wall clock time.
     */
    private static final float TICKS_PER_SECOND = 50f;
    private static final float TEXTURE_ANIM_UNIT = 1f / 128f;

    /** One texture, ready to embed or upload. */
    @Getter
    @AllArgsConstructor(access = AccessLevel.PACKAGE)
    public static final class TextureData {
        private final int id;
        /** Null if the pixels could not be encoded; fall back to {@link #getAverageColor()}. */
        @Nullable
        private final byte[] png;
        /**
         * Packed RGB mean of the non transparent texels. Used as a flat stand in
         * when the image itself is unavailable, which is what the old PLY
         * exporter did for every textured face.
         */
        private final int averageColor;
        /** UV units per second, 0 when the texture does not animate. */
        private final float scrollU;
        private final float scrollV;

        public boolean isAnimated() {
            return scrollU != 0f || scrollV != 0f;
        }
    }

    @NonNull
    private final Client client;
    private final Map<Integer, TextureData> cache = new HashMap<>();

    /**
     * Returns the texture, or null when the client has not loaded it yet (its
     * pixels are fetched lazily, so a texture the local player has never had
     * on screen may genuinely be unavailable).
     */
    @Nullable
    public TextureData get(int textureId) {
        if (textureId < 0) {
            return null;
        }
        if (cache.containsKey(textureId)) {
            return cache.get(textureId);
        }

        TextureData data = load(textureId);
        cache.put(textureId, data);
        return data;
    }

    @Nullable
    private TextureData load(int textureId) {
        final int[] pixels;
        try {
            pixels = client.getTextureProvider().load(textureId);
        } catch (RuntimeException e) {
            log.debug("Could not load texture {}", textureId, e);
            return null;
        }

        if (pixels == null || pixels.length == 0) {
            return null;
        }

        // Textures are square; the client uses 128x128 but deriving it keeps
        // this working if that ever changes.
        final int size = (int) Math.round(Math.sqrt(pixels.length));
        if (size * size != pixels.length) {
            log.debug("Texture {} is not square ({} pixels)", textureId, pixels.length);
            return null;
        }

        byte[] png = null;
        try {
            png = encodePng(pixels, size);
        } catch (IOException | RuntimeException e) {
            // Still worth returning the average colour so the model renders as
            // a plausible flat surface rather than grey.
            log.debug("Could not encode texture {}", textureId, e);
        }

        final float[] scroll = scrollOf(textureId);
        return new TextureData(textureId, png, averageColor(pixels), scroll[0], scroll[1]);
    }

    /** Mean of every texel the game actually draws, ignoring transparent ones. */
    private static int averageColor(int[] pixels) {
        long red = 0;
        long green = 0;
        long blue = 0;
        int counted = 0;
        for (int pixel : pixels) {
            if (pixel == 0) {
                continue;
            }
            red += (pixel >> 16) & 0xff;
            green += (pixel >> 8) & 0xff;
            blue += pixel & 0xff;
            counted++;
        }
        if (counted == 0) {
            return 0xffffff;
        }
        return (int) ((red / counted) << 16 | (green / counted) << 8 | (blue / counted));
    }

    /**
     * A pixel of 0 is the game's transparent texel, which the renderer discards
     * rather than drawing black, so it becomes a fully transparent PNG pixel.
     */
    private static byte[] encodePng(int[] pixels, int size) throws IOException {
        final int[] argb = new int[pixels.length];
        for (int i = 0; i < pixels.length; i++) {
            final int rgb = pixels[i];
            argb[i] = rgb == 0 ? 0 : 0xff000000 | rgb;
        }

        final BufferedImage image = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
        image.setRGB(0, 0, size, size, argb, 0, size);

        final ByteArrayOutputStream out = new ByteArrayOutputStream();
        ImageIO.write(image, "png", out);
        return out.toByteArray();
    }

    /**
     * Direction and speed come straight off the texture definition; the mapping
     * from direction to axis matches the client's own
     * {@code TextureManager.computeTextureAnimations}.
     */
    private float[] scrollOf(int textureId) {
        final Texture[] textures = client.getTextureProvider().getTextures();
        if (textures == null || textureId >= textures.length || textures[textureId] == null) {
            return new float[]{0f, 0f};
        }

        final Texture texture = textures[textureId];
        float u = 0f;
        float v = 0f;
        switch (texture.getAnimationDirection()) {
            case 1:
                v = -1f;
                break;
            case 2:
                u = -1f;
                break;
            case 3:
                v = 1f;
                break;
            case 4:
                u = 1f;
                break;
            default:
                return new float[]{0f, 0f};
        }

        final float perSecond = texture.getAnimationSpeed() * TEXTURE_ANIM_UNIT * TICKS_PER_SECOND;
        return new float[]{u * perSecond, v * perSecond};
    }
}

/*
 * Adapted from RuneProfile (github.com/ReinhardtR/runeprofile-plugin),
 * Copyright (c) 2022, Reinhardt Rijna, BSD 2-Clause License (see LICENSE). Exports a game Model as binary glTF so the player's
 * character - equipment included, since the local player's model is composed
 * from what they are wearing - can be rendered outside the client.
 */
package io.droptracker.modelexport;

import lombok.NonNull;
import net.runelite.api.*;

import java.io.*;
import java.util.*;

/**
 * Exports a game {@link Model} as a mesh dump the server turns into a binary
 * glTF (services/player_model_mesh.py). Writing the glTF itself is pure
 * serialisation, so it happens there; this sends exactly what it needs.
 */
public final class GlbExporter {
    private GlbExporter() {
    }

    /** "DTM1": the mesh, then each primitive with its texture (sent once per texture). */
    public static byte[] toBytes(@NonNull Client client, @NonNull Model model,
                                 @NonNull String name) throws IOException {
        return write(ModelMeshBuilder.build(model), new GameTextures(client)::get, name, model.getFaceCount());
    }

    static byte[] write(MeshData mesh, java.util.function.IntFunction<GameTextures.TextureData> textures,
                        String name, int faceCount) throws IOException {
        if (mesh.isEmpty()) {
            throw new IOException("Refusing to write an empty model");
        }
        final ByteArrayOutputStream bytes = new ByteArrayOutputStream();
        final DataOutputStream out = new DataOutputStream(bytes);
        out.writeInt(0x44544d31);
        out.writeUTF(name);
        out.writeInt(faceCount);
        floats(out, mesh.getPositions());
        out.writeInt(mesh.getColors().length);
        out.write(mesh.getColors());
        floats(out, mesh.getUvs());
        floats(out, mesh.getPriorities());
        out.writeInt(mesh.getIndices().length);
        for (int index : mesh.getIndices()) {
            out.writeInt(index);
        }
        floats(out, mesh.getMin());
        floats(out, mesh.getMax());
        out.writeInt(mesh.getPrimitives().size());
        final Set<Integer> sent = new HashSet<>();
        for (MeshData.Primitive p : mesh.getPrimitives()) {
            out.writeInt(p.getTextureId());
            out.writeInt(p.getIndexOffset());
            out.writeInt(p.getIndexCount());
            out.writeBoolean(p.isTranslucent());
            final GameTextures.TextureData t = p.isTextured() ? textures.apply(p.getTextureId()) : null;
            // 0: no texture; 1: its data follows; 2: sent with an earlier primitive
            final int state = t == null ? 0 : sent.add(t.getId()) ? 1 : 2;
            out.writeByte(state);
            if (state == 1) {
                out.writeInt(t.getAverageColor());
                out.writeFloat(t.getScrollU());
                out.writeFloat(t.getScrollV());
                out.writeInt(t.getPng() == null ? -1 : t.getPng().length);
                if (t.getPng() != null) {
                    out.write(t.getPng());
                }
            }
        }
        return bytes.toByteArray();
    }

    private static void floats(DataOutputStream out, float[] values) throws IOException {
        out.writeInt(values == null ? -1 : values.length);
        if (values != null) {
            for (float v : values) {
                out.writeFloat(v);
            }
        }
    }
}

