package io.droptracker.models.submissions;

import java.time.*;
import java.time.format.DateTimeFormatter;
import java.util.*;

import javax.annotation.Nullable;

import lombok.*;

import com.google.gson.annotations.SerializedName;

import io.droptracker.api.DropTrackerUrls;
import okhttp3.HttpUrl;

/// Nested classes for complex JSON structures
@ToString
public class RecentSubmission {
    @SerializedName("player_name")
    @Getter @Setter
    private String playerName;

    @SerializedName("submission_type") // pb, clog, drop  
    @Getter @Setter  
    private String submissionType;  

    @SerializedName("source_name") 
    @Getter @Setter
    private String sourceName;

    @SerializedName("date_received")
    @Getter @Setter
    private String dateReceived;

    @SerializedName("display_name") 
    @Getter @Setter
    private String displayName;

    @SerializedName("value") // if not a pb
    @Getter @Setter
    private String value;

    @SerializedName("data")
    @Getter @Setter
    private List<Map<String, Object>> data;

    /**
     * Path under {@code /img/} of the icon for this submission, e.g.
     * {@code "itemdb/4151.png"}. The API deliberately sends a path rather than a
     * URL — see {@link io.droptracker.api.DropTrackerUrls}.
     */
    @SerializedName("image_path")
    @Getter @Setter
    private String imagePath;

    /** Path under {@code /img/} of the full submission screenshot. */
    @SerializedName("submission_image_path")
    @Getter @Setter
    private String submissionImagePath;

    /** Absolute URL for {@link #imagePath}, or null if absent or malformed. */
    @Nullable
    public HttpUrl imageUrl() {
        return DropTrackerUrls.image(imagePath);
    }

    /** Absolute URL for {@link #submissionImagePath}, or null if absent or malformed. */
    @Nullable
    public HttpUrl submissionImageUrl() {
        return DropTrackerUrls.image(submissionImagePath);
    }

    public String timeSinceReceived() {
        if (dateReceived == null) {
            return "Unknown";
        }
        try {
            DateTimeFormatter formatter = DateTimeFormatter.ISO_DATE_TIME;
            LocalDateTime receivedDate = LocalDateTime.parse(dateReceived, formatter);
            LocalDateTime now = LocalDateTime.now();

            Duration duration = Duration.between(receivedDate, now);

            if (duration.toDays() > 0) {
                return duration.toDays() + " days ago";
            } else if (duration.toHours() > 0) {
                return duration.toHours() + " hours ago"; 
            } else if (duration.toMinutes() > 0) {
                return duration.toMinutes() + " minutes ago";
            } else {
                return "Just now";
            }
        } catch (Exception e) {
            return "Unknown";
        }
    }

    // Generic method to extract data by type and key
    private Object getDataValueByTypeAndKey(String dataType, String key) {
        if (data == null || data.isEmpty()) {
            return null;
        }

        for (Map<String, Object> dataEntry : data) {
            if (dataEntry != null && dataEntry.containsKey("type")) {
                String entryType = dataEntry.get("type").toString();
                if (entryType.equalsIgnoreCase(dataType) && dataEntry.containsKey(key)) {
                    return dataEntry.get(key);
                }
            }
        }
        return null;
    }

    /** The {@code key} of the first {@code dataType} entry, as text, when this is a {@code type} submission. */
    private String dataText(String type, String dataType, String key) {
        if (!submissionType.equalsIgnoreCase(type)) {
            return null;
        }
        Object value = getDataValueByTypeAndKey(dataType, key);
        return value != null ? value.toString() : null;
    }

    /** JSON numbers arrive as Double, and ids sometimes as text like "4151.0". */
    private static Integer toInt(Object value, Integer fallback) {
        if (value == null) {
            return fallback;
        }
        try {
            if (value instanceof Number) {
                return ((Number) value).intValue();
            }
            return Integer.valueOf(value.toString().replaceAll("\\.0*$", ""));
        } catch (NumberFormatException e) {
            return fallback;
        }
    }

    public String getPbTime() {
        return dataText("pb", "best_time", "time");
    }

    public String getDropItemName() {
        return dataText("drop", "item", "name");
    }

    public Integer getDropItemId() {
        return submissionType.equalsIgnoreCase("drop") ? toInt(getDataValueByTypeAndKey("item", "id"), null) : null;
    }

    /** Defaults to 1: the API often leaves quantity out. */
    public Integer getDropQuantity() {
        return submissionType.equalsIgnoreCase("drop") ? toInt(getDataValueByTypeAndKey("item", "quantity"), 1) : null;
    }

    public String getClogItemName() {
        return dataText("clog", "clog_item", "name");
    }

    public Integer getClogItemId() {
        return submissionType.equalsIgnoreCase("clog") ? toInt(getDataValueByTypeAndKey("clog_item", "id"), null) : null;
    }
}

package io.droptracker.models.submissions;

/**
 * Represents the lifecycle status of a ValidSubmission.
 */
public enum SubmissionStatus {
    /** Submission has been created and is about to be sent */
    PENDING("Sending...", "#FFFF00"),
    /** Submission is actively being sent over the network */
    SENDING("Sending...", "#FFFF00"),
    /** Submission was successfully delivered to the server */
    SENT("Sent successfully", "#00FF00"),
    /** Submission is being retried after a failure */
    RETRYING("Retrying...", "#FFFF00"),
    /** Submission was confirmed processed by the API */
    PROCESSED("Processed by API", "#00FF00"),
    /** Submission failed after exhausting retries */
    FAILED("Failed", "#FF0000");

    private final String description;
    private final String hexColor;

    SubmissionStatus(String description, String hexColor) {
        this.description = description;
        this.hexColor = hexColor;
    }

    public String getDescription() {
        return description;
    }

    public String getHexColor() {
        return hexColor;
    }

    /**
     * Whether this status represents a terminal state that should not be automatically retried
     */
    public boolean isTerminal() {
        return this == PROCESSED || this == FAILED;
    }

    /**
     * Whether this status represents an active/in-progress state that should be polled
     */
    public boolean isActive() {
        return this == PENDING || this == SENDING || this == SENT || this == RETRYING;
    }

    /**
     * Whether this submission can be manually retried by the user
     */
    public boolean canRetry() {
        return this == FAILED || this == SENT || this == PENDING;
    }
}

package io.droptracker.models.submissions;

import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import java.util.Arrays;

import io.droptracker.models.CustomWebhookBody;
import lombok.Data;

/**
 * Can represent any type of outgoing submission, such as a drop, pb, clog, ca, etc.
 * ValidSubmissions are created when a user receives something that their registered group(s)
 * have configured to have notifications sent for.
 * <p>
 * We generate an ID when sending data, and store this ID in the ValidSubmission object,
 * so that we can update/track whether the submission arrived at the API and had its notifications
 * processed properly.
 */
@Data
public class ValidSubmission {
    // generated ID
    private String uuid;
    // type of submission
    private SubmissionType type;
    // group ID(s) that the submission should have been sent to
    private String[] groupIds;
    // account hash
    private String accountHash;
    // item ID
    private String itemId;
    // item name
    private String itemName;
    // npc name
    private String npcName;
    // description
    private String description;
    // time since submission was created on the client-side
    private String timeReceived;

    // message or response from the API on initial submission
    private String initialResponse;
    // time that the API responded with a successful processing of the submission
    private String timeProcessedAt;
    // current status of the submission (enum-based)
    private SubmissionStatus status;

    // number of retry attempts made
    private int retryAttempts;

    // last failure reason
    private String lastFailureReason;

    // array of responses from the API on retry attempts
    private String[] retryResponses;

    // Store the entire webhook data for retry functionality
    private CustomWebhookBody originalWebhook;

    // Store screenshot bytes for retry (transient - not persisted to disk)
    private transient byte[] screenshotData;

    // Total value of the submission (used for drops)
    private long totalValue;

    // Default constructor
    public ValidSubmission() {
        this.timeReceived = LocalDateTime.now().format(DateTimeFormatter.ISO_DATE_TIME);
        this.status = SubmissionStatus.PENDING;
        this.groupIds = new String[0];
        this.retryResponses = new String[0];
        this.retryAttempts = 0;
    }

    public ValidSubmission(CustomWebhookBody webhook, String groupId, SubmissionType type) {
        this();
        this.originalWebhook = webhook;
        this.type = type;
        this.groupIds = new String[] {groupId};

        // Extract data from webhook
        extractDataFromWebhook(webhook);
    }

    private void extractDataFromWebhook(CustomWebhookBody webhook) {
        if (webhook != null && webhook.getEmbeds() != null && !webhook.getEmbeds().isEmpty()) {
            CustomWebhookBody.Embed embed = webhook.getEmbeds().get(0);

            // Extract title for description
            if (embed.getTitle() != null) {
                this.description = embed.getTitle();
            }

            // Extract data from fields - process GUID field with highest priority
            String tempGuid = null;

            if (embed.getFields() != null) {
                for (CustomWebhookBody.Field field : embed.getFields()) {
                    String fieldName = field.getName();
                    String fieldValue = field.getValue();

                    if (fieldName != null && fieldValue != null) {
                        switch (fieldName.toLowerCase()) {
                            case "guid":
                                tempGuid = fieldValue;
                                break;
                            case "item":
                            case "item_name":
                                this.itemName = fieldValue;
                                break;
                            case "item_id":
                                this.itemId = fieldValue;
                                break;
                            case "npc":
                            case "npc_name":
                            case "boss":
                            case "source":
                                this.npcName = fieldValue;
                                break;
                            case "account_hash":
                            case "acc_hash":
                            case "player":
                            case "player_name":
                                this.accountHash = fieldValue;
                                break;
                            case "pet_name":
                                if (this.itemName == null) {
                                    this.itemName = fieldValue;
                                }
                                break;
                        }
                    }
                }
                if (tempGuid != null) {
                    this.uuid = tempGuid;
                } 
            }
        }
    }

    public void addGroupId(String groupId) {
        String[] newGroupIds = Arrays.copyOf(groupIds, groupIds.length + 1);
        newGroupIds[groupIds.length] = groupId;
        this.groupIds = newGroupIds;
    }

    /**
     * Mark the submission as failed with a reason
     */
    public void markAsFailed(String reason) {
        this.status = SubmissionStatus.FAILED;
        this.lastFailureReason = reason;
    }

    /**
     * Mark the submission as currently retrying
     */
    public void markAsRetrying() {
        this.status = SubmissionStatus.RETRYING;
        this.retryAttempts++;
    }

    /**
     * Mark the submission as actively sending
     */
    public void markAsSending() {
        this.status = SubmissionStatus.SENDING;
    }

    /**
     * Mark the submission as successfully sent
     */
    public void markAsSuccess() {
        this.status = SubmissionStatus.SENT;
        this.timeProcessedAt = LocalDateTime.now().format(DateTimeFormatter.ISO_DATE_TIME);
    }

    /**
     * Mark the submission as processed by the API.
     * Note: we intentionally do NOT null out originalWebhook here so the user
     * can still manually retry if the "processed" status was incorrect.
     */
    public void markAsProcessed() {
        this.status = SubmissionStatus.PROCESSED;
        this.timeProcessedAt = LocalDateTime.now().format(DateTimeFormatter.ISO_DATE_TIME);
    }

    /**
     * Check if this submission can be retried
     */
    public boolean canRetry() {
        return retryAttempts < 5 && originalWebhook != null && status.canRetry();
    }

    /**
     * Get a human-readable status description
     */
    public String getStatusDescription() {
        if (status == null) {
            return "Unknown";
        }
        switch (status) {
            case FAILED:
                return "Failed" + (lastFailureReason != null ? ": " + lastFailureReason : "");
            case RETRYING:
                return "Retrying... (attempt " + (retryAttempts + 1) + ")";
            default:
                return status.getDescription();
        }
    }

    /**
     * Get a display-friendly label for the submission type
     */
    public String getTypeLabel() {
        if (type == null) {
            return "Submission";
        }
        switch (type) {
            case DROP: return "Drop";
            case KILL_TIME: return "Personal Best";
            case COLLECTION_LOG: return "Collection Log";
            case COMBAT_ACHIEVEMENT: return "Combat Achievement";
            case LEVEL_UP: return "Level Up";
            case QUEST_COMPLETION: return "Quest Completion";
            case EXPERIENCE: return "Experience";
            case EXPERIENCE_MILESTONE: return "Experience Milestone";
            case EXPERIENCE_UPDATE: return "Experience Sync";
            case PET: return "Pet";
            case SLAYER_TASK: return "Slayer Task";
            case ADVENTURE_LOG: return "Adventure Log";
            default: return "Submission";
        }
    }

    /**
     * Get a short label for the submission type (used in the UI type indicator)
     */
    public String getTypeShortLabel() {
        if (type == null) {
            return "SUB";
        }
        switch (type) {
            case DROP: return "DROP";
            case KILL_TIME: return "PB";
            case COLLECTION_LOG: return "CLOG";
            case COMBAT_ACHIEVEMENT: return "CA";
            case LEVEL_UP: return "LVL";
            case QUEST_COMPLETION: return "QST";
            case PET: return "PET";
            case SLAYER_TASK: return "SLAY";
            case EXPERIENCE: return "XP";
            case EXPERIENCE_MILESTONE: return "XP";
            case EXPERIENCE_UPDATE: return "XP";
            case ADVENTURE_LOG: return "LOG";
            default: return "SUB";
        }
    }

    /**
     * Get a single-line display text for this submission
     */
    public String getDisplayText() {
        String name = itemName;
        if (name == null || name.trim().isEmpty()) {
            name = description;
        }
        if (name == null || name.trim().isEmpty()) {
            name = "Unknown";
        }
        return getTypeLabel() + ": " + name;
    }
}

