package io.droptracker.service;

import lombok.RequiredArgsConstructor;
import com.google.inject.*;
import io.droptracker.*;
import io.droptracker.api.DropTrackerApi;
import io.droptracker.models.CustomWebhookBody;
import io.droptracker.models.api.GroupConfig;
import io.droptracker.models.submissions.SubmissionType;
import io.droptracker.util.*;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.clan.ClanChannel;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.util.Text;

import java.util.*;
import java.nio.charset.StandardCharsets;
import java.security.*;
import java.util.regex.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicBoolean;

/**
 * Relays clan chat to the DropTracker for the clan features:
 * <ul>
 *   <li>{@code CLAN_MESSAGE} system broadcasts ("X received a drop: ...") as
 *       {@code clan_broadcast} submissions — server-side parsing tracks
 *       clanmates who don't run the plugin;</li>
 *   <li>{@code CLAN_CHAT} player lines as {@code clan_chat} submissions — the
 *       game→Discord half of the two-way chat bridge.</li>
 * </ul>
 *
 * On by default (Clan chat sync), but nothing leaves the client unless the
 * clan the player is in has been set up on droptracker.io — see
 * {@link #clanOptedIn(boolean)}. The server enforces the same rule again.
 *
 * The plugin stays a dumb pipe on purpose: no game-message parsing happens
 * client-side, so pattern fixes never wait on a plugin-hub review. Lines are
 * batched (2s debounce, capped batch) into one payload, and each embed
 * carries the standard relayer identity fields — the server authenticates the
 * RELAYER and dedupes across multiple relaying clanmates, so this can be
 * enabled by any number of members safely.
 *
 * Muted clanmates: the game prints a muted player's clan chat only on their
 * own screen. Their own lines are relayed marked {@code self}, the server
 * works out from who else reported them which ones nobody saw, and sends
 * those back to this client as {@code clan_chat_muted} envelopes, shown by
 * {@link #showMutedLine} with a muted icon by the name.
 *
 * Rides whichever transport the player uses: the API, or our Discord
 * webhooks, which the server's webhook bot reads. Only the Discord→game
 * direction needs the API, because it polls our server for lines.
 */
@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class ClanRelayService {

    private static final int FLUSH_DELAY_SECONDS = 2;
    private static final int MAX_LINES_PER_FLUSH = 10;
    /** Backstop so a pathological chat flood can't grow the queue unbounded. */
    private static final int MAX_QUEUED_LINES = 200;
    private static final int MAX_MESSAGE_CHARS = 250;

    /** A chat icon tag in a sender name, e.g. {@code <img=2>} for an ironman. */
    private static final Pattern ICON_TAG = Pattern.compile("<img=(\\d+)>");

    /** Game-mode badges by {@code IconID}, as the server's wire strings. */
    private static final Map<Integer, String> ACCOUNT_ICONS = Map.of(
        2, "ironman", 3, "ultimate_ironman", 10, "hardcore_ironman",
        41, "group_ironman", 42, "hardcore_group_ironman", 43, "unranked_group_ironman");

    /** How long a delivered or rendered clan chat line is remembered. */
    private static final long LINE_MEMORY_MS = TimeUnit.SECONDS.toMillis(90);
    private static final int MAX_REMEMBERED_LINES = 200;

    private final Client client;
    private final DropTrackerConfig config;
    private final DropTrackerApi api;
    private final DropTrackerPlugin plugin;
    private final SubmissionManager submissionManager;
    private final ScheduledExecutorService executor;
    private final ClientThread clientThread;
    private final ChatMessageUtil chatMessageUtil;

    /** Clan chat lines the game delivered (client thread only). */
    private final Map<String, Long> heardLines = new LinkedHashMap<>();
    /** Muted clanmates' lines this client rendered (client thread only). */
    private final Map<String, Long> injectedLines = new LinkedHashMap<>();

    private final ConcurrentLinkedQueue<PendingLine> queue = new ConcurrentLinkedQueue<>();
    private final AtomicBoolean flushScheduled = new AtomicBoolean(false);

    /**
     * The clan channel the local player currently sits in, maintained from
     * the client thread (ClanChannelChanged + relay call sites). Volatile so
     * the notification poller can attach it to presence heartbeats without
     * touching client state off-thread.
     */
    private volatile String currentClanName = null;

    /** How long the published opted-in clan list is trusted before a refetch. */
    private static final long PUBLISHED_CLANS_TTL_MS = TimeUnit.MINUTES.toMillis(10);

    /**
     * Opted-in clans from GitHub Pages ({@code hash -> "b"|"t"|"bt"}), the gate
     * for webhook-only clients. Null until the first successful fetch, and
     * then nothing is relayed.
     */
    private volatile Map<String, String> publishedClans = null;
    private volatile long publishedClansFetchedAt = 0L;
    private final AtomicBoolean publishedClansLoading = new AtomicBoolean(false);

    /** Called from the client thread whenever the clan channel changes. */
    public void updateClanChannel(ClanChannel channel) {
        currentClanName = channel != null ? Text.removeTags(channel.getName()) : null;
    }

    /** The current clan's name, or null when not in a clan. Thread-safe. */
    public String getCurrentClanName() {
        return currentClanName;
    }

    /**
     * Whether the Discord→game direction should be live (poll + display).
     * The one part that still needs the API: Discord lines reach the client
     * by polling our server, which a webhook-only client never contacts.
     */
    public boolean discordChatActive() {
        return config.useApi() && config.clanChatSync() && config.receiveDiscordChat()
            && clanOptedIn(true);
    }

    /**
     * The server's clan comparison key ({@code utils/clan_broadcasts.clan_slug}):
     * markup stripped, '-', '_' and non-breaking spaces folded to a space,
     * whitespace collapsed, lowercased.
     */
    static String clanSlug(String clanName) {
        if (clanName == null) {
            return "";
        }
        String s = Text.removeTags(clanName)
            .replace('\u00A0', ' ').replace('-', ' ').replace('_', ' ')
            .trim().replaceAll("\\s+", " ");
        return s.toLowerCase(Locale.ROOT);
    }

    /**
     * Whether one of the player's OWN groups has set up the clan they are in.
     *
     * <p>This is the privacy line for a setting that is on by default: a
     * player whose groups don't use the clan features, or who isn't in a
     * clan, sends nothing at all. Chat lines need a group running the Discord
     * bridge; broadcasts also go to a group that only tracks them. The group
     * list refreshes every couple of minutes, so a group switching a feature
     * on or off is picked up without a relog (the server drops anything that
     * arrives in between).</p>
     */
    boolean clanOptedIn(boolean chatLine) {
        if (config.useApi()) {
            return clanOptedIn(currentClanName, api.getGroupConfigs(), chatLine);
        }
        // Webhook-only: the group configs need the API, which this client may
        // not contact. Check the clan against the published list instead.
        refreshPublishedClansIfStale();
        return clanInPublishedList(currentClanName, publishedClans, chatLine);
    }

    /**
     * Whether the published list opts this clan in. Same rule as the group
     * check: chat needs a bridging group ({@code b}); broadcasts also go to a
     * tracking-only one ({@code t}).
     */
    static boolean clanInPublishedList(String clan, Map<String, String> published, boolean chatLine) {
        if (clan == null || published == null || published.isEmpty()) {
            return false;
        }
        String slug = clanSlug(clan);
        if (slug.isEmpty()) {
            return false;
        }
        String mode = published.get(publishedHash(slug));
        if (mode == null) {
            return false;
        }
        return mode.contains("b") || (!chatLine && mode.contains("t"));
    }

    /** First 16 hex chars of sha256(slug) (server: clan_relay_gate.published_hash). */
    static String publishedHash(String slug) {
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256")
                .digest(slug.getBytes(StandardCharsets.UTF_8));
            StringBuilder hex = new StringBuilder();
            for (int i = 0; i < 8; i++) {
                hex.append(String.format("%02x", digest[i]));
            }
            return hex.toString();
        } catch (NoSuchAlgorithmException e) {
            return "";
        }
    }

    /** Refetch the published list off-thread when it is missing or stale. */
    private void refreshPublishedClansIfStale() {
        long now = System.currentTimeMillis();
        if (publishedClans != null && now - publishedClansFetchedAt < PUBLISHED_CLANS_TTL_MS) {
            return;
        }
        // A failed fetch retries no sooner than a minute later.
        if (now - publishedClansFetchedAt < TimeUnit.MINUTES.toMillis(1)
            || !publishedClansLoading.compareAndSet(false, true)) {
            return;
        }
        publishedClansFetchedAt = now;
        executor.execute(() -> {
            try {
                Map<String, String> fetched = api.fetchClanChatClans();
                if (fetched != null) {
                    publishedClans = fetched;
                }
            } finally {
                publishedClansLoading.set(false);
            }
        });
    }

    static boolean clanOptedIn(String clan, List<GroupConfig> configs, boolean chatLine) {
        if (clan == null) {
            return false;
        }
        if (configs == null || configs.isEmpty()) {
            return false;
        }
        String slug = clanSlug(clan);
        if (slug.isEmpty()) {
            return false;
        }
        for (GroupConfig group : configs) {
            if (group == null || !slug.equals(group.getClanChatSlug())) {
                continue;
            }
            if (group.isClanChatBridge() || (!chatLine && group.isClanBroadcastTracking())) {
                return true;
            }
        }
        return false;
    }

    /**
     * A CLAN_MESSAGE system broadcast (already tag-sanitized by the caller).
     * Broadcasts feed both the Discord bridge (they are part of the chat box)
     * and broadcast tracking, under the one Clan chat sync setting.
     */
    public void onClanBroadcast(String message) {
        if (!config.clanChatSync()) {
            return;
        }
        queueLine(new PendingLine(SubmissionType.CLAN_BROADCAST, null, message));
    }

    /**
     * The game mode a chat line's sender badge shows, as the server's wire
     * string ({@code utils/account_types.py}). The game draws the badge as an
     * icon tag in the name, so this covers every clanmate, plugin or not.
     * No badge reads as {@code normal}.
     */
    static String accountTypeFromName(String rawName) {
        if (rawName == null) {
            return null;
        }
        Matcher m = ICON_TAG.matcher(rawName);
        while (m.find()) {
            // Anything else is a moderator crown, a league icon, ...
            String type = ACCOUNT_ICONS.get(Integer.parseInt(m.group(1)));
            if (type != null) {
                return type;
            }
        }
        return "normal";
    }

    /**
     * A CLAN_CHAT player line (sender may still carry icon tags).
     *
     * <p>Discord lines the bridge renders locally arrive here too —
     * {@code client.addChatMessage} posts a real {@code ChatMessage}, so the
     * Discord→game direction feeds straight back into the game→Discord one.
     * Unguarded that echoes every Discord message back into the channel it
     * was typed in, so lines wearing {@link
     * ChatMessageUtil#DISCORD_SENDER_MARKER} stop here, and so do muted
     * clanmates' lines from {@link #showMutedLine}, which the server already
     * has.</p>
     */
    public void onClanChat(String senderName, String message) {
        String sender = senderName != null ? Text.removeTags(Text.toJagexName(senderName)).trim() : "";
        if (sender.isEmpty()) {
            return;
        }
        String key = lineKey(sender, message);
        if (injectedLines.remove(key) != null) {
            return;
        }
        remember(heardLines, key);
        if (!config.clanChatSync() || ChatMessageUtil.isDiscordBridgeSender(sender)) {
            return;
        }
        PendingLine line = new PendingLine(SubmissionType.CLAN_CHAT, sender, message);
        line.accountType = accountTypeFromName(senderName);
        // A muted player's own line is printed only on their screen; the
        // server tells those apart by who else reports them.
        line.self = client.getLocalPlayer() != null
            && sender.equalsIgnoreCase(Text.toJagexName(client.getLocalPlayer().getName()));
        queueLine(line);
    }

    /**
     * A muted clanmate's line that the game never delivered here, shown as
     * their clan chat with a muted icon. Dropped if the game did deliver it
     * after all, or if this player ignores them, as the game would.
     */
    public void showMutedLine(String sender, String message, String accountType) {
        clientThread.invokeLater(() -> {
            String key = lineKey(sender, message);
            Long heard = heardLines.get(key);
            if ((heard != null && System.currentTimeMillis() - heard <= LINE_MEMORY_MS)
                || (client.getIgnoreContainer() != null && client.getIgnoreContainer().findByName(sender) != null)) {
                return;
            }
            int icon = -1;
            for (Map.Entry<Integer, String> e : ACCOUNT_ICONS.entrySet()) {
                if (e.getValue().equals(accountType)) {
                    icon = e.getKey();
                }
            }
            remember(injectedLines, key);
            if (!chatMessageUtil.sendMutedClanMessage(sender, message, icon)) {
                injectedLines.remove(key);
            }
        });
    }

    /** Sender and text as both copies of one line compare (case, tags, spacing folded). */
    static String lineKey(String sender, String message) {
        return (Text.toJagexName(Text.removeTags(sender)) + "|" + Text.removeTags(message == null ? "" : message))
            .replace('\u00A0', ' ').trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
    }

    private static void remember(Map<String, Long> lines, String key) {
        long now = System.currentTimeMillis();
        lines.values().removeIf(t -> now - t > LINE_MEMORY_MS);
        if (lines.size() >= MAX_REMEMBERED_LINES) {
            lines.remove(lines.keySet().iterator().next());
        }
        lines.put(key, now);
    }

    private void queueLine(PendingLine line) {
        refreshClanNameFromClient();
        if (currentClanName == null || line.message == null || line.message.trim().isEmpty()) {
            return;
        }
        if (!clanOptedIn(line.type == SubmissionType.CLAN_CHAT)) {
            return;
        }
        if (queue.size() >= MAX_QUEUED_LINES) {
            return;
        }
        line.clanName = currentClanName;
        String trimmed = line.message.trim();
        line.message = trimmed.length() > MAX_MESSAGE_CHARS
            ? trimmed.substring(0, MAX_MESSAGE_CHARS) : trimmed;
        queue.add(line);
        if (flushScheduled.compareAndSet(false, true)) {
            executor.schedule(this::flush, FLUSH_DELAY_SECONDS, TimeUnit.SECONDS);
        }
    }

    /** Chat events arrive on the client thread, so this read is safe here. */
    private void refreshClanNameFromClient() {
        ClanChannel channel = client.getClanChannel();
        currentClanName = channel != null ? Text.removeTags(channel.getName()) : null;
    }

    private void flush() {
        flushScheduled.set(false);
        try {
            List<PendingLine> lines = new ArrayList<>(MAX_LINES_PER_FLUSH);
            PendingLine next;
            while (lines.size() < MAX_LINES_PER_FLUSH && (next = queue.poll()) != null) {
                lines.add(next);
            }
            if (lines.isEmpty()) {
                return;
            }
            // One webhook per submission type so SubmissionManager's per-type
            // dispatch stays uniform; a mixed 2s window is two payloads.
            sendBatch(lines, SubmissionType.CLAN_BROADCAST);
            sendBatch(lines, SubmissionType.CLAN_CHAT);
        } catch (Exception e) {
            log.debug("Clan relay flush failed: {}", e.getMessage());
        } finally {
            // Anything still queued (overflow past the batch cap, or lines
            // added mid-flush) gets its own pass.
            if (!queue.isEmpty() && flushScheduled.compareAndSet(false, true)) {
                executor.schedule(this::flush, FLUSH_DELAY_SECONDS, TimeUnit.SECONDS);
            }
        }
    }

    private void sendBatch(List<PendingLine> lines, SubmissionType type) {
        /* The relayer's own identity is what the server authenticates the batch
           against, and it rejects a batch without one. Flushing happens off the
           client thread, so an unreadable name here is routine — resolve it the
           same way submissions do, and drop the batch rather than relay it
           anonymously or under an invented name. */
        String relayerName = PlayerIdentity.resolve(
            plugin.getLocalPlayerName(),
            String.valueOf(client.getAccountHash()),
            config.lastAccountName(),
            config.lastAccountHash());
        if (relayerName == null) {
            log.debug("Skipping clan relay batch: no resolvable player name");
            return;
        }

        CustomWebhookBody webhook = null;
        for (PendingLine line : lines) {
            if (line.type != type) {
                continue;
            }
            if (webhook == null) {
                webhook = new CustomWebhookBody();
                webhook.setContent("DropTracker Clan Relay");
            }
            CustomWebhookBody.Embed embed = new CustomWebhookBody.Embed();
            embed.setTitle("Clan relay");
            embed.addField("type", type == SubmissionType.CLAN_BROADCAST ? "clan_broadcast" : "clan_chat", true);
            embed.addField("clan_name", line.clanName, true);
            embed.addField("message", line.message, false);
            if (line.sender != null) {
                embed.addField("sender", line.sender, true);
            }
            if (line.accountType != null) {
                embed.addField("account_type", line.accountType, true);
            }
            if (line.self) {
                embed.addField("self", "true", true);
            }
            embed.addField("player_name", relayerName, true);
            embed.addField("acc_hash", String.valueOf(client.getAccountHash()), true);
            embed.addField("p_v", plugin.pluginVersion != null ? plugin.pluginVersion : "unknown", true);
            embed.addField("guid", api.generateGuidForSubmission(), true);
            webhook.getEmbeds().add(embed);
        }
        if (webhook != null) {
            submissionManager.sendDataToDropTracker(webhook, type);
        }
    }

    private static final class PendingLine {
        private final SubmissionType type;
        private final String sender;
        private String clanName;
        private String message;
        private String accountType;
        private boolean self;

        private PendingLine(SubmissionType type, String sender, String message) {
            this.type = type;
            this.sender = sender;
            this.message = message;
        }
    }
}

package io.droptracker.service;

import lombok.RequiredArgsConstructor;
import javax.inject.*;

import io.droptracker.DropTrackerConfig;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;
import net.runelite.api.events.*;
import net.runelite.api.gameval.*;
import net.runelite.client.eventbus.*;

/**
 * Reads the player's <em>entire</em> collection log when they open it.
 *
 * <p>The client API does not expose collection log contents; the game only sends
 * them when the interface asks. The technique here — open the log, invoke its
 * "Search" operation so the server transmits every slot, then re-run the init
 * script to put the interface back — comes from WikiSync
 * (github.com/weirdgloop/WikiSync), Copyright (c) 2021, andmcadams,
 * BSD 2-Clause License (see LICENSE), by way of RuneProfile.
 *
 * <p>Why it matters: without a full read we can only ever know about items that
 * dropped while the plugin was running, so a player's collection log page would
 * start empty on the day they installed and slowly fill in. One open of the log
 * backfills everything they have ever obtained.
 *
 * <p><b>The adventure log guard is not optional.</b> A player viewing someone
 * else's collection log through a POH adventure log receives that player's slots
 * through the very same script. Storing those would silently overwrite the
 * viewer's collection log with a stranger's, so any hint of adventure-log
 * viewing discards everything accumulated.
 */
@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class CollectionLogScraper {

	/**
	 * Fired once per <em>obtained</em> collection log slot, carrying
	 * (itemId, quantity).
	 *
	 * <p>Obtained only — the interface draws every slot on a page greyed out
	 * before the server transmits anything, and this script is what un-greys the
	 * ones the player has. So a complete read cannot tell us which slots
	 * <em>exist</em>, only which are filled; the slot list has to come from the
	 * cache instead (see {@link CollectionLogSlots}). WikiSync sets one bit per
	 * firing with no quantity check and publishes the result as a player's
	 * obtained items, which is the practical proof.
	 */
	private static final int COLLECTION_DELAYED_TRANSMIT = 4100;
	/** Fired when the collection log interface finishes building. */
	private static final int COLLECTION_LOG_SETUP = 7797;
	/** Rebuilds the interface, which closes the search we opened. */
	private static final int COLLECTION_INIT = 2240;

	/**
	 * Ticks of silence after the last slot before the read is considered done.
	 * The slots arrive over several ticks, so "no more for a couple of ticks" is
	 * the only completion signal available.
	 */
	private static final int QUIET_TICKS_UNTIL_COMPLETE = 2;

	private final EventBus eventBus;
	private final Client client;
	private final DropTrackerConfig config;
	private final StateSyncService stateSyncService;
	private final StateSyncScheduler stateSyncScheduler;

	/** Tick the last slot arrived on, or -1 when no read is in progress. */
	private int lastTransmitTick = -1;

	/** True while we are driving the interface, so our own init does not re-trigger us. */
	private boolean selfTriggered = false;

	public void startUp() {
		eventBus.register(this);
	}

	public void shutDown() {
		eventBus.unregister(this);
		reset();
	}

	private void reset() {
		lastTransmitTick = -1;
		selfTriggered = false;
	}

	private boolean isEnabled() {
		return config.useApi() && config.syncAccountState() && stateSyncService.isEnabled();
	}

	/** True when the open log belongs to another player (POH adventure log). */
	private boolean isViewingSomeoneElse() {
		return client.getVarbitValue(VarbitID.COLLECTION_POH_HOST_BOOK_OPEN) == 1;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event) {
		GameState state = event.getGameState();
		if (state != GameState.LOGGED_IN && state != GameState.HOPPING) {
			reset();
		}
	}

	/**
	 * Asks the game to transmit every slot once the log has been opened.
	 *
	 * <p>The "Search" operation is what makes the server send the full contents;
	 * re-running the init script immediately afterwards restores the normal view
	 * so the player does not find their search box mysteriously open.
	 */
	@Subscribe
	public void onScriptPostFired(ScriptPostFired event) {
		if (event.getScriptId() != COLLECTION_LOG_SETUP || !isEnabled()) {
			return;
		}

		if (isViewingSomeoneElse()) {
			stateSyncService.clearItems();
			return;
		}

		// Our own init call re-fires setup; without this we would loop.
		if (selfTriggered) {
			return;
		}
		selfTriggered = true;

		client.menuAction(-1, InterfaceID.Collection.SEARCH_TOGGLE, MenuAction.CC_OP, 1, -1, "Search", null);
		client.runScript(COLLECTION_INIT);
	}

	/** Collects one slot per firing. */
	@Subscribe
	public void onScriptPreFired(ScriptPreFired event) {
		if (event.getScriptId() != COLLECTION_DELAYED_TRANSMIT || !isEnabled()) {
			return;
		}

		if (isViewingSomeoneElse()) {
			return;
		}

		Object[] args = event.getScriptEvent() == null ? null : event.getScriptEvent().getArguments();
		if (args == null || args.length < 3) {
			return;
		}

		try {
			int itemId = (int) args[1];
			int quantity = (int) args[2];
			stateSyncService.storeItem(itemId, quantity);
			lastTransmitTick = client.getTickCount();
		} catch (ClassCastException e) {
			log.debug("Unexpected collection log script arguments: {}", e.toString());
		}
	}

	/**
	 * Detects the end of a read and schedules a sync.
	 *
	 * <p>Only a read that ran to completion marks the item set as complete —
	 * that flag is what tells the server the absence of an item means "not
	 * obtained" rather than "not seen yet".
	 */
	@Subscribe
	public void onGameTick(GameTick event) {
		if (lastTransmitTick == -1) {
			return;
		}
		if (client.getTickCount() <= lastTransmitTick + QUIET_TICKS_UNTIL_COMPLETE) {
			return;
		}

		lastTransmitTick = -1;
		selfTriggered = false;

		if (isViewingSomeoneElse()) {
			stateSyncService.clearItems();
			return;
		}

		stateSyncService.markClogComplete();
		stateSyncScheduler.scheduleRapid("clog");
	}

	/**
	 * Fail-safe: if the adventure log opens at any point, drop everything.
	 *
	 * <p>The checks above cover the ordinary paths, but the cost of being wrong
	 * here is attributing another player's collection log to this account, so it
	 * is worth catching the varbit directly as well.
	 */
	@Subscribe
	public void onVarbitChanged(VarbitChanged event) {
		if (event.getVarbitId() == VarbitID.COLLECTION_POH_HOST_BOOK_OPEN && isViewingSomeoneElse()) {
			log.debug("Adventure log opened; discarding accumulated collection log items");
			stateSyncService.clearItems();
			reset();
		}
	}
}

package io.droptracker.service;

import lombok.RequiredArgsConstructor;
import java.util.*;

import javax.inject.*;

import lombok.extern.slf4j.Slf4j;
import org.jetbrains.annotations.VisibleForTesting;
import net.runelite.api.*;
import net.runelite.client.game.ItemManager;

/**
 * Which item ids the collection log actually has slots for, read from the cache.
 *
 * <p>Needed because a collection log <em>unlock</em> reaches us as a chat
 * message carrying only the item's name, and a name does not identify an item.
 * {@link io.droptracker.util.ItemIDSearch} answers with the earliest id sharing
 * that name, which for a duplicated name is the wrong one: the collection log's
 * Coal bag is 25627, the item cache says 764. Recording the wrong id leaves the
 * slot looking unfilled on the player's profile, and puts an id that is not a
 * slot into the account's item map.
 *
 * <p>The cache states the answer outright. Walking it costs one pass over five
 * structs and their page enums:
 *
 * <pre>
 *   enum 2102         -> the five tab structs
 *   tab struct  p683  -> enum of page structs
 *   page struct p690  -> enum of item ids
 *   enum 3721         -> id replacements
 * </pre>
 *
 * <p><b>Enum 3721 is not optional.</b> A dozen slots are stored against one id
 * and drawn as another — the Coal bag's page entry is 12019, the log draws
 * 25627 — and the game remaps through 3721 before drawing, so the replaced id
 * is what the collection log reports and what the server stores.
 *
 * <p>The walk comes from WikiSync (github.com/weirdgloop/WikiSync), Copyright
 * (c) 2021, andmcadams, BSD 2-Clause License (see LICENSE), which reads the same
 * enums for the same reason.
 */
@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class CollectionLogSlots {

	/** Enum holding the collection log's top level tab structs. */
	private static final int TAB_ENUM = 2102;
	/** Tab struct param: the enum of page structs under that tab. */
	private static final int PARAM_TAB_PAGES = 683;
	/** Page struct param: the enum of item ids on that page. */
	private static final int PARAM_PAGE_ITEMS = 690;
	/** Enum mapping a page's stored item id onto the id the log draws. */
	private static final int REPLACEMENT_ENUM = 3721;

	private final Client client;
	private final ItemManager itemManager;

	/** Every slot id, or empty until the first successful read. */
	private Set<Integer> slotIds = new HashSet<>();

	/**
	 * Slot name -> id, built only when a lookup by name is actually needed.
	 *
	 * <p>Names that belong to more than one slot map to null: every Graceful
	 * piece and all the decorative armour exist several times over, and a chat
	 * message naming one cannot say which was unlocked.
	 */
	private Map<String, Integer> slotByName = null;

	/** Drops the cached read, so a new session re-reads the cache. */
	public void reset() {
		slotIds = new HashSet<>();
		slotByName = null;
	}

	/**
	 * The id the collection log records for a newly unlocked item.
	 *
	 * <p>Must be called on the client thread. Returns {@code candidate} when it
	 * is already a slot, the right slot when the candidate is a same-named
	 * impostor, and null when neither is true — an unknown name, or one that
	 * several slots share. Null means "do not record this": the next full read
	 * of the log reports the slot properly, so guessing here would only write
	 * something wrong in the meantime.
	 */
	public Integer resolve(Integer candidate, String itemName) {
		if (!load()) {
			// Without the cache there is nothing to check against; the caller's
			// candidate is as good as it gets.
			return candidate;
		}
		return resolve(candidate, itemName, slotIds, byName());
	}

	/**
	 * The rule itself, separated from the cache read so it can be tested.
	 *
	 * <p>{@code slotByName} maps a lowercased slot name onto its id, with names
	 * shared by several slots mapped to null — see {@link #indexByName}.
	 */
	@VisibleForTesting
	static Integer resolve(Integer candidate, String itemName,
	                       Set<Integer> slotIds, Map<String, Integer> slotByName) {
		if (candidate != null && slotIds.contains(candidate)) {
			return candidate;
		}
		if (itemName == null || itemName.trim().isEmpty()) {
			return null;
		}
		return slotByName.get(itemName.trim().toLowerCase());
	}

	/**
	 * Lowercased slot name -> its id, with ambiguous names mapped to null.
	 *
	 * <p>Null rather than absent so the distinction survives: a name several
	 * slots share is one we must refuse to answer, not one we have never seen.
	 * Every Graceful piece and all the decorative armour land here.
	 */
	@VisibleForTesting
	static Map<String, Integer> indexByName(Map<Integer, String> namesById) {
		Map<String, Integer> byName = new HashMap<>();
		for (Map.Entry<Integer, String> entry : namesById.entrySet()) {
			String name = entry.getValue();
			if (name == null || name.isEmpty() || "null".equals(name)) {
				continue;
			}
			String key = name.toLowerCase();
			byName.put(key, byName.containsKey(key) ? null : entry.getKey());
		}
		return byName;
	}

	/** True once the slot ids have been read. Must be on the client thread. */
	public boolean load() {
		if (!slotIds.isEmpty()) {
			return true;
		}
		if (client.getGameState() != GameState.LOGGED_IN) {
			// The cache is only reliably readable once the client has loaded.
			return false;
		}

		try {
			Map<Integer, Integer> replacements = new HashMap<>();
			EnumComposition replacementEnum = client.getEnum(REPLACEMENT_ENUM);
			if (replacementEnum != null) {
				int[] keys = replacementEnum.getKeys();
				int[] values = replacementEnum.getIntVals();
				for (int i = 0; i < keys.length && i < values.length; i++) {
					replacements.put(keys[i], values[i]);
				}
			}

			Set<Integer> found = new HashSet<>();
			for (int tabStructId : client.getEnum(TAB_ENUM).getIntVals()) {
				StructComposition tabStruct = client.getStructComposition(tabStructId);
				for (int pageStructId : client.getEnum(tabStruct.getIntValue(PARAM_TAB_PAGES)).getIntVals()) {
					StructComposition pageStruct = client.getStructComposition(pageStructId);
					for (int itemId : client.getEnum(pageStruct.getIntValue(PARAM_PAGE_ITEMS)).getIntVals()) {
						found.add(replacements.getOrDefault(itemId, itemId));
					}
				}
			}

			if (found.isEmpty()) {
				log.debug("Collection log structure read produced no slots");
				return false;
			}
			slotIds = found;
			log.debug("Read {} collection log slots from the cache", found.size());
			return true;
		} catch (Exception e) {
			// A cache the client has not loaded, or an enum that moved in a game
			// update. Neither is worth failing an unlock over.
			log.debug("Could not read the collection log structure: {}", e.toString());
			return false;
		}
	}

	/** Lazily names every slot; only an unrecognised id ever needs this. */
	private Map<String, Integer> byName() {
		if (slotByName != null) {
			return slotByName;
		}
		Map<Integer, String> namesById = new HashMap<>();
		for (int itemId : slotIds) {
			try {
				ItemComposition composition = itemManager.getItemComposition(itemId);
				namesById.put(itemId, composition == null ? null : composition.getName());
			} catch (Exception e) {
				log.debug("Could not name collection log slot {}: {}", itemId, e.toString());
			}
		}
		slotByName = indexByName(namesById);
		return slotByName;
	}
}

package io.droptracker.service;

import io.droptracker.DropTrackerConfig;
import io.droptracker.api.DropTrackerApi;
import io.droptracker.models.*;
import io.droptracker.models.api.*;
import io.droptracker.util.*;
import lombok.*;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.util.Text;
import okhttp3.Call;

import javax.annotation.Nullable;
import javax.inject.*;
import java.time.*;
import java.time.format.DateTimeParseException;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicBoolean;

/**
 * In-game event notifications + HUD state (EVENT_PLUGIN_NOTIFICATIONS_PLAN P2).
 *
 * Long-polls GET /notifications?wait={@value #LONG_POLL_WAIT_SECONDS} while
 * the server reports a live event tracking this player (the
 * {@code active_event} flag in the group configs / notifications response):
 * the server holds an empty-inbox request open until a notification lands,
 * so delivery is near-immediate, and each completed request immediately
 * re-issues the next. Servers that predate the {@code wait} param (no
 * {@code long_poll: true} in the response) fall back to a fixed
 * {@value #POLL_INTERVAL_SECONDS}s poll. The held call runs on OkHttp's own
 * dispatcher via enqueue — the shared client executor is only ever used to
 * schedule the next cycle, never blocked through a hold. Each typed envelope
 * dispatches through a hardcoded renderer registry (unknown types are
 * dropped silently — the forward-compatibility contract), and the service
 * keeps the {@code /event_state} snapshot the HUD and Events tab render.
 *
 * Stacking rules: envelopes are processed per poll as one batch, grouped by
 * event — at most ONE pop-up per batch (coalesced across events, headlined by
 * the most important update), chat collapses beyond
 * {@value #MAX_CHAT_LINES_PER_EVENT} lines per event, a seen-id LRU guards
 * against replays, and at most one state refresh runs per batch. Pop-ups are
 * additionally deduped by (event, task, type) for
 * {@value #TOAST_DEDUPE_WINDOW_MS}ms across batches, and their lifetime and
 * styling follow the envelope's {@code priority} tier.
 */
@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class EventNotificationService {
    /** Fallback poll cadence for legacy servers that ignore the wait param. */
    static final int POLL_INTERVAL_SECONDS = 10;
    /** Requested server-side hold per long-poll (the server clamps to its cap). */
    static final int LONG_POLL_WAIT_SECONDS = 25;
    /** Pause between held polls so a busy inbox can't turn into a hot loop. */
    private static final long REISSUE_DELAY_MS = 250;
    /**
     * An allegedly-held poll that returns empty this fast wasn't actually
     * held (misbehaving proxy/server); use the legacy cadence for that cycle.
     */
    private static final long SUSPICIOUS_FAST_EMPTY_MS = 1500;
    private static final long MAX_FAILURE_BACKOFF_MS = 60_000L;
    private static final int SEEN_IDS_MAX = 200;
    private static final int MAX_CHAT_LINES_PER_EVENT = 3;
    private static final int MAX_TOASTS_QUEUED = 6;
    /**
     * A pop-up about the same (event, task, type) inside this window is the
     * same update to a human — a task ticking twice in a breath (two players
     * feeding it, a re-drain) must not queue twice.
     */
    static final long TOAST_DEDUPE_WINDOW_MS = 10_000L;
    private static final int TOAST_KEYS_MAX = 32;
    /** Re-check the active_event flag this often when idle (no live event). */
    private static final int IDLE_RECHECK_SECONDS = 60;
    /** Recheck cadence for a 404 (identity not registered) — terminal-ish. */
    private static final long NOT_REGISTERED_RECHECK_MS =
        TimeUnit.MINUTES.toMillis(10);
    private static final int MAX_TEXT_LENGTH = 120;

    private final DropTrackerConfig config;
    private final DropTrackerApi api;
    private final ChatMessageUtil chatMessageUtil;
    private final Client client;
    private final ScheduledExecutorService executor;
    private final ConfigManager configManager;
    private final ClanRelayService clanRelayService;

    /** Next scheduled poll cycle; guarded by {@code this}. */
    private ScheduledFuture<?> pollTask;
    private final AtomicBoolean running = new AtomicBoolean(false);
    /** Set while a cycle (including its in-flight HTTP call) owns the chain. */
    private final AtomicBoolean cycleInFlight = new AtomicBoolean(false);
    @Nullable
    private volatile Call inFlightCall;
    /** Only mutated by the single in-flight cycle chain. */
    private volatile int consecutiveFailures = 0;
    /** Cleared when a wait-request comes back without long_poll=true. */
    private volatile boolean serverSupportsLongPoll = true;
    /**
     * Last server-reported active_event. Authoritative over the cached group
     * config for choosing the wait mode: the config cache refreshes on
     * login/XP/submission (all throttled) and NEVER for an idle player, so
     * when an event went live the plugin used to keep sending plain polls —
     * which reissued at {@link #REISSUE_DELAY_MS} — a permanent ~4 req/s hot
     * loop exactly at event start (audit P0-2).
     */
    private volatile boolean serverReportedActiveEvent = false;
    /**
     * True until the session's first non-empty batch. Until then polls ask
     * the server to collapse a stale backlog into one "while you were away"
     * digest per event instead of a message flood.
     */
    private volatile boolean firstBatchOfSession = true;

    /** LRU of processed envelope ids (replay guard). */
    private final Map<String, Boolean> seenIds =
        Collections.synchronizedMap(new LinkedHashMap<String, Boolean>() {
            @Override
            protected boolean removeEldestEntry(Map.Entry<String, Boolean> eldest) {
                return size() > SEEN_IDS_MAX;
            }
        });

    /** Toasts pending display; consumed by EventToastOverlay. */
    @Getter
    private final ConcurrentLinkedDeque<Toast> toasts = new ConcurrentLinkedDeque<>();

    /** Last shown-at per pop-up dedupe key; guarded by its own monitor. */
    private final Map<String, Long> recentToastKeys =
        new LinkedHashMap<String, Long>() {
            @Override
            protected boolean removeEldestEntry(Map.Entry<String, Long> eldest) {
                return size() > TOAST_KEYS_MAX;
            }
        };

    /** Latest /event_state snapshot (HUD + Events tab). */
    @Getter
    @Nullable
    private volatile EventState eventState;
    private volatile long eventStateAtMs = 0;

    /**
     * Invoked (off-EDT) whenever a fresh event state lands.
     *
     * A list rather than a single slot: the side panel and the clan-chat team
     * indicators both hang off this signal, and with one setter the second
     * registration silently replaced the first — the panel would simply stop
     * refreshing, with nothing in the log to say why.
     */
    private final List<Runnable> stateUpdatedListeners = new CopyOnWriteArrayList<>();

    /* ===================== lifecycle ===================== */

    public void start() {
        if (!running.compareAndSet(false, true)) {
            return;
        }
        serverSupportsLongPoll = true;
        serverReportedActiveEvent = false;
        consecutiveFailures = 0;
        firstBatchOfSession = true;
        scheduleNext(POLL_INTERVAL_SECONDS * 1000L);
    }

    public void stop() {
        running.set(false);
        synchronized (this) {
            if (pollTask != null) {
                pollTask.cancel(false);
                pollTask = null;
            }
        }
        Call call = inFlightCall;
        if (call != null) {
            call.cancel();
        }
        toasts.clear();
        synchronized (recentToastKeys) {
            recentToastKeys.clear();
        }
        eventState = null;
        eventStateAtMs = 0;
    }

    private boolean enabled() {
        // The poll loop serves two consumers: event notifications and the
        // Discord→game chat bridge. Either keeps it alive.
        return config.useApi()
            && (config.eventNotifications() || clanRelayService.discordChatActive());
    }

    private void scheduleNext(long delayMs) {
        if (!running.get()) {
            return;
        }
        synchronized (this) {
            if (!running.get()) {
                return;
            }
            pollTask = executor.schedule(this::runCycleSafely, delayMs, TimeUnit.MILLISECONDS);
        }
    }

    private void runCycleSafely() {
        try {
            runCycle();
        } catch (Exception e) {
            log.debug("event notification cycle failed: {}", e.getMessage());
            cycleInFlight.set(false);
            scheduleNext(POLL_INTERVAL_SECONDS * 1000L);
        }
    }

    /**
     * One poll cycle. Runs briefly on the shared executor: it only picks the
     * wait mode and enqueues the HTTP call; the OkHttp callback processes the
     * response and schedules the next cycle. Exactly one cycle owns the chain
     * at a time ({@link #cycleInFlight}); the flag is always cleared before
     * the owner schedules its successor, so the chain cannot strand itself.
     */
    private void runCycle() {
        if (!running.get() || !cycleInFlight.compareAndSet(false, true)) {
            return;
        }
        boolean handedOff = false;
        try {
            if (!enabled()) {
                scheduleNext(IDLE_RECHECK_SECONDS * 1000L);
                return;
            }
            final String playerName = client.getLocalPlayer() != null
                ? client.getLocalPlayer().getName() : null;
            final long accountHash = client.getAccountHash();
            if (playerName == null || accountHash == -1L) {
                scheduleNext(POLL_INTERVAL_SECONDS * 1000L);
                return;
            }
            // Idle (no live event): a plain poll checks the authoritative
            // active_event flag; long-holds are reserved for live events.
            // The server's own last report ORs in so a just-started event
            // flips us to held long-polls immediately instead of waiting for
            // the (throttled, maybe-never) config cache refresh (P0-2). The
            // chat bridge holds too — Discord lines should land in seconds.
            final boolean bridgeActive = clanRelayService.discordChatActive();
            final int waitSeconds =
                ((api.hasActiveEvent() || serverReportedActiveEvent || bridgeActive)
                    && serverSupportsLongPoll)
                ? LONG_POLL_WAIT_SECONDS : 0;
            // The clan param doubles as the bridge presence heartbeat: the
            // server fans Discord lines out only to players it has seen
            // polling with this clan recently.
            final String bridgeClan = bridgeActive
                ? clanRelayService.getCurrentClanName() : null;
            Call call = api.newNotificationsCall(playerName, accountHash, waitSeconds, bridgeClan,
                firstBatchOfSession ? hiddenQuery() : null);
            if (call == null) {
                scheduleNext(POLL_INTERVAL_SECONDS * 1000L);
                return;
            }
            inFlightCall = call;
            final long startedAtMs = System.currentTimeMillis();
            try {
                call.enqueue(new okhttp3.Callback() {
                    @Override
                    public void onFailure(okhttp3.Call c, java.io.IOException e) {
                        inFlightCall = null;
                        cycleInFlight.set(false);
                        if (!running.get() || c.isCanceled()) {
                            return;
                        }
                        consecutiveFailures++;
                        log.debug("/notifications poll failed: {}", e.getMessage());
                        scheduleNext(failureBackoffMs());
                    }

                    @Override
                    public void onResponse(okhttp3.Call c, okhttp3.Response response) {
                        inFlightCall = null;
                        long nextDelayMs;
                        try {
                            final int httpCode = response.code();
                            DropTrackerApi.NotificationsResponse parsed;
                            try (okhttp3.Response r = response) {
                                parsed = api.parseNotificationsResponse(r);
                            }
                            if (parsed == null) {
                                if (httpCode == 404) {
                                    // Not a registered player: terminal for
                                    // this identity, not a server fault —
                                    // recheck rarely instead of retrying the
                                    // failure backoff forever (audit).
                                    consecutiveFailures = 0;
                                    nextDelayMs = NOT_REGISTERED_RECHECK_MS;
                                } else {
                                    consecutiveFailures++;
                                    nextDelayMs = failureBackoffMs();
                                }
                            } else {
                                consecutiveFailures = 0;
                                handleResponse(parsed, playerName, accountHash);
                                nextDelayMs = nextDelayMs(parsed, waitSeconds,
                                    System.currentTimeMillis() - startedAtMs);
                            }
                        } catch (Exception e) {
                            log.debug("/notifications processing failed: {}", e.getMessage());
                            nextDelayMs = POLL_INTERVAL_SECONDS * 1000L;
                        } finally {
                            cycleInFlight.set(false);
                        }
                        scheduleNext(nextDelayMs);
                    }
                });
                handedOff = true;
            } catch (Exception e) {
                inFlightCall = null;
                log.debug("/notifications enqueue failed: {}", e.getMessage());
                scheduleNext(POLL_INTERVAL_SECONDS * 1000L);
            }
        } finally {
            if (!handedOff) {
                cycleInFlight.set(false);
            }
        }
    }

    /** Runs on the OkHttp callback thread (off-EDT, off-client-thread). */
    private void handleResponse(DropTrackerApi.NotificationsResponse response,
                                String playerName, long accountHash) {
        List<EventNotification> fresh = new ArrayList<>();
        if (response.notifications != null) {
            for (EventNotification n : response.notifications) {
                if (n == null || n.getType() == null) {
                    continue;
                }
                if (n.getId() != null && seenIds.put(n.getId(), Boolean.TRUE) != null) {
                    continue; // replay
                }
                fresh.add(n);
            }
        }
        // Bridge lines are chat, not event state: render them immediately and
        // keep them out of the event grouping/catch-up machinery entirely.
        fresh = renderAndStripClanChat(fresh);
        if (!fresh.isEmpty()) {
            DebugLogger.log("[EventNotifications] batch size=" + fresh.size());
            firstBatchOfSession = false;
            renderBatch(fresh);
        }
        if (Boolean.TRUE.equals(response.activeEvent)) {
            serverReportedActiveEvent = true;
        } else if (Boolean.FALSE.equals(response.activeEvent)) {
            serverReportedActiveEvent = false;
        }
        long sinceStateMs = System.currentTimeMillis() - eventStateAtMs;
        boolean stateStale = sinceStateMs > TimeUnit.MINUTES.toMillis(3);
        // Fresh-batch refreshes are coalesced (audit P0-14): notifications
        // fan out to whole teams, and every teammate re-fetching the heavy
        // /event_state on every batch turned one completion into N
        // compositions at once. The batch itself already carries the
        // headline info; the full snapshot follows within the cooldown.
        boolean cooledDown = sinceStateMs > TimeUnit.SECONDS.toMillis(20);
        if ((eventState == null || stateStale || (!fresh.isEmpty() && cooledDown))
                && Boolean.TRUE.equals(response.activeEvent)) {
            refreshEventState(playerName, accountHash);
        }
        if (Boolean.FALSE.equals(response.activeEvent) && eventState != null) {
            // Event(s) ended: clear the HUD snapshot.
            eventState = null;
            notifyStateUpdated();
        }
    }

    /** Age past which a bridge chat line is history, not conversation. */
    private static final long BRIDGE_LINE_MAX_AGE_SECONDS = 120;

    /** Server-side cap for Discord→game lines (clan_chat_bridge.py). */
    private static final int BRIDGE_MESSAGE_MAX_CHARS = 200;

    /**
     * Renders {@code clan_chat_message} envelopes (Discord→game bridge) and
     * {@code clan_chat_muted} ones (a muted clanmate's line) as clan chat and returns the batch without them. Stale lines
     * — an offline backlog draining on login — are silently dropped: chat
     * from twenty minutes ago is noise, exactly like real clan chat you
     * weren't online for.
     */
    private List<EventNotification> renderAndStripClanChat(List<EventNotification> batch) {
        if (batch.isEmpty()) {
            return batch;
        }
        List<EventNotification> remainder = new ArrayList<>(batch.size());
        long nowSeconds = System.currentTimeMillis() / 1000L;
        for (EventNotification n : batch) {
            boolean muted = "clan_chat_muted".equals(n.getType());
            if (!muted && !"clan_chat_message".equals(n.getType())) {
                remainder.add(n);
                continue;
            }
            // Same gate as polling for them: sync on, Discord lines wanted, and
            // still in a clan one of the player's groups bridges.
            if (!clanRelayService.discordChatActive()) {
                continue;
            }
            EventNotification.Data data = n.getData();
            String sender = data != null ? clean(data.getSender()) : null;
            // Matches the server's DISCORD_TO_GAME_MAX_CHARS (200) — the
            // generic 120 cap would re-truncate lines the backend already
            // capped, silently eating the tail of longer Discord messages.
            String message = data != null ? clean(data.getMessage(), BRIDGE_MESSAGE_MAX_CHARS) : null;
            if (sender == null || message == null) {
                continue;
            }
            if (n.getTs() > 0 && nowSeconds - n.getTs() > BRIDGE_LINE_MAX_AGE_SECONDS) {
                continue;
            }
            if (muted) {
                clanRelayService.showMutedLine(sender, message, data.getAccountType());
            } else {
                chatMessageUtil.sendDiscordClanMessage(sender, message);
            }
        }
        return remainder;
    }

    /** Delay before the next cycle, from the just-finished poll's outcome. */
    private long nextDelayMs(DropTrackerApi.NotificationsResponse response,
                             int waitRequestedSeconds, long elapsedMs) {
        boolean active = Boolean.TRUE.equals(response.activeEvent) || api.hasActiveEvent()
            || clanRelayService.discordChatActive();
        if (!active) {
            return IDLE_RECHECK_SECONDS * 1000L;
        }
        if (waitRequestedSeconds > 0) {
            if (!Boolean.TRUE.equals(response.longPoll)) {
                // Legacy server: the wait param was ignored. Stop asking and
                // poll on the fixed cadence for the rest of the session.
                serverSupportsLongPoll = false;
                DebugLogger.log("[EventNotifications] server lacks long-poll; using fixed cadence");
                return POLL_INTERVAL_SECONDS * 1000L;
            }
            boolean empty = response.notifications == null || response.notifications.isEmpty();
            if (empty && elapsedMs < SUSPICIOUS_FAST_EMPTY_MS) {
                return POLL_INTERVAL_SECONDS * 1000L;
            }
            return REISSUE_DELAY_MS;
        }
        // Plain poll while an event is live (idle flip or legacy mode). Only
        // fast-reissue when the server itself confirmed the event — the next
        // cycle then upgrades to a HELD long-poll (serverReportedActiveEvent
        // is set). Any other plain-poll outcome paces at the fixed cadence:
        // a cache-only "active" must never spin at REISSUE_DELAY_MS (P0-2).
        boolean nextCycleWillHold =
            serverSupportsLongPoll && Boolean.TRUE.equals(response.activeEvent);
        return nextCycleWillHold ? REISSUE_DELAY_MS : POLL_INTERVAL_SECONDS * 1000L;
    }

    private long failureBackoffMs() {
        int failures = Math.max(1, Math.min(consecutiveFailures, 5));
        return Math.min(MAX_FAILURE_BACKOFF_MS, 5000L * (1L << (failures - 1)));
    }

    /** Fetch the state snapshot now (panel open / manual refresh). Off-EDT. */
    public void refreshEventStateNow() {
        String playerName = client.getLocalPlayer() != null
            ? client.getLocalPlayer().getName() : null;
        long accountHash = client.getAccountHash();
        if (playerName == null || accountHash == -1L || !enabled()) {
            return;
        }
        refreshEventState(playerName, accountHash);
    }

    private void refreshEventState(String playerName, long accountHash) {
        EventState state = api.fetchEventState(playerName, accountHash);
        if (state != null) {
            eventState = state;
            eventStateAtMs = System.currentTimeMillis();
            notifyStateUpdated();
        }
    }

    /**
     * Item ids the server wants force-screenshotted for event proof, from the
     * latest /event_state snapshot. Empty when no event is live, the API is
     * disabled (the service never polls), or the server predates the field.
     */
    public Set<Integer> getEventScreenshotItemIds() {
        EventState state = eventState;
        List<Integer> ids = state != null ? state.getScreenshotItemIds() : null;
        if (ids == null || ids.isEmpty()) {
            return Collections.emptySet();
        }
        return new LinkedHashSet<>(ids);
    }

    /** Register a listener for fresh state. Safe to call more than once. */
    public void addStateUpdatedListener(Runnable listener) {
        if (listener != null) {
            stateUpdatedListeners.add(listener);
        }
    }

    public void removeStateUpdatedListener(Runnable listener) {
        if (listener != null) {
            stateUpdatedListeners.remove(listener);
        }
    }

    private void notifyStateUpdated() {
        for (Runnable callback : stateUpdatedListeners) {
            // One listener throwing must not cost the others their update.
            try {
                callback.run();
            } catch (Exception e) {
                log.debug("state-updated callback failed: {}", e.getMessage());
            }
        }
    }

    /** The state entry the HUD shows: the pinned event, else the first. */
    @Nullable
    public EventState.Entry hudEntry() {
        EventState state = eventState;
        if (state == null || state.getEvents() == null || state.getEvents().isEmpty()) {
            // No live event: a ::dtpopup preview may lend the HUD a sample
            // one for a minute, so the attached styles can be tried anywhere.
            EventState.Entry preview = previewHudEntry;
            return preview != null && System.currentTimeMillis() < previewHudUntilMs
                ? preview : null;
        }
        int pinned = config.pinnedEventId();
        if (pinned > 0) {
            for (EventState.Entry entry : state.getEvents()) {
                if (entry.getEvent() != null && entry.getEvent().getId() == pinned) {
                    return entry;
                }
            }
        }
        return state.getEvents().get(0);
    }

    /* ===================== ::dtpopup previews ===================== */

    @Nullable
    private volatile EventState.Entry previewHudEntry;
    private volatile long previewHudUntilMs = 0;

    /** Lends the HUD a sample event until {@code untilMs}, while no real event is live. */
    public void setPreviewHudEntry(@Nullable EventState.Entry entry, long untilMs) {
        previewHudEntry = entry;
        previewHudUntilMs = untilMs;
    }

    /**
     * Renders a sample envelope through the real renderer and queues its
     * pop-up straight away: no chat line, no "important only" filter, no
     * dedupe. False when the envelope renders no pop-up (unknown type, or
     * muted by the user's settings).
     */
    public boolean previewNotification(EventNotification n, @Nullable EventPopupStyle popup,
                                       int moreCount) {
        Rendered rendered = render(n);
        if (rendered == null || !rendered.toastEligible) {
            return false;
        }
        Toast toast = rendered.toToast(System.currentTimeMillis());
        if (moreCount > 0) {
            toast = toast.withMore(moreCount);
        }
        previewToast(toast.pinned(popup, System.currentTimeMillis()));
        return true;
    }

    /** Queues a ready-made preview pop-up, bypassing every filter. */
    public void previewToast(Toast toast) {
        toasts.addLast(toast);
        while (toasts.size() > MAX_TOASTS_QUEUED) {
            toasts.pollFirst();
        }
    }

    /* ===================== tracked-task override ===================== */

    private String trackedTaskKey(int eventId) {
        return "trackedTask_" + eventId;
    }

    /** The user's manually tracked task for an event, or 0 = server decides. */
    public int trackedTaskId(int eventId) {
        try {
            Integer stored = configManager.getConfiguration(
                DropTrackerConfig.GROUP, trackedTaskKey(eventId), Integer.class);
            return stored != null ? stored : 0;
        } catch (Exception e) {
            return 0;
        }
    }

    /** Track a task on the HUD for this event; taskId <= 0 reverts to auto. */
    public void setTrackedTask(int eventId, int taskId) {
        if (taskId <= 0) {
            configManager.unsetConfiguration(DropTrackerConfig.GROUP, trackedTaskKey(eventId));
        } else {
            configManager.setConfiguration(DropTrackerConfig.GROUP, trackedTaskKey(eventId), taskId);
        }
    }

    /**
     * The task the HUD and the Events tab headline for an entry: the user's
     * tracked pick while it exists and is incomplete, else the server's focus
     * task ("the server decides"). Null when neither applies.
     *
     * <p>A pin always wins — it is the user saying "this one" — but a server
     * focus the user hid is skipped for the next visible incomplete task, in
     * the order the panel lists them. The server stamps a focus for hours
     * after you progress a task, so without that skip the gold TRACKING box
     * keeps headlining the very tile you just filed under "N hidden".
     */
    @Nullable
    public DisplayTask displayTask(EventState.Entry entry) {
        if (entry == null || entry.getEvent() == null) {
            return null;
        }
        int eventId = entry.getEvent().getId();
        int tracked = trackedTaskId(eventId);
        // Board games have no free task choice: the current tile is the task.
        boolean pickable = !"board_game".equals(entry.getEvent().getKind());
        List<EventState.TaskInfo> tasks = entry.getTasks();
        if (tracked > 0 && pickable && tasks != null) {
            for (EventState.TaskInfo task : tasks) {
                if (task.getId() == tracked && !task.isCompleted()) {
                    return new DisplayTask(task.getId(), task.getLabel(),
                        task.getHave(), task.getNeed(),
                        task.getIconItemId(), task.getIconPath(), true);
                }
            }
        }
        EventState.FocusTask focus = entry.getFocusTask();
        if (focus == null) {
            return null;
        }
        Set<Integer> hidden = pickable ? hiddenTaskIds(eventId) : Collections.emptySet();
        if (!hidden.contains(focus.getId())) {
            return new DisplayTask(focus.getId(), focus.getLabel(),
                focus.getHave(), focus.getNeed(),
                focus.getIconItemId(), focus.getIconPath(), false);
        }
        if (tasks != null) {
            for (EventState.TaskInfo task : tasks) {
                if (!task.isCompleted() && !hidden.contains(task.getId())) {
                    return new DisplayTask(task.getId(), task.getLabel(),
                        task.getHave(), task.getNeed(),
                        task.getIconItemId(), task.getIconPath(), false);
                }
            }
        }
        return null;
    }

    /**
     * Task ids the user hid for this event in the Events tab. Package-private
     * and overridable: this is the seam the notification tests drive, since
     * {@link ConfigManager} cannot be constructed off a live client.
     */
    Set<Integer> hiddenTaskIds(int eventId) {
        return eventId > 0
            ? EventTaskPrefs.hidden(configManager, eventId) : Collections.emptySet();
    }

    /** Every event's hidden tasks, for the server's catch-up digest. */
    String hiddenQuery() {
        return EventTaskPrefs.hiddenQuery(configManager);
    }

    /**
     * True when an envelope is a routine update about a task the user hid.
     * Only task-scoped chatter consults this: event-level news (lead changes,
     * lines, start/end) is never about the one task whose id it happens to
     * carry, and a genuine completion is deliberately still announced.
     */
    private boolean hiddenTask(EventNotification n) {
        EventNotification.Data data = n.getData();
        Integer taskId = data != null ? data.getTaskId() : null;
        Integer eventId = n.getEvent() != null ? n.getEvent().getId() : null;
        return taskId != null && taskId > 0 && eventId != null
            && hiddenTaskIds(eventId).contains(taskId);
    }

    /** Unified view of the headlined task, from either source. */
    @AllArgsConstructor(access = AccessLevel.PACKAGE)
    public static class DisplayTask {
        public final int id;
        public final String label;
        public final long have;
        public final long need;
        @Nullable
        public final Integer iconItemId;
        @Nullable
        public final String iconPath;
        /** true = the user's manual pick; false = server-chosen focus. */
        public final boolean tracked;
    }

    /* ===================== batch rendering ===================== */

    /**
     * Renders one drained batch per event. Package-private: this is the seam
     * the notification tests drive.
     */
    void renderBatch(List<EventNotification> batch) {
        // Group per event id (0 = event-less, e.g. submission notices).
        Map<Integer, List<EventNotification>> byEvent = new LinkedHashMap<>();
        for (EventNotification n : batch) {
            int eventId = n.getEvent() != null && n.getEvent().getId() != null
                ? n.getEvent().getId() : 0;
            byEvent.computeIfAbsent(eventId, k -> new ArrayList<>()).add(n);
        }
        List<Toast> candidates = new ArrayList<>();
        for (List<EventNotification> group : byEvent.values()) {
            if (!"event_digest".equals(group.get(0).getType())) {
                candidates.addAll(renderEventGroup(group));
                continue;
            }
            // A digest replaces its event's whole backlog server-side.
            Toast digest = renderDigest(group);
            if (digest != null) {
                candidates.add(digest);
            }
        }
        queueBatchToasts(candidates);
    }

    /** Renders one event's slice of a batch to chat and returns the pop-ups it
     *  earned; the caller coalesces them across events into one card. */
    private List<Toast> renderEventGroup(List<EventNotification> group) {
        List<Rendered> chatLines = new ArrayList<>();
        List<Toast> groupToasts = new ArrayList<>();
        Set<String> dedupe = new LinkedHashSet<>();
        String eventName = groupEventName(group);
        String teamName = teamNameFor(groupEventId(group));

        for (EventNotification n : group) {
            Rendered rendered = render(n);
            if (rendered == null || !dedupe.add(rendered.text)) {
                continue; // unknown type, filtered, or identical line in batch
            }
            if (rendered.chatEligible) {
                chatLines.add(rendered);
            }
            if (rendered.toastEligible) {
                groupToasts.add(rendered.toToast(System.currentTimeMillis()));
            }
        }

        // Chat: everything up to the cap, then a collapse line.
        int lines = 0;
        for (Rendered line : chatLines) {
            if (lines == MAX_CHAT_LINES_PER_EVENT && chatLines.size() > MAX_CHAT_LINES_PER_EVENT + 1) {
                sendLine(eventName, teamName, null, TONES.get("info"), null,
                    "... and " + (chatLines.size() - MAX_CHAT_LINES_PER_EVENT) + " more event updates.");
                break;
            }
            sendLine(eventName, teamName, line.chatTag, line.chatHex,
                line.chatEmphasis, line.text);
            lines++;
        }
        return groupToasts;
    }

    /**
     * At most ONE pop-up per batch: the most important update headlines it and
     * the rest fold into a "+N more" tail. Several events completing tasks in
     * the same poll used to mean one tall card each — three of those at
     * TOP_CENTER is most of the screen.
     */
    private void queueBatchToasts(List<Toast> candidates) {
        if (candidates.isEmpty()) {
            return;
        }
        Toast lead = candidates.get(0);
        for (Toast candidate : candidates) {
            // Priority is declared most-important-first; ties keep the first.
            if (candidate.getPriority().ordinal() < lead.getPriority().ordinal()) {
                lead = candidate;
            }
        }
        int folded = candidates.size() - 1;
        offerToast(folded == 0 ? lead : lead.withMore(folded));
    }

    /**
     * Queues a pop-up subject to the display mode, the "important only"
     * filter, the cross-batch dedupe window and the queue cap.
     */
    private void offerToast(Toast toast) {
        if (!config.eventDisplayMode().popupsEnabled()) {
            return;
        }
        if (config.eventImportantPopupsOnly()
                && toast.getPriority() != EventNotification.Priority.HIGH) {
            return;
        }
        if (!claimToastKey(toast.getDedupeKey(), toast.getCreatedAt())) {
            return;
        }
        toasts.addLast(toast);
        while (toasts.size() > MAX_TOASTS_QUEUED) {
            toasts.pollFirst();
        }
    }

    /** False when this dedupe key already popped inside the window. */
    private boolean claimToastKey(@Nullable String key, long now) {
        if (key == null) {
            return true;
        }
        synchronized (recentToastKeys) {
            Long last = recentToastKeys.get(key);
            if (last != null && now - last < TOAST_DEDUPE_WINDOW_MS) {
                return false;
            }
            recentToastKeys.put(key, now);
            return true;
        }
    }

    /** First event name carried by the group's envelopes, cleaned; null for
     *  event-less groups (submission notices), which keep the default tag. */
    @Nullable
    private static String groupEventName(List<EventNotification> group) {
        for (EventNotification n : group) {
            if (n.getEvent() != null && n.getEvent().getName() != null) {
                return clean(n.getEvent().getName());
            }
        }
        return null;
    }

    @Nullable
    private static Integer groupEventId(List<EventNotification> group) {
        for (EventNotification n : group) {
            if (n.getEvent() != null && n.getEvent().getId() != null) {
                return n.getEvent().getId();
            }
        }
        return null;
    }

    /** The player's own team in this event, from the last state snapshot
     *  (null before the first snapshot — the prefix then omits the team). */
    @Nullable
    private String teamNameFor(@Nullable Integer eventId) {
        if (eventId == null) {
            return null;
        }
        EventState state = eventState;
        if (state == null || state.getEvents() == null) {
            return null;
        }
        for (EventState.Entry entry : state.getEvents()) {
            if (entry.getEvent() != null && entry.getEvent().getId() == eventId
                    && entry.getTeam() != null) {
                return clean(entry.getTeam().getName());
            }
        }
        return null;
    }

    /**
     * "[Event Name] (Team name): TAG line" when the event is known, else the
     * default [DropTracker] tag (submission notices, event-less groups) —
     * which has no accent scheme, so the styling is dropped there.
     */
    private void sendLine(@Nullable String eventName, @Nullable String teamName,
                          @Nullable String tag, @Nullable String accentHex,
                          @Nullable String emphasis, String line) {
        if (eventName != null) {
            chatMessageUtil.sendEventChatMessage(eventName, teamName, tag, accentHex,
                emphasis, line);
        } else {
            chatMessageUtil.sendChatMessage(line);
        }
    }

    /* ===================== login catch-up digest ===================== */

    /**
     * The server's "while you were away" digest (services/plugin_display.py):
     * a header plus indented tallies in chat, and one HIGH pop-up so
     * "important only" never swallows the card that explains what you missed.
     */
    @Nullable
    private Toast renderDigest(List<EventNotification> group) {
        EventNotification.Display d = group.get(0).getDisplay();
        String title = d != null ? clean(d.getTitle()) : null;
        String body = d != null ? clean(d.getText(), MAX_TEXT_LENGTH * 2) : null;
        if (title == null || body == null || d.getLines() == null) {
            return null;
        }
        String eventName = groupEventName(group);
        String teamName = teamNameFor(groupEventId(group));
        sendLine(eventName, teamName, null, TONES.get("lead"), null, title + ":");
        for (EventNotification.Chat line : d.getLines()) {
            String text = line != null ? clean(line.getText(), MAX_TEXT_LENGTH * 2) : null;
            if (text != null) {
                sendLine(eventName, teamName, null,
                    line.getTone() != null ? TONES.get(line.getTone()) : null, null, "  - " + text);
            }
        }
        EventPopupCard card = d.getCard();
        if (card != null && card.getKind() != null) {
            card.sanitize(EventNotificationService::clean);
        } else {
            card = null;
        }
        return new Toast(title, body, d.getIconItemId(), System.currentTimeMillis(),
            EventNotification.Priority.HIGH, null, card, 0, null);
    }

    /* ===================== rendering ===================== */

    /**
     * Chat accents, one per kind of news, so a completion, a lead change and
     * a KC tick never read the same. The server names a tone; the colour is
     * ours (an unknown tone stays uncoloured). Mirrors DropTrackerTheme: chat
     * can't reference AWT colours from here, so the hexes are duplicated.
     */
    private static final Map<String, String> TONES = Map.of(
        "complete", "#6fbf73", "tile", "#7fe08a", "lead", "#ffd966", "line", "#ff8c42",
        "blackout", "#e05c4d", "action", "#ffb83f", "info", "#d8c9a3", "muted", "#8f8778");

    /** A rendered notification: what chat and the pop-up show. */
    @RequiredArgsConstructor(access = AccessLevel.PACKAGE)
    private static class Rendered {
        final String title;
        /** Plain body: the pop-up card and the in-batch dedupe key. */
        final String text;
        /** Uppercase chat tag, e.g. "TILE COMPLETE"; null = no tag. */
        String chatTag;
        /** Chat accent for the tag/body; null = the legacy uncoloured line. */
        String chatHex;
        /** Substring of {@link #text} to lift out of the accent (item name). */
        String chatEmphasis;
        Integer iconItemId;
        EventNotification.Priority priority = EventNotification.Priority.NORMAL;
        boolean chatEligible = true;
        boolean toastEligible = true;
        /** (event, task, type); null opts out of the cross-batch pop-up dedupe. */
        String dedupeKey;
        /** Structured parts for the showcase-style pop-up layouts. */
        EventPopupCard card;

        Toast toToast(long now) {
            return new Toast(title, text, iconItemId, now, priority, dedupeKey,
                card, 0, null);
        }
    }

    /**
     * Renders an envelope from the server's {@code display} block: the
     * wording, the chat tag and the card are composed server-side
     * (services/plugin_display.py), per reader team. This side owns
     * everything about how it looks: the colours (a tone from a closed
     * set), the layouts (a card kind from a closed set), sanitizing every
     * string again, and the "time left" note, which only the reader's clock
     * can keep current. Local mutes still apply. An envelope without a
     * display we can read is dropped, like an unknown type.
     */
    @Nullable
    private Rendered render(EventNotification n) {
        EventNotification.Data data = n.getData() != null ? n.getData() : new EventNotification.Data();
        String type = String.valueOf(n.getType());
        if ("submission_notice".equals(type)) {
            // Legacy server-text channel: sanitized plain chat only, gated
            // by the pre-existing receiveInGameMessages config.
            String message = clean(data.getMessage());
            if (!config.receiveInGameMessages() || message == null) {
                return null;
            }
            Rendered notice = new Rendered("DropTracker", message);
            notice.toastEligible = false;
            return notice;
        }
        if ("event_task_progress".equals(type)
                && (!config.eventTaskProgressNotifications() || hiddenTask(n))) {
            // The client-side mute for the chattiest type; hiding a task in
            // the panel mutes its ticks too.
            return null;
        }
        EventNotification.Display d = n.getDisplay();
        String title = d != null ? clean(d.getTitle()) : null;
        String text = d != null ? clean(d.getText(), MAX_TEXT_LENGTH * 2) : null;
        if (title == null || text == null) {
            DebugLogger.log("[EventNotifications] no display for type=" + type);
            return null;
        }
        Rendered rendered = new Rendered(title, text);
        EventNotification.Chat chat = d.getChat();
        if (chat != null) {
            rendered.chatTag = clean(chat.getTag(), 24);
            rendered.chatHex = chat.getTone() != null ? TONES.get(chat.getTone()) : null;
            rendered.chatEmphasis = clean(chat.getEmphasis());
        }
        rendered.iconItemId = d.getIconItemId();
        rendered.toastEligible = !Boolean.FALSE.equals(d.getToast());
        rendered.priority = n.priorityTier();
        rendered.dedupeKey = dedupeKey(n);
        EventPopupCard card = d.getCard();
        if (card != null && card.getKind() != null) {
            card.sanitize(EventNotificationService::clean);
            if (card.getKind() != EventPopupCard.Kind.ENDED && card.getKind() != EventPopupCard.Kind.STARTED) {
                String left = timeLeft(d.getEndsAt());
                card.note(left != null ? left + " left" : null);
            }
            rendered.card = card;
        }
        return rendered;
    }

    /** "2d 4h" / "3h 12m" / "5m" until the server's UTC ISO timestamp; null
     *  when absent, unparseable or already past. */
    @Nullable
    static String timeLeft(@Nullable String endsAtIso) {
        if (endsAtIso == null || endsAtIso.isEmpty()) {
            return null;
        }
        try {
            Instant ends = LocalDateTime.parse(endsAtIso).toInstant(ZoneOffset.UTC);
            Duration left = Duration.between(Instant.now(), ends);
            if (left.isNegative() || left.isZero()) {
                return null;
            }
            long days = left.toDays();
            long hours = left.toHours() % 24;
            long minutes = left.toMinutes() % 60;
            if (days > 0) {
                return days + "d " + hours + "h";
            }
            if (hours > 0) {
                return hours + "h " + minutes + "m";
            }
            return Math.max(minutes, 1) + "m";
        } catch (DateTimeParseException e) {
            return null;
        }
    }

    /** Pop-up identity across batches: the same task ticking the same way. */
    private static String dedupeKey(EventNotification n) {
        Integer eventId = n.getEvent() != null ? n.getEvent().getId() : null;
        EventNotification.Data data = n.getData();
        Object task = null;
        if (data != null) {
            task = data.getTaskId() != null ? data.getTaskId() : clean(data.getTaskLabel());
        }
        return eventId + "|" + task + "|" + n.getType();
    }

    /** Tag-strip + length-cap every server-supplied string before rendering. */
    @Nullable
    static String clean(@Nullable String value) {
        return clean(value, MAX_TEXT_LENGTH);
    }

    @Nullable
    static String clean(@Nullable String value, int maxLength) {
        if (value == null) {
            return null;
        }
        String stripped = Text.removeTags(value).replace('\u00A0', ' ').trim();
        if (stripped.isEmpty()) {
            return null;
        }
        return stripped.length() > maxLength
            ? stripped.substring(0, maxLength - 1) + "…" : stripped;
    }

    /** A transient on-screen pop-up. */
    @Getter
    public static class Toast {
        /** Per-tier lifetimes: the big moments linger, routine ticks flick by. */
        static final long LIFETIME_HIGH_MS = 9000;
        static final long LIFETIME_NORMAL_MS = 6000;
        static final long LIFETIME_LOW_MS = 3500;

        private final String title;
        private final String body;
        @Nullable
        private final Integer iconItemId;
        private final long createdAt;
        private final EventNotification.Priority priority;
        /** (event, task, type) for the cross-batch dedupe; null = always show. */
        @Nullable
        private final String dedupeKey;
        /** Structured parts for the showcase-style layouts; null = text only. */
        @Nullable
        private final EventPopupCard card;
        /** Other updates folded into this card ("+N more"). */
        private final int moreCount;
        /** ::dtpopup previews pin a style; null = the display type's. */
        @Nullable
        private final EventPopupStyle popupStyle;

        public Toast(String title, String body, @Nullable Integer iconItemId, long createdAt) {
            this(title, body, iconItemId, createdAt, EventNotification.Priority.NORMAL, null);
        }

        public Toast(String title, String body, @Nullable Integer iconItemId, long createdAt,
                     EventNotification.Priority priority, @Nullable String dedupeKey) {
            this(title, body, iconItemId, createdAt, priority, dedupeKey, null, 0, null);
        }

        public Toast(String title, String body, @Nullable Integer iconItemId, long createdAt,
                     EventNotification.Priority priority, @Nullable String dedupeKey,
                     @Nullable EventPopupCard card, int moreCount,
                     @Nullable EventPopupStyle popupStyle) {
            this.title = title;
            this.body = body;
            this.iconItemId = iconItemId;
            this.createdAt = createdAt;
            this.priority = priority != null ? priority : EventNotification.Priority.NORMAL;
            this.dedupeKey = dedupeKey;
            this.card = card;
            this.moreCount = moreCount;
            this.popupStyle = popupStyle;
        }

        /** This card headlining {@code more} folded updates. */
        Toast withMore(int more) {
            return new Toast(title, body + " (+" + more + " more)", iconItemId, createdAt,
                priority, dedupeKey, card, more, popupStyle);
        }

        /** A copy pinned to the given style and restarted at {@code now}. */
        public Toast pinned(@Nullable EventPopupStyle popup, long now) {
            return new Toast(title, body, iconItemId, now, priority, dedupeKey, card,
                moreCount, popup);
        }

        /** The server icon path to draw when there is no item sprite. */
        @Nullable
        public String getIconPath() {
            return card != null ? card.getIconPath() : null;
        }

        public long lifetimeMs() {
            switch (priority) {
                case HIGH:
                    return LIFETIME_HIGH_MS;
                case LOW:
                    return LIFETIME_LOW_MS;
                default:
                    return LIFETIME_NORMAL_MS;
            }
        }

        /** Milliseconds of life left; <= 0 once expired. */
        public long remainingMs(long now) {
            return lifetimeMs() - (now - createdAt);
        }

        public boolean expired(long now) {
            return remainingMs(now) <= 0;
        }
    }
}

package io.droptracker.service;

import lombok.AllArgsConstructor;
import io.droptracker.DropTrackerConfig;
import io.droptracker.models.api.EventState;
import net.runelite.client.config.ConfigManager;

import javax.annotation.Nullable;
import java.util.*;

/**
 * Per-event task pins and hides for the Events tab, persisted through
 * {@link ConfigManager} with the same per-event keying as the tracked task:
 * {@code pinnedTasks_<eventId>} and {@code hiddenTasks_<eventId>}, each a
 * comma-separated list of task ids in the order the user picked them.
 *
 * <p>The single tracked task is the degenerate one-pin case. The first
 * <i>incomplete</i> pinned task is mirrored into {@code trackedTask_<eventId>}
 * by {@link #syncFocus} — that key stays the canonical "focus" that
 * {@link EventNotificationService#trackedTaskId(int)} reads, so the HUD,
 * {@link EventNotificationService#displayTask(EventState.Entry)} and anything
 * else built on it keep working without knowing pins exist. Config written by
 * an older build (a tracked task, no pin list) is read back as a single pin.
 *
 * <p>The hide set is readable without a panel instance
 * ({@link #hidden(ConfigManager, int)}) because hiding has to reach past the
 * list it was clicked in: {@link EventNotificationService#hiddenTaskIds(int)}
 * reads it to keep a hidden task out of the HUD and to mute its progress
 * chat/pop-ups. Completions are still announced — see that class.
 */
@AllArgsConstructor
public class EventTaskPrefs {
    private static final String PINNED_PREFIX = "pinnedTasks_";
    private static final String HIDDEN_PREFIX = "hiddenTasks_";
    /** Stored for an empty list: 0 is not a task id, so it parses away. */
    private static final String NO_IDS = "0";

    private final ConfigManager configManager;
    private final EventNotificationService service;

    /** Task ids the user pinned for this event, in pin order. */
    public Set<Integer> pinned(int eventId) {
        String raw = get(PINNED_PREFIX + eventId);
        if (raw == null) {
            // Pre-pin-set config: the tracked task is the one and only pin.
            Set<Integer> migrated = new LinkedHashSet<>();
            int tracked = service.trackedTaskId(eventId);
            if (tracked > 0) {
                migrated.add(tracked);
            }
            return migrated;
        }
        return parse(raw);
    }

    /** Task ids the user hid for this event. */
    public Set<Integer> hidden(int eventId) {
        return hidden(configManager, eventId);
    }

    /** {@link #hidden(int)} without a panel — for callers that only have the
     *  ConfigManager (the HUD and notification filtering). */
    public static Set<Integer> hidden(ConfigManager configManager, int eventId) {
        return parse(get(configManager, HIDDEN_PREFIX + eventId));
    }

    /** Every event's hide set as "eventId:id,id;..." (the catch-up digest's
     *  query param); empty when nothing is hidden or the config is unreadable. */
    public static String hiddenQuery(ConfigManager configManager) {
        StringBuilder out = new StringBuilder();
        try {
            for (String key : configManager.getConfigurationKeys(DropTrackerConfig.GROUP + "." + HIDDEN_PREFIX)) {
                String eventId = key.substring(key.lastIndexOf('_') + 1);
                out.append(eventId).append(':').append(get(configManager, HIDDEN_PREFIX + eventId)).append(';');
            }
        } catch (Exception e) {
            return "";
        }
        return out.toString();
    }

    /** Pin or unpin a task, then re-point the HUD focus at the top pin. */
    public void togglePin(EventState.Entry entry, int taskId) {
        int eventId = eventId(entry);
        if (eventId <= 0) {
            return;
        }
        Set<Integer> ids = pinned(eventId);
        if (!ids.remove(taskId)) {
            ids.add(taskId);
            // A task cannot be both focused and out of sight.
            unhide(eventId, taskId);
        }
        put(PINNED_PREFIX + eventId, ids);
        syncFocus(entry);
    }

    /** Drop one pin (the tracked-task box's "unpin"), promoting the next. */
    public void unpin(EventState.Entry entry, int taskId) {
        int eventId = eventId(entry);
        if (eventId <= 0) {
            return;
        }
        Set<Integer> ids = pinned(eventId);
        if (ids.remove(taskId)) {
            put(PINNED_PREFIX + eventId, ids);
        }
        syncFocus(entry);
    }

    /** Hide or unhide a task; hiding it also gives up its pin. */
    public void toggleHidden(EventState.Entry entry, int taskId) {
        int eventId = eventId(entry);
        if (eventId <= 0) {
            return;
        }
        Set<Integer> ids = hidden(eventId);
        if (ids.remove(taskId)) {
            put(HIDDEN_PREFIX + eventId, ids);
        } else {
            ids.add(taskId);
            put(HIDDEN_PREFIX + eventId, ids);
            unpin(entry, taskId);
        }
    }

    /** Bring every hidden task of this event back into the list. */
    public void unhideAll(int eventId) {
        put(HIDDEN_PREFIX + eventId, new LinkedHashSet<>());
    }

    /**
     * Mirror the first incomplete pin into the canonical tracked-task key, so
     * the HUD headlines it. No pins (or every pin completed) means "let the
     * server decide", exactly as an unset tracked task always has.
     *
     * <p>Skipped for board games — their current tile is forced, never picked —
     * and while the server sends no task list, where completion is unknowable
     * and clearing the key would silently drop the user's pick.
     */
    public void syncFocus(@Nullable EventState.Entry entry) {
        int eventId = eventId(entry);
        if (eventId <= 0 || "board_game".equals(entry.getEvent().getKind())) {
            return;
        }
        List<EventState.TaskInfo> tasks = entry.getTasks();
        if (tasks == null) {
            return;
        }
        Set<Integer> pins = pinned(eventId);
        if (!pins.isEmpty() && get(PINNED_PREFIX + eventId) == null) {
            // Migrated from a tracked task: write the pin list out once so the
            // pin survives the task completing (which clears the tracked key).
            put(PINNED_PREFIX + eventId, pins);
        }
        int focus = 0;
        for (Integer id : pins) {
            EventState.TaskInfo task = task(tasks, id);
            if (task != null && !task.isCompleted()) {
                focus = id;
                break;
            }
        }
        if (focus != service.trackedTaskId(eventId)) {
            service.setTrackedTask(eventId, focus);
        }
    }

    private void unhide(int eventId, int taskId) {
        Set<Integer> ids = hidden(eventId);
        if (ids.remove(taskId)) {
            put(HIDDEN_PREFIX + eventId, ids);
        }
    }

    @Nullable
    private static EventState.TaskInfo task(List<EventState.TaskInfo> tasks, int id) {
        for (EventState.TaskInfo task : tasks) {
            if (task.getId() == id) {
                return task;
            }
        }
        return null;
    }

    private static int eventId(@Nullable EventState.Entry entry) {
        return entry != null && entry.getEvent() != null ? entry.getEvent().getId() : 0;
    }

    @Nullable
    private String get(String key) {
        return get(configManager, key);
    }

    @Nullable
    private static String get(ConfigManager configManager, String key) {
        try {
            return configManager.getConfiguration(DropTrackerConfig.GROUP, key);
        } catch (Exception e) {
            return null;
        }
    }

    /**
     * An empty set is stored as {@link #NO_IDS}, never unset and never blank:
     * "the user cleared their pins" must not read back as "never used pins",
     * which would resurrect the tracked task the pins were migrated from.
     */
    private void put(String key, Collection<Integer> ids) {
        StringBuilder csv = new StringBuilder();
        for (Integer id : ids) {
            if (csv.length() > 0) {
                csv.append(',');
            }
            csv.append(id);
        }
        if (csv.length() == 0) {
            csv.append(NO_IDS);
        }
        try {
            configManager.setConfiguration(DropTrackerConfig.GROUP, key, csv.toString());
        } catch (Exception ignored) {
            // A failed write costs the user a pin, never the panel.
        }
    }

    private static Set<Integer> parse(@Nullable String raw) {
        Set<Integer> ids = new LinkedHashSet<>();
        if (raw == null || raw.isEmpty()) {
            return ids;
        }
        for (String part : raw.split(",")) {
            try {
                int id = Integer.parseInt(part.trim());
                if (id > 0) {
                    ids.add(id);
                }
            } catch (NumberFormatException ignored) {
                // Hand-edited config: skip the junk, keep the rest.
            }
        }
        return ids;
    }
}

package io.droptracker.service;

import lombok.AccessLevel;
import lombok.RequiredArgsConstructor;
import lombok.AllArgsConstructor;
import com.google.inject.*;
import io.droptracker.DropTrackerConfig;
import io.droptracker.api.DropTrackerApi;
import io.droptracker.models.TeamIndicatorStyle;
import io.droptracker.models.api.*;
import io.droptracker.util.ChatMessageUtil;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;
import net.runelite.api.events.ScriptCallbackEvent;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.*;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.ui.FontManager;
import net.runelite.client.util.*;
import org.jetbrains.annotations.VisibleForTesting;

import javax.annotation.Nullable;
import java.awt.*;
import java.awt.image.BufferedImage;
import java.util.*;
import java.util.List;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.regex.*;

/**
 * Badges clan-chat lines from players in the same live event with their team
 * (suggestion #150).
 *
 * The roster comes from the API, which is the whole difference from the plugin
 * this was modelled on: nobody types names into a panel, so teams stay right
 * when an admin moves someone, and a clanmate who has never opened the site is
 * still badged.
 *
 * <p>The badge is applied while a chat line is being <em>drawn</em>, through
 * the chat builder's {@code chatMessageBuilding} callback, and is never written
 * back to the {@link MessageNode}. The first version did write it back, and
 * that broke private messages:
 * <ul>
 * <li>{@code MessageNode.setName} changes more than the text. RuneLite also
 * rebuilds the node's sender identity from whatever follows the last '>', so a
 * name ending in {@code </col>} left the line with an empty sender. The game
 * decides "is this from a friend?" from that identity, so with Private set to
 * Friends a teammate's PMs vanished, and with Clan set to Friends so did their
 * clan lines.</li>
 * <li>The walk over {@code client.getMessages()} that badged lines already on
 * screen reached every chat type, DMs included, which is how names in the PM
 * pane got recoloured.</li>
 * </ul>
 * Now each line's type is checked before it is badged. The node keeps the name
 * the server sent, other plugins read it unchanged, and switching the feature
 * off clears every badge on the next redraw.
 *
 * <p>Whatever the badge adds must disappear under the game's
 * {@code removetags}. The chat scripts strip tags from the drawn name to find
 * the clan rank icon and to target Report, Kick, Ban, Add friend and Message.
 * {@code <img>} and {@code <col>} strip cleanly. Literal text such as "[RR]"
 * does not, so the tag is drawn into the team's sprite rather than typed into
 * the name.
 *
 * <p>Two things keep it cheap. The roster is fetched only when the
 * {@code roster_version} on the /event_state poll changes. And the mod-icon
 * slots are claimed once per client lifetime and refilled in place, because
 * growing that array repeatedly leaks slots and stomps on icons other plugins
 * appended after us.
 */
@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class EventTeamIndicatorService {

    /**
     * Sprite slots reserved for team badges, one per team. Sized to the
     * server's cap on teams per roster ({@code ROSTER_TEAMS_LIMIT}), so every
     * team it sends can have one. A team that still ends up without a slot
     * falls back to a coloured name.
     */
    static final int MAX_TEAM_ICONS = 32;

    /** Orb sprite size, matching the game's own chat icons. */
    private static final int ORB_SIZE = 12;

    /** Columns between the orb and the tag when a badge shows both. */
    private static final int PIECE_GAP = 2;

    /** The chat builders' per-line callback (ChatBuilder and ChatSplitBuilder). */
    private static final String CHAT_MESSAGE_BUILDING = "chatMessageBuilding";

    /**
     * Tag text for a team with no colour of its own. The server always sends
     * an orb colour, so this is a backstop, picked to read on both the opaque
     * and the transparent chatbox.
     */
    private static final Color FALLBACK_TAG_COLOR = new Color(0x9f9f9f);

    /** A colour tag, open or close — a coloured name replaces any already there. */
    private static final Pattern COLOR_TAG = Pattern.compile("</?col(=[0-9a-fA-F]*)?>");

    /**
     * A moderator crown leading the name. The chat builder offers "Crown Info"
     * only when the name starts with one, so a badge goes after it.
     */
    private static final Pattern LEADING_CROWN = Pattern.compile("^<img=[01]>");

    /** Runs of whitespace, folded to one — see {@link #normalize(String)}. */
    private static final Pattern WHITESPACE = Pattern.compile("\\s+");

    private final Client client;
    private final ClientThread clientThread;
    private final EventBus eventBus;
    private final DropTrackerConfig config;
    private final DropTrackerApi api;
    private final ManifestService manifestService;
    private final EventNotificationService eventNotificationService;
    private final ScheduledExecutorService executor;

    /**
     * Normalized RSN to badge, replaced wholesale, never mutated in place: the
     * chat builder reads it on the client thread while the executor builds the
     * next one.
     */
    private volatile Map<String, TeamBadge> badgesByName = Collections.emptyMap();

    /** The loaded roster's teams in roster order, kept to redraw their sprites. */
    private volatile List<TeamBadge> loadedTeams = Collections.emptyList();

    /** Roster version currently reflected in {@link #badgesByName}. */
    @Nullable
    private volatile String loadedRosterVersion;

    /** Event the loaded roster belongs to; 0 when nothing is loaded. */
    private volatile int loadedEventId;

    /**
     * Bumped by every {@link #clear()}. A roster fetched before a clear must
     * not be installed after it, or an event that just ended would put its
     * badges back.
     */
    private final AtomicInteger generation = new AtomicInteger();

    /** First slot of our reserved block, or -1 before it is claimed. Client thread. */
    private int iconOffset = -1;

    /** team id -> sprite slot, valid only while {@link #iconOffset} >= 0. */
    private volatile Map<Integer, Integer> slotByTeam = Collections.emptyMap();

    private final Runnable stateListener = this::onEventStateUpdated;

    public void startUp() {
        eventBus.register(this);
        eventNotificationService.addStateUpdatedListener(stateListener);
    }

    public void shutDown() {
        eventBus.unregister(this);
        eventNotificationService.removeStateUpdatedListener(stateListener);
        clear();
        slotByTeam = Collections.emptyMap();
    }

    /**
     * The client rebuilds its mod-icon array on a restart, so the slot block is
     * claimed fresh each time. Call from GameState STARTING (reset) and
     * LOGIN_SCREEN (claim).
     */
    public void onGameStateChanged(GameState state) {
        if (state == GameState.STARTING) {
            iconOffset = -1;
            slotByTeam = Collections.emptyMap();
        } else if (state == GameState.LOGIN_SCREEN && iconOffset < 0) {
            claimIconSlots();
            // A roster held across the restart needs its sprites again.
            List<TeamBadge> teams = loadedTeams;
            if (!teams.isEmpty()) {
                assignIconSlots(teams, config.eventTeamIndicators());
            }
        }
    }

    /** True when the feature can badge anything at all right now. */
    private boolean active() {
        if (!config.useApi() || config.eventTeamIndicators() == TeamIndicatorStyle.OFF) {
            return false;
        }
        Manifest manifest = manifestService.getManifest();
        // A manifest we could not read leaves the feature on: the switch exists
        // to turn it off deliberately, not to fail closed on a fetch error.
        return manifest == null || manifest.getTeamIndicators().isEnabled();
    }

    /**
     * Fresh /event_state landed: refetch the roster if the event we are
     * badging, or its roster, changed. Runs off-EDT on the service's own
     * callback thread, so the fetch is handed to the executor.
     */
    private void onEventStateUpdated() {
        if (!active()) {
            if (!badgesByName.isEmpty()) {
                clear();
            }
            return;
        }
        EventState.Entry entry = eventNotificationService.hudEntry();
        if (entry == null || entry.getEvent() == null) {
            if (!badgesByName.isEmpty()) {
                clear();
            }
            return;
        }
        // A player can be in several live events at once, and a clanmate can be
        // on different teams in two of them. Resolve with the same pinned-event
        // order the HUD uses, so the badge and the HUD never disagree.
        int eventId = entry.getEvent().getId();
        String version = entry.getRosterVersion();
        if (version == null) {
            // Server predates the stamp: no badges rather than a roster we
            // would have no way to know had gone stale.
            clear();
            return;
        }
        if (eventId == loadedEventId && version.equals(loadedRosterVersion)) {
            return;
        }
        final int fetchGeneration = generation.get();
        executor.execute(() -> loadRoster(eventId, version, fetchGeneration));
    }

    private void loadRoster(int eventId, String version, int fetchGeneration) {
        String playerName = client.getLocalPlayer() != null
            ? client.getLocalPlayer().getName() : null;
        long accountHash = client.getAccountHash();
        if (playerName == null || accountHash == -1L) {
            return;
        }
        EventRoster roster = api.fetchEventRoster(playerName, accountHash);
        if (roster == null || roster.getEvents() == null) {
            return;
        }
        EventRoster.Entry entry = null;
        for (EventRoster.Entry candidate : roster.getEvents()) {
            if (candidate.getEventId() == eventId) {
                entry = candidate;
                break;
            }
        }
        if (entry == null || entry.getTeams() == null || entry.getMembers() == null) {
            clear();
            return;
        }

        Map<Integer, TeamBadge> badgeByTeam = new HashMap<>();
        List<TeamBadge> teams = new ArrayList<>();
        for (EventRoster.Team team : entry.getTeams()) {
            TeamBadge badge = new TeamBadge(team.getId(), team.getShortTag(),
                colorOf(team.getOrbColor()), colorOf(team.getColor()));
            badgeByTeam.put(team.getId(), badge);
            teams.add(badge);
        }
        Map<String, TeamBadge> next = new HashMap<>();
        for (Map.Entry<String, List<String>> row : entry.getMembers().entrySet()) {
            Integer teamId = parseTeamId(row.getKey());
            TeamBadge badge = teamId == null ? null : badgeByTeam.get(teamId);
            if (badge == null || row.getValue() == null) {
                continue;
            }
            for (String name : row.getValue()) {
                // Server-normalized already; normalize again so one changed
                // implementation can never split the two sides silently.
                String key = normalize(name);
                if (!key.isEmpty()) {
                    next.put(key, badge);
                }
            }
        }
        clientThread.invoke(() -> install(next, teams, eventId, version, fetchGeneration));
    }

    /**
     * Swap a freshly fetched roster in and redraw the chatbox with it. Client
     * thread, so the chat builder never sees names without their sprites.
     */
    private void install(Map<String, TeamBadge> badges, List<TeamBadge> teams,
                         int eventId, String version, int fetchGeneration) {
        if (fetchGeneration != generation.get()) {
            // Cleared while this roster was in flight. Leaving the loaded
            // version unset lets the next state poll fetch again if it should.
            return;
        }
        assignIconSlots(teams, config.eventTeamIndicators());
        loadedTeams = teams;
        badgesByName = badges;
        loadedRosterVersion = version;
        loadedEventId = eventId;
        client.refreshChat();
    }

    /** A loaded roster without the fetch or the sprite drawing. */
    @VisibleForTesting
    void useBadges(Map<String, TeamBadge> badges, Map<Integer, Integer> slots) {
        badgesByName = badges;
        slotByTeam = slots;
    }

    private void clear() {
        generation.incrementAndGet();
        boolean hadBadges = !badgesByName.isEmpty();
        badgesByName = Collections.emptyMap();
        loadedTeams = Collections.emptyList();
        loadedRosterVersion = null;
        loadedEventId = 0;
        if (hadBadges) {
            // Badges exist only while a line is drawn, so a redraw removes them.
            clientThread.invoke(client::refreshChat);
        }
    }

    /**
     * Redraw on the display settings. They only change how a line is drawn,
     * so nothing is refetched. A new style also needs new sprites.
     */
    @Subscribe
    public void onConfigChanged(ConfigChanged event) {
        if (!DropTrackerConfig.GROUP.equals(event.getGroup())) {
            return;
        }
        String key = event.getKey();
        if (!"eventTeamIndicators".equals(key)
            && !"eventTeamIndicatorColorNames".equals(key)
            && !"eventTeamIndicatorsPublicChat".equals(key)) {
            return;
        }
        clientThread.invoke(() -> {
            List<TeamBadge> teams = loadedTeams;
            if (teams.isEmpty()) {
                return;
            }
            if ("eventTeamIndicators".equals(key)) {
                assignIconSlots(teams, config.eventTeamIndicators());
            }
            client.refreshChat();
        });
    }

    /**
     * Badge one chat line as the chatbox draws it, the same way RuneLite's own
     * chat-channel rank icons are added: replace the name on the script stack
     * and leave the {@link MessageNode} alone. The stack carries the line's
     * id and split-PM flag (ints, top two) and its channel, name, message and
     * timestamp (objects, top four).
     *
     * <p>Deliberately not gated on the plugin's {@code isTracking} flag: that
     * is the webhook-exhaustion kill switch for <em>submissions</em>, and
     * hiding a display feature behind it would silently drop badges for anyone
     * whose webhook list failed to replenish.
     */
    @Subscribe
    public void onScriptCallbackEvent(ScriptCallbackEvent event) {
        if (!CHAT_MESSAGE_BUILDING.equals(event.getEventName())) {
            return;
        }
        Map<String, TeamBadge> badges = badgesByName;
        if (badges.isEmpty()) {
            return;
        }
        TeamIndicatorStyle style = config.eventTeamIndicators();
        if (style == null || style == TeamIndicatorStyle.OFF) {
            return;
        }
        int[] intStack = client.getIntStack();
        int intStackSize = client.getIntStackSize();
        Object[] objectStack = client.getObjectStack();
        int objectStackSize = client.getObjectStackSize();
        if (intStack == null || objectStack == null || intStackSize < 2 || objectStackSize < 4) {
            return;
        }
        // The split private-chat pane builds through the same callback. It
        // holds nothing but DMs, which are never ours to touch.
        if (intStack[intStackSize - 2] == 1) {
            return;
        }
        MessageNode node = client.getMessages().get(intStack[intStackSize - 1]);
        if (node == null || !isBadgedChannel(node.getType())) {
            return;
        }
        // Identify the sender by the node's own name, not the drawn one, which
        // another plugin may already have decorated.
        String sender = node.getName();
        if (sender == null || sender.isEmpty()) {
            return;
        }
        // Our own Discord->game bridge renders relayed lines as real chat
        // messages. A Discord user is not a roster member and must never be
        // badged as one.
        if (ChatMessageUtil.isDiscordBridgeSender(sender)) {
            return;
        }
        TeamBadge badge = badges.get(normalize(sender));
        if (badge == null) {
            return;
        }
        Object shown = objectStack[objectStackSize - 3];
        if (!(shown instanceof String)) {
            return;
        }
        String decorated = badge.render((String) shown, iconSlot(badge.teamId),
            config.eventTeamIndicatorColorNames());
        if (decorated != null) {
            objectStack[objectStackSize - 3] = decorated;
        }
    }

    /**
     * The chat channels a badge belongs on. Everything else, including private
     * messages, trade requests and broadcasts, is never touched.
     */
    boolean isBadgedChannel(@Nullable ChatMessageType type) {
        if (type == null) {
            return false;
        }
        switch (type) {
            case CLAN_CHAT:
            case CLAN_GUEST_CHAT:
            case CLAN_GIM_CHAT:
            case FRIENDSCHAT:
                return true;
            case PUBLICCHAT:
                return config.eventTeamIndicatorsPublicChat();
            default:
                return false;
        }
    }

    // ── sprites ──────────────────────────────────────────────────────────────

    /**
     * Reserve the whole slot block once. Growing {@code modIcons} again on
     * every roster change would leak slots and can stomp on icons a plugin
     * loaded after us appended.
     */
    private void claimIconSlots() {
        if (iconOffset >= 0) {
            return;
        }
        final IndexedSprite[] modIcons = client.getModIcons();
        if (modIcons == null) {
            return;
        }
        final IndexedSprite[] grown = Arrays.copyOf(modIcons, modIcons.length + MAX_TEAM_ICONS);
        iconOffset = modIcons.length;
        // The new slots stay null until a roster assigns them. Nothing
        // dereferences them meanwhile: a slot is only ever named in an
        // <img=> tag after assignIconSlots has filled it, which is the same
        // order RuneLite's own pet icons are loaded in.
        client.setModIcons(grown);
    }

    /** Draw each team's badge for the style into our reserved slots. Client thread. */
    private void assignIconSlots(List<TeamBadge> teams, TeamIndicatorStyle style) {
        Map<Integer, Integer> slots = new HashMap<>();
        if (iconOffset < 0) {
            claimIconSlots();
        }
        IndexedSprite[] modIcons = iconOffset < 0 ? null : client.getModIcons();
        if (modIcons != null && modIcons.length >= iconOffset + MAX_TEAM_ICONS) {
            Font font = FontManager.getRunescapeFont();
            int used = 0;
            for (TeamBadge team : teams) {
                if (used >= MAX_TEAM_ICONS) {
                    break;
                }
                BadgeArt art = drawBadge(team, style, font);
                if (art == null) {
                    continue;
                }
                IndexedSprite sprite = ImageUtil.getImageIndexedSprite(art.image, client);
                // The font sits an <img> with its bottom row on the text
                // baseline, measured by originalHeight. Rows past that hang
                // below it, as a bracket's tail does.
                sprite.setOriginalHeight(art.ascent);
                int slot = iconOffset + used;
                modIcons[slot] = sprite;
                slots.put(team.teamId, slot);
                used++;
            }
        }
        // No slot at all still works: every team falls back to a coloured name.
        slotByTeam = slots;
    }

    private int iconSlot(int teamId) {
        Integer slot = slotByTeam.get(teamId);
        return slot == null ? -1 : slot;
    }

    /** A badge's pixels, and how many of its rows sit above the text baseline. */
    @AllArgsConstructor(access = AccessLevel.PACKAGE)
    static final class BadgeArt {
        final BufferedImage image;
        final int ascent;

    }

    /**
     * A team's badge for a style: its orb, its tag, or both side by side.
     *
     * <p>ORB degrades to the tag for a team without an orb colour, which is
     * why the default style can be ORB without every team needing one.
     *
     * @param font the chat font; with none, the tag is left out
     * @return null when the style draws nothing for this team
     */
    @Nullable
    static BadgeArt drawBadge(TeamBadge badge, TeamIndicatorStyle style, @Nullable Font font) {
        if (style == null || style == TeamIndicatorStyle.OFF) {
            return null;
        }
        List<BadgeArt> pieces = new ArrayList<>(2);
        boolean orb = style.showsOrb() && badge.orbColor != null;
        if (orb) {
            pieces.add(drawOrb(badge.orbColor));
        }
        if ((style.showsTag() || !orb) && badge.tag != null && !badge.tag.isEmpty() && font != null) {
            BadgeArt tag = drawText("[" + badge.tag + "]", badge.tagColor(), font);
            if (tag != null) {
                pieces.add(tag);
            }
        }
        if (pieces.isEmpty()) {
            return null;
        }
        return pieces.size() == 1 ? pieces.get(0) : sideBySide(pieces);
    }

    /**
     * A filled circle in the team's color, sized like the game's chat icons.
     *
     * Antialiasing is deliberately off: an IndexedSprite carries a palette and
     * a single transparent index, so soft edges would either bloat the palette
     * or come out as a fringe of near-transparent pixels. Two colors at 12px
     * is also simply what the game's own chat icons look like.
     */
    private static BadgeArt drawOrb(Color color) {
        BufferedImage image = new BufferedImage(ORB_SIZE, ORB_SIZE, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = image.createGraphics();
        try {
            g.setComposite(AlphaComposite.Src);
            g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_OFF);
            g.setColor(spriteSafe(color));
            g.fillOval(1, 1, ORB_SIZE - 2, ORB_SIZE - 2);
        } finally {
            g.dispose();
        }
        // The whole square sits above the baseline, as the game's icons do.
        return new BadgeArt(image, ORB_SIZE);
    }

    /**
     * Text drawn in the chat font, cropped to its ink.
     *
     * <p>RuneLite's RuneScape font is the game's own chat glyphs, and with
     * antialiasing off it lands on whole pixels exactly as the chatbox draws
     * it. Its metrics are the catch: the glyphs stand a few rows above the
     * baseline FontMetrics reports. So the baseline is measured instead, as
     * the row under a capital.
     */
    @Nullable
    static BadgeArt drawText(String text, Color color, Font font) {
        BufferedImage probe = new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB);
        Graphics2D probeGraphics = probe.createGraphics();
        FontMetrics metrics;
        try {
            metrics = probeGraphics.getFontMetrics(font);
        } finally {
            probeGraphics.dispose();
        }
        int width = metrics.stringWidth(text);
        int height = metrics.getAscent() + metrics.getDescent();
        if (width <= 0 || height <= 0) {
            return null;
        }
        BufferedImage canvas = renderLine(text, color, font, width, height, metrics.getAscent());
        BufferedImage capital = renderLine("H", color, font, width, height, metrics.getAscent());
        int top = firstInkedRow(canvas);
        int bottom = lastInkedRow(canvas);
        int baseline = lastInkedRow(capital);
        if (top < 0 || baseline < top) {
            return null;
        }
        BufferedImage cropped = new BufferedImage(width, bottom - top + 1, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = cropped.createGraphics();
        try {
            g.setComposite(AlphaComposite.Src);
            g.drawImage(canvas, 0, -top, null);
        } finally {
            g.dispose();
        }
        return new BadgeArt(cropped, baseline - top + 1);
    }

    private static BufferedImage renderLine(String text, Color color, Font font,
                                            int width, int height, int baseline) {
        BufferedImage image = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = image.createGraphics();
        try {
            g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_OFF);
            g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_OFF);
            g.setRenderingHint(RenderingHints.KEY_FRACTIONALMETRICS, RenderingHints.VALUE_FRACTIONALMETRICS_OFF);
            g.setFont(font);
            g.setColor(spriteSafe(color));
            g.drawString(text, 0, baseline);
        } finally {
            g.dispose();
        }
        return image;
    }

    /** Pieces laid out left to right, standing on one shared baseline. */
    private static BadgeArt sideBySide(List<BadgeArt> pieces) {
        int ascent = 0;
        int descent = 0;
        int width = PIECE_GAP * (pieces.size() - 1);
        for (BadgeArt piece : pieces) {
            ascent = Math.max(ascent, piece.ascent);
            descent = Math.max(descent, piece.image.getHeight() - piece.ascent);
            width += piece.image.getWidth();
        }
        BufferedImage image = new BufferedImage(width, ascent + descent, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = image.createGraphics();
        try {
            g.setComposite(AlphaComposite.Src);
            int x = 0;
            for (BadgeArt piece : pieces) {
                g.drawImage(piece.image, x, ascent - piece.ascent, null);
                x += piece.image.getWidth() + PIECE_GAP;
            }
        } finally {
            g.dispose();
        }
        return new BadgeArt(image, ascent);
    }

    private static int firstInkedRow(BufferedImage image) {
        for (int y = 0; y < image.getHeight(); y++) {
            if (rowHasInk(image, y)) {
                return y;
            }
        }
        return -1;
    }

    private static int lastInkedRow(BufferedImage image) {
        for (int y = image.getHeight() - 1; y >= 0; y--) {
            if (rowHasInk(image, y)) {
                return y;
            }
        }
        return -1;
    }

    private static boolean rowHasInk(BufferedImage image, int y) {
        for (int x = 0; x < image.getWidth(); x++) {
            if ((image.getRGB(x, y) >>> 24) != 0) {
                return true;
            }
        }
        return false;
    }

    /**
     * An opaque colour the sprite can hold. The indexed-sprite conversion
     * only keeps fully opaque pixels, and it reads pure black as its
     * transparent index, so black is nudged off zero.
     */
    static Color spriteSafe(Color color) {
        int rgb = color.getRGB() & 0xFFFFFF;
        return new Color(rgb == 0 ? 0x010101 : rgb);
    }

    // ── helpers ──────────────────────────────────────────────────────────────

    /**
     * The comparison key for an RSN. {@link Text#standardize} folds the
     * non-breaking space the game uses inside names and lowercases; the
     * underscore fold matches the server's
     * {@code normalize_player_display_equivalence}, which is what the roster
     * names were built with.
     */
    static String normalize(String name) {
        if (name == null) {
            return "";
        }
        String stripped = Text.standardize(Text.removeTags(name));
        // Collapse runs of whitespace as well as folding the separators: the
        // server's normalizer does, and two implementations that disagree by
        // one space badge nobody while looking perfectly correct on both sides.
        return WHITESPACE.matcher(
            stripped.replace('_', ' ').replace('-', ' ').trim()).replaceAll(" ");
    }

    @Nullable
    private static Integer parseTeamId(String key) {
        try {
            return Integer.valueOf(key);
        } catch (NumberFormatException e) {
            return null;
        }
    }

    /** "#rrggbb" to a Color, or null for anything unusable. */
    @Nullable
    static Color colorOf(@Nullable String hex) {
        if (hex == null) {
            return null;
        }
        String value = hex.trim();
        if (value.startsWith("#")) {
            value = value.substring(1);
        }
        if (value.length() != 6) {
            return null;
        }
        try {
            return new Color(Integer.parseInt(value, 16));
        } catch (NumberFormatException e) {
            return null;
        }
    }

    /** One team's rendering inputs, resolved once per roster load. */
    @AllArgsConstructor(access = AccessLevel.PACKAGE)
    static final class TeamBadge {
        private final int teamId;
        @Nullable
        private final String tag;
        @Nullable
        private final Color orbColor;
        @Nullable
        private final Color accent;

        /** The team's colour for text: the admin-set accent, else the orb's. */
        @Nullable
        Color nameColor() {
            return accent != null ? accent : orbColor;
        }

        Color tagColor() {
            Color color = nameColor();
            return color != null ? color : FALLBACK_TAG_COLOR;
        }

        /**
         * The sender name as the line should draw it, or null to leave it as
         * it is.
         *
         * <p>Only an {@code <img>} and a colour are ever added, both of which
         * the game's {@code removetags} strips. The tag itself lives in the
         * sprite. The badge leads the name, except that a moderator crown
         * stays first, where the chat builder looks for it.
         *
         * @param shown     the name on the script stack; another plugin may
         *                  already have given it an icon or a colour
         * @param iconSlot  this team's sprite, or -1 when it has none
         * @param colorName whether to draw the name in the team colour
         */
        @Nullable
        String render(String shown, int iconSlot, boolean colorName) {
            Color color = colorName ? nameColor() : null;
            if (iconSlot < 0 && color == null) {
                return null;
            }
            // Drop any colour the name already carries (RuneLite's chat colour
            // config, applied by a subscriber that may run before this one) so
            // the team colour is the one that shows. </col> resets to the chat
            // default rather than to an enclosing tag, so the result must be
            // one flat span, never a nested one.
            String name = color != null ? COLOR_TAG.matcher(shown).replaceAll("") : shown;
            Matcher crown = LEADING_CROWN.matcher(name);
            String lead = crown.lookingAt() ? crown.group() : "";
            String rest = name.substring(lead.length());

            StringBuilder out = new StringBuilder(lead);
            if (iconSlot >= 0) {
                out.append("<img=").append(iconSlot).append('>');
            }
            if (color != null) {
                out.append("<col=")
                    .append(String.format("%06x", color.getRGB() & 0xFFFFFF))
                    .append('>')
                    .append(rest)
                    .append("</col>");
            } else {
                out.append(rest);
            }
            return out.toString();
        }
    }
}

package io.droptracker.service;
/* Author: https://github.com/pajlads/DinkPlugin */

import com.google.common.cache.*;
import com.google.gson.*;

import io.droptracker.DropTrackerPlugin;
import io.droptracker.models.SerializedDrop;
import io.droptracker.models.submissions.Drop;
import io.droptracker.util.*;
import lombok.extern.slf4j.Slf4j;
import org.jetbrains.annotations.*;
import net.runelite.api.*;
import net.runelite.client.config.*;
import net.runelite.client.events.*;
import net.runelite.client.game.ItemStack;
import net.runelite.client.plugins.chatcommands.ChatCommandsPlugin;
import net.runelite.client.plugins.loottracker.*;
import net.runelite.http.api.loottracker.LootRecordType;
import org.apache.commons.lang3.StringUtils;

import javax.inject.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.regex.*;

@Slf4j
@Singleton
public class KCService {


    private static final String RL_CHAT_CMD_PLUGIN_NAME = ChatCommandsPlugin.class.getSimpleName().toLowerCase();
    private static final String RL_LOOT_PLUGIN_NAME = LootTrackerPlugin.class.getSimpleName().toLowerCase();
    private static final Pattern CLUE_SCROLL_REGEX = Pattern.compile("You have completed (?<scrollCount>\\d+) (?<scrollType>\\w+) Treasure Trails\\.");

    private ConfigManager configManager;


    private Gson gson;

    @Inject
    private ScheduledExecutorService executor;

    private Rarity rarityService;

    @Inject
    private DropTrackerPlugin plugin;

    /* Field-injected (nullable in tests): re-armed on completion messages so
     * the raid chest re-loot dedup never spans two completions. */
    @Inject
    private RaidLootDeduplicator raidLootDeduplicator;

    private List<Integer> whispererIds = Arrays.asList(12204, 12205, 12206, 12207);


    private static final Cache<String, Integer> killCounts = CacheBuilder.newBuilder()
            .expireAfterAccess(10, TimeUnit.MINUTES)
            .maximumSize(64L)
            .build();


    @Inject
    public KCService(ConfigManager configManager, Gson gson,
                     ScheduledExecutorService executor,
                     Rarity rarityService, DropTrackerPlugin plugin) {
        this.configManager = configManager;
        this.gson = gson;
        this.rarityService = rarityService;
        this.executor = executor;
        this.plugin = plugin;
    }

    public void reset() {
        plugin.lastDrop = null;
        KCService.killCounts.invalidateAll();
    }

    @SuppressWarnings("deprecation")
    public void onNpcKill(NpcLootReceived event) {
        NPC npc = event.getNpc();
        int id = npc.getId();
        if (whispererIds.contains(id)) {
            return;
        }

        String name = npc.getName();
        if (NpcUtilities.GAUNTLET_BOSS.equals(name) || NpcUtilities.CG_BOSS.equals(name)) {
            // already handled by onGameMessage
            return;
        }
        if (name != null) {
            this.incrementKills(LootRecordType.NPC, name, event.getItems());
        }
    }

    public void onPlayerKill(PlayerLootReceived event) {
        String name = event.getPlayer().getName();
        if (name != null) {
            this.incrementKills(LootRecordType.PLAYER, name, event.getItems());
        }
    }

    public void onLoot(LootReceived event) {
        boolean increment;
        switch (event.getType()) {
            case NPC:
                // Special case: upstream fires LootReceived for the whisperer, but not NpcLootReceived
                increment = "The Whisperer".equalsIgnoreCase(event.getName());
                break;
            case PLAYER:
                increment = false; // handled by PlayerLootReceived
                break;
            default:
                increment = true;
                break;
        }

        if (increment) {
            this.incrementKills(event.getType(), NpcUtilities.getStandardizedSource(event, plugin), event.getItems());
        }
    }
    public void onServerNpcLoot(ServerNpcLoot event) {
        /* Currently only called for Yama events */
        this.incrementKills(LootRecordType.NPC, event.getComposition().getName(), event.getItems());
    }

    public void onGameMessage(String message) {
        // update cached clue casket count
        Map.Entry<String, Integer> clue = parseClue(message);
        if (clue != null) {
            String tier = ucFirst(clue.getKey());
            int count = clue.getValue() - 1; // decremented since onLoot will increment
            killCounts.put("Clue Scroll (" + tier + ")", count);
            return;
        }

        NpcUtilities.parseBoss(message, plugin).ifPresent(pair -> {
            String boss = pair.getKey();
            Integer kc = pair.getValue();

            // A raid completion message means the next reward chest opened is
            // NEW loot — re-arm the chest re-loot dedup for that raid.
            if (raidLootDeduplicator != null) {
                raidLootDeduplicator.onRaidCompletion(boss);
            }

            // Update cache. We store kc - 1 since onNpcLootReceived will increment; kc - 1 + 1 == kc
            String cacheKey = getCacheKey(LootRecordType.UNKNOWN, boss);
            killCounts.asMap().merge(cacheKey, kc - 1, Math::max);

            if (boss.equals(NpcUtilities.GAUNTLET_BOSS) || boss.equals(NpcUtilities.CG_BOSS) || boss.startsWith(NpcUtilities.TOA) || boss.startsWith(NpcUtilities.TOB) || boss.startsWith(NpcUtilities.COX) || boss.startsWith(NpcUtilities.TFA)) {
                // populate lastDrop to workaround loot tracker quirks
                // (RuneLite fires LootReceived with "The Gauntlet" for both regular and corrupted)
                plugin.lastDrop = new Drop(boss, LootRecordType.EVENT, Collections.emptyList());

                if (!isPluginDisabled(RL_LOOT_PLUGIN_NAME)) {   
                    // onLoot will already increment kc, no need to schedule task below.
                    // this early return also simplifies our test code
                    return;
                }
            }

            // However: we don't know if boss message appeared before/after the loot event.
            // If after, we should store kc. If before, we should store kc - 1.
            // Given this uncertainty, we wait so that the loot event has passed, and then we can store latest kc.


            /* -- We are using the executor here -- */
            executor.schedule(() -> {
                killCounts.asMap().merge(cacheKey, kc, Math::max);
            }, 15, TimeUnit.SECONDS);
        });
    }

    @Nullable
    public Integer getKillCount(LootRecordType type, String sourceName) {
        if (sourceName == null) return null;
        // This static method is deprecated - use instance method instead
        return killCounts.getIfPresent(getCacheKey(type, sourceName));
    }

    @Nullable
    public Integer getKillCountWithStorage(LootRecordType type, String sourceName) {
        if (sourceName == null) return null;
        Integer stored = getStoredKillCount(type, sourceName);
        if (stored != null) {
            return killCounts.asMap().merge(getCacheKey(type, sourceName), stored, Math::max);
        }
        return killCounts.getIfPresent(getCacheKey(type, sourceName));
    }

    private void incrementKills(@NotNull LootRecordType type, @NotNull String sourceName, @NotNull Collection<ItemStack> items) {
        String cacheKey = getCacheKey(type, sourceName);
        killCounts.asMap().compute(cacheKey, (key, cachedKc) -> {
            if (cachedKc != null) {
                // increment kill count
                return cachedKc + 1;
            } else {
                // pull kc from loot tracker or chat commands plugin
                Integer kc = getStoredKillCount(type, sourceName);
                // increment if found
                return kc != null ? kc + 1 : null;
            }
        });
    }

    /**
     * @param type       {@link LootReceived#getType()}
     * @param sourceName {@link NPC#getName()} or {@link LootReceived#getName()}
     * @return the kill count stored by base runelite plugins
     */
    @Nullable
    private Integer getStoredKillCount(@NotNull LootRecordType type, @NotNull String sourceName) {
        // get kc from base runelite chat commands plugin (if enabled)
        if (!isPluginDisabled(RL_CHAT_CMD_PLUGIN_NAME)) {
            Integer kc = configManager.getRSProfileConfiguration("killcount", cleanBossName(sourceName), int.class);
            if (kc != null) {
                return kc - 1; // decremented since chat event typically occurs before loot event
            }
        }

        if (isPluginDisabled(RL_LOOT_PLUGIN_NAME)) {
            // assume stored kc is useless if loot tracker plugin is disabled
            return null;
        }
        String json = configManager.getConfiguration(LootTrackerConfig.GROUP,
                configManager.getRSProfileKey(),
                "drops_" + type + "_" + sourceName
        );
        if (json == null) {
            // no kc stored implies first kill
            return 0;
        }
        try {
            int kc = gson.fromJson(json, SerializedDrop.class).getKills();

            // loot tracker doesn't count kill if no loot - https://github.com/runelite/runelite/issues/5077
            OptionalDouble nothingProbability = rarityService.getRarity(sourceName, -1, 0);
            if (nothingProbability.isPresent() && nothingProbability.getAsDouble() < 1.0) {
                // estimate the actual kc (including kills with no loot)
                kc = (int) Math.round(kc / (1 - nothingProbability.getAsDouble()));
            }

            return kc;
        } catch (JsonSyntaxException e) {
            // should not occur unless loot tracker changes stored loot POJO structure
            log.warn("Failed to read kills from loot tracker config", e);
            return null;
        }
    }

    /**
     * @param boss {@link LootReceived#getName()}
     * @return lowercase boss name that {@link ChatCommandsPlugin} uses during serialization
     */
    @VisibleForTesting
    static String cleanBossName(String boss) {
        if ("The Gauntlet".equalsIgnoreCase(boss)) return "gauntlet";
        if ("The Corrupted Gauntlet".equalsIgnoreCase(boss) || NpcUtilities.CG_BOSS.equalsIgnoreCase(boss)) return "corrupted gauntlet";
        if ("The Leviathan".equalsIgnoreCase(boss)) return "leviathan";
        if ("The Whisperer".equalsIgnoreCase(boss)) return "whisperer";
        if (boss.startsWith("Barrows")) return "barrows chests";
        if (boss.endsWith("Hallowed Sepulchre)")) return "hallowed sepulchre";
        if (boss.endsWith("Tempoross)")) return "tempoross";
        if (boss.endsWith("Wintertodt)")) return "wintertodt";
        return StringUtils.remove(boss.toLowerCase(), ':');
    }

    @VisibleForTesting
    static String getCacheKey(@NotNull LootRecordType type, @NotNull String sourceName) {
        switch (type) {
            case PICKPOCKET:
                return "pickpocket_" + sourceName;
            case PLAYER:
                return "player_" + sourceName;
            default:
                if ("The Gauntlet".equals(sourceName)) return NpcUtilities.GAUNTLET_BOSS;
                if (NpcUtilities.CG_NAME.equals(sourceName) || "The Corrupted Gauntlet".equals(sourceName)) return NpcUtilities.CG_BOSS;
                return sourceName;
        }
    }
    @Nullable
    public static Map.Entry<String, Integer> parseClue(String gameMessage) {
        Matcher clueMatcher = CLUE_SCROLL_REGEX.matcher(gameMessage);
        if (!clueMatcher.find()) return null;
        String tier = clueMatcher.group("scrollType");
        String count = clueMatcher.group("scrollCount");
        return Map.entry(tier, Integer.parseInt(count));
    }

    public String ucFirst(@NotNull String text) {
        if (text.length() < 2) return text.toUpperCase();
        return Character.toUpperCase(text.charAt(0)) + text.substring(1).toLowerCase();
    }

    protected boolean isPluginDisabled(String simpleLowerClassName) {
        return "false".equals(configManager.getConfiguration(RuneLiteConfig.GROUP_NAME, simpleLowerClassName));
    }
}

package io.droptracker.service;

import lombok.AllArgsConstructor;
import javax.annotation.Nullable;
import javax.inject.*;

import io.droptracker.DropTrackerConfig;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;
import net.runelite.api.gameval.InventoryID;

/**
 * Reads what the player is wearing and carrying, for attaching to a personal
 * best.
 *
 * <p>"What did you bring?" is the first thing anyone asks about a good time, and
 * it is information the kill message alone cannot carry. This is item ids only —
 * no geometry, no model, no screenshot — so it costs a few hundred bytes and can
 * be rendered as the familiar inventory and equipment tabs.
 *
 * <p>Timing matters more than it looks. The capture has to happen while the
 * loadout still reflects the kill: a snapshot taken when the submission is
 * assembled can show a player who has already banked, eaten, died or teleported.
 * Callers therefore capture on the client thread as soon as the kill is
 * recognised, within a tick or two of the kill itself.
 *
 * <p>Encoded as a compact string rather than JSON because it travels in a
 * webhook embed field, and those are limited to 1024 characters — a full
 * 28-slot inventory plus worn equipment fits comfortably in this form and would
 * not as JSON.
 */
@Slf4j
@Singleton
@AllArgsConstructor(onConstructor_ = @Inject)
public class LoadoutCapture {

	/** Slot-index/item-id/quantity triples, e.g. {@code "0-11802-1,3-995-1000"}. */
	private static final char ENTRY_SEPARATOR = ',';
	private static final char FIELD_SEPARATOR = '-';

	/**
	 * Hard ceiling on the encoded length. Embed field values are capped at 1024
	 * characters; a real loadout is far shorter, so hitting this means something
	 * unexpected and the value is dropped rather than truncated into nonsense.
	 */
	private static final int MAX_ENCODED_LENGTH = 1000;

	private final Client client;
	private final DropTrackerConfig config;

	public boolean isEnabled() {
		return config.uploadCharacterModel() && config.sendLoadoutWithPbs();
	}

	/**
	 * Worn equipment, or null when unavailable or disabled.
	 *
	 * <p>Must be called on the client thread.
	 */
	@Nullable
	public String captureEquipment() {
		return isEnabled() ? encode(client.getItemContainer(InventoryID.WORN)) : null;
	}

	/**
	 * Carried inventory, or null when unavailable or disabled.
	 *
	 * <p>Must be called on the client thread.
	 */
	@Nullable
	public String captureInventory() {
		return isEnabled() ? encode(client.getItemContainer(InventoryID.INV)) : null;
	}

	/**
	 * Encodes the occupied slots of a container.
	 *
	 * <p>Empty slots are omitted rather than written as zeros: the slot index is
	 * carried explicitly, so the layout survives without paying for the gaps.
	 * Returns null for an absent or empty container, which callers treat as "no
	 * loadout" — an empty string would be indistinguishable from a real capture
	 * of a player carrying nothing.
	 */
	@Nullable
	private String encode(@Nullable ItemContainer container) {
		if (container == null) {
			return null;
		}

		Item[] items = container.getItems();
		if (items == null || items.length == 0) {
			return null;
		}

		StringBuilder encoded = new StringBuilder();
		for (int slot = 0; slot < items.length; slot++) {
			Item item = items[slot];
			if (item == null || item.getId() <= 0 || item.getQuantity() <= 0) {
				continue;
			}
			if (encoded.length() > 0) {
				encoded.append(ENTRY_SEPARATOR);
			}
			encoded.append(slot)
					.append(FIELD_SEPARATOR)
					.append(item.getId())
					.append(FIELD_SEPARATOR)
					.append(item.getQuantity());
		}

		if (encoded.length() == 0) {
			return null;
		}
		if (encoded.length() > MAX_ENCODED_LENGTH) {
			log.debug("Loadout encoding was {} chars; dropping rather than truncating",
					encoded.length());
			return null;
		}
		return encoded.toString();
	}
}

package io.droptracker.service;

import lombok.RequiredArgsConstructor;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.atomic.AtomicBoolean;

import javax.annotation.Nullable;
import javax.inject.*;

import io.droptracker.api.DropTrackerApi;
import io.droptracker.models.api.Manifest;
import lombok.extern.slf4j.Slf4j;

/**
 * Holds the {@link Manifest} for the life of the client session.
 *
 * <p>Fetched once, off the client thread, and never re-fetched: a manifest that
 * changed underneath a running session would mean the varps we are reading stop
 * matching the varps we started with, and callers have no way to reconcile a
 * half-old snapshot. New settings therefore reach a client on its next start,
 * which is the same propagation model as the rest of the plugin's config.
 *
 * <p>Every consumer must tolerate {@link #getManifest()} returning null — that
 * is the state before the first fetch completes, and after a failed one.
 */
@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class ManifestService {

	private final DropTrackerApi api;
	private final ScheduledExecutorService executor;

	/** Guards against a second fetch while the first is still in flight. */
	private final AtomicBoolean fetching = new AtomicBoolean(false);

	private volatile Manifest manifest;

	/**
	 * The manifest, or null if it has not arrived (or could not be fetched).
	 *
	 * <p>Null is a normal state, not an error: callers fall back to their
	 * built-in behaviour, which is what the plugin did before the manifest
	 * existed.
	 */
	@Nullable
	public Manifest getManifest() {
		return manifest;
	}

	/** Kicks off the one fetch for this session. Safe to call more than once. */
	public void startUp() {
		refresh();
	}

	public void shutDown() {
		manifest = null;
		fetching.set(false);
	}

	/**
	 * Fetches the manifest in the background.
	 *
	 * <p>Failure is deliberately quiet: the manifest is an enhancement, and a
	 * user whose network blocked one request should not see an error for a
	 * feature they did not ask about.
	 */
	public void refresh() {
		if (manifest != null || !fetching.compareAndSet(false, true)) {
			return;
		}
		// A failed fetch leaves manifest null, so a later caller may retry. That
		// matters because the API can be disabled (or the endpoint wrong) when
		// the plugin starts, and without a manifest no combat achievement varps
		// are read at all — the sync silently omits them.
		executor.execute(() -> {
			try {
				Manifest fetched = api.getManifest();
				if (fetched != null) {
					manifest = fetched;
					log.debug("Loaded plugin manifest version {}", fetched.getVersion());
				}
			} catch (Exception e) {
				log.debug("Could not load plugin manifest; using built-in defaults", e);
			} finally {
				fetching.set(false);
			}
		});
	}
}

package io.droptracker.service;

import lombok.AccessLevel;
import lombok.RequiredArgsConstructor;
import lombok.AllArgsConstructor;
import net.runelite.api.*;
import net.runelite.api.gameval.*;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.party.PartyService;
import net.runelite.client.util.Text;
import io.droptracker.util.DebugLogger;

import javax.inject.*;
import java.util.*;
import java.util.concurrent.*;

/**
 * Service for resolving the participants attached to submissions.
 *
 * <p>For raid content (ToB / ToA / CoX) the roster is captured from the game's
 * authoritative party sources rather than inferred from proximity:
 * <ul>
 *   <li><b>ToB</b>: health-orb name varcstrings {@code TOB_CLIENT_NAME0..4}</li>
 *   <li><b>ToA</b>: health-orb name varcstrings {@code TOA_CLIENT_NAME0..7}</li>
 *   <li><b>CoX</b>: the raiding-party sidepanel list widget
 *       ({@code InterfaceID.RaidsSidepanel.LIST})</li>
 * </ul>
 * These are server-pushed and independent of render distance, so the roster is
 * exactly the raid party — not whoever happened to be standing nearby.
 *
 * <p>A solo raid yields an empty roster, which is the correct participant list
 * and is deliberately kept — it is not treated as a failed capture, and nothing
 * is guessed to fill it. Guessing only happens when the game's own team size
 * says the raid had company that the authoritative source never returned.
 *
 * <p>Non-raid submissions fall back to a plain proximity scan, and the raid
 * roster is never merged into them, so a retained ToB roster can no longer be
 * attached to an unrelated kill minutes after the raid ended.
 */
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class NearbyPlayerTracker
{
    private final Client client;
    private final ClientThread clientThread;
    private final PartyService partyService;

    public static final String RAID_TOB = "tob";
    public static final String RAID_TOA = "toa";
    public static final String RAID_COX = "cox";
    public static final String RAID_TFA = "tfa";

    /**
     * Names read from the authoritative roster source of the active raid,
     * accumulated over the raid so members who disconnect or leave early are
     * still credited. Includes the local player (needed for spectator
     * detection); the local name is filtered out at emission time.
     */
    private final Set<String> authoritativeRoster = new LinkedHashSet<>();

    /**
     * Last-resort roster accumulated from proximity scans inside the raid
     * instance. Only consulted when the authoritative source yielded nothing
     * (e.g. plugin enabled mid-raid after the widgets/varcs stopped updating),
     * so drops never regress to an empty participant list (issue #43).
     */
    private final Set<String> fallbackRoster = new LinkedHashSet<>();

    /** Raid the rosters above belong to: {@code "tob"|"toa"|"cox"|"tfa"}, or null. */
    private String activeRaidType = null;

    /**
     * Largest team size the game itself reported during the active raid; 0
     * when it was never sampled. This is what tells a solo raid apart from a
     * failed capture — both leave the roster empty, but only the second one
     * may fall back to guessing.
     */
    private int raidTeamSizeMax = 0;

    /**
     * Whether the authoritative source ever returned a name this raid (the
     * local player counts). Proves the source is live, so an empty roster
     * after the local player is removed means "alone", not "capture broken".
     */
    private boolean authoritativeCaptureWorked = false;

    /** Last time (ms) the raid context was observed active. */
    private long rosterLastActiveMs = 0;

    /**
     * How long the roster survives after the raid context ends. Raid
     * completion resets the raid varbits before the player opens the loot
     * chest, so the roster must outlive the raid; players can idle in the
     * treasure room for several minutes before opening the chest.
     */
    private static final long RAID_ROSTER_EXPIRY_MS = TimeUnit.MINUTES.toMillis(10);

    /** Roster scans while inside a raid run every N game ticks (~0.6s each). */
    private static final int ROSTER_SCAN_TICK_INTERVAL = 5;

    /** Radius used for the fallback in-raid proximity scan; raid rooms are large. */
    private static final int ROSTER_SCAN_RADIUS_TILES = 40;

    private int ticksSinceRosterScan = 0;
    private boolean wasInRaid = false;

    /**
     * Maps a submission's source name (drop {@code source} field / PB
     * {@code boss_name}) to the raid it belongs to, or null for non-raid
     * content. Contains-matching covers every mode variant ("Theatre of
     * Blood: Hard Mode", "Chambers of Xeric Challenge Mode", ...).
     */
    public static String raidTypeForSource(String sourceName)
    {
        if (sourceName == null)
        {
            return null;
        }
        String source = sourceName.toLowerCase(Locale.ROOT);
        if (source.contains("theatre of blood"))
        {
            return RAID_TOB;
        }
        if (source.contains("tombs of amascut"))
        {
            return RAID_TOA;
        }
        if (source.contains("chambers of xeric"))
        {
            return RAID_COX;
        }
        if (source.contains("fractured archive"))
        {
            return RAID_TFA;
        }
        return null;
    }

    /**
     * Team size of the given raid ({@code "tob"|"toa"|"cox"}) from the
     * accumulated authoritative roster, merged with a live read. Returns 0
     * when nothing is known; callers fall back to their varbit read.
     */
    public int raidRosterSize(String raidType)
    {
        if (raidType == null)
        {
            return 0;
        }
        Set<String> live = new LinkedHashSet<>();
        if (client.isClientThread())
        {
            captureAuthoritativeRoster(raidType, live);
        }
        Set<String> history = raidType.equals(activeRaidType) ? authoritativeRoster : Collections.emptySet();
        return boundedRoster(live, history, rosterCapacity(raidType)).size();
    }

    /**
     * How many member slots the raid's authoritative source publishes, which is
     * also the largest party the game will let into it: Theatre of Blood has
     * five health orbs, Tombs of Amascut and The Fractured Archive eight. 0
     * means "no fixed ceiling" —
     * Chambers of Xeric has no small cap, so mass raids stay legal there.
     */
    static int rosterCapacity(String raidType)
    {
        if (RAID_TOB.equals(raidType))
        {
            return 5;
        }
        if (RAID_TOA.equals(raidType) || RAID_TFA.equals(raidType))
        {
            return 8;
        }
        return 0;
    }

    /**
     * Merges a live roster read with the accumulated one, never exceeding what
     * the raid can hold.
     *
     * <p>The accumulated roster exists because the authoritative sources go
     * quiet at the end of a raid, while the completion chat and the loot chest
     * arrive after that (issue #43). But accumulating is only safe *within* one
     * raid, and the lifecycle that is supposed to guarantee that has holes —
     * ToB's state varbit covers spectating as well as raiding, so consecutive
     * runs could pile up without the roster ever being cleared. That is how the
     * PB team-size bracket, which reads this roster since plugin 6.0, started
     * submitting Theatre of Blood times as 6-, 7-, 8- and 9-player raids
     * (suggestion #140) and how split credit reached people who were in an
     * earlier run rather than this one.
     *
     * <p>So the live read wins: it is the current raid's party, straight from
     * the game. History only fills slots the live read left empty — the
     * disconnected or departed members it exists for — and never past the
     * ceiling, which self-heals a contaminated roster as soon as the next
     * raid's names appear.
     */
    static Set<String> boundedRoster(Set<String> live, Set<String> history, int capacity)
    {
        Set<String> merged = new LinkedHashSet<>(live);
        for (String name : history)
        {
            if (capacity > 0 && merged.size() >= capacity)
            {
                break;
            }
            merged.add(name);
        }
        if (capacity > 0 && merged.size() > capacity)
        {
            // The live read alone overflowed, which the slot count says cannot
            // happen — keep the first `capacity` names rather than trust it.
            Set<String> trimmed = new LinkedHashSet<>();
            for (String name : merged)
            {
                if (trimmed.size() >= capacity)
                {
                    break;
                }
                trimmed.add(name);
            }
            return trimmed;
        }
        return merged;
    }

    /**
     * Called every game tick (client thread) so the raid roster is accumulated
     * continuously while a raid is in progress, instead of only being sampled
     * when a submission happens. By loot-chest time the raid varbits have
     * already reset, so a point-in-time scan is not enough (issue #43: ToB/ToA
     * drops submitted with an empty participant list).
     */
    public void onGameTick()
    {
        String raidType = currentRaidType();
        long nowMs = System.currentTimeMillis();

        if (raidType == null)
        {
            // Retain the roster for chest-time submissions, then expire it as
            // a whole so a stale raid can't leak into a later session.
            wasInRaid = false;
            if (activeRaidType != null && nowMs - rosterLastActiveMs > RAID_ROSTER_EXPIRY_MS)
            {
                clearRoster();
            }
            return;
        }

        if (!wasInRaid || !raidType.equals(activeRaidType))
        {
            // Entering a new raid (fresh entry — even back-to-back runs of the
            // same raid — or a different raid than the retained roster): drop
            // leftovers so a previous team can't leak into this raid's
            // submissions.
            clearRoster();
            activeRaidType = raidType;
            ticksSinceRosterScan = ROSTER_SCAN_TICK_INTERVAL; // scan immediately
        }
        wasInRaid = true;
        rosterLastActiveMs = nowMs;

        if (++ticksSinceRosterScan < ROSTER_SCAN_TICK_INTERVAL)
        {
            return;
        }
        ticksSinceRosterScan = 0;

        Set<String> live = new LinkedHashSet<>();
        captureAuthoritativeRoster(raidType, live);
        Set<String> merged = boundedRoster(live, authoritativeRoster, rosterCapacity(raidType));
        authoritativeRoster.clear();
        authoritativeRoster.addAll(merged);
        authoritativeCaptureWorked |= !authoritativeRoster.isEmpty();
        // Sampled throughout the raid because the raid varbits reset before the
        // loot chest opens: by submission time there is nothing left to read.
        raidTeamSizeMax = Math.max(raidTeamSizeMax, gameReportedTeamSize(raidType));
        captureFallbackRoster();
    }

    private void clearRoster()
    {
        authoritativeRoster.clear();
        fallbackRoster.clear();
        activeRaidType = null;
        raidTeamSizeMax = 0;
        authoritativeCaptureWorked = false;
    }

    /** The game's own party size for the given raid; 0 when unreadable. */
    private int gameReportedTeamSize(String raidType)
    {
        if (raidType == null)
        {
            return 0;
        }
        switch (raidType)
        {
            case RAID_TOB:
                return getTobTeamCount();
            case RAID_TOA:
                return getToaTeamCount();
            case RAID_COX:
                return getCoxTeamCount();
            case RAID_TFA:
                return getTfaTeamCount();
            default:
                return 0;
        }
    }

    /**
     * Whether an empty roster means "nobody else was in the raid" rather than
     * "the roster capture failed". A solo raid produces an empty roster by
     * definition, so reading emptiness alone as a failure — and guessing from
     * there — is what credited people who were never in the raid.
     *
     * <p>Requires positive evidence either way: a team size the game itself
     * reported as 1, or a live authoritative source that returned the local
     * player and nobody else. Without either, the caller keeps guessing.
     */
    private boolean isSoloRaid(String submissionRaidType, boolean localPlayerInRoster)
    {
        return isSoloRaid(
            gameReportedTeamSize(submissionRaidType),
            submissionRaidType.equals(activeRaidType),
            raidTeamSizeMax,
            authoritativeCaptureWorked,
            localPlayerInRoster);
    }

    /**
     * Best-evidence raid party size (receiver included) for a raid-sourced
     * submission, as a pure function so it can be tested without a client.
     *
     * <p>Takes the max of three independently derived signals because each one
     * can be absent: the live varbit read is usually 0 by loot-chest time (the
     * raid varbits reset at completion), the accumulated max only exists if
     * the plugin was on during the raid, and the participant count is what the
     * payload is about to claim anyway — a submission naming k others asserts
     * a party of at least k+1, so the reported size can never contradict the
     * roster it travels with (the same consistency rule the server applies to
     * {@code split_size}).
     *
     * @param liveTeamSize      team size read right now; 0 when unreadable
     * @param accumulatedMax    largest team size sampled during the raid; 0
     *                          when never sampled or the roster is not this
     *                          raid's
     * @param otherParticipants names attached to the submission (local player
     *                          excluded)
     * @return party size ≥ 1
     */
    static int computeRaidPartySize(int liveTeamSize, int accumulatedMax, int otherParticipants)
    {
        return Math.max(Math.max(liveTeamSize, accumulatedMax), otherParticipants + 1);
    }

    /**
     * The decision above, as a pure function of the evidence, so it can be
     * tested without a game client.
     *
     * @param liveTeamSize      team size read right now; 0 when unreadable
     *                          (normal at loot-chest time — the raid varbits
     *                          have already reset)
     * @param rosterIsThisRaid  whether the accumulated roster state belongs to
     *                          the raid this submission came from
     * @param teamSizeMax       largest team size seen during that raid; 0 when
     *                          never sampled
     * @param captureWorked     whether the authoritative source ever returned a
     *                          name during that raid
     * @param localPlayerInRoster whether the live read just returned the local
     *                          player, which proves the source is working
     */
    static boolean isSoloRaid(
        int liveTeamSize,
        boolean rosterIsThisRaid,
        int teamSizeMax,
        boolean captureWorked,
        boolean localPlayerInRoster
    )
    {
        if (liveTeamSize > 1)
        {
            return false;
        }
        if (rosterIsThisRaid)
        {
            if (teamSizeMax > 1)
            {
                return false;
            }
            if (teamSizeMax == 1)
            {
                return true;
            }
            return captureWorked || localPlayerInRoster;
        }
        return localPlayerInRoster;
    }

    /**
     * Which raid the local player is currently inside, from the raid *state*
     * varbits rather than teammate health orbs — the orbs read zero in
     * lobbies, during transitions, and after completion, which is exactly when
     * we still need to know a raid is (or was) in progress.
     */
    private String currentRaidType()
    {
        // ToB: 0=outside, 1=in party (lobby), 2=inside raid, 3=spectating
        if (client.getVarbitValue(THEATRE_OF_BLOOD_STATE) >= 2)
        {
            return RAID_TOB;
        }
        // ToA: 0=outside, 1=in party (lobby), 2=inside raid
        if (client.getVarbitValue(VarbitID.TOA_CLIENT_PARTYSTATUS) >= 2)
        {
            return RAID_TOA;
        }
        if (client.getVarbitValue(VarbitID.RAIDS_CLIENT_INDUNGEON) == 1)
        {
            return RAID_COX;
        }
        // The Fractured Archive copies ToA's party varbits: 2=inside raid.
        if (client.getVarbitValue(VarbitID.TFA_CLIENT_PARTYSTATUS) >= 2)
        {
            return RAID_TFA;
        }
        return null;
    }

    /** Reads the authoritative roster source for the given raid into {@code into}. */
    private void captureAuthoritativeRoster(String raidType, Set<String> into)
    {
        switch (raidType)
        {
            case RAID_TOB:
                captureVarcNames(VarClientID.TOB_CLIENT_NAME0, VarClientID.TOB_CLIENT_NAME4, into);
                break;
            case RAID_TOA:
                captureVarcNames(VarClientID.TOA_CLIENT_NAME0, VarClientID.TOA_CLIENT_NAME7, into);
                break;
            case RAID_COX:
                captureCoxSidepanelNames(into);
                break;
            case RAID_TFA:
                captureVarcNames(VarClientID.TFA_CLIENT_NAME0, VarClientID.TFA_CLIENT_NAME7, into);
                break;
            default:
                break;
        }
    }

    /**
     * ToB/ToA/TFA publish the party roster in varcstrings (health-orb name slots),
     * which stay populated for the whole raid — and usually beyond — regardless
     * of where teammates are standing. Empty slots read as "" or "-".
     */
    private void captureVarcNames(int firstVarcId, int lastVarcId, Set<String> into)
    {
        for (int varc = firstVarcId; varc <= lastVarcId; varc++)
        {
            String name = normalizePlayerName(client.getVarcStrValue(varc));
            if (name != null && !"-".equals(name))
            {
                into.add(name);
            }
        }
    }

    /**
     * CoX has no roster varcstrings; the authoritative source is the
     * raiding-party sidepanel list, whose child widgets carry member names.
     * The widget stays loaded while in the party/raid even when another side
     * tab is selected.
     */
    private void captureCoxSidepanelNames(Set<String> into)
    {
        Widget list = client.getWidget(InterfaceID.RaidsSidepanel.LIST);
        if (list == null)
        {
            return;
        }
        Widget[] children = list.getChildren();
        if (children == null)
        {
            return;
        }
        for (Widget child : children)
        {
            if (child == null)
            {
                continue;
            }
            String name = normalizePlayerName(child.getName());
            if (name != null && !"-".equals(name))
            {
                into.add(name);
            }
        }
    }

    /**
     * Accumulates the proximity fallback roster while inside a raid. Inside an
     * instanced raid the only nearby players are the team, so this is a
     * reasonable stand-in when the authoritative source is unavailable — but it
     * is never preferred over it.
     *
     * <p>RuneLite's PartyService used to be merged in here as well. It is not
     * evidence of raid participation: party membership survives a member
     * logging out of the game entirely and spans unrelated activities, so on a
     * solo raid it attached whoever was still in the party from an earlier
     * session. Anyone genuinely in the instance is picked up by the scan below.
     */
    private void captureFallbackRoster()
    {
        Player localPlayer = client.getLocalPlayer();

        if (localPlayer != null && localPlayer.getWorldLocation() != null)
        {
            WorldPoint center = localPlayer.getWorldLocation();
            WorldView topLevel = client.getTopLevelWorldView();
            if (topLevel != null)
            {
                ScanStats ignored = new ScanStats();
                collectNamesFromWorldView(topLevel, center, ROSTER_SCAN_RADIUS_TILES, localPlayer, fallbackRoster, ignored);
                for (WorldView subWorldView : topLevel.worldViews())
                {
                    collectNamesFromWorldView(subWorldView, center, ROSTER_SCAN_RADIUS_TILES, localPlayer, fallbackRoster, ignored);
                }
            }
        }
    }

    /** Participant trace with no submission source: plain proximity scan. */
    public NearbyPlayerTrace getNearbyPlayerTrace(int radiusTiles)
    {
        return getParticipantsTrace(null, radiusTiles);
    }

    /**
     * Resolves the participants to attach to a submission from
     * {@code sourceName} (drop {@code source} / PB {@code boss_name}).
     * Raid sources get the authoritative raid roster; everything else gets a
     * proximity scan with no raid-roster merge.
     */
    public NearbyPlayerTrace getParticipantsTrace(String sourceName, int radiusTiles)
    {
        if (client.isClientThread())
        {
            return collectParticipantsTrace(sourceName, radiusTiles);
        }

        CompletableFuture<NearbyPlayerTrace> future = new CompletableFuture<>();
        clientThread.invoke(() ->
        {
            try
            {
                future.complete(collectParticipantsTrace(sourceName, radiusTiles));
            }
            catch (Exception e)
            {
                future.complete(NearbyPlayerTrace.empty(Math.max(1, radiusTiles), "client-thread collection exception: " + e.getMessage()));
            }
        });

        try
        {
            return future.get(500, TimeUnit.MILLISECONDS);
        }
        catch (Exception e)
        {
            return NearbyPlayerTrace.empty(Math.max(1, radiusTiles), "future timeout/exception: " + e.getMessage());
        }
    }

    private NearbyPlayerTrace collectParticipantsTrace(String sourceName, int radiusTiles)
    {
        Player localPlayer = client.getLocalPlayer();
        if (localPlayer == null || localPlayer.getWorldLocation() == null)
        {
            return NearbyPlayerTrace.empty(Math.max(1, radiusTiles), "local player unavailable");
        }

        WorldPoint center = localPlayer.getWorldLocation();
        int effectiveRadius = Math.max(1, radiusTiles);
        String localName = normalizePlayerName(localPlayer.getName());
        String submissionRaidType = raidTypeForSource(sourceName);

        int toaTeamCount = getToaTeamCount();
        int tobTeamCount = getTobTeamCount();
        int coxTeamCount = getCoxTeamCount();
        int tfaTeamCount = getTfaTeamCount();
        boolean inRaidContext = (toaTeamCount > 1) || (tobTeamCount > 1) || (coxTeamCount > 1)
            || (tfaTeamCount > 1) || currentRaidType() != null;

        Set<String> names = new LinkedHashSet<>();
        String rosterSource;
        boolean localPlayerInRoster = false;
        ScanStats scanStats = new ScanStats();

        if (submissionRaidType != null)
        {
            // Raid submission: participants come from the authoritative roster
            // only. Read it live first — the ToB/ToA varcstrings and the CoX
            // sidepanel usually remain populated at loot-chest time — and let
            // the accumulated roster (which survives the varbit reset at
            // completion) fill the slots the live read left empty, bounded by
            // what the raid can hold. See boundedRoster.
            Set<String> live = new LinkedHashSet<>();
            captureAuthoritativeRoster(submissionRaidType, live);
            Set<String> history = submissionRaidType.equals(activeRaidType)
                ? authoritativeRoster
                : Collections.<String>emptySet();
            Set<String> roster = boundedRoster(live, history, rosterCapacity(submissionRaidType));
            if (submissionRaidType.equals(activeRaidType))
            {
                authoritativeRoster.clear();
                authoritativeRoster.addAll(roster);
            }

            localPlayerInRoster = localName != null && roster.contains(localName);
            if (localName != null)
            {
                roster.remove(localName);
            }

            if (!roster.isEmpty())
            {
                names.addAll(roster);
                rosterSource = "authoritative";
            }
            else if (isSoloRaid(submissionRaidType, localPlayerInRoster))
            {
                // Alone in the raid: an empty participant list is the correct
                // answer, and the only correct one. Guessing from here is what
                // credited RuneLite party members who never entered the raid,
                // and — for a submission made back in the lobby — would scan in
                // whichever strangers happened to be standing around.
                rosterSource = "solo";
            }
            else
            {
                // Capture never ran this raid (e.g. plugin enabled mid-raid):
                // fall back to the accumulated proximity roster plus a live
                // scan so the participant list isn't empty (issue #43).
                if (submissionRaidType.equals(activeRaidType))
                {
                    names.addAll(fallbackRoster);
                }
                int fallbackRadius = Math.max(effectiveRadius, ROSTER_SCAN_RADIUS_TILES);
                scanWorldViews(center, fallbackRadius, localPlayer, names, scanStats);
                rosterSource = "proximity-fallback";
            }
        }
        else
        {
            // Non-raid submission: plain proximity scan. The raid roster is
            // deliberately NOT merged here.
            scanWorldViews(center, effectiveRadius, localPlayer, names, scanStats);
            rosterSource = "proximity";
        }

        String raidType = submissionRaidType != null
            ? submissionRaidType
            : (activeRaidType != null ? activeRaidType : "none");

        // Evidence for the server: how big this raid's party actually was.
        // 0 for non-raid submissions (the field is then omitted from payloads).
        int raidPartySize = 0;
        if (submissionRaidType != null)
        {
            int accumulated = submissionRaidType.equals(activeRaidType) ? raidTeamSizeMax : 0;
            raidPartySize = computeRaidPartySize(
                gameReportedTeamSize(submissionRaidType), accumulated, names.size());
        }

        NearbyPlayerTrace trace = new NearbyPlayerTrace(
            new ArrayList<>(names),
            effectiveRadius,
            localName,
            center,
            inRaidContext,
            raidType,
            sourceName,
            rosterSource,
            localPlayerInRoster,
            raidPartySize,
            toaTeamCount,
            tobTeamCount,
            coxTeamCount,
            partyService.isInParty(),
            partyService.isInParty() ? partyService.getMembers().size() : 0,
            scanStats.worldViewsScanned,
            scanStats.playersSeen,
            scanStats.playersWithinRadius,
            scanStats.playersAdded,
            authoritativeRoster.size(),
            fallbackRoster.size(),
            System.currentTimeMillis(),
            null
        );
        DebugLogger.log("[NearbyPlayerTracker] " + trace.toDebugSummary());
        return trace;
    }

    private void scanWorldViews(WorldPoint center, int radiusTiles, Player localPlayer, Set<String> names, ScanStats scanStats)
    {
        WorldView topLevel = client.getTopLevelWorldView();
        if (topLevel == null)
        {
            return;
        }
        collectNamesFromWorldView(topLevel, center, radiusTiles, localPlayer, names, scanStats);
        for (WorldView subWorldView : topLevel.worldViews())
        {
            collectNamesFromWorldView(subWorldView, center, radiusTiles, localPlayer, names, scanStats);
        }
    }

    private void collectNamesFromWorldView(
        WorldView worldView,
        WorldPoint center,
        int radiusTiles,
        Player localPlayer,
        Set<String> names,
        ScanStats scanStats
    )
    {
        if (worldView == null)
        {
            return;
        }
        scanStats.worldViewsScanned++;

        for (Player player : worldView.players())
        {
            scanStats.playersSeen++;
            if (player == null || player == localPlayer)
            {
                continue;
            }

            String playerName = player.getName();
            WorldPoint playerLocation = player.getWorldLocation();
            if (playerName == null || playerLocation == null)
            {
                continue;
            }

            if (playerLocation.getPlane() != center.getPlane())
            {
                continue;
            }

            if (center.distanceTo2D(playerLocation) > radiusTiles)
            {
                continue;
            }
            scanStats.playersWithinRadius++;

            String normalizedName = normalizePlayerName(playerName);
            if (normalizedName != null && names.add(normalizedName))
            {
                scanStats.playersAdded++;
            }
        }
    }

    @SuppressWarnings("deprecation")
    private static final int THEATRE_OF_BLOOD_STATE = Varbits.THEATRE_OF_BLOOD;

    @SuppressWarnings("deprecation")
    private int getToaTeamCount()
    {
        return Math.min(client.getVarbitValue(Varbits.TOA_MEMBER_0_HEALTH), 1) +
            Math.min(client.getVarbitValue(Varbits.TOA_MEMBER_1_HEALTH), 1) +
            Math.min(client.getVarbitValue(Varbits.TOA_MEMBER_2_HEALTH), 1) +
            Math.min(client.getVarbitValue(Varbits.TOA_MEMBER_3_HEALTH), 1) +
            Math.min(client.getVarbitValue(Varbits.TOA_MEMBER_4_HEALTH), 1) +
            Math.min(client.getVarbitValue(Varbits.TOA_MEMBER_5_HEALTH), 1) +
            Math.min(client.getVarbitValue(Varbits.TOA_MEMBER_6_HEALTH), 1) +
            Math.min(client.getVarbitValue(Varbits.TOA_MEMBER_7_HEALTH), 1);
    }

    /**
     * The Fractured Archive's party slots, one varbit per member like ToA's
     * (non-zero while the slot is filled) — the same read RuneLite's loot
     * tracker uses for ToA's team size.
     */
    private int getTfaTeamCount()
    {
        return Math.min(client.getVarbitValue(VarbitID.TFA_CLIENT_P0), 1) +
            Math.min(client.getVarbitValue(VarbitID.TFA_CLIENT_P1), 1) +
            Math.min(client.getVarbitValue(VarbitID.TFA_CLIENT_P2), 1) +
            Math.min(client.getVarbitValue(VarbitID.TFA_CLIENT_P3), 1) +
            Math.min(client.getVarbitValue(VarbitID.TFA_CLIENT_P4), 1) +
            Math.min(client.getVarbitValue(VarbitID.TFA_CLIENT_P5), 1) +
            Math.min(client.getVarbitValue(VarbitID.TFA_CLIENT_P6), 1) +
            Math.min(client.getVarbitValue(VarbitID.TFA_CLIENT_P7), 1);
    }

    @SuppressWarnings("deprecation")
    private int getTobTeamCount()
    {
        return Math.min(client.getVarbitValue(Varbits.THEATRE_OF_BLOOD_ORB1), 1) +
            Math.min(client.getVarbitValue(Varbits.THEATRE_OF_BLOOD_ORB2), 1) +
            Math.min(client.getVarbitValue(Varbits.THEATRE_OF_BLOOD_ORB3), 1) +
            Math.min(client.getVarbitValue(Varbits.THEATRE_OF_BLOOD_ORB4), 1) +
            Math.min(client.getVarbitValue(Varbits.THEATRE_OF_BLOOD_ORB5), 1);
    }

    private int getCoxTeamCount()
    {
        if (client.getVarbitValue(VarbitID.RAIDS_CLIENT_INDUNGEON) == 0)
        {
            return 0;
        }
        return Math.max(client.getVarbitValue(VarbitID.RAIDS_CLIENT_PARTYSIZE), 1);
    }

    private String normalizePlayerName(String rawName)
    {
        if (rawName == null)
        {
            return null;
        }

        String normalized = Text.toJagexName(Text.removeTags(rawName)).trim();
        return normalized.isEmpty() ? null : normalized;
    }

    private static final class ScanStats
    {
        int worldViewsScanned;
        int playersSeen;
        int playersWithinRadius;
        int playersAdded;
    }

    @AllArgsConstructor(access = AccessLevel.PRIVATE)
    public static final class NearbyPlayerTrace
    {
        private final List<String> nearbyPlayers;
        private final int radiusTiles;
        private final String localPlayer;
        private final WorldPoint localWorldPoint;
        private final boolean inRaidContext;
        private final String raidType;
        private final String sourceName;
        private final String rosterSource;
        private final boolean localPlayerInRoster;
        private final int raidPartySize;
        private final int toaTeamCount;
        private final int tobTeamCount;
        private final int coxTeamCount;
        private final boolean inParty;
        private final int partySize;
        private final int worldViewsScanned;
        private final int playersSeen;
        private final int playersWithinRadius;
        private final int uniquePlayersAdded;
        private final int authoritativeRosterSize;
        private final int fallbackRosterSize;
        private final long capturedAtMs;
        private final String fallbackReason;

        public static NearbyPlayerTrace empty(int radiusTiles, String fallbackReason)
        {
            return new NearbyPlayerTrace(
                Collections.emptyList(),
                radiusTiles,
                null,
                null,
                false,
                "none",
                null,
                "none",
                false,
                0,
                0,
                0,
                0,
                false,
                0,
                0,
                0,
                0,
                0,
                0,
                0,
                System.currentTimeMillis(),
                fallbackReason
            );
        }

        public List<String> getNearbyPlayers()
        {
            return nearbyPlayers;
        }

        /** Where the participant list came from: {@code authoritative | solo | proximity-fallback | proximity | none}. */
        public String getRosterSource()
        {
            return rosterSource;
        }

        /** Best-evidence raid party size (receiver included); 0 for non-raid submissions. */
        public int getRaidPartySize()
        {
            return raidPartySize;
        }

        public String toDebugSummary()
        {
            String localPointSummary = localWorldPoint == null
                ? "unknown"
                : localWorldPoint.getX() + "," + localWorldPoint.getY() + "," + localWorldPoint.getPlane();
            return "radius=" + radiusTiles
                + ", localPlayer=" + (localPlayer != null ? localPlayer : "unknown")
                + ", localPoint=" + localPointSummary
                + ", inRaidContext=" + inRaidContext
                + ", raidType=" + raidType
                + ", sourceName=" + (sourceName != null ? sourceName : "none")
                + ", rosterSource=" + rosterSource
                + ", localPlayerInRoster=" + localPlayerInRoster
                + ", raidPartySize=" + raidPartySize
                + ", toaTeamCount=" + toaTeamCount
                + ", tobTeamCount=" + tobTeamCount
                + ", coxTeamCount=" + coxTeamCount
                + ", inParty=" + inParty
                + ", partySize=" + partySize
                + ", worldViewsScanned=" + worldViewsScanned
                + ", playersSeen=" + playersSeen
                + ", playersWithinRadius=" + playersWithinRadius
                + ", uniquePlayersAdded=" + uniquePlayersAdded
                + ", authoritativeRosterSize=" + authoritativeRosterSize
                + ", fallbackRosterSize=" + fallbackRosterSize
                + ", nearbyPlayers=" + nearbyPlayers
                + ", capturedAtMs=" + capturedAtMs
                + (fallbackReason != null ? ", fallbackReason=" + fallbackReason : "");
        }
    }
}

package io.droptracker.service;

import lombok.RequiredArgsConstructor;
import java.util.Arrays;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.atomic.AtomicBoolean;

import javax.annotation.Nullable;
import javax.inject.*;

import io.droptracker.DropTrackerConfig;
import io.droptracker.api.DropTrackerApi;
import io.droptracker.modelexport.GlbExporter;
import io.droptracker.models.api.ModelStatus;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;
import net.runelite.client.callback.ClientThread;

/**
 * Exports the local player's 3D model so their character — wearing whatever
 * they are wearing — can be rendered on the website and attached to
 * notifications.
 *
 * <p>Keyed by an <b>equipment fingerprint</b> rather than exported per event. A
 * GLB is a few hundred kilobytes; sending one with every personal best would be
 * absurd, and would mostly re-send an identical model. One upload per distinct
 * outfit is enough, because the render only changes when the outfit does.
 *
 * <p><b>Ask before sending.</b> Remembering only the last outfit was not enough:
 * a player alternating between two of them re-sent one on every switch, forever,
 * and the server measured four in five uploads as a model it already had (2026-09-14:
 * ~264k uploads a day, ~20% of them new). So an outfit the server may already
 * hold costs a ~200-byte question first, and the export — which runs on the
 * client thread — happens only when the answer is no. The question doubles as
 * how the server learns what the player is wearing, so switching back into known
 * gear still moves their profile.
 *
 * <p>Exports wait for the player to be <b>idle</b>. {@code Player#getModel()}
 * returns the current animation frame, so a model captured mid-attack is
 * captured mid-swing. Nothing here is time-critical, so waiting for a neutral
 * stance costs nothing and avoids a gallery of contorted characters.
 */
@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class PlayerModelService {

	/**
	 * Ticks the player must be idle before exporting. A couple of ticks avoids
	 * catching the tail of an animation that has technically ended.
	 */
	private static final int IDLE_TICKS_REQUIRED = 3;

	private final Client client;
	private final ClientThread clientThread;
	private final DropTrackerConfig config;
	private final DropTrackerApi api;
	private final ScheduledExecutorService executor;

	/**
	 * The outfit already settled with the server this session — either uploaded,
	 * or confirmed as one it holds. Null until the first is settled.
	 *
	 * <p>One entry rather than a set on purpose: switching back to an earlier
	 * outfit should ask again, because that question is what tells the server
	 * which outfit is being worn now.
	 */
	private volatile String settledFingerprint;

	/** Guards against two exports running at once — each one allocates a mesh. */
	private final AtomicBoolean exporting = new AtomicBoolean(false);

	private int idleTicks;

	/**
	 * When the next upload attempt is allowed, as a monotonic timestamp.
	 *
	 * <p>Without this a failing upload retries every tick: the fingerprint never
	 * gets recorded, the player is still idle, so the next tick exports and
	 * uploads again. A single 401 produced 258 requests in three minutes during
	 * testing, each one re-exporting the whole model.
	 */
	// Volatile: written on the executor, read on the client thread.
	private volatile long nextAttemptAtMs;

	/** How long to wait after a failed upload before trying that outfit again. */
	private static final long FAILURE_BACKOFF_MS = 5 * 60 * 1000L;

	/**
	 * The server does not know accounts it has never had a submission from, and
	 * would refuse a model from one. Wait rather than ask on every outfit change.
	 */
	private static final long UNKNOWN_ACCOUNT_BACKOFF_MS = 30 * 60 * 1000L;

	/**
	 * Floor on the gap between two uploads. Asking first already removes the
	 * repeat sends, but a player cycling through more outfits than the server
	 * keeps would miss every time, so this bounds what that can cost: a skipped
	 * upload is not recorded as settled, and the outfit goes up the next time
	 * they stand still in it.
	 */
	private static final long MIN_UPLOAD_INTERVAL_MS = 30 * 1000L;

	/** Earliest an upload may start, as a monotonic timestamp. */
	private volatile long nextUploadAtMs;

	public boolean isEnabled() {
		return config.useApi() && config.uploadCharacterModel();
	}

	public void reset() {
		settledFingerprint = null;
		idleTicks = 0;
		nextAttemptAtMs = 0;
		nextUploadAtMs = 0;
		exporting.set(false);
	}

	/**
	 * Called each game tick. Settles the current outfit with the server when it
	 * has changed and the player has been idle long enough.
	 *
	 * <p>Nothing expensive happens here: whether to export is decided off this
	 * thread, once the server has said whether it needs the model.
	 *
	 * <p>Must be called on the client thread.
	 */
	public void onTick() {
		if (!isEnabled() || client.getGameState() != GameState.LOGGED_IN) {
			return;
		}

		Player local = client.getLocalPlayer();
		if (local == null) {
			return;
		}

		if (isAnimating(local)) {
			idleTicks = 0;
			return;
		}
		idleTicks++;
		if (idleTicks < IDLE_TICKS_REQUIRED) {
			return;
		}

		String fingerprint = fingerprintOf(local);
		if (fingerprint == null || fingerprint.equals(settledFingerprint)) {
			return;
		}
		if (System.currentTimeMillis() < nextAttemptAtMs) {
			return;
		}
		if (!exporting.compareAndSet(false, true)) {
			return;
		}

		// Read here because it is a client read, and it decides whether a model
		// the server already holds is still missing the pet beside it.
		final boolean petOut = client.getFollower() != null;
		try {
			executor.execute(() -> settle(fingerprint, petOut));
		} catch (RuntimeException e) {
			// Never let a refused submission hold the guard — or reach the tick.
			exporting.set(false);
			log.debug("Could not schedule the outfit check: {}", e.toString());
		}
	}

	/** What to do about an outfit once the server has answered. */
	enum Action {
		/** Export and send it. */
		UPLOAD,
		/** The server has it; nothing more to do this session. */
		SETTLED,
		/** The server does not know this account yet. */
		UNKNOWN_ACCOUNT,
		/** Held back by the upload floor; try again later. */
		WAIT
	}

	/**
	 * Pure decision, so the interesting cases are testable without a client.
	 *
	 * @param status what the server answered, or null when it could not be asked
	 *               — which must lead to an upload, the behaviour that predates
	 *               the check endpoint.
	 */
	static Action decide(@Nullable ModelStatus status, boolean petOut, long now, long nextUploadAtMs) {
		if (status != null && !status.isAccepted()) {
			return Action.UNKNOWN_ACCOUNT;
		}
		// A stored outfit can predate the pet now following the player, and the
		// fingerprint cannot say so — it covers the character, not the follower.
		if (status != null && status.hasModel() && (!petOut || status.hasPet())) {
			return Action.SETTLED;
		}
		if (now < nextUploadAtMs) {
			return Action.WAIT;
		}
		return Action.UPLOAD;
	}

	/** Asks the server about an outfit, then exports only if it needs one. */
	private void settle(String fingerprint, boolean petOut) {
		boolean release = true;
		try {
			Action action = decide(api.checkPlayerModel(fingerprint), petOut,
					System.currentTimeMillis(), nextUploadAtMs);
			switch (action) {
				case SETTLED:
					// The question itself told the server what is being worn,
					// which is all the re-upload it replaces ever achieved.
					settledFingerprint = fingerprint;
					nextAttemptAtMs = 0;
					log.debug("Server already holds outfit {}", fingerprint);
					break;
				case UNKNOWN_ACCOUNT:
					nextAttemptAtMs = System.currentTimeMillis() + UNKNOWN_ACCOUNT_BACKOFF_MS;
					break;
				case WAIT:
					// Hold the whole cycle, not just the upload: without this
					// the question would be asked again on the very next tick.
					nextAttemptAtMs = nextUploadAtMs;
					break;
				case UPLOAD:
				default:
					captureAndUpload(fingerprint);
					// Only now has the guard changed hands: if the hop threw,
					// the finally below has to release it.
					release = false;
					break;
			}
		} catch (Exception e) {
			log.debug("Could not settle outfit {}: {}", fingerprint, e.toString());
		} finally {
			if (release) {
				exporting.set(false);
			}
		}
	}

	/** Exports on the client thread, then uploads off it. */
	private void captureAndUpload(String fingerprint) {
		clientThread.invoke(() -> {
			byte[] model = null;
			byte[] petModel = null;
			try {
				Player local = client.getGameState() == GameState.LOGGED_IN
						? client.getLocalPlayer() : null;
				// The outfit can change between the question and the answer, and
				// a model exported for a different one would be filed under the
				// wrong key. The next tick picks the new one up.
				if (local != null && fingerprint.equals(fingerprintOf(local))) {
					model = exportModel(local);
					petModel = exportPet();
				}
			} catch (Exception e) {
				log.debug("Could not export the player model: {}", e.toString());
			}

			if (model == null) {
				exporting.set(false);
				return;
			}

			final byte[] modelBytes = model;
			final byte[] petBytes = petModel;
			// Upload off the client thread: it is a network round-trip with a
			// payload measured in tens of kilobytes. The guard is released by
			// whoever ends up owning the work, so a refused submission (the
			// executor is shutting down) has to release it here or the uploader
			// is stuck for the rest of the session.
			try {
				executor.execute(() -> {
					try {
						if (api.uploadPlayerModel(fingerprint, modelBytes, petBytes)) {
							settledFingerprint = fingerprint;
							nextAttemptAtMs = 0;
							nextUploadAtMs = System.currentTimeMillis() + MIN_UPLOAD_INTERVAL_MS;
							log.debug("Uploaded character model for outfit {}", fingerprint);
						} else {
							// Back off rather than re-exporting on the very next tick.
							nextAttemptAtMs = System.currentTimeMillis() + FAILURE_BACKOFF_MS;
							log.debug("Model upload failed; not retrying for {} minutes",
									FAILURE_BACKOFF_MS / 60000);
						}
					} finally {
						exporting.set(false);
					}
				});
			} catch (RuntimeException e) {
				exporting.set(false);
				throw e;
			}
		});
	}

	/**
	 * Manually captures the player's current model and pins it as their
	 * profile model on the website. Triggered by the panel's "Send Player
	 * Model" button, so unlike {@link #onTick()} it does not wait for the
	 * player to be idle — the player chose this exact moment — and it does not
	 * skip already-uploaded outfits, because the point is to (re)pin this one.
	 *
	 * <p>Deliberately gated only on {@link DropTrackerConfig#useApi()}, not on
	 * the automatic-upload toggle: pressing the button is explicit consent.
	 *
	 * <p>May be called from any thread; the capture hops to the client thread
	 * and the upload to the executor. The callback receives a short
	 * user-facing result message and always runs on the Swing EDT.
	 */
	public void sendCurrentModel(java.util.function.BiConsumer<Boolean, String> callback) {
		if (!config.useApi()) {
			finish(callback, false, "Enable the DropTracker API in the plugin settings first");
			return;
		}
		if (!exporting.compareAndSet(false, true)) {
			finish(callback, false, "Already sending a model — try again in a moment");
			return;
		}
		clientThread.invoke(() -> {
			Player local = client.getGameState() == GameState.LOGGED_IN
					? client.getLocalPlayer() : null;
			if (local == null) {
				exporting.set(false);
				finish(callback, false, "Log in to send your player model");
				return;
			}

			String fingerprint = fingerprintOf(local);
			byte[] model = null;
			byte[] petModel = null;
			try {
				model = exportModel(local);
				petModel = exportPet();
			} catch (Exception e) {
				log.debug("Could not export the player model: {}", e.toString());
			}
			if (fingerprint == null || model == null) {
				exporting.set(false);
				finish(callback, false, "Could not capture your model — try again");
				return;
			}

			final String fp = fingerprint;
			final byte[] modelBytes = model;
			final byte[] petBytes = petModel;
			executor.execute(() -> {
				boolean ok = false;
				try {
					ok = api.uploadPlayerModel(fp, modelBytes, petBytes, true);
				} catch (Exception e) {
					log.debug("Manual model upload failed: {}", e.toString());
				} finally {
					exporting.set(false);
				}
				if (ok) {
					// The automatic path now knows this outfit is settled.
					settledFingerprint = fp;
					nextAttemptAtMs = 0;
				}
				finish(callback, ok, ok
						? "Model sent! Your profile now shows this outfit"
						: "Upload failed — check your connection and try again");
			});
		});
	}

	private static void finish(java.util.function.BiConsumer<Boolean, String> callback,
	                           boolean ok, String message) {
		javax.swing.SwingUtilities.invokeLater(() -> callback.accept(ok, message));
	}

	/** True while the player is doing anything other than standing still. */
	private boolean isAnimating(Player local) {
		return local.getAnimation() != -1
				|| local.getPoseAnimation() != local.getIdlePoseAnimation();
	}

	@Nullable
	private byte[] exportModel(Player local) throws Exception {
		Model model = local.getModel();
		return model == null ? null : GlbExporter.toBytes(client, model, "player");
	}

	/**
	 * The player's pet, if one is following them. Optional in every sense: a
	 * failure here must not cost us the player's own model.
	 */
	@Nullable
	private byte[] exportPet() {
		try {
			NPC follower = client.getFollower();
			Model model = follower == null ? null : follower.getModel();
			return model == null ? null : GlbExporter.toBytes(client, model, "pet");
		} catch (Exception e) {
			log.debug("Could not export the pet model: {}", e.toString());
			return null;
		}
	}

	/**
	 * Fingerprint of the local player's current outfit, or null without one.
	 *
	 * <p>What a personal best attaches so the server can pair the time with the
	 * model of the outfit it was set in: the automatic upload files that model
	 * under exactly this key, so the two meet without any further exchange.
	 * Cheap (no export, no upload) and deliberately not gated on
	 * {@link #isEnabled()} - the caller owns the consent decision.
	 *
	 * <p>Must be called on the client thread.
	 */
	@Nullable
	public String currentFingerprint() {
		return client == null ? null : fingerprintOf(client.getLocalPlayer());
	}

	/**
	 * A stable identifier for "how this character currently looks".
	 *
	 * <p>Covers worn equipment, body kits and colours, because all three change
	 * the rendered model. Two players in identical gear produce the same
	 * fingerprint, which is fine — it keys a cache, not an identity.
	 */
	@Nullable
	String fingerprintOf(Actor actor) {
		if (!(actor instanceof Player)) {
			return null;
		}
		PlayerComposition composition = ((Player) actor).getPlayerComposition();
		if (composition == null) {
			return null;
		}

		int[] equipment = composition.getEquipmentIds();
		int[] colors = composition.getColors();
		if (equipment == null) {
			return null;
		}

		// A plain hash rather than a cryptographic digest: this is a cache key,
		// and collisions cost at most a stale render.
		int hash = 17;
		hash = hash * 31 + Arrays.hashCode(equipment);
		hash = hash * 31 + (colors == null ? 0 : Arrays.hashCode(colors));
		hash = hash * 31 + composition.getGender();
		return Integer.toHexString(hash);
	}
}

package io.droptracker.service;

import lombok.AllArgsConstructor;
import com.google.common.cache.*;

import io.droptracker.util.*;
import net.runelite.api.Client;
import net.runelite.client.plugins.loottracker.LootReceived;
import net.runelite.http.api.loottracker.LootRecordType;
import org.jetbrains.annotations.*;

import javax.inject.*;
import java.util.concurrent.TimeUnit;

/**
 * Suppresses the second loot event fired when a raid reward chest is opened
 * twice for the same completion. RuneLite records raid loot when the reward
 * interface OPENS, not when items are picked up — so a player who opens the
 * chest in the loot room, leaves the loot inside, and later claims it from the
 * collection chest at the bank produces two identical {@link LootReceived}
 * events minutes (or hours) apart. Without suppression the second event
 * submits a duplicate drop AND bumps {@link KCService}'s cached kill count,
 * which the backend then credits as a phantom kill.
 *
 * <p>Keyed per account + raid family, storing the signature of the last chest
 * bundle seen. A raid's next completion chat message re-arms it (see
 * {@link #onRaidCompletion}), so back-to-back raids that happen to roll
 * identical loot are never suppressed: the dedup scope is "since the last
 * completion of this raid", with a generous TTL as a memory backstop.
 *
 * <p>Must gate BOTH {@code DropHandler.onLootReceived} and
 * {@code KCService.onLoot} — suppressing only the drop submission would leave
 * the client's cached kill count permanently one ahead of reality. The single
 * call site in {@code DropTrackerPlugin.onLootReceived} sits before that
 * fan-out for exactly this reason.
 */
@Singleton
@AllArgsConstructor(onConstructor_ = @Inject)
public class RaidLootDeduplicator {

    private final Client client;

    private final Cache<String, String> lastChestSignature = CacheBuilder.newBuilder()
            .expireAfterWrite(2, TimeUnit.HOURS)
            .maximumSize(32L)
            .build();

    /**
     * Whether this loot event repeats a raid chest bundle already seen for the
     * current completion. First sight of a bundle records it and returns
     * false; an identical bundle for the same raid (until the next completion
     * message re-arms it) returns true.
     */
    public boolean isDuplicateRaidLoot(LootReceived event) {
        if (event.getType() != LootRecordType.EVENT) {
            return false;
        }
        boolean duplicate = isDuplicate(client.getAccountHash(), event.getName(),
                ItemStacks.signature(event.getItems()));
        if (duplicate) {
            DebugLogger.log("[RaidLootDeduplicator] suppressing re-looted raid chest; source="
                    + event.getName());
        }
        return duplicate;
    }

    /**
     * Re-arms the dedup for the raid named in a completion chat message
     * ("Your completed Theatre of Blood count is: ..."), so the next chest
     * open is always treated as new loot even if its bundle happens to match
     * the previous completion's.
     */
    public void onRaidCompletion(String bossName) {
        invalidate(client.getAccountHash(), bossName);
    }

    @VisibleForTesting
    boolean isDuplicate(long accountHash, String sourceName, String signature) {
        String family = raidFamily(sourceName);
        if (family == null) {
            return false;
        }
        String key = accountHash + "|" + family;
        String previous = lastChestSignature.getIfPresent(key);
        if (signature.equals(previous)) {
            return true;
        }
        lastChestSignature.put(key, signature);
        return false;
    }

    @VisibleForTesting
    void invalidate(long accountHash, String bossName) {
        String family = raidFamily(bossName);
        if (family != null) {
            lastChestSignature.invalidate(accountHash + "|" + family);
        }
    }

    /**
     * Collapses a raid source or chat-message boss name (any mode variant,
     * e.g. "Theatre of Blood: Entry Mode", "Chambers of Xeric Challenge Mode")
     * to its base raid name, or null for anything that is not a raid. The
     * loot event always carries the base name while the completion message may
     * carry a mode suffix; folding both to the family keys them identically.
     */
    @Nullable
    @VisibleForTesting
    static String raidFamily(String name) {
        if (name == null) {
            return null;
        }
        if (name.startsWith(NpcUtilities.TOB)) {
            return NpcUtilities.TOB;
        }
        if (name.startsWith(NpcUtilities.TOA)) {
            return NpcUtilities.TOA;
        }
        if (name.startsWith(NpcUtilities.COX)) {
            return NpcUtilities.COX;
        }
        if (name.startsWith(NpcUtilities.TFA)) {
            return NpcUtilities.TFA;
        }
        return null;
    }
}

package io.droptracker.service;

import java.lang.ref.WeakReference;
import java.util.*;

import javax.annotation.Nullable;

import net.runelite.api.*;
import org.apache.commons.lang3.ArrayUtils;

/**
 * A short rolling memory of who the local player was fighting.
 *
 * <p>Killer attribution that only looks at the death tick answers the question
 * "who is attacking me <em>right now</em>", and on the tick a player dies the
 * answer is very often "nobody": the game drops an NPC's target the moment that
 * target dies, bosses despawn with the instance, and in group content the NPC
 * has already switched to whoever is still standing. Every candidate is then
 * filtered away and the death is submitted with no source at all.
 *
 * <p>This tracker records each engagement as it is announced by
 * {@code InteractingChanged} — both directions, ours and theirs — as a
 * <em>snapshot</em> (name, NPC id, combat level) rather than a live reference,
 * so an actor that has since despawned or been garbage collected can still be
 * named. A death that no live candidate explains is then attributed to the most
 * plausible engagement from the last few ticks.
 *
 * <p>Not thread safe; every caller is on the client thread.
 */
public final class RecentCombatTracker {

    /** How stale a <em>finished</em> engagement may be and still be blamed (~7s). */
    public static final int RECENT_WINDOW_TICKS = 12;

    /**
     * How stale an engagement we never saw end may be and still be blamed (~30s).
     *
     * <p>An engagement stays "open" until the client tells us it ended, and that
     * message never arrives if the actor simply vanished (instance torn down,
     * region change, world hop). This ceiling is what stops such a leftover from
     * being blamed for an unrelated death minutes later.
     */
    public static final int OPEN_WINDOW_TICKS = 50;

    /** An engagement this fresh is treated as having been live at the death. */
    private static final int AT_DEATH_TICKS = 3;

    private static final int MAX_TRACKED = 24;

    private static final String ATTACK_OPTION = "Attack";

    /** Access-ordered so eviction drops the least recently touched engagement. */
    private final Map<String, Engagement> engagements = new LinkedHashMap<>(16, 0.75f, true);

    /** Records that {@code actor} started attacking (or otherwise targeting) us. */
    public void recordAttackedBy(@Nullable Actor actor, int tick) {
        Engagement engagement = upsert(actor, tick);
        if (engagement != null) {
            engagement.attackedUs = true;
            engagement.inboundOpen = true;
        }
    }

    /** Records that {@code actor} stopped targeting us. */
    public void endAttackedBy(@Nullable Actor actor, int tick) {
        Engagement engagement = actor != null ? engagements.get(key(actor)) : null;
        if (engagement != null && engagement.inboundOpen) {
            engagement.inboundOpen = false;
            engagement.lastTick = tick;
        }
    }

    /**
     * Records that the local player started interacting with {@code actor}.
     *
     * <p>Our own outbound target is implicitly exclusive, so any other open
     * outbound engagement is closed at the same tick.
     */
    public void recordAttacking(@Nullable Actor actor, int tick) {
        Engagement engagement = upsert(actor, tick);
        if (engagement != null) {
            engagement.weAttacked = true;
            engagement.outboundOpen = true;
        }
        endAttacking(actor, tick);
    }

    /**
     * Closes every open outbound engagement except {@code except} (pass null when
     * the local player stopped interacting with anything at all).
     */
    public void endAttacking(@Nullable Actor except, int tick) {
        String keep = except != null ? key(except) : null;
        for (Map.Entry<String, Engagement> entry : engagements.entrySet()) {
            if (entry.getKey().equals(keep)) {
                continue;
            }
            Engagement engagement = entry.getValue();
            if (engagement.outboundOpen) {
                engagement.outboundOpen = false;
                engagement.lastTick = tick;
            }
        }
    }

    /** Drops an actor from consideration — used when it dies. */
    public void forget(@Nullable Actor actor) {
        if (actor != null) {
            engagements.remove(key(actor));
        }
    }

    public void clear() {
        engagements.clear();
    }

    /**
     * @param tick       the current client tick
     * @param pvpEnabled whether another player could plausibly have killed us
     * @return the engagement most likely to explain a death on this tick
     */
    public Optional<Engagement> mostLikelyKiller(int tick, boolean pvpEnabled) {
        Engagement best = null;
        for (Engagement candidate : engagements.values()) {
            if (!eligible(candidate, tick, pvpEnabled)) {
                continue;
            }
            if (best == null || compare(candidate, best, tick) < 0) {
                best = candidate;
            }
        }
        return Optional.ofNullable(best);
    }

    /** Visible for tests: how many engagements are currently remembered. */
    public int size() {
        return engagements.size();
    }

    @Nullable
    private Engagement upsert(@Nullable Actor actor, int tick) {
        if (actor == null) {
            return null;
        }
        String key = key(actor);
        Engagement existing = engagements.get(key);
        if (existing != null) {
            existing.lastTick = tick;
            existing.actor = new WeakReference<>(actor);
            return existing;
        }

        Engagement created = snapshot(actor, tick);
        if (created == null) {
            return null;
        }
        engagements.put(key, created);
        prune(tick);
        return created;
    }

    private void prune(int tick) {
        Iterator<Engagement> values = engagements.values().iterator();
        while (values.hasNext()) {
            Engagement engagement = values.next();
            int age = tick - engagement.lastTick;
            if (age < 0 || age > OPEN_WINDOW_TICKS) {
                values.remove();
            }
        }
        // Access-ordered: the head is the least recently touched engagement.
        Iterator<String> keys = engagements.keySet().iterator();
        while (engagements.size() > MAX_TRACKED && keys.hasNext()) {
            keys.next();
            keys.remove();
        }
    }

    private static boolean eligible(Engagement engagement, int tick, boolean pvpEnabled) {
        if (engagement.player && (!pvpEnabled || engagement.friendly)) {
            // A friend or clanmate we traded with is not a killer, and outside
            // PvP no player is.
            return false;
        }
        Actor live = engagement.actor.get();
        if (live != null && live.isDead()) {
            // We killed it (or it died first); it cannot have killed us.
            return false;
        }
        int age = tick - engagement.lastTick;
        if (age < 0) {
            // Tick counter went backwards — a hop or relog; the record predates
            // this session's world and means nothing.
            return false;
        }
        return age <= (engagement.isOpen() ? OPEN_WINDOW_TICKS : RECENT_WINDOW_TICKS);
    }

    /**
     * Orders candidates best-first (negative means {@code a} is the better
     * explanation for the death).
     */
    private static int compare(Engagement a, Engagement b, int tick) {
        int result = Boolean.compare(b.wasLiveAt(tick), a.wasLiveAt(tick));
        if (result != 0) {
            return result;
        }
        // Something we were trading blows with beats something that only
        // attacked us, which beats something we merely clicked on.
        result = Integer.compare(b.directionRank(), a.directionRank());
        if (result != 0) {
            return result;
        }
        result = Boolean.compare(b.attackable, a.attackable);
        if (result != 0) {
            return result;
        }
        result = Integer.compare(b.combatLevel, a.combatLevel);
        if (result != 0) {
            return result;
        }
        return Integer.compare(b.lastTick, a.lastTick);
    }

    /**
     * Keyed on scene index for NPCs and name for players rather than on the
     * {@link Actor} itself, so nothing here keeps a despawned actor alive.
     */
    private static String key(Actor actor) {
        if (actor instanceof NPC) {
            return "n" + ((NPC) actor).getIndex();
        }
        String name = cleanName(actor.getName());
        return "p" + (name != null ? name : String.valueOf(System.identityHashCode(actor)));
    }

    /**
     * @return a snapshot of the actor, or null when it could not plausibly kill
     *         anyone (a pet, a shopkeeper, an unnamed player)
     */
    @Nullable
    private static Engagement snapshot(Actor actor, int tick) {
        if (actor instanceof NPC) {
            NPC npc = (NPC) actor;
            NPCComposition composition = npc.getTransformedComposition();
            if (composition == null) {
                composition = npc.getComposition();
            }
            if (composition == null || composition.isFollower()) {
                return null;
            }
            boolean attackable = ArrayUtils.contains(composition.getActions(), ATTACK_OPTION);
            int combatLevel = composition.getCombatLevel();
            if (!attackable && combatLevel <= 0) {
                // Dialogue partners, pets and scenery face the player too.
                return null;
            }
            String name = cleanName(npc.getName());
            if (name == null) {
                name = cleanName(composition.getName());
            }
            // isInteractible() is deliberately not required here (it is in the
            // live scan): a few instanced attackers cannot be clicked, and this
            // snapshot is only ever consulted after the live scan came up empty.
            return new Engagement(actor, name, npc.getId(), combatLevel, false, attackable, false, tick);
        }

        if (actor instanceof Player) {
            Player player = (Player) actor;
            String name = cleanName(player.getName());
            if (name == null) {
                return null;
            }
            boolean friendly = player.isFriend() || player.isClanMember() || player.isFriendsChatMember();
            return new Engagement(actor, name, null, player.getCombatLevel(), true, true, friendly, tick);
        }

        return null;
    }

    /**
     * Actor names arrive with colour tags and non-breaking spaces; a name that is
     * nothing but markup is no name at all and must not become a blank source.
     */
    @Nullable
    public static String cleanName(@Nullable String raw) {
        if (raw == null) {
            return null;
        }
        String cleaned = raw.replace('\u00A0', ' ').replaceAll("<[^>]*>", "").trim();
        return cleaned.isEmpty() ? null : cleaned;
    }

    /** An actor the local player was recently in combat with. */
    public static final class Engagement {

        private WeakReference<Actor> actor;
        private final String name;
        private final Integer npcId;
        private final int combatLevel;
        private final boolean player;
        private final boolean attackable;
        private final boolean friendly;

        private boolean attackedUs;
        private boolean weAttacked;
        private boolean inboundOpen;
        private boolean outboundOpen;
        private int lastTick;

        Engagement(Actor actor, @Nullable String name, @Nullable Integer npcId, int combatLevel,
                boolean player, boolean attackable, boolean friendly, int tick) {
            this.actor = new WeakReference<>(actor);
            this.name = name;
            this.npcId = npcId;
            this.combatLevel = combatLevel;
            this.player = player;
            this.attackable = attackable;
            this.friendly = friendly;
            this.lastTick = tick;
        }

        @Nullable
        public String getName() {
            return name;
        }

        @Nullable
        public Integer getNpcId() {
            return npcId;
        }

        public int getCombatLevel() {
            return combatLevel;
        }

        public boolean isPlayer() {
            return player;
        }

        public boolean isNpc() {
            return !player;
        }

        boolean isOpen() {
            return inboundOpen || outboundOpen;
        }

        /** Whether the engagement was, as far as we know, still running at {@code tick}. */
        boolean wasLiveAt(int tick) {
            return isOpen() || tick - lastTick <= AT_DEATH_TICKS;
        }

        int directionRank() {
            if (attackedUs && weAttacked) {
                return 2;
            }
            return attackedUs ? 1 : 0;
        }

        @Override
        public String toString() {
            return "Engagement(" + name + ", npcId=" + npcId + ", lvl=" + combatLevel
                    + ", player=" + player + ", rank=" + directionRank() + ", open=" + isOpen()
                    + ", lastTick=" + lastTick + ")";
        }
    }
}

