package io.droptracker.service;

import lombok.AccessLevel;
import lombok.RequiredArgsConstructor;
import com.google.common.collect.ImmutableSet;
import io.droptracker.models.PrivacyMode;
import java.awt.*;
import java.awt.image.BufferedImage;
import java.util.*;
import java.util.List;
import java.util.function.Consumer;
import javax.inject.*;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;
import net.runelite.api.annotations.Component;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.SpriteID;
import net.runelite.api.widgets.*;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.ui.DrawManager;
import net.runelite.client.util.ImageUtil;
import org.jetbrains.annotations.VisibleForTesting;

/**
 * Captures a single frame with the widgets the user's {@link PrivacyMode} covers
 * hidden, then puts everything back.
 *
 * <p>DMs and chat messages are plain per-frame widget hides in any layout. Hiding
 * the entire chatbox is layout-dependent: in resizable modes the chatbox is an
 * overlay on the scene, so it too is a plain hide; in fixed mode the chatbox owns
 * the bottom 142px of the client, so hiding it means expanding the viewport into
 * the freed space, patching the window-frame border strips it used to cover, and
 * reasserting all of that every frame until the capture lands (widget scripts
 * re-run constantly and would revert the mutation). That machinery lives in the
 * {@link #onBeforeRender()} state machine, driven off the plugin's event bus
 * subscription.
 *
 * <p>When an interface is open inside the chatbox (a dialog, Make-X, bank
 * search), hiding the whole box would hide something the player is interacting
 * with, so the capture degrades to hiding the transcript + DMs for that shot.
 *
 * <p>Every capture in the plugin comes through here, and only one runs at a
 * time. That is a correctness requirement, not an optimisation: hiding is a flag
 * on a shared widget, so two captures overlapping meant the first one's restore
 * unhid the chat while the second was still waiting for its frame. See
 * {@link #capture(PrivacyMode, Consumer)}.
 */
@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class ScreenshotPrivacyService {

    /** Extra rendered frames to wait after hiding before capturing, so the 3D scene finishes growing. */
    private static final int SETTLE_FRAMES = 1;

    /** Give up and restore if the frame listener never fires (GPU stall, minimised client, ...). */
    private static final int MAX_HIDDEN_FRAMES = 120;

    /** Give up if the whole cycle stalls - ticks keep coming when frames do not. */
    private static final int MAX_CYCLE_TICKS = 20;

    /** Attempts one request gets before it is answered without an image. */
    private static final int MAX_ATTEMPTS = 2;

    /**
     * How long a frame already taken can stand in for a fresh request. One kill
     * commonly produces a drop submission and a collection log submission a beat
     * apart, and they are proof of the same moment - two captures would only mean
     * two rounds of hiding the chat, with the second racing the first's restore.
     * Two game ticks is long enough to pair them up and short enough that the
     * next unrelated event still gets its own frame.
     */
    private static final long REUSE_WINDOW_MS = 1200L;

    // Border sprites we synthesise to fill the window frame edges the chatbox used to cover.
    private static final int LEFT_BORDER_SPRITE_ID = -20611;
    private static final int RIGHT_BORDER_SPRITE_ID = -20612;
    private static final int CHATBOX_PARENT_WIDTH = 519;
    private static final int LEFT_BORDER_WIDTH = 4;
    private static final int RIGHT_BORDER_WIDTH = 3;
    private static final int BORDER_HEIGHT = 142;

    /*
     * The fixed viewport is 765x503. Of that, the 3D scene container is 334px tall
     * with the chatbox visible; hiding the chatbox frees the 142px it occupied and
     * lets the scene grow to 476px.
     */
    private static final int DEFAULT_VIEW_HEIGHT = 334;
    private static final int EXPANDED_VIEW_HEIGHT = 476;
    private static final int BANK_X = 12;
    private static final int BANK_Y = 2;
    private static final int SEED_VAULT_X = 6;
    private static final int SEED_VAULT_COMPONENT_ID = 41353217;

    // The view height minus BANK_Y minus 1, since there is a 1px gap at the bottom without the plugin.
    private static final int DEFAULT_VIEW_WIDGET_HEIGHT = DEFAULT_VIEW_HEIGHT - BANK_Y - 1;
    private static final int EXPANDED_VIEW_WIDGET_HEIGHT = EXPANDED_VIEW_HEIGHT - BANK_Y - 1;

    /** The fixed viewport's main container, whose static children make up the game scene area. */
    private static final Map.Entry<Integer, Integer> FIXED_MAIN = entry(net.runelite.api.widgets.InterfaceID.FIXED_VIEWPORT, 9);

    /**
     * Interfaces that live inside the chatbox. If any of these is open the chatbox
     * must stay visible, because hiding it would hide an interface the player is
     * interacting with.
     */
    private static final Set<Map.Entry<Integer, Integer>> CHATBOX_INTERFACE_WIDGETS = ImmutableSet
        .<Map.Entry<Integer, Integer>>builder()
        // 'Rub' option (S219.0) Duel rings, Slayer Rings, Burning Amulets, etc.
        .add(entry(net.runelite.api.widgets.InterfaceID.DIALOG_OPTION, 0))
        // Player dialog (S217.0) - when your player character speaks in a dialog
        .add(entry(net.runelite.api.widgets.InterfaceID.DIALOG_PLAYER, 0))
        // Sprite dialog (S193.0) - "Are you sure you want to drop..." valuable item warnings, etc.
        .add(entry(net.runelite.api.widgets.InterfaceID.DIALOG_SPRITE, 0))
        // Message box dialog (S229.0) - NPC popups with only a "Click here to continue" option.
        .add(entry(InterfaceID.MESSAGEBOX, 0))
        // Membership benefits prompt (S284.0) - "Become a Member" chatbox popup.
        .add(entry(InterfaceID.MEMBERSHIP_BENEFITS_PROMPT, 0))
        // Skill multi-choice dialog (S270.0) - "How many would you like to..." (cutting gems, etc.)
        .add(entry(InterfaceID.SKILLMULTI, 0))
        // Bank search container
        .add(entry(net.runelite.api.widgets.InterfaceID.CHATBOX, 42))
        // Catch-all layer we recurse through: wrong PIN popup, NPC dialog, Make-X, etc.
        .add(entry(net.runelite.api.widgets.InterfaceID.CHATBOX, 566))
        .add(entry(net.runelite.api.widgets.InterfaceID.CHATBOX, 43)) // GE search
        .add(entry(InterfaceID.CHAT_LEFT, 0))
        .add(entry(InterfaceID.CHATBOX, 48)) // mes layer scrollarea
        .build();

    /** Containers that overlap the chatbox area and must be resized along with the viewport. */
    private static final Set<Map.Entry<Integer, Integer>> TO_CONTRACT_WIDGETS = ImmutableSet
        .<Map.Entry<Integer, Integer>>builder()
        .add(entry(ComponentID.BANK_CONTAINER, 0))
        .add(entry(net.runelite.api.widgets.InterfaceID.SEED_VAULT, 1))
        .build();

    private enum State {
        IDLE,
        HIDE_PENDING,
        HIDDEN,
        RESTORE_PENDING
    }

    /**
     * What a capture has to keep out of the frame, independent of how it gets
     * there. {@code transcript} implies nothing about {@code chatbox} but the
     * reverse holds, so the constructor canonicalises it: coverage comparisons
     * between two plans are then a plain componentwise implication.
     */
    @VisibleForTesting
    static final class CapturePlan {

        static final CapturePlan NOTHING = new CapturePlan(false, false, false, false);

        final boolean dms;
        final boolean transcript;
        final boolean chatbox;
        /** Fixed mode only: hide the chatbox by growing the game view into its space. */
        final boolean expandViewport;

        CapturePlan(boolean dms, boolean transcript, boolean chatbox, boolean expandViewport) {
            this.dms = dms;
            this.transcript = transcript || chatbox;
            this.chatbox = chatbox;
            this.expandViewport = expandViewport;
        }

        /** Whether a frame captured under this plan is also acceptable for {@code other}. */
        boolean covers(CapturePlan other) {
            return (dms || !other.dms)
                && (transcript || !other.transcript)
                && (chatbox || !other.chatbox);
        }
    }

    /** One caller waiting for a frame. Client-thread confined. */
    @RequiredArgsConstructor(access = AccessLevel.PRIVATE)
    private static final class Request {

        private final PrivacyMode mode;
        private final Consumer<BufferedImage> consumer;
        private int attempts;

    }

    private final Client client;
    private final ClientThread clientThread;
    private final DrawManager drawManager;
    private final SpriteManager spriteManager;

    /*
     * Everything below is client-thread confined: capture() marshals onto it, and
     * onBeforeRender / onGameTick / the frame callback all run there. No locking.
     */
    private State state = State.IDLE;

    /** Bumped per capture so a late frame callback from an aborted cycle can be ignored. */
    private int cycleId;
    private int framesHidden;
    private int cycleStartTick;
    private boolean captureRequested;
    private boolean widgetsMutated;
    private boolean bordersDrawn;

    /** What the in-flight cycle hides; null while {@link State#IDLE}. */
    private CapturePlan activePlan;

    /** Everyone riding the in-flight cycle's frame. Client-thread confined. */
    private final List<Request> pending = new ArrayList<>();

    /** Requests that need more hidden than the in-flight cycle hides. */
    private final List<Request> queued = new ArrayList<>();

    /** Widgets this service hid, so a restore puts back exactly those. */
    private final List<Widget> hiddenByUs = new ArrayList<>();

    private BufferedImage lastImage;
    private CapturePlan lastImagePlan;
    private long lastImageAt;

    private boolean borderSpritesLoaded;
    private SpritePixels lastWindowFrameLeftSprite;
    private SpritePixels lastSidePanelLeftUpperSprite;

    private static Map.Entry<Integer, Integer> entry(int group, int child) {
        return new AbstractMap.SimpleEntry<>(group, child);
    }

    /**
     * Captures a frame with the given privacy mode applied and hands it to
     * {@code consumer}. Callable from any thread; the consumer runs on the client
     * thread, so keep heavy work off it.
     *
     * <p>Captures are single-flight. One kill can produce several submissions at
     * once - a drop over the screenshot threshold, the collection log slot it
     * filled, a personal best - and each of those asks for proof. They share one
     * frame: requests arriving while a capture is being set up ride it, and a
     * request arriving just after one completes is answered from
     * {@link #REUSE_WINDOW_MS the frame just taken} rather than making the client
     * draw, hide and restore all over again. Two overlapping captures used to
     * unhide each other's widgets mid-flight, which is how a screenshot with the
     * private chat still in it got submitted.
     *
     * <p>The consumer is passed {@code null} when no frame could be captured (the
     * client stopped rendering, or the layout kept moving under the capture). It
     * is never passed a frame with the privacy mode unapplied.
     */
    public void capture(PrivacyMode mode, Consumer<BufferedImage> consumer) {
        clientThread.invoke(() -> accept(new Request(mode, consumer)));
    }

    /** Restores any in-flight mutation; called from the plugin's shutDown. */
    public void shutDown() {
        clientThread.invoke(() -> {
            cycleId++;
            state = State.IDLE;
            activePlan = null;
            captureRequested = false;
            forgetLastImage();
            restoreWidgets();
            clearBorderSprites();

            // Answer anything still waiting rather than dropping it: the plugin
            // is going away, but the submission it belongs to can still be sent
            // without proof.
            final List<Request> waiting = new ArrayList<>(pending);
            waiting.addAll(queued);
            pending.clear();
            queued.clear();
            for (final Request request : waiting) {
                deliver(request, null);
            }
        });
    }

    /**
     * Watchdog, driven off the game tick because it keeps running when rendering
     * does not. A cycle that never sees another frame would otherwise hold every
     * later capture behind it forever.
     */
    public void onGameTick() {
        if (state != State.IDLE) {
            if (client.getTickCount() - cycleStartTick > MAX_CYCLE_TICKS) {
                abort("no rendered frame within " + MAX_CYCLE_TICKS + " ticks");
            }
            return;
        }

        // Nothing is holding a full-size frame open once it is too old to reuse.
        if (lastImage != null && elapsedSinceLastImage() > REUSE_WINDOW_MS) {
            forgetLastImage();
        }
        drainQueued();
    }

    private void accept(Request request) {
        final CapturePlan plan = planFor(request.mode);

        // The frame taken moments ago is the same moment this request is asking
        // about, and it already hides at least as much: reuse it.
        if (lastImage != null && lastImagePlan != null && lastImagePlan.covers(plan)
            && elapsedSinceLastImage() <= REUSE_WINDOW_MS) {
            deliver(request, lastImage);
            return;
        }

        if (state != State.IDLE) {
            if (activePlan.covers(plan)) {
                pending.add(request);
            } else {
                // Wants more hidden than the frame being set up; wait for the next cycle.
                queued.add(request);
            }
            return;
        }

        startCycle(plan, request);
    }

    private void startCycle(CapturePlan plan, Request first) {
        cycleId++;
        activePlan = plan;
        framesHidden = 0;
        captureRequested = false;
        cycleStartTick = client.getTickCount();
        hiddenByUs.clear();
        pending.add(first);
        // Nothing is hidden yet: the hide is applied from onBeforeRender so it
        // lands in the very frame that gets captured, rather than racing a draw
        // that may already be underway.
        state = State.HIDE_PENDING;
    }

    /**
     * Turns the player's configured mode into the set of things this capture must
     * keep out of the frame, given the layout in front of us right now.
     */
    private CapturePlan planFor(PrivacyMode mode) {
        if (mode == null || !mode.hidesDms()) {
            return CapturePlan.NOTHING;
        }

        // "Hide DMs" has to mean the DMs, wherever the client draws them. With
        // split private chat off there is no PM overlay at all and private
        // messages are ordinary transcript lines, so the transcript goes too -
        // otherwise the setting silently does nothing for those players.
        final boolean hideTranscript = mode.hidesMessages() || dmsAreInTranscript();

        if (!mode.hidesChatbox()) {
            return new CapturePlan(true, hideTranscript, false, false);
        }

        // Hiding the whole chatbox. With an interface open inside it (a dialog,
        // Make-X, bank search) that would hide something the player is using, so
        // the capture degrades to the transcript + DMs.
        if (isChatboxInterfaceOpen()) {
            return new CapturePlan(true, true, false, false);
        }

        // Resizable layouts draw the chatbox as an overlay on the scene, so a
        // plain hide is enough. Fixed mode needs the viewport surgery, and only
        // while logged in - a plain hide there would leave a black hole.
        if (client.isResized()) {
            return new CapturePlan(true, true, true, false);
        }
        if (client.getGameState() != GameState.LOGGED_IN) {
            return new CapturePlan(true, true, false, false);
        }
        return new CapturePlan(true, true, true, true);
    }

    /**
     * Whether private messages are rendered as ordinary chat transcript lines.
     * The split private chat overlay is its own interface: when the option is off
     * the client never loads it, so an absent widget is the signal that DMs are
     * inline. (With split chat on, the transcript still lists DMs under its
     * Private tab - "Hide messages + DMs" is the mode that covers that.)
     */
    private boolean dmsAreInTranscript() {
        return client.getWidget(InterfaceID.PmChat.CONTAINER) == null;
    }

    private long elapsedSinceLastImage() {
        return System.currentTimeMillis() - lastImageAt;
    }

    private void forgetLastImage() {
        lastImage = null;
        lastImagePlan = null;
        lastImageAt = 0L;
    }

    // region capture cycle

    public void onBeforeRender() {
        if (state == State.IDLE) {
            drainQueued();
            return;
        }

        // The player resized or logged out mid-cycle; bail out rather than fight
        // the layout. Only the viewport surgery cares - a plain widget hide works
        // in any layout.
        if (activePlan.expandViewport
            && (client.isResized() || client.getGameState() != GameState.LOGGED_IN)) {
            abort("client left fixed mode mid-capture");
            return;
        }

        switch (state) {
            case HIDE_PENDING:
                applyPlan(true);
                state = State.HIDDEN;
                maybeRequestFrame();
                framesHidden++;
                break;

            case HIDDEN:
                // Widget scripts re-run constantly, so the mutation has to be reasserted per frame.
                applyPlan(false);
                maybeRequestFrame();
                framesHidden++;

                if (framesHidden > MAX_HIDDEN_FRAMES) {
                    abort("timed out after " + MAX_HIDDEN_FRAMES + " frames");
                }
                break;

            case RESTORE_PENDING:
                restoreWidgets();
                finishCycle();
                break;

            default:
                break;
        }
    }

    /** Hides everything the active plan covers; safe to call every frame. */
    private void applyPlan(boolean transition) {
        if (activePlan.dms) {
            hideIfVisible(InterfaceID.PmChat.CONTAINER);
        }

        if (activePlan.chatbox) {
            if (activePlan.expandViewport) {
                expandOverChatbox(transition);
            } else {
                hideIfVisible(InterfaceID.Chatbox.UNIVERSE);
            }
        } else if (activePlan.transcript) {
            hideIfVisible(InterfaceID.Chatbox.CHATDISPLAY);
        }
    }

    /**
     * Hides one widget and remembers that we were the ones who did it, so the
     * restore puts back exactly what it took away - a widget the game itself had
     * hidden (a dialog replacing the transcript, split chat off) is left alone.
     * Already hidden by us means nothing to do; hidden again by a script that
     * re-ran means it comes back visible and gets re-hidden here.
     */
    private void hideIfVisible(@Component int componentId) {
        final Widget widget = client.getWidget(componentId);
        if (widget == null || widget.isSelfHidden()) {
            return;
        }

        widget.setHidden(true);
        for (final Widget alreadyTracked : hiddenByUs) {
            if (alreadyTracked == widget) {
                return;
            }
        }
        hiddenByUs.add(widget);
    }

    private void maybeRequestFrame() {
        // Only the viewport expansion needs a settling frame: the 3D scene has to
        // finish growing into the freed space before the shot is worth taking.
        final int settleFrames = activePlan.expandViewport ? SETTLE_FRAMES : 0;
        if (captureRequested || framesHidden < settleFrames) {
            return;
        }

        captureRequested = true;
        final int requestCycle = cycleId;
        drawManager.requestNextFrameListener(image -> onFrameReady(requestCycle, image));
    }

    /** Called on the client thread once the hidden frame has finished drawing. */
    private void onFrameReady(int requestCycle, Image image) {
        if (requestCycle != cycleId || state != State.HIDDEN) {
            // Stale callback from a cycle we already gave up on.
            return;
        }

        final BufferedImage captured = toBufferedImage(image);
        lastImage = captured;
        lastImagePlan = activePlan;
        lastImageAt = System.currentTimeMillis();

        // Detach this cycle's waiters before anything below can start the next
        // one, or a queued request that wanted more hidden than this frame hides
        // would be handed this frame anyway.
        final List<Request> waiting = new ArrayList<>(pending);
        pending.clear();

        state = State.RESTORE_PENDING;
        if (!activePlan.expandViewport) {
            // A plain widget hide can go back immediately now the frame is drawn;
            // only the viewport surgery has to unwind on a render pass.
            restoreWidgets();
            finishCycle();
        }

        for (final Request request : waiting) {
            deliver(request, captured);
        }
    }

    private void finishCycle() {
        state = State.IDLE;
        activePlan = null;
        captureRequested = false;
        drainQueued();
    }

    private void deliver(Request request, BufferedImage image) {
        try {
            request.consumer.accept(image);
        } catch (Exception e) {
            log.warn("screenshot consumer failed", e);
        }
    }

    /** Starts a cycle for anything that could not ride the last one. */
    private void drainQueued() {
        if (queued.isEmpty() || state != State.IDLE) {
            return;
        }

        final List<Request> batch = new ArrayList<>(queued);
        queued.clear();
        for (final Request request : batch) {
            accept(request);
        }
    }

    private void abort(String reason) {
        log.debug("screenshot privacy capture aborted: {}", reason);
        cycleId++;
        state = State.IDLE;
        activePlan = null;
        captureRequested = false;
        restoreWidgets();

        // Give each waiting request one more go with a freshly computed plan; the
        // client may simply have left fixed mode. Anything already retried is
        // answered with no image rather than left hanging - a submission without
        // proof beats a submission that never arrives, and it is never the
        // unhidden frame.
        final List<Request> waiting = new ArrayList<>(pending);
        pending.clear();
        for (final Request request : waiting) {
            if (++request.attempts >= MAX_ATTEMPTS) {
                deliver(request, null);
            } else {
                queued.add(request);
            }
        }

        drainQueued();
    }

    // endregion

    // region fixed-mode widget mutation (derived from Fixed Mode Hide Chat)

    /**
     * Fixed mode only: grow the game view into the 142px the chatbox occupies and
     * hide the frame around it. The DM/transcript hiding this rides on top of is
     * applied by {@link #applyPlan(boolean)}.
     */
    private void expandOverChatbox(boolean transition) {
        widgetsMutated = true;

        setViewSizeTo(DEFAULT_VIEW_HEIGHT, EXPANDED_VIEW_HEIGHT);
        setWidgetsSizeTo(DEFAULT_VIEW_WIDGET_HEIGHT, EXPANDED_VIEW_WIDGET_HEIGHT);
        keepContainersOnScreen(transition);

        hideIfVisible(ComponentID.CHATBOX_FRAME);

        drawChatboxBorders();
    }

    private void restoreWidgets() {
        for (final Widget widget : hiddenByUs) {
            widget.setHidden(false);
        }
        hiddenByUs.clear();

        if (!widgetsMutated || client.isResized()) {
            widgetsMutated = false;
            return;
        }

        widgetsMutated = false;

        setViewSizeTo(EXPANDED_VIEW_HEIGHT, DEFAULT_VIEW_HEIGHT);
        setWidgetsSizeTo(EXPANDED_VIEW_WIDGET_HEIGHT, DEFAULT_VIEW_WIDGET_HEIGHT);
        keepContainersOnScreen(true);
        removeChatboxBorders();
    }

    /**
     * The bank and seed vault containers drift off screen when the viewport
     * resizes under them, so their position is pinned explicitly on every frame
     * we touch the layout.
     */
    private void keepContainersOnScreen(boolean transition) {
        final Widget bankWidget = client.getWidget(ComponentID.BANK_CONTAINER);
        if (bankWidget != null && !bankWidget.isSelfHidden()) {
            // Re-run [clientscript,bankmain_init] so the tag tabs re-extend to the
            // new height. Only on the frames where the layout actually changes -
            // running it every frame tanks performance.
            if (transition) {
                client.createScriptEventBuilder(bankWidget.getOnLoadListener())
                    .setSource(bankWidget)
                    .build()
                    .run();
            }

            pinWidget(bankWidget, BANK_X);
        }

        final Widget seedVaultWidget = client.getWidget(SEED_VAULT_COMPONENT_ID);
        if (seedVaultWidget != null && !seedVaultWidget.isSelfHidden()) {
            pinWidget(seedVaultWidget, SEED_VAULT_X);
        }
    }

    private static void pinWidget(Widget widget, int x) {
        widget.setOriginalX(x);
        widget.setOriginalY(BANK_Y);
        widget.setXPositionMode(WidgetPositionMode.ABSOLUTE_LEFT);
        widget.setYPositionMode(WidgetPositionMode.ABSOLUTE_TOP);
        widget.revalidateScroll();
    }

    private static void setWidgetHeight(Widget widget, int height) {
        widget.setOriginalHeight(height);
        widget.setHeightMode(WidgetSizeMode.ABSOLUTE);
        widget.revalidateScroll();
    }

    private static void changeWidgetHeight(int originalHeight, int newHeight, Widget widget) {
        if (widget.getHeight() != originalHeight) {
            return;
        }

        setWidgetHeight(widget, newHeight);

        final Widget[] nestedChildren = widget.getNestedChildren();
        if (nestedChildren != null) {
            for (final Widget nestedChild : nestedChildren) {
                if (nestedChild != null && nestedChild.getHeight() == originalHeight) {
                    setWidgetHeight(nestedChild, newHeight);
                }
            }
        }

        final Widget[] dynamicChildren = widget.getDynamicChildren();
        if (dynamicChildren != null) {
            for (final Widget child : dynamicChildren) {
                if (child != null && child.getHeight() == originalHeight) {
                    setWidgetHeight(child, newHeight);
                }
            }
        }
    }

    private void setWidgetsSizeTo(int originalHeight, int newHeight) {
        for (final Map.Entry<Integer, Integer> entry : TO_CONTRACT_WIDGETS) {
            final Widget widget = entry.getValue() == 0
                ? client.getWidget(entry.getKey())
                : client.getWidget(entry.getKey(), entry.getValue());

            if (widget != null && !widget.isSelfHidden()) {
                changeWidgetHeight(originalHeight, newHeight, widget);
            }
        }
    }

    private void setViewSizeTo(int originalHeight, int newHeight) {
        final Widget viewport = client.getWidget(InterfaceID.Toplevel.MAIN);
        if (viewport != null) {
            setWidgetHeight(viewport, newHeight);
        }

        final Widget fixedMain = client.getWidget(FIXED_MAIN.getKey(), FIXED_MAIN.getValue());
        if (fixedMain == null || fixedMain.getHeight() != originalHeight) {
            return;
        }

        setWidgetHeight(fixedMain, newHeight);

        final Widget[] staticChildren = fixedMain.getStaticChildren();
        if (staticChildren == null) {
            return;
        }

        for (final Widget child : staticChildren) {
            if (child != null) {
                changeWidgetHeight(originalHeight, newHeight, child);
            }
        }
    }

    // endregion

    // region chatbox interface detection

    /**
     * True when something the player is interacting with lives inside the
     * chatbox - a dialog, the bank search, Make-X, a fairy ring code entry.
     * Hiding the chatbox would hide it too.
     */
    private boolean isChatboxInterfaceOpen() {
        final Widget fairyRingSearch = client.getWidget(net.runelite.api.widgets.InterfaceID.CHATBOX, 38);
        if (fairyRingSearch != null) {
            final Widget[] children = fairyRingSearch.getDynamicChildren();
            if (children != null && children.length > 0 && children[0] != null
                && children[0].getText() != null && children[0].getText().contains("fairy")) {
                return true;
            }
        }

        for (final Map.Entry<Integer, Integer> entry : CHATBOX_INTERFACE_WIDGETS) {
            final Widget widget = client.getWidget(entry.getKey(), entry.getValue());
            if (widget == null || widget.isSelfHidden()) {
                continue;
            }

            final Widget[] staticChildren = widget.getStaticChildren();
            final Widget[] nestedChildren = widget.getNestedChildren();

            final boolean found;
            if (staticChildren != null && staticChildren.length > 0) {
                found = anyVisible(staticChildren);
            } else if (nestedChildren != null && nestedChildren.length > 0) {
                found = anyVisible(nestedChildren);
            } else {
                found = isVisible(widget);
            }

            if (found) {
                return true;
            }
        }

        return false;
    }

    private static boolean anyVisible(Widget[] widgets) {
        return Arrays.stream(widgets).anyMatch(ScreenshotPrivacyService::isVisible);
    }

    private static boolean isVisible(Widget widget) {
        return widget != null && !widget.isSelfHidden() && !widget.isHidden();
    }

    // endregion

    // region chatbox border sprites

    /**
     * The chatbox covers 4px of window frame on the left and 3px on the right.
     * Once it is hidden those strips are empty, so the equivalent slices are
     * cropped out of the client's own frame sprites (respecting resource packs)
     * and drawn as children of the chatbox parent.
     */
    private void drawChatboxBorders() {
        final Widget chatbox = client.getWidget(ComponentID.CHATBOX_PARENT);
        if (chatbox == null || !updateBorderSprites() || chatbox.getChild(1) != null) {
            return;
        }

        final Widget leftBorder = chatbox.createChild(-1, WidgetType.GRAPHIC);
        leftBorder.setSpriteId(LEFT_BORDER_SPRITE_ID);
        leftBorder.setOriginalWidth(LEFT_BORDER_WIDTH);
        leftBorder.setOriginalHeight(BORDER_HEIGHT);
        leftBorder.setOriginalX(0);
        leftBorder.setOriginalY(0);
        leftBorder.setHidden(false);
        leftBorder.revalidate();

        final Widget rightBorder = chatbox.createChild(-1, WidgetType.GRAPHIC);
        rightBorder.setSpriteId(RIGHT_BORDER_SPRITE_ID);
        rightBorder.setOriginalWidth(RIGHT_BORDER_WIDTH);
        rightBorder.setOriginalHeight(BORDER_HEIGHT);
        rightBorder.setOriginalX(CHATBOX_PARENT_WIDTH - RIGHT_BORDER_WIDTH);
        rightBorder.setOriginalY(0);
        rightBorder.setHidden(false);
        rightBorder.revalidate();

        bordersDrawn = true;
    }

    private void removeChatboxBorders() {
        if (!bordersDrawn) {
            return;
        }

        bordersDrawn = false;

        final Widget chatbox = client.getWidget(ComponentID.CHATBOX_PARENT);
        if (chatbox != null && chatbox.getChild(1) != null) {
            chatbox.deleteAllChildren();
        }
    }

    private boolean updateBorderSprites() {
        final SpritePixels windowFrameLeftSprite = client.getSpriteOverrides().get(SpriteID.BACKLEFT1);
        final SpritePixels sidePanelLeftUpperSprite = client.getSpriteOverrides().get(SpriteID.SIDE_BACKGROUND_LEFT1);

        if (borderSpritesLoaded
            && windowFrameLeftSprite == lastWindowFrameLeftSprite
            && sidePanelLeftUpperSprite == lastSidePanelLeftUpperSprite) {
            return true;
        }

        final BufferedImage windowFrameLeft = windowFrameLeftSprite != null
            ? windowFrameLeftSprite.toBufferedImage()
            : spriteManager.getSprite(SpriteID.BACKLEFT1, 0);
        final BufferedImage sidePanelLeftUpper = sidePanelLeftUpperSprite != null
            ? sidePanelLeftUpperSprite.toBufferedImage()
            : spriteManager.getSprite(SpriteID.SIDE_BACKGROUND_LEFT1, 0);

        if (windowFrameLeft == null
            || windowFrameLeft.getWidth() < LEFT_BORDER_WIDTH
            || windowFrameLeft.getHeight() <= 0
            || sidePanelLeftUpper == null
            || sidePanelLeftUpper.getWidth() < RIGHT_BORDER_WIDTH
            || sidePanelLeftUpper.getHeight() <= 0) {
            // SpriteManager loads asynchronously; try again next frame.
            return false;
        }

        final int leftSourceY = Math.max(0, windowFrameLeft.getHeight() - BORDER_HEIGHT);
        final BufferedImage leftBorder = flipVertically(cropSprite(windowFrameLeft, leftSourceY, LEFT_BORDER_WIDTH));
        final BufferedImage rightBorder = cropSprite(sidePanelLeftUpper, 0, RIGHT_BORDER_WIDTH);

        client.getSpriteOverrides().put(LEFT_BORDER_SPRITE_ID, ImageUtil.getImageSpritePixels(leftBorder, client));
        client.getSpriteOverrides().put(RIGHT_BORDER_SPRITE_ID, ImageUtil.getImageSpritePixels(rightBorder, client));

        lastWindowFrameLeftSprite = windowFrameLeftSprite;
        lastSidePanelLeftUpperSprite = sidePanelLeftUpperSprite;
        borderSpritesLoaded = true;
        client.getWidgetSpriteCache().reset();
        return true;
    }

    private void clearBorderSprites() {
        client.getSpriteOverrides().remove(LEFT_BORDER_SPRITE_ID);
        client.getSpriteOverrides().remove(RIGHT_BORDER_SPRITE_ID);
        borderSpritesLoaded = false;
        lastWindowFrameLeftSprite = null;
        lastSidePanelLeftUpperSprite = null;
        client.getWidgetSpriteCache().reset();
    }

    private static BufferedImage cropSprite(BufferedImage source, int sourceY, int width) {
        final int sourceHeight = Math.min(BORDER_HEIGHT, source.getHeight() - sourceY);
        final BufferedImage cropped = new BufferedImage(width, BORDER_HEIGHT, BufferedImage.TYPE_INT_ARGB);
        final Graphics2D graphics = cropped.createGraphics();
        graphics.drawImage(source, 0, 0, width, BORDER_HEIGHT, 0, sourceY, width, sourceY + sourceHeight, null);
        graphics.dispose();
        return cropped;
    }

    private static BufferedImage flipVertically(BufferedImage source) {
        final BufferedImage flipped = new BufferedImage(source.getWidth(), source.getHeight(), BufferedImage.TYPE_INT_ARGB);
        final Graphics2D graphics = flipped.createGraphics();
        graphics.drawImage(source, 0, source.getHeight(), source.getWidth(), -source.getHeight(), null);
        graphics.dispose();
        return flipped;
    }

    // endregion

    private static BufferedImage toBufferedImage(Image image) {
        if (image instanceof BufferedImage) {
            return (BufferedImage) image;
        }

        final BufferedImage copy = new BufferedImage(
            image.getWidth(null), image.getHeight(null), BufferedImage.TYPE_INT_ARGB);
        final Graphics2D graphics = copy.createGraphics();
        graphics.drawImage(image, 0, 0, null);
        graphics.dispose();
        return copy;
    }
}

package io.droptracker.service;

import lombok.RequiredArgsConstructor;
import java.util.concurrent.*;

import javax.inject.*;

import io.droptracker.DropTrackerConfig;
import io.droptracker.models.api.Manifest;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.client.eventbus.*;
import net.runelite.client.events.ConfigChanged;

/**
 * Decides <em>when</em> a state snapshot is sent.
 *
 * <p>Three triggers, in increasing urgency:
 * <ul>
 *   <li>a periodic sync, so a player who never does anything notable still has
 *       current state;</li>
 *   <li>login, so a player who played on another client is caught up;</li>
 *   <li>a short-debounced "rapid" sync after something notable (a new collection
 *       log slot), so the website reflects it while the player still cares.</li>
 * </ul>
 *
 * <p>The interval and the debounce both come from the manifest, so sync load is
 * tunable — and switchable off — from the server without a Plugin Hub release.
 *
 * <p>On logout the remaining delay is preserved rather than restarted. Without
 * that, a player who hops worlds every few minutes would restart a 60-minute
 * timer each time and never sync at all.
 */
@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class StateSyncScheduler {

	private final EventBus eventBus;
	private final ScheduledExecutorService executor;
	private final StateSyncService stateSyncService;
	private final ManifestService manifestService;

	private ScheduledFuture<?> pendingSync;

	/** Milliseconds left on the timer when the player logged out; 0 when not paused. */
	private long remainingOnPause;

	/** Guards the future and the pause state, both touched from several threads. */
	private final Object lock = new Object();

	private static final int DEFAULT_INTERVAL_MINUTES = 60;
	private static final int DEFAULT_RAPID_SECONDS = 3;

	public void startUp() {
		eventBus.register(this);
		// Schedule immediately, not just on the next login. The plugin usually
		// starts while the player is already logged in, so waiting for a
		// GameStateChanged means the first sync never happens at all.
		if (stateSyncService.isEnabled()) {
			scheduleRapid("startup");
		}
	}

	public void shutDown() {
		eventBus.unregister(this);
		synchronized (lock) {
			cancel();
			remainingOnPause = 0;
		}
	}

	/**
	 * Reacts to the sync toggle being flipped while the client is running.
	 *
	 * <p>Without this, enabling "Sync account progress" does nothing until the
	 * player next logs in — which reads as the feature being broken, because
	 * nothing happens and there is no error to see.
	 */
	@Subscribe
	public void onConfigChanged(ConfigChanged event) {
		if (!DropTrackerConfig.GROUP.equals(event.getGroup())) {
			return;
		}
		if (stateSyncService.isEnabled()) {
			// The manifest may never have loaded (it is skipped entirely while
			// the API is disabled), and without it no combat achievement varps
			// are read at all.
			manifestService.refresh();
			scheduleRapid("config-changed");
		} else {
			synchronized (lock) {
				cancel();
				remainingOnPause = 0;
			}
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event) {
		if (!stateSyncService.isEnabled()) {
			return;
		}

		if (event.getGameState() == GameState.LOGGED_IN) {
			// A login is the one moment we know the client's view is fresh and
			// possibly stale server-side, so sync promptly rather than waiting
			// out whatever was left on the timer.
			scheduleRapid("login");
			return;
		}

		// Hopping is not really "away" — but treating it the same is harmless,
		// because the resume below restores the remaining time rather than
		// restarting it.
		synchronized (lock) {
			if (pendingSync != null) {
				remainingOnPause = Math.max(0, pendingSync.getDelay(TimeUnit.MILLISECONDS));
				cancel();
				log.debug("Paused state sync with {}ms remaining", remainingOnPause);
			}
		}
	}

	/** Schedules a sync after the short debounce, replacing anything pending. */
	public void scheduleRapid(String source) {
		if (!stateSyncService.isEnabled()) {
			return;
		}
		synchronized (lock) {
			cancel();
			pendingSync = executor.schedule(() -> run(source), rapidSeconds(), TimeUnit.SECONDS);
		}
	}

	/** Schedules the next periodic sync, resuming a paused timer if there is one. */
	public void scheduleNext() {
		if (!stateSyncService.isEnabled()) {
			return;
		}
		synchronized (lock) {
			cancel();
			long delayMs;
			if (remainingOnPause > 0) {
				delayMs = remainingOnPause;
				remainingOnPause = 0;
				log.debug("Resuming state sync in {}ms", delayMs);
			} else {
				delayMs = TimeUnit.MINUTES.toMillis(intervalMinutes());
			}
			pendingSync = executor.schedule(() -> run("interval"), delayMs, TimeUnit.MILLISECONDS);
		}
	}

	/**
	 * Runs one sync and queues the next.
	 *
	 * <p>The next sync is scheduled unconditionally, including after a failure —
	 * otherwise one network blip would end syncing for the rest of the session.
	 */
	private void run(String source) {
		try {
			stateSyncService.sync(source);
		} catch (Exception e) {
			log.debug("State sync ({}) threw: {}", source, e.toString());
		} finally {
			scheduleNext();
		}
	}

	private void cancel() {
		if (pendingSync != null) {
			pendingSync.cancel(false);
			pendingSync = null;
		}
	}

	private int intervalMinutes() {
		Manifest manifest = manifestService.getManifest();
		return manifest == null ? DEFAULT_INTERVAL_MINUTES : manifest.getSync().getIntervalMinutes();
	}

	private int rapidSeconds() {
		Manifest manifest = manifestService.getManifest();
		return manifest == null ? DEFAULT_RAPID_SECONDS : manifest.getSync().getRapidSeconds();
	}
}

package io.droptracker.service;

import lombok.AllArgsConstructor;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicBoolean;

import javax.inject.*;

import io.droptracker.*;
import io.droptracker.api.DropTrackerApi;
import io.droptracker.models.*;
import io.droptracker.models.api.Manifest;
import io.droptracker.util.WorldTypes;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;
import net.runelite.api.gameval.*;
import net.runelite.client.callback.ClientThread;

/**
 * Builds and sends {@link StateSnapshot}s — the account's current state, which
 * the event submissions cannot describe.
 *
 * <p>Also owns the collection log items accumulated by the clog subscribers,
 * because they arrive asynchronously as the player browses and must survive
 * until the next sync sends them.
 */
@Slf4j
@Singleton
@AllArgsConstructor(onConstructor_ = @Inject)
public class StateSyncService {

	private final Client client;
	private final ClientThread clientThread;
	private final DropTrackerConfig config;
	private final DropTrackerApi api;
	private final ManifestService manifestService;
	private final ScheduledExecutorService executor;
	private final DropTrackerPlugin plugin;

	/**
	 * Collection log slots seen so far this session, item id -> quantity.
	 *
	 * <p>Concurrent because the clog subscribers write from the client thread
	 * while a sync may be reading on an executor thread.
	 */
	private final Map<Integer, Integer> clogItems = new ConcurrentHashMap<>();

	/** Set once a full collection log read has completed this session. */
	private final AtomicBoolean clogComplete = new AtomicBoolean(false);

	/** Prevents overlapping syncs; a slow request must not queue up behind itself. */
	private final AtomicBoolean syncing = new AtomicBoolean(false);

	/** True when the user has opted in and the server has not switched sync off. */
	public boolean isEnabled() {
		if (!config.useApi() || !config.syncAccountState()) {
			return false;
		}
		Manifest manifest = manifestService.getManifest();
		return manifest == null || manifest.getSync().isEnabled();
	}

	/**
	 * Records a collection log slot the player has filled.
	 *
	 * <p>The zero check is a guard, not a filter: the game transmits a slot
	 * only once it has been obtained, so nothing legitimate arrives with a
	 * quantity of zero. It stays because "absent means not obtained" is what the
	 * server reads a complete snapshot as, and a zero slipping through would say
	 * the opposite.
	 */
	public void storeItem(int itemId, int quantity) {
		if (quantity <= 0) {
			return;
		}
		clogItems.put(itemId, quantity);
	}

	/** Marks the accumulated items as a complete read of the collection log. */
	public void markClogComplete() {
		clogComplete.set(true);
	}

	/**
	 * Drops everything accumulated so far.
	 *
	 * <p>Called when we might have been reading somebody else's collection log
	 * (the POH adventure log) or when the logged-in account changes — in both
	 * cases keeping the items would attribute them to the wrong player.
	 */
	public void clearItems() {
		clogItems.clear();
		clogComplete.set(false);
	}

	public void reset() {
		clearItems();
		syncing.set(false);
	}

	/**
	 * Collects a snapshot on the client thread.
	 *
	 * <p>Everything here is a client read, so it must not run anywhere else;
	 * the returned future completes on the client thread.
	 */
	public CompletableFuture<StateSnapshot> collect(String source) {
		CompletableFuture<StateSnapshot> future = new CompletableFuture<>();
		clientThread.invokeLater(() -> {
			try {
				future.complete(buildSnapshot(source));
			} catch (Exception e) {
				future.completeExceptionally(e);
			}
		});
		return future;
	}

	/**
	 * Collects and sends a snapshot, unless one is already in flight.
	 *
	 * <p>Failures are logged at debug and otherwise ignored: state sync is a
	 * background enhancement and must never surface an error for something the
	 * player did not ask for.
	 */
	public void sync(String source) {
		if (!isEnabled() || !isPlayerReady()) {
			return;
		}
		// The snapshot carries no world type, and the server files it against
		// the main-game account: a Leagues, Deadman or Hardcore Worlds character
		// would overwrite the main account's skills, quests and collection log.
		if (!WorldTypes.isMainWorld(client.getWorldType())) {
			log.debug("Not syncing state ({}) from a {} world", source,
					WorldTypes.submissionName(client.getWorldType()));
			return;
		}
		if (!syncing.compareAndSet(false, true)) {
			log.debug("State sync already in progress; skipping {}", source);
			return;
		}
		collect(source)
				.thenAcceptAsync(snapshot -> {
					try {
						api.postStateSnapshot(snapshot);
					} finally {
						syncing.set(false);
					}
				}, executor)
				.exceptionally(e -> {
					log.debug("State sync ({}) failed: {}", source, e.toString());
					syncing.set(false);
					return null;
				});
	}

	private boolean isPlayerReady() {
		return client.getGameState() == GameState.LOGGED_IN && client.getLocalPlayer() != null;
	}

	private StateSnapshot buildSnapshot(String source) {
		StateSnapshot snapshot = new StateSnapshot();
		Manifest manifest = manifestService.getManifest();

		Player local = client.getLocalPlayer();
		snapshot.setPlayerName(local != null ? local.getName() : null);
		snapshot.setAccountHash(String.valueOf(client.getAccountHash()));
		snapshot.setSource(source);
		snapshot.setPluginVersion(plugin.pluginVersion);
		snapshot.setManifestVersion(manifest != null ? manifest.getVersion() : null);
		snapshot.setAccountType(client.getVarbitValue(VarbitID.IRONMAN));
		snapshot.setCombatLevel(local != null ? local.getCombatLevel() : null);

		collectSkills(snapshot);
		collectQuests(snapshot, manifest);
		collectCombatAchievements(snapshot, manifest);
		collectDiaries(snapshot);
		collectCollectionLog(snapshot);

		return snapshot;
	}

	private void collectSkills(StateSnapshot snapshot) {
		Map<String, Integer> skills = new HashMap<>();
		for (Skill skill : Skill.values()) {
			skills.put(skill.getName(), client.getSkillExperience(skill));
		}
		snapshot.setSkills(skills);
	}

	/**
	 * Reads the state of every quest the manifest lists.
	 *
	 * <p>Iterating the manifest rather than RuneLite's {@link Quest} enum is the
	 * point: a quest released today is trackable today, instead of after a
	 * RuneLite release and a Plugin Hub build. An empty manifest list falls back
	 * to the enum so this still works before the manifest is populated.
	 */
	private void collectQuests(StateSnapshot snapshot, Manifest manifest) {
		int[] questIds = manifest != null && !manifest.getQuestIds().isEmpty()
				? manifest.getQuestIds().stream().mapToInt(Integer::intValue).toArray()
				: Arrays.stream(Quest.values()).mapToInt(Quest::getId).toArray();

		Map<Integer, Integer> quests = new HashMap<>();
		for (int questId : questIds) {
			try {
				// What Quest#getState does internally: the script leaves the
				// status on the int stack.
				client.runScript(ScriptID.QUEST_STATUS_GET, questId);
				quests.put(questId, questStateFrom(client.getIntStack()[0]));
			} catch (Exception e) {
				log.debug("Could not read quest {}: {}", questId, e.toString());
			}
		}
		snapshot.setQuests(quests);
	}

	/** Maps a QUEST_STATUS_GET result onto 0 not started / 1 in progress / 2 finished. */
	private static int questStateFrom(int status) {
		if (status == 1) {
			return 0;
		}
		if (status == 2) {
			return 2;
		}
		return 1;
	}

	/**
	 * Reads the combat achievement completion bits listed in the manifest.
	 *
	 * <p>Deliberately does nothing without a manifest: the varps are not a
	 * contiguous range, so there is no safe range to guess at, and sending a
	 * partial set would look like the player had un-completed tasks.
	 *
	 * <p>Raw varps only, no per-task breakdown. The server holds the task
	 * registry and decodes these bits into named, tiered, per-monster tasks when
	 * a profile is read, which means a registry correction applies retroactively
	 * to everything already stored — a decode done here could only ever be
	 * staler than that, and would still miss the tasks the registry has no entry
	 * for that the varps cover anyway.
	 */
	private void collectCombatAchievements(StateSnapshot snapshot, Manifest manifest) {
		if (manifest == null) {
			return;
		}
		Map<Integer, Integer> varps = new HashMap<>();
		for (int varpId : manifest.getCombatAchievementVarps()) {
			varps.put(varpId, client.getVarpValue(varpId));
		}
		snapshot.setCombatAchievementVarps(varps);
	}

	private void collectDiaries(StateSnapshot snapshot) {
		List<StateSnapshot.DiaryTier> tiers = new java.util.ArrayList<>();
		for (AchievementDiaryArea area : AchievementDiaryArea.values()) {
			int[] completed = area.getTiersCompletedCount(client);
			for (int tier = 0; tier < completed.length; tier++) {
				tiers.add(new StateSnapshot.DiaryTier(area.getId(), tier, completed[tier]));
			}
		}
		snapshot.setDiaryTiers(tiers);
	}

	private void collectCollectionLog(StateSnapshot snapshot) {
		snapshot.setItems(new HashMap<>(clogItems));
		snapshot.setClogComplete(clogComplete.get());

		// The game's own counters are correct even when we have read no items
		// at all, so a profile can show real progress before any scrape.
		int completed = client.getVarpValue(VarPlayerID.COLLECTION_COUNT);
		int total = client.getVarpValue(VarPlayerID.COLLECTION_COUNT_MAX);
		if (total > 0 && completed >= 0) {
			snapshot.setClogSlots(completed);
			snapshot.setClogSlotsTotal(total);
		}
	}
}

package io.droptracker.service;

import com.google.gson.Gson;
import com.google.gson.annotations.SerializedName;
import com.google.gson.reflect.TypeToken;
import io.droptracker.DropTrackerConfig;
import io.droptracker.api.*;
import io.droptracker.models.*;
import io.droptracker.models.api.GroupConfig;
import io.droptracker.models.submissions.*;
import io.droptracker.util.*;
import lombok.*;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;
import net.runelite.client.RuneLite;
import net.runelite.client.util.Text;
import okhttp3.*;
import org.jetbrains.annotations.*;

import javax.imageio.ImageIO;
import javax.inject.*;
import java.awt.image.BufferedImage;
import java.io.*;
import java.lang.reflect.Type;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.function.Predicate;

@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class SubmissionManager {

    private final DropTrackerConfig config;
    private final DropTrackerApi api;
    private final ChatMessageUtil chatMessageUtil;
    private final Gson gson;
    private final OkHttpClient okHttpClient;
    private final Client client;
    private final UrlManager urlManager;
    private final ScreenshotPrivacyService screenshotPrivacy;
    private final NearbyPlayerTracker nearbyPlayerTracker;

    /** Thread-safe list of submissions the player has received which qualified for notifications */
    @Getter
    private final List<ValidSubmission> validSubmissions = new CopyOnWriteArrayList<>();

    /** Screenshot captures held back a game tick; drained by {@link #onGameTick()}. */
    private final Queue<Runnable> deferredCaptures = new ConcurrentLinkedQueue<>();

    /** Guards the one-frame encode memo below; see {@link #encodeForUpload(BufferedImage)}. */
    private final Object encodeLock = new Object();
    private BufferedImage lastEncodedImage;
    private byte[] lastEncodedBytes;

    /** Callback for UI updates when submissions change */
    @Setter
    private SubmissionUpdateCallback updateCallback;
    @Setter
    private boolean updatesEnabled = true;
    @Inject
    private ScheduledExecutorService executor;

    /** Total GP value of drops submitted this session */
    @Getter
    private long sessionTotalValue = 0L;

    /** Debounced save handle */
    private ScheduledFuture<?> pendingSave;
    private final AtomicBoolean saveScheduled = new AtomicBoolean(false);

    /** Directory for persisting submissions */
    private static final String PERSISTENCE_DIR = "droptracker";
    private static final String PERSISTENCE_FILE_PREFIX = "submissions_";
    private static final int MAX_PERSISTED_SUBMISSIONS = 50;

    /** Pending webhooks that arrived before group configs were loaded */
    private final List<PendingEvent> pendingEvents = new CopyOnWriteArrayList<>();
    private volatile boolean groupConfigsLoaded = false;

    private static final long BASE_RETRY_DELAY_MS = 1000L;

    // ========== Public Entry Points for Event Handlers ==========

    /**
     * Entry point for non-drop events (PBs, CLogs, CAs, Pets, Quests, Levels, XP, etc.)
     */
    public void sendDataToDropTracker(CustomWebhookBody webhook, SubmissionType type) {
        if (hasUnidentifiedEmbed(webhook)) {
            debugLogEventFlow("skipped", type, "no player_name");
            return;
        }
        boolean requiredScreenshot = false;
        PrivacyMode privacyMode = config.privacyMode();
        debugLogEventFlow("received", type, "useApi=" + config.useApi() + ", privacy=" + privacyMode);

        // Check if the user has this event type enabled locally
        Predicate<DropTrackerConfig> embedsOn = EMBED_TOGGLES.get(type);
        if (embedsOn != null && !embedsOn.test(config)) {
            debugLogEventFlow("skipped", type, "embeds off");
            return;
        }
        switch (type) {
            case DROP:
                // Drops use the value-based overload; this should not be called for drops
                debugLogEventFlow("skipped", type, "wrong entrypoint");
                break;
            case KILL_TIME:
                // Raid completion times are raid data: attach the
                // authoritative raid roster. Non-raid kill times are left
                // untouched.
                if (NearbyPlayerTracker.raidTypeForSource(extractSourceName(webhook)) != null) {
                    addParticipantsField(webhook);
                }
                boolean isPb = isFieldTrue(webhook, "is_pb");
                if (config.screenshots() && isPb) {
                    requiredScreenshot = true;
                }
                if (!isPb) {
                    // Non-PB kill times: just send, no ValidSubmission tracking
                    debugLogEventFlow("send", type, "non-pb; screenshot=" + requiredScreenshot);
                    if (requiredScreenshot) {
                        captureAndSend(webhook, null, privacyMode);
                    } else {
                        sendWebhookDirect(webhook, null, null);
                    }
                    return;
                }
                break;
            case LEVEL_UP:
                // Honor the "Minimum Level to Screenshot" option: only capture
                // when at least one skill reached that level (default 1 = always).
                if (config.screenshots()
                        && maxNewLevelIn(webhook) >= config.minLevelToScreenshot()) {
                    requiredScreenshot = true;
                }
                break;
            case EXPERIENCE:
            case ADVENTURE_LOG:
                // No screenshot, no extra processing
                break;
            case EXPERIENCE_UPDATE:
                // Background XP snapshot for event tracking
            case CLAN_BROADCAST:
            case CLAN_CHAT:
                // Clan relay payloads ride whichever transport the player
                // uses (API or our Discord webhooks; the webhook bot reads
                // them server-side). ClanRelayService only queues lines from
                // an opted-in clan.
            case CONFIG_SNAPSHOT:
                // Debug record of the player's settings (ConfigSnapshotHandler).
                // None of these take a screenshot, group qualification or a
                // side-panel entry: the server owns everything downstream.
                debugLogEventFlow("send", type, "direct");
                sendWebhookDirect(webhook, null, null);
                return;
            default:
                // Collection log, combat achievements, quests, pets, deaths,
                // diaries, slayer tasks and XP milestones.
                requiredScreenshot = config.screenshots();
                break;
        }

        // Create ValidSubmission if the event qualifies for any group
        ValidSubmission submission = createSubmissionIfQualified(webhook, type, requiredScreenshot, 0, 0);
        debugLogEventFlow("qualification", type, "screenshot=" + requiredScreenshot);

        if (requiredScreenshot) {
            captureAndSend(webhook, submission, privacyMode);
        } else {
            sendWebhookDirect(webhook, null, submission);
        }
    }

    /**
     * Highest {@code *_new_level} field value across the webhook's embeds.
     * Level-up embeds carry one such field per levelled skill; used to honor
     * the "Minimum Level to Screenshot" config option. Returns 0 when no
     * level fields are present.
     */
    /** The per-type embed switches in the plugin config. */
    private static final Map<SubmissionType, Predicate<DropTrackerConfig>> EMBED_TOGGLES = Map.of(
        SubmissionType.KILL_TIME, DropTrackerConfig::pbEmbeds,
        SubmissionType.COLLECTION_LOG, DropTrackerConfig::clogEmbeds,
        SubmissionType.COMBAT_ACHIEVEMENT, DropTrackerConfig::caEmbeds,
        SubmissionType.LEVEL_UP, DropTrackerConfig::levelEmbed,
        SubmissionType.QUEST_COMPLETION, DropTrackerConfig::questsEmbed,
        SubmissionType.PET, DropTrackerConfig::petEmbeds,
        SubmissionType.DEATH, DropTrackerConfig::deathEmbeds,
        SubmissionType.DIARY, DropTrackerConfig::diaryEmbeds,
        SubmissionType.SLAYER_TASK, DropTrackerConfig::slayerEmbeds,
        SubmissionType.EXPERIENCE_MILESTONE, DropTrackerConfig::xpMilestoneEmbeds);

    private int maxNewLevelIn(CustomWebhookBody webhook) {
        int max = 0;
        if (webhook == null || webhook.getEmbeds() == null) {
            return max;
        }
        for (CustomWebhookBody.Embed embed : webhook.getEmbeds()) {
            for (CustomWebhookBody.Field field : embed.getFields()) {
                if (field.getName() != null && field.getName().endsWith("_new_level")) {
                    try {
                        max = Math.max(max, Integer.parseInt(field.getValue().trim()));
                    } catch (NumberFormatException ignored) {
                        // non-numeric level field; skip
                    }
                }
            }
        }
        return max;
    }

    /**
     * Entry point for drop events (value-based qualification)
     */
    public void sendDataToDropTracker(CustomWebhookBody customWebhookBody, long totalValue, long singleValue, boolean valueModified) {
        if (hasUnidentifiedEmbed(customWebhookBody)) {
            debugLogEventFlow("skipped", SubmissionType.DROP, "no player_name");
            return;
        }
        if (!config.lootEmbeds()) {
            debugLogEventFlow("skipped", SubmissionType.DROP, "embeds off");
            return;
        }

        addParticipantsField(customWebhookBody);

        boolean requiredScreenshot = (config.screenshots() && totalValue > config.screenshotValue()) || valueModified;
        debugLogEventFlow("received", SubmissionType.DROP, "total=" + totalValue + ", single=" + singleValue
                + ", modified=" + valueModified + ", screenshot=" + requiredScreenshot
                + ", threshold=" + config.screenshotValue() + ", privacy=" + config.privacyMode());

        // Create ValidSubmission if the drop qualifies for any group
        ValidSubmission submission = createSubmissionIfQualified(customWebhookBody, SubmissionType.DROP, requiredScreenshot, totalValue, singleValue);

        // Update session value statistics
        this.sessionTotalValue += totalValue;
        if (submission != null) {
            submission.setTotalValue(totalValue);
        }

        if (requiredScreenshot) {
            captureAndSend(customWebhookBody, submission, config.privacyMode());
        } else {
            sendWebhookDirect(customWebhookBody, null, submission);
        }
    }

    /**
     * The submission's source name from its embed fields: {@code source} on
     * drop embeds, {@code boss_name} on kill-time embeds. Null when absent.
     */
    private String extractSourceName(CustomWebhookBody webhook) {
        if (webhook == null || webhook.getEmbeds() == null) {
            return null;
        }
        for (CustomWebhookBody.Embed embed : webhook.getEmbeds()) {
            if (embed == null) {
                continue;
            }
            for (CustomWebhookBody.Field field : embed.getFields()) {
                if (field == null || field.getName() == null) {
                    continue;
                }
                if ("source".equalsIgnoreCase(field.getName()) || "boss_name".equalsIgnoreCase(field.getName())) {
                    return field.getValue();
                }
            }
        }
        return null;
    }

    /**
     * Last line of defence for the identity fix: a submission whose
     * {@code player_name} is present but blank cannot be attributed to anyone,
     * and the backend rejects it anyway. Handlers already skip these at the
     * source; this stops a future path from reintroducing a nameless — or
     * worse, invented — submission by accident. Embeds that carry no
     * {@code player_name} at all (the adventure log names its field
     * {@code player}) are left alone.
     */
    @VisibleForTesting
    static boolean hasUnidentifiedEmbed(CustomWebhookBody webhook) {
        if (webhook == null || webhook.getEmbeds() == null) {
            return false;
        }
        for (CustomWebhookBody.Embed embed : webhook.getEmbeds()) {
            if (embed == null || embed.getFields() == null) {
                continue;
            }
            for (CustomWebhookBody.Field field : embed.getFields()) {
                if (field == null || !"player_name".equalsIgnoreCase(field.getName())) {
                    continue;
                }
                if (PlayerIdentity.isMissingName(field.getValue())) {
                    return true;
                }
            }
        }
        return false;
    }

    private void addParticipantsField(CustomWebhookBody webhook) {
        if (webhook == null || webhook.getEmbeds() == null) {
            return;
        }

        // Raid-sourced submissions get the authoritative raid roster; anything
        // else gets a plain proximity scan (see NearbyPlayerTracker).
        String sourceName = extractSourceName(webhook);
        boolean raidSourced = NearbyPlayerTracker.raidTypeForSource(sourceName) != null;
        NearbyPlayerTracker.NearbyPlayerTrace trace = nearbyPlayerTracker.getParticipantsTrace(sourceName, 20);
        List<String> members = trace.getNearbyPlayers();
        String membersValue = String.join(",", members);
        int added = 0;

        for (CustomWebhookBody.Embed embed : webhook.getEmbeds()) {
            if (embed == null) {
                continue;
            }

            boolean hasMembersField = false;
            boolean hasPartySizeField = false;
            for (CustomWebhookBody.Field field : embed.getFields()) {
                if (field == null || field.getName() == null) {
                    continue;
                }
                if ("nearby_players".equalsIgnoreCase(field.getName())
                        || "members".equalsIgnoreCase(field.getName())) {
                    hasMembersField = true;
                }
                if ("raid_party_size".equalsIgnoreCase(field.getName())) {
                    hasPartySizeField = true;
                }
            }

            // Discord rejects embed fields with empty values, so omit the field
            // entirely when no players are nearby rather than sending a sentinel.
            if (!hasMembersField && !membersValue.isEmpty()) {
                embed.addField("nearby_players", membersValue, false);
                added++;
            }

            // Raid submissions carry the evidence behind the participant list,
            // not just the list: the party size the game itself reported and
            // which source produced the roster. The server cross-checks the
            // list against these, so a roster bug (or a stale client) can no
            // longer credit people who were never in the raid — a proven solo
            // (raid_party_size=1, roster_source=solo) is never split.
            if (raidSourced && !hasPartySizeField) {
                if (trace.getRaidPartySize() > 0) {
                    embed.addField("raid_party_size", String.valueOf(trace.getRaidPartySize()), false);
                }
                if (trace.getRosterSource() != null && !trace.getRosterSource().isEmpty()) {
                    embed.addField("roster_source", trace.getRosterSource(), false);
                }
            }
        }

        debugLogEventFlow("nearby-trace", null, "nearby_players added to " + added + " embeds, raid=" + raidSourced);
    }

    // ========== Unified Qualification Logic ==========

    /**
     * Checks all group configurations to determine if this event qualifies for tracked notifications.
     * Creates a single ValidSubmission covering all qualifying groups, or returns null if none qualify.
     */
    private ValidSubmission createSubmissionIfQualified(
            CustomWebhookBody webhook, SubmissionType type,
            boolean hasScreenshot, long totalValue, long singleValue) {

        if (!config.useApi()) {
            debugLogEventFlow("qualification", type, "useApi=false");
            return null;
        }

        // Keep configs warm; the refresh is rate-limited and fully async (previously this
        // happened as a hidden side effect of getGroupConfigs()).
        api.refreshGroupConfigsAsync();
        List<GroupConfig> groupConfigs = api.getGroupConfigs();

        // If group configs haven't loaded yet, queue the event for later evaluation
        if (groupConfigs == null || groupConfigs.isEmpty()) {
            if (!groupConfigsLoaded) {
                pendingEvents.add(new PendingEvent(webhook, type, hasScreenshot, totalValue, singleValue));
            }
            debugLogEventFlow("qualification", type, "no group configs; queued=" + !groupConfigsLoaded);
            return null;
        }

        ValidSubmission submission = null;

        for (GroupConfig groupConfig : groupConfigs) {
            String failReason = getQualificationFailureReason(type, groupConfig, hasScreenshot, totalValue, singleValue);
            if (failReason != null) {
                debugLogEventFlow("qualification", type, "skip group=" + groupConfig.getGroupId() + ": " + failReason);
                continue;
            }

            if (submission == null) {
                submission = new ValidSubmission(webhook, groupConfig.getGroupId(), type);
                addSubmissionToMemory(submission);
            } else {
                submission.addGroupId(groupConfig.getGroupId());
            }
        }
        debugLogEventFlow("qualification", type, summarizeSubmission(submission));
        return submission;
    }

    /**
     * Returns null when the event qualifies, otherwise a concise reason it was excluded.
     */
    private String getQualificationFailureReason(SubmissionType type, GroupConfig groupConfig,
                                                 boolean hasScreenshot, long totalValue, long singleValue) {
        // If the group requires screenshots and we don't have one, skip
        if (groupConfig.isOnlyScreenshots() && !hasScreenshot) {
            return "group requires screenshot";
        }

        switch (type) {
            case DROP:
                if (!groupConfig.isSendDrops()) return "group sendDrops=false";
                if (totalValue < groupConfig.getMinimumDropValue()) {
                    return "totalValue(" + totalValue + ") < groupMin(" + groupConfig.getMinimumDropValue() + ")";
                }
                // Check stacked items: if group doesn't allow stacked and total > single, skip
                if (!groupConfig.isSendStackedItems() && totalValue > singleValue && singleValue > 0) {
                    return "stacked item and group sendStackedItems=false";
                }
                return null;

            case KILL_TIME:
                return groupConfig.isSendPbs() ? null : "group sendPbs=false";

            case COLLECTION_LOG:
                return groupConfig.isSendClogs() ? null : "group sendClogs=false";

            case COMBAT_ACHIEVEMENT:
                return groupConfig.isSendCAs() ? null : "group sendCAs=false";

            case LEVEL_UP:
                return groupConfig.isSendXP() ? null : "group sendXP=false";

            case QUEST_COMPLETION:
                return groupConfig.isSendQuests() ? null : "group sendQuests=false";

            case PET:
                return groupConfig.isSendPets() ? null : "group sendPets=false";

            case DEATH:
                return groupConfig.isSendDeaths() ? null : "group sendDeaths=false";

            case DIARY:
                return groupConfig.isSendDiaries() ? null : "group sendDiaries=false";

            case SLAYER_TASK:
                // Sent regardless; groups have no slayer notifications yet, so
                // the only group a completion means anything to is one whose
                // live event may count it.
                return groupConfig.isActiveEvent() ? null : "no active event in group";

            case EXPERIENCE:
            case EXPERIENCE_MILESTONE:
                // XP events typically don't create group notifications,
                // but respect the group config if present
                return groupConfig.isSendXP() ? null : "group sendXP=false";

            case EXPERIENCE_UPDATE:
                // Snapshot syncs are sent directly and never tracked per-group
                return "experience snapshots are not tracked per-group";

            case ADVENTURE_LOG:
                // Adventure log currently has no group-level toggle
                return "adventure log unsupported for group notifications";

            default:
                return "unsupported submission type";
        }
    }

    // ========== Send Logic ==========

    /**
     * Sends a webhook directly (with optional screenshot and ValidSubmission tracking).
     * This is the single send method -- the ValidSubmission is passed through, not looked up.
     *
     * @param webhook The webhook body to send
     * @param screenshot Optional JPEG screenshot bytes
     * @param submission Optional ValidSubmission for status tracking
     */
    private void sendWebhookDirect(CustomWebhookBody webhook, byte[] screenshot, ValidSubmission submission) {
        String worldTypeName = getWorldTypeName();

        debugLogFlow("send", submission, "world=" + worldTypeName + ", image=" + (screenshot != null)
                + ", " + summarizeSubmission(submission));

        if (submission != null) {
            submission.markAsSending();
            if (screenshot != null) {
                submission.setScreenshotData(screenshot);
            }
            submissionsChanged();
        }

        // Inject world_type into every embed so the server can distinguish main-game vs. temporary world submissions
        for (CustomWebhookBody.Embed embed : webhook.getEmbeds()) {
            embed.addField("world_type", worldTypeName, true);
        }

        sendWebhookWithRetry(webhook, screenshot, 0, submission);
    }

    private void sendWebhookWithRetry(CustomWebhookBody webhook, byte[] screenshot, int attempt, ValidSubmission submission) {

        MultipartBody.Builder requestBodyBuilder = new MultipartBody.Builder()
                .setType(MultipartBody.FORM)
                .addFormDataPart("payload_json", gson.toJson(webhook));

        if (screenshot != null) {
            String mimeType = detectImageMimeType(screenshot);
            String filename = mimeType.equals("image/png") ? "image.png" : "image.jpeg";
            requestBodyBuilder.addFormDataPart("file", filename,
                    RequestBody.create(MediaType.parse(mimeType), screenshot));
        }

        MultipartBody requestBody = requestBodyBuilder.build();

        HttpUrl url;
        if (!config.useApi()) {
            try {
                url = UrlManager.getRandomEndpoint();
                debugLogFlow("dispatch", submission, "webhook, attempt=" + attempt);
            } catch (Exception e) {
                debugLogFlow("failed", submission, "no webhook endpoint: " + e.getMessage());
                return;
            }
        } else {
            url = HttpUrl.parse(api.getApiUrl() + "/webhook");
            debugLogFlow("dispatch", submission, "api, attempt=" + attempt + ", url=" + url);
        }
        // Both branches build on a hardcoded base, so this is defence in depth rather
        // than a real gate. Log only the host: a webhook URL's path is a credential.
        if (url == null || !urlManager.isValidDiscordWebhookUrl(url)) {
            String host = url == null ? "(unparseable)" : url.host();
            debugLogFlow("failed", submission, "invalid host: " + host);
            return;
        }

        Request request = new Request.Builder()
                .url(url)
                .post(requestBody)
                .build();

        okHttpClient.newCall(request).enqueue(new Callback() {
            @Override
            public void onFailure(@NotNull Call call, @NotNull IOException e) {
                debugLogFlow("retry", submission, "attempt=" + attempt + ": " + e.getMessage());
                scheduleRetryOrFail(webhook, screenshot, submission, attempt, e);
            }

            @Override
            public void onResponse(@NotNull Call call, @NotNull Response response) throws IOException {
                try (ResponseBody body = response.body()) {
                    if (config.useApi()) {
                        api.lastCommunicationTime = (int) (System.currentTimeMillis() / 1000);
                        if (body != null) {
                            try {
                                String bodyString = body.string();
                                if (!bodyString.isEmpty()) {
                                    ApiResponse apiResponse = gson.fromJson(bodyString, ApiResponse.class);
                                    if (apiResponse != null) {
                                        String noticeMessage = apiResponse.getNotice();
                                        if (noticeMessage != null && !noticeMessage.isEmpty() && config.receiveInGameMessages()) {
                                            chatMessageUtil.sendChatMessage(noticeMessage);
                                        }
                                        String updateMessage = apiResponse.getRankUpdate();
                                        if (updateMessage != null && !updateMessage.isEmpty() && config.receiveInGameMessages()) {
                                            chatMessageUtil.sendChatMessage(updateMessage);
                                        }
                                    }
                                }
                            } catch (Exception e) {
                                log.debug("Failed to parse API response: {}", e.getMessage());
                            }
                        }
                    }

                    if (!response.isSuccessful()) {
                        int code = response.code();
                        debugLogFlow("response", submission, "HTTP " + code + " " + response.message() + ", attempt=" + attempt);

                        if (code == 400 || code == 401 || code == 403) {
                            if (submission != null) {
                                submission.markAsFailed("HTTP " + code);
                                submissionsChanged();
                            }
                            return;
                        }

                        if (code == 404) {
                            executor.submit(() -> {
                                try {
                                    urlManager.fetchNewList();
                                } catch (Exception ex) {
                                    log.debug("Failed to fetch new webhook list: {}", ex.getMessage());
                                }
                            });
                        }

                        scheduleRetryOrFail(webhook, screenshot, submission, attempt, new IOException("HTTP " + code + ": " + response.message()));
                        return;
                    }

                    // Success
                    if (submission != null) {
                        submission.markAsSuccess();
                        submissionsChanged();
                    }
                    debugLogFlow("response", submission, "ok, attempt=" + attempt + ", " + summarizeSubmission(submission));

                    // Check if the API has already processed this submission
                    if (config.useApi() && submission != null && submission.getUuid() != null && !submission.getUuid().isEmpty()) {
                        executor.submit(() -> {
                            try {
                                boolean processed = api.checkSubmissionProcessed(submission.getUuid());
                                if (processed) {
                                    submission.markAsProcessed();
                                    submissionsChanged();
                                    debugLogFlow("processed", submission, submission.getUuid());
                                }
                            } catch (IOException e) {
                                debugLogFlow("processed", submission, "check failed: " + e.getMessage());
                            }
                        });
                    }
                }
            }
        });
    }

    private void scheduleRetryOrFail(CustomWebhookBody webhook, byte[] screenshot, ValidSubmission submission, int attempt, Throwable e) {
        int maxAttempts = 10;
        if (attempt < maxAttempts) {
            long delay = BASE_RETRY_DELAY_MS * (1L << Math.min(attempt, 16));
            if (submission != null) {
                submission.markAsRetrying();
                submissionsChanged();
            }
            executor.schedule(() -> sendWebhookWithRetry(webhook, screenshot, attempt + 1, submission), delay, TimeUnit.MILLISECONDS);
            debugLogFlow("retry", submission, "in " + delay + "ms, attempt " + (attempt + 1) + "/" + maxAttempts
                + (e != null ? ": " + e.getMessage() : ""));
        } else {
            if (submission != null) {
                String reason = e != null && e.getMessage() != null ? e.getMessage() : "Retry limit reached";
                submission.markAsFailed(reason);
                submissionsChanged();
            }
            log.warn("Exhausted retry attempts when sending webhook");
            debugLogFlow("failed", submission, "gave up: " + (e != null ? e.getMessage() : null));
        }
    }

    // ========== Capture (Screenshot) ==========

    /**
     * Runs any screenshot captures held back a game tick. Called from the
     * plugin's {@code onGameTick} ahead of its tracking check: a capture is
     * only ever queued for a submission that already qualified, so draining
     * unconditionally keeps a mid-flight tracking toggle from stranding it
     * here and firing a stale frame whenever tracking resumes.
     */
    public void onGameTick() {
        Runnable capture;
        while ((capture = deferredCaptures.poll()) != null) {
            try {
                capture.run();
            } catch (Exception e) {
                log.debug("Deferred screenshot capture failed", e);
            }
        }
    }

    private void captureAndSend(CustomWebhookBody webhook, ValidSubmission submission, PrivacyMode privacyMode) {
        // Sources that announce loot a tick late would otherwise be
        // photographed before their own drop message (issue #48).
        String source = extractSourceName(webhook);
        if (NpcUtilities.needsDeferredScreenshot(source)) {
            debugLogFlow("capture", submission, "deferred a tick: " + source);
            deferredCaptures.add(() -> captureNow(webhook, submission, privacyMode));
            return;
        }
        captureNow(webhook, submission, privacyMode);
    }

    /**
     * Captures a single screenshot and sends the webhook with it.
     *
     * @param webhook The webhook body to send after capture
     * @param submission Optional ValidSubmission for tracking
     * @param privacyMode What to hide from the frame before it is captured
     */
    private void captureNow(CustomWebhookBody webhook, ValidSubmission submission, PrivacyMode privacyMode) {

        screenshotPrivacy.capture(privacyMode, bufferedImage -> {
            // PNG/JPEG encoding can take hundreds of ms for large frames; keep it
            // off the frame-listener thread so the client doesn't stall.
            executor.submit(() -> {
                if (bufferedImage == null) {
                    // No frame could be captured with the player's privacy mode
                    // applied. Send the submission without proof rather than lose
                    // it — an unhidden frame is never the fallback.
                    debugLogFlow("capture", submission, "no frame; sending without");
                    sendWebhookDirect(webhook, null, submission);
                    return;
                }

                byte[] imageBytes = null;
                try {
                    imageBytes = encodeForUpload(bufferedImage);
                } catch (IOException e) {
                    log.error("Error converting image to byte array", e);
                }
                debugLogFlow("capture", submission, "bytes=" + (imageBytes != null ? imageBytes.length : 0));
                sendWebhookDirect(webhook, imageBytes, submission);
            });
        });
    }

    /**
     * Encodes a captured frame for upload, remembering the last one.
     *
     * <p>ScreenshotPrivacyService hands the same frame to every submission that a
     * single moment produced — a drop and the collection log slot it filled share
     * one capture — so without this the identical image is compressed once per
     * submission. Encoding is the expensive half of a screenshot, so the second
     * caller waits on the lock and leaves with the bytes the first one produced.
     */
    private byte[] encodeForUpload(BufferedImage bufferedImage) throws IOException {
        synchronized (encodeLock) {
            if (bufferedImage == lastEncodedImage && lastEncodedBytes != null) {
                return lastEncodedBytes;
            }

            // Compression off = always lossless, whatever the size.
            int thresholdBytes = config.compressImages()
                ? config.imageCompressionThresholdKb() * 1024
                : Integer.MAX_VALUE;
            byte[] pngBytes = encodeImage(bufferedImage, "png");
            byte[] imageBytes = thresholdBytes > 0 && pngBytes.length <= thresholdBytes
                // PNG is within the threshold — send lossless
                ? pngBytes
                // PNG exceeds threshold (or threshold is 0) — compress to JPEG
                : encodeImage(bufferedImage, "jpeg");

            lastEncodedImage = bufferedImage;
            lastEncodedBytes = imageBytes;
            return imageBytes;
        }
    }

    private static byte[] encodeImage(BufferedImage bufferedImage, String format) throws IOException {
        ByteArrayOutputStream byteArrayOutputStream = new ByteArrayOutputStream();
        ImageIO.write(bufferedImage, format, byteArrayOutputStream);
        return byteArrayOutputStream.toByteArray();
    }

    /**
     * Detects image MIME type from magic bytes.
     * PNG files begin with 0x89 P N G; all others are treated as JPEG.
     */
    private static String detectImageMimeType(byte[] bytes) {
        if (bytes != null && bytes.length >= 4
                && bytes[0] == (byte) 0x89 && bytes[1] == 0x50
                && bytes[2] == 0x4E && bytes[3] == 0x47) {
            return "image/png";
        }
        return "image/jpeg";
    }

    // ========== Submission Management ==========

    public void addSubmissionToMemory(ValidSubmission validSubmission) {
        // Prune oldest processed submissions to stay within limits
        while (validSubmissions.size() >= MAX_PERSISTED_SUBMISSIONS) {
            // Prefer removing oldest processed submission first
            ValidSubmission toRemove = null;
            for (ValidSubmission s : validSubmissions) {
                if (s.getStatus() == SubmissionStatus.PROCESSED) {
                    toRemove = s;
                    break;
                }
            }
            if (toRemove != null) {
                validSubmissions.remove(toRemove);
            } else {
                // Remove the oldest submission regardless
                validSubmissions.remove(0);
            }
        }
        validSubmissions.add(validSubmission);
        submissionsChanged();
    }

    /**
     * Retry a failed submission using the stored webhook data
     */
    public void retrySubmission(ValidSubmission validSubmission) {
        if (validSubmission == null || validSubmission.getOriginalWebhook() == null) {
            log.warn("Cannot retry submission: missing webhook data");
            return;
        }
        validSubmission.markAsRetrying();
        submissionsChanged();
        // Use stored screenshot data if available
        byte[] screenshot = validSubmission.getScreenshotData();
        sendWebhookWithRetry(validSubmission.getOriginalWebhook(), screenshot, 0, validSubmission);
    }

    /**
     * Remove a submission from the list (e.g., when user dismisses it)
     */
    public void removeSubmission(ValidSubmission validSubmission) {
        validSubmissions.remove(validSubmission);
        submissionsChanged();
    }

    // ========== Statistics (derived from list) ==========

    /**
     * Count of all submissions that qualified for group notifications this session
     */
    public int getTotalSubmissions() {
        return validSubmissions.size();
    }

    /**
     * Count of submissions that were successfully sent or processed
     */
    public int getNotificationsSent() {
        int count = 0;
        for (ValidSubmission s : validSubmissions) {
            if (s.getStatus() == SubmissionStatus.SENT || s.getStatus() == SubmissionStatus.PROCESSED) {
                count++;
            }
        }
        return count;
    }

    /**
     * Count of submissions that failed
     */
    public int getFailedSubmissions() {
        int count = 0;
        for (ValidSubmission s : validSubmissions) {
            if (s.getStatus() == SubmissionStatus.FAILED) {
                count++;
            }
        }
        return count;
    }

    /**
     * Total GP value of drops submitted (session-only, not derived from list because
     * non-qualifying drops also contribute to GP value)
     */
    public long getTotalValue() {
        return sessionTotalValue;
    }

    // ========== Pending Status Polling ==========

    /**
     * Poll the API to update statuses of pending submissions. All pending uuids are
     * checked with a single batch POST /check per tick; if the batch form is
     * unavailable (older custom API endpoints), it falls back to per-uuid checks for
     * that tick. A "pending" result is a normal long-lived state - submissions stay
     * pending until the API processes them or the retry logic marks them failed.
     */
    public void checkPendingStatuses() {
        if (!config.useApi()) {
            return;
        }
        executor.submit(() -> {
            try {
                List<ValidSubmission> pending = new ArrayList<>();
                List<String> uuids = new ArrayList<>();
                for (ValidSubmission submission : validSubmissions) {
                    SubmissionStatus status = submission.getStatus();
                    if (status == null || status.isTerminal()) {
                        continue;
                    }
                    String uuid = submission.getUuid();
                    if (uuid == null || uuid.isEmpty()) {
                        continue;
                    }
                    pending.add(submission);
                    uuids.add(uuid);
                }
                if (pending.isEmpty()) {
                    return;
                }

                boolean changed = false;
                java.util.Map<String, Boolean> results = api.checkSubmissionsProcessed(uuids);
                for (ValidSubmission submission : pending) {
                    if (Boolean.TRUE.equals(results.get(submission.getUuid()))) {
                        submission.markAsProcessed();
                        changed = true;
                    }
                }

                if (changed) {
                    submissionsChanged();
                }
            } catch (Exception e) {
                log.debug("Error while checking pending statuses: {}", e.getMessage());
            }
        });
    }

    /**
     * Check if there are any submissions in active (non-terminal) states
     */
    public boolean hasActiveSubmissions() {
        for (ValidSubmission submission : validSubmissions) {
            SubmissionStatus status = submission.getStatus();
            if (status != null && status.isActive()) {
                return true;
            }
        }
        return false;
    }

    // ========== Group Config Loading Notification ==========

    /**
     * Called when group configs have been loaded. Re-evaluates any events that were
     * queued while configs were unavailable.
     */
    public void onGroupConfigsLoaded() {
        this.groupConfigsLoaded = true;
        if (pendingEvents.isEmpty()) {
            return;
        }

        debugLogEventFlow("qualification", null, "configs loaded; replaying " + pendingEvents.size());
        List<PendingEvent> toProcess = new ArrayList<>(pendingEvents);
        pendingEvents.clear();

        for (PendingEvent event : toProcess) {
            // Re-run qualification now that configs are available
            createSubmissionIfQualified(event.webhook, event.type, event.hasScreenshot, event.totalValue, event.singleValue);
        }

        if (!validSubmissions.isEmpty()) {
            submissionsChanged();
        }
    }

    // ========== Persistence ==========

    /**
     * Load persisted submissions from disk for the given account hash.
     */
    public void loadSubmissions(String accountHash) {
        if (accountHash == null || accountHash.isEmpty() || "-1".equals(accountHash)) {
            return;
        }

        Path filePath = getSubmissionFilePath(accountHash);
        if (!Files.exists(filePath)) {
            return;
        }

        executor.submit(() -> {
            try {
                String json = new String(Files.readAllBytes(filePath), StandardCharsets.UTF_8);
                Type listType = new TypeToken<List<ValidSubmission>>() {}.getType();
                List<ValidSubmission> loaded = gson.fromJson(json, listType);
                if (loaded != null && !loaded.isEmpty()) {
                    // Only load submissions that are still actionable (not yet processed, or recently processed)
                    for (ValidSubmission s : loaded) {
                        // Fix null status from old persistence format
                        if (s.getStatus() == null) {
                            s.markAsFailed("Unknown state after restart");
                        }
                        // Don't re-add if we already have it in memory (by UUID)
                        if (s.getUuid() != null && findByUuid(s.getUuid()) != null) {
                            continue;
                        }
                        validSubmissions.add(s);
                    }
                    debugLogEventFlow("persistence", null, "loaded " + loaded.size() + " for " + accountHash);
                    notifyUpdateCallback();
                }
            } catch (Exception e) {
                log.debug("Failed to load persisted submissions: {}", e.getMessage());
            }
        });
    }

    /**
     * Save current submissions to disk. This is debounced to avoid excessive I/O.
     */
    private void schedulePersistence() {
        if (executor == null) {
            return;
        }
        if (saveScheduled.compareAndSet(false, true)) {
            pendingSave = executor.schedule(() -> {
                saveScheduled.set(false);
                persistSubmissions();
            }, 2, TimeUnit.SECONDS);
        }
    }

    private void persistSubmissions() {
        String accountHash = client != null ? String.valueOf(client.getAccountHash()) : null;
        if (accountHash == null || "-1".equals(accountHash)) {
            return;
        }

        try {
            Path filePath = getSubmissionFilePath(accountHash);
            Files.createDirectories(filePath.getParent());

            // Only persist submissions that have webhook data (can be retried) or are recent
            List<ValidSubmission> toSave = new ArrayList<>();
            for (ValidSubmission s : validSubmissions) {
                toSave.add(s);
                if (toSave.size() >= MAX_PERSISTED_SUBMISSIONS) {
                    break;
                }
            }

            String json = gson.newBuilder().setPrettyPrinting().create().toJson(toSave);
            Files.write(filePath, json.getBytes(StandardCharsets.UTF_8));
            debugLogEventFlow("persistence", null, "saved " + toSave.size() + " for " + accountHash);
        } catch (Exception e) {
            log.debug("Failed to persist submissions: {}", e.getMessage());
        }
    }

    private Path getSubmissionFilePath(String accountHash) {
        return RuneLite.RUNELITE_DIR.toPath().resolve(PERSISTENCE_DIR).resolve(PERSISTENCE_FILE_PREFIX + accountHash + ".json");
    }

    private ValidSubmission findByUuid(String uuid) {
        if (uuid == null) return null;
        for (ValidSubmission s : validSubmissions) {
            if (uuid.equals(s.getUuid())) {
                return s;
            }
        }
        return null;
    }

    // ========== Utilities ==========

    /**
     * The current world's type for submission tagging (see {@link WorldTypes}).
     * Submissions from all world types are sent to the server; this field lets the
     * server separate main-game data from temporary-world data.
     */
    private String getWorldTypeName() {
        return WorldTypes.submissionName(client.getWorldType());
    }

    public String sanitize(String str) {
        if (str == null || str.isEmpty())
            return "";
        return Text.removeTags(ChatMessageUtil.expandTagVariables(str).replace("<br>", "\n")).replace('\u00A0', ' ').trim();
    }

    /**
     * Check if a specific embed field has value "true"
     */
    private boolean isFieldTrue(CustomWebhookBody webhook, String fieldName) {
        if (webhook == null || webhook.getEmbeds() == null) return false;
        for (CustomWebhookBody.Embed embed : webhook.getEmbeds()) {
            for (CustomWebhookBody.Field field : embed.getFields()) {
                if (field.getName().equalsIgnoreCase(fieldName)
                        && field.getValue().equalsIgnoreCase("true")) {
                    return true;
                }
            }
        }
        return false;
    }

    private void submissionsChanged() {
        notifyUpdateCallback();
        schedulePersistence();
    }

    private void notifyUpdateCallback() {
        if (updatesEnabled && updateCallback != null) {
            updateCallback.onSubmissionsUpdated();
        }
    }

    private void debugLogFlow(String stage, ValidSubmission submission, String message) {
        debugLogEventFlow(stage, submission != null ? submission.getType() : null, message);
    }

    private void debugLogEventFlow(String stage, SubmissionType type, String message) {
        DebugLogger.log("[SubmissionManager][" + stage + "][" + (type != null ? type : "UNKNOWN") + "] " + message);
    }

    private String summarizeSubmission(ValidSubmission submission) {
        if (submission == null) {
            return "none";
        }
        return submission.getUuid() + " " + submission.getStatus() + " groups=" + Arrays.toString(submission.getGroupIds());
    }

    // ========== Inner Classes ==========

    public interface SubmissionUpdateCallback {
        void onSubmissionsUpdated();
    }

    @Getter
    private static class ApiResponse {
        private String notice;

        @SerializedName("rank_update")
        private String rankUpdate;

        private String status;

        private Boolean processed;

        @SerializedName("submission_id")
        private String submissionId;
    }

    /**
     * Represents an event that arrived before group configs were loaded.
     * Stored temporarily until configs arrive, then re-evaluated.
     */
    @AllArgsConstructor(access = AccessLevel.PACKAGE)
    private static class PendingEvent {
        final CustomWebhookBody webhook;
        final SubmissionType type;
        final boolean hasScreenshot;
        final long totalValue;
        final long singleValue;

    }
}

package io.droptracker.ui;

import io.droptracker.api.*;
import io.droptracker.*;
import io.droptracker.service.*;

import javax.inject.Inject;
import javax.swing.*;

import io.droptracker.ui.components.*;
import io.droptracker.ui.pages.*;
import io.droptracker.util.*;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.ui.*;
import net.runelite.client.game.ItemManager;
import net.runelite.client.util.*;
import okhttp3.OkHttpClient;

import javax.swing.border.EmptyBorder;
import java.awt.*;

@Slf4j
public class DropTrackerPanel extends PluginPanel {

	private static final ImageIcon LOGO_GIF;

	static {
		Image logoGif = ImageUtil.loadImageResource(DropTrackerPlugin.class, "brand/droptracker-small.gif");
		Image logoResized = logoGif.getScaledInstance(44, 44, Image.SCALE_DEFAULT);
		LOGO_GIF = new ImageIcon(logoResized);
	}

	/** Connection state shown as a dot + label in the persistent header. */
	public enum ConnectionState {
		CONNECTED("Connected", DropTrackerTheme.GREEN),
		CONNECTING("Connecting…", DropTrackerTheme.EMBER),
		OFFLINE("Offline", DropTrackerTheme.RED),
		DISABLED("API off", DropTrackerTheme.STONE);

		private final String label;
		private final Color color;

		ConnectionState(String label, Color color) {
			this.label = label;
			this.color = color;
		}
	}

	private final DropTrackerPlugin plugin;
	private final DropTrackerApi api;
	private final OkHttpClient httpClient;
	private JPanel headerPanel;

	@Inject
	private Client client;
	@Inject
	private ItemManager itemManager;
	@Inject
	private DropTrackerConfig config;
	@Inject
	private SubmissionManager submissionManager;
	@Inject
	private EventNotificationService eventNotificationService;
	@Inject
	private RemoteImageCache remoteImageCache;
	@Inject
	private ItemImageCache itemImageCache;
	@Inject
	private ItemIDSearch itemIDSearch;
	@Inject
	private ConfigManager configManager;
	@Inject
	private io.droptracker.service.PlayerModelService playerModelService;
	@Inject
	private io.droptracker.api.DeathMessageApi deathMessageApi;
	@Inject
	private io.droptracker.api.GroupAdminApi groupAdminApi;
	@Inject
	private net.runelite.client.callback.ClientThread clientThread;

	private PlayerStatsPanel statsPanel;
	private GroupPanel groupPanel;
	private ActivityPanel activityPanel;
	private HomePanel homePanel;
	private EventsPanel eventsPanel;
	/** This panel's registration on the event service's state-updated signal,
	 *  held so a re-init can deregister the previous one. */
	private Runnable stateUpdatedListener;
	private JTabbedPane tabbedPane;

	// The actual component instances added as tabs
	private JPanel homeComponent;
	private JPanel activityComponent;
	private JPanel playerComponent;
	private JPanel groupComponent;
	private JPanel eventsComponent;

	private JLabel statusDotLabel;
	private JLabel statusTextLabel;

	@Inject
	public DropTrackerPanel(DropTrackerConfig config, DropTrackerApi api, DropTrackerPlugin plugin, Client client, OkHttpClient httpClient) {
		this.config = config;
		this.api = api;
		this.plugin = plugin;
		this.client = client;
		this.httpClient = httpClient;
		// Static UI helpers fetch images through the shared client; hand it over once here.
		// They also need to know whether the API is on: lootboards come from our own
		// host, so they must not be fetched unless the user has enabled connections.
		PanelElements.setHttpClient(httpClient, config.useApi());

		setLayout(new BorderLayout());
		setBorder(new EmptyBorder(6, 6, 6, 6));
		setBackground(DropTrackerTheme.SURFACE_0);

		// init() will be called by the plugin - don't call it here to avoid double initialization
	}

	public void init() {
		// Stop any timer owned by a previous incarnation of the Activity tab
		if (activityPanel != null) {
			activityPanel.cleanup();
			activityPanel = null;
		}
		removeAll();

		setLayout(new BorderLayout());
		headerPanel = buildHeader();

		tabbedPane = new JTabbedPane();
		tabbedPane.setBackground(DropTrackerTheme.SURFACE_0);
		tabbedPane.setForeground(DropTrackerTheme.TEXT);
		tabbedPane.setFont(FontManager.getRunescapeSmallFont());

		homePanel = new HomePanel(config, api, client, this, groupAdminApi);
		homeComponent = homePanel.create();

		if (config.useApi()) {
			activityPanel = new ActivityPanel(config, api, submissionManager, this);
			activityComponent = activityPanel.create();
			statsPanel = new PlayerStatsPanel(client, plugin, config, api, itemManager);
			playerComponent = statsPanel.create();
			groupPanel = new GroupPanel(client, config, api, itemManager, this, httpClient);
			groupComponent = groupPanel.create();
			eventsPanel = new EventsPanel(config, api, eventNotificationService,
				client, itemManager, itemImageCache, remoteImageCache, itemIDSearch, configManager);
			eventsComponent = eventsPanel.create();
			// init() re-runs whenever the API toggle changes, so drop the
			// previous registration first — the service keeps a list now, and
			// re-adding without this would refresh the panel once per init().
			eventNotificationService.removeStateUpdatedListener(stateUpdatedListener);
			stateUpdatedListener = () -> {
				if (eventsPanel != null) {
					eventsPanel.onUpdated();
				}
			};
			eventNotificationService.addStateUpdatedListener(stateUpdatedListener);

			tabbedPane.addTab("Home", homeComponent);
			tabbedPane.addTab("Activity", activityComponent);
			tabbedPane.addTab("Events", eventsComponent);
			tabbedPane.addTab("Player", playerComponent);
			tabbedPane.addTab("Group", groupComponent);
			tabbedPane.addTab("Extras", new ExtrasPanel(config, client, deathMessageApi, playerModelService).create());
		} else {
			activityComponent = null;
			playerComponent = null;
			groupComponent = null;
			eventsComponent = null;
			eventsPanel = null;
			eventNotificationService.removeStateUpdatedListener(stateUpdatedListener);
			stateUpdatedListener = null;
			tabbedPane.addTab("Home", homeComponent);
		}

		add(headerPanel, BorderLayout.NORTH);
		add(tabbedPane, BorderLayout.CENTER);
		tabbedPane.setSelectedComponent(homeComponent);

		// Populate the connection indicator once everything is wired up
		if (config.useApi() && activityPanel != null) {
			activityPanel.updateStatusLabel();
		} else {
			updateConnectionState(ConnectionState.DISABLED);
		}

		revalidate();
		repaint();
	}

	/**
	 * Compact persistent header: logo, name + version, tracked account, and a single
	 * connection dot + label, plus the refresh affordance.
	 */
	private JPanel buildHeader() {
		JPanel header = DropTrackerTheme.vbox(DropTrackerTheme.SURFACE_1);
		header.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createMatteBorder(0, 0, 1, 0, DropTrackerTheme.SURFACE_3),
			new EmptyBorder(6, 8, 6, 8)));

		// Row 1: logo | title + version | refresh
		JPanel topRow = new JPanel(new BorderLayout(8, 0));
		topRow.setBackground(DropTrackerTheme.SURFACE_1);
		topRow.setMaximumSize(new Dimension(PluginPanel.PANEL_WIDTH, 48));

		JLabel logoLabel = new JLabel(LOGO_GIF);
		topRow.add(logoLabel, BorderLayout.WEST);

		JPanel titleCol = DropTrackerTheme.vbox(DropTrackerTheme.SURFACE_1);

		JLabel titleLabel = DropTrackerTheme.label("DropTracker", FontManager.getRunescapeBoldFont(), DropTrackerTheme.TEXT);
		titleLabel.setAlignmentX(Component.LEFT_ALIGNMENT);

		JLabel versionLabel = DropTrackerTheme.label("v" + plugin.pluginVersion, FontManager.getRunescapeSmallFont(), DropTrackerTheme.TEXT_MUTED);
		versionLabel.setAlignmentX(Component.LEFT_ALIGNMENT);

		titleCol.add(Box.createVerticalGlue());
		titleCol.add(titleLabel);
		titleCol.add(versionLabel);
		titleCol.add(Box.createVerticalGlue());
		topRow.add(titleCol, BorderLayout.CENTER);

		JButton docsButton = DropTrackerTheme.button("?");
		docsButton.setToolTipText("Open the DropTracker documentation");
		docsButton.setPreferredSize(new Dimension(26, 26));
		docsButton.setMargin(new java.awt.Insets(0, 0, 0, 0));
		docsButton.addActionListener(e -> LinkBrowser.browse(DropTrackerUrls.web("docs").toString()));

		JButton refreshButton = new JButton(PanelIcons.refresh(DropTrackerTheme.TEXT, 12));
		DropTrackerTheme.styleButton(refreshButton);
		refreshButton.setToolTipText("Refresh panel");
		refreshButton.setPreferredSize(new Dimension(26, 26));
		refreshButton.setMargin(new java.awt.Insets(0, 0, 0, 0));
		refreshButton.addActionListener(e -> init());

		JPanel refreshWrap = new JPanel(new FlowLayout(FlowLayout.RIGHT, 4, 0));
		refreshWrap.setBackground(DropTrackerTheme.SURFACE_1);
		refreshWrap.add(docsButton);
		refreshWrap.add(refreshButton);
		topRow.add(refreshWrap, BorderLayout.EAST);

		header.add(topRow);
		header.add(DropTrackerTheme.gap(4));

		// Row 2: tracked account + connection status on one compact line
		JPanel statusRow = new JPanel(new BorderLayout(4, 0));
		statusRow.setBackground(DropTrackerTheme.SURFACE_1);
		statusRow.setMaximumSize(new Dimension(PluginPanel.PANEL_WIDTH, 18));

		JLabel accountLabel = new JLabel();
		accountLabel.setFont(FontManager.getRunescapeSmallFont());
		String lastAccount = config.lastAccountName();
		if (lastAccount != null && !lastAccount.isEmpty()) {
			accountLabel.setText(lastAccount);
			accountLabel.setForeground(DropTrackerTheme.TEXT_MUTED);
			accountLabel.setToolTipText("Currently tracked account");
		} else {
			accountLabel.setText("You are not registered!");
			accountLabel.setForeground(DropTrackerTheme.EMBER);
			accountLabel.setToolTipText("<html>Claim your in-game name in our Discord to register.<br/>"
				+ "Join via the <b>Join Discord</b> button on the Home tab.</html>");
		}
		statusRow.add(accountLabel, BorderLayout.WEST);

		JPanel connectionPanel = new JPanel(new FlowLayout(FlowLayout.RIGHT, 3, 0));
		connectionPanel.setBackground(DropTrackerTheme.SURFACE_1);
		statusDotLabel = DropTrackerTheme.statusDot(DropTrackerTheme.STONE);
		statusTextLabel = DropTrackerTheme.label("…", FontManager.getRunescapeSmallFont(), DropTrackerTheme.TEXT_MUTED);
		connectionPanel.add(statusDotLabel);
		connectionPanel.add(statusTextLabel);
		statusRow.add(connectionPanel, BorderLayout.EAST);

		header.add(statusRow);

		return header;
	}

	public void deinit() {
		removeAll();
		if (activityPanel != null) {
			activityPanel.cleanup();
		}
		// Only this panel's own registration — the team indicator service has
		// its own listener on the same signal and must outlive the panel.
		eventNotificationService.removeStateUpdatedListener(stateUpdatedListener);
		stateUpdatedListener = null;
		eventsPanel = null;
	}

	public void selectPanel(String panelToSelect) {
		if (tabbedPane == null) {
			return;
		}

		switch (panelToSelect.toLowerCase()) {
			case "home":
			case "welcome":
				if (homeComponent != null) {
					tabbedPane.setSelectedComponent(homeComponent);
				}
				break;
			case "player":
			case "players":
			case "stats":
				if (playerComponent != null && config.useApi()) {
					tabbedPane.setSelectedComponent(playerComponent);
				}
				break;
			case "group":
			case "groups":
				if (groupComponent != null && config.useApi()) {
					tabbedPane.setSelectedComponent(groupComponent);
				}
				break;
			// "api" kept for backwards compatibility: that tab is now "Activity"
			case "api":
			case "activity":
				if (activityComponent != null && config.useApi()) {
					tabbedPane.setSelectedComponent(activityComponent);
				}
				break;
			default:
				break;
		}
	}

	// Allow searched for player by name (Perhaps for right-click lookups later, etc)
	public void updatePlayerPanel(String playerToLoad) {
		if (statsPanel != null) {
			statsPanel.performPlayerSearch(playerToLoad);
		}
	}

	// Update the player panel with the current player's name
	public void updatePlayerPanel() {
		if (statsPanel != null) {
			statsPanel.performPlayerSearch("");
		}
	}

	/** Registers a group in game; without the API or a logged-in account, the website's guide. */
	public void openRegister() {
		String name = config.lastAccountName();
		if (config.useApi() && name != null && !name.isEmpty() && client.getAccountHash() != -1) {
			io.droptracker.ui.admin.RegisterWindow.open(client, clientThread, config, groupAdminApi);
		} else {
			LinkBrowser.browse(DropTrackerUrls.web("wiki", "create-group").toString());
		}
	}

	// Update the Activity tab with the current session's valid submissions
	public void updateSentSubmissions() {
		if (activityPanel != null) {
			activityPanel.refresh();
		}
	}

	/**
	 * Updates the player button on the home panel if a local name becomes available after initial render
	 */
	public void updateHomePlayerButton() {
		if (homePanel != null) {
			homePanel.updatePlayerButton();
		}
	}

	/**
	 * Updates the connection dot + label in the persistent header.
	 */
	public void updateConnectionState(ConnectionState state) {
		if (statusDotLabel == null || statusTextLabel == null || state == null) {
			return;
		}
		statusDotLabel.setForeground(state.color);
		statusTextLabel.setText(state.label);
		statusTextLabel.setForeground(state.color);
		if (headerPanel != null) {
			headerPanel.revalidate();
			headerPanel.repaint();
		}
	}
}

package io.droptracker.ui;

import io.droptracker.ui.components.PanelIcons;
import net.runelite.client.ui.FontManager;

import javax.swing.*;
import javax.swing.border.*;
import java.awt.*;
import java.awt.event.*;

/**
 * Design tokens for the DropTracker side panel, mapped from the droptracker.io web
 * design system (dark parchment surfaces, gold accents) to Swing colors.
 *
 * Surfaces get lighter as they nest: SURFACE_0 is the page background, SURFACE_1 is a
 * card, SURFACE_2 is nested/hover content inside a card, SURFACE_3 is borders/accents.
 */
public final class DropTrackerTheme {

    /* Surfaces */
    public static final Color SURFACE_0 = new Color(0x15110c);
    public static final Color SURFACE_1 = new Color(0x211a12);
    public static final Color SURFACE_2 = new Color(0x2c2318);
    public static final Color SURFACE_3 = new Color(0x3a2f20);

    /* Text */
    public static final Color TEXT = new Color(0xefe6d2);
    public static final Color TEXT_MUTED = new Color(0xd8c9a3);

    /* Accents */
    public static final Color GOLD = new Color(0xffb83f);
    public static final Color GOLD_BRIGHT = new Color(0xffd966);
    public static final Color GREEN = new Color(0x6fbf73);
    public static final Color RED = new Color(0xe05c4d);
    public static final Color EMBER = new Color(0xff8c42);

    /* Subtle borders */
    public static final Color BRONZE = new Color(0x7a5a32);
    public static final Color STONE = new Color(0x5a5a52);

    private DropTrackerTheme() {
    }

    /** Standard matte card border: 1px SURFACE_3 line with 8px inner padding. */
    public static Border cardBorder() {
        return cardBorder(8, 8, 8, 8);
    }

    /** Matte card border with custom inner padding. */
    public static Border cardBorder(int top, int left, int bottom, int right) {
        return BorderFactory.createCompoundBorder(
            BorderFactory.createLineBorder(SURFACE_3, 1),
            new EmptyBorder(top, left, bottom, right));
    }

    /** Accented card border (bronze), for panels that should stand out. */
    public static Border accentCardBorder(int top, int left, int bottom, int right) {
        return BorderFactory.createCompoundBorder(
            BorderFactory.createLineBorder(BRONZE, 1),
            new EmptyBorder(top, left, bottom, right));
    }

    /** Creates a SURFACE_1 card panel with the standard matte border. */
    public static JPanel card(LayoutManager layout) {
        JPanel panel = new JPanel(layout);
        panel.setBackground(SURFACE_1);
        panel.setBorder(cardBorder());
        return panel;
    }

    /** A vertical BoxLayout panel on the given background. */
    public static JPanel vbox(Color background) {
        JPanel panel = new JPanel();
        panel.setLayout(new BoxLayout(panel, BoxLayout.Y_AXIS));
        panel.setBackground(background);
        return panel;
    }

    /** A label in the given font and colour. */
    public static JLabel label(String text, Font font, Color color) {
        JLabel label = new JLabel(text);
        label.setFont(font);
        label.setForeground(color);
        return label;
    }

    /** A fixed vertical gap (a rigid area: unlike a strut it never stretches sideways). */
    public static Component gap(int height) {
        return Box.createRigidArea(new Dimension(0, height));
    }

    /** Applies the standard themed button look (SURFACE_2 body, gold-bright hover). */
    public static JButton button(String text) {
        JButton button = new JButton(text);
        styleButton(button);
        return button;
    }

    /** A panel no taller than its content inside a vertical BoxLayout. */
    public static class FitPanel extends JPanel {
        public FitPanel(LayoutManager layout) {
            super(layout);
        }

        @Override
        public Dimension getMaximumSize() {
            return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
        }
    }

    public static void styleButton(JButton button) {
        button.setFocusPainted(false);
        button.setContentAreaFilled(true);
        button.setOpaque(true);
        button.setBackground(SURFACE_2);
        button.setForeground(TEXT);
        button.setFont(FontManager.getRunescapeSmallFont());
        button.setBorder(BorderFactory.createCompoundBorder(
            BorderFactory.createLineBorder(SURFACE_3, 1),
            new EmptyBorder(4, 8, 4, 8)));
        button.addMouseListener(new MouseAdapter() {
            @Override
            public void mouseEntered(MouseEvent e) {
                if (button.isEnabled()) {
                    button.setBackground(SURFACE_3);
                    button.setForeground(GOLD_BRIGHT);
                }
            }

            @Override
            public void mouseExited(MouseEvent e) {
                button.setBackground(SURFACE_2);
                button.setForeground(TEXT);
            }
        });
    }

    /** Small round status dot in the given color. Painted rather than drawn as
     *  a "●" glyph, which no bundled font carries (see PanelIcons). */
    public static JLabel statusDot(Color color) {
        JLabel dot = new JLabel(PanelIcons.dot(color, 10));
        dot.setForeground(color);
        return dot;
    }

    /**
     * Compact status "chip": small bordered label used for submission states.
     * The chip text is rendered in the accent color on a SURFACE_2 body.
     */
    public static JLabel chip(String text, Color accent) {
        JLabel label = new JLabel(text);
        label.setFont(FontManager.getRunescapeSmallFont());
        label.setForeground(accent);
        label.setOpaque(true);
        label.setBackground(SURFACE_2);
        label.setBorder(BorderFactory.createCompoundBorder(
            BorderFactory.createLineBorder(SURFACE_3, 1),
            new EmptyBorder(1, 4, 1, 4)));
        return label;
    }
}

package io.droptracker.ui.admin;

import java.awt.*;
import java.awt.event.*;
import java.util.*;
import java.util.List;
import java.util.function.Consumer;

import javax.swing.*;
import javax.swing.border.EmptyBorder;

import io.droptracker.models.api.GroupAdmin;
import io.droptracker.ui.DropTrackerTheme;
import net.runelite.client.ui.FontManager;

/**
 * Picks several of a setting's options (Hall of Fame bosses, pets, slayer
 * masters): a search box, the options under their headings, and a count.
 * Nothing changes until Done.
 */
final class ChecklistDialog {

    private ChecklistDialog() {
    }

    static void open(Component owner, String title, List<GroupAdmin.Choice> options, Set<String> chosen,
                     Consumer<Set<String>> onDone) {
        JDialog dialog = new JDialog(SwingUtilities.getWindowAncestor(owner), title, Dialog.ModalityType.APPLICATION_MODAL);
        dialog.setContentPane(content(options, chosen, dialog::dispose, picked -> {
            dialog.dispose();
            onDone.accept(picked);
        }));
        dialog.setSize(380, 480);
        dialog.setLocationRelativeTo(owner);
        dialog.setVisible(true);
    }

    static JPanel content(List<GroupAdmin.Choice> options, Set<String> chosen, Runnable close,
                          Consumer<Set<String>> onDone) {
        Set<String> picked = new LinkedHashSet<>(chosen);
        JPanel list = DropTrackerTheme.vbox(DropTrackerTheme.SURFACE_1);
        list.setBorder(new EmptyBorder(4, 8, 4, 8));
        JLabel count = DropTrackerTheme.label(" ", FontManager.getRunescapeSmallFont(), DropTrackerTheme.TEXT_MUTED);
        JTextField search = new JTextField();
        search.putClientProperty("JTextField.placeholderText", "Search");
        search.setFont(FontManager.getRunescapeSmallFont());

        Map<GroupAdmin.Choice, JCheckBox> boxes = new LinkedHashMap<>();
        for (GroupAdmin.Choice option : options) {
            JCheckBox box = new JCheckBox(option.getLabel() == null ? option.getValue() : option.getLabel(),
                picked.contains(option.getValue()));
            box.setFont(FontManager.getRunescapeSmallFont());
            box.setForeground(DropTrackerTheme.TEXT);
            box.setOpaque(false);
            box.addActionListener(e -> {
                if (box.isSelected()) {
                    picked.add(option.getValue());
                } else {
                    picked.remove(option.getValue());
                }
                count.setText(picked.size() + " of " + options.size() + " chosen");
            });
            boxes.put(option, box);
        }

        Runnable refresh = () -> {
            String needle = search.getText().trim().toLowerCase(Locale.ROOT);
            list.removeAll();
            String heading = null;
            for (Map.Entry<GroupAdmin.Choice, JCheckBox> entry : boxes.entrySet()) {
                JCheckBox box = entry.getValue();
                if (!box.getText().toLowerCase(Locale.ROOT).contains(needle)) {
                    continue;
                }
                String group = entry.getKey().getGroup();
                if (group != null && !group.equals(heading)) {
                    heading = group;
                    JLabel label = DropTrackerTheme.label(group, FontManager.getRunescapeSmallFont(), DropTrackerTheme.GOLD);
                    label.setBorder(new EmptyBorder(list.getComponentCount() == 0 ? 2 : 8, 2, 2, 0));
                    list.add(SettingsForm.left(label));
                }
                box.setSelected(picked.contains(entry.getKey().getValue()));
                list.add(SettingsForm.left(box));
            }
            if (list.getComponentCount() == 0) {
                list.add(SettingsForm.left(DropTrackerTheme.label("Nothing matches \"" + search.getText().trim() + "\".",
                    FontManager.getRunescapeSmallFont(), DropTrackerTheme.TEXT_MUTED)));
            }
            count.setText(picked.size() + " of " + options.size() + " chosen");
            list.revalidate();
            list.repaint();
        };
        SettingsForm.listen(search, refresh);

        JButton all = button("Select shown", () -> {
            boxes.forEach((option, box) -> {
                if (box.getParent() == list) {
                    picked.add(option.getValue());
                }
            });
            refresh.run();
        });
        JButton none = button("Clear", () -> {
            picked.clear();
            refresh.run();
        });
        JButton cancel = button("Cancel", close);
        JButton done = button("Done", () -> onDone.accept(picked));
        done.setForeground(DropTrackerTheme.GOLD_BRIGHT);

        JPanel top = new JPanel(new BorderLayout(0, 6));
        top.setOpaque(false);
        top.add(search, BorderLayout.CENTER);
        top.add(count, BorderLayout.SOUTH);
        JScrollPane scroll = new JScrollPane(list);
        scroll.setBorder(BorderFactory.createLineBorder(DropTrackerTheme.SURFACE_3));
        scroll.getVerticalScrollBar().setUnitIncrement(16);
        JPanel buttons = new JPanel(new BorderLayout());
        buttons.setOpaque(false);
        buttons.add(row(all, none), BorderLayout.WEST);
        buttons.add(row(cancel, done), BorderLayout.EAST);

        JPanel content = new JPanel(new BorderLayout(0, 8));
        content.setBackground(DropTrackerTheme.SURFACE_0);
        content.setBorder(new EmptyBorder(12, 12, 12, 12));
        content.add(top, BorderLayout.NORTH);
        content.add(scroll, BorderLayout.CENTER);
        content.add(buttons, BorderLayout.SOUTH);
        content.registerKeyboardAction(e -> close.run(), KeyStroke.getKeyStroke(KeyEvent.VK_ESCAPE, 0),
            JComponent.WHEN_IN_FOCUSED_WINDOW);
        refresh.run();
        return content;
    }

    private static JButton button(String text, Runnable action) {
        JButton b = DropTrackerTheme.button(text);
        b.addActionListener(e -> action.run());
        return b;
    }

    private static JPanel row(JComponent... items) {
        JPanel row = new JPanel(new FlowLayout(FlowLayout.LEFT, 6, 0));
        row.setOpaque(false);
        for (JComponent item : items) {
            row.add(item);
        }
        return row;
    }
}

package io.droptracker.ui.admin;

import java.awt.*;
import java.awt.event.*;
import java.util.*;
import java.util.List;

import javax.annotation.Nullable;
import javax.swing.*;
import javax.swing.border.EmptyBorder;
import javax.swing.text.*;

import io.droptracker.ui.DropTrackerTheme;
import net.runelite.client.ui.FontManager;

/**
 * Three boxes of three digits for a {@code 123-456-789} verification code.
 * Typing moves to the next box, backspace in an empty box moves back, and a
 * pasted code in any spelling fills all three.
 */
class CodeEntryPanel extends JPanel {

    private final List<JTextField> boxes = new ArrayList<>();
    private final Runnable onChange;

    CodeEntryPanel(Runnable onSubmit, Runnable onChange) {
        super(new FlowLayout(FlowLayout.CENTER, 6, 0));
        this.onChange = onChange;
        setOpaque(false);
        for (int i = 0; i < 3; i++) {
            if (i > 0) {
                add(DropTrackerTheme.label("-", FontManager.getRunescapeBoldFont(), DropTrackerTheme.TEXT_MUTED));
            }
            JTextField box = new JTextField(3);
            box.setFont(FontManager.getRunescapeBoldFont().deriveFont(20f));
            box.setHorizontalAlignment(JTextField.CENTER);
            box.setBackground(DropTrackerTheme.SURFACE_2);
            box.setForeground(DropTrackerTheme.GOLD_BRIGHT);
            box.setCaretColor(DropTrackerTheme.GOLD_BRIGHT);
            box.setBorder(BorderFactory.createCompoundBorder(
                BorderFactory.createLineBorder(DropTrackerTheme.BRONZE, 1), new EmptyBorder(6, 8, 6, 8)));
            ((AbstractDocument) box.getDocument()).setDocumentFilter(new DigitsFilter(i));
            int index = i;
            SettingsForm.listen(box, () -> changed(index));
            box.addKeyListener(new KeyAdapter() {
                @Override
                public void keyPressed(KeyEvent e) {
                    if (e.getKeyCode() == KeyEvent.VK_BACK_SPACE && box.getText().isEmpty() && index > 0) {
                        boxes.get(index - 1).requestFocusInWindow();
                    } else if (e.getKeyCode() == KeyEvent.VK_ENTER && code() != null) {
                        onSubmit.run();
                    }
                }
            });
            boxes.add(box);
            add(box);
        }
    }

    /** The code as {@code 123-456-789}, or null until all nine digits are in. */
    @Nullable
    String code() {
        StringBuilder sb = new StringBuilder();
        for (JTextField box : boxes) {
            if (box.getText().length() != 3) {
                return null;
            }
            sb.append(sb.length() > 0 ? "-" : "").append(box.getText());
        }
        return sb.toString();
    }

    void clear() {
        for (JTextField box : boxes) {
            box.setText("");
        }
        focusFirst();
    }

    void focusFirst() {
        boxes.get(0).requestFocusInWindow();
    }

    @Override
    public void setEnabled(boolean enabled) {
        super.setEnabled(enabled);
        for (JTextField box : boxes) {
            box.setEnabled(enabled);
        }
    }

    /** Fills the boxes from {@code start} with up to nine digits. */
    void fill(String digits, int start) {
        int box = start;
        for (int i = 0; i < digits.length() && box < boxes.size(); i += 3, box++) {
            boxes.get(box).setText(digits.substring(i, Math.min(i + 3, digits.length())));
        }
    }

    private void changed(int index) {
        if (boxes.size() == 3 && boxes.get(index).getText().length() == 3 && index < 2) {
            SwingUtilities.invokeLater(() -> boxes.get(index + 1).requestFocusInWindow());
        }
        onChange.run();
    }

    /** Digits only, three per box; a longer paste spills into the boxes after. */
    private final class DigitsFilter extends DocumentFilter {
        private final int index;

        DigitsFilter(int index) {
            this.index = index;
        }

        @Override
        public void insertString(FilterBypass fb, int offset, String text, AttributeSet attr)
            throws BadLocationException {
            replace(fb, offset, 0, text, attr);
        }

        @Override
        public void replace(FilterBypass fb, int offset, int length, String text, AttributeSet attrs)
            throws BadLocationException {
            String digits = text == null ? "" : text.replaceAll("[^0-9]", "");
            if (digits.length() > 3) {
                // A pasted code: spread it over this box and the ones after.
                String all = digits.substring(0, Math.min(digits.length(), 9 - index * 3));
                SwingUtilities.invokeLater(() -> fill(all, index));
                return;
            }
            int room = 3 - (fb.getDocument().getLength() - length);
            super.replace(fb, offset, length, digits.substring(0, Math.min(digits.length(), Math.max(room, 0))), attrs);
        }
    }
}

package io.droptracker.ui.admin;

import java.awt.*;
import java.awt.event.*;
import java.util.*;
import java.util.List;
import java.util.function.*;

import javax.annotation.Nullable;
import javax.swing.*;
import javax.swing.border.*;

import io.droptracker.DropTrackerConfig;
import io.droptracker.api.*;
import io.droptracker.models.api.GroupAdmin;
import io.droptracker.ui.DropTrackerTheme;
import io.droptracker.ui.components.*;
import net.runelite.api.Client;
import net.runelite.client.ui.FontManager;
import net.runelite.client.util.LinkBrowser;

/**
 * The group manager: a window of its own rather than more side-panel rows,
 * because a group has dozens of settings and the side panel is 225px wide.
 *
 * <p>Left, a list of pages (Overview, Members, then one per settings category
 * from the server); right, the page; along the bottom, a save bar that appears once
 * something has changed. Before any of that, a group needs its verification
 * code once on this device (see {@link GroupAdminApi}).
 */
public class GroupAdminWindow extends JPanel {

    private static final String STATUS = "status";
    private static final String LINK = "link";
    private static final String MANAGE = "manage";

    @Nullable
    private static JDialog openDialog;
    @Nullable
    private static GroupAdminWindow openWindow;

    private final GroupAdminApi api;
    private final Supplier<String> playerName;
    private final LongSupplier accountHash;
    private final List<GroupAdmin.Group> groups;

    private final CardLayout bodyCards = new CardLayout();
    private final JPanel body = new JPanel(bodyCards);
    private final CardLayout pageCards = new CardLayout();
    private final JPanel pages = new JPanel(pageCards);
    private final JPanel nav = DropTrackerTheme.vbox(DropTrackerTheme.SURFACE_1);
    private final List<NavItem> navItems = new ArrayList<>();
    private final List<SettingsForm> forms = new ArrayList<>();

    private final JLabel groupName = DropTrackerTheme.label(" ", FontManager.getRunescapeBoldFont(), DropTrackerTheme.GOLD);
    private final JLabel groupMeta = DropTrackerTheme.label(" ", FontManager.getRunescapeSmallFont(), DropTrackerTheme.TEXT_MUTED);
    private final JButton signOut = button("Sign out", "Forget this device's access to the group");
    private final JComboBox<String> switcher = new JComboBox<>();

    private final JLabel statusText = DropTrackerTheme.label(" ", FontManager.getRunescapeFont(), DropTrackerTheme.TEXT_MUTED);
    private final JButton statusRetry = button("Try again", null);

    private final CodeEntryPanel codeEntry;
    private final JLabel linkTitle = DropTrackerTheme.label(" ", FontManager.getRunescapeBoldFont(), DropTrackerTheme.GOLD);
    private final JLabel linkStatus = DropTrackerTheme.label(" ", FontManager.getRunescapeSmallFont(), DropTrackerTheme.RED);
    private final JButton verify = button("Verify", null);

    private final JPanel saveBar = new JPanel(new BorderLayout());
    private final JLabel saveText = DropTrackerTheme.label(" ", FontManager.getRunescapeSmallFont(), DropTrackerTheme.TEXT);
    private final JButton save = button("Save changes", null);
    private final JButton discard = button("Discard", null);

    private GroupAdmin.Group group;
    @Nullable
    private GroupAdmin.Settings settings;
    @Nullable
    private MembersPage members;
    private boolean busy;
    private boolean closed;

    public GroupAdminWindow(GroupAdminApi api, Supplier<String> playerName, LongSupplier accountHash,
                            List<GroupAdmin.Group> groups) {
        super(new BorderLayout());
        this.api = api;
        this.playerName = playerName;
        this.accountHash = accountHash;
        this.groups = groups;
        this.codeEntry = new CodeEntryPanel(this::link, () -> verify.setEnabled(!busy && codeEntryReady()));
        setBackground(DropTrackerTheme.SURFACE_0);
        setPreferredSize(new Dimension(780, 560));

        add(header(), BorderLayout.NORTH);
        body.setBackground(DropTrackerTheme.SURFACE_0);
        body.add(statusPage(), STATUS);
        body.add(linkPage(), LINK);
        body.add(managePage(), MANAGE);
        add(body, BorderLayout.CENTER);
        add(saveBar(), BorderLayout.SOUTH);
    }

    /** Opens the manager on a group, or brings the open one forward. Call on the Swing thread. */
    public static void open(Client client, DropTrackerConfig config, GroupAdminApi api,
                            List<GroupAdmin.Group> groups, int groupId) {
        if (openDialog != null && openDialog.isDisplayable() && openWindow != null) {
            openWindow.select(groupId);
            openDialog.toFront();
            return;
        }
        JFrame parent = PanelElements.getParentFrame(client);
        JDialog dialog = new JDialog(parent, "DropTracker - Group manager", false);
        GroupAdminWindow window = new GroupAdminWindow(api, config::lastAccountName, client::getAccountHash, groups);
        dialog.setContentPane(window);
        dialog.setDefaultCloseOperation(JDialog.DO_NOTHING_ON_CLOSE);
        dialog.addWindowListener(new WindowAdapter() {
            @Override
            public void windowClosing(WindowEvent e) {
                if (window.confirmLeave("close the manager")) {
                    window.closed = true;
                    dialog.dispose();
                }
            }

            @Override
            public void windowClosed(WindowEvent e) {
                if (openDialog == dialog) {
                    openDialog = null;
                    openWindow = null;
                }
            }
        });
        dialog.setMinimumSize(new Dimension(640, 440));
        dialog.pack();
        dialog.setLocationRelativeTo(parent);
        openDialog = dialog;
        openWindow = window;
        dialog.setVisible(true);
        window.select(groupId);
    }

    /** Switches to a group: straight in with a stored session, else the code page. */
    public void select(int groupId) {
        GroupAdmin.Group next = groups.stream().filter(g -> g.getId() == groupId).findFirst()
            .orElse(groups.isEmpty() ? null : groups.get(0));
        if (next == null || (group != null && next.getId() == group.getId() && settings != null)) {
            return;
        }
        if (group != null && !confirmLeave("switch groups")) {
            syncSwitcher();
            return;
        }
        group = next;
        syncSwitcher();
        groupName.setText(next.getName());
        groupMeta.setText(meta(next));
        settings = null;
        if (api.hasSession(next.getId())) {
            load();
        } else {
            showLink(null);
        }
    }

    /** Points the switcher at the current group (it's empty with one group). */
    private void syncSwitcher() {
        int i = groups.indexOf(group);
        if (i >= 0 && i < switcher.getItemCount()) {
            switcher.setSelectedIndex(i);
        }
    }

    // ------------------------------------------------------------------ flows

    private void load() {
        int id = group.getId();
        showStatus("Loading " + group.getName() + "...", false);
        GroupAdmin.Overview[] overview = new GroupAdmin.Overview[1];
        GroupAdmin.Settings[] loaded = new GroupAdmin.Settings[1];
        String[] error = new String[1];
        boolean[] needsCode = new boolean[1];
        int[] pending = {2};
        Runnable done = () -> {
            if (--pending[0] > 0 || closed || group.getId() != id) {
                return;
            }
            if (needsCode[0]) {
                showLink(error[0]);
            } else if (error[0] != null) {
                showStatus(error[0], true);
            } else {
                build(overview[0], loaded[0]);
            }
        };
        api.overview(playerName.get(), accountHash.getAsLong(), id, r -> {
            overview[0] = r.value;
            note(r, error, needsCode);
            done.run();
        });
        api.settings(playerName.get(), accountHash.getAsLong(), id, r -> {
            loaded[0] = r.value;
            note(r, error, needsCode);
            done.run();
        });
    }

    private static void note(GroupAdminApi.Result<?> r, String[] error, boolean[] needsCode) {
        needsCode[0] |= r.needsCode;
        if (r.error != null && error[0] == null) {
            error[0] = r.error;
        }
    }

    private void link() {
        String code = codeEntry.code();
        if (code == null || busy) {
            return;
        }
        setBusy(true);
        linkStatus.setText(" ");
        int id = group.getId();
        api.link(playerName.get(), accountHash.getAsLong(), id, code, r -> {
            setBusy(false);
            if (closed || group.getId() != id) {
                return;
            }
            if (r.value == null) {
                linkStatus.setText(r.error == null ? " " : r.error);
                codeEntry.clear();
                return;
            }
            signOut.setVisible(true);
            load();
        });
    }

    private void signOut() {
        int choice = JOptionPane.showConfirmDialog(this,
            "Sign this device out of " + group.getName() + "?\nYou'll need the verification code to come back.",
            "Sign out", JOptionPane.OK_CANCEL_OPTION);
        if (choice != JOptionPane.OK_OPTION) {
            return;
        }
        api.unlink(playerName.get(), accountHash.getAsLong(), group.getId(), r -> showLink(null));
    }

    private void save() {
        Map<String, Object> changes = new LinkedHashMap<>();
        forms.forEach(f -> changes.putAll(f.changes()));
        if (changes.isEmpty() || busy) {
            return;
        }
        setBusy(true);
        saveText.setText("Saving...");
        int id = group.getId();
        api.save(playerName.get(), accountHash.getAsLong(), id, changes, r -> {
            setBusy(false);
            if (closed || group.getId() != id) {
                return;
            }
            if (r.needsCode) {
                showLink(r.error);
            } else if (r.value == null) {
                saveText.setText(r.error);
                saveText.setForeground(DropTrackerTheme.RED);
            } else if (!r.value.getErrors().isEmpty()) {
                forms.forEach(f -> f.showErrors(r.value.getErrors()));
                saveText.setText("Some changes weren't saved. Check the highlighted settings.");
                saveText.setForeground(DropTrackerTheme.RED);
            } else {
                int page = selectedPage();
                settings = r.value;
                buildForms(r.value, page);
                saveBar.setVisible(true);
                saveText.setText("Saved.");
                saveText.setForeground(DropTrackerTheme.GREEN);
                save.setVisible(false);
                discard.setVisible(false);
            }
        });
    }

    private void discard() {
        if (settings != null) {
            buildForms(settings, selectedPage());
        }
    }

    /** True when there's nothing unsaved, or the leader agrees to drop it. */
    boolean confirmLeave(String action) {
        int dirty = dirtyCount();
        if (dirty == 0) {
            return true;
        }
        return JOptionPane.showConfirmDialog(this,
            "You have " + plural(dirty, "unsaved change") + ". Discard and " + action + "?",
            "Unsaved changes", JOptionPane.OK_CANCEL_OPTION) == JOptionPane.OK_OPTION;
    }

    // ------------------------------------------------------------------ pages

    private void build(GroupAdmin.Overview overview, GroupAdmin.Settings loaded) {
        settings = loaded;
        if (overview.getGroup() != null) {
            groupMeta.setText(meta(overview.getGroup()));
        }
        signOut.setVisible(true);
        pages.removeAll();
        pages.add(overviewPage(overview), "page0");
        members = new MembersPage(api, playerName, accountHash, () -> group.getId(), this::showLink);
        buildForms(loaded, 0);
        bodyCards.show(body, MANAGE);
    }

    /** (Re)builds the nav and settings pages from the server's copy. */
    private void buildForms(GroupAdmin.Settings loaded, int page) {
        while (pages.getComponentCount() > 1) {
            pages.remove(1);
        }
        forms.clear();
        navItems.clear();
        nav.removeAll();
        nav.add(navHeading("GROUP"));
        addNav("Overview", 0);
        pages.add(members, "page1");
        addNav("Members", 1);
        nav.add(navHeading("SETTINGS"));
        int index = 2;
        for (GroupAdmin.Category category : loaded.getCategories()) {
            if (loaded.getFields().stream().noneMatch(f -> category.getKey().equals(f.getCategory()))) {
                continue;
            }
            SettingsForm form = new SettingsForm(loaded, category, this::updateSaveBar, this::openSettingsOnWeb);
            forms.add(form);
            JScrollPane scroll = new JScrollPane(form);
            scroll.setBorder(null);
            scroll.getVerticalScrollBar().setUnitIncrement(16);
            scroll.getViewport().setBackground(DropTrackerTheme.SURFACE_0);
            pages.add(scroll, "page" + index);
            addNav(category.getLabel(), index++);
        }
        nav.add(Box.createVerticalGlue());
        nav.revalidate();
        nav.repaint();
        showPage(Math.min(page, index - 1));
        updateSaveBar();
    }

    private JComponent overviewPage(GroupAdmin.Overview overview) {
        JPanel page = DropTrackerTheme.vbox(DropTrackerTheme.SURFACE_0);
        page.setBorder(new EmptyBorder(14, 16, 14, 16));
        page.add(SettingsForm.left(DropTrackerTheme.label("Overview", FontManager.getRunescapeBoldFont(), DropTrackerTheme.GOLD)));
        page.add(DropTrackerTheme.gap(10));

        JPanel tiles = new JPanel(new GridLayout(0, 3, 8, 8));
        tiles.setOpaque(false);
        for (GroupAdmin.Stat stat : overview.getStats()) {
            JPanel tile = DropTrackerTheme.vbox(DropTrackerTheme.SURFACE_1);
            tile.setBorder(DropTrackerTheme.cardBorder(8, 10, 8, 10));
            tile.add(DropTrackerTheme.label(stat.getLabel(), FontManager.getRunescapeSmallFont(), DropTrackerTheme.TEXT_MUTED));
            tile.add(DropTrackerTheme.label(stat.getValue(), FontManager.getRunescapeBoldFont(), DropTrackerTheme.GOLD_BRIGHT));
            if (stat.getDetail() != null) {
                tile.add(DropTrackerTheme.label(stat.getDetail(), FontManager.getRunescapeSmallFont(), DropTrackerTheme.TEXT_MUTED));
            }
            tiles.add(tile);
        }
        page.add(SettingsForm.left(tiles));
        page.add(DropTrackerTheme.gap(14));

        if (!overview.getChecklist().isEmpty()) {
            page.add(SettingsForm.left(DropTrackerTheme.label("Setup", FontManager.getRunescapeBoldFont(), DropTrackerTheme.TEXT)));
            page.add(DropTrackerTheme.gap(6));
            JPanel list = DropTrackerTheme.vbox(DropTrackerTheme.SURFACE_1);
            list.setBorder(DropTrackerTheme.cardBorder(4, 10, 4, 10));
            for (GroupAdmin.Check check : overview.getChecklist()) {
                JPanel row = new JPanel(new BorderLayout(8, 0));
                row.setOpaque(false);
                row.setBorder(new EmptyBorder(5, 0, 5, 0));
                JLabel mark = new JLabel(check.isOk() ? PanelIcons.check(DropTrackerTheme.GREEN, 12)
                    : PanelIcons.dot(DropTrackerTheme.EMBER, 10));
                mark.setVerticalAlignment(SwingConstants.TOP);
                row.add(mark, BorderLayout.WEST);
                JPanel text = DropTrackerTheme.vbox(DropTrackerTheme.SURFACE_1);
                text.add(SettingsForm.left(DropTrackerTheme.label(check.getLabel(), FontManager.getRunescapeSmallFont(),
                    check.isOk() ? DropTrackerTheme.TEXT : DropTrackerTheme.GOLD_BRIGHT)));
                if (!check.isOk() && check.getHint() != null) {
                    text.add(SettingsForm.left(SettingsForm.wrapped(check.getHint(), DropTrackerTheme.TEXT_MUTED)));
                }
                row.add(text, BorderLayout.CENTER);
                list.add(SettingsForm.left(row));
            }
            page.add(SettingsForm.left(list));
            page.add(DropTrackerTheme.gap(14));
        }

        JPanel links = new JPanel(new FlowLayout(FlowLayout.LEFT, 0, 0));
