    private JComponent managePage() {
        JPanel page = new JPanel(new BorderLayout());
        nav.setBorder(new CompoundBorder(new MatteBorder(0, 0, 0, 1, DropTrackerTheme.SURFACE_3), new EmptyBorder(8, 0, 8, 0)));
        nav.setPreferredSize(new Dimension(170, 0));
        page.add(nav, BorderLayout.WEST);
        pages.setBackground(DropTrackerTheme.SURFACE_0);
        page.add(pages, BorderLayout.CENTER);
        return page;
    }

    private JComponent saveBar() {
        saveBar.setBackground(DropTrackerTheme.SURFACE_1);
        saveBar.setBorder(new CompoundBorder(new MatteBorder(1, 0, 0, 0, DropTrackerTheme.GOLD), new EmptyBorder(8, 14, 8, 14)));
        saveBar.add(saveText, BorderLayout.CENTER);
        JPanel buttons = new JPanel(new FlowLayout(FlowLayout.RIGHT, 6, 0));
        buttons.setOpaque(false);
        discard.addActionListener(e -> discard());
        save.addActionListener(e -> save());
        save.setForeground(DropTrackerTheme.GOLD_BRIGHT);
        buttons.add(discard);
        buttons.add(save);
        saveBar.add(buttons, BorderLayout.EAST);
        saveBar.setVisible(false);
        return saveBar;
    }

    // ------------------------------------------------------------------ state

    private void showStatus(String text, boolean retry) {
        statusText.setText(text);
        statusRetry.setVisible(retry);
        saveBar.setVisible(false);
        bodyCards.show(body, STATUS);
    }

    private void showLink(@Nullable String message) {
        settings = null;
        forms.clear();
        signOut.setVisible(false);
        saveBar.setVisible(false);
        linkTitle.setText("Verify you manage " + group.getName());
        linkStatus.setText(message == null ? " " : message);
        codeEntry.clear();
        verify.setEnabled(false);
        bodyCards.show(body, LINK);
        SwingUtilities.invokeLater(codeEntry::focusFirst);
    }

    private void updateSaveBar() {
        int dirty = dirtyCount();
        if (dirty > 0) {
            saveText.setText(plural(dirty, "unsaved change"));
            saveText.setForeground(DropTrackerTheme.TEXT);
        }
        save.setVisible(dirty > 0);
        discard.setVisible(dirty > 0);
        save.setEnabled(!busy && forms.stream().allMatch(SettingsForm::valid));
        saveBar.setVisible(dirty > 0 || "Saved.".equals(saveText.getText()) && saveBar.isVisible());
        saveBar.revalidate();
    }

    private void setBusy(boolean busy) {
        this.busy = busy;
        save.setEnabled(!busy);
        discard.setEnabled(!busy);
        codeEntry.setEnabled(!busy);
        verify.setEnabled(!busy && codeEntryReady());
        verify.setText(busy ? "Checking..." : "Verify");
    }

    private boolean codeEntryReady() {
        return codeEntry != null && codeEntry.code() != null;
    }

    int dirtyCount() {
        return forms.stream().mapToInt(SettingsForm::dirtyCount).sum();
    }

    private void addNav(String label, int page) {
        NavItem item = new NavItem(label, page);
        navItems.add(item);
        nav.add(item);
    }

    private void showPage(int page) {
        pageCards.show(pages, "page" + page);
        if (page == 1 && members != null) {
            members.opened();
        }
        navItems.forEach(n -> n.setSelected(n.page == page));
    }

    private int selectedPage() {
        return navItems.stream().filter(n -> n.selected).mapToInt(n -> n.page).findFirst().orElse(0);
    }

    private void openSettingsOnWeb() {
        LinkBrowser.browse(groupUrl("settings"));
    }

    private JButton webButton(String text, String path) {
        JButton b = button(text, null);
        b.setIcon(PanelElements.getExternalLinkIcon());
        b.addActionListener(e -> LinkBrowser.browse(groupUrl(path)));
        return b;
    }

    private String groupUrl(String path) {
        String id = String.valueOf(group == null ? 0 : group.getId());
        return (path.isEmpty() ? DropTrackerUrls.web("groups", id) : DropTrackerUrls.web("groups", id, path)).toString();
    }

    static String meta(GroupAdmin.Group g) {
        StringBuilder sb = new StringBuilder("owner".equals(g.getRole()) ? "Owner" : "Admin");
        if (g.getMemberCount() > 0) {
            sb.append("  ·  ").append(plural(g.getMemberCount(), "member"));
        }
        if (g.getTier() != null) {
            sb.append("  ·  ").append(g.getTier());
        }
        return sb.toString();
    }

    static String plural(int n, String noun) {
        return String.format("%,d %s%s", n, noun, n == 1 ? "" : "s");
    }

    private static JButton button(String text, @Nullable String tooltip) {
        JButton b = DropTrackerTheme.button(text);
        b.setToolTipText(tooltip);
        return b;
    }

    private static JComponent navHeading(String text) {
        JLabel label = DropTrackerTheme.label(text, FontManager.getRunescapeSmallFont(), DropTrackerTheme.STONE);
        label.setBorder(new EmptyBorder(8, 14, 3, 8));
        label.setAlignmentX(LEFT_ALIGNMENT);
        label.setMaximumSize(new Dimension(Integer.MAX_VALUE, label.getPreferredSize().height));
        return label;
    }

    /** One entry in the left-hand list. Selected: lighter row and a gold edge. */
    private final class NavItem extends JLabel {
        final int page;
        boolean selected;

        NavItem(String text, int page) {
            super(text);
            this.page = page;
            setFont(FontManager.getRunescapeSmallFont());
            setOpaque(true);
            setAlignmentX(LEFT_ALIGNMENT);
            setMaximumSize(new Dimension(Integer.MAX_VALUE, 26));
            setSelected(false);
            setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
            addMouseListener(new MouseAdapter() {
                @Override
                public void mouseClicked(MouseEvent e) {
                    showPage(page);
                }

                @Override
                public void mouseEntered(MouseEvent e) {
                    if (!selected) {
                        setForeground(DropTrackerTheme.GOLD_BRIGHT);
                    }
                }

                @Override
                public void mouseExited(MouseEvent e) {
                    setSelected(selected);
                }
            });
        }

        void setSelected(boolean selected) {
            this.selected = selected;
            setBackground(selected ? DropTrackerTheme.SURFACE_2 : DropTrackerTheme.SURFACE_1);
            setForeground(selected ? DropTrackerTheme.GOLD : DropTrackerTheme.TEXT);
            setBorder(new CompoundBorder(new MatteBorder(0, 3, 0, 0, selected ? DropTrackerTheme.GOLD : DropTrackerTheme.SURFACE_1),
                new EmptyBorder(5, 11, 5, 8)));
        }
    }
}

package io.droptracker.ui.admin;

import java.awt.*;
import java.util.function.*;

import javax.swing.*;
import javax.swing.border.*;

import io.droptracker.api.GroupAdminApi;
import io.droptracker.models.api.GroupAdmin;
import io.droptracker.ui.DropTrackerTheme;
import net.runelite.client.ui.FontManager;

/**
 * The group's members, drawn from the server's page: search, most loot this
 * month first, and a switch per member for whether they appear on the group's
 * boards. Loaded the first time the page is opened.
 */
class MembersPage extends JPanel {

    private final GroupAdminApi api;
    private final Supplier<String> playerName;
    private final LongSupplier accountHash;
    private final IntSupplier groupId;
    /** Called when the session has ended, with the server's sentence. */
    private final Consumer<String> onNeedsCode;

    private final JLabel summary = DropTrackerTheme.label(" ", FontManager.getRunescapeSmallFont(), DropTrackerTheme.TEXT_MUTED);
    private final JLabel help = DropTrackerTheme.label(" ", FontManager.getRunescapeSmallFont(), DropTrackerTheme.TEXT_MUTED);
    private final JTextField search = new JTextField();
    private final JButton sync = DropTrackerTheme.button("Sync from WiseOldMan");
    private final JLabel notice = DropTrackerTheme.label(" ", FontManager.getRunescapeSmallFont(), DropTrackerTheme.TEXT_MUTED);
    private final JPanel list = DropTrackerTheme.vbox(DropTrackerTheme.SURFACE_0);
    private final JLabel footer = DropTrackerTheme.label(" ", FontManager.getRunescapeSmallFont(), DropTrackerTheme.TEXT_MUTED);
    private final Timer debounce;

    private int request;
    private boolean loaded;

    MembersPage(GroupAdminApi api, Supplier<String> playerName, LongSupplier accountHash, IntSupplier groupId,
                Consumer<String> onNeedsCode) {
        super(new BorderLayout());
        this.api = api;
        this.playerName = playerName;
        this.accountHash = accountHash;
        this.groupId = groupId;
        this.onNeedsCode = onNeedsCode;
        setBackground(DropTrackerTheme.SURFACE_0);
        setBorder(new EmptyBorder(14, 16, 10, 16));

        JPanel top = DropTrackerTheme.vbox(DropTrackerTheme.SURFACE_0);
        JPanel title = new JPanel(new BorderLayout(8, 0));
        title.setOpaque(false);
        title.add(DropTrackerTheme.label("Members", FontManager.getRunescapeBoldFont(), DropTrackerTheme.GOLD), BorderLayout.WEST);
        title.add(summary);
        top.add(SettingsForm.left(title));
        top.add(SettingsForm.left(help));
        top.add(DropTrackerTheme.gap(8));

        search.putClientProperty("JTextField.placeholderText", "Search by name");
        search.setFont(FontManager.getRunescapeSmallFont());
        debounce = new Timer(300, e -> load());
        debounce.setRepeats(false);
        SettingsForm.listen(search, debounce::restart);
        sync.addActionListener(e -> sync());
        JPanel tools = new JPanel(new BorderLayout(8, 0));
        tools.setOpaque(false);
        tools.add(search, BorderLayout.CENTER);
        tools.add(sync, BorderLayout.EAST);
        tools.setMaximumSize(new Dimension(Integer.MAX_VALUE, 28));
        top.add(SettingsForm.left(tools));
        top.add(DropTrackerTheme.gap(4));
        top.add(SettingsForm.left(notice));
        top.add(DropTrackerTheme.gap(6));
        add(top, BorderLayout.NORTH);

        JPanel wrap = new JPanel(new BorderLayout());
        wrap.setBackground(DropTrackerTheme.SURFACE_0);
        wrap.add(list, BorderLayout.NORTH);
        JScrollPane scroll = new JScrollPane(wrap);
        scroll.setBorder(null);
        scroll.getVerticalScrollBar().setUnitIncrement(16);
        add(scroll, BorderLayout.CENTER);

        footer.setBorder(new EmptyBorder(8, 0, 0, 0));
        add(footer, BorderLayout.SOUTH);
        message("Loading members...");
    }

    /** Loads the first page the first time the page is shown. */
    void opened() {
        if (!loaded) {
            loaded = true;
            load();
        }
    }

    private void load() {
        int ticket = ++request;
        api.members(playerName.get(), accountHash.getAsLong(), groupId.getAsInt(), search.getText().trim(), 1, r -> {
            if (ticket != request) {
                return;  // an older search answered after a newer one
            }
            if (r.needsCode) {
                onNeedsCode.accept(r.error);
            } else if (r.value == null) {
                message(r.error);
            } else {
                show(r.value);
            }
        });
    }

    private void show(GroupAdmin.Members m) {
        summary.setText(m.getSummary());
        help.setText(m.getHelp());
        GroupAdmin.Wom wom = m.getWom();
        sync.setVisible(wom != null && wom.isCanSync());
        if (wom != null && !notice.getForeground().equals(DropTrackerTheme.GREEN)) {
            setNotice(wom.getNote(), DropTrackerTheme.TEXT_MUTED);
        }
        list.removeAll();
        for (GroupAdmin.Member member : m.getRows()) {
            list.add(SettingsForm.left(row(member)));
            list.add(DropTrackerTheme.gap(4));
        }
        if (m.getRows().isEmpty()) {
            String q = search.getText().trim();
            message(q.isEmpty() ? "No members yet. They appear once your WiseOldMan group syncs."
                : "No members match \"" + q + "\".");
        }
        footer.setText(m.getFooter() == null ? " " : m.getFooter());
        list.revalidate();
        list.repaint();
    }

    private JComponent row(GroupAdmin.Member member) {
        JPanel row = new JPanel(new BorderLayout(10, 0));
        row.setBackground(DropTrackerTheme.SURFACE_1);
        row.setBorder(DropTrackerTheme.cardBorder(6, 10, 6, 10));
        row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 44));

        JLabel rank = DropTrackerTheme.label("#" + member.getRank(), FontManager.getRunescapeSmallFont(), DropTrackerTheme.STONE);
        rank.setPreferredSize(new Dimension(34, 16));
        row.add(rank, BorderLayout.WEST);

        JPanel text = DropTrackerTheme.vbox(DropTrackerTheme.SURFACE_1);
        JLabel name = DropTrackerTheme.label(member.getName(), FontManager.getRunescapeFont(), DropTrackerTheme.TEXT);
        JLabel detail = DropTrackerTheme.label(member.getDetail(), FontManager.getRunescapeSmallFont(), DropTrackerTheme.TEXT_MUTED);
        text.add(name);
        text.add(detail);
        row.add(text, BorderLayout.CENTER);

        JLabel state = DropTrackerTheme.label(" ", FontManager.getRunescapeSmallFont(), DropTrackerTheme.TEXT_MUTED);
        ToggleSwitch[] toggle = new ToggleSwitch[1];
        Consumer<Boolean> paint = shown -> {
            state.setText(shown ? "On boards" : "Hidden");
            state.setForeground(shown ? DropTrackerTheme.TEXT_MUTED : DropTrackerTheme.EMBER);
            name.setForeground(shown ? DropTrackerTheme.TEXT : DropTrackerTheme.STONE);
        };
        toggle[0] = new ToggleSwitch(!member.isHidden(), () -> {
            boolean shown = toggle[0].isOn();
            paint.accept(shown);
            api.setHidden(playerName.get(), accountHash.getAsLong(), groupId.getAsInt(), member.getPlayerId(), !shown, r -> {
                if (r.value == null) {
                    // Put it back: the change didn't happen.
                    toggle[0].setOn(!shown);
                    paint.accept(!shown);
                    setNotice(r.error, DropTrackerTheme.RED);
                    if (r.needsCode) {
                        onNeedsCode.accept(r.error);
                    }
                }
            });
        });
        toggle[0].setToolTipText("Show " + member.getName() + " on your lootboard and leaderboards");
        paint.accept(!member.isHidden());
        JPanel east = new JPanel(new FlowLayout(FlowLayout.RIGHT, 8, 4));
        east.setOpaque(false);
        east.add(state);
        east.add(toggle[0]);
        row.add(east, BorderLayout.EAST);
        return row;
    }

    private void sync() {
        sync.setEnabled(false);
        sync.setText("Syncing...");
        api.womSync(playerName.get(), accountHash.getAsLong(), groupId.getAsInt(), r -> {
            sync.setEnabled(true);
            sync.setText("Sync from WiseOldMan");
            if (r.needsCode) {
                onNeedsCode.accept(r.error);
                return;
            }
            boolean good = r.value != null && "good".equals(r.value.getTone());
            setNotice(r.value != null ? r.value.getMessage() : r.error, good ? DropTrackerTheme.GREEN : DropTrackerTheme.EMBER);
            if (good) {
                load();
            }
        });
    }

    private void setNotice(String text, Color color) {
        notice.setText(text == null ? " " : text);
        notice.setForeground(color);
    }

    private void message(String text) {
        list.removeAll();
        list.add(SettingsForm.left(SettingsForm.wrapped(text, DropTrackerTheme.TEXT_MUTED)));
        list.revalidate();
        list.repaint();
    }
}

package io.droptracker.ui.admin;

import java.awt.*;
import java.util.*;
import java.util.List;
import java.util.regex.*;

import javax.annotation.Nullable;
import javax.swing.*;
import javax.swing.border.EmptyBorder;

import io.droptracker.DropTrackerConfig;
import io.droptracker.api.*;
import io.droptracker.models.api.GroupAdmin;
import io.droptracker.ui.DropTrackerTheme;
import io.droptracker.ui.components.PanelElements;
import net.runelite.api.Client;
import net.runelite.api.clan.*;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.ui.FontManager;
import net.runelite.client.util.LinkBrowser;

/**
 * Registers a group without leaving the game: a name and a WiseOldMan group
 * (one the leader has, or one made from their clan's member list), then one
 * trip through Discord to add the bot, which also proves they manage the
 * server. The window waits for that and opens the group manager.
 */
public final class RegisterWindow extends JPanel {

    private static final Pattern WOM_ID = Pattern.compile("(?:groups/)?(\\d{1,9})/?\\s*$");
    @Nullable
    private static JDialog openDialog;

    private final Client client;
    private final DropTrackerConfig config;
    private final GroupAdminApi api;
    private final CardLayout cards = new CardLayout();
    private final JTextField name = new JTextField();
    private final JRadioButton create = new JRadioButton();
    private final JRadioButton existing = new JRadioButton("I already have one:");
    private final JTextField womId = new JTextField();
    private final JLabel error = label(" ", DropTrackerTheme.RED);
    private final JButton next = DropTrackerTheme.button("Continue");
    private final JLabel waitTitle = bold(" ");
    private final JLabel waiting = label(" ", DropTrackerTheme.TEXT_MUTED);
    private final JLabel doneTitle = bold(" ");
    private final JComponent doneText = SettingsForm.wrapped(" ", DropTrackerTheme.TEXT_MUTED);
    private final JButton manage = DropTrackerTheme.button("Open group manager");
    private final javax.swing.Timer poll;

    private List<Map<String, String>> roster = new ArrayList<>();
    @Nullable
    private String id;
    private long deadline;
    private GroupAdmin.RegistrationStatus done;

    private RegisterWindow(Client client, DropTrackerConfig config, GroupAdminApi api) {
        this.client = client;
        this.config = config;
        this.api = api;
        setLayout(cards);
        setPreferredSize(new Dimension(440, 300));
        poll = new javax.swing.Timer(3000, e -> check());
        add(form(), "form");
        add(waitPage(), "wait");
        add(donePage(), "done");
    }

    /** Opens the window, or brings the open one forward. Call on the Swing thread. */
    public static void open(Client client, ClientThread clientThread, DropTrackerConfig config, GroupAdminApi api) {
        if (openDialog != null && openDialog.isDisplayable()) {
            openDialog.toFront();
            return;
        }
        RegisterWindow window = new RegisterWindow(client, config, api);
        JDialog dialog = new JDialog(PanelElements.getParentFrame(client), "DropTracker - Register your group", false);
        dialog.setContentPane(window);
        dialog.setDefaultCloseOperation(JDialog.DISPOSE_ON_CLOSE);
        dialog.addWindowListener(new java.awt.event.WindowAdapter() {
            @Override
            public void windowClosed(java.awt.event.WindowEvent e) {
                window.poll.stop();
                openDialog = null;
            }
        });
        dialog.pack();
        dialog.setLocationRelativeTo(dialog.getParent());
        openDialog = dialog;
        dialog.setVisible(true);
        clientThread.invoke(() -> {
            ClanSettings clan = client.getClanSettings();
            String clanName = clan != null ? clan.getName() : null;
            List<Map<String, String>> members = new ArrayList<>();
            if (clan != null) {
                for (ClanMember m : clan.getMembers()) {
                    ClanTitle title = clan.titleForRank(m.getRank());
                    Map<String, String> row = new HashMap<>();
                    row.put("name", m.getName());
                    row.put("rank", title != null ? title.getName() : "");
                    members.add(row);
                }
            }
            SwingUtilities.invokeLater(() -> window.clan(clanName, members));
        });
    }

    private void clan(@Nullable String clanName, List<Map<String, String>> members) {
        roster = members;
        if (name.getText().isEmpty() && clanName != null) {
            name.setText(clanName);
        }
        create.setText(members.isEmpty() ? "Make one from my clan (join your clan first)"
            : "Make one from my clan's " + GroupAdminWindow.plural(members.size(), "member"));
        create.setEnabled(!members.isEmpty());
        (members.isEmpty() ? existing : create).setSelected(true);
        womId.setEnabled(existing.isSelected());
    }

    private JComponent form() {
        JPanel page = page("Register your group",
            "Put your clan on the DropTracker from here. You'll add our bot to your clan's Discord at the end.");
        page.add(SettingsForm.left(label("Group name", DropTrackerTheme.TEXT)));
        name.setFont(FontManager.getRunescapeSmallFont());
        name.setMaximumSize(new Dimension(Integer.MAX_VALUE, 26));
        page.add(SettingsForm.left(name));
        page.add(DropTrackerTheme.gap(10));
        page.add(SettingsForm.left(label("WiseOldMan group (we sync your members from it)", DropTrackerTheme.TEXT)));
        ButtonGroup choice = new ButtonGroup();
        for (JRadioButton b : new JRadioButton[]{create, existing}) {
            choice.add(b);
            b.setOpaque(false);
            b.setFont(FontManager.getRunescapeSmallFont());
            b.setForeground(DropTrackerTheme.TEXT);
            b.addActionListener(e -> womId.setEnabled(existing.isSelected()));
        }
        clan(null, roster);
        page.add(SettingsForm.left(create));
        JPanel row = new JPanel(new BorderLayout(6, 0));
        row.setOpaque(false);
        row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 26));
        row.add(existing, BorderLayout.WEST);
        womId.setFont(FontManager.getRunescapeSmallFont());
        womId.putClientProperty("JTextField.placeholderText", "Group id or wiseoldman.net link");
        row.add(womId);
        page.add(SettingsForm.left(row));
        page.add(DropTrackerTheme.gap(10));
        page.add(SettingsForm.left(error));
        next.addActionListener(e -> start());
        return card(page, next);
    }

    private JComponent waitPage() {
        JPanel page = page(null, null);
        page.add(SettingsForm.left(waitTitle));
        page.add(SettingsForm.left(SettingsForm.wrapped("Your browser opens Discord. Pick your clan's server and "
            + "approve. You need Manage Server there. This window carries on by itself.", DropTrackerTheme.TEXT_MUTED)));
        page.add(DropTrackerTheme.gap(12));
        page.add(SettingsForm.left(waiting));
        JButton again = DropTrackerTheme.button("Open Discord again");
        again.addActionListener(e -> browse());
        return card(page, again);
    }

    private JComponent donePage() {
        JPanel page = page(null, null);
        page.add(SettingsForm.left(doneTitle));
        page.add(DropTrackerTheme.gap(6));
        page.add(SettingsForm.left(doneText));
        manage.addActionListener(e -> openManager());
        return card(page, manage);
    }

    private void start() {
        Integer wom = null;
        if (existing.isSelected()) {
            Matcher m = WOM_ID.matcher(womId.getText().trim());
            if (!m.find()) {
                error.setText("Enter your WiseOldMan group's id, or paste its link.");
                return;
            }
            wom = Integer.parseInt(m.group(1));
        }
        next.setEnabled(false);
        next.setText("Checking...");
        error.setText(" ");
        api.register(config.lastAccountName(), client.getAccountHash(), name.getText().trim(), wom,
            existing.isSelected() ? Collections.emptyList() : roster, r -> {
                next.setEnabled(true);
                next.setText("Continue");
                if (r.value == null || r.value.getId() == null || !r.value.getId().matches("[A-Za-z0-9_-]{16,40}")) {
                    error.setText(r.error == null ? " " : r.error);
                    return;
                }
                id = r.value.getId();
                deadline = System.currentTimeMillis() + 29 * 60_000L;
                waitTitle.setText("Add the bot to " + name.getText().trim() + "'s Discord");
                waiting.setText(r.value.getNote() != null ? r.value.getNote() + " Waiting for Discord..." : "Waiting for Discord...");
                cards.show(this, "wait");
                browse();
                poll.start();
            });
    }

    private void browse() {
        LinkBrowser.browse(DropTrackerUrls.web("api", "auth", "login").newBuilder()
            .addQueryParameter("bot", "1").addQueryParameter("redirect", "/register-group/" + id).build().toString());
    }

    private void check() {
        if (System.currentTimeMillis() > deadline) {
            poll.stop();
            finish("This took too long", "The registration expired. Close this window and start again.", false);
            return;
        }
        api.registration(config.lastAccountName(), client.getAccountHash(), id, r -> {
            if (r.value == null || "pending".equals(r.value.getStatus()) || !poll.isRunning()) {
                return;
            }
            poll.stop();
            done = r.value;
            boolean ok = "done".equals(done.getStatus());
            finish(ok ? done.getGroupName() + " is on the DropTracker" : "Not registered",
                done.getMessage() != null ? done.getMessage()
                    : "Your members are syncing from WiseOldMan. Next, pick the channels your clan's "
                    + "drops and achievements go to.", ok && api.hasSession(done.getGroupId()));
        });
    }

    private void finish(String title, String text, boolean canManage) {
        doneTitle.setText(title);
        ((JTextArea) doneText).setText(text);
        manage.setVisible(canManage);
        cards.show(this, "done");
    }

    private void openManager() {
        api.groups(config.lastAccountName(), client.getAccountHash(), r -> {
            if (r.value != null) {
                Window self = SwingUtilities.getWindowAncestor(this);
                GroupAdminWindow.open(client, config, api, r.value.getGroups(), done.getGroupId());
                self.dispose();
            }
        });
    }

    /** A step: its content at the top, its action at the bottom left. */
    private static JPanel card(JComponent content, JComponent action) {
        JPanel card = new JPanel(new BorderLayout());
        card.setBackground(DropTrackerTheme.SURFACE_0);
        card.setBorder(new EmptyBorder(16, 18, 16, 18));
        card.add(content, BorderLayout.NORTH);
        JPanel south = new JPanel(new FlowLayout(FlowLayout.LEFT, 0, 0));
        south.setOpaque(false);
        south.add(action);
        card.add(south, BorderLayout.SOUTH);
        return card;
    }

    private static JPanel page(@Nullable String title, @Nullable String intro) {
        JPanel page = DropTrackerTheme.vbox(DropTrackerTheme.SURFACE_0);
        if (title != null) {
            page.add(SettingsForm.left(bold(title)));
        }
        if (intro != null) {
            page.add(SettingsForm.left(SettingsForm.wrapped(intro, DropTrackerTheme.TEXT_MUTED)));
            page.add(DropTrackerTheme.gap(12));
        }
        return page;
    }

    private static JLabel bold(String text) {
        return DropTrackerTheme.label(text, FontManager.getRunescapeBoldFont(), DropTrackerTheme.GOLD);
    }

    private static JLabel label(String text, Color color) {
        return DropTrackerTheme.label(text, FontManager.getRunescapeSmallFont(), color);
    }

    private static JButton button(String text) {
        JButton b = DropTrackerTheme.button(text);
        return b;
    }
}

package io.droptracker.ui.admin;

import java.awt.*;
import java.util.*;
import java.util.List;
import java.util.function.Supplier;

import javax.annotation.Nullable;
import javax.swing.*;
import javax.swing.border.*;
import javax.swing.event.*;
import javax.swing.text.JTextComponent;

import com.google.gson.*;

import io.droptracker.models.api.GroupAdmin;
import io.droptracker.ui.DropTrackerTheme;
import io.droptracker.ui.components.PanelElements;
import net.runelite.client.ui.FontManager;

/**
 * One settings category, drawn from the server's field list.
 *
 * <p>Each field becomes a row: name and help on the left, a control on the
 * right. Only the types in {@link GroupAdmin#KNOWN_TYPES} get a control; any
 * other type, and anything the server marks locked, is shown read-only. A
 * changed row gets a gold edge, and {@link #changes()} holds exactly the rows
 * whose value differs from what the server sent.
 */
public class SettingsForm extends JPanel implements Scrollable {

    private static final int CONTROL_WIDTH = 210;

    private final List<Row> rows = new ArrayList<>();
    private final Runnable onDirty;

    SettingsForm(GroupAdmin.Settings settings, GroupAdmin.Category category, Runnable onDirty, Runnable openWebsite) {
        this.onDirty = onDirty;
        setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
        setBackground(DropTrackerTheme.SURFACE_0);
        setBorder(new EmptyBorder(14, 16, 14, 16));

        add(left(DropTrackerTheme.label(category.getLabel(), FontManager.getRunescapeBoldFont(), DropTrackerTheme.GOLD)));
        if (category.getHelp() != null) {
            add(left(wrapped(category.getHelp(), DropTrackerTheme.TEXT_MUTED)));
        }
        add(DropTrackerTheme.gap(10));

        for (GroupAdmin.Field field : settings.getFields()) {
            if (category.getKey().equals(field.getCategory())) {
                Row row = new Row(field, settings, openWebsite);
                rows.add(row);
                add(left(row.panel));
                add(DropTrackerTheme.gap(6));
            }
        }
        if (rows.isEmpty()) {
            add(left(wrapped("Nothing to set here yet.", DropTrackerTheme.TEXT_MUTED)));
        }
    }

    /** Changed keys and their new values, ready to send. */
    Map<String, Object> changes() {
        Map<String, Object> changes = new LinkedHashMap<>();
        for (Row row : rows) {
            if (row.dirty()) {
                JsonElement value = row.read.get();
                changes.put(row.field.getKey(), value == null || value.isJsonNull() ? null : value);
            }
        }
        return changes;
    }

    int dirtyCount() {
        int n = 0;
        for (Row row : rows) {
            n += row.dirty() ? 1 : 0;
        }
        return n;
    }

    /** False while a number is out of range: Save stays off until it's fixed. */
    boolean valid() {
        for (Row row : rows) {
            if ("int".equals(row.field.getType()) && intIssue(row.read.get(), row.field) != null) {
                return false;
            }
        }
        return true;
    }

    /** Shows the server's per-key problems under the rows they belong to. */
    void showErrors(Map<String, String> errors) {
        for (Row row : rows) {
            row.setError(errors.get(row.field.getKey()));
        }
    }

    // Scrollable: track the viewport's width so help text wraps instead of
    // widening the form.
    @Override
    public Dimension getPreferredScrollableViewportSize() {
        return getPreferredSize();
    }

    @Override
    public int getScrollableUnitIncrement(Rectangle r, int orientation, int direction) {
        return 16;
    }

    @Override
    public int getScrollableBlockIncrement(Rectangle r, int orientation, int direction) {
        return r.height - 32;
    }

    @Override
    public boolean getScrollableTracksViewportWidth() {
        return true;
    }

    @Override
    public boolean getScrollableTracksViewportHeight() {
        return false;
    }

    /** One setting: its labels, its control, and how to read the control back. */
    private final class Row {
        final GroupAdmin.Field field;
        final JPanel panel = new JPanel(new BorderLayout(12, 0));
        final JLabel error = DropTrackerTheme.label(" ", FontManager.getRunescapeSmallFont(), DropTrackerTheme.RED);
        Supplier<JsonElement> read;
        String baseline;

        Row(GroupAdmin.Field field, GroupAdmin.Settings settings, Runnable openWebsite) {
            this.field = field;
            panel.setBackground(DropTrackerTheme.SURFACE_1);

            JPanel text = DropTrackerTheme.vbox(DropTrackerTheme.SURFACE_1);
            JPanel title = new JPanel(new FlowLayout(FlowLayout.LEFT, 0, 0));
            title.setOpaque(false);
            title.add(DropTrackerTheme.label(field.getLabel() == null ? field.getKey() : field.getLabel(),
                FontManager.getRunescapeFont(), DropTrackerTheme.TEXT));
            if (field.isLocked()) {
                title.add(Box.createRigidArea(new Dimension(6, 0)));
                title.add(DropTrackerTheme.chip("Locked", DropTrackerTheme.EMBER));
            }
            text.add(left(title));
            if (field.getHelp() != null && !field.getHelp().isEmpty()) {
                text.add(left(wrapped(field.getHelp(), DropTrackerTheme.TEXT_MUTED)));
            }
            if (field.isLocked() && field.getLockedReason() != null) {
                text.add(left(wrapped(field.getLockedReason(), DropTrackerTheme.EMBER)));
            }
            error.setVisible(false);
            text.add(left(error));
            panel.add(text, BorderLayout.CENTER);

            JComponent control = control(field, settings, openWebsite);
            JPanel east = new JPanel(new GridBagLayout());
            east.setOpaque(false);
            east.add(control);
            panel.add(east, BorderLayout.EAST);

            baseline = String.valueOf(read.get());
            paintEdge();
        }

        boolean dirty() {
            return !baseline.equals(String.valueOf(read.get()));
        }

        void changed() {
            setError(null);
            paintEdge();
            onDirty.run();
        }

        void setError(@Nullable String message) {
            error.setText(message == null ? " " : message);
            error.setVisible(message != null);
            panel.revalidate();
        }

        /** A gold edge on a changed row, so a leader sees what Save will send. */
        private void paintEdge() {
            boolean dirty = dirty();
            panel.setBorder(new CompoundBorder(
                new MatteBorder(0, 3, 0, 0, dirty ? DropTrackerTheme.GOLD : DropTrackerTheme.SURFACE_0),
                new CompoundBorder(BorderFactory.createLineBorder(dirty ? DropTrackerTheme.BRONZE : DropTrackerTheme.SURFACE_3),
                    new EmptyBorder(8, 10, 8, 10))));
        }

        private JComponent control(GroupAdmin.Field field, GroupAdmin.Settings settings, Runnable openWebsite) {
            JsonElement value = field.getValue();
            String type = field.getType() == null ? "" : field.getType();
            if (!GroupAdmin.KNOWN_TYPES.contains(type)) {
                read = () -> value;
                JButton web = DropTrackerTheme.button("Edit on website");
                web.addActionListener(e -> openWebsite.run());
                return web;
            }
            JComponent control;
            switch (type) {
                case "boolean": {
                    ToggleSwitch toggle = new ToggleSwitch(asBoolean(value), this::changed);
                    read = () -> new JsonPrimitive(toggle.isOn());
                    control = toggle;
                    break;
                }
                case "select":
                case "channel":
                case "role": {
                    List<GroupAdmin.Choice> choices = "select".equals(type) ? field.getOptions()
                        : "channel".equals(type) ? settings.getChannels() : settings.getRoles();
                    JComboBox<GroupAdmin.Choice> box = choiceBox(choices, asString(value), !"select".equals(type), type);
                    box.addActionListener(e -> changed());
                    read = () -> {
                        GroupAdmin.Choice choice = (GroupAdmin.Choice) box.getSelectedItem();
                        return choice == null || choice.getValue() == null ? JsonNull.INSTANCE
                            : new JsonPrimitive(choice.getValue());
                    };
                    control = box;
                    break;
                }
                case "int": {
                    JTextField input = textField(grouped(asString(value)));
                    input.setHorizontalAlignment(JTextField.RIGHT);
                    read = () -> {
                        String digits = input.getText().replaceAll("[,\\s]", "");
                        if (digits.isEmpty()) {
                            return JsonNull.INSTANCE;
                        }
                        try {
                            return new JsonPrimitive(Long.parseLong(digits));
                        } catch (NumberFormatException e) {
                            return new JsonPrimitive(input.getText());
                        }
                    };
                    listen(input, () -> {
                        changed();
                        setError(intIssue(read.get(), field));
                    });
                    control = input;
                    break;
                }
                case "multi": {
                    Set<String> chosen = new LinkedHashSet<>();
                    if (value != null && value.isJsonArray()) {
                        value.getAsJsonArray().forEach(v -> chosen.add(v.getAsString()));
                    }
                    JButton pick = DropTrackerTheme.button(" ");
                    pick.setHorizontalAlignment(SwingConstants.LEFT);
                    pick.setPreferredSize(new Dimension(CONTROL_WIDTH, 26));
                    Runnable label = () -> {
                        List<String> names = chosenLabels(field.getOptions(), chosen);
                        pick.setText(names.isEmpty() ? "None chosen" : names.size() == 1 ? names.get(0)
                            : names.get(0) + " +" + (names.size() - 1) + " more");
                        pick.setToolTipText("<html>" + (names.isEmpty() ? "" : PanelElements.escapeHtml(String.join(", ", names)) + "<br>")
                            + "Click to choose</html>");
                    };
                    label.run();
                    pick.addActionListener(e -> ChecklistDialog.open(pick, field.getLabel(), field.getOptions(), chosen,
                        picked -> {
                            chosen.clear();
                            chosen.addAll(picked);
                            label.run();
                            changed();
                        }));
                    read = () -> {
                        // Option order, then anything chosen that's no longer offered.
                        Set<String> ordered = new LinkedHashSet<>();
                        field.getOptions().stream().map(GroupAdmin.Choice::getValue).filter(chosen::contains)
                            .forEach(ordered::add);
                        ordered.addAll(chosen);
                        JsonArray out = new JsonArray();
                        ordered.forEach(out::add);
                        return out;
                    };
                    control = pick;
                    break;
                }
                case "text": {
                    JTextArea area = new JTextArea(asString(value), 3, 18);
                    area.setLineWrap(true);
                    area.setWrapStyleWord(true);
                    style(area);
                    read = () -> new JsonPrimitive(area.getText());
                    listen(area, this::changed);
                    JScrollPane scroll = new JScrollPane(area);
                    scroll.setBorder(BorderFactory.createLineBorder(DropTrackerTheme.SURFACE_3, 1));
                    int lines = asString(value).split("\n", -1).length;
                    scroll.setPreferredSize(new Dimension(CONTROL_WIDTH, lines > 3 ? Math.min(160, 16 * lines + 16) : 64));
                    control = scroll;
                    break;
                }
                default: {
                    JTextField input = textField(asString(value));
                    read = () -> new JsonPrimitive(input.getText());
                    listen(input, this::changed);
                    control = input;
                }
            }
            if (field.isLocked()) {
                control.setEnabled(false);
                control.setToolTipText(field.getLockedReason());
            }
            return control;
        }
    }

    /** Labels of the chosen options, in option order; a value no longer offered shows as itself. */
    static List<String> chosenLabels(List<GroupAdmin.Choice> options, Set<String> chosen) {
        List<String> names = new ArrayList<>();
        Set<String> left = new LinkedHashSet<>(chosen);
        for (GroupAdmin.Choice c : options) {
            if (left.remove(c.getValue())) {
                names.add(c.getLabel() == null ? c.getValue() : c.getLabel());
            }
        }
        names.addAll(left);
        return names;
    }

    /** "Must be at least 0", or null when the number is fine (or empty). */
    @Nullable
    static String intIssue(JsonElement value, GroupAdmin.Field field) {
        if (value == null || value.isJsonNull()) {
            return null;
        }
        long n;
        try {
            n = value.getAsLong();
        } catch (NumberFormatException e) {
            return "Numbers only.";
        }
        if (field.getMin() != null && n < field.getMin()) {
            return "Must be at least " + String.format("%,d", field.getMin()) + ".";
        }
        if (field.getMax() != null && n > field.getMax()) {
            return "Must be at most " + String.format("%,d", field.getMax()) + ".";
        }
        return null;
    }

    /** "2500000" as "2,500,000": GP thresholds are unreadable without commas. */
    static String grouped(String digits) {
        try {
            return String.format("%,d", Long.parseLong(digits.trim()));
        } catch (NumberFormatException e) {
            return digits;
        }
    }

    static boolean asBoolean(@Nullable JsonElement value) {
        String s = asString(value).trim().toLowerCase(Locale.ROOT);
        return s.equals("true") || s.equals("1") || s.equals("yes");
    }

    static String asString(@Nullable JsonElement value) {
        if (value == null || value.isJsonNull()) {
            return "";
        }
        return value.isJsonPrimitive() ? value.getAsString() : value.toString();
    }

    private static JComboBox<GroupAdmin.Choice> choiceBox(List<GroupAdmin.Choice> choices, String current,
                                                          boolean allowNone, String type) {
        JComboBox<GroupAdmin.Choice> box = new JComboBox<>();
        if (allowNone) {
            box.addItem(new GroupAdmin.Choice(null, "None", null));
        }
        GroupAdmin.Choice selected = null;
        for (GroupAdmin.Choice c : choices) {
            box.addItem(c);
            if (c.getValue() != null && c.getValue().equals(current)) {
                selected = c;
            }
        }
        if (selected == null && !current.isEmpty()) {
            // A channel or role the bot can't see any more: keep it, but say so.
            selected = new GroupAdmin.Choice(current, "Unknown " + type + " (" + current + ")", null);
            box.addItem(selected);
        }
        box.setSelectedItem(selected != null ? selected : box.getItemCount() > 0 ? box.getItemAt(0) : null);
        box.setPreferredSize(new Dimension(CONTROL_WIDTH, box.getPreferredSize().height));
        box.setBackground(DropTrackerTheme.SURFACE_2);
        box.setForeground(DropTrackerTheme.TEXT);
        box.setFont(FontManager.getRunescapeSmallFont());
        String prefix = "channel".equals(type) ? "#" : "role".equals(type) ? "@" : "";
        box.setRenderer(new DefaultListCellRenderer() {
            @Override
            public Component getListCellRendererComponent(JList<?> list, Object item, int index, boolean selected,
                                                          boolean focus) {
                super.getListCellRendererComponent(list, item, index, selected, focus);
                GroupAdmin.Choice c = (GroupAdmin.Choice) item;
                if (c != null) {
                    String label = c.getLabel() == null ? c.getValue() : c.getLabel();
                    // Only real channels/roles get a # or @; "None" and a lost id don't.
                    String name = choices.contains(c) ? prefix + label : label;
                    // Channel categories trail in muted text inside the list only.
                    setText(index >= 0 && c.getGroup() != null
                        ? "<html>" + PanelElements.escapeHtml(name) + " <font color='#9a8a6a'>" + PanelElements.escapeHtml(c.getGroup()) + "</font></html>"
                        : name);
                }
                setFont(FontManager.getRunescapeSmallFont());
                setBackground(selected ? DropTrackerTheme.SURFACE_3 : DropTrackerTheme.SURFACE_2);
                setForeground(selected ? DropTrackerTheme.GOLD_BRIGHT : DropTrackerTheme.TEXT);
                return this;
            }
        });
        return box;
    }

    private static JTextField textField(String text) {
        JTextField input = new JTextField(text);
        style(input);
        input.setBorder(BorderFactory.createCompoundBorder(
            BorderFactory.createLineBorder(DropTrackerTheme.SURFACE_3, 1), new EmptyBorder(4, 6, 4, 6)));
        input.setPreferredSize(new Dimension(CONTROL_WIDTH, input.getPreferredSize().height));
        return input;
    }

    private static void style(JTextComponent c) {
        c.setBackground(DropTrackerTheme.SURFACE_2);
        c.setForeground(DropTrackerTheme.TEXT);
        c.setCaretColor(DropTrackerTheme.GOLD_BRIGHT);
        c.setFont(FontManager.getRunescapeSmallFont());
    }

    public static void listen(JTextComponent c, Runnable onChange) {
        c.getDocument().addDocumentListener(new DocumentListener() {
            @Override
            public void insertUpdate(DocumentEvent e) {
                onChange.run();
            }

            @Override
            public void removeUpdate(DocumentEvent e) {
                onChange.run();
            }

            @Override
            public void changedUpdate(DocumentEvent e) {
            }
        });
    }

    public static JComponent wrapped(String text, Color color) {
        JTextArea area = new JTextArea(text);
        area.setLineWrap(true);
        area.setWrapStyleWord(true);
        area.setEditable(false);
        area.setFocusable(false);
        area.setOpaque(false);
        area.setForeground(color);
        area.setFont(FontManager.getRunescapeSmallFont());
        area.setBorder(new EmptyBorder(2, 0, 0, 0));
        return area;
    }

    public static JComponent left(JComponent c) {
        c.setAlignmentX(Component.LEFT_ALIGNMENT);
        return c;
    }

}

package io.droptracker.ui.admin;

import java.awt.*;
import java.awt.event.*;

import javax.swing.*;

import io.droptracker.ui.DropTrackerTheme;

/** A painted on/off switch: clearer than a checkbox for a settings row. */
class ToggleSwitch extends JComponent {

    private static final int W = 34;
    private static final int H = 18;

    private boolean on;
    private final Runnable onChange;

    ToggleSwitch(boolean on, Runnable onChange) {
        this.on = on;
        this.onChange = onChange;
        setPreferredSize(new Dimension(W, H));
        setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        setFocusable(true);
        addMouseListener(new MouseAdapter() {
            @Override
            public void mouseClicked(MouseEvent e) {
                toggle();
            }
        });
        addKeyListener(new KeyAdapter() {
            @Override
            public void keyPressed(KeyEvent e) {
                if (e.getKeyCode() == KeyEvent.VK_SPACE) {
                    toggle();
                }
            }
        });
    }

    boolean isOn() {
        return on;
    }

    void setOn(boolean on) {
        this.on = on;
        repaint();
    }

    private void toggle() {
        if (isEnabled()) {
            setOn(!on);
            onChange.run();
        }
    }

    @Override
    protected void paintComponent(Graphics g) {
        Graphics2D g2 = (Graphics2D) g.create();
        g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        int y = (getHeight() - H) / 2;
        Color track = on ? DropTrackerTheme.GOLD : DropTrackerTheme.SURFACE_3;
        g2.setColor(isEnabled() ? track : track.darker());
        g2.fillRoundRect(0, y, W, H, H, H);
        g2.setColor(on ? DropTrackerTheme.SURFACE_0 : DropTrackerTheme.TEXT_MUTED);
        g2.fillOval(on ? W - H + 3 : 3, y + 3, H - 6, H - 6);
        if (isFocusOwner()) {
            g2.setColor(DropTrackerTheme.GOLD_BRIGHT);
            g2.drawRoundRect(0, y, W - 1, H - 1, H, H);
        }
        g2.dispose();
    }
}

package io.droptracker.ui.components;

import java.awt.event.*;

import javax.annotation.Nullable;
import javax.swing.*;

import io.droptracker.DropTrackerConfig;
import io.droptracker.api.DeathMessageApi;
import net.runelite.api.Client;

/**
 * The window around {@link DeathMessageEditor}, opened from the Extras tab.
 * One at a time: a second click brings the open one forward.
 */
public final class DeathMessageDialog {

    @Nullable
    private static JDialog openDialog;

    private DeathMessageDialog() {
    }

    /** Opens the editor (or brings the open one forward). Call on the Swing thread. */
    public static void open(Client client, DropTrackerConfig config, DeathMessageApi api) {
        if (openDialog != null && openDialog.isDisplayable()) {
            openDialog.toFront();
            return;
        }
        JFrame parent = PanelElements.getParentFrame(client);
        JDialog dialog = new JDialog(parent, "DropTracker - Your messages", false);
        dialog.setDefaultCloseOperation(JDialog.DISPOSE_ON_CLOSE);

        DeathMessageEditor editor = new DeathMessageEditor(
            api, client::getAccountHash, config::lastAccountName, dialog::dispose, dialog::pack);
        dialog.setContentPane(editor);
        dialog.addWindowListener(new WindowAdapter() {
            @Override
            public void windowClosed(WindowEvent e) {
                editor.markClosed();
                if (openDialog == dialog) {
                    openDialog = null;
                }
            }
        });
        dialog.pack();
        dialog.setLocationRelativeTo(parent);
        openDialog = dialog;
        dialog.setVisible(true);
        editor.load();
    }
}

package io.droptracker.ui.components;

import java.awt.*;
import java.awt.event.*;
import java.util.*;
import java.util.List;
import java.util.function.*;

import javax.annotation.Nullable;
import javax.swing.*;
import javax.swing.border.EmptyBorder;
import javax.swing.text.BadLocationException;

import io.droptracker.api.*;
import io.droptracker.models.api.DeathMessages;
import io.droptracker.ui.DropTrackerTheme;
import io.droptracker.util.DeathMessageRules;
import net.runelite.client.ui.FontManager;
import net.runelite.client.util.LinkBrowser;

/**
 * The member message editor itself: a message type, five boxes, placeholders,
 * a preview, and where the message is posted. {@link DeathMessageDialog} puts
 * it in a window.
 *
 * <p>What the member writes here is what their clan sees when they die, log a
 * collection log slot, get a drop or set a personal best — in every clan whose
 * leaders let members write their own. Each type has its own placeholders,
 * which come from the server with its messages. The same messages are
 * on the website and in Discord's {@code /settings}, so this is a view onto the
 * server's copy, never a local one: it loads on open and saves straight back.
 * Nothing here is a RuneLite config item, which would be per profile rather
 * than per account and a second copy to disagree with the server's.
 */
public class DeathMessageEditor extends JPanel {

    static final int WIDTH = 390;
    private static final String[] TYPES = {"death", "clog", "drop", "pb"};

    private final DeathMessageApi api;
    private final LongSupplier accountHash;
    private final Supplier<String> playerNameSupplier;
    private final Runnable onClose;
    private final Runnable onResize;

    private final List<JTextField> fields = new ArrayList<>();
    private final JLabel groupsLabel = new JLabel(" ");
    private final JLabel previewLabel = new JLabel(" ");
    private final JLabel statusLabel = new JLabel(" ");
    private final JButton saveButton = new JButton("Save");
    private final JPanel tokenPanel = new JPanel(new GridLayout(0, 2, 4, 4));
    private final JComboBox<String> typeBox = new JComboBox<>(
        new String[]{"Deaths", "Collection logs", "Drops", "Personal bests"});

    private JTextField lastFocused;
    private long hash = -1;
    @Nullable
    private String playerName;
    private List<String> savedMessages = new ArrayList<>();
    private Map<String, String> samples = new HashMap<>();
    private String type = TYPES[0];
    private List<String> shownTokens = DeathMessageRules.TOKENS;
    private Map<String, String> aliases = DeathMessageRules.ALIASES;
    private Set<String> allowed = DeathMessageRules.allowed(shownTokens, aliases);
    private boolean busy;
    private boolean closed;

    /**
     * @param onClose  what "Close" does (dispose the window)
     * @param onResize called after the content changes size (re-pack the window)
     */
    public DeathMessageEditor(DeathMessageApi api, LongSupplier accountHash, Supplier<String> playerName,
                              Runnable onClose, Runnable onResize) {
        this.api = api;
        this.accountHash = accountHash;
        this.playerNameSupplier = playerName;
        this.onClose = onClose;
        this.onResize = onResize;
        build();
    }

    /** Loads the server's copy for the logged-in account. */
    public void load() {
        hash = accountHash.getAsLong();
        playerName = playerNameSupplier.get();
        if (hash == -1) {
            showStatus("Log in first: your messages belong to the account you're playing.",
                DropTrackerTheme.EMBER);
            return;
        }
        busy = true;
        setEditable(false);
        showStatus("Loading...", DropTrackerTheme.TEXT_MUTED);
        String requested = type;
        api.fetch(playerName, hash, requested, result -> {
            if (closed || !requested.equals(type)) {
                return;
            }
            busy = false;
            if (result.messages == null) {
                showStatus(result.error, DropTrackerTheme.RED);
                return;
            }
            apply(result.messages);
            setEditable(true);
            showStatus(" ", DropTrackerTheme.TEXT_MUTED);
            refresh();
        });
    }

    /** Stops late answers from touching a closed window. */
    public void markClosed() {
        closed = true;
    }

    private void build() {
        setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
        setBackground(DropTrackerTheme.SURFACE_0);
        setBorder(new EmptyBorder(10, 12, 10, 12));

        JLabel title = DropTrackerTheme.label("Your messages", FontManager.getRunescapeBoldFont(), DropTrackerTheme.GOLD);
        add(row(title));

        add(row(wrapped(
            "Write what your clan sees for your deaths, collection logs, drops and personal bests. One of "
                + "your messages is picked at random each time, in every clan whose leaders let members write "
                + "their own. Also on the DropTracker website and /settings in Discord.")));
        add(DropTrackerTheme.gap(6));
        typeBox.addActionListener(e -> {
            String picked = TYPES[Math.max(0, typeBox.getSelectedIndex())];
            if (!picked.equals(type)) {
                type = picked;
                load();
            }
        });
        add(row(typeBox));
        add(DropTrackerTheme.gap(6));

        groupsLabel.setFont(FontManager.getRunescapeSmallFont());
        groupsLabel.setForeground(DropTrackerTheme.TEXT_MUTED);
        add(row(groupsLabel));
        add(DropTrackerTheme.gap(6));

        JPanel rows = new JPanel(new GridLayout(DeathMessageRules.MAX_MESSAGES, 1, 0, 4));
        rows.setBackground(DropTrackerTheme.SURFACE_0);
        for (int i = 0; i < DeathMessageRules.MAX_MESSAGES; i++) {
            JTextField field = new JTextField();
            // A fixed width: a text field's preferred width follows its text,
            // so a long message would otherwise widen the whole window.
            field.setPreferredSize(new Dimension(WIDTH - 24, field.getPreferredSize().height));
            field.setToolTipText("Message " + (i + 1) + " - leave blank if you don't need it");
            io.droptracker.ui.admin.SettingsForm.listen(field, this::refresh);
            field.addFocusListener(new FocusAdapter() {
                @Override
                public void focusGained(FocusEvent e) {
                    lastFocused = field;
                    refresh();
                }
            });
            fields.add(field);
            rows.add(field);
        }
        lastFocused = fields.get(0);
        add(row(rows));
        add(DropTrackerTheme.gap(6));

        JLabel tokensTitle = DropTrackerTheme.label("Click a placeholder to add it:", FontManager.getRunescapeSmallFont(), DropTrackerTheme.TEXT_MUTED);
        add(row(tokensTitle));
        tokenPanel.setBackground(DropTrackerTheme.SURFACE_0);
        setTokens(DeathMessageRules.TOKENS);
        add(row(tokenPanel));
        add(DropTrackerTheme.gap(6));

        previewLabel.setFont(FontManager.getRunescapeSmallFont());
        previewLabel.setForeground(DropTrackerTheme.TEXT);
        add(row(previewLabel));
        statusLabel.setFont(FontManager.getRunescapeSmallFont());
        add(row(statusLabel));
        add(DropTrackerTheme.gap(8));

        JPanel buttons = new JPanel(new BorderLayout());
        buttons.setBackground(DropTrackerTheme.SURFACE_0);
        JPanel leftButtons = new JPanel(new FlowLayout(FlowLayout.LEFT, 0, 0));
        leftButtons.setBackground(DropTrackerTheme.SURFACE_0);
        DropTrackerTheme.styleButton(saveButton);
        saveButton.addActionListener(e -> save());
        JButton close = DropTrackerTheme.button("Close");
        close.addActionListener(e -> onClose.run());
        leftButtons.add(saveButton);
        leftButtons.add(Box.createRigidArea(new Dimension(6, 0)));
        leftButtons.add(close);
        buttons.add(leftButtons, BorderLayout.WEST);
        JButton website = DropTrackerTheme.button("Open website");
        website.setToolTipText("Edit your messages on the DropTracker website");
        website.addActionListener(e -> LinkBrowser.browse(DropTrackerUrls.web("settings").toString()));
        buttons.add(website, BorderLayout.EAST);
        add(row(buttons));

        setEditable(false);
    }

    private void save() {
        List<String> rows = rows();
        String issue = DeathMessageRules.listIssue(rows, allowed, shownTokens);
        if (issue != null) {
            showStatus(issue, DropTrackerTheme.RED);
            return;
        }
        List<String> messages = DeathMessageRules.normalize(rows);
        busy = true;
        setEditable(false);
        showStatus("Saving...", DropTrackerTheme.TEXT_MUTED);
        String requested = type;
        api.save(playerName, hash, requested, messages, result -> {
            busy = false;
            if (closed || !requested.equals(type)) {
                return;
            }
            setEditable(true);
            if (result.messages == null) {
                refresh();
                showStatus(result.error, DropTrackerTheme.RED);
                return;
            }
            apply(result.messages);
            refresh();
            showStatus(messages.isEmpty() ? "Cleared. Your clans will use their own message."
                : "Saved.", DropTrackerTheme.GREEN);
        });
    }

    /** Puts the server's copy into the boxes, the groups line and the samples. */
    private void apply(DeathMessages loaded) {
        if (loaded.getPlayerName() != null) {
            playerName = loaded.getPlayerName();
        }
        savedMessages = new ArrayList<>(DeathMessageRules.normalize(loaded.getMessages()));
        for (int i = 0; i < fields.size(); i++) {
            fields.get(i).setText(i < savedMessages.size() ? savedMessages.get(i) : "");
        }
        samples = new HashMap<>();
        List<String> tokens = new ArrayList<>();
        for (DeathMessages.Token token : loaded.getTokens()) {
            if (token.getToken() == null) {
                continue;
            }
            tokens.add(token.getToken());
            samples.put(token.getToken(), token.getSample() == null ? "" : token.getSample());
        }
        shownTokens = tokens.isEmpty() ? DeathMessageRules.TOKENS : tokens;
        aliases = loaded.getAliases().isEmpty() && TYPES[0].equals(type) ? DeathMessageRules.ALIASES : loaded.getAliases();
        allowed = DeathMessageRules.allowed(shownTokens, aliases);
        setTokens(shownTokens);
        groupsLabel.setText(groupsText(loaded.getGroups()));
        onResize.run();
    }

    /** Re-validates after any edit: the preview, the problem line and the Save button. */
    private void refresh() {
        if (busy) {
            return;
        }
        List<String> rows = rows();
        String issue = DeathMessageRules.listIssue(rows, allowed, shownTokens);
        boolean changed = !DeathMessageRules.normalize(rows).equals(savedMessages);
        saveButton.setEnabled(issue == null && changed && hash != -1 && fields.get(0).isEditable());

        String source = lastFocused != null && !lastFocused.getText().trim().isEmpty()
            ? lastFocused.getText() : firstNonBlank(rows);
        if (issue == null && source != null) {
            previewLabel.setText(html("Example: " + escape(DeathMessageRules.preview(source, samples, aliases, playerName))));
        } else {
            previewLabel.setText(" ");
        }
        if (issue != null) {
            showStatus(issue, DropTrackerTheme.RED);
        } else if (changed) {
            showStatus("Unsaved changes.", DropTrackerTheme.TEXT_MUTED);
        } else if (DropTrackerTheme.RED.equals(statusLabel.getForeground())) {
            showStatus(" ", DropTrackerTheme.TEXT_MUTED);
        }
    }

    private void insertToken(String token) {
        JTextField target = lastFocused != null ? lastFocused : fields.get(0);
        if (!target.isEditable()) {
            return;
        }
        String text = target.getText();
        int caret = Math.max(0, Math.min(target.getCaretPosition(), text.length()));
        boolean needsSpace = caret > 0 && !Character.isWhitespace(text.charAt(caret - 1));
        try {
            target.getDocument().insertString(caret, (needsSpace ? " " : "") + token, null);
        } catch (BadLocationException e) {
            target.setText(text + (needsSpace ? " " : "") + token);
        }
        target.requestFocusInWindow();
    }

    private void setTokens(List<String> tokens) {
        tokenPanel.removeAll();
        boolean editable = !fields.isEmpty() && fields.get(0).isEditable();
        for (String token : tokens) {
            JButton button = DropTrackerTheme.button(token);
            button.setEnabled(editable);
            button.addActionListener(e -> insertToken(token));
            tokenPanel.add(button);
        }
        tokenPanel.revalidate();
    }

    private void setEditable(boolean editable) {
        for (JTextField field : fields) {
            field.setEditable(editable);
        }
        for (Component c : tokenPanel.getComponents()) {
            c.setEnabled(editable);
        }
        saveButton.setEnabled(false);
    }

    private List<String> rows() {
        List<String> rows = new ArrayList<>();
        for (JTextField field : fields) {
            rows.add(field.getText());
        }
        return rows;
    }

    private void showStatus(@Nullable String text, Color color) {
        statusLabel.setText(text == null || text.trim().isEmpty() ? " " : html(escape(text)));
        statusLabel.setForeground(color);
    }

    // Package-private views for the tests.

    List<JTextField> fields() {
        return fields;
    }

    JButton saveButton() {
        return saveButton;
    }

    String statusText() {
        return statusLabel.getText();
    }

    String previewText() {
        return previewLabel.getText();
    }

    String groupsLabelText() {
        return groupsLabel.getText();
    }

    void clickToken(String token) {
        insertToken(token);
    }

    void clickSave() {
        save();
    }

    /** "Posted in: Clan A, Clan B (not switched on)" — where the message goes, and where not. */
    static String groupsText(List<DeathMessages.Group> groups) {
        if (groups == null || groups.isEmpty()) {
            return html("This account isn't in any clans on the DropTracker yet.");
        }
        StringBuilder sb = new StringBuilder("Posted in: ");
        for (int i = 0; i < groups.size(); i++) {
            DeathMessages.Group group = groups.get(i);
            if (i > 0) {
                sb.append(", ");
            }
            String name = escape(group.getName() == null ? "Group " + group.getId() : group.getName());
            if (group.isBlocked()) {
                sb.append(colored(name + " (blocked by its leaders)", DropTrackerTheme.RED));
            } else if (group.isAllowed()) {
                sb.append(colored(name, DropTrackerTheme.GREEN));
            } else {
                sb.append(colored(name + " (not switched on)", DropTrackerTheme.TEXT_MUTED));
            }
        }
        return html(sb.toString());
    }

    @Nullable
    private static String firstNonBlank(List<String> rows) {
        for (String row : rows) {
            if (row != null && !row.trim().isEmpty()) {
                return row;
            }
        }
        return null;
    }

    private static String colored(String escapedText, Color color) {
        return String.format("<font color='#%06x'>%s</font>", color.getRGB() & 0xFFFFFF, escapedText);
    }

    private static String html(String body) {
        // Swing's HTML renderer scales a CSS width by 96/72, so ask for three
        // quarters of the space the text should actually take.
        return "<html><div style='width:" + ((WIDTH - 30) * 3 / 4) + "px'>" + body + "</div></html>";
    }

    /** Clan names and messages are user-written; a JLabel would render their HTML. */
    static String escape(String text) {
        return text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
    }

    private static JTextArea wrapped(String text) {
        JTextArea area = new JTextArea(text);
        area.setWrapStyleWord(true);
        area.setLineWrap(true);
        area.setOpaque(false);
        area.setEditable(false);
        area.setFocusable(false);
        area.setForeground(DropTrackerTheme.TEXT_MUTED);
        area.setFont(FontManager.getRunescapeSmallFont());
        area.setBorder(BorderFactory.createEmptyBorder(4, 0, 0, 0));
        area.setSize(new Dimension(WIDTH - 24, Short.MAX_VALUE));
        return area;
    }

    private static JPanel row(Component component) {
        JPanel wrap = new JPanel(new BorderLayout());
        wrap.setBackground(DropTrackerTheme.SURFACE_0);
        wrap.add(component, BorderLayout.CENTER);
        wrap.setAlignmentX(Component.LEFT_ALIGNMENT);
        wrap.setMaximumSize(new Dimension(WIDTH, Integer.MAX_VALUE));
        if (component instanceof JTextArea) {
            wrap.setPreferredSize(new Dimension(WIDTH - 24, component.getPreferredSize().height));
        }
        return wrap;
    }
}

package io.droptracker.ui.components;

import lombok.AllArgsConstructor;
import lombok.extern.slf4j.Slf4j;

import java.awt.*;
import java.util.List;
import java.util.function.*;
import java.util.concurrent.CompletableFuture;

import javax.swing.*;
import javax.swing.border.*;

import io.droptracker.models.api.PanelCard;
import io.droptracker.ui.DropTrackerTheme;
import net.runelite.client.ui.*;

@Slf4j
public class LeaderboardComponents {

    /**
     * Creates a standard header panel with title and search functionality
     */
    public static HeaderResult createHeaderPanel(String title, String searchPlaceholder, Runnable searchAction) {
        JPanel headerPanel = new JPanel(new BorderLayout());
        headerPanel.setBackground(DropTrackerTheme.SURFACE_1);
        headerPanel.setBorder(DropTrackerTheme.cardBorder(10, 10, 10, 10));
        headerPanel.setAlignmentX(Component.LEFT_ALIGNMENT);
        headerPanel.setPreferredSize(new Dimension(PluginPanel.PANEL_WIDTH, 90));
        headerPanel.setMaximumSize(new Dimension(PluginPanel.PANEL_WIDTH, 90));
        headerPanel.setMinimumSize(new Dimension(PluginPanel.PANEL_WIDTH, 90));

        JPanel titleAndSearchPanel = DropTrackerTheme.vbox(DropTrackerTheme.SURFACE_1);

        JLabel titleLabel = DropTrackerTheme.label(title, FontManager.getRunescapeBoldFont(), DropTrackerTheme.TEXT);
        titleLabel.setAlignmentX(Component.CENTER_ALIGNMENT);
        titleLabel.setHorizontalAlignment(JLabel.CENTER);
        titleLabel.setPreferredSize(new Dimension(PluginPanel.PANEL_WIDTH - 40, 25));
        titleLabel.setMaximumSize(new Dimension(PluginPanel.PANEL_WIDTH - 40, 25));

        // Search field
        JPanel searchPanel = new JPanel(new BorderLayout(5, 0));
        searchPanel.setBackground(DropTrackerTheme.SURFACE_2);
        searchPanel.setBorder(new StrokeBorder(new BasicStroke(1), DropTrackerTheme.SURFACE_3));
        searchPanel.setAlignmentX(Component.CENTER_ALIGNMENT);
        searchPanel.setPreferredSize(new Dimension(PluginPanel.PANEL_WIDTH - 40, 35));
        searchPanel.setMaximumSize(new Dimension(PluginPanel.PANEL_WIDTH - 40, 35));
        searchPanel.setMinimumSize(new Dimension(PluginPanel.PANEL_WIDTH - 40, 35));

        JTextField searchField = new JTextField();
        searchField.setBackground(DropTrackerTheme.SURFACE_2);
        searchField.setForeground(DropTrackerTheme.TEXT);
        searchField.setCaretColor(DropTrackerTheme.GOLD);
        searchField.setBorder(new StrokeBorder(new BasicStroke(1), DropTrackerTheme.SURFACE_3));
        searchField.setToolTipText(searchPlaceholder);
        searchField.setHorizontalAlignment(JTextField.LEFT);
        searchField.setMargin(new Insets(5, 8, 5, 8));
        searchField.setFont(FontManager.getRunescapeSmallFont());
        searchField.setPreferredSize(new Dimension(200, 35));
        searchField.setMinimumSize(new Dimension(100, 35));

        JButton searchButton = DropTrackerTheme.button("Search");
        searchButton.setPreferredSize(new Dimension(70, 35));
        searchButton.setMaximumSize(new Dimension(70, 35));
        searchButton.setMinimumSize(new Dimension(70, 35));
        searchButton.setMargin(new Insets(5, 5, 5, 5));
        searchButton.addActionListener(e -> searchAction.run());

        searchPanel.add(searchField, BorderLayout.CENTER);
        searchPanel.add(searchButton, BorderLayout.EAST);

        titleAndSearchPanel.add(titleLabel);
        titleAndSearchPanel.add(DropTrackerTheme.gap(10));
        titleAndSearchPanel.add(searchPanel);

        headerPanel.add(titleAndSearchPanel, BorderLayout.CENTER);

        return new HeaderResult(headerPanel, searchField);
    }

    /**
     * Creates a standard leaderboard table with rank, name, and value columns
     */
    public static JPanel createLeaderboardTable(String title, String nameColumnHeader,
            List<PanelCard.Row> data, Consumer<PanelCard.Row> onClick) {

        JPanel leaderboardPanel = DropTrackerTheme.vbox(DropTrackerTheme.SURFACE_0);
        leaderboardPanel.setAlignmentX(Component.CENTER_ALIGNMENT);

        // Title for the leaderboard
        JLabel leaderboardTitle = DropTrackerTheme.label(title, FontManager.getRunescapeBoldFont(), DropTrackerTheme.TEXT);
        leaderboardTitle.setAlignmentX(Component.CENTER_ALIGNMENT);
        leaderboardTitle.setHorizontalAlignment(JLabel.CENTER);

        JPanel tableContainer = DropTrackerTheme.vbox(DropTrackerTheme.SURFACE_1);
        tableContainer.setBorder(DropTrackerTheme.cardBorder(10, 10, 10, 10));
        tableContainer.setAlignmentX(Component.CENTER_ALIGNMENT);
        tableContainer.setMaximumSize(new Dimension(PluginPanel.PANEL_WIDTH - 20, 200));

        JPanel headerRow = createTableHeader(nameColumnHeader);

        JPanel dataContainer = DropTrackerTheme.vbox(DropTrackerTheme.SURFACE_1);
        dataContainer.setAlignmentX(Component.CENTER_ALIGNMENT);

        if (data != null && !data.isEmpty()) {
            int displayRank = 1;
            for (PanelCard.Row item : data) {
                if (displayRank > 5) break; // Only show top 5

                JPanel dataRow = createDataRow(item, displayRank, onClick);
                dataContainer.add(dataRow);

                if (displayRank < Math.min(5, data.size())) {
                    dataContainer.add(DropTrackerTheme.gap(3));
                }
                displayRank++;
            }
        } else {
            // No data fallback
            JLabel noDataLabel = DropTrackerTheme.label("No leaderboard data available", FontManager.getRunescapeSmallFont(), DropTrackerTheme.TEXT_MUTED);
            noDataLabel.setHorizontalAlignment(JLabel.CENTER);
            noDataLabel.setAlignmentX(Component.CENTER_ALIGNMENT);
            dataContainer.add(noDataLabel);
        }

        // Assemble the table
        tableContainer.add(headerRow);
        tableContainer.add(DropTrackerTheme.gap(5));
        tableContainer.add(dataContainer);

        leaderboardPanel.add(leaderboardTitle);
        leaderboardPanel.add(DropTrackerTheme.gap(10));
        leaderboardPanel.add(tableContainer);

        return leaderboardPanel;
    }

    /**
     * Creates table header row
     */
    private static JPanel createTableHeader(String nameColumnHeader) {
        JPanel headerRow = new JPanel(new BorderLayout(5, 0));
        headerRow.setBackground(DropTrackerTheme.SURFACE_1);
        headerRow.setMaximumSize(new Dimension(PluginPanel.PANEL_WIDTH - 40, 25));
        headerRow.setPreferredSize(new Dimension(PluginPanel.PANEL_WIDTH - 40, 25));

        JLabel rankHeader = DropTrackerTheme.label("Rank", FontManager.getRunescapeBoldFont(), DropTrackerTheme.TEXT_MUTED);
        rankHeader.setHorizontalAlignment(JLabel.LEFT);
        rankHeader.setPreferredSize(new Dimension(40, 25));

        JPanel nameAndLootHeader = new JPanel(new BorderLayout(10, 0));
        nameAndLootHeader.setBackground(DropTrackerTheme.SURFACE_1);

        JLabel nameHeader = DropTrackerTheme.label(nameColumnHeader, FontManager.getRunescapeBoldFont(), DropTrackerTheme.TEXT_MUTED);
        nameHeader.setHorizontalAlignment(JLabel.LEFT);

        JLabel lootHeader = DropTrackerTheme.label("Loot", FontManager.getRunescapeBoldFont(), DropTrackerTheme.TEXT_MUTED);
        lootHeader.setHorizontalAlignment(JLabel.RIGHT);
        lootHeader.setPreferredSize(new Dimension(50, 25));

        nameAndLootHeader.add(nameHeader, BorderLayout.CENTER);
        nameAndLootHeader.add(lootHeader, BorderLayout.EAST);

        headerRow.add(rankHeader, BorderLayout.WEST);
        headerRow.add(nameAndLootHeader, BorderLayout.CENTER);

        return headerRow;
    }

    /**
     * Creates a data row for the leaderboard table
     */
    private static JPanel createDataRow(PanelCard.Row item, int displayRank, Consumer<PanelCard.Row> onClick) {
        JPanel dataRow = new JPanel(new BorderLayout(5, 0));
        dataRow.setBackground(DropTrackerTheme.SURFACE_1);
        dataRow.setMaximumSize(new Dimension(PluginPanel.PANEL_WIDTH - 40, 25));
        dataRow.setPreferredSize(new Dimension(PluginPanel.PANEL_WIDTH - 40, 25));

        // Rank
        Integer apiRank = item.getRank();
        int rankToShow = (apiRank != null) ? apiRank : displayRank;

        JLabel rankLabel = DropTrackerTheme.label("#" + rankToShow, FontManager.getRunescapeSmallFont(), rankToShow <= 3 ? DropTrackerTheme.GOLD : DropTrackerTheme.TEXT);
        rankLabel.setHorizontalAlignment(JLabel.LEFT);
        rankLabel.setPreferredSize(new Dimension(40, 25));

        // Name and loot panel
        JPanel nameAndLootData = new JPanel(new BorderLayout(10, 0));
        nameAndLootData.setBackground(DropTrackerTheme.SURFACE_1);

        // Name button. No remote <img> tags: Swing HTML would fetch them over the network.
        String name = item.getName() != null && !item.getName().trim().isEmpty() ? item.getName() : "Unknown";
        JButton nameButton = new JButton(name);
        nameButton.setFont(FontManager.getRunescapeSmallFont());
        nameButton.setForeground(DropTrackerTheme.TEXT);
        nameButton.setHorizontalAlignment(JLabel.LEFT);
        nameButton.setBorder(null);
        nameButton.setOpaque(false);
        nameButton.setContentAreaFilled(false);
        nameButton.setFocusPainted(false);
        nameButton.setToolTipText(name);
        nameButton.setCursor(java.awt.Cursor.getPredefinedCursor(java.awt.Cursor.HAND_CURSOR));
        nameButton.addMouseListener(new java.awt.event.MouseAdapter() {
            @Override
            public void mouseEntered(java.awt.event.MouseEvent e) {
                nameButton.setForeground(DropTrackerTheme.GOLD_BRIGHT);
            }

            @Override
            public void mouseExited(java.awt.event.MouseEvent e) {
                nameButton.setForeground(DropTrackerTheme.TEXT);
            }
        });
        nameButton.addActionListener(e -> onClick.accept(item));

        // Loot value
        String lootValue = item.getTotalLoot() != null && !item.getTotalLoot().trim().isEmpty() ? item.getTotalLoot() : "0 GP";
        JLabel lootLabel = DropTrackerTheme.label(lootValue, FontManager.getRunescapeSmallFont(), DropTrackerTheme.GOLD);
        lootLabel.setHorizontalAlignment(JLabel.RIGHT);
        lootLabel.setPreferredSize(new Dimension(50, 25));

        nameAndLootData.add(nameButton, BorderLayout.CENTER);
        nameAndLootData.add(lootLabel, BorderLayout.EAST);

        dataRow.add(rankLabel, BorderLayout.WEST);
        dataRow.add(nameAndLootData, BorderLayout.CENTER);

        return dataRow;
    }

    /**
     * Replaces a placeholder panel with the actual content
     */
    public static void replacePlaceholder(JPanel placeholder, JPanel replacement) {
        SwingUtilities.invokeLater(() -> {
            if (placeholder != null && replacement != null) {
                Container parent = placeholder.getParent();
                if (parent != null) {
                    // Find the index of the placeholder
                    int index = -1;
                    for (int i = 0; i < parent.getComponentCount(); i++) {
                        if (parent.getComponent(i) == placeholder) {
                            index = i;
                            break;
                        }
                    }

                    if (index != -1) {
                        parent.remove(index);
                        parent.add(replacement, index);
                        parent.revalidate();
                        parent.repaint();
                    }
                }
            }
        });
    }

    /**
     * Creates a clear button for search results
     */
    public static JButton createClearButton(Runnable clearAction) {
        JButton clearButton = new JButton("×");
        clearButton.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 16));
        clearButton.setForeground(DropTrackerTheme.TEXT_MUTED);
        clearButton.setBackground(DropTrackerTheme.SURFACE_1);
        clearButton.setBorder(new EmptyBorder(5, 8, 5, 8));
        clearButton.setPreferredSize(new Dimension(30, 30));
        clearButton.setMaximumSize(new Dimension(30, 30));
        clearButton.setMinimumSize(new Dimension(30, 30));
        clearButton.setToolTipText("Clear search");
        clearButton.setOpaque(false);
        clearButton.setContentAreaFilled(false);
        clearButton.addActionListener(e -> clearAction.run());
        return clearButton;
    }

    /**
     * Handles asynchronous leaderboard loading
     */
    public static <T> void loadLeaderboardAsync(JPanel placeholder, 
            Supplier<T> dataLoader, 
            Function<T, JPanel> panelCreator) {

        CompletableFuture.supplyAsync(() -> {
            try {
                T data = dataLoader.get();
                if (data != null) {
                    return panelCreator.apply(data);
                }
            } catch (Exception e) {
                log.debug("Async leaderboard load failed: {}", e.getMessage());
            }
            return null;
        }).thenAccept(leaderboardPanel -> {
            if (leaderboardPanel != null) {
                replacePlaceholder(placeholder, leaderboardPanel);
            }
        });
    }

    /**
     * Result container for header creation
     */
    @AllArgsConstructor
    public static class HeaderResult {
        public final JPanel panel;
        public final JTextField searchField;

    }

}

