        container.add(titlePanel);
        container.add(DropTrackerTheme.gap(5));
        container.add(contentWrapper);

        return container;
    }

    private static JPanel submissionsContainer(int height) {
        JPanel container = DropTrackerTheme.vbox(DropTrackerTheme.SURFACE_1);
        container.setBorder(new EmptyBorder(10, 0, 10, 0));
        container.setPreferredSize(new Dimension(PluginPanel.PANEL_WIDTH - 40, height));
        container.setMaximumSize(new Dimension(PluginPanel.PANEL_WIDTH - 40, height));
        container.setAlignmentX(Component.LEFT_ALIGNMENT); // Keep consistent with parent
        return container;
    }

    /** A fixed-height, panel-wide row that centers what it holds. */
    private static JPanel centeredRow(int height) {
        JPanel row = new JPanel(new FlowLayout(FlowLayout.CENTER, 0, 0));
        row.setBackground(DropTrackerTheme.SURFACE_1);
        row.setPreferredSize(new Dimension(PluginPanel.PANEL_WIDTH - 40, height));
        row.setMaximumSize(new Dimension(PluginPanel.PANEL_WIDTH - 40, height));
        return row;
    }

    private static JPanel updateValidSubmissionPanel(JPanel panel, List<RecentSubmission> recentSubmissions, ItemManager itemManager, Client client, boolean forGroup) {
        panel.removeAll();


        GridBagConstraints c = new GridBagConstraints();
        c.fill = GridBagConstraints.NONE;
        c.anchor = GridBagConstraints.CENTER;
        c.weightx = 0.2; // Equal weight for 5 columns
        c.weighty = 0.5; // Equal weight for 2 rows
        c.gridx = 0;
        c.gridy = 0;
        c.insets = new Insets(1, 1, 1, 1); // Padding around each icon

        int successfullyAdded = 0;
        final int ITEMS_PER_ROW = 5;
        final int MAX_ITEMS = 10;

        // Add each submission icon to the panel (limit to 10 items)
        for (int i = 0; i < Math.min(recentSubmissions.size(), MAX_ITEMS); i++) {
            RecentSubmission submission = recentSubmissions.get(i);
            boolean effects = false;
            if (submission.submissionImageUrl() != null) {
                effects = true;
            }
            try {
                JLabel iconContainer = null;
                if (submission.getSubmissionType().equalsIgnoreCase("drop")) {
                    // Handle drops
                    Integer itemId = submission.getDropItemId();
                    Integer quantity = submission.getDropQuantity();

                    if (itemId != null && quantity != null && itemManager != null) {
                        iconContainer = itemIcon(itemManager.getImage(itemId, quantity, quantity > 1),
                            quantity > 0 ? 1.0f : 0.5f, effects, submission, forGroup, true);
                    }
                } else if (submission.getSubmissionType().equalsIgnoreCase("clog")) {
                    // Handle collection log items
                    Integer itemId = submission.getClogItemId();

                    if (itemId != null && itemManager != null) {
                        iconContainer = itemIcon(itemManager.getImage(itemId, 1, false),
                            1.0f, effects, submission, forGroup, false);
                    }
                } else {
                    // Personal bests, and event completions credited by any
                    // other source type (manual, kc, …): the API's image_path
                    // is the only icon there is.
                    boolean isPb = submission.getSubmissionType().equalsIgnoreCase("pb");
                    HttpUrl imageUrl = submission.imageUrl();

                    if (imageUrl != null) {
                        final int size = isPb ? 16 : 28;
                        final JLabel pbContainer = PanelElements.createStyledIconContainer(effects);
                        pbContainer.setToolTipText(buildSubmissionTooltip(submission, forGroup));
                        pbContainer.setText(isPb ? "PB" : "");
                        pbContainer.setFont(FontManager.getRunescapeSmallFont());
                        pbContainer.setForeground(DropTrackerTheme.TEXT);
                        iconContainer = pbContainer;

                        // Load image asynchronously
                        CompletableFuture.supplyAsync(() -> {
                            BufferedImage image = fetchImage(imageUrl);
                            if (image != null) {
                                Image scaled = image.getScaledInstance(size, size, Image.SCALE_SMOOTH);
                                return new ImageIcon(scaled);
                            }
                            return null;
                        }).thenAccept(imageIcon -> {
                            if (imageIcon != null) {
                                SwingUtilities.invokeLater(() -> {
                                    pbContainer.setText(""); // Remove text
                                    pbContainer.setIcon(imageIcon);
                                    pbContainer.revalidate();
                                    pbContainer.repaint();
                                });
                            }
                        });
                    }
                }


                // Add the icon container if it was created successfully
                if (iconContainer != null) {
                    if (submission.submissionImageUrl() != null) {
                        // Capture submission data for the click listener
                        final String submissionTypeForListener = submission.getSubmissionType();
                        final HttpUrl submissionImageUrlForListener = submission.submissionImageUrl();
                        // Add hover effect and click listener
                        iconContainer.addMouseListener(new MouseAdapter() {
                            @Override
                            public void mouseClicked(MouseEvent e) {
                                PanelElements.showSubmissionImage(client, submissionTypeForListener, submissionImageUrlForListener);
                            }
                        });
                    }

                    panel.add(iconContainer, c);
                    successfullyAdded++;

                    // Move to next position
                    c.gridx++;
                    if (c.gridx >= ITEMS_PER_ROW) {
                        c.gridx = 0;
                        c.gridy++;
                    }
                }
            } catch (Exception e) {
                log.warn("Failed updating submission panel", e);
            }
        }


        // If no icons were added, show a message
        if (successfullyAdded == 0) {
            JLabel debugLabel = DropTrackerTheme.label("No recent submissions to display", FontManager.getRunescapeSmallFont(), DropTrackerTheme.TEXT_MUTED);
            c.gridx = 0;
            c.gridy = 0;
            c.gridwidth = ITEMS_PER_ROW;
            c.gridheight = 2;
            panel.add(debugLabel, c);
        }

        panel.revalidate();
        panel.repaint();
        return panel;
    }

    /**
     * A 28px item icon that starts blank and fills in once the sprite loads.
     * {@code retip} rebuilds the tooltip then, refreshing its "time ago".
     */
    private static JLabel itemIcon(AsyncBufferedImage originalImage, float alpha, boolean effects,
                                   RecentSubmission submission, boolean forGroup, boolean retip) {
        // Create a scaled version of the image for initial display
        BufferedImage scaledImage = new BufferedImage(28, 28, BufferedImage.TYPE_INT_ARGB);
        BufferedImage opaque = ImageUtil.alphaOffset(scaledImage, alpha);
        final JLabel container = PanelElements.createStyledIconContainer(effects);
        container.setToolTipText(buildSubmissionTooltip(submission, forGroup));
        container.setIcon(new ImageIcon(opaque));

        // onLoaded runs on the client thread (and re-posts there when
        // the sprite is already loaded): scale and relayout on the EDT.
        originalImage.onLoaded(() -> SwingUtilities.invokeLater(() -> {
            // Scale the loaded image to 28x28
            Image scaled = originalImage.getScaledInstance(28, 28, Image.SCALE_SMOOTH);
            BufferedImage scaledBuffered = new BufferedImage(28, 28, BufferedImage.TYPE_INT_ARGB);
            Graphics g = scaledBuffered.getGraphics();
            g.drawImage(scaled, 0, 0, null);
            g.dispose(); // Clean up graphics resources

            BufferedImage finalImage = ImageUtil.alphaOffset(scaledBuffered, alpha);
            container.setIcon(new ImageIcon(finalImage));
            if (retip) {
                container.setToolTipText(buildSubmissionTooltip(submission, forGroup));
            }
            container.revalidate();
            container.repaint();
        }));
        return container;
    }

    public static String buildSubmissionTooltip(RecentSubmission submission, boolean forGroup) {
        try {
            String tooltip = "<html><p style='font-size:10px;'>";
            if (submission.getSubmissionType().equalsIgnoreCase("pb")) {
                String pbTime = sanitizeTxt(submission.getPbTime());
                tooltip += "<b>" + pbTime + "</b> at " + sanitizeTxt(submission.getSourceName()) + "<br>" +
                        sanitizeTxt(submission.getPlayerName()) + " - new personal best!<br><br>" +
                        "<i>" + sanitizeTxt(submission.timeSinceReceived()) + "</i>";
            } else if (submission.getSubmissionType().equalsIgnoreCase("drop")) {
                String itemName = sanitizeTxt(submission.getDropItemName());
                tooltip += "<b>" + itemName + "</b><br>" +
                        sanitizeTxt(submission.getPlayerName()) + "<br>" +
                        "from: <i>" + sanitizeTxt(submission.getSourceName()) + "</i><br>" +
                        "<i>" + sanitizeTxt(submission.timeSinceReceived()) + "</i>";
            } else if (submission.getSubmissionType().equalsIgnoreCase("clog")) {
                String itemName = sanitizeTxt(submission.getClogItemName());
                // Group tooltips also name where the item came from.
                tooltip += sanitizeTxt(submission.getPlayerName()) + " - New Collection Log:<br>" +
                        "<b>" + itemName + "</b><br>" +
                        (forGroup ? "<i>from: " + sanitizeTxt(submission.getSourceName()) + "</i><br>" : "") +
                        "<i>" + sanitizeTxt(submission.timeSinceReceived()) + "</i>";
            } else {
                tooltip += genericSubmissionTooltip(submission);
            }
            tooltip += "</p></html>";
            return tooltip;

        } catch (Exception e) {
            return sanitizeTxt(submission.getPlayerName() + " - " + submission.getSubmissionType() + " - " + submission.getSourceName());
        }
    }

    /**
     * Fallback body for submission types the tabs have no bespoke wording for —
     * an event completion credited by kc, xp or a moderator's hand. The API's
     * own display name is the only thing that describes those, and an empty
     * tooltip would be worse than a plain one.
     */
    private static String genericSubmissionTooltip(RecentSubmission submission) {
        String body = "<b>" + sanitizeTxt(submission.getDisplayName()) + "</b><br>" +
                sanitizeTxt(submission.getPlayerName()) + "<br>";
        if (submission.getSourceName() != null) {
            body += "for: <i>" + sanitizeTxt(submission.getSourceName()) + "</i><br>";
        }
        if (submission.getValue() != null) {
            body += sanitizeTxt(submission.getValue()) + "<br>";
        }
        return body + "<i>" + sanitizeTxt(submission.timeSinceReceived()) + "</i>";
    }

    private static String sanitizeTxt(String tooltip) {
        return escapeHtml(tooltip);
    }

    /**
     * Escapes text that is about to be interpolated into a Swing {@code <html>}
     * string. Swing's HTML renderer resolves {@code <img src>} over the network, so
     * any server-supplied string reaching a JLabel or tooltip must come through
     * here — otherwise the API could make the client fetch an arbitrary URL without
     * a single line of request code being involved.
     */
    public static String escapeHtml(String value) {
        return value == null ? "" : value
            .replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
    }

    private static void displayImageInDialog(JDialog imageDialog, BufferedImage originalImage, JFrame parentFrame) {
        // Calculate display size based on screen dimensions
        Dimension screenSize = java.awt.Toolkit.getDefaultToolkit().getScreenSize();
        int maxWidth = (int) (screenSize.width * 0.9);
        int maxHeight = (int) (screenSize.height * 0.9);

        int originalWidth = originalImage.getWidth();
        int originalHeight = originalImage.getHeight();

        int displayWidth = originalWidth;
        int displayHeight = originalHeight;

        // Scale down if image is too large for screen
        if (originalWidth > maxWidth || originalHeight > maxHeight) {
            double scaleX = (double) maxWidth / originalWidth;
            double scaleY = (double) maxHeight / originalHeight;
            double scale = Math.min(scaleX, scaleY);

            displayWidth = (int) (originalWidth * scale);
            displayHeight = (int) (originalHeight * scale);
        }

        // Create image label
        JLabel imageLabel = new JLabel();
        imageLabel.setPreferredSize(new Dimension(displayWidth, displayHeight));
        imageLabel.setBorder(new StrokeBorder(new BasicStroke(2), DropTrackerTheme.SURFACE_3));
        imageLabel.setHorizontalAlignment(JLabel.CENTER);
        imageLabel.setVerticalAlignment(JLabel.CENTER);
        imageLabel.setBackground(DropTrackerTheme.SURFACE_1);
        imageLabel.setOpaque(true);

        // Scale image if needed
        Image displayImage;
        if (displayWidth == originalWidth && displayHeight == originalHeight) {
            displayImage = originalImage;
        } else {
            displayImage = originalImage.getScaledInstance(displayWidth, displayHeight, Image.SCALE_SMOOTH);
        }

        imageLabel.setIcon(new ImageIcon(displayImage));

        // Add listeners
        addCloseListener(imageLabel, imageDialog);
        addEscapeKeyListener(imageLabel, imageDialog);

        // Set up dialog
        imageDialog.add(imageLabel);
        imageDialog.pack();
        imageDialog.setLocationRelativeTo(parentFrame);

        // Request focus for escape key
        SwingUtilities.invokeLater(() -> imageLabel.requestFocusInWindow());

    }

    // Helper methods to reduce code duplication
    private static void addCloseListener(JLabel label, JDialog dialog) {
        label.addMouseListener(new MouseAdapter() {
            @Override
            public void mouseClicked(MouseEvent e) {
                dialog.dispose();
            }
        });
    }

    private static void addEscapeKeyListener(JLabel label, JDialog dialog) {
        label.setFocusable(true);
        label.addKeyListener(new java.awt.event.KeyAdapter() {
            @Override
            public void keyPressed(java.awt.event.KeyEvent e) {
                if (e.getKeyCode() == java.awt.event.KeyEvent.VK_ESCAPE) {
                    dialog.dispose();
                }
            }
        });
    }

}

package io.droptracker.ui.components;

import lombok.AccessLevel;
import lombok.AllArgsConstructor;
import java.awt.*;
import java.awt.geom.*;

import javax.swing.Icon;

/**
 * Small symbols painted with Graphics2D instead of drawn as text.
 * <p>
 * These used to be Unicode characters. RuneLite's bundled fonts stop at U+2122,
 * so they only ever rendered by falling back to a system font — a chain that
 * does not cover them on macOS, where they came out as missing-glyph boxes.
 * Painting the shapes removes the dependency on font coverage entirely.
 * <p>
 * Symbols that Latin-1 already covers (notably {@code ×}) are left as text;
 * only shapes with no in-font equivalent live here.
 */
public final class PanelIcons {

    private PanelIcons() {
    }

    /** Tick mark, for completed / obtained state. */
    public static Icon check(Color color, int size) {
        return new ShapeIcon(size, color, (g, s, c) -> {
            g.setColor(c);
            g.setStroke(new BasicStroke(Math.max(1.6f, s * 0.16f),
                BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
            Path2D.Float p = new Path2D.Float();
            p.moveTo(s * 0.18f, s * 0.54f);
            p.lineTo(s * 0.42f, s * 0.78f);
            p.lineTo(s * 0.84f, s * 0.22f);
            g.draw(p);
        });
    }

    /** Five-pointed star; {@code filled} distinguishes pinned from unpinned. */
    public static Icon star(Color color, int size, boolean filled) {
        return new ShapeIcon(size, color, (g, s, c) -> {
            g.setColor(c);
            Path2D.Float p = starPath(s);
            if (filled) {
                g.fill(p);
            } else {
                g.setStroke(new BasicStroke(Math.max(1f, s * 0.1f),
                    BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
                g.draw(p);
            }
        });
    }

    /** Circular arrow, for refresh / retry actions. */
    public static Icon refresh(Color color, int size) {
        return new ShapeIcon(size, color, (g, s, c) -> {
            g.setColor(c);
            float inset = s * 0.18f;
            float d = s - inset * 2f;
            g.setStroke(new BasicStroke(Math.max(1.4f, s * 0.13f),
                BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
            // Open arc, with the gap where the arrowhead sits.
            g.drawArc(Math.round(inset), Math.round(inset),
                Math.round(d), Math.round(d), 55, 285);
            // Arrowhead at the open end (top-right of the arc).
            float cx = s / 2f;
            float cy = s / 2f;
            float r = d / 2f;
            double a = Math.toRadians(55);
            float hx = cx + (float) (Math.cos(a) * r);
            float hy = cy - (float) (Math.sin(a) * r);
            float h = s * 0.24f;
            Path2D.Float head = new Path2D.Float();
            head.moveTo(hx + h * 0.5f, hy - h * 0.1f);
            head.lineTo(hx - h * 0.5f, hy - h * 0.35f);
            head.lineTo(hx + h * 0.05f, hy + h * 0.6f);
            head.closePath();
            g.fill(head);
        });
    }

    /** Filled circle, for status dots. */
    public static Icon dot(Color color, int size) {
        return new ShapeIcon(size, color, (g, s, c) -> {
            g.setColor(c);
            float inset = s * 0.2f;
            g.fill(new Ellipse2D.Float(inset, inset, s - inset * 2f, s - inset * 2f));
        });
    }

    /**
     * Paints a tick directly onto an existing surface, for callers already
     * compositing an image rather than showing an {@link Icon}.
     */
    public static void paintCheck(Graphics2D g, int x, int y, int size, Color color) {
        Graphics2D g2 = (Graphics2D) g.create(x, y, size, size);
        try {
            g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING,
                RenderingHints.VALUE_ANTIALIAS_ON);
            g2.setColor(color);
            g2.setStroke(new BasicStroke(Math.max(1.6f, size * 0.16f),
                BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
            Path2D.Float p = new Path2D.Float();
            p.moveTo(size * 0.18f, size * 0.54f);
            p.lineTo(size * 0.42f, size * 0.78f);
            p.lineTo(size * 0.84f, size * 0.22f);
            g2.draw(p);
        } finally {
            g2.dispose();
        }
    }

    private static Path2D.Float starPath(float s) {
        Path2D.Float p = new Path2D.Float();
        float cx = s / 2f;
        float cy = s / 2f + s * 0.03f;
        float outer = s * 0.46f;
        float inner = outer * 0.42f;
        for (int i = 0; i < 10; i++) {
            double angle = Math.toRadians(-90 + i * 36);
            float r = (i % 2 == 0) ? outer : inner;
            float px = cx + (float) (Math.cos(angle) * r);
            float py = cy + (float) (Math.sin(angle) * r);
            if (i == 0) {
                p.moveTo(px, py);
            } else {
                p.lineTo(px, py);
            }
        }
        p.closePath();
        return p;
    }

    @FunctionalInterface
    private interface ShapePainter {
        void paint(Graphics2D g, float size, Color color);
    }

    /** Square icon that antialiases and hands a clean surface to its painter. */
    @AllArgsConstructor(access = AccessLevel.PRIVATE)
    private static final class ShapeIcon implements Icon {
        private final int size;
        private final Color color;
        private final ShapePainter painter;

        @Override
        public void paintIcon(Component c, Graphics g, int x, int y) {
            Graphics2D g2 = (Graphics2D) g.create(x, y, size, size);
            try {
                g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING,
                    RenderingHints.VALUE_ANTIALIAS_ON);
                g2.setRenderingHint(RenderingHints.KEY_STROKE_CONTROL,
                    RenderingHints.VALUE_STROKE_PURE);
                painter.paint(g2, size, color);
            } finally {
                g2.dispose();
            }
        }

        @Override
        public int getIconWidth() {
            return size;
        }

        @Override
        public int getIconHeight() {
            return size;
        }
    }
}

package io.droptracker.ui.components;

import io.droptracker.ui.DropTrackerTheme;
import net.runelite.client.ui.FontManager;

import javax.swing.*;
import java.awt.*;

/**
 * Shared loading / error / empty state views used across all side panel pages,
 * so every page presents the same visual language for these states.
 */
public final class StateViews {

    private StateViews() {
    }

    /** Subtle centered "Loading…" label. */
    public static JPanel loading(String text) {
        return centeredLabelPanel(text != null ? text : "Loading…", DropTrackerTheme.TEXT_MUTED, 20);
    }

    /** Short muted hint for empty content. */
    public static JPanel empty(String hint) {
        return centeredLabelPanel(hint != null ? hint : "Nothing here yet.", DropTrackerTheme.TEXT_MUTED, 20);
    }

    /** Error message with a retry (or back) button. */
    public static JPanel error(String message, String buttonText, Runnable retryAction) {
        JPanel panel = DropTrackerTheme.vbox(DropTrackerTheme.SURFACE_0);
        panel.setAlignmentX(Component.CENTER_ALIGNMENT);

        panel.add(DropTrackerTheme.gap(20));

        JLabel errorLabel = new JLabel("<html><div style='text-align:center;'>" + message + "</div></html>");
        errorLabel.setFont(FontManager.getRunescapeSmallFont());
        errorLabel.setForeground(DropTrackerTheme.RED);
        errorLabel.setAlignmentX(Component.CENTER_ALIGNMENT);
        errorLabel.setHorizontalAlignment(JLabel.CENTER);
        panel.add(errorLabel);

        if (retryAction != null) {
            panel.add(DropTrackerTheme.gap(12));
            JButton retryButton = DropTrackerTheme.button(buttonText != null ? buttonText : "Retry");
            retryButton.setAlignmentX(Component.CENTER_ALIGNMENT);
            retryButton.addActionListener(e -> retryAction.run());
            panel.add(retryButton);
        }

        panel.add(Box.createVerticalGlue());
        return panel;
    }

    private static JPanel centeredLabelPanel(String text, java.awt.Color color, int topGap) {
        JPanel panel = DropTrackerTheme.vbox(DropTrackerTheme.SURFACE_0);
        panel.setAlignmentX(Component.CENTER_ALIGNMENT);

        panel.add(Box.createRigidArea(new Dimension(0, topGap)));

        JLabel label = new JLabel("<html><div style='text-align:center;'>" + text + "</div></html>");
        label.setFont(FontManager.getRunescapeSmallFont());
        label.setForeground(color);
        label.setAlignmentX(Component.CENTER_ALIGNMENT);
        label.setHorizontalAlignment(JLabel.CENTER);
        panel.add(label);

        panel.add(Box.createVerticalGlue());
        return panel;
    }
}

package io.droptracker.ui.overlays;

import io.droptracker.DropTrackerConfig;
import io.droptracker.models.EventHudDetail;
import io.droptracker.models.api.EventState;
import io.droptracker.service.EventNotificationService;
import io.droptracker.ui.DropTrackerTheme;
import io.droptracker.util.*;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.*;

import javax.annotation.Nullable;
import javax.inject.*;
import java.awt.*;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.List;

/**
 * The "Enhanced display" HUD, painted in the style of the game's collection
 * log popup: layered parchment card with a bronze frame, a title strip, the
 * team standing and the tracked task with a framed progress bar. Movable
 * (hold Alt to drag — standard RuneLite overlay behavior). Data comes from
 * the {@code /event_state} snapshot in {@link EventNotificationService};
 * which event shows is the "Show on HUD" pick in the Events tab, and which
 * task shows honors the user's tracked-task pick (Events tab) before the
 * server's focus choice.
 *
 * Pop-ups are not drawn here: with this display type they show as showcase
 * panels in {@link EventToastOverlay}, which is movable on its own.
 */
@Singleton
public class EventHudOverlay extends Overlay {
    private static final int WIDTH = 200;
    private static final int PAD = 8;
    private static final int ICON_SIZE = 26;
    private static final int BAR_HEIGHT = 13;

    /* Frame palette (collection-log-popup inspired). */
    private static final Color EDGE_DARK = new Color(0x0e, 0x0b, 0x07);
    private static final Color FRAME_BRONZE = DropTrackerTheme.BRONZE;
    private static final Color BG_TOP = new Color(0x2c, 0x23, 0x18, 242);
    private static final Color BG_BOTTOM = new Color(0x15, 0x11, 0x0c, 242);
    private static final Color TITLE_STRIP = new Color(0x0e, 0x0b, 0x07, 130);
    private static final Color BAR_FILL = new Color(0x2e, 0x5c, 0x33);
    private static final Color BAR_EDGE = DropTrackerTheme.GREEN;

    private final DropTrackerConfig config;
    private final EventNotificationService service;
    private final ItemManager itemManager;
    private final RemoteImageCache remoteImages;

    @Inject
    public EventHudOverlay(DropTrackerConfig config, EventNotificationService service,
                           ItemManager itemManager, RemoteImageCache remoteImages) {
        this.config = config;
        this.service = service;
        this.itemManager = itemManager;
        this.remoteImages = remoteImages;
        setPosition(OverlayPosition.TOP_LEFT);
        setResizable(false);
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        if (!config.eventNotifications() || !config.eventDisplayMode().hudEnabled()) {
            return null;
        }
        EventState.Entry entry = service.hudEntry();
        if (entry == null || entry.getEvent() == null) {
            return null;
        }
        boolean detailed = config.eventHudDetail() == EventHudDetail.DETAILED;
        EventNotificationService.DisplayTask task = service.displayTask(entry);
        boolean awaitingRoll = "awaiting_roll".equals(entry.getBoardStatus());

        graphics.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING,
            RenderingHints.VALUE_TEXT_ANTIALIAS_ON);

        Font titleFont = FontManager.getRunescapeBoldFont();
        Font smallFont = FontManager.getRunescapeSmallFont();
        FontMetrics titleFm = graphics.getFontMetrics(titleFont);
        FontMetrics smallFm = graphics.getFontMetrics(smallFont);

        int innerWidth = WIDTH - PAD * 2;
        String title = truncateToWidth(entry.getEvent().getName(), titleFm, innerWidth);

        // Task label lines (max 2), leaving room for the icon column.
        BufferedImage icon = task != null ? taskIcon(task) : null;
        int labelWidth = innerWidth - (icon != null ? ICON_SIZE + 6 : 0);
        List<String> taskLines = task != null
            ? wrap(taskLabel(task), smallFm, labelWidth, 2) : new ArrayList<>();
        boolean hasBar = task != null && (task.need > 1 || task.have > 0);

        /* ---- measure ---- */
        int titleStripH = titleFm.getHeight() + 6;
        int height = titleStripH;
        if (detailed && entry.getTeam() != null) {
            height += 4 + smallFm.getHeight();
            if (entry.getTeam().getRank() != null) {
                height += smallFm.getHeight();
            }
        }
        if (awaitingRoll) {
            height += 6 + titleFm.getHeight();
        } else if (task != null) {
            int textBlock = taskLines.size() * smallFm.getHeight();
            int rowH = Math.max(icon != null ? ICON_SIZE : 0, textBlock);
            height += 6 + rowH;
            if (hasBar) {
                height += 4 + BAR_HEIGHT;
            }
        } else if (entry.getTasksTotal() > 0) {
            height += 6 + smallFm.getHeight();
        }
        height += PAD;

        /* ---- frame ---- */
        graphics.setPaint(new GradientPaint(0, 0, BG_TOP, 0, height, BG_BOTTOM));
        graphics.fillRect(1, 1, WIDTH - 2, height - 2);
        graphics.setColor(EDGE_DARK);
        graphics.setStroke(new BasicStroke(1));
        graphics.drawRect(0, 0, WIDTH - 1, height - 1);
        graphics.setColor(FRAME_BRONZE);
        graphics.drawRect(1, 1, WIDTH - 3, height - 3);

        /* ---- title strip ---- */
        graphics.setColor(TITLE_STRIP);
        graphics.fillRect(2, 2, WIDTH - 4, titleStripH - 2);
        graphics.setColor(FRAME_BRONZE);
        graphics.drawLine(2, titleStripH, WIDTH - 3, titleStripH);
        graphics.setFont(titleFont);
        int titleX = (WIDTH - titleFm.stringWidth(title)) / 2;
        int titleY = 3 + titleFm.getAscent();
        graphics.setColor(Color.BLACK);
        graphics.drawString(title, titleX + 1, titleY + 1);
        graphics.setColor(DropTrackerTheme.GOLD);
        graphics.drawString(title, titleX, titleY);

        int y = titleStripH + 4;

        /* ---- team standing (Detailed) ---- */
        if (detailed && entry.getTeam() != null) {
            EventState.TeamInfo team = entry.getTeam();
            Color teamColor = parseColor(team.getColor(), DropTrackerTheme.TEXT);
            graphics.setFont(smallFont);

            int swatch = 8;
            int swatchY = y + (smallFm.getHeight() - swatch) / 2;
            graphics.setColor(teamColor);
            graphics.fillRect(PAD, swatchY, swatch, swatch);
            graphics.setColor(EDGE_DARK);
            graphics.drawRect(PAD, swatchY, swatch, swatch);

            String standing = team.getRank() != null
                ? ordinal(team.getRank()) + " of " + team.getTeamCount()
                : ValueFormat.commas(team.getScore()) + " pts";
            String teamName = truncateToWidth(team.getName(), smallFm,
                innerWidth - swatch - 6 - smallFm.stringWidth(standing) - 4);
            int textY = y + smallFm.getAscent();
            shadowed(graphics, teamName, PAD + swatch + 6, textY, teamColor);
            shadowed(graphics, standing, WIDTH - PAD - smallFm.stringWidth(standing),
                textY, DropTrackerTheme.TEXT_MUTED);
            y += smallFm.getHeight();

            if (team.getRank() != null) {
                String score = ValueFormat.commas(team.getScore());
                textY = y + smallFm.getAscent();
                shadowed(graphics, "Score", PAD, textY, DropTrackerTheme.TEXT_MUTED);
                shadowed(graphics, score, WIDTH - PAD - smallFm.stringWidth(score),
                    textY, DropTrackerTheme.GOLD_BRIGHT);
                y += smallFm.getHeight();
            }
        }

        /* ---- task / roll prompt ---- */
        if (awaitingRoll) {
            y += 6;
            graphics.setFont(titleFont);
            String roll = "Roll the dice!";
            int rollX = (WIDTH - titleFm.stringWidth(roll)) / 2;
            shadowed(graphics, roll, rollX, y + titleFm.getAscent(), DropTrackerTheme.GOLD_BRIGHT);
        } else if (task != null) {
            y += 6;
            int textBlock = taskLines.size() * smallFm.getHeight();
            int rowH = Math.max(icon != null ? ICON_SIZE : 0, textBlock);
            int textX = PAD;
            if (icon != null) {
                graphics.drawImage(scaled(icon), PAD, y + (rowH - ICON_SIZE) / 2, null);
                textX += ICON_SIZE + 6;
            }
            graphics.setFont(smallFont);
            int lineY = y + (rowH - textBlock) / 2 + smallFm.getAscent();
            for (String line : taskLines) {
                shadowed(graphics, line, textX, lineY,
                    task.tracked ? DropTrackerTheme.GOLD_BRIGHT : DropTrackerTheme.TEXT);
                lineY += smallFm.getHeight();
            }
            y += rowH;

            if (hasBar) {
                y += 4;
                drawProgressBar(graphics, smallFm, PAD, y, innerWidth, task.have, task.need);
                y += BAR_HEIGHT;
            }
        } else if (entry.getTasksTotal() > 0) {
            y += 6;
            graphics.setFont(smallFont);
            String done = entry.getTasksCompleted() + " / " + entry.getTasksTotal();
            shadowed(graphics, "Tasks", PAD, y + smallFm.getAscent(), DropTrackerTheme.TEXT_MUTED);
            shadowed(graphics, done, WIDTH - PAD - smallFm.stringWidth(done),
                y + smallFm.getAscent(), DropTrackerTheme.TEXT);
        }

        return new Dimension(WIDTH, height);
    }

    /* ===================== painting helpers ===================== */

    private void drawProgressBar(Graphics2D g, FontMetrics fm, int x, int y,
                                 int width, long have, long need) {
        long max = Math.max(need, 1);
        long value = Math.min(Math.max(have, 0), max);
        g.setColor(new Color(0x0a, 0x08, 0x05));
        g.fillRect(x, y, width, BAR_HEIGHT);
        int fill = (int) Math.round((double) value / max * (width - 2));
        g.setColor(BAR_FILL);
        g.fillRect(x + 1, y + 1, fill, BAR_HEIGHT - 2);
        g.setColor(BAR_EDGE);
        g.fillRect(x + 1, y + 1, fill, 2);
        g.setColor(FRAME_BRONZE);
        g.drawRect(x, y, width - 1, BAR_HEIGHT - 1);

        String text = ValueFormat.progress(have, need);
        int tx = x + (width - fm.stringWidth(text)) / 2;
        int ty = y + (BAR_HEIGHT + fm.getAscent() - fm.getDescent()) / 2;
        g.setColor(Color.BLACK);
        g.drawString(text, tx + 1, ty + 1);
        g.setColor(DropTrackerTheme.TEXT);
        g.drawString(text, tx, ty);
    }

    private void shadowed(Graphics2D g, String text, int x, int y, Color color) {
        g.setColor(Color.BLACK);
        g.drawString(text, x + 1, y + 1);
        g.setColor(color);
        g.drawString(text, x, y);
    }

    private String taskLabel(EventNotificationService.DisplayTask task) {
        // "*" not "★": this string is drawn with a RuneScape font, which has
        // no star glyph (see PanelIcons).
        return (task.tracked ? "* " : "") + (task.label != null ? task.label : "");
    }

    @Nullable
    private BufferedImage taskIcon(EventNotificationService.DisplayTask task) {
        if (task.iconItemId != null && task.iconItemId > 0) {
            return itemManager.getImage(task.iconItemId);
        }
        return remoteImages.get(task.iconPath, null);
    }

    private static BufferedImage scaled(BufferedImage source) {
        if (source.getWidth() <= ICON_SIZE && source.getHeight() <= ICON_SIZE) {
            return source;
        }
        // Fit within the slot, centered, aspect ratio preserved (item sprites
        // are 36x32 — a straight square scale visibly squishes them).
        int w = Math.max(source.getWidth(), 1);
        int h = Math.max(source.getHeight(), 1);
        float scale = Math.min((float) ICON_SIZE / w, (float) ICON_SIZE / h);
        int nw = Math.max(Math.round(w * scale), 1);
        int nh = Math.max(Math.round(h * scale), 1);
        BufferedImage out = new BufferedImage(ICON_SIZE, ICON_SIZE, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = out.createGraphics();
        g.setRenderingHint(RenderingHints.KEY_INTERPOLATION,
            RenderingHints.VALUE_INTERPOLATION_BILINEAR);
        g.drawImage(source, (ICON_SIZE - nw) / 2, (ICON_SIZE - nh) / 2, nw, nh, null);
        g.dispose();
        return out;
    }

    /* ===================== text helpers ===================== */

    private static String truncateToWidth(String text, FontMetrics fm, int width) {
        if (text == null) {
            return "";
        }
        if (fm.stringWidth(text) <= width) {
            return text;
        }
        String out = text;
        while (out.length() > 1 && fm.stringWidth(out + "…") > width) {
            out = out.substring(0, out.length() - 1);
        }
        return out + "…";
    }

    /** Word-wrap into at most maxLines lines; the last line is ellipsized. */
    private static List<String> wrap(String text, FontMetrics fm, int width, int maxLines) {
        List<String> lines = new ArrayList<>();
        if (text == null || text.isEmpty()) {
            return lines;
        }
        String[] words = text.split(" ");
        StringBuilder line = new StringBuilder();
        for (String word : words) {
            String candidate = line.length() == 0 ? word : line + " " + word;
            if (fm.stringWidth(candidate) <= width || line.length() == 0) {
                line = new StringBuilder(candidate);
            } else {
                lines.add(line.toString());
                line = new StringBuilder(word);
                if (lines.size() == maxLines - 1) {
                    break;
                }
            }
        }
        if (line.length() > 0 && lines.size() < maxLines) {
            lines.add(line.toString());
        }
        // If the text didn't fully fit, ellipsize the final line.
        String joined = String.join(" ", lines);
        if (!joined.equals(text) && !lines.isEmpty()) {
            int last = lines.size() - 1;
            lines.set(last, truncateToWidth(lines.get(last) + "…", fm, width));
        }
        return lines;
    }

    private static Color parseColor(String hex, Color fallback) {
        if (hex == null || hex.isEmpty()) {
            return fallback;
        }
        try {
            return Color.decode(hex);
        } catch (NumberFormatException e) {
            return fallback;
        }
    }

    private static String ordinal(int n) {
        if (n % 100 >= 11 && n % 100 <= 13) {
            return n + "th";
        }
        switch (n % 10) {
            case 1: return n + "st";
            case 2: return n + "nd";
            case 3: return n + "rd";
            default: return n + "th";
        }
    }
}

package io.droptracker.ui.overlays;

import io.droptracker.DropTrackerConfig;
import io.droptracker.service.EventNotificationService;
import io.droptracker.service.EventNotificationService.Toast;
import io.droptracker.ui.overlays.popup.*;
import net.runelite.client.ui.overlay.*;

import javax.inject.*;
import java.awt.*;
import java.util.*;
import java.util.List;

/**
 * Transient event pop-ups, stacked top-center: slim banners for "Chat + text
 * pop-ups", showcase panels for "Enhanced display" (or whichever style a
 * {@code ::dtpopup} preview pinned), fading out at the end of their
 * priority-dependent lifetime. Movable like any overlay (hold Alt to drag).
 */
@Singleton
public class EventToastOverlay extends Overlay {
    private final DropTrackerConfig config;
    private final EventNotificationService service;
    private final PopupRenderers renderers;

    @Inject
    public EventToastOverlay(DropTrackerConfig config, EventNotificationService service,
                             PopupRenderers renderers) {
        this.config = config;
        this.service = service;
        this.renderers = renderers;
        setPosition(OverlayPosition.TOP_CENTER);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        if (!config.eventNotifications() || !config.eventDisplayMode().popupsEnabled()) {
            service.getToasts().clear();
            return null;
        }
        long now = System.currentTimeMillis();
        List<Toast> visible = new ArrayList<>();
        List<PopupRenderer> painters = new ArrayList<>();
        int width = 0;
        Iterator<Toast> iterator = service.getToasts().iterator();
        while (iterator.hasNext()) {
            Toast toast = iterator.next();
            if (toast.expired(now)) {
                iterator.remove();
                continue;
            }
            PopupRenderer renderer = renderers.popup(toast.getPopupStyle() != null
                ? toast.getPopupStyle() : config.eventDisplayMode().popupStyle());
            if (visible.size() < renderer.maxVisible()) {
                visible.add(toast);
                painters.add(renderer);
                width = Math.max(width, renderer.preferredWidth());
            }
        }
        if (visible.isEmpty()) {
            return null;
        }

        graphics.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING,
            RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
        int y = 0;
        for (int i = 0; i < visible.size(); i++) {
            PopupRenderer renderer = painters.get(i);
            if (i > 0) {
                y += renderer.gap();
            }
            int cardWidth = renderer.preferredWidth();
            y += renderer.draw(graphics, visible.get(i), (width - cardWidth) / 2, y, cardWidth, now);
        }
        return new Dimension(width, y);
    }
}

package io.droptracker.ui.overlays.popup;

import lombok.AccessLevel;
import lombok.AllArgsConstructor;
import io.droptracker.models.EventPopupCard;
import io.droptracker.service.EventNotificationService.Toast;

import java.awt.*;
import java.awt.geom.AffineTransform;
import java.awt.image.BufferedImage;
import java.util.Locale;

/**
 * A slim banner: the icon on a colour block at the left, caption (and who
 * did it) over the headline, the one number that matters on the right, and a thin line along
 * the bottom that shows task progress or, failing that, the time left on
 * screen. Slides down into place and fades out. The least screen for the most
 * information, for players who want pop-ups but not panels.
 */
@AllArgsConstructor(access = AccessLevel.PACKAGE)
class BannerRenderer implements PopupRenderer {
    private static final int WIDTH = 340;
    private static final int HEIGHT = 40;
    private static final int BLOCK = 40;
    private static final long SLIDE_MS = 240;
    private static final long FADE_MS = 500;

    private final PopupIcons icons;

    @Override
    public int preferredWidth() {
        return WIDTH;
    }

    @Override
    public int gap() {
        return 4;
    }

    @Override
    public int draw(Graphics2D g, Toast toast, int x, int top, int w, long now) {
        EventPopupCard card = PopupPaint.cardOf(toast);
        Color accent = PopupPaint.accent(card.getKind());
        long age = now - toast.getCreatedAt();

        Composite previousComposite = g.getComposite();
        AffineTransform previousTransform = g.getTransform();
        float slide = PopupPaint.easeOutCubic(PopupPaint.phase(age, 0, SLIDE_MS));
        PopupPaint.setAlpha(g, PopupPaint.fadeOut(toast, now, FADE_MS) * slide);
        g.translate(0, Math.round((slide - 1f) * HEIGHT * 0.6f));

        /* ---- body ---- */
        g.setPaint(new GradientPaint(x, 0, PopupPaint.alpha(PopupPaint.mix(accent, PopupPaint.INK, 0.72f), 240),
            x + w, 0, PopupPaint.alpha(PopupPaint.INK, 225)));
        g.fillRect(x, top, w, HEIGHT);
        g.setColor(PopupPaint.INK);
        g.drawRect(x, top, w - 1, HEIGHT - 1);
        g.setColor(accent);
        g.drawLine(x + 1, top + 1, x + w - 2, top + 1);

        /* ---- icon block ---- */
        g.setColor(PopupPaint.mix(accent, PopupPaint.INK, 0.55f));
        g.fillRect(x + 1, top + 2, BLOCK - 1, HEIGHT - 3);
        g.setColor(accent);
        g.drawLine(x + BLOCK, top + 2, x + BLOCK, top + HEIGHT - 2);
        BufferedImage sprite = icons.forToast(toast);
        if (sprite != null) {
            PopupPaint.drawSprite(g, sprite, x + 4, top + 5, BLOCK - 8);
        } else {
            // No item: the kind's emblem, so the block never sits empty.
            PopupGlyphs.draw(g, card.getKind(), x + 9, top + 9, BLOCK - 18,
                PopupPaint.mix(accent, Color.WHITE, 0.25f));
        }

        /* ---- right column ---- */
        FontMetrics smallFm = g.getFontMetrics(PopupPaint.small());
        FontMetrics boldFm = g.getFontMetrics(PopupPaint.bold());
        int right = x + w - 8;
        String value = card.getRightValue();
        String label = card.getRightLabel() != null ? trimColon(card.getRightLabel()) : null;
        if (value == null && toast.getMoreCount() > 0) {
            value = "+" + toast.getMoreCount();
            label = "more";
        } else if (toast.getMoreCount() > 0) {
            label = (label != null ? label + "  " : "") + "+" + toast.getMoreCount() + " more";
        }
        int valueWidth = value != null ? Math.min(boldFm.stringWidth(value), 110) : 0;
        int labelWidth = label != null ? Math.min(smallFm.stringWidth(label), 110) : 0;
        int column = Math.max(valueWidth, labelWidth);

        /* ---- text ---- */
        int textX = x + BLOCK + 8;
        int textWidth = right - (column > 0 ? column + 10 : 0) - textX;
        g.setFont(PopupPaint.small());
        int captionY = top + 4 + smallFm.getAscent();
        String captionText = PopupPaint.ellipsize(card.getCaption().toUpperCase(Locale.ROOT),
            smallFm, textWidth);
        PopupPaint.shadowed(g, captionText, textX, captionY, accent);
        // Who did it, after the caption when it fits: "TASK COMPLETE - Zezima".
        String who = card.getLeftValue();
        int whoX = textX + smallFm.stringWidth(captionText) + 6;
        int whoRoom = textX + textWidth - whoX;
        if (who != null && whoRoom > smallFm.stringWidth("- ") + 20) {
            PopupPaint.shadowed(g, PopupPaint.ellipsize("- " + who, smallFm, whoRoom), whoX, captionY,
                PopupPaint.TEXT_MUTED);
        }
        g.setFont(PopupPaint.bold());
        int headlineY = top + HEIGHT - 8 - boldFm.getDescent();
        PopupPaint.shadowed(g, PopupPaint.ellipsize(card.getHeadline(), boldFm, textWidth),
            textX, headlineY, PopupPaint.TEXT);

        if (label != null) {
            g.setFont(PopupPaint.small());
            PopupPaint.shadowedRight(g, PopupPaint.ellipsize(label, smallFm, 110), right, captionY,
                PopupPaint.TEXT_MUTED);
        }
        if (value != null) {
            g.setFont(PopupPaint.bold());
            PopupPaint.shadowedRight(g, PopupPaint.ellipsize(value, boldFm, 110), right, headlineY,
                PopupPaint.VALUE);
        }

        /* ---- bottom line: progress, else time left ---- */
        int lineX = x + BLOCK + 1;
        int lineW = w - BLOCK - 2;
        int lineY = top + HEIGHT - 3;
        g.setColor(PopupPaint.alpha(PopupPaint.INK, 200));
        g.fillRect(lineX, lineY, lineW, 2);
        float fraction = card.fraction();
        if (fraction >= 0f) {
            float grow = PopupPaint.easeOutCubic(PopupPaint.phase(age, 150, 600));
            g.setColor(accent);
            g.fillRect(lineX, lineY, Math.round(lineW * fraction * grow), 2);
        } else {
            float left = PopupPaint.clamp01(toast.remainingMs(now) / (float) toast.lifetimeMs());
            g.setColor(PopupPaint.alpha(accent, 150));
            g.fillRect(lineX, lineY, Math.round(lineW * left), 2);
        }

        g.setTransform(previousTransform);
        g.setComposite(previousComposite);
        return HEIGHT;
    }

    private static String trimColon(String label) {
        return label.endsWith(":") ? label.substring(0, label.length() - 1) : label;
    }
}

package io.droptracker.ui.overlays.popup;

import io.droptracker.models.EventPopupCard;

import java.awt.*;

/**
 * Small vector emblems for the kinds of news that carry no item (a lead
 * change, a bingo line, the event starting), so their icon slot never sits
 * empty. Drawn with plain shapes: the RuneScape fonts have no symbol glyphs,
 * and nothing here needs an image resource.
 */
final class PopupGlyphs {
    private PopupGlyphs() {
    }

    /** Paints the kind's emblem centred in a {@code size} square at (x, y), with a drop shadow. */
    static void draw(Graphics2D g, EventPopupCard.Kind kind, int x, int y, int size, Color color) {
        Object aa = g.getRenderingHint(RenderingHints.KEY_ANTIALIASING);
        Stroke stroke = g.getStroke();
        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        g.translate(1, 1);
        shape(g, kind, x, y, size, Color.BLACK);
        g.translate(-1, -1);
        shape(g, kind, x, y, size, color);
        g.setStroke(stroke);
        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING,
            aa != null ? aa : RenderingHints.VALUE_ANTIALIAS_DEFAULT);
    }

    private static void shape(Graphics2D g, EventPopupCard.Kind kind, int x, int y, int size, Color c) {
        // Work in a padded square so every emblem has the same optical weight.
        int pad = Math.max(1, size / 8);
        int s = size - pad * 2;
        int ox = x + pad;
        int oy = y + pad;
        float line = Math.max(1.5f, s / 9f);
        g.setColor(c);
        g.setStroke(new BasicStroke(line, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
        switch (kind) {
            case COMPLETE: {
                int[] xs = {ox + s / 8, ox + s * 3 / 8, ox + s * 7 / 8};
                int[] ys = {oy + s / 2, oy + s * 6 / 8, oy + s / 5};
                g.setStroke(new BasicStroke(line * 1.6f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
                g.drawPolyline(xs, ys, 3);
                break;
            }
            case TILE:
                grid(g, ox, oy, s, c, new boolean[]{false, false, false, false, true, false, false, false, false});
                break;
            case LINE:
                grid(g, ox, oy, s, c, new boolean[]{false, false, false, true, true, true, false, false, false});
                break;
            case BLACKOUT:
                grid(g, ox, oy, s, c, new boolean[]{true, true, true, true, true, true, true, true, true});
                break;
            case PROGRESS: {
                int bar = Math.max(2, s / 5);
                int gap = (s - bar * 3) / 2;
                for (int i = 0; i < 3; i++) {
                    int h = s * (i + 1) / 3;
                    g.fillRect(ox + i * (bar + gap), oy + s - h, bar, h);
                }
                break;
            }
            case LEAD: {
                // Crown: three points over a band.
                Polygon crown = new Polygon();
                crown.addPoint(ox, oy + s * 3 / 4);
                crown.addPoint(ox, oy + s / 4);
                crown.addPoint(ox + s / 4, oy + s / 2);
                crown.addPoint(ox + s / 2, oy + s / 8);
                crown.addPoint(ox + s * 3 / 4, oy + s / 2);
                crown.addPoint(ox + s, oy + s / 4);
                crown.addPoint(ox + s, oy + s * 3 / 4);
                g.fillPolygon(crown);
                g.fillRect(ox, oy + s * 13 / 16, s + 1, Math.max(2, s / 8));
                break;
            }
            case STARTED:
            case ENDED: {
                // Flag on a pole; the finish flag is chequered.
                int pole = Math.max(2, s / 8);
                g.fillRect(ox + s / 8, oy, pole, s);
                int fx = ox + s / 8 + pole;
                int fw = s * 3 / 4;
                int fh = s / 2;
                if (kind == EventPopupCard.Kind.STARTED) {
                    Polygon flag = new Polygon();
                    flag.addPoint(fx, oy);
                    flag.addPoint(fx + fw, oy + fh / 2);
                    flag.addPoint(fx, oy + fh);
                    g.fillPolygon(flag);
                } else {
                    int cell = Math.max(2, fw / 4);
                    for (int row = 0; row * cell < fh; row++) {
                        for (int col = 0; col * cell < fw; col++) {
                            if ((row + col) % 2 == 0) {
                                g.fillRect(fx + col * cell, oy + row * cell, cell, cell);
                            }
                        }
                    }
                    g.drawRect(fx, oy, fw, fh);
                }
                break;
            }
            case BOARD:
            case ROLL: {
                g.drawRoundRect(ox, oy, s, s, s / 4, s / 4);
                int pip = Math.max(2, s / 6);
                int[][] spots = kind == EventPopupCard.Kind.ROLL
                    ? new int[][]{{1, 1}, {3, 1}, {2, 2}, {1, 3}, {3, 3}}
                    : new int[][]{{1, 1}, {2, 2}, {3, 3}};
                for (int[] spot : spots) {
                    g.fillOval(ox + s * spot[0] / 4 - pip / 2, oy + s * spot[1] / 4 - pip / 2, pip, pip);
                }
                break;
            }
            case DIGEST:
            default: {
                // A short list: three lines, the first one a heading.
                g.drawLine(ox + s / 8, oy + s / 4, ox + s * 7 / 8, oy + s / 4);
                g.drawLine(ox + s / 8, oy + s / 2, ox + s * 3 / 4, oy + s / 2);
                g.drawLine(ox + s / 8, oy + s * 3 / 4, ox + s * 5 / 8, oy + s * 3 / 4);
                break;
            }
        }
    }

    /** A 3x3 bingo board with the given cells filled. */
    private static void grid(Graphics2D g, int x, int y, int s, Color c, boolean[] filled) {
        int cell = s / 3;
        int inset = Math.max(1, cell / 6);
        for (int i = 0; i < 9; i++) {
            int cx = x + (i % 3) * cell + inset;
            int cy = y + (i / 3) * cell + inset;
            int w = cell - inset * 2;
            if (filled[i]) {
                g.fillRect(cx, cy, w, w);
            } else {
                g.setColor(new Color(c.getRed(), c.getGreen(), c.getBlue(), 90));
                g.fillRect(cx, cy, w, w);
                g.setColor(c);
            }
        }
    }
}

package io.droptracker.ui.overlays.popup;

import io.droptracker.service.EventNotificationService.Toast;

import javax.annotation.Nullable;
import java.awt.image.BufferedImage;
import java.util.function.*;

/**
 * The picture for a pop-up: the item sprite when the toast names one (the
 * drop that caused it, or the task's own item), else the server icon for the
 * task or team (an NPC, a skill, a team piece), else null and the renderer
 * draws the kind's emblem. Both lookups are cache reads that never block:
 * a remote icon still downloading simply shows up a frame or two later.
 */
@FunctionalInterface
interface PopupIcons {
    @Nullable
    BufferedImage forToast(Toast toast);

    static PopupIcons of(IntFunction<BufferedImage> items, Function<String, BufferedImage> paths) {
        return toast -> {
            Integer itemId = PopupPaint.iconOf(toast);
            BufferedImage image = itemId != null ? items.apply(itemId) : null;
            if (image == null && toast.getIconPath() != null) {
                image = paths.apply(toast.getIconPath());
            }
            return image;
        };
    }
}

package io.droptracker.ui.overlays.popup;

import io.droptracker.models.EventPopupCard;
import io.droptracker.models.api.EventNotification;
import io.droptracker.service.EventNotificationService.Toast;
import net.runelite.client.ui.FontManager;

import javax.annotation.Nullable;
import java.awt.*;
import java.awt.image.BufferedImage;
import java.util.*;
import java.util.List;

/**
 * Shared painting helpers for the pop-up renderers: palette, fonts, easing,
 * text fitting and sprite drawing. Everything here runs on the client thread
 * inside an overlay's render, so it stays allocation-light: derived fonts are
 * cached and nothing touches the ItemManager directly.
 */
final class PopupPaint {
    /** The game's own orange, as on the collection log caption. */
    static final Color OSRS_ORANGE = new Color(0xff, 0x98, 0x1f);
    static final Color INK = new Color(0x0b, 0x09, 0x06);
    static final Color TEXT = new Color(0xef, 0xe6, 0xd2);
    static final Color TEXT_MUTED = new Color(0xc8, 0xb8, 0x9a);
    static final Color VALUE = new Color(0xff, 0xd2, 0x4a);

    private static final Map<Float, Font> BOLD_SIZES = new HashMap<>();

    private PopupPaint() {
    }

    /* ---------------- palette ---------------- */

    /** One accent per kind of news, in the spirit of rarity tiers. */
    static Color accent(EventPopupCard.Kind kind) {
        switch (kind) {
            case PROGRESS:
                return new Color(0xa8, 0xa8, 0x9e);
            case COMPLETE:
                return new Color(0x5f, 0xc8, 0x6a);
            case TILE:
                return new Color(0xe8, 0xc5, 0x47);
            case LINE:
                return new Color(0xff, 0x8c, 0x42);
            case BLACKOUT:
                return new Color(0xe8, 0x3f, 0x6f);
            case LEAD:
                return new Color(0xb0, 0x6a, 0xf0);
            case STARTED:
                return new Color(0x3d, 0x9b, 0xe9);
            case ENDED:
                return new Color(0xd8, 0xc9, 0xa3);
            case BOARD:
                return new Color(0x3f, 0xc9, 0xb6);
            case ROLL:
                return new Color(0xff, 0xb8, 0x3f);
            case DIGEST:
            default:
                return new Color(0x8f, 0xa7, 0xc7);
        }
    }

    /** Linear blend: t = 0 is {@code a}, t = 1 is {@code b}. */
    static Color mix(Color a, Color b, float t) {
        float u = 1f - t;
        return new Color(
            Math.round(a.getRed() * u + b.getRed() * t),
            Math.round(a.getGreen() * u + b.getGreen() * t),
            Math.round(a.getBlue() * u + b.getBlue() * t));
    }

    static Color alpha(Color c, int alpha) {
        return new Color(c.getRed(), c.getGreen(), c.getBlue(), Math.max(0, Math.min(255, alpha)));
    }

    /* ---------------- content ---------------- */

    /**
     * The toast's structured card; toasts built without one (nothing today,
     * but the constructor allows it) get a card from their title and body.
     */
    static EventPopupCard cardOf(Toast toast) {
        if (toast.getCard() != null) {
            return toast.getCard();
        }
        EventPopupCard.Kind kind = toast.getPriority() == EventNotification.Priority.HIGH
            ? EventPopupCard.Kind.TILE
            : toast.getPriority() == EventNotification.Priority.LOW
                ? EventPopupCard.Kind.PROGRESS : EventPopupCard.Kind.COMPLETE;
        return new EventPopupCard(kind, toast.getTitle(), toast.getBody());
    }

    @Nullable
    static Integer iconOf(Toast toast) {
        Integer id = toast.getIconItemId();
        return id != null && id > 0 ? id : null;
    }

    /* ---------------- fonts ---------------- */

    static Font bold() {
        return FontManager.getRunescapeBoldFont();
    }

    static Font plain() {
        return FontManager.getRunescapeFont();
    }

    static Font small() {
        return FontManager.getRunescapeSmallFont();
    }

    /** The RuneScape bold face at another size; cached, deriveFont isn't free. */
    static Font bold(float size) {
        Font font = BOLD_SIZES.get(size);
        if (font == null) {
            font = FontManager.getRunescapeBoldFont().deriveFont(size);
            BOLD_SIZES.put(size, font);
        }
        return font;
    }

    /* ---------------- timing ---------------- */

    static float clamp01(float v) {
        return v < 0f ? 0f : (v > 1f ? 1f : v);
    }

    /** 0..1 progress through a window starting {@code delay} ms after birth. */
    static float phase(long ageMs, long delay, long duration) {
        return clamp01((ageMs - delay) / (float) duration);
    }

    static float easeOutCubic(float t) {
        float u = 1f - t;
        return 1f - u * u * u;
    }

    /** Overshoots past 1 then settles; {@code s} sets how far. */
    static float easeOutBack(float t, float s) {
        float u = t - 1f;
        return 1f + (s + 1f) * u * u * u + s * u * u;
    }

    /** 1 while the toast is fresh, falling to 0 over its last {@code fadeMs}. */
    static float fadeOut(Toast toast, long now, long fadeMs) {
        long remaining = toast.remainingMs(now);
        return remaining < fadeMs ? clamp01(remaining / (float) fadeMs) : 1f;
    }

    static void setAlpha(Graphics2D g, float alpha) {
        g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, clamp01(alpha)));
    }

    /* ---------------- text ---------------- */

    static void shadowed(Graphics2D g, String text, int x, int y, Color color) {
        g.setColor(Color.BLACK);
        g.drawString(text, x + 1, y + 1);
        g.setColor(color);
        g.drawString(text, x, y);
    }

    static void shadowedCentered(Graphics2D g, String text, int centerX, int y, Color color) {
        int width = g.getFontMetrics().stringWidth(text);
        shadowed(g, text, centerX - width / 2, y, color);
    }

    static void shadowedRight(Graphics2D g, String text, int rightX, int y, Color color) {
        int width = g.getFontMetrics().stringWidth(text);
        shadowed(g, text, rightX - width, y, color);
    }

    static String ellipsize(@Nullable String text, FontMetrics fm, int width) {
        if (text == null) {
            return "";
        }
        if (fm.stringWidth(text) <= width) {
            return text;
        }
        String out = text;
        while (out.length() > 1 && fm.stringWidth(out + "…") > width) {
            out = out.substring(0, out.length() - 1);
        }
        return out + "…";
    }

    /** Word-wrap into at most {@code maxLines}; the last line is ellipsized if anything is dropped. */
    static List<String> wrap(@Nullable String text, FontMetrics fm, int width, int maxLines) {
        List<String> lines = new ArrayList<>();
        if (text == null || text.isEmpty()) {
            return lines;
        }
        StringBuilder current = new StringBuilder();
        boolean clipped = false;
        for (String word : text.split(" ")) {
            String candidate = current.length() == 0 ? word : current + " " + word;
            if (fm.stringWidth(candidate) <= width || current.length() == 0) {
                current = new StringBuilder(candidate);
            } else if (lines.size() == maxLines - 1) {
                clipped = true;
                break;
            } else {
                lines.add(current.toString());
                current = new StringBuilder(word);
            }
        }
        if (current.length() > 0 && lines.size() < maxLines) {
            lines.add(current.toString());
        }
        if (!lines.isEmpty()) {
            int last = lines.size() - 1;
            String tail = lines.get(last);
            if (clipped) {
                tail += "…";
            }
            lines.set(last, ellipsize(tail, fm, width));
        }
        return lines;
    }

    /**
     * The biggest bold size from {@code max} down to {@code min} at which the
     * text fits {@code width}; the caller ellipsizes if even {@code min} won't.
     */
    static Font fitBold(Graphics2D g, String text, int width, float max, float min) {
        for (float size = max; size > min; size -= 1f) {
            Font font = bold(size);
            if (g.getFontMetrics(font).stringWidth(text) <= width) {
                return font;
            }
        }
        return bold(min);
    }

    /* ---------------- sprites ---------------- */

    /**
     * Draws an item sprite fitted into a {@code box}-sized square, centred,
     * aspect kept (sprites are 36x32). Scales up as well as down, smoothly.
     */
    static void drawSprite(Graphics2D g, BufferedImage sprite, int x, int y, int box) {
        int w = Math.max(sprite.getWidth(), 1);
        int h = Math.max(sprite.getHeight(), 1);
        float scale = Math.min((float) box / w, (float) box / h);
        int nw = Math.max(Math.round(w * scale), 1);
        int nh = Math.max(Math.round(h * scale), 1);
        Object previous = g.getRenderingHint(RenderingHints.KEY_INTERPOLATION);
        g.setRenderingHint(RenderingHints.KEY_INTERPOLATION,
            RenderingHints.VALUE_INTERPOLATION_BILINEAR);
        g.drawImage(sprite, x + (box - nw) / 2, y + (box - nh) / 2, nw, nh, null);
        g.setRenderingHint(RenderingHints.KEY_INTERPOLATION,
            previous != null ? previous : RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
    }
}

package io.droptracker.ui.overlays.popup;

import io.droptracker.service.EventNotificationService.Toast;

import java.awt.Graphics2D;

/**
 * One pop-up layout. Called every frame from an overlay's render on the
 * client thread; animation is driven purely by the toast's age, so a
 * renderer holds no per-toast state.
 */
public interface PopupRenderer {
    /** Width of a stand-alone card. HUD nudges ignore it and fill the HUD's width. */
    int preferredWidth();

    /** Space left above this card when it stacks under another (or under the HUD). */
    default int gap() {
        return 6;
    }

    /** How many cards of this style may show at once. */
    default int maxVisible() {
        return 3;
    }

    /**
     * Paints the toast with its top-left corner at ({@code x}, {@code top})
     * and returns the height it takes up in the stack.
     */
    int draw(Graphics2D g, Toast toast, int x, int top, int width, long now);
}

package io.droptracker.ui.overlays.popup;

import io.droptracker.models.EventPopupStyle;
import io.droptracker.util.*;

import javax.inject.*;
import java.awt.image.BufferedImage;
import java.util.*;
import java.util.function.*;

/** The renderer for each pop-up style; renderers are stateless, so one each. */
@Singleton
public class PopupRenderers {
    private final Map<EventPopupStyle, PopupRenderer> popups = new EnumMap<>(EventPopupStyle.class);

    @Inject
    public PopupRenderers(ItemImageCache images, RemoteImageCache remoteImages) {
        this(id -> images.get(id, null), path -> remoteImages.get(path, null));
    }

    /** Test seam: any sprite and icon lookups (the caches need a live client). */
    PopupRenderers(IntFunction<BufferedImage> items, Function<String, BufferedImage> paths) {
        PopupIcons icons = PopupIcons.of(items, paths);
        popups.put(EventPopupStyle.SHOWCASE, new ShowcaseRenderer(icons));
        popups.put(EventPopupStyle.BANNER, new BannerRenderer(icons));
    }

    public PopupRenderer popup(EventPopupStyle style) {
        return popups.getOrDefault(style, popups.get(EventPopupStyle.BANNER));
    }
}

package io.droptracker.ui.overlays.popup;

import lombok.AccessLevel;
import lombok.AllArgsConstructor;
import io.droptracker.models.EventPopupCard;
import io.droptracker.models.api.EventNotification;
import io.droptracker.service.EventNotificationService.Toast;

import java.awt.*;
import java.awt.geom.AffineTransform;
import java.awt.image.BufferedImage;
import javax.annotation.Nullable;
import java.util.Collections;
import java.util.List;

/**
 * The showcase panel, after the Collection Log Popup Enhanced plugin's
 * layout: a small orange caption, a big headline, a progress line, up to
 * four "label / value" stats in the corners and the icon in a framed box
 * hanging off the bottom edge between them. The panel folds open, the icon
 * pops in after it, and big moments get one light sweep across the face.
 * Each kind of news gets its own tinted panel and frame, like rarity tiers.
 */
@AllArgsConstructor(access = AccessLevel.PACKAGE)
class ShowcaseRenderer implements PopupRenderer {
    static final int WIDTH = 330;
    private static final int PAD = 12;
    private static final int BOX = 54;

    private static final long FOLD_MS = 320;
    private static final long ICON_DELAY_MS = 220;
    private static final long ICON_POP_MS = 340;
    private static final long BAR_DELAY_MS = 260;
    private static final long BAR_FILL_MS = 700;
    private static final long SWEEP_DELAY_MS = 380;
    private static final long SWEEP_MS = 900;
    private static final long FADE_MS = 600;

    private final PopupIcons icons;

    @Override
    public int preferredWidth() {
        return WIDTH;
    }

    @Override
    public int gap() {
        return 8;
    }

    @Override
    public int maxVisible() {
        return 2;
    }

    @Override
    public int draw(Graphics2D g, Toast toast, int x, int top, int w, long now) {
        EventPopupCard card = PopupPaint.cardOf(toast);
        long age = now - toast.getCreatedAt();
        Color accent = PopupPaint.accent(card.getKind());

        /* ---- fonts and metrics ---- */
        Font captionFont = PopupPaint.bold();
        Font labelFont = PopupPaint.small();
        Font valueFont = PopupPaint.bold();
        Font detailFont = PopupPaint.small();
        FontMetrics captionFm = g.getFontMetrics(captionFont);
        FontMetrics labelFm = g.getFontMetrics(labelFont);
        FontMetrics valueFm = g.getFontMetrics(valueFont);
        FontMetrics detailFm = g.getFontMetrics(detailFont);

        int innerWidth = w - PAD * 2;
        String moreText = toast.getMoreCount() > 0 ? "+" + toast.getMoreCount() + " more" : null;
        String note = card.getNote();
        // The caption is centred; keep it clear of whichever corner is wider.
        int corner = Math.max(moreText != null ? detailFm.stringWidth(moreText) : 0,
            note != null ? detailFm.stringWidth(note) : 0);
        int captionRoom = innerWidth - (corner > 0 ? 2 * (corner + 6) : 0);
        String caption = PopupPaint.ellipsize(card.getCaption(), captionFm, captionRoom);
        Font headlineFont = PopupPaint.fitBold(g, card.getHeadline(), innerWidth, 25f, 16f);
        FontMetrics headlineFm = g.getFontMetrics(headlineFont);
        String headline = PopupPaint.ellipsize(card.getHeadline(), headlineFm, innerWidth);
        List<String> detail = card.getDetail() != null
            ? PopupPaint.wrap(card.getDetail(), detailFm, innerWidth,
                card.getKind() == EventPopupCard.Kind.DIGEST ? 3 : 1)
            : Collections.emptyList();

        BufferedImage sprite = icons.forToast(toast);
        boolean stats = card.hasStats();
        boolean secondRow = card.hasSecondRow();
        int statWidth = (w - BOX) / 2 - PAD - 6;

        /* ---- measure ---- */
        int captionY = top + 6 + captionFm.getAscent();
        int headlineY = captionY + captionFm.getDescent() + 1 + headlineFm.getAscent();
        int y = headlineY + headlineFm.getDescent();
        int detailY = y + detailFm.getAscent();
        y += detail.size() * detailFm.getHeight();
        int barY = y + 6;
        int barH = 3;
        y = barY + barH;
        int rowH = labelFm.getAscent() + labelFm.getDescent() + valueFm.getAscent() + valueFm.getDescent();
        int statsTop = y + 6;
        if (stats) {
            y = statsTop + rowH + (secondRow ? 4 + rowH : 0);
        }
        int panelBottom = y + 8;
        int panelH = panelBottom - top;
        // Hang the icon off the bottom edge, but never over the bar.
        int boxTop = Math.max(barY + barH + 5, panelBottom - BOX + BOX * 2 / 5);
        int total = Math.max(panelH, boxTop + BOX - top);

        Composite previousComposite = g.getComposite();
        AffineTransform previousTransform = g.getTransform();
        Shape previousClip = g.getClip();
        float fade = PopupPaint.fadeOut(toast, now, FADE_MS);

        /* ---- panel: folds open around its middle ---- */
        float fold = PopupPaint.easeOutBack(PopupPaint.phase(age, 0, FOLD_MS), 1.2f);
        float foldIn = PopupPaint.phase(age, 0, FOLD_MS / 2);
        PopupPaint.setAlpha(g, fade * foldIn);
        int midY = top + panelH / 2;
        g.translate(0, midY);
        g.scale(1.0, Math.max(fold, 0.01f));
        g.translate(0, -midY);

        paintPanel(g, x, top, w, panelH, accent);

        g.setFont(captionFont);
        PopupPaint.shadowedCentered(g, caption, x + w / 2, captionY, PopupPaint.OSRS_ORANGE);
        g.setFont(detailFont);
        int cornerY = top + 7 + detailFm.getAscent();
        if (note != null) {
            PopupPaint.shadowed(g, note, x + PAD - 3, cornerY, PopupPaint.TEXT_MUTED);
        }
        if (moreText != null) {
            PopupPaint.shadowedRight(g, moreText, x + w - PAD + 3, cornerY, accent);
        }
        g.setFont(headlineFont);
        PopupPaint.shadowedCentered(g, headline, x + w / 2, headlineY,
            PopupPaint.mix(accent, Color.WHITE, 0.12f));
        g.setFont(detailFont);
        int lineY = detailY;
        for (String line : detail) {
            PopupPaint.shadowedCentered(g, line, x + w / 2, lineY, PopupPaint.TEXT_MUTED);
            lineY += detailFm.getHeight();
        }

        paintBar(g, card, x, w, barY, barH, accent, age);

        if (stats) {
            int row1 = statsTop;
            int row2 = statsTop + rowH + 4;
            paintStat(g, card.getLeftLabel(), card.getLeftValue(), x + PAD, row1, statWidth,
                false, labelFont, valueFont);
            paintStat(g, card.getRightLabel(), card.getRightValue(), x + w - PAD, row1, statWidth,
                true, labelFont, valueFont);
            paintStat(g, card.getLeft2Label(), card.getLeft2Value(), x + PAD, row2, statWidth,
                false, labelFont, valueFont);
            paintStat(g, card.getRight2Label(), card.getRight2Value(), x + w - PAD, row2, statWidth,
                true, labelFont, valueFont);
        }

        if (toast.getPriority() == EventNotification.Priority.HIGH) {
            paintSweep(g, x, top, w, panelH, age);
        }
        g.setTransform(previousTransform);
        g.setClip(previousClip);

        /* ---- icon: pops in once the panel is open ---- */
        float t = PopupPaint.phase(age, ICON_DELAY_MS, ICON_POP_MS);
        if (t > 0f) {
            float scale = 0.4f + 0.6f * PopupPaint.easeOutBack(t, 1.9f);
            PopupPaint.setAlpha(g, fade * Math.min(1f, t * 2f));
            int boxX = x + (w - BOX) / 2;
            double cx = boxX + BOX / 2.0;
            double cy = boxTop + BOX / 2.0;
            g.translate(cx, cy);
            g.scale(scale, scale);
            g.translate(-cx, -cy);
            paintIconBox(g, boxX, boxTop, BOX, accent);
            if (sprite != null) {
                PopupPaint.drawSprite(g, sprite, boxX + 6, boxTop + 6, BOX - 12);
            } else {
                // No item or task icon: the kind's emblem, so the box never sits empty.
                int glyph = BOX * 11 / 20;
                PopupGlyphs.draw(g, card.getKind(), boxX + (BOX - glyph) / 2, boxTop + (BOX - glyph) / 2,
                    glyph, accent);
            }
            g.setTransform(previousTransform);
        }

        g.setComposite(previousComposite);
        return total;
    }

    /** One "label / value" corner; {@code right} anchors it to {@code anchorX} from the right. */
    private static void paintStat(Graphics2D g, @Nullable String label, @Nullable String value,
                                  int anchorX, int rowTop, int width, boolean right,
                                  Font labelFont, Font valueFont) {
        if (value == null) {
            return;
        }
        FontMetrics labelFm = g.getFontMetrics(labelFont);
        FontMetrics valueFm = g.getFontMetrics(valueFont);
        int labelY = rowTop + labelFm.getAscent();
        int valueY = labelY + labelFm.getDescent() + valueFm.getAscent();
        g.setFont(labelFont);
        String l = PopupPaint.ellipsize(label, labelFm, width);
        g.setFont(valueFont);
        String v = PopupPaint.ellipsize(value, valueFm, width);
        g.setFont(labelFont);
        if (right) {
            PopupPaint.shadowedRight(g, l, anchorX, labelY, PopupPaint.TEXT_MUTED);
        } else {
            PopupPaint.shadowed(g, l, anchorX, labelY, PopupPaint.TEXT_MUTED);
        }
        g.setFont(valueFont);
        if (right) {
            PopupPaint.shadowedRight(g, v, anchorX, valueY, PopupPaint.VALUE);
        } else {
            PopupPaint.shadowed(g, v, anchorX, valueY, PopupPaint.VALUE);
        }
    }

    /* ---------------- pieces ---------------- */

    private void paintPanel(Graphics2D g, int x, int y, int w, int h, Color accent) {
        Color face = PopupPaint.mix(accent, PopupPaint.INK, 0.80f);
        Color faceLow = PopupPaint.mix(accent, PopupPaint.INK, 0.87f);
        g.setPaint(new GradientPaint(0, y, PopupPaint.alpha(face, 242), 0, y + h,
            PopupPaint.alpha(faceLow, 242)));
        g.fillRect(x, y, w, h);
        g.setColor(PopupPaint.INK);
        g.drawRect(x, y, w - 1, h - 1);
        g.setColor(accent);
        g.drawRect(x + 1, y + 1, w - 3, h - 3);
        g.drawRect(x + 2, y + 2, w - 5, h - 5);
        g.setColor(PopupPaint.mix(accent, PopupPaint.INK, 0.55f));
        g.drawRect(x + 3, y + 3, w - 7, h - 7);
    }

    /** The progress line: task progress when the card has it, else a plain rule. */
    private void paintBar(Graphics2D g, EventPopupCard card, int x, int w, int y, int h,
                          Color accent, long age) {
        int inset = Math.round(w * 0.06f);
        int left = x + inset;
        int barW = w - inset * 2;
        Color fill = accent;
        g.setColor(PopupPaint.mix(accent, PopupPaint.INK, 0.65f));
        g.fillRect(left, y, barW, h);
        float fraction = card.fraction();
        if (fraction < 0f) {
            fraction = 1f; // no progress to show: a full rule, drawn in
        }
        float grow = PopupPaint.easeOutCubic(PopupPaint.phase(age, BAR_DELAY_MS, BAR_FILL_MS));
        int filled = Math.round(barW * fraction * grow);
        g.setColor(card.fraction() < 0f ? PopupPaint.alpha(fill, 150) : fill);
        g.fillRect(left, y, filled, h);
    }

    private void paintIconBox(Graphics2D g, int x, int y, int box, Color accent) {
        g.setColor(PopupPaint.mix(accent, PopupPaint.INK, 0.84f));
        g.fillRect(x, y, box, box);
        g.setColor(PopupPaint.INK);
        g.drawRect(x, y, box - 1, box - 1);
        g.setColor(accent);
        g.drawRect(x + 1, y + 1, box - 3, box - 3);
        g.drawRect(x + 2, y + 2, box - 5, box - 5);
        paintCorners(g, x, y, box, box, box >= 44 ? 6 : 4, accent);
    }

    /** Stepped corner ornaments, drawn inward from each corner. */
    private static void paintCorners(Graphics2D g, int x, int y, int w, int h, int size, Color color) {
        g.setColor(color);
        int s = size;
        g.fillRect(x + 3, y + 3, s, 2);
        g.fillRect(x + 3, y + 3, 2, s);
        g.fillRect(x + w - 3 - s, y + 3, s, 2);
        g.fillRect(x + w - 5, y + 3, 2, s);
        g.fillRect(x + 3, y + h - 5, s, 2);
        g.fillRect(x + 3, y + h - 3 - s, 2, s);
        g.fillRect(x + w - 3 - s, y + h - 5, s, 2);
        g.fillRect(x + w - 5, y + h - 3 - s, 2, s);
    }

    /** One soft light band across the face, for the moments worth a second look. */
    private static void paintSweep(Graphics2D g, int x, int y, int w, int h, long age) {
        float t = PopupPaint.phase(age, SWEEP_DELAY_MS, SWEEP_MS);
        if (t <= 0f || t >= 1f) {
            return;
        }
        int band = 36;
        int bx = x - band * 2 + Math.round((w + band * 3) * t);
        g.clipRect(x + 3, y + 3, w - 6, h - 6);
        Polygon shape = new Polygon(
            new int[]{bx, bx + band, bx + band - h / 2, bx - h / 2},
            new int[]{y, y, y + h, y + h}, 4);
        g.setColor(new Color(255, 255, 255, 38));
        g.fill(shape);
    }
}

package io.droptracker.ui.pages;

import lombok.RequiredArgsConstructor;
import io.droptracker.DropTrackerConfig;
import io.droptracker.api.DropTrackerApi;
import io.droptracker.models.api.GroupConfig;
import io.droptracker.models.submissions.*;
import io.droptracker.service.SubmissionManager;
import io.droptracker.ui.*;
import io.droptracker.ui.components.*;
import net.runelite.client.ui.*;

import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;
import java.awt.event.*;
import java.time.*;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * The "Activity" tab: this session's submission feed (promoted from the old buried
 * "API" tab), a compact session stats row, and the per-group configuration summary.
 */
@RequiredArgsConstructor
public class ActivityPanel {
    private final DropTrackerConfig config;
    private final DropTrackerApi api;
    private final SubmissionManager submissionManager;
    private final DropTrackerPanel mainPanel;

    private JPanel activityRoot;
    private JPanel statsCard;
    private JPanel feedCard;
    private JPanel feedListPanel;
    private Timer statusUpdateTimer;

    private JPanel groupConfigPanel;
    private JPanel groupsContainerPanel;
    private JScrollPane groupsScrollPane;
    private final Map<String, Boolean> groupExpandStates = new HashMap<>();

    public JPanel create() {
        activityRoot = DropTrackerTheme.vbox(DropTrackerTheme.SURFACE_0);
        activityRoot.setBorder(new EmptyBorder(5, 0, 5, 0));

        statsCard = buildStatsCard();
        feedCard = buildFeedCard();
        JPanel configCard = buildGroupConfigCard();

        activityRoot.add(statsCard);
        activityRoot.add(DropTrackerTheme.gap(6));
        activityRoot.add(feedCard);
        activityRoot.add(DropTrackerTheme.gap(6));
        activityRoot.add(configCard);
        activityRoot.add(Box.createVerticalGlue());

        refresh();

        if (config.pollUpdates()) {
            statusUpdateTimer = new Timer(10000, e -> {
                updateStatusLabel();
                refreshStatistics();
                refreshGroupConfigs();
                if (config.useApi() && submissionManager.hasActiveSubmissions()) {
                    submissionManager.checkPendingStatuses();
                    refreshSubmissions();
                }
            });
            statusUpdateTimer.start();
        }

        JPanel wrapperPanel = new JPanel(new BorderLayout());
        wrapperPanel.setBackground(DropTrackerTheme.SURFACE_0);
        wrapperPanel.add(activityRoot, BorderLayout.CENTER);
        return wrapperPanel;
    }

    /* ===================== Session stats ===================== */

    private JPanel buildStatsCard() {
        JPanel card = DropTrackerTheme.vbox(DropTrackerTheme.SURFACE_1);
        card.setBorder(DropTrackerTheme.cardBorder(8, 8, 8, 8));
        card.setMaximumSize(new Dimension(PluginPanel.PANEL_WIDTH, 70));
        card.setAlignmentX(Component.LEFT_ALIGNMENT);

        rebuildStatsCard(card);
        return card;
    }

    private void rebuildStatsCard(JPanel card) {
        card.removeAll();

        JLabel title = DropTrackerTheme.label("This Session", FontManager.getRunescapeBoldFont(), DropTrackerTheme.TEXT);
        title.setAlignmentX(Component.CENTER_ALIGNMENT);
        card.add(title);
        card.add(DropTrackerTheme.gap(4));

        int sent = submissionManager.getTotalSubmissions();
        int processed = submissionManager.getNotificationsSent();
        int failed = submissionManager.getFailedSubmissions();

        JPanel row = new JPanel(new FlowLayout(FlowLayout.CENTER, 8, 0));
        row.setBackground(DropTrackerTheme.SURFACE_1);
        row.setMaximumSize(new Dimension(PluginPanel.PANEL_WIDTH - 30, 16));
        row.add(compactStat("Sent", String.valueOf(sent), DropTrackerTheme.GOLD));
        row.add(compactStat("Processed", String.valueOf(processed), DropTrackerTheme.GREEN));
        row.add(compactStat("Failed", String.valueOf(failed), DropTrackerTheme.RED));
        row.setToolTipText("Submissions that qualified for notifications in your groups this session");
        card.add(row);

        JLabel gpLabel = DropTrackerTheme.label("Session loot: " + formatValue(submissionManager.getTotalValue()) + " GP", FontManager.getRunescapeSmallFont(), DropTrackerTheme.TEXT_MUTED);
        gpLabel.setAlignmentX(Component.CENTER_ALIGNMENT);
        card.add(DropTrackerTheme.gap(3));
        card.add(gpLabel);

        card.revalidate();
        card.repaint();
    }

    private JPanel compactStat(String label, String value, Color valueColor) {
        JPanel stat = new JPanel(new FlowLayout(FlowLayout.LEFT, 3, 0));
        stat.setBackground(DropTrackerTheme.SURFACE_1);

        JLabel labelComponent = DropTrackerTheme.label(label, FontManager.getRunescapeSmallFont(), DropTrackerTheme.TEXT_MUTED);

        JLabel valueComponent = DropTrackerTheme.label(value, FontManager.getRunescapeSmallFont(), valueColor);

        stat.add(labelComponent);
        stat.add(valueComponent);
        return stat;
    }

    private String formatValue(long value) {
        if (value >= 1_000_000) {
            return String.format("%.1fM", value / 1_000_000.0);
        } else if (value >= 1_000) {
            return String.format("%.1fK", value / 1_000.0);
        }
        return String.valueOf(value);
    }

    /* ===================== Submission feed ===================== */

    private JPanel buildFeedCard() {
        JPanel card = DropTrackerTheme.vbox(DropTrackerTheme.SURFACE_1);
        card.setBorder(DropTrackerTheme.cardBorder(8, 8, 8, 8));
        card.setMaximumSize(new Dimension(PluginPanel.PANEL_WIDTH, 320));
        card.setAlignmentX(Component.LEFT_ALIGNMENT);

        JLabel title = DropTrackerTheme.label("Submission Feed", FontManager.getRunescapeBoldFont(), DropTrackerTheme.TEXT);
        title.setAlignmentX(Component.CENTER_ALIGNMENT);
        card.add(title);
        card.add(DropTrackerTheme.gap(4));

        feedListPanel = DropTrackerTheme.vbox(DropTrackerTheme.SURFACE_1);

        JScrollPane scrollPane = new JScrollPane(feedListPanel);
        scrollPane.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
        scrollPane.setVerticalScrollBarPolicy(ScrollPaneConstants.VERTICAL_SCROLLBAR_AS_NEEDED);
        scrollPane.setBorder(null);
        scrollPane.setBackground(DropTrackerTheme.SURFACE_1);
        scrollPane.getViewport().setBackground(DropTrackerTheme.SURFACE_1);
        scrollPane.setPreferredSize(new Dimension(PluginPanel.PANEL_WIDTH - 30, 260));
        scrollPane.setMaximumSize(new Dimension(PluginPanel.PANEL_WIDTH - 30, 280));
        card.add(scrollPane);

        return card;
    }

    public void refreshSubmissions() {
        if (feedListPanel == null) {
            return;
        }

        feedListPanel.removeAll();

        List<ValidSubmission> submissions = submissionManager.getValidSubmissions();
        if (submissions != null && !submissions.isEmpty()) {
            // Newest first: submissions are appended chronologically.
            List<ValidSubmission> newestFirst = new ArrayList<>(submissions);
            Collections.reverse(newestFirst);
            for (ValidSubmission submission : newestFirst) {
                feedListPanel.add(createFeedRow(submission));
                feedListPanel.add(DropTrackerTheme.gap(3));
            }
        } else {
            JLabel emptyLabel = DropTrackerTheme.label("<html>Qualifying drops and achievements will appear here as you receive them. Failed sends can be retried.</html>", FontManager.getRunescapeSmallFont(), DropTrackerTheme.TEXT_MUTED);
            emptyLabel.setBorder(new EmptyBorder(5, 5, 5, 5));
            feedListPanel.add(emptyLabel);
        }

        feedListPanel.revalidate();
        feedListPanel.repaint();
    }

    private JPanel createFeedRow(ValidSubmission submission) {
        JPanel row = new JPanel(new BorderLayout(5, 0));
        row.setBackground(DropTrackerTheme.SURFACE_2);
        row.setBorder(DropTrackerTheme.cardBorder(4, 5, 4, 5));
        row.setPreferredSize(new Dimension(PluginPanel.PANEL_WIDTH - 40, 42));
        row.setMaximumSize(new Dimension(PluginPanel.PANEL_WIDTH - 40, 42));

        // Type indicator
        JLabel typeLabel = DropTrackerTheme.label(submission.getTypeShortLabel(), FontManager.getRunescapeSmallFont(), typeColor(submission.getTypeShortLabel()));
        typeLabel.setHorizontalAlignment(SwingConstants.CENTER);
        typeLabel.setPreferredSize(new Dimension(32, 32));
        row.add(typeLabel, BorderLayout.WEST);

        // Name + timestamp
        JPanel textPanel = DropTrackerTheme.vbox(DropTrackerTheme.SURFACE_2);

        String displayText = submission.getDisplayText();
        JLabel nameLabel = DropTrackerTheme.label(displayText.length() > 24 ? displayText.substring(0, 21) + "..." : displayText, FontManager.getRunescapeSmallFont(), DropTrackerTheme.TEXT);
        nameLabel.setAlignmentX(Component.LEFT_ALIGNMENT);

        JPanel metaRow = new JPanel(new FlowLayout(FlowLayout.LEFT, 4, 0));
        metaRow.setBackground(DropTrackerTheme.SURFACE_2);
        metaRow.setAlignmentX(Component.LEFT_ALIGNMENT);

        String timestamp = formatReceivedTime(submission.getTimeReceived());
        if (timestamp != null) {
            JLabel timeLabel = DropTrackerTheme.label(timestamp, FontManager.getRunescapeSmallFont(), DropTrackerTheme.TEXT_MUTED);
            metaRow.add(timeLabel);
        }
        metaRow.add(statusChip(submission.getStatus()));

        textPanel.add(nameLabel);
        textPanel.add(metaRow);
        row.add(textPanel, BorderLayout.CENTER);

        // Actions: retry for failed submissions, dismiss for everything
        JPanel actions = new JPanel(new FlowLayout(FlowLayout.RIGHT, 2, 0));
        actions.setBackground(DropTrackerTheme.SURFACE_2);

        if (submission.getStatus() == SubmissionStatus.FAILED) {
            // Painted icon: the RuneScape fonts have no "↻" glyph, so its
            // colour rides on the icon rather than the foreground.
            JButton retryButton = smallActionButton("", "Retry sending this submission");
            retryButton.setIcon(PanelIcons.refresh(DropTrackerTheme.EMBER, 11));
            retryButton.setForeground(DropTrackerTheme.EMBER);
            retryButton.addActionListener(e -> {
                submissionManager.retrySubmission(submission);
                refreshSubmissions();
            });
            actions.add(retryButton);
        }

        JButton dismissButton = smallActionButton("×", "Remove from list");
        dismissButton.setForeground(DropTrackerTheme.RED);
        dismissButton.addActionListener(e -> {
            submissionManager.removeSubmission(submission);
            refresh();
        });
        actions.add(dismissButton);

        row.add(actions, BorderLayout.EAST);

        row.setToolTipText(buildSubmissionTooltip(submission));
        return row;
    }

    private JButton smallActionButton(String glyph, String tooltip) {
        JButton button = new JButton(glyph);
        button.setFont(FontManager.getRunescapeSmallFont());
        button.setPreferredSize(new Dimension(20, 20));
        button.setMargin(new Insets(0, 0, 0, 0));
        button.setFocusPainted(false);
        button.setContentAreaFilled(true);
        button.setOpaque(true);
        button.setBackground(DropTrackerTheme.SURFACE_3);
        button.setBorder(BorderFactory.createLineBorder(DropTrackerTheme.SURFACE_3, 1));
        button.setToolTipText(tooltip);
        return button;
    }

    private JLabel statusChip(SubmissionStatus status) {
        if (status == null) {
            return DropTrackerTheme.chip("Unknown", DropTrackerTheme.STONE);
        }
        switch (status) {
            case PROCESSED:
                return DropTrackerTheme.chip("Processed", DropTrackerTheme.GREEN);
            case SENT:
                return DropTrackerTheme.chip("Sent", DropTrackerTheme.GREEN);
            case FAILED:
                return DropTrackerTheme.chip("Failed", DropTrackerTheme.RED);
            case PENDING:
            case SENDING:
            case RETRYING:
            default:
                return DropTrackerTheme.chip("Pending", DropTrackerTheme.EMBER);
        }
    }

    private Color typeColor(String shortLabel) {
        switch (shortLabel) {
            case "DROP":
                return DropTrackerTheme.GOLD;
            case "CLOG":
                return DropTrackerTheme.EMBER;
            case "PB":
                return DropTrackerTheme.GOLD_BRIGHT;
            case "CA":
                return new Color(0xc98bd8);
            case "PET":
                return DropTrackerTheme.GREEN;
            case "LVL":
                return new Color(0x8fb8d8);
            case "QST":
                return DropTrackerTheme.TEXT_MUTED;
            default:
                return DropTrackerTheme.TEXT;
        }
    }

    private String buildSubmissionTooltip(ValidSubmission submission) {
        StringBuilder tooltip = new StringBuilder();
        tooltip.append("<html><div style='font-size: 10px; line-height: 1.2; padding: 3px;'>");

        tooltip.append("<div style='color: #ffb83f; font-weight: bold; margin-bottom: 3px;'>")
               .append(submission.getTypeShortLabel()).append(" SUBMISSION</div>");

        tooltip.append("<div style='color: #efe6d2; margin-bottom: 3px;'>")
               .append(submission.getDisplayText()).append("</div>");

        SubmissionStatus status = submission.getStatus();
        String statusColor = status != null ? status.getHexColor() : "#808080";
        tooltip.append("<div style='color: ").append(statusColor).append("; margin-bottom: 3px;'>")
               .append("Status: ").append(submission.getStatusDescription()).append("</div>");

        if (submission.getGroupIds() != null && submission.getGroupIds().length > 0) {
            tooltip.append("<div style='color: #d8c9a3; margin-bottom: 3px;'>")
                   .append("Configured for ").append(submission.getGroupIds().length).append(" group(s)</div>");
        }

        String receivedAt = formatReceivedTime(submission.getTimeReceived());
        if (receivedAt != null) {
            tooltip.append("<div style='color: #d8c9a3; margin-bottom: 3px;'>")
                   .append("Received: ").append(receivedAt).append("</div>");
        }

        if (submission.getRetryAttempts() > 0) {
            tooltip.append("<div style='color: #ff8c42; margin-bottom: 3px;'>")
                   .append("Retry attempts: ").append(submission.getRetryAttempts()).append("</div>");
        }

        if (submission.getLastFailureReason() != null && !submission.getLastFailureReason().isEmpty()) {
            tooltip.append("<div style='color: #e05c4d; margin-bottom: 3px;'>")
                   .append("Last failure: ").append(submission.getLastFailureReason()).append("</div>");
        }

        tooltip.append("</div></html>");
        return tooltip.toString();
    }

    /** Formats the ISO timeReceived value into a short human-readable time, or null. */
    private String formatReceivedTime(String isoTime) {
        if (isoTime == null || isoTime.isEmpty()) {
            return null;
        }
        try {
            java.time.LocalDateTime received = java.time.LocalDateTime.parse(isoTime, java.time.format.DateTimeFormatter.ISO_DATE_TIME);
            return received.format(java.time.format.DateTimeFormatter.ofPattern("HH:mm:ss"));
        } catch (Exception e) {
            return isoTime;
        }
    }

    /* ===================== Group config summary ===================== */

    private JPanel buildGroupConfigCard() {
        JPanel wrapperPanel = DropTrackerTheme.vbox(DropTrackerTheme.SURFACE_1);
        wrapperPanel.setMaximumSize(new Dimension(PluginPanel.PANEL_WIDTH - 20, 400));

        JPanel groupsContainer = DropTrackerTheme.vbox(DropTrackerTheme.SURFACE_1);

        // Built empty here; refreshGroupConfigs() populates it from the in-memory list.
        buildGroupConfigPanels(groupsContainer, null);

        groupsScrollPane = new JScrollPane(groupsContainer);
        groupsScrollPane.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
        groupsScrollPane.setVerticalScrollBarPolicy(ScrollPaneConstants.VERTICAL_SCROLLBAR_AS_NEEDED);
        groupsScrollPane.setBorder(null);
        groupsScrollPane.setBackground(DropTrackerTheme.SURFACE_1);
        groupsScrollPane.getViewport().setBackground(DropTrackerTheme.SURFACE_1);
        groupsScrollPane.setMaximumSize(new Dimension(PluginPanel.PANEL_WIDTH - 20, 150));
        groupsScrollPane.setPreferredSize(new Dimension(PluginPanel.PANEL_WIDTH - 20, 150));

        wrapperPanel.add(groupsScrollPane);
        this.groupsContainerPanel = groupsContainer;
        groupConfigPanel = createMainCollapsiblePanel("Group Configurations", wrapperPanel);

        return groupConfigPanel;
    }

    private JPanel createMainCollapsiblePanel(String title, JPanel content) {
        JPanel panel = DropTrackerTheme.vbox(DropTrackerTheme.SURFACE_1);
        panel.setBorder(DropTrackerTheme.cardBorder(8, 8, 8, 8));

        panel.setMaximumSize(new Dimension(PluginPanel.PANEL_WIDTH, 200));
        panel.setPreferredSize(new Dimension(PluginPanel.PANEL_WIDTH, 200));
        panel.setAlignmentX(Component.LEFT_ALIGNMENT);

        JPanel headerPanel = new JPanel(new BorderLayout());
        headerPanel.setBackground(DropTrackerTheme.SURFACE_1);

        JLabel titleLabel = DropTrackerTheme.label(title, FontManager.getRunescapeBoldFont(), DropTrackerTheme.TEXT);

        final ImageIcon expandedIcon = PanelElements.getExpandedIcon();
        final ImageIcon collapsedIcon = PanelElements.getCollapsedIcon();
        final JLabel toggleIcon = new JLabel(expandedIcon);

        headerPanel.add(titleLabel, BorderLayout.WEST);
        headerPanel.add(toggleIcon, BorderLayout.EAST);

        final boolean[] isCollapsed = {false};

        headerPanel.addMouseListener(new MouseAdapter() {
            @Override
            public void mouseClicked(MouseEvent e) {
                isCollapsed[0] = !isCollapsed[0];
                toggleIcon.setIcon(isCollapsed[0] ? collapsedIcon : expandedIcon);
                content.setVisible(!isCollapsed[0]);

                if (isCollapsed[0]) {
                    panel.setPreferredSize(new Dimension(PluginPanel.PANEL_WIDTH, headerPanel.getPreferredSize().height + 20));
                    panel.setMaximumSize(new Dimension(PluginPanel.PANEL_WIDTH, headerPanel.getPreferredSize().height + 20));
                } else {
                    panel.setPreferredSize(new Dimension(PluginPanel.PANEL_WIDTH, 200));
                    panel.setMaximumSize(new Dimension(PluginPanel.PANEL_WIDTH, 200));
                }

                panel.revalidate();
                panel.repaint();
            }

            @Override
            public void mouseEntered(MouseEvent e) {
                headerPanel.setCursor(new Cursor(Cursor.HAND_CURSOR));
            }

            @Override
            public void mouseExited(MouseEvent e) {
                headerPanel.setCursor(new Cursor(Cursor.DEFAULT_CURSOR));
            }
        });

        JSeparator separator = new JSeparator();
        separator.setBackground(DropTrackerTheme.SURFACE_3);
        separator.setForeground(DropTrackerTheme.SURFACE_3);

        panel.add(headerPanel);
        panel.add(separator);
        panel.add(content);

        return panel;
    }

    private void buildGroupConfigPanels(JPanel parentPanel, List<GroupConfig> groupConfigs) {
        parentPanel.removeAll();

        if (groupConfigs != null && !groupConfigs.isEmpty()) {
            for (GroupConfig groupConfig : groupConfigs) {
                JPanel groupContentPanel = createGroupConfigPanel(groupConfig);
                String groupTitle = groupConfig.getGroupName() + " (ID: " + groupConfig.getGroupId() + ")";
                String groupKey = String.valueOf(groupConfig.getGroupId());
                boolean isCollapsed = groupExpandStates.getOrDefault(groupKey, true);
                JPanel collapsibleGroup = createCompactCollapsiblePanel(groupTitle, groupContentPanel, groupKey, isCollapsed);
                parentPanel.add(collapsibleGroup);
                parentPanel.add(DropTrackerTheme.gap(2));
            }
        } else {
            JPanel emptyPanel = DropTrackerTheme.vbox(DropTrackerTheme.SURFACE_1);
            emptyPanel.setMaximumSize(new Dimension(Integer.MAX_VALUE, 30));
            emptyPanel.setPreferredSize(new Dimension(PluginPanel.PANEL_WIDTH - 40, 30));

            JLabel noConfigsLabel = DropTrackerTheme.label("No group configurations loaded.", FontManager.getRunescapeSmallFont(), DropTrackerTheme.TEXT_MUTED);
            noConfigsLabel.setAlignmentX(Component.CENTER_ALIGNMENT);
            emptyPanel.add(Box.createVerticalGlue());
            emptyPanel.add(noConfigsLabel);
            emptyPanel.add(Box.createVerticalGlue());

            parentPanel.add(emptyPanel);
        }
    }

    private JPanel createCompactCollapsiblePanel(String title, JPanel content, String groupKey, boolean isCollapsed) {
        JPanel panel = DropTrackerTheme.vbox(DropTrackerTheme.SURFACE_1);
        panel.setBorder(new EmptyBorder(2, 5, 2, 5));
        panel.setMaximumSize(new Dimension(Integer.MAX_VALUE, 130));

        JPanel headerPanel = new JPanel(new BorderLayout());
        headerPanel.setBackground(DropTrackerTheme.SURFACE_1);
        headerPanel.setMaximumSize(new Dimension(Integer.MAX_VALUE, 18));
        headerPanel.setPreferredSize(new Dimension(PluginPanel.PANEL_WIDTH - 40, 18));

        JLabel titleLabel = DropTrackerTheme.label(title, FontManager.getRunescapeSmallFont(), DropTrackerTheme.TEXT);

        final ImageIcon expandedIcon = PanelElements.getExpandedIcon();
        final ImageIcon collapsedIcon = PanelElements.getCollapsedIcon();
        final JLabel toggleIcon = new JLabel(isCollapsed ? collapsedIcon : expandedIcon);

        headerPanel.add(titleLabel, BorderLayout.WEST);
        headerPanel.add(toggleIcon, BorderLayout.EAST);

        content.setVisible(!isCollapsed);

        if (isCollapsed) {
            panel.setMaximumSize(new Dimension(Integer.MAX_VALUE, 24));
            panel.setPreferredSize(new Dimension(PluginPanel.PANEL_WIDTH - 40, 24));
        }

        final boolean[] isCollapsedRef = {isCollapsed};

        MouseAdapter clickListener = new MouseAdapter() {
            @Override
            public void mouseClicked(MouseEvent e) {
                isCollapsedRef[0] = !isCollapsedRef[0];
                toggleIcon.setIcon(isCollapsedRef[0] ? collapsedIcon : expandedIcon);
                content.setVisible(!isCollapsedRef[0]);
                groupExpandStates.put(groupKey, isCollapsedRef[0]);

                if (isCollapsedRef[0]) {
                    panel.setMaximumSize(new Dimension(Integer.MAX_VALUE, 24));
                    panel.setPreferredSize(new Dimension(PluginPanel.PANEL_WIDTH - 40, 24));
                } else {
                    panel.setMaximumSize(new Dimension(Integer.MAX_VALUE, 130));
                    panel.setPreferredSize(null);
                }

                panel.revalidate();
                panel.repaint();
                if (panel.getParent() != null) {
                    panel.getParent().revalidate();
                    panel.getParent().repaint();
                }
            }

            @Override
            public void mouseEntered(MouseEvent e) {
                headerPanel.setCursor(new Cursor(Cursor.HAND_CURSOR));
            }

            @Override
            public void mouseExited(MouseEvent e) {
                headerPanel.setCursor(new Cursor(Cursor.DEFAULT_CURSOR));
            }
        };

        headerPanel.addMouseListener(clickListener);

        JSeparator separator = new JSeparator();
        separator.setBackground(DropTrackerTheme.SURFACE_3);
        separator.setForeground(DropTrackerTheme.SURFACE_3);
        separator.setMaximumSize(new Dimension(Integer.MAX_VALUE, 1));

        panel.add(headerPanel);
        panel.add(separator);
        panel.add(content);

        return panel;
    }

    private JPanel createGroupConfigPanel(GroupConfig groupConfig) {
        JPanel panel = DropTrackerTheme.vbox(DropTrackerTheme.SURFACE_1);
        panel.setBorder(new EmptyBorder(2, 5, 2, 5));

        JPanel headerPanel = new JPanel(new FlowLayout(FlowLayout.LEFT, 2, 0));
        headerPanel.setBackground(DropTrackerTheme.SURFACE_1);
        headerPanel.setMaximumSize(new Dimension(Integer.MAX_VALUE, 18));
        headerPanel.setPreferredSize(new Dimension(PluginPanel.PANEL_WIDTH - 70, 18));

        JLabel notificationsLabel = DropTrackerTheme.label("Notifications:", FontManager.getRunescapeSmallFont(), DropTrackerTheme.TEXT);
        headerPanel.add(notificationsLabel);

        panel.add(headerPanel);
        panel.add(DropTrackerTheme.gap(2));

        panel.add(createConfigRow("Drops", groupConfig.isSendDrops(), "Min: " + groupConfig.getMinimumDropValue()));
        panel.add(createConfigRow("CAs", groupConfig.isSendCAs(), "Min Tier: " + groupConfig.getMinimumCATier()));
        panel.add(createConfigRow("PBs", groupConfig.isSendPbs(), null));
        panel.add(createConfigRow("CLogs", groupConfig.isSendClogs(), null));
        panel.add(createConfigRow("Pets", groupConfig.isSendPets(), null));
        panel.add(createConfigRow("Quests", groupConfig.isSendQuests(), null));

        String levelText = groupConfig.isSendXP()
            ? "Levels (" + groupConfig.getMinimumLevel() + " min)"
            : "Levels";
        panel.add(createConfigRow(levelText, groupConfig.isSendXP(), null));
        return panel;
    }

    private JPanel createConfigRow(String label, boolean enabled, String details) {
        JPanel row = new JPanel(new FlowLayout(FlowLayout.LEFT, 2, 0));
        row.setBackground(DropTrackerTheme.SURFACE_1);
        row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 18));
        row.setPreferredSize(new Dimension(PluginPanel.PANEL_WIDTH - 70, 18));

        JLabel nameLabel = DropTrackerTheme.label(label + ":", FontManager.getRunescapeSmallFont(), DropTrackerTheme.TEXT_MUTED);
        row.add(nameLabel);

        JLabel statusLabel = DropTrackerTheme.label(enabled ? "On" : "Off", FontManager.getRunescapeSmallFont(), enabled ? DropTrackerTheme.GREEN : DropTrackerTheme.RED);
        row.add(statusLabel);

        if (details != null && !details.isEmpty()) {
            JLabel detailsLabel = DropTrackerTheme.label("(" + details + ")", FontManager.getRunescapeSmallFont(), DropTrackerTheme.STONE);
            row.add(detailsLabel);
        }

        return row;
    }

    public void refreshGroupConfigs() {
        if (groupsContainerPanel == null || groupsScrollPane == null) {
            return;
        }

        // Kick a rate-limited async refresh, then render whatever is in memory right now.
        // getGroupConfigs() is a pure in-memory read, so this never blocks the EDT.
        api.refreshGroupConfigsAsync();
        List<GroupConfig> groupConfigs = api.getGroupConfigs();
        SwingUtilities.invokeLater(() -> {
            if (groupsContainerPanel == null || groupsScrollPane == null) {
                return;
            }
            int scrollPosition = groupsScrollPane.getVerticalScrollBar().getValue();

            buildGroupConfigPanels(groupsContainerPanel, groupConfigs);
            groupsContainerPanel.revalidate();
            groupsContainerPanel.repaint();

            SwingUtilities.invokeLater(() -> groupsScrollPane.getVerticalScrollBar().setValue(scrollPosition));

            if (groupConfigPanel != null) {
                groupConfigPanel.revalidate();
                groupConfigPanel.repaint();
            }
        });
    }

    /* ===================== Status + lifecycle ===================== */

    /** Recomputes the header connection state from the last successful API communication. */
    public void updateStatusLabel() {
        if (!config.useApi() || mainPanel == null) {
            return;
        }

        long deltaSeconds = Math.max(0L, Instant.now().getEpochSecond() - api.lastCommunicationTime);
        Duration sinceLastContact = Duration.ofSeconds(deltaSeconds);

        DropTrackerPanel.ConnectionState state;
        if (sinceLastContact.getSeconds() < 60) {
            state = DropTrackerPanel.ConnectionState.CONNECTED;
        } else if (sinceLastContact.getSeconds() < 300) {
            state = DropTrackerPanel.ConnectionState.CONNECTING;
        } else {
            state = DropTrackerPanel.ConnectionState.OFFLINE;
        }
        mainPanel.updateConnectionState(state);
    }

    public void refreshStatistics() {
        if (statsCard != null) {
            rebuildStatsCard(statsCard);
        }
    }

    public void refresh() {
        updateStatusLabel();
        refreshStatistics();
        refreshSubmissions();
        refreshGroupConfigs();
    }

    public void cleanup() {
        if (statusUpdateTimer != null && statusUpdateTimer.isRunning()) {
            statusUpdateTimer.stop();
        }
    }
}

package io.droptracker.ui.pages;

import io.droptracker.api.DropTrackerUrls;
import io.droptracker.models.api.EventView;
import io.droptracker.ui.DropTrackerTheme;
import io.droptracker.ui.components.PanelElements;
import net.runelite.client.ui.FontManager;
import net.runelite.client.util.LinkBrowser;
import okhttp3.HttpUrl;

import javax.annotation.Nullable;
import javax.swing.*;
import javax.swing.border.*;
import java.awt.*;
import java.awt.event.*;
import java.util.*;
import java.util.List;
import java.util.concurrent.CompletableFuture;

/**
 * The event window: an event's pages (overview, tasks, board, teams, players,
 * history) in a window of their own, for any event the account is on or its
 * groups run. The server composes every page as blocks (see {@link EventView});
 * this draws them and follows {@code page} links, nothing else.
 */
public class EventWindow extends JPanel {

    @Nullable
    private static JDialog openDialog;
    @Nullable
    private static EventWindow openWindow;

    private final EventsPanel panel;
    private final JLabel name = DropTrackerTheme.label(" ", FontManager.getRunescapeBoldFont().deriveFont(18f), DropTrackerTheme.GOLD);
    private final JLabel subtitle = DropTrackerTheme.label(" ", FontManager.getRunescapeSmallFont(), DropTrackerTheme.TEXT_MUTED);
    private final JComboBox<String> switcher = new JComboBox<>();
    private final JPanel tabs = new JPanel(new FlowLayout(FlowLayout.LEFT, 4, 0));
    private final JPanel column = new EventsPanel.ScrollableColumn();
    private final JScrollPane scroll = new JScrollPane(column,
        JScrollPane.VERTICAL_SCROLLBAR_AS_NEEDED, JScrollPane.HORIZONTAL_SCROLLBAR_NEVER);

    private List<EventView.Event> events = new ArrayList<>();
    private int eventId;
    private String page = "overview";
    private long loadedAt;
    private int loadSeq;
    private boolean syncing;

    private EventWindow(EventsPanel panel) {
        super(new BorderLayout());
        this.panel = panel;
        setBackground(DropTrackerTheme.SURFACE_0);
        setPreferredSize(new Dimension(820, 600));

        JPanel header = new JPanel(new BorderLayout(10, 6));
        header.setBackground(DropTrackerTheme.SURFACE_1);
        header.setBorder(new CompoundBorder(new MatteBorder(0, 0, 1, 0, DropTrackerTheme.BRONZE), new EmptyBorder(10, 14, 8, 14)));
        JPanel title = DropTrackerTheme.vbox(DropTrackerTheme.SURFACE_1);
        title.add(name);
        title.add(subtitle);
        header.add(title, BorderLayout.CENTER);

        JPanel actions = new JPanel(new FlowLayout(FlowLayout.RIGHT, 6, 0));
        actions.setOpaque(false);
        switcher.setFont(FontManager.getRunescapeSmallFont());
        switcher.setBackground(DropTrackerTheme.SURFACE_2);
        switcher.setForeground(DropTrackerTheme.TEXT);
        switcher.addActionListener(e -> {
            int i = switcher.getSelectedIndex();
            if (!syncing && i >= 0 && i < events.size() && events.get(i).getId() != eventId) {
                show(events.get(i).getId(), "overview");
            }
        });
        switcher.setVisible(false);
        actions.add(switcher);
        JButton refresh = DropTrackerTheme.button("Refresh");
        refresh.addActionListener(e -> load());
        actions.add(refresh);
        JButton web = DropTrackerTheme.button("Website");
        web.setIcon(PanelElements.getExternalLinkIcon());
        web.setToolTipText("Open this event on droptracker.io");
        web.addActionListener(e -> LinkBrowser.browse(DropTrackerUrls.web("events", String.valueOf(eventId)).toString()));
        actions.add(web);
        header.add(actions, BorderLayout.EAST);
        tabs.setOpaque(false);
        header.add(tabs, BorderLayout.SOUTH);
        add(header, BorderLayout.NORTH);

        column.setLayout(new BoxLayout(column, BoxLayout.Y_AXIS));
        column.setBackground(DropTrackerTheme.SURFACE_0);
        column.setBorder(new EmptyBorder(10, 14, 14, 14));
        scroll.setBorder(null);
        scroll.getViewport().setBackground(DropTrackerTheme.SURFACE_0);
        scroll.getVerticalScrollBar().setUnitIncrement(16);
        add(scroll, BorderLayout.CENTER);
    }

    /** Opens an event (0: the first the account may open), or brings the window forward. EDT. */
    static void open(EventsPanel panel, int eventId) {
        if (openDialog != null && openDialog.isDisplayable() && openWindow != null) {
            if (eventId > 0) {
                openWindow.show(eventId, "overview");
            }
            openDialog.toFront();
            return;
        }
        JFrame parent = PanelElements.getParentFrame(panel.client);
        JDialog dialog = new JDialog(parent, "DropTracker - Events", false);
        EventWindow window = new EventWindow(panel);
        dialog.setContentPane(window);
        dialog.addWindowListener(new WindowAdapter() {
            @Override
            public void windowClosed(WindowEvent e) {
                if (openDialog == dialog) {
                    openDialog = null;
                    openWindow = null;
                }
            }
        });
        dialog.setDefaultCloseOperation(JDialog.DISPOSE_ON_CLOSE);
        dialog.setMinimumSize(new Dimension(640, 440));
        dialog.pack();
        dialog.setLocationRelativeTo(parent);
        openDialog = dialog;
        openWindow = window;
        dialog.setVisible(true);
        window.eventId = eventId;
        window.status("Loading...");
        window.loadList();
    }

    /** A fresh /event_state landed (something scored): refresh the open page, at most every 15s. EDT. */
    static void stateUpdated() {
        EventWindow w = openWindow;
        if (w != null && w.eventId > 0 && System.currentTimeMillis() - w.loadedAt > 15_000) {
            w.load();
        }
    }

    private void show(int id, String key) {
        eventId = id;
        page = key;
        load();
    }

    private void loadList() {
        String player = panel.config.lastAccountName();
        long hash = panel.client.getAccountHash();
        CompletableFuture.supplyAsync(() -> panel.api.fetchEventList(player, hash)).thenAccept(listing ->
            SwingUtilities.invokeLater(() -> {
                events = listing != null ? listing.getEvents() : new ArrayList<>();
                if (eventId <= 0 && !events.isEmpty()) {
                    eventId = events.get(0).getId();
                }
                syncSwitcher();
                if (eventId > 0) {
                    load();
                } else {
                    status(listing == null ? "Couldn't load your events. Try Refresh in a minute."
                        : "None of your groups have an event running, coming up or ended this week.");
                }
            }));
    }

    private void syncSwitcher() {
        syncing = true;
        switcher.removeAllItems();
        for (EventView.Event e : events) {
            switcher.addItem(e.getTeam() == null && e.getGroup() != null ? e.getName() + " (" + e.getGroup() + ")" : e.getName());
            if (e.getId() == eventId) {
                switcher.setSelectedIndex(switcher.getItemCount() - 1);
            }
        }
        switcher.setVisible(events.size() > 1);
        syncing = false;
    }

    private void load() {
        if (eventId <= 0) {
            loadList();
            return;
        }
        int seq = ++loadSeq;
        int id = eventId;
        String key = page;
        String player = panel.config.lastAccountName();
        long hash = panel.client.getAccountHash();
        CompletableFuture.supplyAsync(() -> panel.api.fetchEventView(id, key, player, hash)).thenAccept(view ->
            SwingUtilities.invokeLater(() -> {
                if (seq != loadSeq) {
                    return;
                }
                loadedAt = System.currentTimeMillis();
                if (view == null || view.getEvent() == null) {
                    status("Couldn't load this event. It may have been removed, or the server is busy.");
                    return;
                }
                render(view);
            }));
    }

    private void status(String text) {
        column.removeAll();
        column.add(text(text, DropTrackerTheme.TEXT_MUTED));
        column.revalidate();
        column.repaint();
    }

    private void render(EventView view) {
        name.setText(view.getEvent().getName());
        subtitle.setText(view.getEvent().getSubtitle() + (view.getTeam() != null ? "  ·  Your team: " + view.getTeam().getName() : ""));
        page = view.getPage();
        tabs.removeAll();
        for (EventView.Page p : view.getPages()) {
            JButton tab = DropTrackerTheme.button(p.getLabel());
            if (page.startsWith(p.getKey())) {
                tab.setForeground(DropTrackerTheme.GOLD);
                tab.setBorder(new CompoundBorder(new MatteBorder(0, 0, 2, 0, DropTrackerTheme.GOLD), tab.getBorder()));
            }
            tab.addActionListener(e -> show(eventId, p.getKey()));
            tabs.add(tab);
        }
        tabs.revalidate();
        tabs.repaint();

        int scrollValue = scroll.getVerticalScrollBar().getValue();
        boolean samePage = page.equals(column.getName());
        column.setName(page);
        column.removeAll();
        for (EventView.Block b : view.getBlocks()) {
            JComponent c = block(b);
            if (c != null) {
                c.setAlignmentX(LEFT_ALIGNMENT);
                column.add(c);
                column.add(DropTrackerTheme.gap(10));
            }
        }
        column.add(Box.createVerticalGlue());
        column.revalidate();
        column.repaint();
        // A refresh keeps the reader's place; a new page starts at the top.
        SwingUtilities.invokeLater(() -> scroll.getVerticalScrollBar().setValue(samePage ? scrollValue : 0));
    }

    /* ===================== blocks ===================== */

    @Nullable
    private JComponent block(EventView.Block b) {
        switch (String.valueOf(b.getType())) {
            case "heading":
                JLabel h = DropTrackerTheme.label(b.getText(), FontManager.getRunescapeBoldFont(), DropTrackerTheme.GOLD);
                h.setBorder(new CompoundBorder(new MatteBorder(0, 0, 1, 0, DropTrackerTheme.BRONZE), new EmptyBorder(4, 0, 3, 0)));
                return fit(h);
            case "text":
                return text(b.getText(), "muted".equals(b.getTone()) ? DropTrackerTheme.TEXT_MUTED : DropTrackerTheme.TEXT);
            case "stats":
                JPanel stats = new JPanel(new GridLayout(0, Math.min(Math.max(b.getItems().size(), 1), 4), 6, 6));
                stats.setOpaque(false);
                for (EventView.Item i : b.getItems()) {
                    JPanel box = PanelElements.createStatBox(i.getLabel(), i.getValue());
                    box.setToolTipText(i.getTip());
                    stats.add(box);
                }
                return fit(stats);
            case "table":
                return table(b);
            case "tasks":
                return tasks(b);
            case "board":
                return board(b);
            default:
                return null;
        }
    }

    private JComponent table(EventView.Block b) {
        JPanel t = DropTrackerTheme.vbox(DropTrackerTheme.SURFACE_0);
        if (b.getRows().isEmpty()) {
            return text(b.getEmpty(), DropTrackerTheme.TEXT_MUTED);
        }
        List<String> heads = new ArrayList<>();
        b.getColumns().forEach(c -> heads.add(c.getLabel()));
        t.add(tableRow(b.getColumns(), heads, null, null, false, true));
        for (EventView.Row r : b.getRows()) {
            JPanel row = tableRow(b.getColumns(), r.getCells(), r.getColor(), r.getPage(), r.isHighlight(), false);
            row.setToolTipText(r.getTip());
            t.add(row);
        }
        return t;
    }

    /** One row; zero-width cells with weights keep every row's columns aligned. */
    private JPanel tableRow(List<EventView.Column> cols, List<String> cells, @Nullable String color,
                            @Nullable String link, boolean highlight, boolean head) {
        JPanel row = new DropTrackerTheme.FitPanel(new GridBagLayout());
        row.setBackground(head ? DropTrackerTheme.SURFACE_1 : highlight ? DropTrackerTheme.SURFACE_3 : DropTrackerTheme.SURFACE_2);
        row.setBorder(new CompoundBorder(new MatteBorder(0, 3, 1, 0, color != null ? parse(color) : row.getBackground()), new EmptyBorder(4, 6, 4, 6)));
        GridBagConstraints c = new GridBagConstraints();
        c.fill = GridBagConstraints.HORIZONTAL;
        c.insets = new Insets(0, 0, 0, 8);
        for (int i = 0; i < cells.size(); i++) {
            EventView.Column col = i < cols.size() ? cols.get(i) : null;
            JLabel cell = DropTrackerTheme.label(cells.get(i), head ? FontManager.getRunescapeBoldFont() : FontManager.getRunescapeSmallFont(),
                head ? DropTrackerTheme.TEXT_MUTED : highlight ? DropTrackerTheme.GOLD_BRIGHT : DropTrackerTheme.TEXT);
            cell.setPreferredSize(new Dimension(0, cell.getPreferredSize().height));
            cell.setMinimumSize(cell.getPreferredSize());
            cell.setToolTipText(cells.get(i));
            if (col != null && col.isRight()) {
                cell.setHorizontalAlignment(SwingConstants.RIGHT);
            }
            c.gridx = i;
            c.weightx = col != null ? Math.max(col.getWidth(), 1) : 1;
            row.add(cell, c);
        }
        if (link != null) {
            row.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
            row.addMouseListener(new MouseAdapter() {
                @Override
                public void mouseClicked(MouseEvent e) {
                    show(eventId, link);
                }
            });
        }
        return row;
    }

    private JComponent tasks(EventView.Block b) {
        if (b.getItems().isEmpty()) {
            return text(b.getEmpty(), DropTrackerTheme.TEXT_MUTED);
        }
        JPanel list = DropTrackerTheme.vbox(DropTrackerTheme.SURFACE_0);
        for (EventView.Item i : b.getItems()) {
            JPanel card = new DropTrackerTheme.FitPanel(new BorderLayout(8, 4));
            card.setBackground(DropTrackerTheme.SURFACE_1);
            card.setBorder(DropTrackerTheme.cardBorder(6, 8, 6, 8));
            card.setToolTipText(i.getTip());
            JLabel icon = new JLabel();
            icon.setPreferredSize(new Dimension(28, 28));
            panel.applyTaskIcon(icon, i.getIconItemId(), null, 28);
            card.add(icon, BorderLayout.WEST);

            JPanel body = DropTrackerTheme.vbox(DropTrackerTheme.SURFACE_1);
            JPanel top = new JPanel(new BorderLayout(6, 0));
            top.setOpaque(false);
            top.add(DropTrackerTheme.label(i.getLabel(), FontManager.getRunescapeBoldFont(), DropTrackerTheme.TEXT), BorderLayout.CENTER);
            if (i.getPoints() != null) {
                top.add(DropTrackerTheme.chip(i.getPoints(), DropTrackerTheme.GOLD), BorderLayout.EAST);
            }
            body.add(fit(top));
            if (i.getDetail() != null) {
                body.add(fit(DropTrackerTheme.label(i.getDetail(), FontManager.getRunescapeSmallFont(), DropTrackerTheme.TEXT_MUTED)));
            }
            for (EventView.Bar bar : i.getBars()) {
                JPanel line = new DropTrackerTheme.FitPanel(new BorderLayout(8, 0));
                line.setOpaque(false);
                line.setBorder(new EmptyBorder(3, 0, 0, 0));
                line.setAlignmentX(LEFT_ALIGNMENT);
                JLabel team = DropTrackerTheme.label(bar.getLabel(), bar.isHighlight() ? FontManager.getRunescapeBoldFont() : FontManager.getRunescapeSmallFont(),
                    bar.isHighlight() ? DropTrackerTheme.GOLD_BRIGHT : DropTrackerTheme.TEXT_MUTED);
                team.setPreferredSize(new Dimension(130, 14));
                team.setToolTipText(bar.getLabel());
                line.add(team, BorderLayout.WEST);
                line.add(EventsPanel.progressBar(bar.getHave(), bar.getNeed(), bar.getText(),
                    bar.getColor() != null ? parse(bar.getColor()) : DropTrackerTheme.GREEN), BorderLayout.CENTER);
                body.add(line);
            }
            card.add(body, BorderLayout.CENTER);
            list.add(card);
            list.add(DropTrackerTheme.gap(4));
        }
        return list;
    }

    private JComponent board(EventView.Block b) {
        JPanel box = DropTrackerTheme.vbox(DropTrackerTheme.SURFACE_0);
        HttpUrl url = panel.api.eventBoardImageUrl(eventId, b.getTeamId(), panel.config.lastAccountName(), panel.client.getAccountHash());
        JButton full = DropTrackerTheme.button("Full size");
        full.addActionListener(e -> PanelElements.showRemoteImage(panel.client, name.getText(), url));
        box.add(full);
        box.add(DropTrackerTheme.gap(8));
        JLabel image = DropTrackerTheme.label("Loading the board...", FontManager.getRunescapeSmallFont(), DropTrackerTheme.TEXT_MUTED);
        box.add(image);
        int width = Math.max(scroll.getViewport().getWidth() - 30, 300);
        CompletableFuture.supplyAsync(() -> PanelElements.fetchImage(url)).thenAccept(img ->
            SwingUtilities.invokeLater(() -> {
                image.setText(img == null ? "Couldn't load the board. Try Refresh in a moment." : null);
                if (img != null) {
                    image.setIcon(new ImageIcon(img.getWidth() > width
                        ? img.getScaledInstance(width, img.getHeight() * width / img.getWidth(), Image.SCALE_SMOOTH) : img));
                    column.revalidate();
                }
            }));
        return box;
    }

    /* ===================== bits ===================== */

    private static JComponent text(@Nullable String value, Color color) {
        JTextArea area = new JTextArea(value == null ? "" : value);
        area.setLineWrap(true);
        area.setWrapStyleWord(true);
        area.setEditable(false);
        area.setOpaque(false);
        area.setForeground(color);
        area.setFont(FontManager.getRunescapeSmallFont());
        return area;
    }

    private static JComponent fit(JComponent c) {
        c.setAlignmentX(LEFT_ALIGNMENT);
        c.setMaximumSize(new Dimension(Integer.MAX_VALUE, c.getPreferredSize().height));
        return c;
    }

    private static Color parse(String hex) {
        return EventsPanel.parseColor(hex, DropTrackerTheme.STONE);
    }
}

package io.droptracker.ui.pages;

import io.droptracker.DropTrackerConfig;
import io.droptracker.api.DropTrackerApi;
import io.droptracker.models.api.EventState;
import io.droptracker.models.submissions.RecentSubmission;
import io.droptracker.service.*;
import io.droptracker.ui.DropTrackerTheme;
import io.droptracker.ui.components.*;
import io.droptracker.util.*;
import net.runelite.api.Client;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.*;
import net.runelite.client.util.ImageUtil;

import javax.annotation.Nullable;
import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;
import java.awt.event.*;
import java.awt.image.BufferedImage;
import java.time.*;
import java.time.format.DateTimeParseException;
import java.util.*;
import java.util.List;
import java.util.concurrent.CompletableFuture;

/**
 * "Events" side-panel tab: the active event's card — themed header with the
 * time remaining, stat tiles, the tracked task (click any task in the list to
 * pin it; the top pin leads the HUD, and with none the server decides) and the
 * team's recent submissions. With several events, a row per event picks the
 * active one. Standings, boards, rosters and history live in the
 * {@link EventWindow}.
 */
public class EventsPanel {
    final DropTrackerConfig config;
    final DropTrackerApi api;
    private final EventNotificationService service;
    final Client client;
    private final ItemManager itemManager;
    private final ItemImageCache itemImages;
    private final RemoteImageCache remoteImages;
    private final ItemIDSearch itemIds;
    private final EventTaskPrefs taskPrefs;

    /* Tracked-task required-item strip: small wrapping grid of item sprites. */
    private static final int REQ_ICONS_PER_ROW = 5;
    private static final int REQ_ICON_SLOT = 28;
    private static final int REQ_ICON_SIZE = 26;

    private JPanel root;
    private JPanel listPanel;
    private JScrollPane scrollPane;
    /** EDT only: a rebuild is already queued (see {@link #requestRebuild}). */
    private boolean rebuildQueued;
    /** EDT only: state changed while the tab was hidden. */
    private boolean staleWhileHidden;
    /**
     * Expand/collapse choices per card section (key: eventId + section),
     * surviving rebuilds — clicking a task to track it re-renders the card
     * and must not fold the task list back to its size-based default.
     */
    private final java.util.Map<String, Boolean> sectionCollapsed = new java.util.HashMap<>();
    /**
     * Whether the "N hidden" group of a card is currently folded open (key:
     * eventId). Hiding is persisted; peeking at what you hid is not.
     */
    private final java.util.Map<String, Boolean> hiddenRevealed = new java.util.HashMap<>();

    public EventsPanel(DropTrackerConfig config, DropTrackerApi api,
                       EventNotificationService service, Client client,
                       ItemManager itemManager, ItemImageCache itemImages,
                       RemoteImageCache remoteImages,
                       ItemIDSearch itemIds, ConfigManager configManager) {
        this.config = config;
        this.api = api;
        this.service = service;
        this.client = client;
        this.itemManager = itemManager;
        this.itemImages = itemImages;
        this.remoteImages = remoteImages;
        this.itemIds = itemIds;
        this.taskPrefs = new EventTaskPrefs(configManager, service);
    }

    public JPanel create() {
        root = new JPanel(new BorderLayout());
        root.setBackground(DropTrackerTheme.SURFACE_0);

        listPanel = new ScrollableColumn();
        listPanel.setLayout(new BoxLayout(listPanel, BoxLayout.Y_AXIS));
        listPanel.setBackground(DropTrackerTheme.SURFACE_0);
        listPanel.setBorder(new EmptyBorder(5, 0, 5, 0));

        JPanel header = new JPanel(new BorderLayout());
        header.setBackground(DropTrackerTheme.SURFACE_0);
        JLabel title = DropTrackerTheme.label("Your events", FontManager.getRunescapeBoldFont(), DropTrackerTheme.GOLD);
        header.add(title, BorderLayout.WEST);
        JPanel buttons = new JPanel(new GridLayout(1, 2, 4, 0));
        buttons.setOpaque(false);
        JButton all = DropTrackerTheme.button("All events");
        all.setToolTipText("Open the event window: every event you or your groups are running");
        all.addActionListener(e -> EventWindow.open(this, 0));
        buttons.add(all);
        JButton refresh = DropTrackerTheme.button("Refresh");
        refresh.addActionListener(e -> refreshAsync());
        buttons.add(refresh);
        header.add(buttons, BorderLayout.EAST);
        header.setBorder(new EmptyBorder(4, 6, 4, 6));

        scrollPane = new JScrollPane(listPanel,
            JScrollPane.VERTICAL_SCROLLBAR_AS_NEEDED,
            JScrollPane.HORIZONTAL_SCROLLBAR_NEVER);
        scrollPane.setBorder(null);
        scrollPane.getViewport().setBackground(DropTrackerTheme.SURFACE_0);
        scrollPane.getVerticalScrollBar().setUnitIncrement(16);

        root.add(header, BorderLayout.NORTH);
        root.add(scrollPane, BorderLayout.CENTER);
        // Catch up on anything that arrived while the tab was out of view.
        root.addHierarchyListener(e -> {
            if ((e.getChangeFlags() & HierarchyEvent.SHOWING_CHANGED) != 0
                    && root.isShowing() && staleWhileHidden) {
                staleWhileHidden = false;
                rebuild();
            }
        });

        rebuild();
        refreshAsync();
        return root;
    }

    /** Kick a state refetch off the EDT; rebuild lands via onUpdated(). */
    public void refreshAsync() {
        CompletableFuture.runAsync(service::refreshEventStateNow);
    }

    /** Called (any thread) when a fresh /event_state snapshot lands. */
    public void onUpdated() {
        SwingUtilities.invokeLater(() -> {
            requestRebuild();
            EventWindow.stateUpdated();
        });
    }

    /**
     * EDT. Every event notification refreshes the state, and most arrive while
     * the player is fighting with this tab closed. Rebuilding then is wasted
     * work, so a hidden tab only notes that it is stale and rebuilds when it
     * is next shown. A burst of updates while it is showing makes one rebuild.
     */
    private void requestRebuild() {
        if (root != null && !root.isShowing()) {
            staleWhileHidden = true;
            return;
        }
        if (rebuildQueued) {
            return;
        }
        rebuildQueued = true;
        SwingUtilities.invokeLater(() -> {
            rebuildQueued = false;
            rebuild();
        });
    }

    private void rebuild() {
        if (listPanel == null) {
            return;
        }
        // Keep the viewport where the user left it: a rebuild triggered by
        // clicking a task (or a background state refresh) must not jump the
        // panel back to the top.
        final int scrollValue = scrollPane != null
            ? scrollPane.getVerticalScrollBar().getValue() : 0;
        listPanel.removeAll();

        EventState state = service.getEventState();
        List<EventState.Entry> entries = state != null ? state.getEvents() : null;
        if (!config.useApi() || !config.eventNotifications()) {
            listPanel.add(emptyLabel("Enable the API and event notifications to see your events."));
        } else if (entries == null || entries.isEmpty()) {
            listPanel.add(emptyLabel("No active events right now."));
        } else {
            // The active event (explicit pick, else the first) drives this
            // tab, the HUD and the team badges alike. With several, a row per
            // event picks it; everything else is in the event window.
            EventState.Entry active = service.hudEntry();
            if (entries.size() > 1) {
                for (EventState.Entry entry : entries) {
                    listPanel.add(pickerRow(entry, entry == active));
                    listPanel.add(DropTrackerTheme.gap(4));
                }
                listPanel.add(DropTrackerTheme.gap(4));
            }
            if (active != null) {
                listPanel.add(eventCard(active));
            }
        }
        listPanel.add(Box.createVerticalGlue());
        listPanel.revalidate();
        listPanel.repaint();
        if (scrollPane != null && scrollValue > 0) {
            // After the new layout pass — setValue clamps to the new extent.
            SwingUtilities.invokeLater(() ->
                scrollPane.getVerticalScrollBar().setValue(scrollValue));
        }
    }

