        EventState.EventInfo event = entry.getEvent();
        JPanel row = new DropTrackerTheme.FitPanel(new BorderLayout(4, 0));
        row.setBackground(active ? DropTrackerTheme.SURFACE_3 : DropTrackerTheme.SURFACE_1);
