    /* ===================== task list ===================== */

    private JPanel taskListPanel(EventState.Entry entry, List<EventState.TaskInfo> tasks,
                                 @Nullable EventNotificationService.DisplayTask display,
                                 boolean pickable) {
        JPanel list = DropTrackerTheme.vbox(DropTrackerTheme.SURFACE_1);
        list.setAlignmentX(Component.LEFT_ALIGNMENT);
        int displayedId = display != null ? display.id : -1;
        if (!pickable) {
            // Board games force the current tile: nothing to pin or hide.
            for (EventState.TaskInfo task : tasks) {
                list.add(taskRow(entry, task, displayedId, false, false, false));
                list.add(vgap(2));
            }
            return list;
        }

        int eventId = entry.getEvent().getId();
        Set<Integer> pins = taskPrefs.pinned(eventId);
        Set<Integer> hides = taskPrefs.hidden(eventId);
        List<EventState.TaskInfo> pinned = new ArrayList<>();
        List<EventState.TaskInfo> rest = new ArrayList<>();
        List<EventState.TaskInfo> hidden = new ArrayList<>();
        // Pins lead the list in the order they were pinned — the first one
        // still open is the task the HUD is tracking.
        for (Integer id : pins) {
            EventState.TaskInfo task = taskInfoById(entry, id);
            if (task != null) {
                pinned.add(task);
            }
        }
        for (EventState.TaskInfo task : tasks) {
            if (pins.contains(task.getId())) {
                continue;
            }
            (hides.contains(task.getId()) ? hidden : rest).add(task);
        }

        for (EventState.TaskInfo task : pinned) {
            list.add(taskRow(entry, task, displayedId, true, true, false));
            list.add(vgap(2));
        }
        for (EventState.TaskInfo task : rest) {
            list.add(taskRow(entry, task, displayedId, true, false, false));
            list.add(vgap(2));
        }
        if (!hidden.isEmpty()) {
            String key = String.valueOf(eventId);
            boolean revealed = Boolean.TRUE.equals(hiddenRevealed.get(key));
            list.add(hiddenHeader(entry, key, hidden.size(), revealed));
            list.add(vgap(2));
            if (revealed) {
                for (EventState.TaskInfo task : hidden) {
                    list.add(taskRow(entry, task, displayedId, true, false, true));
                    list.add(vgap(2));
                }
            }
        }

        JLabel hint = new JLabel("<html><div style='width:"
            + (PluginPanel.PANEL_WIDTH - 60) + "px;'>"
            + "Click a task to pin it to the top and the HUD; × hides it."
            + "</div></html>");
        hint.setFont(FontManager.getRunescapeSmallFont());
        hint.setForeground(DropTrackerTheme.TEXT_MUTED);
        hint.setBorder(new EmptyBorder(2, 2, 0, 0));
        hint.setAlignmentX(Component.LEFT_ALIGNMENT);
        list.add(hint);
        return list;
    }

    /** Fold-out header for the tasks the user hid, with a way back. */
    private JComponent hiddenHeader(EventState.Entry entry, String key, int count, boolean revealed) {
        JPanel row = new DropTrackerTheme.FitPanel(new BorderLayout(5, 0));
        row.setBackground(DropTrackerTheme.SURFACE_1);
        row.setBorder(new EmptyBorder(2, 2, 2, 4));
        row.setAlignmentX(Component.LEFT_ALIGNMENT);
        row.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));

        JLabel chevron = new JLabel(revealed
            ? PanelElements.getExpandedIcon() : PanelElements.getCollapsedIcon());
        row.add(chevron, BorderLayout.WEST);

        JLabel label = DropTrackerTheme.label(count + " hidden", FontManager.getRunescapeSmallFont(), DropTrackerTheme.TEXT_MUTED);
        row.add(label, BorderLayout.CENTER);

        row.addMouseListener(new MouseAdapter() {
            @Override
            public void mouseClicked(MouseEvent e) {
                hiddenRevealed.put(key, !revealed);
                rebuild();
            }
        });

        JLabel unhideAll = DropTrackerTheme.label("unhide all", FontManager.getRunescapeSmallFont(), DropTrackerTheme.TEXT_MUTED);
        unhideAll.setToolTipText("Show every hidden task again");
        unhideAll.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        unhideAll.addMouseListener(new MouseAdapter() {
            @Override
            public void mouseClicked(MouseEvent e) {
                taskPrefs.unhideAll(entry.getEvent().getId());
                rebuild();
            }

            @Override
            public void mouseEntered(MouseEvent e) {
                unhideAll.setForeground(DropTrackerTheme.GOLD_BRIGHT);
            }

            @Override
            public void mouseExited(MouseEvent e) {
                unhideAll.setForeground(DropTrackerTheme.TEXT_MUTED);
            }
        });
        row.add(unhideAll, BorderLayout.EAST);
        return row;
    }

    /**
     * One task row. {@code controls} adds the pin/hide glyphs and click-to-pin
     * (off for board games, whose tile is forced); {@code pinned} marks a row
     * in the pin set; {@code hidden} renders it inside the folded-out hidden
     * group, where the only action is putting it back.
     */
    private JPanel taskRow(EventState.Entry entry, EventState.TaskInfo task,
                           int displayedId, boolean controls, boolean pinned, boolean hidden) {
        boolean isDisplayed = task.getId() == displayedId;

        JPanel row = new DropTrackerTheme.FitPanel(new BorderLayout(5, 0));
        Color baseBg = isDisplayed ? DropTrackerTheme.SURFACE_3 : DropTrackerTheme.SURFACE_2;
        row.setBackground(baseBg);
        row.setBorder(BorderFactory.createCompoundBorder(
            BorderFactory.createMatteBorder(0, 2, 0, 0,
                isDisplayed ? DropTrackerTheme.GOLD
                    : (pinned ? DropTrackerTheme.BRONZE : DropTrackerTheme.SURFACE_3)),
            new EmptyBorder(3, 4, 3, 4)));
        row.setAlignmentX(Component.LEFT_ALIGNMENT);

        JLabel icon = new JLabel();
        icon.setPreferredSize(new Dimension(20, 20));
        applyTaskIcon(icon, task.getIconItemId(), task.getIconPath(), 20);
        row.add(icon, BorderLayout.WEST);

        JLabel label = new JLabel(truncate(task.getLabel(), controls ? 22 : 30));
        label.setFont(FontManager.getRunescapeSmallFont());
        label.setForeground(task.isCompleted() || hidden ? DropTrackerTheme.TEXT_MUTED
            : (isDisplayed ? DropTrackerTheme.GOLD_BRIGHT : DropTrackerTheme.TEXT));
        row.add(label, BorderLayout.CENTER);

        JLabel state;
        if (task.isCompleted()) {
            state = new JLabel(PanelIcons.check(DropTrackerTheme.GREEN, 11));
        } else if (task.getNeed() > 1 || task.getHave() > 0) {
            state = new JLabel(ValueFormat.abbrev(task.getHave())
                + "/" + ValueFormat.abbrev(task.getNeed()));
            state.setForeground(DropTrackerTheme.TEXT_MUTED);
        } else {
            state = new JLabel("");
        }
        state.setFont(FontManager.getRunescapeSmallFont());

        if (!controls) {
            row.add(state, BorderLayout.EAST);
        } else {
            JPanel east = new JPanel(new BorderLayout(3, 0));
            east.setOpaque(false);
            east.add(state, BorderLayout.CENTER);

            JPanel glyphs = new JPanel(new BorderLayout(1, 0));
            glyphs.setOpaque(false);
            // A completed task can't lead the HUD, but one pinned before it
            // completed still needs its way out.
            if (!hidden && (!task.isCompleted() || pinned)) {
                Color pinColor = pinned ? DropTrackerTheme.GOLD : DropTrackerTheme.STONE;
                glyphs.add(controlGlyph(
                    PanelIcons.star(pinColor, 11, pinned),
                    PanelIcons.star(DropTrackerTheme.GOLD_BRIGHT, 11, pinned),
                    pinned ? "Unpin this task" : "Pin this task to the top and the HUD",
                    () -> togglePin(entry, task.getId(), pinned)), BorderLayout.WEST);
            }
            glyphs.add(controlGlyph(hidden ? "+" : "×", DropTrackerTheme.STONE,
                hidden ? "Show this task again" : "Hide this task",
                () -> {
                    taskPrefs.toggleHidden(entry, task.getId());
                    rebuild();
                }), BorderLayout.EAST);
            east.add(glyphs, BorderLayout.EAST);
            row.add(east, BorderLayout.EAST);
        }

        row.setToolTipText(taskTooltip(task));

        if (controls && !hidden && (!task.isCompleted() || pinned)) {
            row.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
            row.addMouseListener(new MouseAdapter() {
                @Override
                public void mouseClicked(MouseEvent e) {
                    togglePin(entry, task.getId(), pinned);
                }

                @Override
                public void mouseEntered(MouseEvent e) {
                    row.setBackground(DropTrackerTheme.SURFACE_3);
                }

                @Override
                public void mouseExited(MouseEvent e) {
                    row.setBackground(baseBg);
                }
            });
        }
        return row;
    }

    /** Pin or unpin a task and redraw. Pinning is an act of focus: point the
     *  HUD at this event too, otherwise pins made in a second event never show
     *  anywhere (the HUD keeps rendering the pinned/first event). */
    private void togglePin(EventState.Entry entry, int taskId, boolean pinned) {
        taskPrefs.togglePin(entry, taskId);
        if (!pinned) {
            config.setPinnedEventId(entry.getEvent().getId());
        }
        rebuild();
    }

    /** Small clickable control in a task row. Sans-serif on purpose: the
     *  RuneScape bitmap fonts have no symbol coverage to fall back on. */
    private static JLabel controlGlyph(String text, Color color, String tooltip, Runnable action) {
        JLabel glyph = DropTrackerTheme.label(text, new Font(Font.SANS_SERIF, Font.BOLD, 11), color);
        return wireControlGlyph(glyph, tooltip, action,
            () -> glyph.setForeground(DropTrackerTheme.GOLD_BRIGHT),
            () -> glyph.setForeground(color));
    }

    /** Icon-backed control. A painted icon carries its own colour, so the
     *  caller supplies the hover variant rather than us recolouring text. */
    private static JLabel controlGlyph(Icon icon, Icon hoverIcon, String tooltip, Runnable action) {
        JLabel glyph = new JLabel(icon);
        return wireControlGlyph(glyph, tooltip, action,
            () -> glyph.setIcon(hoverIcon),
            () -> glyph.setIcon(icon));
    }

    private static JLabel wireControlGlyph(JLabel glyph, String tooltip, Runnable action,
                                           Runnable onEnter, Runnable onExit) {
        glyph.setToolTipText(tooltip);
        glyph.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        glyph.setBorder(new EmptyBorder(0, 2, 0, 2));
        glyph.addMouseListener(new MouseAdapter() {
            @Override
            public void mouseClicked(MouseEvent e) {
                action.run();
            }

            @Override
            public void mouseEntered(MouseEvent e) {
                onEnter.run();
            }

            @Override
            public void mouseExited(MouseEvent e) {
                onExit.run();
            }
        });
        return glyph;
    }

    /** The server's tooltip lines, escaped, in its fixed set of styles. */
    private static String tip(List<EventState.TipLine> lines) {
        StringBuilder html = new StringBuilder("<html><p style='width:200px;'>");
        for (int i = 0; i < lines.size(); i++) {
            String text = escape(lines.get(i).getText() == null ? "" : lines.get(i).getText());
            String style = String.valueOf(lines.get(i).getStyle());
            html.append(i > 0 ? "<br/>" : "").append("title".equals(style) ? "<b>" + text + "</b>"
                : "note".equals(style) ? "<i>" + text + "</i>"
                : "done".equals(style) ? "<strike><font color='#8a7c5e'>" + text + "</font></strike>" : text);
        }
        return html.append("</p></html>").toString();
    }

    private String taskTooltip(EventState.TaskInfo task) {
        return tip(task.getTip() != null ? task.getTip()
            : Collections.singletonList(new EventState.TipLine(task.getLabel(), "title")));
    }

    /* ===================== shared bits ===================== */

    /**
     * Vertical spacer safe for BoxLayout columns. Every child of a vertical
     * BoxLayout must share the same alignmentX — one centered (default 0.5)
     * child shifts every left-aligned sibling right by half its width, which
     * is exactly the "rows indented off the left edge" bug.
     */
    private static Component vgap(int height) {
        Box.Filler gap = (Box.Filler) Box.createVerticalStrut(height);
        gap.setAlignmentX(Component.LEFT_ALIGNMENT);
        return gap;
    }

    /**
     * Lightweight collapsible section: tiny header row + body. The user's
     * toggle is remembered under {@code key} so rebuilds (task tracked,
     * state refreshed) restore it; {@code defaultCollapsed} only applies the
     * first time a section is seen.
     */
    private JPanel section(String key, String title, JComponent body, boolean defaultCollapsed) {
        boolean startCollapsed = sectionCollapsed.getOrDefault(key, defaultCollapsed);
        JPanel wrap = DropTrackerTheme.vbox(DropTrackerTheme.SURFACE_1);
        wrap.setAlignmentX(Component.LEFT_ALIGNMENT);

        JPanel head = new DropTrackerTheme.FitPanel(new BorderLayout());
        head.setAlignmentX(Component.LEFT_ALIGNMENT);
        head.setBackground(DropTrackerTheme.SURFACE_1);
        head.setBorder(BorderFactory.createCompoundBorder(
            BorderFactory.createMatteBorder(0, 0, 1, 0, DropTrackerTheme.SURFACE_3),
            new EmptyBorder(0, 0, 3, 0)));
        head.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));

        JLabel titleLabel = DropTrackerTheme.label(title, FontManager.getRunescapeBoldFont(), DropTrackerTheme.TEXT);
        head.add(titleLabel, BorderLayout.WEST);

        JLabel chevron = new JLabel(startCollapsed
            ? PanelElements.getCollapsedIcon() : PanelElements.getExpandedIcon());
        head.add(chevron, BorderLayout.EAST);

        body.setAlignmentX(Component.LEFT_ALIGNMENT);
        body.setVisible(!startCollapsed);
        final boolean[] collapsed = {startCollapsed};
        head.addMouseListener(new MouseAdapter() {
            @Override
            public void mouseClicked(MouseEvent e) {
                collapsed[0] = !collapsed[0];
                sectionCollapsed.put(key, collapsed[0]);
                chevron.setIcon(collapsed[0]
                    ? PanelElements.getCollapsedIcon() : PanelElements.getExpandedIcon());
                body.setVisible(!collapsed[0]);
                wrap.revalidate();
                wrap.repaint();
            }
        });

        wrap.add(head);
        wrap.add(vgap(3));
        wrap.add(body);
        return wrap;
    }

    /** Slim custom progress bar: bronze frame, {@code fill}-coloured progress, centered text. */
    static JComponent progressBar(long have, long need, String text, Color fill) {
        long max = Math.max(need, 1);
        long value = Math.min(Math.max(have, 0), max);
        Color body = fill.darker().darker();
        JComponent bar = new JComponent() {
            @Override
            protected void paintComponent(Graphics g) {
                Graphics2D g2 = (Graphics2D) g.create();
                int w = getWidth();
                int h = getHeight();
                g2.setColor(DropTrackerTheme.SURFACE_0);
                g2.fillRect(0, 0, w, h);
                int filled = (int) Math.round((double) value / max * (w - 2));
                g2.setColor(body);
                g2.fillRect(1, 1, filled, h - 2);
                g2.setColor(fill);
                g2.fillRect(1, 1, filled, 2);
                g2.setColor(DropTrackerTheme.BRONZE);
                g2.setStroke(new BasicStroke(1));
                g2.drawRect(0, 0, w - 1, h - 1);
                g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING,
                    RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
                g2.setFont(FontManager.getRunescapeSmallFont());
                java.awt.FontMetrics fm = g2.getFontMetrics();
                int tx = (w - fm.stringWidth(text)) / 2;
                int ty = (h + fm.getAscent() - fm.getDescent()) / 2;
                g2.setColor(Color.BLACK);
                g2.drawString(text, tx + 1, ty + 1);
                g2.setColor(DropTrackerTheme.TEXT);
                g2.drawString(text, tx, ty);
                g2.dispose();
            }

            @Override
            public Dimension getPreferredSize() {
                return new Dimension(PluginPanel.PANEL_WIDTH - 40, 14);
            }

            @Override
            public Dimension getMaximumSize() {
                return new Dimension(Integer.MAX_VALUE, 14);
            }
        };
        bar.setToolTipText(ValueFormat.commas(have) + " / " + ValueFormat.commas(need));
        bar.setAlignmentX(Component.LEFT_ALIGNMENT);
        return bar;
    }

    /** Item sprite (rendered locally) or allowlisted remote icon, scaled to
     *  fit the slot with its aspect ratio preserved (item sprites are 36x32 —
     *  naive square scaling squishes them, raw addTo clips them). */
    void applyTaskIcon(JLabel target, @Nullable Integer iconItemId,
                               @Nullable String iconPath, int size) {
        java.util.function.Consumer<BufferedImage> apply = image ->
            setIconNow(target, fitIcon(image, size));
        BufferedImage image = null;
        if (iconItemId != null && iconItemId > 0) {
            image = itemImages.get(iconItemId, apply);
        } else if (iconPath != null) {
            image = remoteImages.get(iconPath, () -> applyRemoteLater(iconPath, apply));
        }
        if (image != null) {
            target.setIcon(fitIcon(image, size));
        }
    }

    /** EDT: an icon that arrived after its row was built. */
    private static void setIconNow(JLabel target, Icon icon) {
        target.setIcon(icon);
        target.revalidate();
        target.repaint();
    }

    /** Remote-fetch callback (background thread): hop to the EDT and apply. */
    private void applyRemoteLater(String iconPath, java.util.function.Consumer<BufferedImage> apply) {
        SwingUtilities.invokeLater(() -> {
            BufferedImage image = remoteImages.get(iconPath, null);
            if (image != null) {
                apply.accept(image);
            }
        });
    }

    /** Scale into a size×size box, centered, aspect ratio preserved. */
    private static ImageIcon fitIcon(BufferedImage source, int size) {
        return new ImageIcon(fitImage(source, size));
    }

    /** {@link #fitIcon} as a raw image, for callers that post-process it. */
    private static BufferedImage fitImage(BufferedImage source, int size) {
        int w = Math.max(source.getWidth(), 1);
        int h = Math.max(source.getHeight(), 1);
        float scale = Math.min((float) size / w, (float) size / h);
        int nw = Math.max(Math.round(w * scale), 1);
        int nh = Math.max(Math.round(h * scale), 1);
        BufferedImage out = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = out.createGraphics();
        g.setRenderingHint(RenderingHints.KEY_INTERPOLATION,
            RenderingHints.VALUE_INTERPOLATION_BILINEAR);
        g.drawImage(source, (size - nw) / 2, (size - nh) / 2, nw, nh, null);
        g.dispose();
        return out;
    }

    private static String kindLabel(String kind) {
        if (kind == null) {
            return "Event";
        }
        switch (kind) {
            case "bingo":
                return "Bingo";
            case "board_game":
                return "Board Game";
            case "clan_vs_clan":
                return "Clan vs Clan";
            default:
                return Character.toUpperCase(kind.charAt(0)) + kind.substring(1).replace('_', ' ');
        }
    }

    /** "Ends in 2d 4h" from the server's UTC ISO timestamp, or null. */
    @Nullable
    private static String endsIn(@Nullable String endsAtIso) {
        if (endsAtIso == null || endsAtIso.isEmpty()) {
            return null;
        }
        try {
            Instant ends = LocalDateTime.parse(endsAtIso).toInstant(ZoneOffset.UTC);
            Duration left = Duration.between(Instant.now(), ends);
            if (left.isNegative()) {
                return "Ending…";
            }
            long days = left.toDays();
            long hours = left.toHours() % 24;
            long minutes = left.toMinutes() % 60;
            if (days > 0) {
                return "Ends in " + days + "d " + hours + "h";
            }
            if (hours > 0) {
                return "Ends in " + hours + "h " + minutes + "m";
            }
            return "Ends in " + Math.max(minutes, 1) + "m";
        } catch (DateTimeParseException e) {
            return null;
        }
    }

    private static String truncate(String value, int max) {
        if (value == null) {
            return "";
        }
        return value.length() <= max ? value : value.substring(0, max - 1) + "…";
    }

    private static String escape(String value) {
        return PanelElements.escapeHtml(value);
    }

    static Color parseColor(String hex, Color fallback) {
        if (hex == null || hex.isEmpty()) {
            return fallback;
        }
        try {
            return Color.decode(hex);
        } catch (NumberFormatException e) {
            return fallback;
        }
    }

    private static String ordinal(int n) {
        if (n % 100 >= 11 && n % 100 <= 13) {
            return n + "th";
        }
        switch (n % 10) {
            case 1: return n + "st";
            case 2: return n + "nd";
            case 3: return n + "rd";
            default: return n + "th";
        }
    }

    /**
     * A vertical column that always matches the scroll viewport's width. A
     * plain JPanel inside a JScrollPane is laid out at its preferred width —
     * wider content silently overflows past the right edge (the horizontal
     * scrollbar is disabled), narrower content leaves a gutter.
     */
    static class ScrollableColumn extends JPanel implements Scrollable {
        @Override
        public Dimension getPreferredScrollableViewportSize() {
            return getPreferredSize();
        }

        @Override
        public int getScrollableUnitIncrement(Rectangle visible, int orientation, int direction) {
            return 16;
        }

        @Override
        public int getScrollableBlockIncrement(Rectangle visible, int orientation, int direction) {
            return 64;
        }

        @Override
        public boolean getScrollableTracksViewportWidth() {
            return true;
        }

        @Override
        public boolean getScrollableTracksViewportHeight() {
            return false;
        }
    }
}

package io.droptracker.ui.pages;

import java.awt.*;
import java.util.*;
import java.util.List;
import java.util.function.Consumer;

import javax.swing.*;
import javax.swing.Timer;
import javax.swing.border.EmptyBorder;

import io.droptracker.DropTrackerConfig;
import io.droptracker.api.DeathMessageApi;
import io.droptracker.service.PlayerModelService;
import io.droptracker.ui.DropTrackerTheme;
import io.droptracker.ui.admin.SettingsForm;
import io.droptracker.ui.components.DeathMessageDialog;
import lombok.RequiredArgsConstructor;
import net.runelite.api.Client;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;

/**
 * Things a player sets up once on the DropTracker that aren't plugin settings:
 * they live with the account on the server, so they follow it to every clan.
 * One card each.
 */
@RequiredArgsConstructor
public class ExtrasPanel {
    private final DropTrackerConfig config;
    private final Client client;
    private final DeathMessageApi deathMessageApi;
    private final PlayerModelService playerModelService;

    public JPanel create() {
        JPanel page = DropTrackerTheme.vbox(DropTrackerTheme.SURFACE_0);
        page.setBorder(new EmptyBorder(8, 0, 8, 0));
        page.add(SettingsForm.left(DropTrackerTheme.label("Extras", FontManager.getRunescapeBoldFont(), DropTrackerTheme.GOLD)));
        page.add(DropTrackerTheme.gap(4));
        page.add(wrapped("Set these up once. They're saved to your account on the DropTracker, not in your "
            + "plugin settings, so they follow you to every clan.", 60));
        page.add(DropTrackerTheme.gap(10));
        page.add(card("Your messages", "What your clans' Discord says when you die, log a collection log slot, "
            + "get a drop or set a personal best. Add a few and one is picked at random.", "Edit messages",
            b -> DeathMessageDialog.open(client, config, deathMessageApi)));
        page.add(DropTrackerTheme.gap(8));
        page.add(card("Your character", "The model shown on your droptracker.io profile. Stand still with your "
            + "favourite gear on, then send it. Your pet comes along too.", "Send my model", this::sendModel));
        page.add(DropTrackerTheme.gap(8));
        page.add(card("Your privacy", "Whether you're pinged when your drops are posted, and whether you show "
            + "on droptracker.io and in the DropTracker Discord. Your clans still see you.", "Privacy settings",
            this::privacy));
        // Spare height collects below the cards instead of inside them.
        page.add(Box.createVerticalGlue());
        return page;
    }

    /** The website's privacy switches (users table): key, label. */
    private static final String[][] PRIVACY = {
        {"hidden", "Hide me on droptracker.io and in the DropTracker Discord"},
        {"global_ping", "Ping me in the DropTracker Discord"},
        {"group_ping", "Ping me in my clans' Discords"},
        {"never_ping", "Never ping me (beats both above)"},
    };

    /** Loads the switches, shows them, saves what changed. */
    private void privacy(JButton button) {
        String name = config.lastAccountName();
        long hash = client.getAccountHash();
        button.setEnabled(false);
        deathMessageApi.privacy(name, hash, null, (settings, error) -> {
            button.setEnabled(true);
            if (settings == null) {
                JOptionPane.showMessageDialog(button, error, "Your privacy", JOptionPane.INFORMATION_MESSAGE);
                return;
            }
            JPanel form = new JPanel(new GridLayout(0, 1, 0, 4));
            List<JCheckBox> boxes = new ArrayList<>();
            for (String[] option : PRIVACY) {
                JCheckBox box = new JCheckBox(option[1], Boolean.TRUE.equals(settings.get(option[0])));
                boxes.add(box);
                form.add(box);
            }
            if (JOptionPane.showConfirmDialog(button, form, "Your privacy", JOptionPane.OK_CANCEL_OPTION,
                JOptionPane.PLAIN_MESSAGE) != JOptionPane.OK_OPTION) {
                return;
            }
            Map<String, Boolean> changes = new HashMap<>();
            for (int i = 0; i < PRIVACY.length; i++) {
                if (boxes.get(i).isSelected() != Boolean.TRUE.equals(settings.get(PRIVACY[i][0]))) {
                    changes.put(PRIVACY[i][0], boxes.get(i).isSelected());
                }
            }
            if (changes.isEmpty()) {
                return;
            }
            deathMessageApi.privacy(name, hash, changes, (saved, saveError) -> JOptionPane.showMessageDialog(button,
                saved != null ? "Saved. It can take a minute to show on the site." : saveError, "Your privacy",
                JOptionPane.INFORMATION_MESSAGE));
        });
    }

    /** Sends the character as it looks now; the button narrates, then resets. */
    private void sendModel(JButton button) {
        String idle = button.getText();
        button.setEnabled(false);
        button.setText("Sending model...");
        playerModelService.sendCurrentModel((ok, message) -> {
            // Already on the EDT.
            button.setText(ok ? "Model sent!" : "Failed to send");
            button.setToolTipText(message);
            Timer restore = new Timer(4000, ev -> {
                button.setText(idle);
                button.setEnabled(true);
            });
            restore.setRepeats(false);
            restore.start();
        });
    }

    private JComponent card(String title, String text, String button, Consumer<JButton> action) {
        JPanel card = io.droptracker.ui.components.PanelElements.heightCappedPanel();
        card.setLayout(new BoxLayout(card, BoxLayout.Y_AXIS));
        card.setBackground(DropTrackerTheme.SURFACE_1);
        card.setBorder(DropTrackerTheme.cardBorder(8, 10, 10, 10));
        card.add(SettingsForm.left(DropTrackerTheme.label(title, FontManager.getRunescapeFont(), DropTrackerTheme.TEXT)));
        card.add(wrapped(text, 80));
        card.add(DropTrackerTheme.gap(8));
        JButton open = DropTrackerTheme.button(button);
        open.addActionListener(e -> {
            String name = config.lastAccountName();
            if (name == null || name.isEmpty()) {
                JOptionPane.showMessageDialog(card, "Log in to the game first, so the DropTracker knows which "
                    + "account this is for.", title, JOptionPane.INFORMATION_MESSAGE);
                return;
            }
            action.accept(open);
        });
        open.setMaximumSize(new Dimension(Integer.MAX_VALUE, 28));
        card.add(SettingsForm.left(open));
        return SettingsForm.left(card);
    }

    /**
     * Muted text wrapped to a fixed width, {@code inset} px narrower than the
     * panel. Not a JTextArea: before the panel has a width, a wrapping text area
     * reports a tall preferred size and BoxLayout lets it soak up the card's
     * spare height, which pushed each button to the bottom of its card.
     */
    private static JComponent wrapped(String text, int inset) {
        return SettingsForm.left(DropTrackerTheme.label("<html><div style='width:" + (PluginPanel.PANEL_WIDTH - inset)
            + "px'>" + text + "</div></html>", FontManager.getRunescapeSmallFont(), DropTrackerTheme.TEXT_MUTED));
    }

}

package io.droptracker.ui.pages;

import io.droptracker.DropTrackerConfig;
import io.droptracker.api.*;
import io.droptracker.models.api.*;
import io.droptracker.ui.*;
import io.droptracker.ui.components.*;
import net.runelite.api.Client;
import net.runelite.client.game.ItemManager;
import net.runelite.client.util.LinkBrowser;
import javax.annotation.Nullable;

import okhttp3.*;

import javax.imageio.ImageIO;
import javax.swing.*;
import java.awt.*;
import java.awt.image.BufferedImage;
import java.util.concurrent.CompletableFuture;

public class GroupPanel extends SearchPage {
    private final DropTrackerPanel panel;
    private final OkHttpClient httpClient;

    private int currentGroupId = 2; // Track group ID instead of URL

    /**
     * Name of the group currently shown in the detail view. Used to make sure a
     * late-arriving async enrichment doesn't clobber a newer view.
     */
    private String activeDetailGroupName;

    public GroupPanel(Client client, DropTrackerConfig config, DropTrackerApi api, ItemManager itemManager, DropTrackerPanel panel, OkHttpClient httpClient) {
        super(client, config, api, itemManager);
        this.panel = panel;
        // Redirects off: group icons load from a hardcoded base, and following a
        // redirect would let the response choose the host instead.
        this.httpClient = httpClient.newBuilder()
            .followRedirects(false)
            .followSslRedirects(false)
            .build();
    }

    public JPanel create() {
        return create("DropTracker - Groups", "Search for a group", () -> performGroupSearch(""));
    }

    @Override
    protected void showDefaultState() {
        activeDetailGroupName = null;
        contentPanel.removeAll();

        JPanel defaultPanel = defaultPanel();
        defaultPanel.add(instructions("Search for a group by name above"));
        defaultPanel.add(DropTrackerTheme.gap(5));

        if (config.useApi()) {
            leaderboardPlaceholder = StateViews.loading("Loading top groups…");
            defaultPanel.add(leaderboardPlaceholder);
            defaultPanel.add(DropTrackerTheme.gap(10));
            LeaderboardComponents.loadLeaderboardAsync(leaderboardPlaceholder, () -> {
                try {
                    return api.getTopGroups();
                } catch (Exception e) {
                    return null;
                }
            }, this::showLeaderboard);
        }

        defaultPanel.add(buttonRow(PanelElements.createExternalLinkButton("Register your group", "Put your clan on the DropTracker from here", false, panel::openRegister), 0));
        defaultPanel.add(DropTrackerTheme.gap(5));
        defaultPanel.add(buttonRow(PanelElements.createExternalLinkButton("View All Groups", "Click to visit the group page", true, this::openGroupPage), 0));
        defaultPanel.add(Box.createVerticalGlue());
        show(defaultPanel);
    }

    private JPanel showLeaderboard(PanelCard.Top top) {
        // Render the preview instantly from the row's card; enrich asynchronously.
        return LeaderboardComponents.createLeaderboardTable("Top Groups", "Name", top.rows(),
            row -> showGroupDetailsFromRow(row));
    }

    public void performGroupSearch(String directQuery) {
        String searchQuery = directQuery.equalsIgnoreCase("") ? searchField.getText().trim() : directQuery;

        if (searchQuery.isEmpty()) {
            JOptionPane.showMessageDialog(contentPanel, "Please enter a group name to search for.");
            return;
        }

        runSearch("Searching for group…", () -> api.searchCard("/group_search", searchQuery), this::showGroupCard,
            "Group '" + searchQuery + "' was not found.");
    }

    @Override
    protected void showSearchError(String message) {
        activeDetailGroupName = null;
        super.showSearchError(message);
    }

    /**
     * Instantly shows the preview card a top-groups row carries (name, rank,
     * total loot, members, top member), then swaps in the full card from
     * /group_search once it arrives. Never blocks on the network.
     */
    private void showGroupDetailsFromRow(PanelCard.Row row) {
        final String groupName = row.getName();
        if (groupName == null || groupName.trim().isEmpty()) {
            return;
        }
        if (row.getCard() == null) {
            performGroupSearch(groupName);
            return;
        }
        showGroupCard(row.getCard());

        // Enrich in the background; drop the result if the user has navigated away.
        CompletableFuture.supplyAsync(() -> {
            try {
                return api.searchCard("/group_search", groupName);
            } catch (Exception e) {
                return null;
            }
        }).thenAccept(full -> SwingUtilities.invokeLater(() -> {
            if (full != null && groupName.equals(activeDetailGroupName)) {
                showGroupCard(full);
            }
        }));
    }

    private void showGroupCard(PanelCard card) {
        activeDetailGroupName = card.getTitle();
        if (card.getGroupId() != null) {
            currentGroupId = card.getGroupId();
            PanelElements.loadLootboardForGroup(currentGroupId);
        }
        PanelElements.cachedGroupName = card.getTitle();
        showCard(card);
    }

    @Override
    protected JComponent cardIcon(PanelCard card) {
        BufferedImage placeholderImg = new BufferedImage(50, 50, BufferedImage.TYPE_INT_ARGB);
        JLabel groupIcon = new JLabel(new ImageIcon(placeholderImg));
        groupIcon.setBackground(DropTrackerTheme.SURFACE_2);
        groupIcon.setPreferredSize(new Dimension(50, 50));
        groupIcon.setMaximumSize(new Dimension(50, 50));
        groupIcon.setMinimumSize(new Dimension(50, 50));
        loadGroupIcon(groupIcon, card.getIconPath());
        return groupIcon;
    }

    @Override
    protected void onCardAction(String type, String value) {
        if ("player".equals(type) && value != null) {
            panel.selectPanel("players");
            panel.updatePlayerPanel(value);
        } else if ("lootboard".equals(type)) {
            PanelElements.showLootboardForGroup(client, currentGroupId);
        }
    }

    private void openGroupPage() {
        try {
            LinkBrowser.browse(DropTrackerUrls.web("groups").toString());
        } catch (Exception e) {
            // Fallback: copy URL to clipboard or show message
            JOptionPane.showMessageDialog(contentPanel,
                    "Could not open browser. Please visit:\nhttps://www.droptracker.io/groups",
                    "Group Page",
                    JOptionPane.INFORMATION_MESSAGE);
        }
    }


    /**
     * Downloads the group icon, scales it to 50×50, then swaps it into the given label.
     * This runs off the EDT to avoid blocking the UI.
     *
     * @param imagePath path under {@code /img/} supplied by the API, e.g.
     *                  {@code "clans/2/icon.png"}. Not a URL — the host is decided
     *                  by {@link DropTrackerUrls#image}.
     */
    private void loadGroupIcon(JLabel iconLabel, String imagePath) {
        if (imagePath == null || imagePath.trim().isEmpty()) {
            return; // nothing to load
        }

        // we can't load gifs in swing panels natively, so we swap for a png alternative hoping it exists
        String pngPath = imagePath.replace(".gif", ".png");
        HttpUrl pngUrl = DropTrackerUrls.image(pngPath);
        HttpUrl originalUrl = DropTrackerUrls.image(imagePath);

        CompletableFuture.supplyAsync(() -> {
            ImageIcon icon = fetchScaledIcon(pngUrl);
            if (icon == null && !pngPath.equals(imagePath)) {
                // Fall back to the original path if the .png swap didn't exist.
                icon = fetchScaledIcon(originalUrl);
            }
            return icon;
        }).thenAccept(icon -> {
            if (icon != null) {
                SwingUtilities.invokeLater(() -> iconLabel.setIcon(icon));
            }
        });
    }

    private ImageIcon fetchScaledIcon(@Nullable HttpUrl url) {
        if (url == null) {
            return null;
        }
        Request request = new Request.Builder().url(url).build();
        try (Response response = httpClient.newCall(request).execute()) {
            ResponseBody body = response.body();
            if (!response.isSuccessful() || body == null) {
                return null;
            }
            BufferedImage img = ImageIO.read(body.byteStream());
            if (img == null) {
                return null;
            }
            Image scaled = img.getScaledInstance(50, 50, Image.SCALE_SMOOTH);
            return new ImageIcon(scaled);
        } catch (Exception e) {
            return null;
        }
    }

}

package io.droptracker.ui.pages;

import lombok.RequiredArgsConstructor;
import io.droptracker.api.*;
import io.droptracker.DropTrackerConfig;
import io.droptracker.ui.*;
import io.droptracker.ui.admin.GroupAdminWindow;
import io.droptracker.ui.components.*;
import io.droptracker.models.api.GroupAdmin;
import net.runelite.api.Client;
import net.runelite.client.ui.*;
import net.runelite.client.util.LinkBrowser;

import javax.annotation.Nullable;
import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;

@RequiredArgsConstructor
public class HomePanel {
    private final DropTrackerConfig config;
    private final DropTrackerApi api;
    private final Client client;
    private final DropTrackerPanel panel;
    private final GroupAdminApi groupAdminApi;

    // Store references for dynamic updates
    private JPanel homePanel;
    private @Nullable JPanel playerButtonRow;
    private int playerButtonIndex = -1; // Tracks where to insert the button
    /** Holds the "Group admin" card; empty (and so invisible) for most players. */
    private final JPanel adminSlot = DropTrackerTheme.vbox(DropTrackerTheme.SURFACE_0);
    private long adminCardHash = -1;

    public JPanel create() {
        homePanel = DropTrackerTheme.vbox(DropTrackerTheme.SURFACE_0);
        homePanel.setBorder(new EmptyBorder(5, 0, 5, 0));

        // Set maximum width to prevent expansion
        homePanel.setMaximumSize(new Dimension(PluginPanel.PANEL_WIDTH, Integer.MAX_VALUE));

        // When the API is disabled, lead with a call-to-action explaining what it unlocks.
        if (!config.useApi()) {
            homePanel.add(createApiCtaCard());
            homePanel.add(DropTrackerTheme.gap(8));
        }

        final JPanel welcomeMessagePanel = PanelElements.createCollapsiblePanel("Welcome to the DropTracker", PanelElements.getLatestWelcomeContent(api), true);

        final JPanel patchNotesPanel = PanelElements.createCollapsiblePanel("News / Updates", PanelElements.getLatestUpdateContent(config, api), false);

        homePanel.add(welcomeMessagePanel);
        homePanel.add(DropTrackerTheme.gap(8));

        // Global lootboard button row — a 1-cell grid so the button fills the
        // panel's full width instead of hugging its text.
        JButton viewGlobalButton = PanelElements.createLootboardButton("Global Lootboard", "Click to view the global lootboard", () -> PanelElements.showLootboardForGroup(client, 2));
        viewGlobalButton.setMargin(new Insets(3, 3, 3, 3));
        viewGlobalButton.setHorizontalAlignment(SwingConstants.CENTER);

        JPanel buttonPanel = new JPanel(new GridLayout(1, 1, 5, 0));
        buttonPanel.setBackground(DropTrackerTheme.SURFACE_0);
        buttonPanel.setAlignmentX(Component.LEFT_ALIGNMENT);
        buttonPanel.setMaximumSize(new Dimension(PluginPanel.PANEL_WIDTH, 30));
        buttonPanel.add(viewGlobalButton);
        homePanel.add(buttonPanel);

        // Note: playerButtonIndex will be set to the next component index
        playerButtonIndex = homePanel.getComponentCount();

        adminSlot.setAlignmentX(Component.LEFT_ALIGNMENT);
        homePanel.add(adminSlot);

        // Initialize player button (will add if config is available)
        updatePlayerButton();

        homePanel.add(DropTrackerTheme.gap(8));
        homePanel.add(patchNotesPanel);
        homePanel.add(DropTrackerTheme.gap(8));
        homePanel.add(createQuickLinks());
        // Collect leftover vertical space here instead of stretching the cards.
        homePanel.add(Box.createVerticalGlue());

        return homePanel;
    }

    /**
     * Prominent card shown when the API integration is disabled, explaining what
     * enabling it adds. The rest of the plugin (Discord webhook notifications) still
     * works without it.
     */
    private JPanel createApiCtaCard() {
        JPanel card = DropTrackerTheme.vbox(DropTrackerTheme.SURFACE_1);
        card.setBorder(DropTrackerTheme.accentCardBorder(10, 10, 10, 10));
        card.setMaximumSize(new Dimension(PluginPanel.PANEL_WIDTH, 170));
        card.setAlignmentX(Component.LEFT_ALIGNMENT);

        JLabel title = DropTrackerTheme.label("Unlock the full DropTracker", FontManager.getRunescapeBoldFont(), DropTrackerTheme.GOLD);
        title.setAlignmentX(Component.LEFT_ALIGNMENT);

        JTextArea body = new JTextArea(
            "Enable \"Use API Connections\" in the plugin settings to unlock:\n"
            + "- Live top player & group leaderboards\n"
            + "- Player and group lookups\n"
            + "- Submission tracking with retries\n"
            + "- Participation in clan events");
        body.setWrapStyleWord(true);
        body.setLineWrap(true);
        body.setOpaque(false);
        body.setEditable(false);
        body.setFocusable(false);
        body.setForeground(DropTrackerTheme.TEXT_MUTED);
        body.setFont(FontManager.getRunescapeSmallFont());
        body.setBorder(new EmptyBorder(5, 0, 5, 0));
        body.setAlignmentX(Component.LEFT_ALIGNMENT);

        JButton learnMore = DropTrackerTheme.button("Learn more");
        learnMore.setToolTipText("Read about the DropTracker API on the wiki");
        learnMore.setAlignmentX(Component.LEFT_ALIGNMENT);
        learnMore.addActionListener(e -> LinkBrowser.browse(DropTrackerUrls.web("wiki").toString()));

        card.add(title);
        card.add(body);
        card.add(learnMore);

        return card;
    }

    /** 2x2 grid of quick links: wiki, discord, suggestions, bug reports. */
    private JPanel createQuickLinks() {
        JPanel quickAccessPanel = DropTrackerTheme.vbox(DropTrackerTheme.SURFACE_0);
        quickAccessPanel.setAlignmentX(Component.LEFT_ALIGNMENT);

        JPanel topButtonRow = new JPanel(new GridLayout(1, 2, 5, 0));
        topButtonRow.setBackground(DropTrackerTheme.SURFACE_0);

        JPanel bottomButtonRow = new JPanel(new GridLayout(1, 2, 5, 0));
        bottomButtonRow.setBackground(DropTrackerTheme.SURFACE_0);

        topButtonRow.add(linkButton("Read the Wiki", DropTrackerUrls.web("wiki").toString()));
        topButtonRow.add(linkButton("Join Discord", DropTrackerUrls.web("discord").toString()));
        bottomButtonRow.add(linkButton("Suggest Features", DropTrackerUrls.web("forums", "suggestions").toString()));
        bottomButtonRow.add(linkButton("Report a Bug", DropTrackerUrls.web("forums", "bug-reports").toString()));

        quickAccessPanel.add(topButtonRow);
        quickAccessPanel.add(DropTrackerTheme.gap(8));
        quickAccessPanel.add(bottomButtonRow);

        quickAccessPanel.setMaximumSize(new Dimension(PluginPanel.PANEL_WIDTH, 68));
        return quickAccessPanel;
    }

    private JButton linkButton(String text, String url) {
        JButton button = DropTrackerTheme.button(text);
        button.addActionListener(e -> LinkBrowser.browse(url));
        button.setMargin(new Insets(0, 0, 0, 0));
        return button;
    }

    /**
     * Updates the player button based on current config state.
     * Can be called dynamically when the config changes.
     */
    public void updatePlayerButton() {
        if (homePanel == null) {
            return; // Panel not initialized yet
        }

        // Remove existing player button if it exists
        if (playerButtonRow != null) {
            homePanel.remove(playerButtonRow);
            playerButtonRow = null;
        }

        // Add player button if the API is on and an account has been seen
        if (config.useApi() && config.lastAccountName() != null && !config.lastAccountName().isEmpty()) {
            playerButtonRow = new JPanel(new GridLayout(1, 1));
            playerButtonRow.setBackground(DropTrackerTheme.SURFACE_0);
            playerButtonRow.setAlignmentX(Component.LEFT_ALIGNMENT);
            playerButtonRow.setMaximumSize(new Dimension(PluginPanel.PANEL_WIDTH, 30));

            JButton playerStatsButton = DropTrackerTheme.button("View your Stats");
            playerStatsButton.addActionListener(e -> {
                panel.selectPanel("player");
                panel.updatePlayerPanel(config.lastAccountName());
            });
            playerStatsButton.setMargin(new Insets(0, 0, 0, 0));

            playerButtonRow.add(playerStatsButton);

            // Insert at the correct position (after the global lootboard button)
            homePanel.add(playerButtonRow, playerButtonIndex);
        }

        refreshAdminCard();

        // Refresh the panel
        homePanel.revalidate();
        homePanel.repaint();
    }

    /**
     * Asks once per account which groups it may manage, and shows a small card
     * for them. Players who manage nothing never see it.
     */
    private void refreshAdminCard() {
        long hash = client.getAccountHash();
        String name = config.lastAccountName();
        if (!config.useApi() || hash == -1 || name == null || name.isEmpty()) {
            adminSlot.removeAll();
            adminCardHash = -1;
            return;
        }
        if (hash == adminCardHash) {
            return;
        }
        adminCardHash = hash;
        groupAdminApi.groups(name, hash, result -> {
            adminSlot.removeAll();
            if (result.value != null && !result.value.getGroups().isEmpty() && hash == adminCardHash) {
                adminSlot.add(DropTrackerTheme.gap(8));
                adminSlot.add(createAdminCard(result.value.getGroups()));
            }
            adminSlot.revalidate();
            adminSlot.repaint();
        });
    }

    private JPanel createAdminCard(java.util.List<GroupAdmin.Group> groups) {
        JPanel card = DropTrackerTheme.vbox(DropTrackerTheme.SURFACE_1);
        card.setBorder(DropTrackerTheme.accentCardBorder(8, 8, 8, 8));
        card.setAlignmentX(Component.LEFT_ALIGNMENT);
        card.setMaximumSize(new Dimension(PluginPanel.PANEL_WIDTH, Integer.MAX_VALUE));

        JLabel title = DropTrackerTheme.label("Group admin", FontManager.getRunescapeBoldFont(), DropTrackerTheme.GOLD);
        title.setAlignmentX(Component.LEFT_ALIGNMENT);
        card.add(title);
        JLabel hint = DropTrackerTheme.label("Manage your group in-game.",
            FontManager.getRunescapeSmallFont(), DropTrackerTheme.TEXT_MUTED);
        hint.setAlignmentX(Component.LEFT_ALIGNMENT);
        card.add(hint);

        for (GroupAdmin.Group group : groups.subList(0, Math.min(groups.size(), 4))) {
            card.add(DropTrackerTheme.gap(6));
            JPanel row = new JPanel(new BorderLayout(6, 0));
            row.setBackground(DropTrackerTheme.SURFACE_2);
            row.setBorder(new EmptyBorder(4, 6, 4, 4));
            row.setAlignmentX(Component.LEFT_ALIGNMENT);
            row.setMaximumSize(new Dimension(PluginPanel.PANEL_WIDTH, 30));

            JPanel names = DropTrackerTheme.vbox(DropTrackerTheme.SURFACE_2);
            names.add(DropTrackerTheme.label(group.getName(), FontManager.getRunescapeSmallFont(), DropTrackerTheme.TEXT));
            boolean owner = "owner".equals(group.getRole());
            names.add(DropTrackerTheme.label(owner ? "Owner" : "Admin", FontManager.getRunescapeSmallFont(),
                owner ? DropTrackerTheme.GOLD : DropTrackerTheme.TEXT_MUTED));
            row.add(names, BorderLayout.CENTER);

            JButton manage = DropTrackerTheme.button("Manage");
            manage.addActionListener(e -> GroupAdminWindow.open(client, config, groupAdminApi, groups, group.getId()));
            row.add(manage, BorderLayout.EAST);
            card.add(row);
        }
        return card;
    }
}

package io.droptracker.ui.pages;

import io.droptracker.api.*;
import io.droptracker.*;
import io.droptracker.models.api.*;
import io.droptracker.ui.components.*;
import io.droptracker.ui.DropTrackerTheme;
import net.runelite.api.Client;
import net.runelite.client.game.ItemManager;

import javax.swing.*;
import java.awt.*;

public class PlayerStatsPanel extends SearchPage {
    private final DropTrackerPlugin plugin;
    /** The player the detail card shows, for its Refresh button. */
    private String lastPlayer;

    public PlayerStatsPanel(Client client, DropTrackerPlugin plugin, DropTrackerConfig config, DropTrackerApi api, ItemManager itemManager) {
        super(client, config, api, itemManager);
        this.plugin = plugin;
    }

    public JPanel create() {
        return create("DropTracker - Players", "Search for a player", () -> performPlayerSearch(""));
    }

    @Override
    protected void showDefaultState() {
        contentPanel.removeAll();
        JPanel defaultPanel = defaultPanel();
        defaultPanel.add(DropTrackerTheme.gap(5));
        defaultPanel.add(instructions("Search for a player by name above"));
        defaultPanel.add(DropTrackerTheme.gap(5));

        // Get current player and add button if logged in
        String playerName = config.lastAccountName();

        if (playerName != null && !"Not logged in".equals(playerName)) {
            // Button to view current player stats
            JButton viewStatsButton = DropTrackerTheme.button("View My Stats (" + playerName + ")");
            viewStatsButton.setPreferredSize(new Dimension(200, 30));
            viewStatsButton.setToolTipText("View your DropTracker statistics");
            viewStatsButton.addActionListener(e -> performPlayerSearch(playerName));
            defaultPanel.add(buttonRow(viewStatsButton, 5));
            defaultPanel.add(DropTrackerTheme.gap(10));
        }

        if (config.useApi()) {
            leaderboardPlaceholder = StateViews.loading("Loading top players…");
            defaultPanel.add(leaderboardPlaceholder);
            LeaderboardComponents.loadLeaderboardAsync(leaderboardPlaceholder, () -> {
                try {
                    return api.getTopPlayers();
                } catch (Exception e) {
                    return null;
                }
            }, this::showPlayerLeaderboard);
        }

        defaultPanel.add(Box.createVerticalGlue());
        show(defaultPanel);
    }

    private JPanel showPlayerLeaderboard(PanelCard.Top top) {
        // Search for this player when clicked
        return LeaderboardComponents.createLeaderboardTable("Top Players", "Player", top.rows(),
            row -> performPlayerSearch(row.getName()));
    }

    public void performPlayerSearch(String searchQuery) {
        String toSearch;
        if (searchQuery.isEmpty()) {
            if (searchField != null && searchField.getText() != null && !searchField.getText().isEmpty()) {
                toSearch = searchField.getText().trim();
            } else if (plugin.getLocalPlayerName() != null && !plugin.getLocalPlayerName().isEmpty()) {
                toSearch = plugin.getLocalPlayerName();
            } else {
                return;
            }
        } else {
            toSearch = searchQuery;
        }

        runSearch("Searching for player…", () -> api.searchCard("/player_search", toSearch), card -> {
            lastPlayer = card.getTitle();
            showCard(card);
        }, "Player '" + toSearch + "' was not found.");
    }

    @Override
    protected void onCardAction(String type, String value) {
        if ("refresh".equals(type) && lastPlayer != null) {
            performPlayerSearch(lastPlayer);
        }
    }
}

package io.droptracker.ui.pages;

import lombok.AccessLevel;
import lombok.RequiredArgsConstructor;
import lombok.AllArgsConstructor;
import io.droptracker.DropTrackerConfig;
import io.droptracker.api.*;
import io.droptracker.models.api.PanelCard;
import io.droptracker.models.submissions.RecentSubmission;
import io.droptracker.ui.DropTrackerTheme;
import io.droptracker.ui.components.*;
import net.runelite.api.Client;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.*;
import net.runelite.client.util.LinkBrowser;

import javax.annotation.Nullable;
import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;
import java.awt.event.*;
import java.util.List;
import java.util.concurrent.*;
import java.util.function.Consumer;

/**
 * The shell the Players and Groups pages share: a search header over a content
 * area that swaps between the default view, a loading state, an error and a
 * detail card. Both pages lay their detail cards out the same way.
 */
@RequiredArgsConstructor(access = AccessLevel.PACKAGE)
abstract class SearchPage {
    protected final Client client;
    protected final DropTrackerConfig config;
    protected final DropTrackerApi api;
    protected final ItemManager itemManager;

    // UI components that we need to update
    protected JPanel contentPanel;
    protected JTextField searchField;
    protected JPanel leaderboardPlaceholder;

    protected abstract void showDefaultState();

    protected JPanel create(String title, String searchHint, Runnable onSearch) {
        JPanel mainPanel = DropTrackerTheme.vbox(DropTrackerTheme.SURFACE_0);

        LeaderboardComponents.HeaderResult headerResult = LeaderboardComponents.createHeaderPanel(title, searchHint, onSearch);
        searchField = headerResult.searchField;

        // Content panel that will change based on state
        contentPanel = DropTrackerTheme.vbox(DropTrackerTheme.SURFACE_0);
        contentPanel.setAlignmentX(Component.LEFT_ALIGNMENT);

        showDefaultState();

        mainPanel.add(headerResult.panel);
        mainPanel.add(DropTrackerTheme.gap(10));
        mainPanel.add(contentPanel);
        mainPanel.add(Box.createVerticalGlue());
        return mainPanel;
    }

    /** Replaces whatever the content area shows. */
    protected void show(JComponent view) {
        contentPanel.removeAll();
        contentPanel.add(view);
        contentPanel.revalidate();
        contentPanel.repaint();
    }

    /** Clears the search box and goes back to the default view. */
    protected void reset() {
        searchField.setText("");
        showDefaultState();
    }

    protected void showSearchError(String message) {
        show(StateViews.error(message, "Back to Search", this::reset));
    }

    /**
     * Shows {@code loadingText}, runs {@code lookup} off the EDT, then shows
     * the result. Keeps the failure cause so the user can tell "doesn't exist"
     * apart from "the API call failed".
     */
    protected <R> void runSearch(String loadingText, Callable<R> lookup, Consumer<R> onFound, String notFoundMessage) {
        show(StateViews.loading(loadingText));
        CompletableFuture.supplyAsync(() -> {
            try {
                return new SearchOutcome<>(lookup.call(), null);
            } catch (Exception e) {
                return new SearchOutcome<R>(null, e);
            }
        }).thenAccept(outcome -> SwingUtilities.invokeLater(() -> {
            if (outcome.result != null) {
                onFound.accept(outcome.result);
            } else if (outcome.error == null || isNotFound(outcome.error)) {
                showSearchError(notFoundMessage);
            } else {
                showSearchError("Search failed — the DropTracker API could not be reached. Please try again.");
            }
        }));
    }

    private static boolean isNotFound(Exception e) {
        String message = e.getMessage();
        return message != null && message.contains("status: 404");
    }

    @AllArgsConstructor(access = AccessLevel.PACKAGE)
    private static class SearchOutcome<R> {
        final R result;
        final Exception error;

    }

    /* ===================== default view pieces ===================== */

    protected static JPanel defaultPanel() {
        JPanel panel = DropTrackerTheme.vbox(DropTrackerTheme.SURFACE_0);
        panel.setAlignmentX(Component.CENTER_ALIGNMENT);
        return panel;
    }

    protected static JLabel instructions(String text) {
        JLabel label = DropTrackerTheme.label(text, FontManager.getRunescapeFont(), DropTrackerTheme.TEXT_MUTED);
        label.setAlignmentX(Component.CENTER_ALIGNMENT);
        label.setHorizontalAlignment(JLabel.CENTER);
        return label;
    }

    /** A full-width row holding one centered button. */
    protected static JPanel buttonRow(Component button, int gap) {
        JPanel row = new JPanel(new FlowLayout(FlowLayout.CENTER, gap, gap));
        row.setBackground(DropTrackerTheme.SURFACE_0);
        row.setAlignmentX(Component.CENTER_ALIGNMENT);
        row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 30));
        row.setPreferredSize(new Dimension(PluginPanel.PANEL_WIDTH, 30));
        row.add(button);
        return row;
    }

    /* ===================== detail card pieces ===================== */

    private static JPanel fixed(LayoutManager layout, int width, int height) {
        JPanel panel = new JPanel(layout);
        panel.setBackground(DropTrackerTheme.SURFACE_1);
        panel.setMaximumSize(new Dimension(width, height));
        panel.setPreferredSize(new Dimension(PluginPanel.PANEL_WIDTH - 40, height));
        panel.setAlignmentX(Component.LEFT_ALIGNMENT);
        return panel;
    }

    protected static JPanel statsGrid(JComponent... boxes) {
        JPanel stats = fixed(new GridLayout(2, 2, 5, 5), PluginPanel.PANEL_WIDTH, 100);
        stats.setBorder(new EmptyBorder(10, 0, 10, 0));
        for (JComponent box : boxes) {
            stats.add(box);
        }
        return stats;
    }

    protected static JButton actionButton(String text) {
        JButton button = DropTrackerTheme.button(text);
        button.setMargin(new Insets(0, 5, 0, 5));
        return button;
    }

    /** Recent submissions, or a placeholder carrying {@code emptyText}. */
    protected JPanel recent(List<RecentSubmission> submissions, boolean group, String emptyText) {
        return submissions != null && !submissions.isEmpty()
            ? PanelElements.createRecentSubmissionPanel(submissions, itemManager, client, group)
            : PanelElements.createRecentSubmissionsPlaceholder(emptyText);
    }

    /* ===================== server-composed cards ===================== */

    /** The page's own actions: player, lootboard, refresh. */
    protected abstract void onCardAction(String type, @Nullable String value);

    /** The header icon, if this page's cards have one. */
    @Nullable
    protected JComponent cardIcon(PanelCard card) {
        return null;
    }

    /**
     * Draws a detail card the server composed (api/panel_cards.py): every
     * string is escaped or set as plain text, and links are built here, on
     * our own hosts.
     */
    protected void showCard(PanelCard card) {
        JComponent icon = cardIcon(card);
        // Text wraps to what the icon and the clear button leave of the row.
        int width = PluginPanel.PANEL_WIDTH - (icon != null ? 150 : 80);
        JPanel names = DropTrackerTheme.vbox(DropTrackerTheme.SURFACE_1);
        names.add(left(DropTrackerTheme.label(html(card.getTitle(), width), FontManager.getRunescapeBoldFont(),
            DropTrackerTheme.TEXT)));
        PanelCard.Subtitle sub = card.getSubtitle();
        if (sub != null) {
            names.add(DropTrackerTheme.gap(5));
            JLabel label = DropTrackerTheme.label(sub.getText(), FontManager.getRunescapeSmallFont(),
                "good".equals(sub.getTone()) ? DropTrackerTheme.GREEN
                    : "warn".equals(sub.getTone()) ? DropTrackerTheme.EMBER : DropTrackerTheme.TEXT_MUTED);
            label.setToolTipText(html(sub.getTip(), 0));
            names.add(left(label));
        }
        List<String> lines = new java.util.ArrayList<>();
        if (card.getDescription() != null && !card.getDescription().isEmpty()) {
            lines.add(card.getDescription());
        }
        if (card.getListTitle() != null) {
            lines.add(card.getListTitle());
        }
        lines.addAll(card.getList());
        for (String line : lines) {
            names.add(left(DropTrackerTheme.label(html(line, width), FontManager.getRunescapeSmallFont(),
                DropTrackerTheme.TEXT_MUTED)));
        }

        JPanel header = new JPanel(new BorderLayout(10, 0));
        header.setBackground(DropTrackerTheme.SURFACE_1);
        header.setAlignmentX(Component.LEFT_ALIGNMENT);
        if (icon != null) {
            header.add(top(icon), BorderLayout.WEST);
        }
        header.add(names, BorderLayout.CENTER);
        header.add(top(LeaderboardComponents.createClearButton(this::reset)), BorderLayout.EAST);

        JComponent[] boxes = card.getStats().stream().map(this::statBox).toArray(JComponent[]::new);
        // One button per row: two side by side don't fit the panel's width.
        JPanel actions = DropTrackerTheme.vbox(DropTrackerTheme.SURFACE_1);
        actions.setAlignmentX(Component.LEFT_ALIGNMENT);
        for (PanelCard.Button b : card.getActions()) {
            Runnable run = () -> perform(b.getAction());
            JButton button;
            if ("lootboard".equals(b.getIcon())) {
                button = PanelElements.createLootboardButton(b.getLabel(), "Click to view the lootboard", run);
            } else {
                button = actionButton(b.getLabel());
                if ("external".equals(b.getIcon())) {
                    button.setIcon(PanelElements.getExternalLinkIcon());
                }
                button.addActionListener(e -> run.run());
            }
            JPanel row = new JPanel(new FlowLayout(FlowLayout.CENTER, 0, 2));
            row.setOpaque(false);
            row.setAlignmentX(Component.LEFT_ALIGNMENT);
            row.add(button);
            row.setMaximumSize(new Dimension(Integer.MAX_VALUE, row.getPreferredSize().height));
            actions.add(row);
        }
        showCard(header, statsGrid(boxes), recent(card.getRecent(), card.isRecentGroup(), card.getRecentEmpty()),
            actions);
    }


    /** A stat tile; one with an action is clickable and lights up on hover. */
    private JComponent statBox(PanelCard.Stat stat) {
        JPanel box = PanelElements.createStatBox(stat.getLabel(), stat.getValue());
        if (stat.getAction() != null) {
            box.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
            box.setToolTipText(html(stat.getTip(), 0));
            box.addMouseListener(new MouseAdapter() {
                @Override
                public void mouseClicked(MouseEvent e) {
                    perform(stat.getAction());
                }

                @Override
                public void mouseEntered(MouseEvent e) {
                    box.setBackground(DropTrackerTheme.SURFACE_3);
                }

                @Override
                public void mouseExited(MouseEvent e) {
                    box.setBackground(DropTrackerTheme.SURFACE_2);
                }
            });
        }
        return box;
    }

    private void perform(@Nullable PanelCard.Action action) {
        if (action == null || action.getType() == null) {
            return;
        }
        String value = action.getValue();
        if ("web".equals(action.getType()) && value != null) {
            LinkBrowser.browse(DropTrackerUrls.web(value.split("/")).toString());
        } else if ("discord".equals(action.getType())) {
            okhttp3.HttpUrl invite = DropTrackerUrls.discordInvite(value);
            if (invite != null) {
                LinkBrowser.browse(invite.toString());
            }
        } else {
            onCardAction(action.getType(), value);
        }
    }

    /** Escaped for a Swing HTML label (it would fetch a remote {@code <img>}); newlines kept. */
    @Nullable
    private static String html(@Nullable String text, int width) {
        return text == null ? null : "<html>" + (width > 0 ? "<div style='width:" + width + "px'>" : "")
            + PanelElements.escapeHtml(text).replace("\n", "<br/>") + "</html>";
    }

    /** Pins a header piece to the top instead of stretching it down the row. */
    private static JComponent top(JComponent c) {
        JPanel wrap = new JPanel(new BorderLayout());
        wrap.setOpaque(false);
        wrap.add(c, BorderLayout.NORTH);
        return wrap;
    }

    private static JComponent left(JComponent c) {
        c.setAlignmentX(Component.LEFT_ALIGNMENT);
        return c;
    }

    /** Shows a detail card: header, stats, recent submissions, actions. */
    protected void showCard(JPanel header, JPanel stats, JPanel recent, JPanel actions) {
        JPanel card = DropTrackerTheme.vbox(DropTrackerTheme.SURFACE_1);
        card.setBorder(DropTrackerTheme.cardBorder(10, 10, 10, 10));
        card.add(header);
        card.add(DropTrackerTheme.gap(10));
        card.add(stats);
        card.add(DropTrackerTheme.gap(10));
        card.add(recent);
        card.add(DropTrackerTheme.gap(10));
        card.add(actions);
        show(card);
    }
}

package io.droptracker.util;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import lombok.extern.slf4j.Slf4j;

import javax.inject.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.function.UnaryOperator;

/**
 * Data-driven registry mapping adventure-log / chat short boss names to their
 * canonical long names. The mappings live in
 * {@code /io/droptracker/boss_names.json} and were extracted verbatim from the
 * former switch statement in {@code WidgetEventHandler.longBossName}.
 *
 * Dynamic behavior (the {@code " (echo)"} suffix recursion and the
 * unmapped-name fallback) intentionally remains in code rather than data.
 */
@Slf4j
@Singleton
public final class BossNameRegistry {

    private static final String RESOURCE_PATH = "/io/droptracker/boss_names.json";
    private static final String ECHO_SUFFIX = " (echo)";

    private final Map<String, String> mappings;

    @Inject
    public BossNameRegistry(Gson gson) {
        this.mappings = loadMappings(gson);
    }

    private static Map<String, String> loadMappings(Gson gson) {
        try (InputStream is = BossNameRegistry.class.getResourceAsStream(RESOURCE_PATH);
             Reader reader = new BufferedReader(new InputStreamReader(Objects.requireNonNull(is), StandardCharsets.UTF_8))) {
            Map<String, String> mappings = gson.fromJson(reader,
                    new TypeToken<Map<String, String>>() {}.getType());
            return Collections.unmodifiableMap(Objects.requireNonNull(mappings));
        } catch (Exception e) {
            log.error("Failed to load boss name mappings from {}", RESOURCE_PATH, e);
            return Collections.emptyMap();
        }
    }

    /**
     * Resolves a short boss name to its canonical long name.
     * Names ending in {@code " (echo)"} (case-insensitive) are resolved by
     * recursing on the base name and re-appending {@code " (Echo)"}.
     *
     * @param shortName the short name to resolve
     * @return the canonical name, or the input unchanged when unmapped
     */
    public String canonicalName(String shortName) {
        return canonicalName(shortName, UnaryOperator.identity());
    }

    /**
     * Resolves a short boss name to its canonical long name, applying
     * {@code unmappedFallback} to the (possibly echo-stripped, lowercased)
     * name when no mapping exists. This mirrors the exact recursion order of
     * the original {@code longBossName} implementation.
     *
     * @param shortName        the short name to resolve
     * @param unmappedFallback transformation applied to unmapped names
     * @return the canonical name, or the fallback-transformed input when unmapped
     */
    public String canonicalName(String shortName, UnaryOperator<String> unmappedFallback) {
        String lowerBoss = shortName.toLowerCase();
        if (lowerBoss.endsWith(ECHO_SUFFIX)) {
            String actualBoss = lowerBoss.substring(0, lowerBoss.length() - ECHO_SUFFIX.length());
            return canonicalName(actualBoss, unmappedFallback) + " (Echo)";
        }

        String mapped = mappings.get(lowerBoss);
        return mapped != null ? mapped : unmappedFallback.apply(shortName);
    }

    /**
     * @return the number of short-name mappings loaded from the data file
     */
    public int size() {
        return mappings.size();
    }
}

package io.droptracker.util;

import io.droptracker.api.DropTrackerUrls;
import com.google.inject.Inject;

import io.droptracker.DropTrackerConfig;
import net.runelite.client.chat.*;
import net.runelite.api.*;
import net.runelite.api.events.CommandExecuted;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.util.*;

import java.awt.*;


public class ChatMessageUtil {

    @Inject
    private DropTrackerConfig config;

    @Inject
    private ChatMessageManager chatMessageManager;

    @Inject
    private Client client;
    @Inject
    private ClientThread clientThread;

    private static final java.awt.image.BufferedImage MUTED_ICON =
        ImageUtil.loadImageResource(ChatMessageUtil.class, "muted.png");
    /** Mod-icon slot holding {@link #MUTED_ICON}, claimed on first use. */
    private int mutedIconSlot = -1;

    @Subscribe
    public void onCommandExecuted(CommandExecuted event)
    {
        if (event.getCommand().equals("droptracker"))
        {
            LinkBrowser.browse(DropTrackerUrls.web("wiki", "why-api").toString());
        }
        if (event.getCommand().equals("debugurl"))
        {
            String apiUrlToUse = event.getArguments()[0];
            config.setCustomApiEndpoint(apiUrlToUse);
            sendChatMessage("All outgoing requests will now be sent to " + apiUrlToUse);
        }
    }
    public void warnApiSetting() {
        queueWarning("It is strongly recommended that you enable our API connections in the DropTracker plugin configuration. To learn more, type ::droptracker");
    }
    public void warnClogSetting() {
        queueWarning("Your collection log slots will not be tracked unless you enabled the game setting: Collection log - New addition notification");
    }

    private void queueWarning(String message) {
        Color color = ColorUtil.fromHex("#ff0000");
        String formatted = String.format("[%s] %s: %s",
                ColorUtil.wrapWithColorTag("DropTracker.io", color),
                "Warning",
                ColorUtil.wrapWithColorTag(message, color));
        chatMessageManager.queue(
                QueuedMessage.builder()
                        .type(ChatMessageType.CONSOLE)
                        .runeLiteFormattedMessage(formatted)
                        .build()
        );
    }

    public void sendChatMessage(String messageContent) {
        ChatMessageBuilder messageBuilder = new ChatMessageBuilder();
        messageBuilder.append(ChatColorType.HIGHLIGHT)
                .append("[")
                .append(ChatColorType.NORMAL)
                .append("DropTracker")
                .append(ChatColorType.HIGHLIGHT)
                .append("] ")
                .append(ChatColorType.NORMAL);
        messageBuilder.append(messageContent);
        final String finalMessage = messageBuilder.build();
        chatMessageManager.queue(
                QueuedMessage.builder()
                        .type(ChatMessageType.CONSOLE)
                        .runeLiteFormattedMessage(finalMessage)
                        .build()
        );
    }

    /**
     * Stamped onto a Discord author's name when their line is rendered in the
     * game's clan chat. Two jobs: a Discord user can never be mistaken for an
     * in-game clanmate, AND it is what stops the bridge from looping — the
     * render goes through {@code client.addChatMessage}, which posts a real
     * {@link net.runelite.api.events.ChatMessage}, so our own injected line
     * comes straight back through the plugin's chat subscriber. An in-game
     * display name cannot contain parentheses, so no real clanmate wears it.
     */
    public static final String DISCORD_SENDER_MARKER = "(Discord)";

    /**
     * Whether a CLAN_CHAT sender name is one of our own rendered Discord
     * lines. Substring rather than suffix: the marker is appended at the end
     * today, but the test has to keep holding if the rendered name is ever
     * decorated further, and no real name can contain it either way.
     */
    public static boolean isDiscordBridgeSender(String name) {
        return name != null && name.contains(DISCORD_SENDER_MARKER);
    }

    // Jagex string variables (rev241, 2026-10-07): a line defines a value in a
    // tag and references it later, e.g. quest broadcasts read
    // "<str_quest_name_0=Big Chompy Bird Hunting>X has completed a quest: <str_quest_name_0>".
    // Both halves are tags, so Text.removeTags alone deletes the name. The
    // underscore keeps <col=..>, <img=..> and <str> out of the match.
    private static final java.util.regex.Pattern TAG_VAR_DEF =
        java.util.regex.Pattern.compile("<([a-zA-Z]+_[a-zA-Z0-9_]+)=([^>]*)>");
    private static final java.util.regex.Pattern TAG_VAR_REF =
        java.util.regex.Pattern.compile("<([a-zA-Z]+_[a-zA-Z0-9_]+)>");

    /**
     * Drops {@code <name=value>} definitions and replaces each {@code <name>}
     * reference with its value; undefined references are left for removeTags.
     */
    public static String expandTagVariables(String str) {
        if (str == null || str.indexOf('=') < 0) {
            return str;
        }
        java.util.Map<String, String> values = new java.util.HashMap<>();
        java.util.regex.Matcher def = TAG_VAR_DEF.matcher(str);
        StringBuffer stripped = new StringBuffer();
        while (def.find()) {
            values.put(def.group(1).toLowerCase(), def.group(2));
            def.appendReplacement(stripped, "");
        }
        def.appendTail(stripped);
        if (values.isEmpty()) {
            return str;
        }
        java.util.regex.Matcher ref = TAG_VAR_REF.matcher(stripped);
        StringBuffer out = new StringBuffer();
        while (ref.find()) {
            String value = values.get(ref.group(1).toLowerCase());
            ref.appendReplacement(out, java.util.regex.Matcher.quoteReplacement(value != null ? value : ref.group()));
        }
        ref.appendTail(out);
        return out.toString();
    }

    /**
     * Discord→game bridge line, rendered to look like clan chat (visible only
     * to this client — nothing is sent to the game server). Approach adapted
     * from the TrackScape Connector, Copyright (c) 2023, Bailey Townsend,
     * BSD 2-Clause License (see LICENSE). The sender carries
     * {@link #DISCORD_SENDER_MARKER}; both strings must already be
     * sanitized/capped by the caller.
     */
    public void sendDiscordClanMessage(String sender, String messageContent) {
        // Callers arrive on the OkHttp callback thread (the notification
        // poller), and client.getClanChannel() is only safe on the client
        // thread — hop over for the read; queue() itself is thread-safe.
        clientThread.invokeLater(() -> {
            String clanName = client.getClanChannel() != null
                    ? net.runelite.client.util.Text.removeTags(client.getClanChannel().getName())
                    : "Discord";
            chatMessageManager.queue(
                    QueuedMessage.builder()
                            .type(ChatMessageType.CLAN_CHAT)
                            .name(sender + " " + DISCORD_SENDER_MARKER)
                            .sender(clanName)
                            .value(messageContent)
                            .build()
            );
        });
    }

    /**
     * A muted clanmate's line as their clan chat, with a muted icon before the
     * name: the game showed it to nobody, so clanmates without the plugin did
     * not see it. Client thread. False when the icon can't be loaded yet.
     */
    public boolean sendMutedClanMessage(String sender, String message, int accountIcon) {
        if (mutedIconSlot < 0) {
            IndexedSprite[] icons = client.getModIcons();
            if (icons == null) {
                return false;
            }
            IndexedSprite[] grown = java.util.Arrays.copyOf(icons, icons.length + 1);
            grown[icons.length] = ImageUtil.getImageIndexedSprite(MUTED_ICON, client);
            client.setModIcons(grown);
            mutedIconSlot = icons.length;
        }
        String clanName = client.getClanChannel() != null
                ? Text.removeTags(client.getClanChannel().getName()) : "";
        chatMessageManager.queue(
                QueuedMessage.builder()
                        .type(ChatMessageType.CLAN_CHAT)
                        .name((accountIcon >= 0 ? "<img=" + accountIcon + ">" : "")
                            + "<img=" + mutedIconSlot + ">" + sender)
                        .sender(clanName)
                        .value(message)
                        .build()
        );
        return true;
    }

    /**
     * Event-notification line: prefixed "[Event Name] (Team name):" instead
     * of the generic [DropTracker] tag so lines read as the event talking.
     * Both names must already be sanitized/capped by the caller; teamName is
     * optional (omitted before the first /event_state snapshot lands).
     */
    public void sendEventChatMessage(String eventName, String teamName, String messageContent) {
        sendEventChatMessage(eventName, teamName, null, null, null, messageContent);
    }

    /**
     * Accented event line: an uppercase type tag ("COMPLETE", "LEAD CHANGE",
     * "PROGRESS"...) in a brightened accent, the body in the accent itself,
     * and — when {@code emphasis} occurs in the body — that one substring
     * (usually the item name) lifted back to the bright shade. A null accent
     * reproduces the old uncoloured line exactly.
     *
     * <p>Colours must go through {@link ChatMessageBuilder#append(Color,
     * String)}: the plain {@code append(String)} runs {@code escapeJagex},
     * which would print the tags literally. All strings must already be
     * sanitized/capped by the caller.</p>
     */
    public void sendEventChatMessage(String eventName, String teamName,
                                     String tag, String accentHex,
                                     String emphasis, String messageContent) {
        // The chatbox style is game state (a varbit), readable only on the
        // client thread; callers arrive from the notification poller.
        clientThread.invokeLater(() -> chatMessageManager.queue(
                QueuedMessage.builder()
                        .type(ChatMessageType.CONSOLE)
                        .runeLiteFormattedMessage(formatEventLine(eventName, teamName, tag, accentHex,
                                emphasis, messageContent, opaqueChatbox()))
                        .build()
        ));
    }

    /**
     * True for the parchment chatbox: Fixed mode, or Resizable with the
     * "Transparent chatbox" option off. Same test RuneLite uses to pick its
     * opaque or transparent chat colours. Client thread only.
     */
    private boolean opaqueChatbox() {
        return !(client.isResized() && client.getVarbitValue(VarbitID.CHATBOX_TRANSPARENCY) == 1);
    }

    /** The event line's RuneLite-formatted text; see {@link #sendEventChatMessage}. */
    static String formatEventLine(String eventName, String teamName, String tag, String accentHex,
                                  String emphasis, String messageContent, boolean opaque) {
        ChatMessageBuilder messageBuilder = new ChatMessageBuilder();
        messageBuilder.append(ChatColorType.HIGHLIGHT)
                .append("[")
                .append(ChatColorType.NORMAL)
                .append(eventName)
                .append(ChatColorType.HIGHLIGHT)
                .append("] ");
        if (teamName != null && !teamName.isEmpty()) {
            messageBuilder.append("(")
                    .append(ChatColorType.NORMAL)
                    .append(teamName)
                    .append(ChatColorType.HIGHLIGHT)
                    .append("): ");
        }
        Color accent = accentHex != null ? ColorUtil.fromHex(accentHex) : null;
        if (accent == null) {
            if (tag != null && !tag.isEmpty()) {
                messageBuilder.append(ChatColorType.HIGHLIGHT).append(tag).append(" ");
            }
            messageBuilder.append(ChatColorType.NORMAL).append(messageContent);
        } else {
            Color body = chatAccent(accent, opaque);
            Color strong = chatEmphasis(accent, opaque);
            if (tag != null && !tag.isEmpty()) {
                messageBuilder.append(strong, tag).append(" ");
            }
            appendEmphasized(messageBuilder, messageContent, emphasis, body, strong);
        }
        return messageBuilder.build();
    }

    /* ---------------- chatbox contrast ---------------- */

    /**
     * Relative luminance ceilings for text on the opaque chatbox. Its
     * parchment sits near luminance 0.49, so 0.07 keeps a body line at about
     * 4.5:1 (WCAG AA) and 0.035 lifts the tag and item name clearly above it.
     */
    private static final double OPAQUE_BODY_LUMINANCE = 0.07;
    private static final double OPAQUE_STRONG_LUMINANCE = 0.035;
    /** Floor for the transparent chatbox, where text is shadowed over the game
     *  world: dim greys and deep reds disappear against busy scenery. */
    private static final double TRANSPARENT_MIN_LUMINANCE = 0.30;

    /** The accent as the body colour for this chatbox: the same hue, darkened
     *  to read on parchment, or lifted to read over the game world. */
    static Color chatAccent(Color accent, boolean opaque) {
        return opaque
                ? withMaxLuminance(accent, OPAQUE_BODY_LUMINANCE)
                : withMinLuminance(accent, TRANSPARENT_MIN_LUMINANCE);
    }

    /** The tag / item-name colour: a step darker than the body on parchment,
     *  a step brighter over the game world. */
    static Color chatEmphasis(Color accent, boolean opaque) {
        return opaque
                ? withMaxLuminance(accent, OPAQUE_STRONG_LUMINANCE)
                : ColorUtil.colorLerp(chatAccent(accent, false), Color.WHITE, 0.45);
    }

    /** WCAG relative luminance of an sRGB colour. */
    static double luminance(Color c) {
        return 0.2126 * linear(c.getRed()) + 0.7152 * linear(c.getGreen()) + 0.0722 * linear(c.getBlue());
    }

    private static double linear(int channel) {
        double v = channel / 255.0;
        return v <= 0.04045 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4);
    }

    /**
     * Darkens the colour (hue kept) until it is at most {@code max} luminance.
     * Coloured accents are made fully saturated first: a pastel only darkened
     * turns to mud (gold goes olive), while a deep saturated shade still reads
     * as its colour on parchment. Greys stay grey.
     */
    private static Color withMaxLuminance(Color c, double max) {
        if (luminance(c) <= max) {
            return c;
        }
        float[] hsb = Color.RGBtoHSB(c.getRed(), c.getGreen(), c.getBlue(), null);
        float saturation = hsb[1] < 0.3f ? hsb[1] : Math.max(hsb[1], 0.95f);
        for (float brightness = hsb[2]; brightness > 0f; brightness -= 0.01f) {
            Color out = Color.getHSBColor(hsb[0], saturation, brightness);
            if (luminance(out) <= max) {
                return out;
            }
        }
        return Color.BLACK;
    }

    /** Blends toward white until the colour reaches {@code min} luminance. */
    private static Color withMinLuminance(Color c, double min) {
        Color out = c;
        for (int i = 1; i <= 10 && luminance(out) < min; i++) {
            out = ColorUtil.colorLerp(c, Color.WHITE, i * 0.08);
        }
        return out;
    }

    /** Body in {@code accent}, with the first occurrence of {@code emphasis}
     *  (if any) in {@code bright}. Segments are appended side by side, never
     *  nested: RuneScape's {@code </col>} resets to the chat default rather
     *  than to an enclosing tag. */
    private static void appendEmphasized(ChatMessageBuilder builder, String body,
                                         String emphasis, Color accent, Color bright) {
        int at = emphasis != null && !emphasis.isEmpty() ? body.indexOf(emphasis) : -1;
        if (at < 0) {
            builder.append(accent, body);
            return;
        }
        if (at > 0) {
            builder.append(accent, body.substring(0, at));
        }
        builder.append(bright, emphasis);
        String rest = body.substring(at + emphasis.length());
        if (!rest.isEmpty()) {
            builder.append(accent, rest);
        }
    }
}

package io.droptracker.util;

import java.util.*;
import java.util.regex.*;

import javax.annotation.Nullable;

/**
 * What a member's own message may contain, checked as they type. Death,
 * collection log, drop and personal best messages share every rule but their
 * placeholders: the constants here are death's, and the other types pass the
 * placeholders and aliases the server sent with their messages.
 *
 * <p>The server is the authority (disc {@code db/member_messages.py}) and
 * refuses anything that breaks these rules with the same wording; this mirror
 * only exists so the editor can say what is wrong before a save round-trip.
 * The website carries the same mirror, and all three pin the same cases in
 * their tests — change a rule in all three places or the editors will
 * disagree with the server about what can be saved.
 */
public final class DeathMessageRules {

    public static final int MAX_MESSAGES = 5;
    public static final int MAX_LENGTH = 150;

    /** Placeholders a member may use, in display order. */
    public static final List<String> TOKENS = Collections.unmodifiableList(Arrays.asList(
        "{player_name}", "{killer}", "{location}", "{value_lost}", "{value_kept}", "{killer_combat_level}"));

    /** Also accepted, so a line copied from a group's own death messages works. */
    public static final Map<String, String> ALIASES = Map.of(
        "{source}", "{killer}",
        "{region_name}", "{location}");

    /** Death's accepted placeholders. */
    public static final Set<String> ALLOWED = allowed(TOKENS, ALIASES);

    /** The placeholders a type accepts: the ones it documents plus their aliases. */
    public static Set<String> allowed(List<String> tokens, Map<String, String> aliases) {
        Set<String> allowed = new LinkedHashSet<>(tokens);
        allowed.addAll(aliases.keySet());
        return allowed;
    }

    private static final Pattern TOKEN = Pattern.compile("\\{[a-z0-9_]+\\}", Pattern.CASE_INSENSITIVE);
    private static final Pattern DISCORD_ENTITY = Pattern.compile(
        "@everyone|@here|<@[&!]?\\d+>|<#\\d+>|<a?:\\w+:\\d+>|</[^<>:\\n]+:\\d+>|<t:-?\\d+(?::[a-z])?>",
        Pattern.CASE_INSENSITIVE);
    private static final Pattern LINK = Pattern.compile(
        "https?://\\S*|www\\.\\S*|\\bdiscord(?:app)?\\.(?:gg|com/invite)\\S*"
            + "|\\b[a-z0-9][a-z0-9-]*\\.(?:com|net|org|gg|io|co|me|xyz|tv|ly|link|site|app|dev|info|ru|uk|us)\\b\\S*",
        Pattern.CASE_INSENSITIVE);
    private static final Pattern BLOCK_MARKDOWN = Pattern.compile("^\\s*(?:#{1,3}\\s|-#\\s|>>>|>\\s)");
    /** Control characters plus the Unicode line and paragraph separators. */
    private static final Pattern CONTROL = Pattern.compile("[\\x00-\\x1f\\x7f\\u2028\\u2029]");
    private static final Pattern SPACES = Pattern.compile("\\s{2,}");

    private DeathMessageRules() {
    }

    /** Why one trimmed message cannot be saved, or null. Same wording as the server. */
    @Nullable
    public static String issue(String text, Set<String> allowed, List<String> shown) {
        if (text.codePointCount(0, text.length()) > MAX_LENGTH) {
            return "Each message can be at most " + MAX_LENGTH + " characters.";
        }
        if (CONTROL.matcher(text).find()) {
            return "Each message has to be a single line of text.";
        }
        if (DISCORD_ENTITY.matcher(text).find()) {
            return "Messages can't mention people, roles or channels, or use custom emoji.";
        }
        if (LINK.matcher(text).find()) {
            return "Messages can't contain links.";
        }
        if (BLOCK_MARKDOWN.matcher(text).find()) {
            return "Messages can't start with a heading or a quote.";
        }
        Set<String> unknown = new TreeSet<>();
        Matcher m = TOKEN.matcher(text);
        while (m.find()) {
            if (!allowed.contains(m.group().toLowerCase(Locale.ROOT))) {
                unknown.add(m.group());
            }
        }
        if (!unknown.isEmpty()) {
            return "Unknown placeholder" + (unknown.size() > 1 ? "s " : " ") + String.join(", ", unknown)
                + ". You can use " + String.join(", ", shown) + ".";
        }
        return null;
    }

    /**
     * What the server will store: each row trimmed, blank rows and exact
     * duplicates dropped, placeholder names lowercased.
     */
    public static List<String> normalize(List<String> rows) {
        List<String> out = new ArrayList<>();
        for (String raw : rows) {
            if (raw == null) {
                continue;
            }
            String text = lowercaseTokens(raw.trim());
            if (!text.isEmpty() && !out.contains(text)) {
                out.add(text);
            }
        }
        return out;
    }

    /** The first problem with the whole list, or null when it can be saved. */
    @Nullable
    public static String listIssue(List<String> rows, Set<String> allowed, List<String> shown) {
        List<String> cleaned = normalize(rows);
        for (String message : cleaned) {
            String issue = issue(message, allowed, shown);
            if (issue != null) {
                return issue;
            }
        }
        if (cleaned.size() > MAX_MESSAGES) {
            return "You can save at most " + MAX_MESSAGES + " messages.";
        }
        return null;
    }

    /**
     * A template filled with sample values the way the bot fills a real death:
     * {@code {player_name}} becomes the account's name, aliases read their
     * canonical placeholder's sample, and anything else is left out.
     */
    public static String preview(String template, Map<String, String> samples, Map<String, String> aliases,
                                 String playerName) {
        Matcher m = TOKEN.matcher(template);
        StringBuilder out = new StringBuilder();
        while (m.find()) {
            String token = m.group().toLowerCase(Locale.ROOT);
            String canonical = aliases.getOrDefault(token, token);
            String value;
            if ("{player_name}".equals(canonical)) {
                value = playerName == null ? "" : playerName;
            } else {
                value = samples.getOrDefault(canonical, "");
            }
            m.appendReplacement(out, Matcher.quoteReplacement(value));
        }
        m.appendTail(out);
        return SPACES.matcher(out.toString()).replaceAll(" ").trim();
    }

    private static String lowercaseTokens(String text) {
        Matcher m = TOKEN.matcher(text);
        StringBuilder out = new StringBuilder();
        while (m.find()) {
            m.appendReplacement(out, Matcher.quoteReplacement(m.group().toLowerCase(Locale.ROOT)));
        }
        m.appendTail(out);
        return out.toString();
    }
}

