package io.droptracker.util;

import java.io.*;
import java.nio.file.*;
import java.text.SimpleDateFormat;
import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import java.util.Date;

import io.droptracker.DropTrackerConfig;
import javax.inject.Inject;

import lombok.extern.slf4j.Slf4j;
import net.runelite.client.RuneLite;
@Slf4j
public class DebugLogger {

    private static final String PLUGIN_DIR_NAME = "droptracker";
    private static final String LOGS_DIR_NAME = "logs";
    private static final String BASE_LOG_FILENAME = "droptracker.log";

    private static volatile DebugLogger activeInstance;

    private final DropTrackerConfig config;
    private final File logsDir;
    private final File currentLogFile;
    private final Object writeLock = new Object();
    private volatile boolean sessionHeaderWritten = false;
    private FileWriter writer;

    @Inject
    public DebugLogger(DropTrackerConfig config) {
        this.config = config;

        File pluginDir = new File(RuneLite.RUNELITE_DIR, PLUGIN_DIR_NAME);
        this.logsDir = new File(pluginDir, LOGS_DIR_NAME);
        if (!logsDir.exists()) {
            logsDir.mkdirs();
        }

        this.currentLogFile = new File(logsDir, BASE_LOG_FILENAME);
        rotateIfExists(currentLogFile);

        try {
            this.writer = new FileWriter(currentLogFile, true);
        } catch (IOException e) {
            // If we cannot open the writer, logging will become a no-op
            this.writer = null;
        }

        activeInstance = this;
    }

    public boolean isEnabled() {
        return config.debugLogging();
    }

    public static void log(String message) {
        DebugLogger instance = activeInstance;
        if (instance == null) {
            return;
        }
        if (!instance.isEnabled()) {
            /* Still forwarding these messages to the default Sl4fj logger;
                since we use the DebugLogger throughout as an alternative in our plugin
            */
            log.debug(message);
            return;
        }
        log.debug("DebugLogger message: " + message);
        instance.ensureSessionHeader();
        instance.writeLine(message);
    }

    private void ensureSessionHeader() {
        if (sessionHeaderWritten) {
            return;
        }
        synchronized (writeLock) {
            if (sessionHeaderWritten) {
                return;
            }
            writeLine("---- Debug logging enabled for this session ----");
            sessionHeaderWritten = true;
        }
    }

    private void writeLine(String message) {
        synchronized (writeLock) {
            if (writer == null) {
                return;
            }
            try {
                String timestamp = DateTimeFormatter.ISO_LOCAL_DATE_TIME.format(LocalDateTime.now());
                writer.write("[" + timestamp + "] " + message + System.lineSeparator());
                writer.flush();
            } catch (IOException e) {
                // Swallow to avoid impacting game thread; debugging only
            }
        }
    }

    private void rotateIfExists(File file) {
        if (!file.exists()) {
            return;
        }

        long lastModified = file.lastModified();
        String ts = new SimpleDateFormat("yyyy-MM-dd_HHmmss").format(new Date(lastModified));
        File target = new File(logsDir, "droptracker-" + ts + ".log");

        if (target.exists()) {
            int idx = 1;
            File candidate;
            do {
                candidate = new File(logsDir, "droptracker-" + ts + "-" + idx + ".log");
                idx++;
            } while (candidate.exists());
            target = candidate;
        }

        try {
            Files.move(file.toPath(), target.toPath(), StandardCopyOption.ATOMIC_MOVE);
        } catch (IOException moveEx) {
            // Fallback to simple numeric roll if atomic move fails
            int idx = 1;
            File candidate;
            do {
                candidate = new File(logsDir, "droptracker-" + idx + ".log");
                idx++;
            } while (candidate.exists());
            // Best-effort rename; ignore result
            //noinspection ResultOfMethodCallIgnored
            file.renameTo(candidate);
        }
    }

    public void close() {
        synchronized (writeLock) {
            if (writer != null) {
                try {
                    writer.flush();
                    writer.close();
                } catch (IOException e) {
                    // Ignore on close
                } finally {
                    writer = null;
                }
            }
            if (activeInstance == this) {
                activeInstance = null;
            }
        }
    }
}

package io.droptracker.util;


import io.droptracker.api.DropTrackerUrls;
import com.google.gson.Gson;
import lombok.extern.slf4j.Slf4j;
import okhttp3.HttpUrl;
import okhttp3.*;
import org.jetbrains.annotations.*;

import javax.inject.*;
import java.io.*;
import java.util.*;
import java.util.concurrent.CompletableFuture;
import java.util.function.Function;

/**
 * This thread-safe singleton holds a mapping of item names to their item id, using the RuneLite API.
 * <p>
 * Unlike {@link net.runelite.client.game.ItemManager#search(String)}, this mapping supports untradable items.
 *
 * Author: iProdigy ( https://github.com/pajlads/DinkPlugin )
 */

@Slf4j
@Singleton
public class ItemIDSearch {
    private final Map<String, Integer> itemIdByName = Collections.synchronizedMap(new HashMap<>(16384));
    private @Inject OkHttpClient httpClient;
    private @Inject Gson gson;

    /**
     * @param name the exact in-game name of an item
     * @return the id associated with the item name, or null if not found
     */
    @Nullable
    public Integer findItemId(@NotNull String name) {
        return itemIdByName.get(name);
    }

    /**
     * Begins the initialization process for {@link #itemIdByName}
     * by querying item names and noted item ids from the RuneLite API,
     * before passing them to {@link #populate(Map, Set)}
     *
     * @implNote This operation does not block the current thread,
     * by utilizing OkHttp's thread pool and Java's Fork-Join common pool.
     */
    @Inject
    void init() {
        queryNamesById()
                .thenAcceptBothAsync(
                        queryNotedItemIds().exceptionally(e -> {
                            log.error("Failed to read noted items", e);
                            return Collections.emptySet();
                        }),
                        this::populate
                )
                .exceptionally(e -> {
                    log.error("Failed to read item names", e);
                    return null;
                });
    }

    /**
     * Populates {@link #itemIdByName} with the inverted mappings of {@code namesById},
     * while skipping noted items specified in {@code notedIds}.
     *
     * @param namesById a mapping of item id's to the corresponding in-game name
     * @param notedIds  the id's of noted items
     * @implNote When multiple non-noted item id's have the same in-game name, only the earliest id is saved
     */
    @VisibleForTesting
    void populate(@NotNull Map<Integer, String> namesById, @NotNull Set<Integer> notedIds) {
        namesById.forEach((id, name) -> {
            if (!notedIds.contains(id))
                itemIdByName.putIfAbsent(name, id);
        });

        log.debug("Completed initialization of item cache with {} entries", itemIdByName.size());
    }

    /**
     * @return a mapping of item ids to their in-game names, provided by the RuneLite API
     */
    private CompletableFuture<Map<Integer, String>> queryNamesById() {
        // Read JSON as Map<String, String> first
        return queryCache("names.json", Map.class)
                .thenApply(stringMap -> {
                    Map<Integer, String> result = new HashMap<>();
                    for (Object keyObj : stringMap.keySet()) {
                        String keyStr = (String) keyObj;
                        Object valObj = stringMap.get(keyStr);
                        // Defensive: valObj might be String or something else
                        String valueStr = valObj != null ? valObj.toString() : null;
                        result.put(Integer.parseInt(keyStr), valueStr);
                    }
                    return result;
                });

    }

    /**
     * @return a set of id's of noted items, provided by the RuneLite API
     */
    private CompletableFuture<Set<Integer>> queryNotedItemIds() {
        return queryCache("notes.json", Map.class)
                .thenApply(stringMap -> {
                    Set<Integer> keys = new HashSet<>();
                    for (Object keyObj : stringMap.keySet()) {
                        keys.add(Integer.parseInt((String) keyObj));
                    }
                    return keys;
                });

    }

    /**
     * @param fileName the name of the file to query from RuneLite's cache
     * @param type     a type token that indicates how the json response should be parsed
     * @return the transformed cache response, wrapped in a future
     */
    private <T> CompletableFuture<T> queryCache(@NotNull String fileName, @NotNull Class<T> clazz) {
        return readJson(httpClient, gson, DropTrackerUrls.itemCache(fileName), clazz);
    }

    public <T> CompletableFuture<T> readJson(@NotNull OkHttpClient httpClient, @NotNull Gson gson, @NotNull HttpUrl url, @NotNull Class<T> clazz) {
        return readUrl(httpClient, url, reader -> gson.fromJson(reader, clazz));
    }

    public <T> CompletableFuture<T> readUrl(@NotNull OkHttpClient httpClient, @NotNull HttpUrl url, @NotNull Function<Reader, T> transformer) {
        CompletableFuture<T> future = new CompletableFuture<>();
        Request request = new Request.Builder().url(url).build();
        httpClient.newCall(request).enqueue(new Callback() {
            @Override
            public void onFailure(@NotNull Call call, @NotNull IOException e) {
                future.completeExceptionally(e);
            }

            @Override
            public void onResponse(@NotNull Call call, @NotNull Response response) {
                try (Response autoClose = response) {
                    ResponseBody body = response.body();
                    if (body == null) {
                        future.completeExceptionally(new IOException("Empty response body from " + url));
                        return;
                    }
                    try (Reader reader = body.charStream()) {
                        future.complete(transformer.apply(reader));
                    }
                } catch (Exception e) {
                    future.completeExceptionally(e);
                }
            }
        });
        return future;
    }
    public class IntStringEntry {
        public int key;
        public String value;
    }
    public class IntIntEntry {
        public int key;
        public int value;
    }


}

package io.droptracker.util;

import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.ItemManager;
import net.runelite.client.util.AsyncBufferedImage;

import javax.annotation.Nullable;
import javax.inject.*;
import javax.swing.SwingUtilities;
import java.awt.image.BufferedImage;
import java.util.*;
import java.util.function.*;

/**
 * Item sprites for the side panel, without leaning on the game thread.
 *
 * <p>Two things about {@link ItemManager#getImage} make it a poor fit for a
 * panel that rebuilds on every event update. Its cache holds only 128
 * images, so a big bingo board evicts its own icons and every rebuild renders
 * them all again. And {@link AsyncBufferedImage#onLoaded} on an image that has
 * already loaded does not run the callback: it posts it to the client thread.
 * A rebuild used to queue one such callback per icon, image scaling and Swing
 * layout included, and the game thread ran the lot in a single frame. That is
 * the hitch players felt when an event pop-up landed mid-fight.
 *
 * <p>Here, loaded sprites stay in our own larger cache, new sprites are
 * rendered at most {@value #LOADS_PER_FRAME} per frame, and callbacks always
 * run on the EDT. The game thread only ever does the sprite render itself.
 */
@Singleton
public class ItemImageCache {
    private static final int MAX_ENTRIES = 512;
    static final int LOADS_PER_FRAME = 4;

    private final IntFunction<AsyncBufferedImage> loader;
    private final ClientThread clientThread;

    /** Access-ordered LRU. Guarded by {@code this}. */
    private final Map<Integer, BufferedImage> loaded =
        new LinkedHashMap<Integer, BufferedImage>(64, 0.75f, true) {
            @Override
            protected boolean removeEldestEntry(Map.Entry<Integer, BufferedImage> eldest) {
                return size() > MAX_ENTRIES;
            }
        };
    /** Callbacks per item still loading; a key here means it is queued or rendering. Guarded by {@code this}. */
    private final Map<Integer, List<Consumer<BufferedImage>>> waiting = new HashMap<>();
    /** Item ids not yet handed to the ItemManager. Guarded by {@code this}. */
    private final ArrayDeque<Integer> queue = new ArrayDeque<>();
    /** True while a drain is scheduled on the client thread. Guarded by {@code this}. */
    private boolean draining;

    @Inject
    public ItemImageCache(ItemManager itemManager, ClientThread clientThread) {
        this(itemManager::getImage, clientThread);
    }

    /** Test seam: ItemManager cannot be constructed outside the client. */
    ItemImageCache(IntFunction<AsyncBufferedImage> loader, ClientThread clientThread) {
        this.loader = loader;
        this.clientThread = clientThread;
    }

    /**
     * The sprite for {@code itemId} if it is already here, else null. On a
     * miss the sprite is queued, and {@code onReady} runs on the EDT once it
     * has been rendered. Callable from any thread.
     */
    @Nullable
    public BufferedImage get(int itemId, @Nullable Consumer<BufferedImage> onReady) {
        boolean schedule;
        synchronized (this) {
            BufferedImage image = loaded.get(itemId);
            if (image != null) {
                return image;
            }
            List<Consumer<BufferedImage>> callbacks = waiting.get(itemId);
            if (callbacks == null) {
                callbacks = new ArrayList<>(1);
                waiting.put(itemId, callbacks);
                queue.addLast(itemId);
            }
            if (onReady != null) {
                callbacks.add(onReady);
            }
            schedule = !draining;
            draining = true;
        }
        if (schedule) {
            clientThread.invokeLater(this::drain);
        }
        return null;
    }

    /**
     * Client thread: render up to {@value #LOADS_PER_FRAME} queued sprites.
     * Returning false asks the ClientThread to run this again next frame.
     */
    boolean drain() {
        for (int i = 0; i < LOADS_PER_FRAME; i++) {
            Integer itemId;
            synchronized (this) {
                itemId = queue.pollFirst();
                if (itemId == null) {
                    draining = false;
                    return true;
                }
            }
            // On the client thread this renders the sprite inline, unless it
            // was still in the ItemManager's own cache.
            AsyncBufferedImage image = loader.apply(itemId);
            final int id = itemId;
            image.onLoaded(() -> store(id, image));
        }
        synchronized (this) {
            if (queue.isEmpty()) {
                draining = false;
                return true;
            }
            return false;
        }
    }

    private void store(int itemId, BufferedImage image) {
        List<Consumer<BufferedImage>> callbacks;
        synchronized (this) {
            loaded.put(itemId, image);
            callbacks = waiting.remove(itemId);
        }
        if (callbacks == null || callbacks.isEmpty()) {
            return;
        }
        SwingUtilities.invokeLater(() -> {
            for (Consumer<BufferedImage> callback : callbacks) {
                callback.accept(image);
            }
        });
    }
}

package io.droptracker.util;

import net.runelite.client.game.ItemStack;

import java.util.*;
import java.util.stream.Collectors;

/**
 * Helpers for working with loot bundles ({@link ItemStack} collections).
 * Shared by {@link io.droptracker.events.DropHandler} (embed building and
 * cross-handler dedup) and {@link io.droptracker.service.RaidLootDeduplicator}
 * (raid chest re-loot suppression), so every consumer derives the same
 * signature for the same bundle.
 */
public final class ItemStacks {

    private ItemStacks() {
    }

    @SuppressWarnings("deprecation")
    public static Collection<ItemStack> stack(Collection<ItemStack> items) {
        final List<ItemStack> list = new ArrayList<>();

        for (final ItemStack item : items) {
            int quantity = 0;
            for (final ItemStack i : list) {
                if (i.getId() == item.getId()) {
                    quantity = i.getQuantity();
                    list.remove(i);
                    break;
                }
            }
            if (quantity > 0) {
                list.add(new ItemStack(item.getId(), item.getQuantity() + quantity, item.getLocation()));
            } else {
                list.add(item);
            }
        }

        return list;
    }

    /**
     * Order-independent signature of a loot bundle (consolidated id:qty pairs),
     * used to recognise the same loot arriving via two different loot events.
     */
    public static String signature(Collection<ItemStack> items) {
        return stack(items).stream()
                .map(i -> i.getId() + ":" + i.getQuantity())
                .sorted()
                .collect(Collectors.joining(","));
    }
}

