    public static final int MAD_ANGEL_POST_QUEST_B = 16314;

    /* Use a list for all special npc names, since Sailing added a number of them */
    public static final Set<Integer> SERVER_LOOT_NPC_IDS = Set.of(
                NpcID.YAMA,
                NpcID.HESPORI,
                NpcID.SAILING_BULL_SHARK_DEAD,
                NpcID.SAILING_HAMMERHEAD_SHARK_DEAD,
                NpcID.SAILING_TIGER_SHARK_DEAD,
                NpcID.SAILING_GREAT_WHITE_SHARK_DEAD,
                NpcID.SAILING_NARWHAL_DEAD,
                NpcID.SAILING_ORCA_DEAD,
                NpcID.SAILING_PYGMY_KRAKEN_DEAD,
                NpcID.SAILING_SPINED_KRAKEN_DEAD,
                NpcID.SAILING_ARMOURED_KRAKEN_DEAD,
                NpcID.SAILING_VAMPYRE_KRAKEN_DEAD,
                NpcID.SAILING_EAGLE_RAY_DEAD,
                NpcID.SAILING_BUTTERFLY_RAY_DEAD,
                NpcID.SAILING_STINGRAY_DEAD,
                NpcID.SAILING_MANTA_RAY_DEAD,
                NpcID.SAILING_OSPREY_DEAD,
                NpcID.SAILING_ALBATROSS_DEAD,
                NpcID.SAILING_FRIGATEBIRD_DEAD,
                NpcID.SAILING_TERN_DEAD,
                NpcID.SAILING_SEA_MOGRE_DEAD,
                NpcID.SAILING_DOLPHIN_DEAD,
                NpcID.SAILING_VEILED_KRAKEN_DEAD,
                NpcID.MAGGOT_KING,
                NpcID.MAGGOT_KING_CORPSE,
                // Mad Angel awards loot server-side, so nothing spawns on the
                // death tile for LootManager to scrape and NpcLootReceived
                // never fires — kills were tracked (166 PBs landed on release
                // day) while every drop was silently discarded by the
                // onServerNpcLoot gate below.
                MAD_ANGEL_QUEST_A,
                MAD_ANGEL_QUEST_B,
                MAD_ANGEL_POST_QUEST_A,
                MAD_ANGEL_POST_QUEST_B
        );

    /**
     * Server-loot npc ids published by the backend at
     * {@code content/server_loot_npc_ids.txt}, layered over the compiled-in
     * {@link #SERVER_LOOT_NPC_IDS} above. This is what stops a newly released
     * boss (Mad Angel, 2026-07-29) needing a plugin release before its drops
     * track at all.
     * <p>
     * Volatile immutable snapshot: written by the executor thread that fetches
     * the list, read by the loot handlers on the client thread.
     */
    private static volatile Set<Integer> remoteServerLootNpcIds = Collections.emptySet();

    /**
     * Install the published server-loot id list. A null/empty argument (fetch
     * failed, file unreachable, garbage body) is ignored rather than applied,
     * so a bad publish or an offline client degrades to the compiled-in list
     * instead of losing loot tracking for every server-loot boss.
     */
    public static void setRemoteServerLootNpcIds(Collection<Integer> ids) {
        if (ids == null || ids.isEmpty()) {
            return;
        }
        remoteServerLootNpcIds = Collections.unmodifiableSet(new HashSet<>(ids));
    }

    /**
     * Whether this npc's loot is awarded server-side, i.e. arrives via
     * {@code ServerNpcLoot} and must not also be submitted from the
     * client-side {@code NpcLootReceived} path. The union of the compiled-in
     * list and the published one — never fewer ids than the build shipped with.
     */
    public static boolean isServerLootNpc(int npcId) {
        return SERVER_LOOT_NPC_IDS.contains(npcId) || remoteServerLootNpcIds.contains(npcId);
    }

    /* Canonical encounter names that a multi-part boss's sub-NPCs are remapped
     * to (see canonicalizeSpecialSource). Loot for these can arrive via more
     * than one RuneLite loot event, so they need cross-handler de-duplication. */
    public static final Set<String> REMAP_TARGET_NAMES = Set.of(
            "Royal Titans", "Grotesque Guardians", "The Corrupted Gauntlet", "The Gauntlet");

    /**
     * Collapse the raw sub-NPC name of a multi-part boss to its canonical
     * encounter name (e.g. "Dusk" -> "Grotesque Guardians"). Names without a
     * remapping are returned unchanged. Centralises the remapping that used to
     * live inline in {@code DropHandler.onLootReceived} so every loot path
     * (NpcLootReceived / ServerNpcLoot / LootReceived) agrees on one name — a
     * prerequisite for reliably de-duplicating the same kill across handlers.
     */
    public static String canonicalizeSpecialSource(String name) {
        if (name == null) {
            return null;
        }
        switch (name) {
            case "Branda the Fire Queen":
            case "Eldric the Ice King":
                return "Royal Titans";
            case "Dusk":
                return "Grotesque Guardians";
            case "Corrupted Hunllef":
                return "The Corrupted Gauntlet";
            case "Crystalline Hunllef":
                return "The Gauntlet";
            default:
                return name;
        }
    }

    /**
     * Whether loot from this (already canonicalised) source can be delivered by
     * more than one RuneLite loot event for a single kill — the bosses in
     * {@link #SPECIAL_NPC_NAMES} (Whisperer/Araxxor/Maggot King and the raw
     * sub-NPC names) plus the {@link #REMAP_TARGET_NAMES} they collapse to.
     * These are the only sources that need duplicate submissions suppressed;
     * ordinary NPCs (which can legitimately be multi-killed in one tick with
     * identical loot) are intentionally excluded.
     */
    public static boolean isMultiPathLootSource(String canonicalName) {
        return canonicalName != null
                && (SPECIAL_NPC_NAMES.contains(canonicalName) || REMAP_TARGET_NAMES.contains(canonicalName));
    }

    public static final Pattern PRIMARY_REGEX = Pattern.compile(
            "Your (?<key>[\\w\\s:'-]+) (?<type>kill|chest|completion|success) count is:? (?<value>[\\d,]+)");
    public static final Pattern SECONDARY_REGEX = Pattern
            .compile("Your (?<type>kill|chest|completed) (?<key>[\\w\\s:]+) count is:? (?<value>[\\d,]+)");

    @SuppressWarnings("null")
    public static String getStandardizedSource(LootReceived event, DropTrackerPlugin plugin) {
        if (isCorruptedGauntlet(event, plugin)) {
            return CG_NAME;
        }
        if (plugin.lastDrop == null) {
            return event.getName();
        } else if (shouldUseChatName(event, plugin) && plugin.lastDrop.getSource() != null) {
            return plugin.lastDrop.getSource(); // distinguish entry/expert/challenge modes
        }
        return event.getName();
    }

    @SuppressWarnings("null")
    private static boolean isCorruptedGauntlet(LootReceived event, DropTrackerPlugin plugin) {
        return event.getType() == LootRecordType.EVENT && plugin.lastDrop != null
                && "The Gauntlet".equals(event.getName())
                && (CG_NAME.equals(plugin.lastDrop.getSource()) || CG_BOSS.equals(plugin.lastDrop.getSource())
                    || "The Corrupted Gauntlet".equals(plugin.lastDrop.getSource()));
    }

    private static boolean shouldUseChatName(LootReceived event, DropTrackerPlugin plugin) {
        assert plugin.lastDrop != null;
        String lastSource = plugin.lastDrop.getSource();
        Predicate<String> coincides = source -> source.equals(event.getName()) && lastSource.startsWith(source);
        return coincides.test(TOA) || coincides.test(TOB) || coincides.test(COX) || coincides.test(TFA);
    }

    public static Optional<Pair<String, Integer>> parseBoss(String message, DropTrackerPlugin plugin) {
        Matcher primary = PRIMARY_REGEX.matcher(message);
        Matcher secondary = SECONDARY_REGEX.matcher(message);
        Pair<String, Integer> mostRecentNpcData = null;

        if (primary.find()) {
            String boss = parsePrimaryBoss(primary.group("key"), primary.group("type"));
            String count = primary.group("value");
            if (boss != null) {
                try {
                    int killCount = Integer.parseInt(count.replace(",", ""));
                    mostRecentNpcData = Pair.of(boss, killCount);
                    plugin.ticksSinceNpcDataUpdate = 0;
                    return Optional.of(mostRecentNpcData);
                } catch (NumberFormatException ignored) {
                }
            }
        } else if (secondary.find()) {
            String key = parseSecondary(secondary.group("key"));
            String value = secondary.group("value");
            if (key != null) {
                try {
                    int killCount = Integer.parseInt(value.replace(",", ""));
                    mostRecentNpcData = Pair.of(key, killCount);
                    plugin.ticksSinceNpcDataUpdate = 0;
                    return Optional.of(mostRecentNpcData);
                } catch (NumberFormatException ignored) {
                }
            }
        }
        return Optional.empty();
    }

    @Nullable
    @VisibleForTesting
    static String parsePrimaryBoss(String boss, String type) {
        switch (type.toLowerCase()) {
            case "chest":
                if ("Barrows".equalsIgnoreCase(boss))
                    return boss;
                if ("Lunar".equals(boss))
                    return boss + " " + type;
                return null;

            case "completion":
                if (GAUNTLET_NAME.equalsIgnoreCase(boss))
                    return GAUNTLET_BOSS;
                if (CG_NAME.equalsIgnoreCase(boss))
                    return CG_BOSS;
                return null;

            case "kill":
                return boss;

            case "success":
                return boss;

            default:
                return null;
        }
    }

    @VisibleForTesting
    static String parseSecondary(String boss) {
        if (boss == null || "Wintertodt".equalsIgnoreCase(boss))
            return boss;

        int modeSeparator = boss.lastIndexOf(':');
        String raid = modeSeparator > 0 ? boss.substring(0, modeSeparator) : boss;
        if (raid.equalsIgnoreCase("Theatre of Blood")
                || raid.equalsIgnoreCase("Tombs of Amascut")
                || raid.equalsIgnoreCase("Chambers of Xeric")
                || raid.equalsIgnoreCase("Chambers of Xeric Challenge Mode")
                || raid.equalsIgnoreCase(TFA))
            return boss;

        return null;
    }

}

package io.droptracker.util;

import javax.annotation.Nullable;

/**
 * Decides which RSN a submission is sent under.
 *
 * <p>Every submission the plugin builds carries a {@code player_name}, and the
 * backend resolves that name against a real account. An unreadable RSN used to
 * be replaced with the literal string {@code "Unknown"} — which is not an inert
 * placeholder. It is a name like any other, it matches a real (but empty) Wise
 * Old Man record, and adopting that record renamed whichever live account the
 * submission resolved to, breaking its identity and silently discarding
 * everything it submitted afterwards. The server no longer trusts that record,
 * but the plugin has no business inventing a name in the first place.
 *
 * <p>So: resolve honestly or not at all. A caller that gets {@code null} skips
 * the submission — an event with no identity has nothing to attach itself to.
 */
public final class PlayerIdentity {

    private PlayerIdentity() {
    }

    /**
     * Resolves the RSN to submit under.
     *
     * <p>The live name is unreadable whenever the local player is gone: at
     * logout and during a world hop (which is where most of these come from —
     * the XP handler snapshots on both), and in the short window after login
     * before the name arrives. The account hash outlives the local player in
     * all three, so the cached name covers them — and it is trusted only when
     * it was stored against the hash logged in right now, so it can never
     * attribute an event to whichever account the player was on previously.
     *
     * @param liveName          name read from the client
     * @param accountHash       account hash of the session being submitted for
     * @param cachedName        last name stored by the plugin at login
     * @param cachedAccountHash account hash {@code cachedName} was stored for
     * @return the RSN, or {@code null} when it cannot be established
     */
    @Nullable
    public static String resolve(@Nullable String liveName, @Nullable String accountHash,
                                 @Nullable String cachedName, @Nullable String cachedAccountHash) {
        if (liveName != null && !liveName.trim().isEmpty()) {
            return liveName;
        }
        if (cachedName == null || cachedName.trim().isEmpty()) {
            return null;
        }
        // The account hash is the only thing that proves the cached name
        // belongs to this session rather than the last one.
        if (!isUsableAccountHash(accountHash) || cachedAccountHash == null
                || !accountHash.trim().equals(cachedAccountHash.trim())) {
            return null;
        }
        return cachedName;
    }

    /**
     * True when an account hash identifies a logged-in account. The client
     * reports -1 when logged out, and the plugin substitutes 0 when there is no
     * client at all; both are strings the backend would otherwise try to match
     * a player row against.
     */
    public static boolean isUsableAccountHash(@Nullable String accountHash) {
        if (accountHash == null) {
            return false;
        }
        String trimmed = accountHash.trim();
        return !trimmed.isEmpty() && !"0".equals(trimmed) && !"-1".equals(trimmed);
    }

    /**
     * True when a submission's {@code player_name} field is unusable. Used as
     * the last line of defence before a payload leaves the client.
     */
    public static boolean isMissingName(@Nullable String playerName) {
        return playerName == null || playerName.trim().isEmpty();
    }
}

package io.droptracker.util;


import com.google.gson.Gson;
import com.google.gson.annotations.SerializedName;
import com.google.gson.reflect.TypeToken;
import lombok.*;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ItemComposition;
import net.runelite.client.game.*;

import javax.inject.*;
import java.io.*;
import java.util.*;
import java.util.stream.Collectors;

@Slf4j
@Singleton
public class Rarity {
    private final Map<String, Collection<Drop>> dropsByNpcName = new HashMap<>(1024);
    private @Inject Gson gson;
    private @Inject ItemManager itemManager;
    public static final double EPSILON = 0.00001;
    private static final int[] FACTORIALS;

    @Inject
    void init() {
        Map<String, List<RawDrop>> raw;
        try (InputStream is = getClass().getResourceAsStream("/npc_drops.json");
             Reader reader = new BufferedReader(new InputStreamReader(Objects.requireNonNull(is)))) {
            raw = gson.fromJson(reader,
                    new TypeToken<Map<String, List<RawDrop>>>() {}.getType());
        } catch (Exception e) {
            log.error("Failed to read monster drop rates", e);
            return;
        }

        raw.forEach((npcName, rawDrops) -> {
            List<Drop> drops = rawDrops.stream()
                    .map(RawDrop::transform)
                    .flatMap(Collection::stream)
                    .collect(Collectors.toList());
            dropsByNpcName.put(npcName, drops);
        });
    }

    public OptionalDouble getRarity(String npcName, int itemId, int quantity) {
        ItemComposition composition = itemId >= 0 ? itemManager.getItemComposition(itemId) : null;
        int canonical = composition != null && composition.getNote() != -1 ? composition.getLinkedNoteId() : itemId;
        String itemName = composition != null ? composition.getMembersName() : "";
        Collection<Integer> variants = new HashSet<>(
                ItemVariationMapping.getVariations(ItemVariationMapping.map(canonical))
        );
        return dropsByNpcName.getOrDefault(npcName, Collections.emptyList())
                .stream()
                .filter(drop -> drop.getMinQuantity() <= quantity && quantity <= drop.getMaxQuantity())
                .filter(drop -> {
                    int id = drop.getItemId();
                    if (id == itemId) return true;
                    return variants.contains(id) && itemName.equals(itemManager.getItemComposition(id).getMembersName());
                })
                .mapToDouble(Drop::getProbability)
                .reduce(Double::sum);
    }

    @Value
    private static class Drop {
        int itemId;
        int minQuantity;
        int maxQuantity;
        double probability;
    }

    @Data
    @Setter(AccessLevel.PRIVATE)
    private static class RawDrop {
        private @SerializedName("i") int itemId;
        private @SerializedName("r") Integer rolls;
        private @SerializedName("d") double denominator;
        private @SerializedName("q") Integer quantity;
        private @SerializedName("m") Integer quantMin;
        private @SerializedName("n") Integer quantMax;

        Collection<Drop> transform() {
            int rounds = rolls != null ? rolls : 1;
            int min = quantMin != null ? quantMin : quantity;
            int max = quantMax != null ? quantMax : quantity;
            double prob = 1 / denominator;

            if (rounds == 1) {
                return List.of(new Drop(itemId, min, max, prob));
            }
            List<Drop> drops = new ArrayList<>(rounds);
            for (int successCount = 1; successCount <= rounds; successCount++) {
                double density = binomialProbability(prob, rounds, successCount);
                drops.add(new Drop(itemId, min * successCount, max * successCount, density));
            }
            return drops;
        }
        public double binomialProbability(double p, int nTrials, int kSuccess) {
            // https://en.wikipedia.org/wiki/Binomial_distribution#Probability_mass_function
            return binomialCoefficient(nTrials, kSuccess) * Math.pow(p, kSuccess) * Math.pow(1 - p, nTrials - kSuccess);
        }
        private int binomialCoefficient(int n, int k) {
            assert n < FACTORIALS.length && k <= n && k >= 0;
            return FACTORIALS[n] / (FACTORIALS[k] * FACTORIALS[n - k]); // https://en.wikipedia.org/wiki/nCk
        }
    }

    static {
        // precompute factorials from 0 to 9 for n-choose-k formula
        int n = 10; // max rolls in npc_drops.json is 9 (for Bloodthirsty Leagues IV tier 5 relic)
        int[] facts = new int[n];
        facts[0] = 1; // 0! = 1
        for (int i = 1; i < n; i++) {
            facts[i] = i * facts[i - 1];
        }
        FACTORIALS = facts;
    }
}

package io.droptracker.util;

import lombok.AccessLevel;
import lombok.AllArgsConstructor;
import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import lombok.extern.slf4j.Slf4j;

import javax.annotation.Nullable;
import javax.inject.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

/**
 * Resolves an OSRS map region id to a human-readable area name
 * ("Theatre of Blood", "Catacombs of Kourend") and a coarse area type.
 *
 * The data in {@code /io/droptracker/region_names.json} was extracted verbatim
 * from RuneLite's {@code DiscordGameEventType} enum (BSD 2-Clause, same licence
 * as this plugin), which maintains this mapping for Discord rich presence. That
 * enum is package-private so it cannot be imported; regenerate the resource by
 * re-parsing the enum constants that carry a {@code DiscordAreaType} and one or
 * more region ids.
 *
 * Region ids are only meaningful when they come from an instance-corrected
 * {@link net.runelite.api.coords.WorldPoint} — inside an instance the raw
 * {@code getWorldLocation()} returns template coordinates that resolve to the
 * wrong area (or none at all). See {@code DeathHandler#currentLocation}.
 */
@Slf4j
@Singleton
public final class RegionNameRegistry {

    private static final String RESOURCE_PATH = "/io/droptracker/region_names.json";

    /** A named area and the coarse bucket RuneLite files it under. */
    @AllArgsConstructor(access = AccessLevel.PACKAGE)
    public static final class Area {
        private final String name;
        private final String type;

        /** Human-readable area name, e.g. {@code "Theatre of Blood"}. */
        public String getName() {
            return name;
        }

        /**
         * One of {@code BOSSES}, {@code RAIDS}, {@code DUNGEONS}, {@code CITIES},
         * {@code MINIGAMES}, {@code REGIONS}.
         */
        public String getType() {
            return type;
        }

        @Override
        public String toString() {
            return name;
        }
    }

    /** Deserialization shape of the JSON resource. */
    private static final class AreaEntry {
        String name;
        String type;
        int[] regions;
    }

    private static final class AreaFile {
        List<AreaEntry> areas;
    }

    private final Map<Integer, Area> byRegion;

    @Inject
    public RegionNameRegistry(Gson gson) {
        this.byRegion = load(gson);
    }

    private static Map<Integer, Area> load(Gson gson) {
        try (InputStream is = RegionNameRegistry.class.getResourceAsStream(RESOURCE_PATH);
             Reader reader = new BufferedReader(new InputStreamReader(Objects.requireNonNull(is), StandardCharsets.UTF_8))) {
            AreaFile file = gson.fromJson(reader, new TypeToken<AreaFile>() {}.getType());
            Objects.requireNonNull(file);
            Objects.requireNonNull(file.areas);

            Map<Integer, Area> map = new HashMap<>();
            for (AreaEntry entry : file.areas) {
                if (entry == null || entry.name == null || entry.regions == null) {
                    continue;
                }
                Area area = new Area(entry.name, entry.type);
                for (int region : entry.regions) {
                    map.put(region, area);
                }
            }
            return Collections.unmodifiableMap(map);
        } catch (Exception e) {
            // A missing/corrupt resource must not break death tracking — callers
            // degrade to reporting the bare region id.
            log.error("Failed to load region names from {}", RESOURCE_PATH, e);
            return Collections.emptyMap();
        }
    }

    /**
     * @param regionId an instance-corrected map region id
     * @return the area covering that region, or null when unmapped
     */
    @Nullable
    public Area lookup(int regionId) {
        return byRegion.get(regionId);
    }

    /**
     * @param regionId an instance-corrected map region id
     * @return the human-readable area name, or null when unmapped
     */
    @Nullable
    public String nameOf(int regionId) {
        Area area = byRegion.get(regionId);
        return area != null ? area.getName() : null;
    }

    /**
     * @param regionId an instance-corrected map region id
     * @return the coarse area type, or null when unmapped
     */
    @Nullable
    public String typeOf(int regionId) {
        Area area = byRegion.get(regionId);
        return area != null ? area.getType() : null;
    }

    /** Number of distinct region ids the registry can name. */
    public int size() {
        return byRegion.size();
    }
}

package io.droptracker.util;

import io.droptracker.api.DropTrackerUrls;
import lombok.extern.slf4j.Slf4j;
import okhttp3.*;

import javax.annotation.Nullable;
import javax.imageio.ImageIO;
import javax.inject.*;
import java.awt.image.BufferedImage;
import java.util.*;
import java.util.concurrent.*;

/**
 * Tiny async cache for server-hosted icons (team pieces, NPC/skill task icons).
 *
 * <p>Keys are <em>relative paths</em> under {@code /img/}, e.g.
 * {@code "npcdb/2215.png"}, not URLs: the API is not permitted to tell the plugin
 * which host to contact. {@link DropTrackerUrls#image} anchors the path onto a
 * hardcoded base and rejects anything that tries to escape it, redirects are
 * disabled, and bytes go through ImageIO so a non-image body decodes to null and
 * renders nothing.
 */
@Slf4j
@Singleton
public class RemoteImageCache {
    private static final int MAX_ENTRIES = 256;
    private static final int MAX_DIMENSION = 512;

    private final Map<String, BufferedImage> cache =
        // Access-ordered, so an event board bigger than the cache evicts what it
        // is not showing, not the icons the panel is about to ask for again.
        Collections.synchronizedMap(new LinkedHashMap<String, BufferedImage>(64, 0.75f, true) {
            @Override
            protected boolean removeEldestEntry(Map.Entry<String, BufferedImage> eldest) {
                return size() > MAX_ENTRIES;
            }
        });
    private final Map<String, Boolean> inFlight = new ConcurrentHashMap<>();

    private final OkHttpClient httpClient;
    private final ScheduledExecutorService executor;

    @Inject
    public RemoteImageCache(OkHttpClient httpClient, ScheduledExecutorService executor) {
        // Redirects off: the base is hardcoded, and following one would hand the
        // choice of host back to the server.
        this.httpClient = httpClient.newBuilder()
            .followRedirects(false)
            .followSslRedirects(false)
            .build();
        this.executor = executor;
    }

    /**
     * Cached image for the given {@code /img/}-relative path, or null while it
     * loads (or when the path is absent, malformed, or not an image). Kicks off at
     * most one background fetch per path; {@code onLoaded} runs off-EDT after a
     * successful load so callers can repaint.
     */
    @Nullable
    public BufferedImage get(@Nullable String imagePath, @Nullable Runnable onLoaded) {
        HttpUrl url = DropTrackerUrls.image(imagePath);
        if (url == null) {
            return null;
        }
        final String key = imagePath;
        BufferedImage cached = cache.get(key);
        if (cached != null) {
            return cached;
        }
        if (inFlight.putIfAbsent(key, Boolean.TRUE) == null) {
            CompletableFuture.runAsync(() -> {
                try {
                    BufferedImage image = fetch(url);
                    if (image != null
                            && image.getWidth() <= MAX_DIMENSION
                            && image.getHeight() <= MAX_DIMENSION) {
                        cache.put(key, image);
                        if (onLoaded != null) {
                            onLoaded.run();
                        }
                    }
                } catch (Exception e) {
                    log.debug("icon fetch failed for {}: {}", key, e.getMessage());
                } finally {
                    inFlight.remove(key);
                }
            }, executor);
        }
        return null;
    }

    @Nullable
    private BufferedImage fetch(HttpUrl url) throws Exception {
        Request request = new Request.Builder().url(url).build();
        try (Response response = httpClient.newCall(request).execute()) {
            ResponseBody body = response.body();
            if (!response.isSuccessful() || body == null) {
                return null;
            }
            // A non-image body (HTML error page, redirect target) decodes to null and renders nothing.
            return ImageIO.read(body.byteStream());
        }
    }
}

package io.droptracker.util;

import java.text.NumberFormat;
import java.util.Locale;

/**
 * Quantity formatting for event progress values: large targets like
 * 10,000,000 XP must never render as raw digit runs. Panel rows use comma
 * grouping ({@link #commas}); tight spots (HUD progress bar) use GP-style
 * abbreviations ({@link #abbrev}).
 */
public final class ValueFormat {

    private static final NumberFormat COMMAS = NumberFormat.getIntegerInstance(Locale.US);

    private ValueFormat() {
    }

    /** 10000000 → "10,000,000". */
    public static String commas(long value) {
        synchronized (COMMAS) {
            return COMMAS.format(value);
        }
    }

    /** 10000000 → "10M", 1250000 → "1.25M", 813636 → "813.6K", 500 → "500". */
    public static String abbrev(long value) {
        long abs = Math.abs(value);
        if (abs >= 1_000_000_000L) {
            return trim(value / 1_000_000_000.0, 2) + "B";
        }
        if (abs >= 1_000_000L) {
            return trim(value / 1_000_000.0, 2) + "M";
        }
        if (abs >= 10_000L) {
            return trim(value / 1_000.0, 1) + "K";
        }
        return commas(value);
    }

    /**
     * "have / need" for progress displays: abbreviated once values get long
     * enough that comma strings stop fitting, comma-grouped below that.
     */
    public static String progress(long have, long need) {
        if (need >= 100_000L || have >= 100_000L) {
            return abbrev(have) + " / " + abbrev(need);
        }
        return commas(have) + " / " + commas(need);
    }

    private static String trim(double value, int maxDecimals) {
        String out = String.format(Locale.US, "%." + maxDecimals + "f", value);
        while (out.contains(".") && (out.endsWith("0") || out.endsWith("."))) {
            out = out.substring(0, out.length() - 1);
        }
        return out;
    }
}

package io.droptracker.util;

/**
 * Minimal dotted-version comparison for plugin update checks.
 */
public final class VersionUtil {

    private VersionUtil() {
    }

    /**
     * Compares two dotted version strings numerically (e.g. "5.4.0" vs "5.10.2").
     * Missing segments are treated as zero; non-numeric segments compare as zero.
     *
     * @return negative if a &lt; b, 0 if equal, positive if a &gt; b
     */
    public static int compare(String a, String b) {
        String[] as = sanitize(a).split("\\.");
        String[] bs = sanitize(b).split("\\.");
        int length = Math.max(as.length, bs.length);
        for (int i = 0; i < length; i++) {
            int ai = segment(as, i);
            int bi = segment(bs, i);
            if (ai != bi) {
                return Integer.compare(ai, bi);
            }
        }
        return 0;
    }

    public static boolean isOlderThan(String current, String other) {
        return compare(current, other) < 0;
    }

    private static String sanitize(String version) {
        if (version == null) {
            return "0";
        }
        String trimmed = version.trim();
        if (trimmed.startsWith("v") || trimmed.startsWith("V")) {
            trimmed = trimmed.substring(1);
        }
        return trimmed.isEmpty() ? "0" : trimmed;
    }

    private static int segment(String[] parts, int index) {
        if (index >= parts.length) {
            return 0;
        }
        try {
            return Integer.parseInt(parts[index].trim());
        } catch (NumberFormatException e) {
            return 0;
        }
    }
}

package io.droptracker.util;

import java.util.Set;
import net.runelite.api.WorldType;

/**
 * Which "world" a piece of data belongs to, as the server files it.
 *
 * <p>Main-game data and data from worlds with their own characters (Leagues,
 * Deadman, Hardcore Worlds, ...) must never be mixed: a fresh character's
 * drops, XP or collection log would otherwise land on the main-game account.
 */
public final class WorldTypes {

    public static final String MAIN = "MAIN";

    private WorldTypes() {
    }

    /**
     * "MAIN" for regular game worlds, or the specific WorldType name for
     * temporary/special worlds (e.g. "BETA_WORLD", "DEADMAN", "SEASONAL").
     * LAST_MAN_STANDING worlds are intentionally treated as MAIN because LMS is
     * played on rotating main-game worlds; PVP worlds are MAIN because they
     * play the main-game character.
     */
    public static String submissionName(Set<WorldType> worldType) {
        if (worldType.contains(WorldType.BETA_WORLD))         return "BETA_WORLD";
        // Hardcore Worlds (Nov 2026): fresh one-life characters with their own
        // economy, kept apart from main-game data like seasonal.
        if (worldType.contains(WorldType.HARDCORE_MAIN))      return "HARDCORE_MAIN";
        if (worldType.contains(WorldType.DEADMAN))            return "DEADMAN";
        if (worldType.contains(WorldType.FRESH_START_WORLD))  return "FRESH_START_WORLD";
        if (worldType.contains(WorldType.NOSAVE_MODE))        return "NOSAVE_MODE";
        if (worldType.contains(WorldType.PVP_ARENA))          return "PVP_ARENA";
        if (worldType.contains(WorldType.QUEST_SPEEDRUNNING)) return "QUEST_SPEEDRUNNING";
        if (worldType.contains(WorldType.SEASONAL))           return "SEASONAL";
        if (worldType.contains(WorldType.TOURNAMENT_WORLD))   return "TOURNAMENT_WORLD";
        return MAIN;
    }

    /** Whether data from this world belongs to the main-game character. */
    public static boolean isMainWorld(Set<WorldType> worldType) {
        return MAIN.equals(submissionName(worldType));
    }
}

package io.droptracker;

import java.lang.reflect.Method;
import java.util.Set;
import java.util.TreeSet;

import net.runelite.client.config.ConfigItem;

import org.junit.Test;

import static org.junit.Assert.assertEquals;

/**
 * Pins every config keyName.
 * <p>
 * A player's saved setting is looked up by keyName, so renaming one silently
 * resets that option for everyone who had configured it — there is no
 * migration and no warning, the old value simply stops being found. Section,
 * position, display name and description are all safe to change and are
 * deliberately not asserted here.
 * <p>
 * If this fails you either renamed a key (don't — keep the old keyName and
 * change the display name instead) or added/removed one, in which case update
 * the list below and make sure it's a deliberate choice.
 */
public class DropTrackerConfigKeyNamesTest {

    /** Every keyName the plugin is allowed to read or write. */
    private static final Set<String> EXPECTED = new TreeSet<>(Set.of(
        // Tracking
        "lootEmbeds", "pbEmbeds", "clogEmbeds", "caEmbeds", "petEmbeds",
        "levelEmbed", "xpMilestoneEmbeds", "questsEmbed", "deathEmbeds",
        "diaryEmbeds", "slayerEmbeds", "trackActivities",
        // Screenshots
        "screenshots", "screenshotValue", "screenshotUntradeables",
        "minLevelToScreenshot", "privacyMode", "compressImages",
        "screenshotCompressionKb",
        // Events
        "eventNotifications", "eventDisplayMode", "eventTaskProgressNotifications",
        "eventHudDetail", "eventTeamIndicators", "eventTeamIndicatorColorNames",
        "eventTeamIndicatorsPublicChat",
        // Clan Chat
        "clanChatSync", "receiveDiscordChat",
        // Advanced
        "useApi", "inGameMessages", "dropConfirmations", "syncAccountState",
        "uploadCharacterModel", "showSidePanel", "debugLogging",
        // Retired from the UI, kept so existing values still apply
        "trackExperience", "trackTrawling", "hideWhispers",
        "sendLoadoutWithPbs", "eventImportantPopupsOnly", "pollUpdates",
        // Internal state
        "pinnedEventId", "lastVersionNotified", "lastAccountName",
        "customApiEndpoint", "lastAccountHash"
    ));

    @Test
    public void configKeyNamesAreUnchanged() {
        Set<String> actual = new TreeSet<>();
        for (Method m : DropTrackerConfig.class.getMethods()) {
            ConfigItem item = m.getAnnotation(ConfigItem.class);
            if (item != null) {
                actual.add(item.keyName());
            }
        }
        assertEquals("config keyNames changed — a rename resets that setting for "
            + "every player who had configured it", EXPECTED, actual);
    }

    @Test
    public void everySettingHasAHomeOrIsDeliberatelyHidden() {
        // A visible item with no section renders loose at the top of the panel,
        // which is how options quietly escape the four-section layout.
        for (Method m : DropTrackerConfig.class.getMethods()) {
            ConfigItem item = m.getAnnotation(ConfigItem.class);
            if (item == null || item.hidden()) {
                continue;
            }
            assertEquals(item.keyName() + " is visible but has no section",
                false, item.section().isEmpty());
        }
    }
}

