package io.droptracker.events;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import io.droptracker.DropTrackerConfig;
import org.junit.Test;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.HashSet;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import java.util.stream.Collectors;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class ConfigSnapshotHandlerTest {
    private static DropTrackerConfig defaults() {
        return new DropTrackerConfig() {
            @Override
            public void setPinnedEventId(int eventId) {
            }

            @Override
            public void setLastVersionNotified(String versionNotified) {
            }

            @Override
            public void setLastAccountName(String accountName) {
            }

            @Override
            public void setCustomApiEndpoint(String customApiEndpoint) {
            }

            @Override
            public void setLastAccountHash(String accountHash) {
            }

            @Override
            public String customApiEndpoint() {
                return "https://private.example/api";
            }
        };
    }

    private static JsonObject env() {
        JsonObject env = new JsonObject();
        env.addProperty("runelite_version", "1.13.1");
        env.addProperty("resizable", true);
        env.addProperty("chatbox_transparent", false);
        env.addProperty("loot_tracker_enabled", true);
        env.addProperty("custom_api_endpoint", true);
        return env;
    }

    @Test
    public void settingsAreGroupedBySectionWithTheirValues() {
        JsonObject snapshot = ConfigSnapshotHandler.build(defaults(), "petEmbeds"::equals, env());
        JsonObject settings = snapshot.getAsJsonObject("settings");
        assertEquals(ConfigSnapshotHandler.FORMAT_VERSION, snapshot.get("v").getAsInt());
        assertTrue(settings.getAsJsonObject("Tracking").get("lootEmbeds").getAsBoolean());
        assertEquals("POPUP", settings.getAsJsonObject("Events").get("eventDisplayMode").getAsString());
        assertTrue(settings.getAsJsonObject("Hidden").has("trackExperience"));
        assertEquals(1, snapshot.getAsJsonArray("customized").size());
        assertEquals("petEmbeds", snapshot.getAsJsonArray("customized").get(0).getAsString());
    }

    @Test
    public void internalAndTextSettingsNeverLeave() {
        String json = new Gson().toJson(ConfigSnapshotHandler.build(defaults(), key -> true, env()));
        for (String key : ConfigSnapshotHandler.EXCLUDED) {
            assertFalse(key + " was sent", json.contains("\"" + key + "\""));
        }
        assertFalse(json.contains("private.example"));
        assertFalse(json.contains("customized\":[\"customApiEndpoint"));
    }

    @Test
    public void worstCaseFitsAnEmbedDescription() {
        // Every setting customized, plus the hash the sender appends.
        JsonObject snapshot = ConfigSnapshotHandler.build(defaults(), key -> true, env());
        snapshot.addProperty("hash", "0123456789abcdef");
        String json = new Gson().toJson(snapshot);
        assertTrue("snapshot is " + json.length() + " chars",
            json.length() < ConfigSnapshotHandler.MAX_DESCRIPTION - 1000);
    }

    /**
     * Every boolean, number and enum setting in DropTrackerConfig is either in
     * SETTINGS or deliberately EXCLUDED, and SETTINGS names no key that does
     * not exist. Reads the config interface as source text: the snapshot list
     * is explicit because the Plugin Hub does not allow reflection.
     */
    @Test
    public void settingsListMatchesTheConfigInterface() throws IOException {
        String source = new String(Files.readAllBytes(
            Paths.get("src/main/java/io/droptracker/DropTrackerConfig.java")), StandardCharsets.UTF_8);
        Pattern item = Pattern.compile(
            "@ConfigItem\\((.*?)\\)\\s*(?:@\\w+(?:\\([^)]*\\))?\\s*)*default\\s+([\\w.<>]+)\\s+\\w+\\(\\)",
            Pattern.DOTALL);
        Pattern keyName = Pattern.compile("keyName\\s*=\\s*\"([^\"]+)\"");
        Set<String> expected = new HashSet<>();
        Matcher m = item.matcher(source);
        while (m.find()) {
            Matcher key = keyName.matcher(m.group(1));
            if (!key.find()) {
                continue;
            }
            if (!"String".equals(m.group(2)) && !ConfigSnapshotHandler.EXCLUDED.contains(key.group(1))) {
                expected.add(key.group(1));
            }
        }
        Set<String> listed = ConfigSnapshotHandler.SETTINGS.stream()
            .map(s -> s.key).collect(Collectors.toSet());
        assertTrue("found only " + expected.size() + " settings in the source", expected.size() > 30);
        assertEquals(expected, listed);
        assertEquals("duplicate keys in SETTINGS", listed.size(), ConfigSnapshotHandler.SETTINGS.size());
    }
}

package io.droptracker.events;

import java.util.Collections;
import java.util.EnumSet;

import io.droptracker.DropTrackerConfig;
import io.droptracker.testing.RuneLiteStubs;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.WorldType;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.events.ActorDeath;
import net.runelite.api.events.InteractingChanged;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * Tests {@link DeathHandler#identifyKiller}, which decides what a death
 * submission reports as its source.
 *
 * <p>Attribution has two layers: a live scan for whoever is still targeting the
 * local player, and — when that finds nobody, which in production is most of the
 * time — the engagement history built from {@code InteractingChanged}. Without
 * the second layer the submission goes out with no source and a killer type of
 * "unknown".
 */
public class DeathHandlerKillerAttributionTest {

    private DeathHandler handler;
    private Player localPlayer;
    private Client client;

    @Before
    public void setUp() {
        handler = new DeathHandler();
        localPlayer = RuneLiteStubs.player("Local", 126);
        client = RuneLiteStubs.client(localPlayer);
        handler.client = client;
        handler.config = RuneLiteStubs.stub(DropTrackerConfig.class, "config");
    }

    private void tick(int tick) {
        RuneLiteStubs.state(client).put("getTickCount", tick);
    }

    private void targets(NPC npc, Object target) {
        RuneLiteStubs.state(npc).put("getInteracting", target);
    }

    // --- live scan ------------------------------------------------------

    @Test
    public void npcStillAttackingUsIsAttributed() {
        NPC vorkath = RuneLiteStubs.npc(1, 8061, "Vorkath", 732);
        targets(vorkath, localPlayer);
        RuneLiteStubs.setScene(client, localPlayer, Collections.emptyList(), Collections.singletonList(vorkath));

        DeathHandler.Killer killer = handler.identifyKiller(localPlayer, null);
        assertNotNull(killer);
        assertEquals("Vorkath", killer.getName());
        assertEquals(Integer.valueOf(8061), killer.getNpcId());
        assertTrue(killer.isNpc());
        assertFalse(killer.isPlayer());
    }

    /**
     * Instanced NPCs sometimes report no name of their own; the composition still
     * has one, and an embed with an NPC id but no source is what a blank killer
     * looks like on the site.
     */
    @Test
    public void npcWithNoNameOfItsOwnFallsBackToItsComposition() {
        NPC boss = RuneLiteStubs.npc(1, 11751, "The Whisperer", 480);
        RuneLiteStubs.state(boss).put("getName", null);
        targets(boss, localPlayer);
        RuneLiteStubs.setScene(client, localPlayer, Collections.emptyList(), Collections.singletonList(boss));

        assertEquals("The Whisperer", handler.identifyKiller(localPlayer, null).getName());
    }

    // --- the fallback ---------------------------------------------------

    /**
     * The production failure. The boss dropped its target when we died and the
     * instance took it out of the scene, so nothing is left to scan — but the
     * interaction history still knows who we were fighting two ticks ago.
     */
    @Test
    public void deathWithNothingLeftToScanIsAttributedFromRecentCombat() {
        NPC vorkath = RuneLiteStubs.npc(1, 8061, "Vorkath", 732);

        tick(100);
        handler.onInteractingChanged(new InteractingChanged(localPlayer, vorkath));
        handler.onInteractingChanged(new InteractingChanged(vorkath, localPlayer));

        // Death tick: it lets go of us and leaves the scene entirely.
        tick(118);
        handler.onInteractingChanged(new InteractingChanged(vorkath, null));
        RuneLiteStubs.setScene(client, localPlayer, Collections.emptyList(), Collections.emptyList());

        DeathHandler.Killer killer = handler.identifyKiller(localPlayer, null);
        assertNotNull("a death with no live attacker must still name a killer", killer);
        assertEquals("Vorkath", killer.getName());
        assertEquals(Integer.valueOf(8061), killer.getNpcId());
        assertEquals(732, killer.getCombatLevel());
    }

    /**
     * Regression: only the local player's outbound target used to be recorded,
     * so anything that attacked us without us ever clicking it — the common way
     * to die — left no trace at all.
     */
    @Test
    public void anNpcAttackingUsIsRememberedEvenIfWeNeverAttackedIt() {
        NPC dagannoth = RuneLiteStubs.npc(1, 100, "Dagannoth", 90);

        tick(50);
        handler.onInteractingChanged(new InteractingChanged(dagannoth, localPlayer));
        assertEquals(1, handler.recentCombat.size());

        tick(52);
        assertEquals("Dagannoth", handler.identifyKiller(localPlayer, null).getName());
    }

    @Test
    public void aDeathNothingExplainsIsStillReportedAsUnattributed() {
        // Poison, falling damage, a wilderness dragonfire wall: nothing ever
        // engaged us, so there is nobody to blame and we say so.
        assertNull(handler.identifyKiller(localPlayer, null));
    }

    // --- players --------------------------------------------------------

    @Test
    public void aPlayerIsNotBlamedOutsidePvp() {
        Player bystander = RuneLiteStubs.player("Zezima", 126);
        RuneLiteStubs.state(bystander).put("getInteracting", localPlayer);
        RuneLiteStubs.setScene(client, localPlayer, Collections.singletonList(bystander), Collections.emptyList());

        tick(10);
        handler.onInteractingChanged(new InteractingChanged(bystander, localPlayer));

        assertNull(handler.identifyKiller(localPlayer, null));
    }

    @Test
    public void aPkerInTheWildernessIsAttributed() {
        insideWilderness();
        Player pker = RuneLiteStubs.player("Zezima", 126);
        RuneLiteStubs.state(pker).put("getInteracting", localPlayer);
        RuneLiteStubs.setScene(client, localPlayer, Collections.singletonList(pker), Collections.emptyList());

        DeathHandler.Killer killer = handler.identifyKiller(localPlayer, null);
        assertNotNull(killer);
        assertEquals("Zezima", killer.getName());
        assertTrue(killer.isPlayer());
        assertNull(killer.getNpcId());
    }

    /**
     * A PvP world's bank is a safe zone: nobody standing there can have killed
     * us, so no bystander should be named.
     */
    @Test
    public void nobodyIsBlamedInsideAPvpSafeZone() {
        RuneLiteStubs.state(client).put("getWorldType", EnumSet.of(WorldType.PVP));
        showOnly(InterfaceID.PvpIcons.PVPW_SAFE);

        Player bystander = RuneLiteStubs.player("Zezima", 126);
        RuneLiteStubs.state(bystander).put("getInteracting", localPlayer);
        RuneLiteStubs.setScene(client, localPlayer, Collections.singletonList(bystander), Collections.emptyList());

        assertNull(handler.identifyKiller(localPlayer, null));
    }

    /** A dead attacker is a corpse we outlived, not our killer. */
    @Test
    public void anNpcThatDiedFirstIsNotBlamed() {
        NPC dying = RuneLiteStubs.npc(1, 100, "Dagannoth", 90);
        targets(dying, localPlayer);

        tick(20);
        handler.onInteractingChanged(new InteractingChanged(dying, localPlayer));
        RuneLiteStubs.state(dying).put("isDead", true);
        RuneLiteStubs.setScene(client, localPlayer, Collections.emptyList(), Collections.singletonList(dying));

        assertNull(handler.identifyKiller(localPlayer, null));
    }

    // --- history lifecycle ----------------------------------------------

    @Test
    public void ourOwnDeathWipesTheHistory() {
        NPC vorkath = RuneLiteStubs.npc(1, 8061, "Vorkath", 732);
        tick(100);
        handler.onInteractingChanged(new InteractingChanged(vorkath, localPlayer));
        assertEquals(1, handler.recentCombat.size());

        // deathEmbeds() is false on the stub, so the handler skips the
        // submission — the history must still be reset for the next life.
        handler.onActorDeath(new ActorDeath(localPlayer));
        assertEquals(0, handler.recentCombat.size());
    }

    @Test
    public void killingSomethingRemovesItFromTheHistory() {
        NPC vorkath = RuneLiteStubs.npc(1, 8061, "Vorkath", 732);
        tick(100);
        handler.onInteractingChanged(new InteractingChanged(localPlayer, vorkath));
        assertEquals(1, handler.recentCombat.size());

        handler.onActorDeath(new ActorDeath(vorkath));
        assertEquals(0, handler.recentCombat.size());
    }

    @Test
    public void interactingWithAHarmlessNpcLeavesNoCandidate() {
        NPC banker = RuneLiteStubs.npc(1, 1613, "Banker", 0, false, false);
        tick(100);
        handler.onInteractingChanged(new InteractingChanged(localPlayer, banker));

        assertEquals(0, handler.recentCombat.size());
        assertNull(handler.identifyKiller(localPlayer, null));
    }

    /**
     * The regression behind 6.1.6: the PvP icons layer (SAFEZONE) is shown all
     * over the Wilderness, and treating it as the safe-zone marker stopped
     * every player kill from being attributed.
     */
    @Test
    public void thePvpIconsLayerIsNotASafeZone() {
        insideWilderness();
        showOnly(InterfaceID.PvpIcons.SAFEZONE);
        Player pker = RuneLiteStubs.player("Zezima", 126);
        RuneLiteStubs.state(pker).put("getInteracting", localPlayer);
        RuneLiteStubs.setScene(client, localPlayer, Collections.singletonList(pker), Collections.emptyList());

        DeathHandler.Killer killer = handler.identifyKiller(localPlayer, null);
        assertNotNull(killer);
        assertTrue(killer.isPlayer());
    }

    /** LMS is outside the Wilderness, but the other players are the opponents. */
    @Test
    public void anOpponentInLastManStandingIsAttributed() {
        Player opponent = RuneLiteStubs.player("Zezima", 126);
        RuneLiteStubs.state(opponent).put("getInteracting", localPlayer);
        RuneLiteStubs.setScene(client, localPlayer, Collections.singletonList(opponent), Collections.emptyList());

        DeathHandler.Killer killer = handler.identifyKiller(localPlayer, new WorldPoint(3456, 5824, 0));
        assertNotNull(killer);
        assertEquals("Zezima", killer.getName());
        assertTrue(killer.isPlayer());
    }

    /** Only the widget with this component id is visible; every other lookup finds nothing. */
    private void showOnly(int componentId) {
        Widget visible = RuneLiteStubs.visibleWidget();
        RuneLiteStubs.state(client).put("getWidget",
                (RuneLiteStubs.Answer) args -> args.length == 1 && Integer.valueOf(componentId).equals(args[0])
                        ? visible : null);
    }

    private void insideWilderness() {
        RuneLiteStubs.state(client).put("getVarbitValue", 1);
    }

    /**
     * Guards the stub itself: if the scene helper handed back an empty set the
     * live-scan tests above would pass for the wrong reason.
     */
    @Test
    public void sceneStubExposesItsNpcsToTheScan() {
        NPC npc = RuneLiteStubs.npc(1, 100, "Goblin", 2);
        RuneLiteStubs.setScene(client, localPlayer, Collections.emptyList(), Collections.singletonList(npc));
        assertEquals(1L, localPlayer.getWorldView().npcs().stream().count());
    }
}

package io.droptracker.events;

import java.lang.reflect.Proxy;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.client.game.ItemStack;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * Opened PvP loot keys, read straight off the Wilderness loot chest (6.1.16).
 * The chest holds one item container per key, 558-562. Each key is sent once,
 * however often the chest is reopened before the loot is taken.
 */
public class DropHandlerLootChestTest {

    private final Map<Integer, Item[]> containers = new HashMap<>();
    private DropHandler handler;

    @Before
    public void setUp() {
        handler = new DropHandler();
        handler.client = (Client) Proxy.newProxyInstance(Client.class.getClassLoader(),
            new Class<?>[]{Client.class}, (p, m, a) -> {
                if (m.getName().equals("getItemContainer")) {
                    Item[] items = containers.get((Integer) a[0]);
                    return items == null ? null : container(items);
                }
                Class<?> r = m.getReturnType();
                return r == boolean.class ? false : r == int.class ? 0 : r == long.class ? 0L : null;
            });
    }

    private static ItemContainer container(Item[] items) {
        return (ItemContainer) Proxy.newProxyInstance(ItemContainer.class.getClassLoader(),
            new Class<?>[]{ItemContainer.class},
            (p, m, a) -> m.getName().equals("getItems") ? items : null);
    }

    @Test
    public void eachHeldKeyIsOneSubmission() {
        containers.put(558, new Item[]{new Item(4151, 1), new Item(385, 10)});
        containers.put(560, new Item[]{new Item(995, 250_000)});
        List<List<ItemStack>> keys = handler.unsentLootKeys();
        assertEquals(2, keys.size());
        assertEquals(2, keys.get(0).size());
        assertEquals(995, keys.get(1).get(0).getId());
    }

    @Test
    public void reopeningTheChestSendsNothingTwice() {
        containers.put(558, new Item[]{new Item(4151, 1)});
        assertEquals(1, handler.unsentLootKeys().size());
        assertTrue(handler.unsentLootKeys().isEmpty());
        // A key won later shows up beside the unclaimed one.
        containers.put(559, new Item[]{new Item(11802, 1)});
        assertEquals(1, handler.unsentLootKeys().size());
    }

    @Test
    public void emptySlotsAndPlaceholdersAreSkipped() {
        containers.put(558, new Item[]{new Item(-1, 0), new Item(0, 0)});
        assertTrue(handler.unsentLootKeys().isEmpty());
    }

    @Test
    public void theChestIsNotAnNpcLootSource() {
        assertEquals("Loot Chest", DropHandler.LOOT_CHEST);
    }
}

package io.droptracker.events;

import org.junit.Test;

import static org.junit.Assert.assertEquals;

/**
 * The Wilderness level sent with a PvP kill (6.1.9). The game draws a level
 * line every eight tiles north of the ditch, and again in the dungeons under
 * the Wilderness, which sit 6400 tiles further north on the map.
 */
public class DropHandlerPvpTest {

    @Test
    public void theDitchIsLevelOne() {
        assertEquals(1, DropHandler.wildernessLevel(3520));
        assertEquals(1, DropHandler.wildernessLevel(3527));
        assertEquals(2, DropHandler.wildernessLevel(3528));
    }

    @Test
    public void theNorthernEdgeIsLevelFiftySix() {
        assertEquals(56, DropHandler.wildernessLevel(3967));
    }

    @Test
    public void dungeonsUseTheirOwnBaseline() {
        assertEquals(1, DropHandler.wildernessLevel(9920));
        assertEquals(28, DropHandler.wildernessLevel(10140));
    }

    @Test
    public void neverReportsBelowOne() {
        // Just south of the ditch while the varbit still reads "inside".
        assertEquals(1, DropHandler.wildernessLevel(3515));
    }
}

package io.droptracker.events;

import com.google.gson.Gson;
import io.droptracker.DropTrackerConfig;
import io.droptracker.models.CustomWebhookBody;
import io.droptracker.models.submissions.SubmissionType;
import net.runelite.api.Client;
import net.runelite.api.Player;
import org.junit.Before;
import org.junit.Test;

import java.lang.reflect.Proxy;
import java.util.*;

import static org.junit.Assert.*;

/**
 * Which chat lines PbHandler forwards, and when. The server parses them
 * (data/submissions/pb_lines.py, whose tests hold the parsing cases); this
 * side only has to send a kill's lines together, on the tick they complete it.
 */
public class PbHandlerBatchTest {

    private final List<Map<String, String>> sent = new ArrayList<>();
    private int tick = 100;
    private PbHandler handler;

    @Before
    public void setUp() {
        Client client = (Client) Proxy.newProxyInstance(Client.class.getClassLoader(), new Class<?>[]{Client.class},
            (p, m, a) -> {
                switch (m.getName()) {
                    case "getTickCount": return tick;
                    case "getPlayers": return Collections.nCopies(2, (Player) null);
                    case "getVarbitValue": return 0;
                }
                Class<?> r = m.getReturnType();
                return r == boolean.class ? false : r == int.class ? 0 : r == long.class ? 0L : null;
            });
        DropTrackerConfig config = (DropTrackerConfig) Proxy.newProxyInstance(DropTrackerConfig.class.getClassLoader(),
            new Class<?>[]{DropTrackerConfig.class}, (p, m, a) -> m.getReturnType() == boolean.class ? Boolean.TRUE
                : m.getReturnType() == String.class ? "" : m.getReturnType() == int.class ? 0 : null);
        handler = new PbHandler() {
            @Override
            protected String getPlayerName() {
                return "P";
            }

            @Override
            protected void sendData(CustomWebhookBody webhook, SubmissionType type) {
                Map<String, String> fields = new LinkedHashMap<>();
                for (CustomWebhookBody.Field f : webhook.getEmbeds().get(0).getFields()) {
                    fields.put(f.getName(), f.getValue());
                }
                sent.add(fields);
            }
        };
        handler.client = client;
        handler.config = config;
        handler.gson = new Gson();
    }

    private void at(int tick, String... messages) {
        this.tick = tick;
        for (String message : messages) {
            handler.onGameMessage(message);
        }
        handler.onTick();
    }

    @Test
    public void aCountAndATimeAreSentTogetherOnTheTickTheyComplete() {
        at(100, "Fight duration: 1:23.40 (new personal best)");
        assertTrue(sent.isEmpty());
        at(101, "Your Vorkath kill count is: 12.");
        assertEquals(1, sent.size());
        Map<String, String> kill = sent.get(0);
        assertEquals("npc_kill", kill.get("type"));
        assertEquals("true", kill.get("is_pb"));
        assertEquals("Your Vorkath kill count is: 12.", kill.get("source"));
        assertTrue(kill.get("chat_line_1"), kill.get("chat_line_1").contains("\"t\":100"));
        assertTrue(kill.get("chat_line_2"), kill.get("chat_line_2").contains("\"p\":[0,0,0,2]"));
        assertNull(kill.get("chat_line_3"));
        at(102);
        assertEquals("the batch is cleared once sent", 1, sent.size());
    }

    @Test
    public void wallClockTotalsAndIgnoredLinesDoNotCompleteAKill() {
        at(100, "Theatre of Blood total completion time: 24:40.20. Personal best: 20:45.00",
            "Your completed Theatre of Blood count is: 5.", "Preparation time: 1:00");
        assertTrue(sent.isEmpty());
        at(101, "Theatre of Blood completion time: 17:00.20 (new personal best)");
        assertEquals(1, sent.size());
        assertNotNull(sent.get(0).get("chat_line_3"));
        assertFalse("the preparation line is never forwarded", sent.get(0).toString().contains("Preparation"));
    }

    @Test
    public void aRoomPersonalBestOnATotalLineIsNotAPb() {
        at(100, "Tombs of Amascut total completion time: 0:01 (new personal best)",
            "Tombs of Amascut challenge completion time: 8:31. Personal best: 8:00",
            "Your completed Tombs of Amascut count is: 3.");
        assertEquals("false", sent.get(0).get("is_pb"));
    }

    @Test
    public void aTimedDelveLevelIsAKillOnItsOwn() {
        at(100, "Delve level: 8+ (9)");
        assertTrue("the level-start announcement has no time", sent.isEmpty());
        at(101, "Delve level: 8+ (9) duration: 1:27 (new personal best)");
        assertEquals(1, sent.size());
    }

    @Test
    public void unrelatedMessagesAreNotForwarded() {
        at(100, "You have a funny feeling...", "Your heriblore level is now 78.");
        at(101, "Your Vorkath kill count is: 12.", "Fight duration: 1:00.");
        assertEquals(1, sent.size());
        assertNull(sent.get(0).get("chat_line_3"));
    }
}

package io.droptracker.events;

import org.junit.Test;

import java.util.regex.Matcher;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Tests the pet chat-message patterns exposed via {@code @VisibleForTesting}.
 * PET_REGEX gates local pet detection; CLAN_REGEX pulls the pet name and
 * milestone out of the clan broadcast.
 */
public class PetHandlerParseTest {

    @Test
    public void petRegexMatchesFunnyFeelingVariants() {
        assertTrue(PetHandler.PET_REGEX.matcher("You have a funny feeling like you're being followed.").matches());
        assertTrue(PetHandler.PET_REGEX.matcher("You have a funny feeling like you would have been followed...").matches());
        assertTrue(PetHandler.PET_REGEX.matcher("You feel something weird sneaking into your backpack.").matches());
    }

    @Test
    public void petRegexRejectsUnrelatedMessages() {
        assertFalse(PetHandler.PET_REGEX.matcher("You have completed a Treasure Trail.").matches());
        assertFalse(PetHandler.PET_REGEX.matcher("You feel a funny sensation.").matches());
    }

    @Test
    public void clanRegexExtractsUserPetAndMilestoneForFollow() {
        Matcher m = PetHandler.CLAN_REGEX.matcher(
                "Koeppy has a funny feeling like he would have been followed: Herbi at 500 kills.");
        assertTrue(m.find());
        assertEquals("Koeppy", m.group("user"));
        assertEquals("Herbi", m.group("pet"));
        assertEquals("500 kills.", m.group("milestone"));
    }

    @Test
    public void clanRegexExtractsBackpackVariant() {
        Matcher m = PetHandler.CLAN_REGEX.matcher(
                "Big Man feels something weird sneaking into his backpack: Baby mole at 200 kills.");
        assertTrue(m.find());
        assertEquals("Big Man", m.group("user"));
        assertEquals("Baby mole", m.group("pet"));
        assertEquals("200 kills.", m.group("milestone"));
    }

    // Pet names come from the server's manifest ("pets": name -> kill-count boss).
    // Skilling pets have no boss and must still be recognised; chat spells
    // names in whatever case the game uses.
    @Test
    public void petKeyFindsManifestPetsIgnoringCase() {
        java.util.Map<String, String> pets = new java.util.HashMap<>();
        pets.put("Baby mole", "Giant Mole");
        pets.put("Heron", null);
        pets.put("Lil' zik", "Theatre of Blood");
        assertEquals("Baby mole", PetHandler.petKey(pets, "baby Mole"));
        assertEquals("Heron", PetHandler.petKey(pets, "Heron"));
        assertEquals("Lil' zik", PetHandler.petKey(pets, "Lil' Zik"));
        assertEquals(null, PetHandler.petKey(pets, "Dragon warhammer"));
        assertEquals(null, PetHandler.petKey(java.util.Collections.emptyMap(), "Baby mole"));
    }
}

package io.droptracker.events;

import org.junit.Test;

import static org.junit.Assert.assertFalse;
