        chat("You have completed your task! You killed 20 Moon Moths. You gained 900 xp.",
            "You've completed 7 tasks and received 12 points, giving you a total of 90; return to a Slayer master.");
        killsLeft(0);
        nextTick();

        SlayerHandler.Completion done = onlySubmission();
        assertEquals("Moon Moths", done.getTaskName());
        assertEquals(250, done.getTaskId());
    }

    /** "Turael skipping": reported with its master; the server decides it doesn't count. */
    @Test
    public void aTuraelTaskEarnsNothingAndSaysWhoGaveIt() {
        varbits.put(VarbitID.SLAYER_POINTS, 420);
        assign(TURAEL, BIRDS, 20);
        chat("You have completed your task! You killed 20 Birds. You gained 1,200 xp.",
            "You've completed 3 tasks.You'll be eligible to earn reward points if you complete tasks from a more advanced Slayer Master.");
        killsLeft(0);
        nextTick();

        SlayerHandler.Completion done = onlySubmission();
        assertEquals(TURAEL, done.getMasterId());
        assertEquals("Birds", done.getTaskName());
        assertEquals(Integer.valueOf(3), done.getStreak());
        assertEquals(Integer.valueOf(0), done.getPointsAwarded());
        assertEquals("the total is not in the line, so it comes from the varbit",
            Integer.valueOf(420), done.getPointsTotal());
    }

    @Test
    public void withoutTheStreakLineTheCompletionWaitsATickThenReadsTheVars() {
        varbits.put(VarbitID.SLAYER_WILDERNESS_TASKS_COMPLETED, 12);
        varbits.put(VarbitID.SLAYER_TASKS_COMPLETED, 999);
        varbits.put(VarbitID.SLAYER_POINTS, 1500);
        assign(KRYSTILIA, DUST_DEVILS, 100);
        chat("You have completed your task! You killed 100 Dust Devils. You gained 9,000 xp.");
        killsLeft(0);
        endFrame();
        // A tick event carrying the line's own tick count: the streak line
        // could still be on its way.
        handler.onTick();
        assertTrue(submitted.isEmpty());

        nextTick();

        SlayerHandler.Completion done = onlySubmission();
        assertEquals("Krystilia's streak is her own", Integer.valueOf(12), done.getStreak());
        assertNull(done.getPointsAwarded());
        assertEquals(Integer.valueOf(1500), done.getPointsTotal());
        assertEquals("You have completed your task! You killed 100 Dust Devils. You gained 9,000 xp.",
            done.getCompletionMessage());
    }

    @Test
    public void aKonarTaskCarriesItsArea() {
        varp(VarPlayerID.SLAYER_AREA, 3);
        assign(KONAR, HYDRAS, 120);
        chat("You have completed your task! You killed 120 Hydras. You gained 43,000 xp.",
            "You've completed 50 tasks and received 25 points, giving you a total of 800; return to a Slayer master.");
        killsLeft(0);
        nextTick();

        SlayerHandler.Completion done = onlySubmission();
        assertEquals(3, done.getAreaId());
        assertEquals(KONAR, done.getMasterId());
    }

    @Test
    public void aQuantityModifierMovesTheStartingAmount() {
        varbits.put(VarbitID.SLAYER_MODIFIER_ID, 2);
        varbits.put(VarbitID.SLAYER_MODIFIER_VALUE, 20);
        varbits.put(VarbitID.SLAYER_MODIFIER_NEGATIVE, 1);
        assign(DURADEL, CAVE_KRAKEN, 150);
        chat("You have completed your task! You killed 130 Cave Kraken. You gained 54,000 xp.", POINTS_LINE);
        killsLeft(0);
        nextTick();

        SlayerHandler.Completion done = onlySubmission();
        assertEquals(130, done.getAmountInitial());
        assertEquals(130, done.getAmountKilled());
    }

    /**
     * If the game clears the other task vars in the same batch as the count,
     * reading between updates would report a task with no master and no name.
     * The task is read once the batch is in, so the count drop still finds it.
     */
    @Test
    public void varsClearedAlongsideTheCountDoNotRewriteTheTask() {
        assign(DURADEL, CAVE_KRAKEN, 150);
        chat(KRAKEN_LINE, POINTS_LINE);
        varbit(VarbitID.SLAYER_MASTER, 0);
        varp(VarPlayerID.SLAYER_TARGET, 0);
        killsLeft(0);
        nextTick();

        SlayerHandler.Completion done = onlySubmission();
        assertEquals("Cave Kraken", done.getTaskName());
        assertEquals(CAVE_KRAKEN, done.getTaskId());
        assertEquals(DURADEL, done.getMasterId());
    }

    /** A new task replaces the old one wholesale, master included. */
    @Test
    public void theNextTaskIsReportedWithItsOwnMaster() {
        assign(DURADEL, CAVE_KRAKEN, 150);
        chat(KRAKEN_LINE, POINTS_LINE);
        killsLeft(0);
        nextTick();
        submitted.clear();

        assign(NIEVE, DUST_DEVILS, 100);
        chat("You have completed your task! You killed 100 Dust Devils. You gained 9,000 xp.",
            "You've completed 1,001 tasks and received 12 points, giving you a total of 2,596; return to a Slayer master.");
        killsLeft(0);
        nextTick();

        SlayerHandler.Completion done = onlySubmission();
        assertEquals("Dust Devils", done.getTaskName());
        assertEquals(NIEVE, done.getMasterId());
        assertEquals(100, done.getAmountInitial());
        assertEquals(Integer.valueOf(1001), done.getStreak());
    }

    // --- fields ---------------------------------------------------------

    @Test
    public void fieldsCarryWhatTheServerReads() {
        SlayerHandler.Completion done = new SlayerHandler.Completion(
            "The Cave Kraken boss", BOSS, CAVE_KRAKEN_BOSS, NIEVE, 0, 50, 50,
            14200, 150, 10, 200, "line");

        Map<String, Object> fields = SlayerHandler.fields(done, 1_700_000_000L);

        assertEquals("The Cave Kraken boss", fields.get("task_name"));
        assertEquals(BOSS, fields.get("task_id"));
        assertEquals(true, fields.get("is_boss"));
        assertEquals(CAVE_KRAKEN_BOSS, fields.get("boss_id"));
        assertEquals(NIEVE, fields.get("master_id"));
        assertEquals(50, fields.get("amount_initial"));
        assertEquals(50, fields.get("amount_killed"));
        assertEquals(14200, fields.get("xp_gained"));
        assertEquals(150, fields.get("streak"));
        assertEquals(10, fields.get("points_awarded"));
        assertEquals(200, fields.get("points_total"));
        assertEquals("line", fields.get("completion_message"));
        assertEquals(1_700_000_000L, fields.get("timestamp"));
        assertFalse("no area outside Konar", fields.containsKey("area_id"));
    }

    /**
     * addFields turns null into "N/A", which the server would keep as text: a
     * master called "N/A", a message reading "N/A". Unknowns stay out.
     */
    @Test
    public void unknownsAreLeftOut() {
        SlayerHandler.Completion done = new SlayerHandler.Completion(
            "Birds", BIRDS, 0, TURAEL, 0, 0, 20, null, null, null, null, "line");

        Map<String, Object> fields = SlayerHandler.fields(done, 1L);

        assertFalse(fields.containsValue(null));
        assertFalse(fields.containsKey("boss_id"));
        assertFalse(fields.containsKey("amount_initial"));
        assertFalse(fields.containsKey("xp_gained"));
        assertFalse(fields.containsKey("streak"));
        assertFalse(fields.containsKey("points_awarded"));
        assertFalse(fields.containsKey("points_total"));
        assertFalse(fields.containsKey("master_name"));
        assertEquals(false, fields.get("is_boss"));
    }
}

package io.droptracker.events;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;

/**
 * Tests the trawling catch-message parser and the trawling-species id map
 * exposed via {@code @VisibleForTesting}. The species map doubles as the
 * allowlist that keeps ordinary fishing "You catch a ..." messages from being
 * submitted as trawling loot.
 */
public class TrawlingHandlerParseTest {

    @Test
    public void parsesSingleCatch() {
        TrawlingHandler.ParsedCatch parsed = TrawlingHandler.parseCatch("You catch a raw halibut!");
        assertNotNull(parsed);
        assertEquals("raw halibut", parsed.getFishName());
        assertEquals(1, parsed.getQuantity());
    }

    @Test
    public void parsesMultiCatchWithCount() {
        TrawlingHandler.ParsedCatch parsed = TrawlingHandler.parseCatch("You catch 2 raw giant krill!");
        assertNotNull(parsed);
        assertEquals("raw giant krill", parsed.getFishName());
        assertEquals(2, parsed.getQuantity());
    }

    @Test
    public void parsesAnArticleAndPeriodEnding() {
        TrawlingHandler.ParsedCatch parsed = TrawlingHandler.parseCatch("You catch an orangefin.");
        assertNotNull(parsed);
        assertEquals("orangefin", parsed.getFishName());
        assertEquals(1, parsed.getQuantity());
    }

    @Test
    public void rejectsCrewmateCatches() {
        assertNull(TrawlingHandler.parseCatch("First mate Dave catches 3 raw haddock!"));
        assertNull(TrawlingHandler.parseCatch("Koeppy catches a raw marlin!"));
    }

    @Test
    public void rejectsTrawlersTrustBonusLines() {
        assertNull(TrawlingHandler.parseCatch("Your Trawler's trust grants you an extra catch: You catch a raw bluefin!"));
    }

    @Test
    public void rejectsNetCollectionMessages() {
        assertNull(TrawlingHandler.parseCatch("You empty the net into your cargo hold."));
        assertNull(TrawlingHandler.parseCatch("You take all of the fish from the net."));
        assertNull(TrawlingHandler.parseCatch("You take some fish from the net"));
    }

    @Test
    public void rejectsZeroQuantity() {
        assertNull(TrawlingHandler.parseCatch("You catch 0 raw haddock!"));
    }

    @Test
    public void resolvesAllTrawlingSpecies() {
        assertEquals(Integer.valueOf(32309), TrawlingHandler.resolveFishId("raw giant krill"));
        assertEquals(Integer.valueOf(32317), TrawlingHandler.resolveFishId("raw haddock"));
        assertEquals(Integer.valueOf(32325), TrawlingHandler.resolveFishId("raw yellowfin"));
        assertEquals(Integer.valueOf(32333), TrawlingHandler.resolveFishId("raw halibut"));
        assertEquals(Integer.valueOf(32341), TrawlingHandler.resolveFishId("raw bluefin"));
        assertEquals(Integer.valueOf(32349), TrawlingHandler.resolveFishId("raw marlin"));
    }

    @Test
    public void resolvesTrophyFish() {
        assertEquals(Integer.valueOf(31408), TrawlingHandler.resolveFishId("giant blue krill"));
        assertEquals(Integer.valueOf(31412), TrawlingHandler.resolveFishId("golden haddock"));
        assertEquals(Integer.valueOf(31416), TrawlingHandler.resolveFishId("orangefin"));
        assertEquals(Integer.valueOf(31420), TrawlingHandler.resolveFishId("huge halibut"));
        assertEquals(Integer.valueOf(31424), TrawlingHandler.resolveFishId("purplefin"));
        assertEquals(Integer.valueOf(31428), TrawlingHandler.resolveFishId("swift marlin"));
    }

    @Test
    public void resolvesPluralizedNames() {
        assertEquals(Integer.valueOf(32317), TrawlingHandler.resolveFishId("raw haddocks"));
        assertEquals(Integer.valueOf(32349), TrawlingHandler.resolveFishId("marlins"));
    }

    @Test
    public void ordinaryFishingSpeciesDoNotResolve() {
        assertNull(TrawlingHandler.resolveFishId("lobster"));
        assertNull(TrawlingHandler.resolveFishId("swordfish"));
        assertNull(TrawlingHandler.resolveFishId("shark"));
        assertNull(TrawlingHandler.resolveFishId("raw anglerfish"));
    }
}

package io.droptracker.events;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

import io.droptracker.testing.RuneLiteStubs;
import java.lang.reflect.Field;
import java.util.HashMap;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import org.junit.Before;
import org.junit.Test;

/**
 * Reading the POH adventure log owner (ticket #472).
 *
 * <p>The adventure log opens in one of two menu interfaces, and the player's
 * interface style setting decides which. Only the original one was handled, so
 * on the newer style the owner was never read and the Counters page PB sync
 * silently did nothing.
 */
public class WidgetEventHandlerAdventureLogTest {

    private static final String PLAYER = "Rickness666";

    private final Map<Integer, Widget> widgets = new HashMap<>();
    private WidgetEventHandler handler;

    @Before
    public void setUp() {
        Client client = RuneLiteStubs.client(RuneLiteStubs.player(PLAYER, 126));
        RuneLiteStubs.state(client).put("getWidget",
            (RuneLiteStubs.Answer) args -> widgets.get((Integer) args[0]));
        handler = new WidgetEventHandler();
        handler.client = client;
    }

    @Test
    public void readsOwnerFromNewerMenuInterface() {
        // The title is a later dynamic child, among null and non-text children.
        widgets.put(InterfaceID.MenuNew.TITLE, container(null,
            null, text(null), text(""), text("The Exploits of " + PLAYER), text("The Exploits of Someone Else")));

        openAdventureLog(InterfaceID.MENU_NEW);

        assertEquals(PLAYER, pohOwner());
    }

    @Test
    public void readsOwnerFromOriginalMenuInterface() {
        widgets.put(InterfaceID.Menu.LJ_LAYER2, container(null, text(""), text("The Exploits of " + PLAYER)));

        openAdventureLog(InterfaceID.MENU);

        assertEquals(PLAYER, pohOwner());
    }

    @Test
    public void readsOwnerFromContainerTextAndStripsTags() {
        widgets.put(InterfaceID.MenuNew.TITLE, container("<col=ff981f>The Exploits of </col>" + PLAYER));

        assertEquals(PLAYER, handler.readAdventureLogOwner());
    }

    @Test
    public void unrelatedMenuDoesNotSetOwner() {
        widgets.put(InterfaceID.Menu.LJ_LAYER2, container(null, text("Select an option"), text("Teleport")));

        openAdventureLog(InterfaceID.MENU);

        assertNull(pohOwner());
    }

    @Test
    public void changingRegionOrWorldClearsOwner() {
        widgets.put(InterfaceID.MenuNew.TITLE, container(null, text("The Exploits of " + PLAYER)));
        openAdventureLog(InterfaceID.MENU_NEW);

        handler.onGameStateChanged(GameState.LOADING);
        assertNull(pohOwner());

        openAdventureLog(InterfaceID.MENU_NEW);
        handler.onGameStateChanged(GameState.HOPPING);
        assertNull(pohOwner());
    }

    @Test
    public void matchAdventureLogOwnerIgnoresOtherText() {
        assertNull(WidgetEventHandler.matchAdventureLogOwner(null));
        assertNull(WidgetEventHandler.matchAdventureLogOwner("Counters"));
        assertEquals("A Name", WidgetEventHandler.matchAdventureLogOwner("The Exploits of A Name"));
    }

    private void openAdventureLog(int groupId) {
        WidgetLoaded loaded = new WidgetLoaded();
        loaded.setGroupId(groupId);
        handler.onWidgetLoaded(loaded);
        handler.onGameTick(new GameTick());
    }

    private String pohOwner() {
        try {
            Field field = WidgetEventHandler.class.getDeclaredField("pohOwner");
            field.setAccessible(true);
            return (String) field.get(handler);
        } catch (ReflectiveOperationException e) {
            throw new AssertionError(e);
        }
    }

    private static Widget text(String value) {
        Widget widget = RuneLiteStubs.stub(Widget.class, "text:" + value);
        RuneLiteStubs.state(widget).put("getText", value);
        return widget;
    }

    private static Widget container(String ownText, Widget... children) {
        Widget widget = text(ownText);
        RuneLiteStubs.state(widget).put("getChildren", children);
        return widget;
    }
}

