package io.droptracker.service;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import io.droptracker.models.api.GroupConfig;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.Test;

/**
 * Clan chat sync is on by default, so the relay must stay silent unless one of
 * the player's own groups set up the clan they are in.
 */
public class ClanRelayOptInTest {

    private static GroupConfig group(boolean bridge, boolean tracking, String slug) {
        return new Gson().fromJson(String.format(
            "{\"group_id\":\"1\",\"clan_chat_bridge\":%s,\"clan_broadcast_tracking\":%s,"
                + "\"clan_chat_slug\":%s}",
            bridge, tracking, slug == null ? "null" : "\"" + slug + "\""), GroupConfig.class);
    }

    @Test
    public void slugMatchesTheServerRule() {
        assertEquals("the best clan", ClanRelayService.clanSlug("The_Best-Clan"));
        assertEquals("the best clan", ClanRelayService.clanSlug("<col=ff0000>The Best  Clan</col> "));
        assertEquals("", ClanRelayService.clanSlug(null));
    }

    @Test
    public void bridgedClanRelaysChatAndBroadcasts() {
        List<GroupConfig> groups = Collections.singletonList(group(true, false, "the best clan"));
        assertTrue(ClanRelayService.clanOptedIn("The_Best Clan", groups, true));
        assertTrue(ClanRelayService.clanOptedIn("The_Best Clan", groups, false));
    }

    @Test
    public void trackingOnlyClanRelaysBroadcastsButNotChat() {
        List<GroupConfig> groups = Collections.singletonList(group(false, true, "the best clan"));
        assertFalse(ClanRelayService.clanOptedIn("The Best Clan", groups, true));
        assertTrue(ClanRelayService.clanOptedIn("The Best Clan", groups, false));
    }

    @Test
    public void nothingIsRelayedOutsideAnOptedInClan() {
        List<GroupConfig> groups = Arrays.asList(
            group(true, true, "another clan"), group(false, false, null));
        // In a different clan than the group bridges.
        assertFalse(ClanRelayService.clanOptedIn("The Best Clan", groups, false));
        // Not in a clan at all.
        assertFalse(ClanRelayService.clanOptedIn(null, groups, false));
        // In no group, or group configs not loaded yet.
        assertFalse(ClanRelayService.clanOptedIn("Another Clan", Collections.emptyList(), false));
        assertFalse(ClanRelayService.clanOptedIn("Another Clan", null, false));
    }

    @Test
    public void olderServerWithoutTheFieldsMeansNoRelay() {
        GroupConfig legacy = new Gson().fromJson("{\"group_id\":\"1\"}", GroupConfig.class);
        assertFalse(ClanRelayService.clanOptedIn("Any Clan",
            Collections.singletonList(legacy), false));
    }

    // ── webhook-only clients: the published list ──────────────────────────

    @Test
    public void publishedHashMatchesTheServer() {
        // utils/clan_relay_gate.published_hash("realists") on the server.
        assertEquals("9929627de8a8e5c6", ClanRelayService.publishedHash("realists"));
    }

    @Test
    public void publishedListGatesLikeTheGroupCheck() {
        Map<String, String> published = new HashMap<>();
        published.put(ClanRelayService.publishedHash("the best clan"), "b");
        published.put(ClanRelayService.publishedHash("trackers"), "t");
        assertTrue(ClanRelayService.clanInPublishedList("The_Best Clan", published, true));
        assertTrue(ClanRelayService.clanInPublishedList("The Best Clan", published, false));
        assertFalse(ClanRelayService.clanInPublishedList("Trackers", published, true));
        assertTrue(ClanRelayService.clanInPublishedList("Trackers", published, false));
        assertFalse(ClanRelayService.clanInPublishedList("Strangers", published, false));
        assertFalse(ClanRelayService.clanInPublishedList(null, published, false));
        // Not fetched yet, or the server published "none".
        assertFalse(ClanRelayService.clanInPublishedList("The Best Clan", null, false));
        assertFalse(ClanRelayService.clanInPublishedList("The Best Clan", new HashMap<>(), false));
    }
}

package io.droptracker.service;

import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

/**
 * Tests the rule that decides which item id a collection log unlock is recorded
 * under. The cache walk itself needs a running client; the judgement does not,
 * and it is the judgement that has been getting this wrong.
 *
 * <p>An unlock arrives as a chat message carrying only the item's *name*, which
 * {@link io.droptracker.util.ItemIDSearch} resolves to the earliest item sharing
 * it. For a duplicated name that is the wrong item — the collection log's Coal
 * bag is 25627, the item cache answers 764 — and nothing errors: the slot simply
 * stays empty on the player's profile while a non-slot id sits in their item
 * map.
 */
public class CollectionLogSlotsTest {

    /** Coal bag, Pet snakeling, and both Graceful hoods. */
    private static final Set<Integer> SLOTS = new HashSet<>();
    private static final Map<String, Integer> BY_NAME = new HashMap<>();

    static {
        SLOTS.add(25627);
        SLOTS.add(12921);
        SLOTS.add(11850);
        SLOTS.add(21061);
        BY_NAME.put("coal bag", 25627);
        BY_NAME.put("pet snakeling", 12921);
        // Two slots, one name: unanswerable from a name alone.
        BY_NAME.put("graceful hood", null);
    }

    private static Integer resolve(Integer candidate, String name) {
        return CollectionLogSlots.resolve(candidate, name, SLOTS, BY_NAME);
    }

    @Test
    public void anIdThatIsAlreadyASlotIsKept() {
        assertEquals(Integer.valueOf(12921), resolve(12921, "Pet snakeling"));
    }

    @Test
    public void aSameNamedImpostorIsCorrectedToTheSlot() {
        // The whole point: 764 is a Coal bag, but not the log's Coal bag.
        assertEquals(Integer.valueOf(25627), resolve(764, "Coal bag"));
    }

    @Test
    public void anAmbiguousNameIsRefused() {
        // Rooftop Agility and the Hallowed Sepulchre both have a Graceful hood
        // slot, and the chat message does not say which was unlocked. Recording
        // either would be a coin flip; the next full read knows the answer.
        assertNull(resolve(30045, "Graceful hood"));
    }

    @Test
    public void anUnknownNameIsRefused() {
        // A game update adds slots before the cache read knows them. Better a
        // slot that fills on the next full read than a wrong id recorded now.
        assertNull(resolve(30805, "Dossier"));
    }

    @Test
    public void aNullCandidateStillResolvesByName() {
        // ItemIDSearch has not finished loading, or has no row for the name.
        assertEquals(Integer.valueOf(25627), resolve(null, "Coal bag"));
    }

    @Test
    public void nameMatchingIgnoresCaseAndPadding() {
        assertEquals(Integer.valueOf(25627), resolve(764, "  coal BAG "));
    }

    @Test
    public void anEmptyNameWithAnUnknownIdIsRefused() {
        assertNull(resolve(764, ""));
        assertNull(resolve(764, null));
    }

    @Test
    public void duplicateNamesArePoisonedRatherThanOverwritten() {
        Map<Integer, String> names = new HashMap<>();
        names.put(11850, "Graceful hood");
        names.put(21061, "Graceful hood");
        names.put(30045, "Graceful hood");
        names.put(25627, "Coal bag");

        Map<String, Integer> index = CollectionLogSlots.indexByName(names);
        assertEquals(Integer.valueOf(25627), index.get("coal bag"));
        // Present, but deliberately unanswerable — and a third sighting must
        // not resurrect it.
        assertEquals(true, index.containsKey("graceful hood"));
        assertNull(index.get("graceful hood"));
    }

    @Test
    public void unnamedSlotsAreSkipped() {
        // A cache miss names an item "null"; indexing that would let any unlock
        // the client could not name resolve to a random slot.
        Map<Integer, String> names = new HashMap<>();
        names.put(1, null);
        names.put(2, "");
        names.put(3, "null");
        assertEquals(0, CollectionLogSlots.indexByName(names).size());
    }
}

package io.droptracker.service;

import com.google.gson.Gson;
import io.droptracker.DropTrackerConfig;
import io.droptracker.models.EventDisplayMode;
import io.droptracker.models.EventPopupCard;
import io.droptracker.models.api.EventNotification;
import io.droptracker.models.api.EventNotification.Priority;
import io.droptracker.models.api.EventState;
import io.droptracker.service.EventNotificationService.DisplayTask;
import io.droptracker.service.EventNotificationService.Toast;
import io.droptracker.util.ChatMessageUtil;
import org.junit.Test;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * Broadcast legibility: the importance tier drives which pop-up survives a
 * batch, how long it lives and whether "important only" lets it through, and
 * every chat line carries its own type tag. The JSON bodies mirror what the
 * server actually enqueues (services/event_engine.py), and each fixture's
 * display block is services/plugin_display.py's real output for its data.
 *
 * <p>Also covers what a task hidden in the Events tab is allowed to say: the
 * hide has to reach the chat, the pop-ups and the HUD, not just the list it
 * was clicked in.
 */
public class EventBroadcastPriorityTest {

    private final Gson gson = new Gson();

    /* ===================== envelope contract ===================== */

    @Test
    public void missingOrUnknownPriorityReadsAsNormal() {
        // The field post-dates the wire contract: a server that never sends it
        // (or sends something we don't know) must not break the plugin.
        assertEquals(Priority.NORMAL, envelope("event_completion", "{}", null).priorityTier());
        assertEquals(Priority.NORMAL, envelope("event_completion", "{}", "critical").priorityTier());
        assertEquals(Priority.NORMAL, Priority.from(null));
        assertEquals(Priority.NORMAL, Priority.from(""));
        assertEquals(Priority.HIGH, envelope("event_completion", "{}", "high").priorityTier());
        assertEquals(Priority.LOW, envelope("event_task_progress", "{}", "low").priorityTier());
        assertEquals(Priority.HIGH, Priority.from("HIGH"));
    }

    @Test
    public void parsesTheDisplayBlock() {
        EventNotification.Display d = tileCompletion(null).getDisplay();
        assertEquals("Tile complete!", d.getTitle());
        assertEquals("TILE COMPLETE", d.getChat().getTag());
        assertEquals("tile", d.getChat().getTone());
        assertEquals(EventPopupCard.Kind.TILE, d.getCard().getKind());
        assertEquals("Standing:", d.getCard().getRightLabel());
        assertEquals("2nd of 5", d.getCard().getRightValue());
        // The typed fields older plugins render from are still there.
        assertEquals(Integer.valueOf(218), tileCompletion(null).getData().getTaskId());
    }

    /* ===================== pop-up policy ===================== */

    @Test
    public void tileCompletionHeadlinesTheBatchAndTheRestFold() {
        RecordingChat chat = new RecordingChat();
        EventNotificationService service = service(new TestConfig(), chat);
        service.renderBatch(Arrays.asList(
            progressTick(), tileCompletion(null), otherEventCompletion()));

        // One card for the whole batch, headlined by the important update.
        List<Toast> toasts = new ArrayList<>(service.getToasts());
        assertEquals(1, toasts.size());
        Toast toast = toasts.get(0);
        assertEquals(Priority.HIGH, toast.getPriority());
        assertEquals("Tile complete!", toast.getTitle());
        assertTrue(toast.getBody(), toast.getBody().contains("tile: Bandos set"));
        assertTrue(toast.getBody(), toast.getBody().contains("7 tiles, 2nd of 5"));
        assertTrue(toast.getBody(), toast.getBody().endsWith("(+2 more)"));
    }

    @Test
    public void theServersWordingIsShownButSanitized() {
        RecordingChat chat = new RecordingChat();
        EventNotificationService service = service(new TestConfig(), chat);
        service.renderBatch(java.util.Collections.singletonList(envelope("event_line", "{}", "high",
            "{'title':'<img=1>Bingo line!','text':'<col=ff0000>Red</col> completed a line!',"
                + "'chat':{'tag':'BINGO LINE','tone':'not-a-tone','emphasis':'<b>Red'},"
                + "'card':{'kind':'LINE','caption':'Bingo line','headline':'<col=00ff00>Red',"
                + "'leftLabel':'Bonus:','leftValue':'<br>+10 pts'}}")));
        Toast toast = service.getToasts().getFirst();
        assertEquals("Bingo line!", toast.getTitle());
        assertEquals("Red completed a line!", toast.getBody());
        assertEquals("Red", toast.getCard().getHeadline());
        assertEquals("+10 pts", toast.getCard().getLeftValue());
        assertEquals("Red", chat.lines.get(0).emphasis);
        assertNull(chat.lines.get(0).hex); // an unknown tone stays uncoloured
    }

    @Test
    public void anEnvelopeWithoutADisplayIsDropped() {
        // A server from before display (or a type it composed nothing for):
        // dropped like an unknown type, never rendered half-empty.
        RecordingChat chat = new RecordingChat();
        EventNotificationService service = service(new TestConfig(), chat);
        service.renderBatch(java.util.Collections.singletonList(gson.fromJson(
            "{\"id\":\"x\",\"type\":\"event_line\",\"ts\":1,\"data\":{}}", EventNotification.class)));
        assertTrue(chat.lines.isEmpty());
        assertTrue(service.getToasts().isEmpty());
    }

    @Test
    public void theTimeLeftNoteIsKeptByTheReadersClock() {
        String endsAt = java.time.LocalDateTime.now(java.time.ZoneOffset.UTC).plusHours(5).plusMinutes(1)
            .withNano(0).toString();
        RecordingChat chat = new RecordingChat();
        EventNotificationService service = service(new TestConfig(), chat);
        service.renderBatch(java.util.Collections.singletonList(envelope("event_line", "{}", "high",
            "{'title':'Bingo line!','text':'Red completed a line!','ends_at':'" + endsAt + "',"
                + "'card':{'kind':'LINE','caption':'Bingo line','headline':'Red'}}")));
        assertEquals("5h 0m left", service.getToasts().getFirst().getCard().getNote());
    }

    @Test
    public void serverPriorityOverridesTheLocalDefault() {
        RecordingChat chat = new RecordingChat();
        EventNotificationService service = service(new TestConfig(), chat);
        // The same tile completion the server chose to call routine.
        service.renderBatch(java.util.Collections.singletonList(tileCompletion("low")));
        assertEquals(Priority.LOW, service.getToasts().getFirst().getPriority());
    }

    @Test
    public void importantOnlyDropsOrdinaryPopUpsButKeepsChat() {
        TestConfig config = new TestConfig();
        config.importantOnly = true;
        RecordingChat chat = new RecordingChat();
        EventNotificationService service = service(config, chat);

        service.renderBatch(java.util.Collections.singletonList(progressTick()));
        assertTrue(service.getToasts().isEmpty());
        assertEquals(1, chat.lines.size()); // chat is never filtered by tier

        service.renderBatch(java.util.Collections.singletonList(tileCompletion(null)));
        assertEquals(1, service.getToasts().size());
    }

    @Test
