        // Distinct envelope ids (the seen-id guard is upstream of this), same
        // (event, task, type) — one human-visible update, one card.
        service.renderBatch(java.util.Collections.singletonList(progressTick()));
        service.renderBatch(java.util.Collections.singletonList(progressTick()));
