package io.droptracker.service;

import io.droptracker.api.DropTrackerUrls;
import okhttp3.HttpUrl;
import com.google.gson.Gson;
import io.droptracker.api.DropTrackerApi;
import io.droptracker.models.api.EventNotification;
import io.droptracker.models.api.EventState;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * Wire-format tests: the JSON bodies here mirror what the production API
 * actually returns (captured from live /notifications and /event_state
 * responses), pinning the plugin's parsing of the server contract.
 */
public class EventNotificationParseTest {

    private final Gson gson = new Gson();

    @Test
    public void parsesNotificationsResponse() {
        String json = "{\"notifications\":[{"
            + "\"id\":\"1752770000-abc12345\",\"type\":\"event_completion\",\"ts\":1752770000,"
            + "\"event\":{\"id\":19,\"name\":\"Bingo Extravaganza\"},"
            + "\"data\":{\"task_id\":42,\"task_label\":\"Obtain 3 Bandos hilts\",\"team_id\":38,"
            + "\"team_name\":\"Team Alpha\",\"player_name\":\"Koeppy\",\"points\":5,"
            + "\"icon_item_id\":11804,\"progress\":3,\"target\":3}}],"
            + "\"active_event\":true}";
        DropTrackerApi.NotificationsResponse response =
            gson.fromJson(json, DropTrackerApi.NotificationsResponse.class);
        assertNotNull(response.notifications);
        assertEquals(1, response.notifications.size());
        assertEquals(Boolean.TRUE, response.activeEvent);

        EventNotification n = response.notifications.get(0);
        assertEquals("event_completion", n.getType());
        assertEquals(Integer.valueOf(19), n.getEvent().getId());
        assertEquals(Integer.valueOf(42), n.getData().getTaskId());
        assertEquals("Obtain 3 Bandos hilts", n.getData().getTaskLabel());
    }

    @Test
    public void parsesLongPollMarker() {
        // Long-poll servers stamp long_poll=true on wait-requests; legacy
        // servers omit it entirely, which must parse as null (not false).
        DropTrackerApi.NotificationsResponse held = gson.fromJson(
            "{\"notifications\":[],\"active_event\":true,\"long_poll\":true}",
            DropTrackerApi.NotificationsResponse.class);
        assertEquals(Boolean.TRUE, held.longPoll);

        DropTrackerApi.NotificationsResponse legacy = gson.fromJson(
            "{\"notifications\":[],\"active_event\":true}",
            DropTrackerApi.NotificationsResponse.class);
        assertNull(legacy.longPoll);
    }

    @Test
    public void unknownFieldsAndTypesParseWithoutError() {
        // Forward compatibility: a future type with unknown fields must still
        // deserialize (the service then drops it by type).
        String json = "{\"notifications\":[{"
            + "\"id\":\"x\",\"type\":\"event_meteor_strike\",\"ts\":1,"
            + "\"data\":{\"brand_new_field\":{\"nested\":true}}}],\"active_event\":false}";
        DropTrackerApi.NotificationsResponse response =
            gson.fromJson(json, DropTrackerApi.NotificationsResponse.class);
        assertEquals("event_meteor_strike", response.notifications.get(0).getType());
        assertNull(response.notifications.get(0).getEvent());
    }

    @Test
    public void parsesEventState() {
        // Shape captured from the live /event_state endpoint (board_game +
        // bingo entries, all three focus sources).
        String json = "{\"events\":[{"
            + "\"event\":{\"id\":18,\"name\":\"Droptracker Board\",\"kind\":\"board_game\","
            + "\"has_bingo\":false,\"ends_at\":\"2026-07-30T13:07:00\"},"
            + "\"team\":{\"id\":36,\"name\":\"Jimmy Baller\",\"color\":null,"
            + "\"icon_item_id\":null,\"icon_path\":null,\"score\":0,\"rank\":1,\"team_count\":2},"
            + "\"focus_task\":{\"id\":218,\"label\":\"Bandos Chestplate\",\"have\":0,\"need\":1,"
            + "\"icon_item_id\":11832,\"icon_path\":null,\"source\":\"board\"},"
            + "\"board_status\":\"active\",\"tasks_completed\":1,\"tasks_total\":83,"
            + "\"board\":{\"available\":true,\"team_id\":36},"
            + "\"standings\":[{\"team_id\":36,\"name\":\"Jimmy Baller\",\"score\":0,\"rank\":1,\"color\":null},"
            + "{\"team_id\":37,\"name\":\"Steve-O sickos\",\"score\":0,\"rank\":2,\"color\":null}]},"
            + "{\"event\":{\"id\":19,\"name\":\"Bingo\",\"kind\":\"bingo\",\"has_bingo\":true,\"ends_at\":null},"
            + "\"team\":{\"id\":38,\"name\":\"T\",\"color\":\"#cc4444\",\"icon_item_id\":null,"
            + "\"icon_path\":null,\"score\":5,\"rank\":2,\"team_count\":2},"
            + "\"focus_task\":{\"id\":127,\"label\":\"1,000,000 Magic XP\",\"have\":297656,"
            + "\"need\":1000000,\"icon_item_id\":null,"
            + "\"icon_path\":\"metrics/magic.png\",\"source\":\"team_progress\"},"
            + "\"board_status\":null,\"tasks_completed\":5,\"tasks_total\":24,"
            + "\"board\":{\"available\":true,\"team_id\":38},\"standings\":[],"
            + "\"tasks\":[{\"id\":127,\"label\":\"1,000,000 Magic XP\",\"type\":\"xp_target\","
            + "\"points\":5,\"have\":297656,\"need\":1000000,\"completed\":false,"
            + "\"icon_item_id\":null,\"icon_path\":\"metrics/magic.png\","
            + "\"badge\":\"XP TARGET\",\"value\":\"1.00M XP\","
            + "\"description\":\"Gain 1.00M Magic XP as a team.\",\"requirements\":[]},"
            + "{\"id\":128,\"label\":\"Point hunt\",\"type\":\"item_collection\",\"points\":10,"
            + "\"have\":25,\"need\":50,\"completed\":false,\"icon_item_id\":20997,\"icon_path\":null,"
            + "\"badge\":\"POINTS\",\"value\":\"50 pts\","
            + "\"description\":\"Earn 50 points. Each listed item awards its own point value.\","
            + "\"requirements\":[{\"name\":\"Twisted bow\",\"points\":25},"
            + "{\"name\":\"Dragon claws\",\"quantity\":2,\"points\":10,\"obtained\":true}]}],"
            + "\"members\":[{\"player_id\":1,\"name\":\"joelhalen\"},"
            + "{\"player_id\":3422,\"name\":\"Ra ine\"}],\"members_total\":69}]}";
        EventState state = gson.fromJson(json, EventState.class);
        assertEquals(2, state.getEvents().size());

        EventState.Entry board = state.getEvents().get(0);
        assertEquals("board_game", board.getEvent().getKind());
        assertEquals("active", board.getBoardStatus());
        assertEquals("board", board.getFocusTask().getSource());
        assertEquals(Integer.valueOf(11832), board.getFocusTask().getIconItemId());

        EventState.Entry bingo = state.getEvents().get(1);
        assertNull(bingo.getBoardStatus());
        assertEquals(297656L, bingo.getFocusTask().getHave());
        assertEquals("metrics/magic.png", bingo.getFocusTask().getIconPath());
        assertEquals("#cc4444", bingo.getTeam().getColor());

        // P3 additions: full task list (absent on older servers).
        assertNull(board.getTasks());
        assertNotNull(bingo.getTasks());
        assertEquals(2, bingo.getTasks().size());
        EventState.TaskInfo xp = bingo.getTasks().get(0);
        assertEquals("XP TARGET", xp.getBadge());
        assertEquals("Gain 1.00M Magic XP as a team.", xp.getDescription());
        assertFalse(xp.isCompleted());
        EventState.TaskInfo points = bingo.getTasks().get(1);
        assertEquals(2, points.getRequirements().size());
        assertEquals("Twisted bow", points.getRequirements().get(0).getName());
        assertEquals(Integer.valueOf(25), points.getRequirements().get(0).getPoints());
        assertEquals(Integer.valueOf(2), points.getRequirements().get(1).getQuantity());
        assertNull(points.getRequirements().get(0).getObtained());
        assertEquals(Boolean.TRUE, points.getRequirements().get(1).getObtained());
    }

    @Test
    public void cleanStripsTagsAndCaps() {
        assertEquals("hello world",
            EventNotificationService.clean("<col=ff0000>hello</col> world"));
        assertNull(EventNotificationService.clean("   "));
        assertNull(EventNotificationService.clean(null));
        String longText = new String(new char[300]).replace('\0', 'a');
        String cleaned = EventNotificationService.clean(longText);
        assertNotNull(cleaned);
        assertTrue(cleaned.length() <= 121);
        assertTrue(cleaned.endsWith("…"));
    }

    @Test
    public void iconPathsAnchorOnTheHardcodedImageHost() {
        // The API sends /img/-relative paths; the plugin owns the host. Anything
        // that looks like a URL is refused outright rather than fetched.
        assertEquals(HttpUrl.get("https://www.droptracker.io/img/metrics/magic.png"),
            DropTrackerUrls.image("metrics/magic.png"));
        assertNull(DropTrackerUrls.image("https://evil.example.com/x.png"));
        assertNull(DropTrackerUrls.image("http://www.droptracker.io/img/x.png"));
        assertNull(DropTrackerUrls.image("../../evil"));
        assertNull(DropTrackerUrls.image(null));
    }
}

package io.droptracker.service;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import io.droptracker.DropTrackerConfig;
import io.droptracker.models.EventDisplayMode;
import io.droptracker.models.EventPopupCard;
import io.droptracker.models.EventPopupStyle;
import io.droptracker.models.api.EventNotification;
import io.droptracker.models.api.EventState;
import io.droptracker.service.EventNotificationService.Toast;
import io.droptracker.util.ChatMessageUtil;
import net.runelite.client.config.ConfigManager;

import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.function.Supplier;

/**
 * DEV ONLY, not registered in release builds (see
 * DropTrackerPlugin#onCommandExecuted to switch it back on).
 *
 * {@code ::dtpopup}: fake event pop-ups on demand, so the layouts can be
 * judged in a real client without a live event. Samples are ordinary
 * notification envelopes pushed through the real renderer, so they read
 * exactly as the live ones would; only the chat line, the filters and the
 * dedupe are skipped. Nothing is sent to the server.
 *
 * <pre>
 *   ::dtpopup                   usage + current styles
 *   ::dtpopup test [kind]       one sample pop-up (kinds: see KINDS)
 *   ::dtpopup all               every kind, one after another
 *   ::dtpopup demo [kind]       the same pop-up as a showcase, then a banner
 *   ::dtpopup mode [chat|popup|hud]  switch the event display type
 * </pre>
 */
@Singleton
public class EventPopupPreview {
    public static final String COMMAND = "dtpopup";

    private static final long DEMO_STEP_MS = 5500;
    private static final long ALL_STEP_MS = 1800;
    /** How long a preview may lend the HUD its sample event. */
    private static final long PREVIEW_HUD_MS = 90_000;
    private static final int PREVIEW_EVENT_ID = -4242;
    private static final String PREVIEW_EVENT = "Autumn Bingo";
    private static final String PREVIEW_TEAM = "Iron Eagles";
    /** Sample tasks whose icons come from the sample event, not the envelope. */
    private static final int PREVIEW_KC_TASK = 9101;
    private static final int PREVIEW_XP_TASK = 9102;

    private final DropTrackerConfig config;
    private final ConfigManager configManager;
    private final EventNotificationService service;
    private final ChatMessageUtil chat;
    private final ScheduledExecutorService executor;
    private final Gson gson;

    /** Sample makers by kind name, in the order "all" plays them. */
    private final Map<String, Supplier<JsonObject>> kinds = new LinkedHashMap<>();
    private final List<ScheduledFuture<?>> scheduled = new ArrayList<>();

    @Inject
    public EventPopupPreview(DropTrackerConfig config, ConfigManager configManager,
                             EventNotificationService service, ChatMessageUtil chat,
                             ScheduledExecutorService executor, Gson gson) {
        this.config = config;
        this.configManager = configManager;
        this.service = service;
        this.chat = chat;
        this.executor = executor;
        this.gson = gson;
        kinds.put("tile", this::tileSample);
        kinds.put("complete", this::completeSample);
        kinds.put("progress", this::progressSample);
        kinds.put("kc", () -> envelope("event_completion", "normal", data()
            .put("task_id", PREVIEW_KC_TASK).put("player_name", "Zezima")
            .put("task_label", "Kill Vorkath 50 times").put("points", 15)
            .put("team_name", PREVIEW_TEAM).json));
        kinds.put("xp", () -> envelope("event_task_progress", "low", data()
            .put("task_id", PREVIEW_XP_TASK).put("player_name", "Lynx Titan")
            .put("task_label", "Gain 2M Slayer XP").put("progress", 1_300_000)
            .put("target", 2_000_000).put("milestone_pct", 50).json));
        kinds.put("lead", () -> envelope("event_lead_change", "high", data()
            .put("team_name", PREVIEW_TEAM).put("team_score", 1240).json));
        kinds.put("line", () -> envelope("event_line", "high", data()
            .put("team_name", PREVIEW_TEAM).put("bonus_points", 25).json));
        kinds.put("blackout", () -> envelope("event_blackout", "high", data()
            .put("team_name", PREVIEW_TEAM).put("bonus_points", 100).json));
        kinds.put("start", () -> envelope("event_started", "high", data().json));
        kinds.put("end", () -> envelope("event_ended", "high", data().json));
        kinds.put("board", () -> envelope("event_board_turn", "normal", data()
            .put("player_name", "Zezima").put("dice_str", "4 + 2").put("tile_to", 18)
            .put("next_task_label", "Obtain any Zenyte jewel").json));
        kinds.put("roll", () -> envelope("event_board_roll_prompt", "high", data()
            .put("coins_awarded", 3).json));
        kinds.put("digest", () -> null); // built as a toast directly, see sample()
        kinds.put("more", this::tileSample); // a tile headlining two folded updates
    }

    /** Entry point from the plugin's CommandExecuted subscriber. */
    public void onCommand(String[] args) {
        String sub = args.length > 0 ? args[0].toLowerCase(Locale.ROOT) : "help";
        String arg = args.length > 1 ? String.join(" ", Arrays.copyOfRange(args, 1, args.length)) : null;
        switch (sub) {
            case "test":
            case "show":
                test(arg != null ? arg.toLowerCase(Locale.ROOT) : "tile");
                break;
            case "all":
                playAll();
                break;
            case "demo":
                demo(arg != null ? arg.toLowerCase(Locale.ROOT) : "tile");
                break;
            case "mode":
                setMode(arg);
                break;
            case "stop":
            case "clear":
                cancelScheduled();
                service.getToasts().clear();
                say("Cleared the pop-ups.");
                break;
            default:
                help();
        }
    }

    /* ===================== subcommands ===================== */

    private void help() {
        EventDisplayMode mode = config.eventDisplayMode();
        say("Pop-up preview. Display type: " + mode
            + (mode.popupsEnabled() ? " (" + mode.popupStyle() + " pop-ups)." : "."));
        say("::dtpopup demo - the same pop-up as a showcase, then a banner. ::dtpopup test [kind], ::dtpopup all.");
        say("::dtpopup mode [chat|popup|hud] - popup shows banners, hud shows showcases.");
        say("Kinds: " + String.join(", ", kinds.keySet()) + ".");
    }

    private void test(String kind) {
        if (!kinds.containsKey(kind)) {
            say("Unknown kind '" + kind + "'. Kinds: " + String.join(", ", kinds.keySet()) + ".");
            return;
        }
        if (!ready()) {
            return;
        }
        cancelScheduled();
        show(kind, null);
    }

    private void playAll() {
        if (!ready()) {
            return;
        }
        cancelScheduled();
        say("Playing every kind of pop-up (" + kinds.size() + "), in your current style.");
        long delay = 0;
        for (String kind : kinds.keySet()) {
            schedule(() -> show(kind, null), delay);
            delay += ALL_STEP_MS;
        }
    }

    /** One kind of pop-up in each style, one at a time, each introduced in chat. */
    private void demo(String kind) {
        if (!kinds.containsKey(kind)) {
            say("Unknown kind '" + kind + "'. Kinds: " + String.join(", ", kinds.keySet()) + ".");
            return;
        }
        if (!ready()) {
            return;
        }
        cancelScheduled();
        long delay = 0;
        for (EventPopupStyle style : EventPopupStyle.values()) {
            schedule(() -> {
                service.getToasts().clear();
                say(style + " pop-up (" + (style == EventPopupStyle.SHOWCASE
                    ? "Enhanced display" : "Chat + text pop-ups") + ").");
                show(kind, style);
            }, delay);
            delay += DEMO_STEP_MS;
        }
    }

    private void setMode(@Nullable String arg) {
        EventDisplayMode mode = null;
        if (arg != null) {
            switch (arg.toLowerCase(Locale.ROOT)) {
                case "chat":
                    mode = EventDisplayMode.CHAT;
                    break;
                case "popup":
                case "popups":
                    mode = EventDisplayMode.POPUP;
                    break;
                case "hud":
                case "enhanced":
                    mode = EventDisplayMode.ENHANCED;
                    break;
                default:
                    break;
            }
        }
        if (mode == null) {
            say("Display type is " + config.eventDisplayMode() + ". Use ::dtpopup mode chat, popup or hud.");
            return;
        }
        configManager.setConfiguration(DropTrackerConfig.GROUP, "eventDisplayMode", mode);
        say("Display type is now " + mode + ".");
        if (mode.popupsEnabled() && ready()) {
            cancelScheduled();
            show("tile", null);
        }
    }

    /* ===================== plumbing ===================== */

    /** False (and says why) when pop-ups can't show at all right now. */
    private boolean ready() {
        if (!config.eventNotifications()) {
            say("Event notifications are off. Turn on 'Receive notifications' in the Events settings.");
            return false;
        }
        if (!config.eventDisplayMode().popupsEnabled()) {
            say("Your display type is chat only, so there are no pop-ups. Try ::dtpopup mode popup or ::dtpopup mode hud.");
            return false;
        }
        return true;
    }

    private void show(String kind, @Nullable EventPopupStyle popup) {
        // Lend the HUD a sample event (it only paints with one to show, and a
        // live event still wins); the samples' pop-ups read their extra
        // details from it too.
        service.setPreviewHudEntry(previewHudEntry(), System.currentTimeMillis() + PREVIEW_HUD_MS);
        if ("digest".equals(kind)) {
            EventPopupCard card = new EventPopupCard(EventPopupCard.Kind.DIGEST,
                "While you were away", PREVIEW_EVENT)
                .detail("4 tasks completed (+23 pts), 1 bingo line, " + PREVIEW_TEAM + " took the lead.");
            service.previewToast(new Toast("While you were away",
                "4 tasks completed (+23 pts), 1 bingo line, " + PREVIEW_TEAM + " took the lead.",
                20997, System.currentTimeMillis(), EventNotification.Priority.HIGH, null,
                card, 0, popup));
            return;
        }
        JsonObject envelope = kinds.get(kind).get();
        // The wording is the server's now: borrow what it composes for this
        // sample (src/test/resources/io/droptracker/popup-samples.json).
        JsonObject display = SAMPLE_DISPLAYS.getAsJsonObject("more".equals(kind) ? "tile" : kind);
        if (display != null) {
            String endsAt = java.time.LocalDateTime.now(java.time.ZoneOffset.UTC).plusDays(2).plusHours(4)
                .withNano(0).toString();
            envelope.add("display", gson.fromJson(display.toString().replace("ENDS_AT", endsAt), JsonObject.class));
        }
        EventNotification n = gson.fromJson(envelope, EventNotification.class);
        boolean shown = service.previewNotification(n, popup, "more".equals(kind) ? 2 : 0);
        if (!shown) {
            say("That kind is muted by your settings (Task progress notifications is off).");
        }
    }

    private void schedule(Runnable task, long delayMs) {
        synchronized (scheduled) {
            scheduled.add(executor.schedule(task, delayMs, TimeUnit.MILLISECONDS));
        }
    }

    private void cancelScheduled() {
        synchronized (scheduled) {
            for (ScheduledFuture<?> future : scheduled) {
                future.cancel(false);
            }
            scheduled.clear();
        }
    }

    private void say(String message) {
        chat.sendChatMessage(message);
    }

    /* ===================== samples ===================== */

    private JsonObject tileSample() {
        JsonArray idxs = new JsonArray();
        idxs.add(6);
        JsonArray labels = new JsonArray();
        labels.add("Bandos set");
        JsonObject d = data()
            .put("player_name", "Zezima").put("task_label", "Obtain Bandos tassets")
            .put("received_item", "Bandos tassets").put("icon_item_id", 11834)
            .put("points", 10).put("tiles_completed", 7).put("team_rank", 2).put("team_count", 5)
            .put("team_name", PREVIEW_TEAM).json;
        d.add("cell_idxs", idxs);
        d.add("cell_labels", labels);
        return envelope("event_completion", "high", d);
    }

    private JsonObject completeSample() {
        return envelope("event_completion", "normal", data()
            .put("player_name", "Zezima").put("task_label", "Obtain a Dragon warhammer")
            .put("received_item", "Dragon warhammer").put("icon_item_id", 13576)
            .put("points", 5).put("team_name", PREVIEW_TEAM).json);
    }

    private JsonObject progressSample() {
        return envelope("event_task_progress", "low", data()
            .put("player_name", "Lynx Titan").put("task_label", "Obtain 5 Abyssal whips")
            .put("received_item", "Abyssal whip").put("icon_item_id", 4151)
            .put("progress", 2).put("target", 5).json);
    }

    private JsonObject envelope(String type, String priority, JsonObject data) {
        JsonObject event = new JsonObject();
        event.addProperty("id", PREVIEW_EVENT_ID);
        event.addProperty("name", PREVIEW_EVENT);
        JsonObject n = new JsonObject();
        // A fresh id and task each time, so nothing downstream sees a repeat.
        n.addProperty("id", "preview-" + System.nanoTime());
        n.addProperty("type", type);
        n.addProperty("ts", System.currentTimeMillis() / 1000L);
        n.addProperty("priority", priority);
        n.add("event", event);
        if (!data.has("task_id")) {
            data.addProperty("task_id", (int) (System.nanoTime() & 0x7fffffff));
        }
        n.add("data", data);
        return n;
    }

    private static final JsonObject SAMPLE_DISPLAYS = new Gson().fromJson(new java.io.InputStreamReader(
        EventPopupPreview.class.getResourceAsStream("/io/droptracker/popup-samples.json"),
        java.nio.charset.StandardCharsets.UTF_8), JsonObject.class);

    private static DataBuilder data() {
        return new DataBuilder();
    }

    /** Tiny fluent wrapper so the samples read as one expression each. */
    private static final class DataBuilder {
        final JsonObject json = new JsonObject();

        DataBuilder put(String key, String value) {
            json.addProperty(key, value);
            return this;
        }

        DataBuilder put(String key, Number value) {
            json.addProperty(key, value);
            return this;
        }
    }

    private EventState.Entry previewHudEntry() {
        JsonObject event = new JsonObject();
        event.addProperty("id", PREVIEW_EVENT_ID);
        event.addProperty("name", PREVIEW_EVENT);
        event.addProperty("kind", "bingo");
        event.addProperty("has_bingo", true);
        event.addProperty("ends_at", java.time.LocalDateTime.now(java.time.ZoneOffset.UTC)
            .plusDays(2).plusHours(4).plusMinutes(1).withNano(0).toString());
        JsonObject team = new JsonObject();
        team.addProperty("id", 1);
        team.addProperty("name", PREVIEW_TEAM);
        team.addProperty("color", "#3d9be9");
        team.addProperty("score", 1240);
        team.addProperty("rank", 2);
        team.addProperty("team_count", 5);
        JsonObject focus = new JsonObject();
        focus.addProperty("id", 1);
        focus.addProperty("label", "Obtain 5 Abyssal whips");
        focus.addProperty("have", 2);
        focus.addProperty("need", 5);
        focus.addProperty("icon_item_id", 4151);
        JsonArray tasks = new JsonArray();
        tasks.add(previewTask(PREVIEW_KC_TASK, "Kill Vorkath 50 times", 15, null, "npcdb/8061.png"));
        tasks.add(previewTask(PREVIEW_XP_TASK, "Gain 2M Slayer XP", 20, null, "metrics/slayer.png"));
        tasks.add(previewTask(9103, "Obtain any Zenyte jewel", 25, 19529, null));
        JsonObject entry = new JsonObject();
        entry.add("event", event);
        entry.add("team", team);
        entry.add("focus_task", focus);
        entry.add("tasks", tasks);
        entry.addProperty("tasks_completed", 7);
        entry.addProperty("tasks_total", 25);
        return gson.fromJson(entry, EventState.Entry.class);
    }

    private static JsonObject previewTask(int id, String label, int points,
                                          @Nullable Integer iconItemId, @Nullable String iconPath) {
        JsonObject task = new JsonObject();
        task.addProperty("id", id);
        task.addProperty("label", label);
        task.addProperty("points", points);
        if (iconItemId != null) {
            task.addProperty("icon_item_id", iconItemId);
        }
        if (iconPath != null) {
            task.addProperty("icon_path", iconPath);
        }
        return task;
    }
}

package io.droptracker.service;

import com.google.gson.Gson;
import io.droptracker.DropTrackerConfig;
import io.droptracker.models.TeamIndicatorStyle;
import io.droptracker.models.api.EventRoster;
import io.droptracker.models.api.EventState;
import io.droptracker.testing.RuneLiteStubs;
import io.droptracker.util.ChatMessageUtil;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.IterableHashTable;
import net.runelite.api.MessageNode;
import net.runelite.api.events.ScriptCallbackEvent;
import net.runelite.client.util.Text;
import org.junit.Before;
import org.junit.Test;

import java.awt.Color;
import java.awt.Font;
import java.awt.image.BufferedImage;
import java.io.InputStream;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

import static io.droptracker.testing.RuneLiteStubs.state;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * Clan-chat team badges (suggestion #150): the wire format of GET
 * /event_roster, the name matching, the badge sprites, and the chat builder
 * callback that puts a badge on a line as it is drawn.
 *
 * The callback tests drive {@code chatMessageBuilding} against a stubbed
 * client. They pin the two rules whose absence broke private messages: only
 * clan, friends-chat and opted-in public lines are badged, and the
 * {@link MessageNode} itself is never renamed.
 */
public class EventTeamIndicatorTest {

    private final Gson gson = new Gson();

    // ── wire format ──────────────────────────────────────────────────────────

    @Test
    public void parsesRosterResponse() {
        String json = "{\"events\":[{"
            + "\"event_id\":46,\"roster_version\":\"3f1c9a0b12345678\","
            + "\"teams\":[{\"id\":101,\"name\":\"Red Rockets\",\"short_tag\":\"RR\","
            + "\"color\":\"#cc3333\",\"orb\":\"🔴\",\"orb_color\":\"#dd2e44\","
            + "\"icon_item_id\":11802,\"icon_path\":null},"
            + "{\"id\":102,\"name\":\"Blue Blazers\",\"short_tag\":\"BB\","
            + "\"color\":\"#3355cc\",\"orb\":\"🔵\",\"orb_color\":\"#55acee\","
            + "\"icon_item_id\":null,\"icon_path\":null}],"
            + "\"members\":{\"101\":[\"beast owned\",\"zezima\"],\"102\":[\"woox\"]},"
            + "\"members_total\":3,\"truncated\":false}]}";

        EventRoster roster = gson.fromJson(json, EventRoster.class);
        assertNotNull(roster.getEvents());
        assertEquals(1, roster.getEvents().size());

        EventRoster.Entry entry = roster.getEvents().get(0);
        assertEquals(46, entry.getEventId());
        assertEquals("3f1c9a0b12345678", entry.getRosterVersion());
        assertEquals(3, entry.getMembersTotal());
        assertEquals(false, entry.isTruncated());

        EventRoster.Team red = entry.getTeams().get(0);
        assertEquals(101, red.getId());
        assertEquals("RR", red.getShortTag());
        assertEquals("#dd2e44", red.getOrbColor());
        assertEquals(Integer.valueOf(11802), red.getIconItemId());

        List<String> redMembers = entry.getMembers().get("101");
        assertEquals(2, redMembers.size());
        assertTrue(redMembers.contains("beast owned"));
    }

    @Test
    public void toleratesAnEmptyRoster() {
        EventRoster roster = gson.fromJson("{\"events\":[]}", EventRoster.class);
        assertNotNull(roster.getEvents());
        assertTrue(roster.getEvents().isEmpty());
    }

    @Test
    public void rosterVersionIsOptionalOnEventState() {
        // Older servers do not send the stamp; the client must parse the rest
        // of the entry rather than lose the HUD over a missing field.
        String json = "{\"events\":[{\"event\":{\"id\":46,\"name\":\"Bingo\",\"kind\":\"bingo\"},"
            + "\"team\":{\"id\":101,\"name\":\"Red Rockets\",\"score\":5,\"team_count\":2}}]}";
        EventState state = gson.fromJson(json, EventState.class);
        assertNull(state.getEvents().get(0).getRosterVersion());
    }

    @Test
    public void readsRosterVersionWhenPresent() {
        String json = "{\"events\":[{\"event\":{\"id\":46,\"name\":\"Bingo\",\"kind\":\"bingo\"},"
            + "\"team\":{\"id\":101,\"name\":\"Red Rockets\",\"score\":5,\"team_count\":2},"
            + "\"roster_version\":\"abc123\"}]}";
        EventState state = gson.fromJson(json, EventState.class);
        assertEquals("abc123", state.getEvents().get(0).getRosterVersion());
    }

    // ── name matching ────────────────────────────────────────────────────────

    @Test
    public void nameKeyFoldsEverySpellingOfTheSameRsn() {
        // The plugin submits "Beast_Owned", the database stores "Beast Owned",
        // and the game renders the space as U+00A0. All three are one player.
        String expected = "beast owned";
        assertEquals(expected, EventTeamIndicatorService.normalize("Beast Owned"));
        assertEquals(expected, EventTeamIndicatorService.normalize("Beast_Owned"));
        assertEquals(expected, EventTeamIndicatorService.normalize("Beast-Owned"));
        assertEquals(expected, EventTeamIndicatorService.normalize("Beast Owned"));
        assertEquals(expected, EventTeamIndicatorService.normalize("BEAST OWNED"));
    }

    @Test
    public void nameKeyIgnoresIconsAndColoursOnTheName() {
        // Icons and colours another plugin put on a name are not part of it.
        assertEquals("zezima", EventTeamIndicatorService.normalize("<img=25>Zezima"));
        assertEquals("zezima",
            EventTeamIndicatorService.normalize("<img=42><col=cc3333>Zezima</col>"));
    }

    @Test
    public void nameKeyCollapsesWhitespaceLikeTheServerDoes() {
        // normalize_player_display_equivalence collapses runs; two normalizers
        // that disagree by one space badge nobody and look right on both sides.
        assertEquals("beast owned", EventTeamIndicatorService.normalize("Beast__Owned"));
        assertEquals("beast owned", EventTeamIndicatorService.normalize("Beast -_ Owned"));
    }

    @Test
    public void nameKeyHandlesNullAndBlank() {
        assertEquals("", EventTeamIndicatorService.normalize(null));
        assertEquals("", EventTeamIndicatorService.normalize("   "));
    }

    // ── colors ───────────────────────────────────────────────────────────────

    @Test
    public void parsesHexColors() {
        assertEquals(new Color(0xdd2e44), EventTeamIndicatorService.colorOf("#dd2e44"));
        assertEquals(new Color(0xdd2e44), EventTeamIndicatorService.colorOf("DD2E44"));
    }

    @Test
    public void unusableColorsAreNull() {
        assertNull(EventTeamIndicatorService.colorOf(null));
        assertNull(EventTeamIndicatorService.colorOf(""));
        assertNull(EventTeamIndicatorService.colorOf("#fff"));
        assertNull(EventTeamIndicatorService.colorOf("rebeccapurple"));
    }

    // ── rendering the name ───────────────────────────────────────────────────

    private static final int SLOT = 42;

    private EventTeamIndicatorService.TeamBadge badge() {
        return new EventTeamIndicatorService.TeamBadge(
            101, "RR", new Color(0xdd2e44), new Color(0xcc3333));
    }

    @Test
    public void aSlotPrefixesTheName() {
        assertEquals("<img=42>Zezima", badge().render("Zezima", SLOT, false));
    }

    @Test
    public void colorsTheNameWhenAsked() {
        assertEquals("<img=42><col=cc3333>Zezima</col>", badge().render("Zezima", SLOT, true));
    }

    @Test
    public void theGameCanAlwaysStripTheBadgeBackOff() {
        // The chat scripts removetags() the drawn name to find the clan rank
        // icon and to target Report, Kick, Ban, Add friend and Message. The
        // tag used to be typed in as "[RR]", which survives that, so every one
        // of those looked up a player called "[RR]Zezima".
        for (int slot : new int[] {SLOT, -1}) {
            for (boolean colorName : new boolean[] {true, false}) {
                String drawn = badge().render("Zezima", slot, colorName);
                if (drawn != null) {
                    assertEquals("Zezima", Text.removeTags(drawn));
                }
            }
        }
    }

    @Test
    public void withoutASlotTheNameIsStillColoured() {
        assertEquals("<col=cc3333>Zezima</col>", badge().render("Zezima", -1, true));
    }

    @Test
    public void withoutASlotOrAColourTheNameIsLeftAlone() {
        assertNull(badge().render("Zezima", -1, false));
    }

    @Test
    public void anIconAlreadyOnTheNameSurvives() {
        // e.g. RuneLite's friends-chat rank icon, added by a subscriber that
        // ran before this one.
        assertEquals("<img=42><img=25>Zezima", badge().render("<img=25>Zezima", SLOT, false));
    }

    @Test
    public void aModeratorCrownStaysFirst() {
