package io.droptracker.service;

import org.junit.Test;

import java.util.Arrays;
import java.util.Collections;
import java.util.LinkedHashSet;
import java.util.Set;

import static org.junit.Assert.assertEquals;

/**
 * Tests {@link NearbyPlayerTracker#boundedRoster}, which keeps an accumulated
 * raid roster inside the party the raid can actually hold.
 *
 * <p>Plugin 6.0 started bracketing raid PBs by this roster, and the roster
 * accumulates across whatever the clear-on-entry lifecycle misses — ToB's state
 * varbit covers spectating as well as raiding — so Theatre of Blood times were
 * submitted as 6-, 7-, 8- and 9-player raids and the Hall of Fame grew boards
 * for team sizes the game cannot produce (suggestion #140). The same roster
 * decides who gets split credit, so the names matter as much as the count.
 */
public class NearbyPlayerTrackerRosterBoundTest {

    private static Set<String> setOf(String... names) {
        return new LinkedHashSet<>(Arrays.asList(names));
    }

    @Test
    public void capacityMatchesTheGamesOwnSlotCounts() {
        assertEquals(5, NearbyPlayerTracker.rosterCapacity(NearbyPlayerTracker.RAID_TOB));
        assertEquals(8, NearbyPlayerTracker.rosterCapacity(NearbyPlayerTracker.RAID_TOA));
        // Chambers of Xeric has no small ceiling — mass raids are legal.
        assertEquals(0, NearbyPlayerTracker.rosterCapacity(NearbyPlayerTracker.RAID_COX));
        assertEquals(0, NearbyPlayerTracker.rosterCapacity(null));
    }

    /** The regression: two runs' worth of names can no longer stack up. */
    @Test
    public void staleNamesNeverPushAToBRosterPastFive() {
        Set<String> thisRaid = setOf("Alpha", "Bravo", "Charlie");
        Set<String> lastRaid = setOf("Delta", "Echo", "Foxtrot", "Golf", "Hotel", "India");

        Set<String> bounded = NearbyPlayerTracker.boundedRoster(thisRaid, lastRaid, 5);

        assertEquals(5, bounded.size());
        assertEquals(setOf("Alpha", "Bravo", "Charlie", "Delta", "Echo"), bounded);
    }

    @Test
    public void liveReadWinsOverHistory() {
        // Every name the game is publishing right now survives; history only
        // fills what is left, so a contaminated roster self-heals as soon as
        // the next raid's party appears.
        Set<String> live = setOf("Alpha", "Bravo", "Charlie", "Delta", "Echo");
        Set<String> history = setOf("Stale1", "Stale2", "Stale3");

        assertEquals(live, NearbyPlayerTracker.boundedRoster(live, history, 5));
    }

    /**
     * Why history is kept at all (issue #43): the authoritative sources go
     * quiet before the loot chest opens, so a chest-time read is empty.
     */
    @Test
    public void historyStillCarriesTheRosterWhenTheLiveReadIsEmpty() {
        Set<String> history = setOf("Alpha", "Bravo", "Charlie", "Delta");

        Set<String> bounded = NearbyPlayerTracker.boundedRoster(
            Collections.<String>emptySet(), history, 5);

        assertEquals(history, bounded);
    }

    @Test
    public void toaKeepsItsEightSlots() {
        Set<String> live = setOf("A", "B", "C", "D", "E", "F", "G", "H");
        Set<String> history = setOf("Stale");

        Set<String> bounded = NearbyPlayerTracker.boundedRoster(live, history, 8);

        assertEquals(8, bounded.size());
        assertEquals(live, bounded);
    }

    @Test
    public void unboundedRaidsAreLeftAlone() {
        Set<String> live = setOf("A", "B", "C");
        Set<String> history = setOf("D", "E", "F", "G", "H", "I", "J", "K", "L");

        Set<String> bounded = NearbyPlayerTracker.boundedRoster(live, history, 0);

        assertEquals(12, bounded.size());
    }

    @Test
    public void duplicateNamesAcrossSourcesCountOnce() {
        Set<String> live = setOf("Alpha", "Bravo");
        Set<String> history = setOf("Bravo", "Charlie");

        assertEquals(setOf("Alpha", "Bravo", "Charlie"),
            NearbyPlayerTracker.boundedRoster(live, history, 5));
    }

    @Test
    public void emptySourcesGiveAnEmptyRoster() {
        assertEquals(Collections.<String>emptySet(),
            NearbyPlayerTracker.boundedRoster(
                Collections.<String>emptySet(), Collections.<String>emptySet(), 5));
    }
}

package io.droptracker.service;

import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Tests {@link NearbyPlayerTracker#isSoloRaid}, which decides what an empty
 * authoritative roster means. A solo raid empties the roster exactly the way a
 * broken capture does, and the old code read both as breakage and guessed from
 * proximity + the RuneLite party — so a solo raider's submission was credited
 * to whoever was still in their party from an earlier session.
 *
 * <p>A false positive here drops real participants from a genuine team raid; a
 * false negative re-opens the guessing that credited non-participants.
 */
public class NearbyPlayerTrackerSoloRaidTest {

    /** The regression: solo raid, party size 1 sampled throughout. */
    @Test
    public void soloRaidWithSampledPartySizeIsSolo() {
        assertTrue(NearbyPlayerTracker.isSoloRaid(0, true, 1, true, true));
        // Capture never worked, but the game still said the party was 1.
        assertTrue(NearbyPlayerTracker.isSoloRaid(0, true, 1, false, false));
    }

    @Test
    public void teamSizeSeenDuringTheRaidRulesOutSolo() {
        // Varbits have reset by loot-chest time; only the high-water mark knows.
        assertFalse(NearbyPlayerTracker.isSoloRaid(0, true, 3, false, false));
        assertFalse(NearbyPlayerTracker.isSoloRaid(0, true, 2, true, true));
    }

    @Test
    public void liveTeamSizeRulesOutSolo() {
        assertFalse(NearbyPlayerTracker.isSoloRaid(2, true, 0, true, true));
        assertFalse(NearbyPlayerTracker.isSoloRaid(5, false, 0, false, true));
    }

    /**
     * Team size never sampled (plugin enabled mid-raid): a live source that
     * returned the local player proves the capture works, so an empty roster
     * really is empty.
     */
    @Test
    public void workingCaptureWithNobodyElseIsSolo() {
        assertTrue(NearbyPlayerTracker.isSoloRaid(0, true, 0, true, false));
        assertTrue(NearbyPlayerTracker.isSoloRaid(0, true, 0, false, true));
        assertTrue(NearbyPlayerTracker.isSoloRaid(0, false, 0, false, true));
    }

    /** No evidence either way: keep guessing rather than drop real teammates. */
    @Test
    public void noEvidenceIsNotSolo() {
        assertFalse(NearbyPlayerTracker.isSoloRaid(0, true, 0, false, false));
        assertFalse(NearbyPlayerTracker.isSoloRaid(0, false, 0, false, false));
    }

    /** Retained state from a *different* raid must not settle this one. */
    @Test
    public void staleRosterFromAnotherRaidIsIgnored() {
        // teamSizeMax=1 and captureWorked belong to the previous raid.
        assertFalse(NearbyPlayerTracker.isSoloRaid(0, false, 1, true, false));
    }
}

package io.droptracker.service;

import io.droptracker.models.api.ModelStatus;
import org.junit.Test;

import static org.junit.Assert.assertEquals;

/**
 * Whether an outfit has to be exported and sent, given what the server says it
 * already holds.
 *
 * <p>Why this exists: the uploader used to remember one outfit, so a player
 * alternating between two re-sent one of them on every switch. The server
 * measured four in five uploads (of ~264k a day, 2026-09-14) as a model it
 * already had — each one a mesh export on the client thread and tens of
 * kilobytes off the player's connection, discarded on arrival. Asking first is
 * only worth it if the answers are read correctly, which is what this pins.
 */
public class PlayerModelDecisionTest {

    private static final long NOW = 1_000_000L;

    private static ModelStatus status(boolean accepted, boolean hasModel, boolean hasPet) {
        return new ModelStatus(accepted, hasModel, hasPet);
    }

    @Test
    public void anOutfitTheServerHoldsNeedsNothingSent() {
        assertEquals(PlayerModelService.Action.SETTLED,
                PlayerModelService.decide(status(true, true, false), false, NOW, 0));
    }

    @Test
    public void anOutfitTheServerLacksIsUploaded() {
        assertEquals(PlayerModelService.Action.UPLOAD,
                PlayerModelService.decide(status(true, false, false), false, NOW, 0));
    }

    @Test
    public void noAnswerFallsBackToSending() {
        // An older or unreachable server must leave the client behaving the way
        // it did before the check endpoint existed: send, and let the server
        // decide. Silence must never be read as "they have it".
        assertEquals(PlayerModelService.Action.UPLOAD,
                PlayerModelService.decide(null, false, NOW, 0));
    }

    @Test
    public void aPetOutIsSentWhenTheStoredOutfitHasNone() {
        // The fingerprint covers the character, not the follower, so an outfit
        // stored before the pet was out is held without one.
        assertEquals(PlayerModelService.Action.UPLOAD,
                PlayerModelService.decide(status(true, true, false), true, NOW, 0));
    }

    @Test
    public void aPetAlreadyStoredAlongsideTheOutfitNeedsNothing() {
        assertEquals(PlayerModelService.Action.SETTLED,
                PlayerModelService.decide(status(true, true, true), true, NOW, 0));
    }

    @Test
    public void anAccountTheServerDoesNotKnowIsNotWorthSendingTo() {
        // Identity comes from submissions; a model from an unknown account is
        // refused, so sending one is pure waste on both sides.
        assertEquals(PlayerModelService.Action.UNKNOWN_ACCOUNT,
                PlayerModelService.decide(status(false, false, false), false, NOW, 0));
    }

    @Test
    public void theUploadFloorHoldsAMissBack() {
        // Cycling through more outfits than the server keeps misses every time;
        // without a floor that is one export and upload per idle moment.
        assertEquals(PlayerModelService.Action.WAIT,
                PlayerModelService.decide(status(true, false, false), false, NOW, NOW + 1));
    }

    @Test
    public void theFloorNeverHoldsBackAnOutfitTheServerAlreadyHas() {
        // Being inside the window must not stop us recording what is worn —
        // that answer costs nothing and is how the profile follows a switch.
        assertEquals(PlayerModelService.Action.SETTLED,
                PlayerModelService.decide(status(true, true, false), false, NOW, NOW + 60_000));
    }

    @Test
    public void theFloorIsOpenOnceItsWindowHasPassed() {
        assertEquals(PlayerModelService.Action.UPLOAD,
                PlayerModelService.decide(status(true, false, false), false, NOW, NOW));
    }
}

package io.droptracker.service;

import io.droptracker.DropTrackerConfig;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.PlayerComposition;
import net.runelite.client.callback.ClientThread;
import org.junit.Test;

import java.lang.reflect.Proxy;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicReference;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * The manual "Send Player Model" path: its gating, and the outfit fingerprint
 * it shares with the automatic uploader.
 *
 * <p>The capture itself needs a live {@link net.runelite.api.Model} and is not
 * covered here; everything that decides whether a send is allowed to start is.
 */
public class PlayerModelServiceSendTest {

    /** A JDK-proxy stub answering only the listed methods; anything else returns a zero value. */
    @SuppressWarnings("unchecked")
    private static <T> T stub(Class<T> type, Map<String, Object> answers) {
        return (T) Proxy.newProxyInstance(type.getClassLoader(), new Class<?>[]{type},
                (proxy, method, args) -> {
                    if (answers.containsKey(method.getName())) {
                        return answers.get(method.getName());
                    }
                    Class<?> rt = method.getReturnType();
                    if (rt == boolean.class) return false;
                    if (rt == int.class) return 0;
                    if (rt == long.class) return 0L;
                    return null;
                });
    }

    private static DropTrackerConfig config(boolean useApi) {
        Map<String, Object> answers = new HashMap<>();
        answers.put("useApi", useApi);
        return stub(DropTrackerConfig.class, answers);
    }

    /** Runs the client-thread hop synchronously, like the real thing eventually does. */
    private static ClientThread immediateClientThread() {
        return new ClientThread() {
            @Override
            public void invoke(Runnable r) {
                r.run();
            }
        };
    }

    private static String await(PlayerModelService service) throws InterruptedException {
        CountDownLatch latch = new CountDownLatch(1);
        AtomicBoolean okOut = new AtomicBoolean();
        AtomicReference<String> messageOut = new AtomicReference<>();
        service.sendCurrentModel((ok, message) -> {
            okOut.set(ok);
            messageOut.set(message);
            latch.countDown();
        });
        assertTrue("callback never ran", latch.await(5, TimeUnit.SECONDS));
        assertFalse(okOut.get());
        return messageOut.get();
    }

    @Test
    public void withTheApiDisabledTheSendFailsBeforeTouchingTheClient() throws Exception {
        // Nulls everywhere the gate should never reach.
        PlayerModelService service = new PlayerModelService(null, null, config(false), null, null);

        String message = await(service);
        assertTrue(message, message.contains("API"));
    }

    @Test
    public void loggedOutFailsCleanlyAndReleasesTheGuardForTheNextTry() throws Exception {
        Map<String, Object> clientAnswers = new HashMap<>();
        clientAnswers.put("getGameState", GameState.LOGIN_SCREEN);
        Client client = stub(Client.class, clientAnswers);

        PlayerModelService service = new PlayerModelService(
                client, immediateClientThread(), config(true), null, null);

        String first = await(service);
        assertTrue(first, first.contains("Log in"));
        // A failed attempt must not leave the in-flight guard held.
        String second = await(service);
        assertEquals(first, second);
    }

    @Test
    public void whileACaptureIsInFlightASecondSendIsRefused() throws Exception {
        Map<String, Object> clientAnswers = new HashMap<>();
        clientAnswers.put("getGameState", GameState.LOGGED_IN);
        Client client = stub(Client.class, clientAnswers);

        // Holds the hop instead of running it, freezing the first send mid-capture.
        ClientThread parked = new ClientThread() {
            @Override
            public void invoke(Runnable r) {
                // never runs
            }
        };
        PlayerModelService service = new PlayerModelService(
                client, parked, config(true), null, null);

        service.sendCurrentModel((ok, message) -> {
        });
        String message = await(service);
        assertTrue(message, message.contains("Already sending"));
    }

    // ── the outfit fingerprint the pin is keyed by ──────────────────────────

    private static Player playerWith(int[] equipment, int[] colors, int gender) {
        Map<String, Object> compositionAnswers = new HashMap<>();
        compositionAnswers.put("getEquipmentIds", equipment);
        compositionAnswers.put("getColors", colors);
        compositionAnswers.put("getGender", gender);
        PlayerComposition composition = stub(PlayerComposition.class, compositionAnswers);

        Map<String, Object> playerAnswers = new HashMap<>();
        playerAnswers.put("getPlayerComposition", composition);
        return stub(Player.class, playerAnswers);
    }

    @Test
    public void fingerprintIsStableForTheSameOutfitAndChangesWithIt() {
        PlayerModelService service = new PlayerModelService(null, null, config(true), null, null);

        int[] outfit = {512, 1024, 2048};
        int[] colors = {1, 2, 3, 4, 5};
        String fingerprint = service.fingerprintOf(playerWith(outfit, colors, 0));
        assertNotNull(fingerprint);
        assertEquals(fingerprint, service.fingerprintOf(playerWith(outfit.clone(), colors.clone(), 0)));

        assertNotEquals(fingerprint, service.fingerprintOf(playerWith(new int[]{512, 1024, 4096}, colors, 0)));
        assertNotEquals(fingerprint, service.fingerprintOf(playerWith(outfit, colors, 1)));
    }

    // ── the fingerprint a personal best attaches ────────────────────────────

    @Test
    public void currentFingerprintIsTheLocalPlayersOutfitUnderTheUploadsOwnKey() {
        // A PB submission and the automatic upload must agree on the key, or
        // the leaderboard can never find the model for the time.
        Player local = playerWith(new int[]{512, 1024, 2048}, new int[]{1, 2, 3, 4, 5}, 0);
        Map<String, Object> clientAnswers = new HashMap<>();
        clientAnswers.put("getLocalPlayer", local);
        Client client = stub(Client.class, clientAnswers);
        PlayerModelService service = new PlayerModelService(client, null, config(true), null, null);

        assertEquals(service.fingerprintOf(local), service.currentFingerprint());
    }

    @Test
    public void currentFingerprintIsNullWithoutALocalPlayer() {
        Client client = stub(Client.class, new HashMap<>());
        PlayerModelService service = new PlayerModelService(client, null, config(true), null, null);

        assertNull(service.currentFingerprint());
    }
}

package io.droptracker.service;

import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * Tests the raid chest re-loot suppression: a player who opens the reward
 * chest in the loot room and later claims the same (unclaimed) loot from the
 * collection chest at the bank fires two identical loot events for one
 * completion — the second must be suppressed, but a NEW completion of the same
 * raid must always be accepted, even with an identical loot signature.
 */
public class RaidLootDeduplicatorTest {

    private static final long ACC = 4062539364958246995L;
    private static final String TOB_LOOT = "22446:1,565:500";

    private RaidLootDeduplicator dedup;

    @Before
    public void setUp() {
        // Client is only touched by the public wrappers; the testable core
        // takes the account hash explicitly.
        dedup = new RaidLootDeduplicator(null);
    }

    @Test
    public void firstChestOpenIsNotADuplicate() {
        assertFalse(dedup.isDuplicate(ACC, "Theatre of Blood", TOB_LOOT));
    }

    @Test
    public void reLootingTheSameBundleIsSuppressed() {
        assertFalse(dedup.isDuplicate(ACC, "Theatre of Blood", TOB_LOOT));
        assertTrue(dedup.isDuplicate(ACC, "Theatre of Blood", TOB_LOOT));
        // and it stays suppressed until the next completion
        assertTrue(dedup.isDuplicate(ACC, "Theatre of Blood", TOB_LOOT));
    }

    @Test
    public void nextCompletionReArmsEvenWithIdenticalLoot() {
        assertFalse(dedup.isDuplicate(ACC, "Theatre of Blood", TOB_LOOT));
        dedup.invalidate(ACC, "Theatre of Blood");
        assertFalse(dedup.isDuplicate(ACC, "Theatre of Blood", TOB_LOOT));
    }

    @Test
    public void completionMessageModeVariantReArmsTheBaseSource() {
        // Loot events carry the base raid name; the completion chat message
        // may carry a mode suffix. Both must fold to one dedup scope.
        assertFalse(dedup.isDuplicate(ACC, "Theatre of Blood", TOB_LOOT));
        dedup.invalidate(ACC, "Theatre of Blood: Hard Mode");
        assertFalse(dedup.isDuplicate(ACC, "Theatre of Blood", TOB_LOOT));
    }

    @Test
    public void differentBundleReplacesTheStoredSignature() {
        assertFalse(dedup.isDuplicate(ACC, "Theatre of Blood", TOB_LOOT));
        assertFalse(dedup.isDuplicate(ACC, "Theatre of Blood", "995:1000000"));
        // the older signature is no longer tracked
        assertFalse(dedup.isDuplicate(ACC, "Theatre of Blood", TOB_LOOT));
    }

    @Test
    public void raidsDoNotShareDedupScope() {
        assertFalse(dedup.isDuplicate(ACC, "Theatre of Blood", TOB_LOOT));
        assertFalse(dedup.isDuplicate(ACC, "Tombs of Amascut", TOB_LOOT));
        assertFalse(dedup.isDuplicate(ACC, "Chambers of Xeric", TOB_LOOT));
    }

    @Test
    public void accountsDoNotShareDedupScope() {
        assertFalse(dedup.isDuplicate(ACC, "Theatre of Blood", TOB_LOOT));
        assertFalse(dedup.isDuplicate(ACC + 1, "Theatre of Blood", TOB_LOOT));
    }

    @Test
    public void nonRaidSourcesAreNeverSuppressed() {
        assertFalse(dedup.isDuplicate(ACC, "Zulrah", TOB_LOOT));
        assertFalse(dedup.isDuplicate(ACC, "Zulrah", TOB_LOOT));
        assertFalse(dedup.isDuplicate(ACC, "Barrows", TOB_LOOT));
        assertFalse(dedup.isDuplicate(ACC, null, TOB_LOOT));
    }

    @Test
    public void raidFamilyFoldsModeVariants() {
        assertEquals("Theatre of Blood", RaidLootDeduplicator.raidFamily("Theatre of Blood"));
        assertEquals("Theatre of Blood", RaidLootDeduplicator.raidFamily("Theatre of Blood: Entry Mode"));
        assertEquals("Tombs of Amascut", RaidLootDeduplicator.raidFamily("Tombs of Amascut: Expert Mode"));
        assertEquals("Chambers of Xeric", RaidLootDeduplicator.raidFamily("Chambers of Xeric Challenge Mode"));
        assertEquals("Fractured Archive", RaidLootDeduplicator.raidFamily("Fractured Archive"));
        assertNull(RaidLootDeduplicator.raidFamily("Zulrah"));
        assertNull(RaidLootDeduplicator.raidFamily(null));
    }
}

package io.droptracker.service;

import java.util.Optional;

import io.droptracker.service.RecentCombatTracker.Engagement;
import io.droptracker.testing.RuneLiteStubs;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * Tests {@link RecentCombatTracker}, the memory that lets a death be attributed
 * after every live candidate has vanished.
 *
 * <p>The production failure this exists for: on the tick the local player dies,
 * the killer has usually already dropped its target (the game clears an NPC's
 * interaction when that target dies), so a scan of "who is attacking me right
 * now" finds nobody and the death is submitted with a blank source and a killer
 * type of "unknown".
 */
public class RecentCombatTrackerTest {

    private final RecentCombatTracker tracker = new RecentCombatTracker();

    /** The incident shape: the boss let go of us at the very tick we died. */
    @Test
    public void attackerIsStillBlamedAfterItDropsItsTargetOnTheDeathTick() {
        NPC vorkath = RuneLiteStubs.npc(1, 8061, "Vorkath", 732);

        tracker.recordAttackedBy(vorkath, 100);
        tracker.recordAttacking(vorkath, 100);
        // Death tick: the client tells us it stopped interacting with us, then
        // fires ActorDeath for the local player.
        tracker.endAttackedBy(vorkath, 118);

        Engagement killer = require(tracker.mostLikelyKiller(118, false));
        assertEquals("Vorkath", killer.getName());
        assertEquals(Integer.valueOf(8061), killer.getNpcId());
        assertEquals(732, killer.getCombatLevel());
        assertFalse(killer.isPlayer());
        assertTrue(killer.isNpc());
    }

    @Test
    public void engagementThatEndedLongAgoIsNotBlamed() {
        NPC goblin = RuneLiteStubs.npc(1, 100, "Goblin", 2);
        tracker.recordAttackedBy(goblin, 100);
        tracker.endAttackedBy(goblin, 100);

        assertTrue(tracker.mostLikelyKiller(100 + RecentCombatTracker.RECENT_WINDOW_TICKS, false).isPresent());
        assertFalse(tracker.mostLikelyKiller(100 + RecentCombatTracker.RECENT_WINDOW_TICKS + 1, false).isPresent());
    }

    /**
     * A boss that despawns with its instance never reports that it disengaged,
     * so the engagement stays open. It is still the right answer for a while —
     * but only a while, or a Gauntlet leftover gets blamed for a bank-stand
     * death minutes later.
     */
    @Test
    public void openEngagementIsTrustedLongerThanAFinishedOneButNotForever() {
        NPC hunllef = RuneLiteStubs.npc(1, 9035, "Crystalline Hunllef", 890);
        tracker.recordAttackedBy(hunllef, 100);

        int longAfterRecent = 100 + RecentCombatTracker.RECENT_WINDOW_TICKS + 5;
        assertTrue(tracker.mostLikelyKiller(longAfterRecent, false).isPresent());
        assertTrue(tracker.mostLikelyKiller(100 + RecentCombatTracker.OPEN_WINDOW_TICKS, false).isPresent());
        assertFalse(tracker.mostLikelyKiller(100 + RecentCombatTracker.OPEN_WINDOW_TICKS + 1, false).isPresent());
    }

    /**
     * The thing we were trading blows with is the answer people expect, even
     * when something bigger wandered in and aggroed us on the way down. The
     * distractor is deliberately the higher-level NPC so that only the
     * direction of the engagement can decide this.
     */
    @Test
    public void mutualCombatOutranksAHigherLevelBystanderThatMerelyAggroed() {
        NPC weFought = RuneLiteStubs.npc(1, 100, "Green dragon", 79);
        NPC aggroed = RuneLiteStubs.npc(2, 101, "Chaos Elemental", 305);

        tracker.recordAttacking(weFought, 100);
        tracker.recordAttackedBy(weFought, 100);
        tracker.recordAttackedBy(aggroed, 104);

        assertEquals("Green dragon", require(tracker.mostLikelyKiller(105, false)).getName());
    }

    /**
     * Something that attacked us beats something we merely clicked on and that
     * never fought back — again with the levels inverted so only the direction
     * can be doing the work.
     */
    @Test
    public void inboundAttackerOutranksAHigherLevelOutboundTarget() {
        NPC weClicked = RuneLiteStubs.npc(1, 8061, "Vorkath", 732);
        NPC itAttackedUs = RuneLiteStubs.npc(2, 101, "Skeletal Wyvern", 140);

        tracker.recordAttacking(weClicked, 100);
        tracker.recordAttackedBy(itAttackedUs, 100);

        assertEquals("Skeletal Wyvern", require(tracker.mostLikelyKiller(101, false)).getName());
    }

    /**
     * Something the client told us disengaged three ticks ago was still on us at
     * the death; something that walked off twenty seconds ago was not, and must
     * not outrank it just for being a bigger monster.
     */
    @Test
    public void anEngagementLiveAtTheDeathBeatsAStalerBiggerOne() {
        NPC oldBoss = RuneLiteStubs.npc(1, 8061, "Vorkath", 732);
        NPC current = RuneLiteStubs.npc(2, 100, "Green dragon", 79);

        tracker.recordAttackedBy(oldBoss, 100);
        tracker.endAttackedBy(oldBoss, 101);
        tracker.recordAttackedBy(current, 108);
        tracker.endAttackedBy(current, 110);

        assertEquals("Green dragon", require(tracker.mostLikelyKiller(111, false)).getName());
    }

    /** Pets follow us around all day; they are not killers. */
    @Test
    public void followersAreNotTracked() {
        NPC pet = RuneLiteStubs.npc(1, 13178, "Vorki", 0, false, true);
        tracker.recordAttackedBy(pet, 100);
        assertEquals(0, tracker.size());
        assertFalse(tracker.mostLikelyKiller(100, false).isPresent());
    }

    /** Talking to a banker is an interaction, not a fight. */
    @Test
    public void harmlessNpcsAreNotTracked() {
        NPC banker = RuneLiteStubs.npc(1, 1613, "Banker", 0, false, false);
        tracker.recordAttacking(banker, 100);
        assertEquals(0, tracker.size());
    }

    /**
     * Regression: the old handler only remembered targets with a combat level
     * above zero, which silently excluded every boss the game gives no level to.
     */
    @Test
    public void attackableNpcWithNoCombatLevelIsStillTracked() {
        NPC zalcano = RuneLiteStubs.npc(1, 9049, "Zalcano", 0, true, false);
        tracker.recordAttackedBy(zalcano, 100);
        assertEquals("Zalcano", require(tracker.mostLikelyKiller(101, false)).getName());
    }

    @Test
    public void playersAreOnlyBlamedWhereTheyCouldHaveKilledUs() {
        Player pker = RuneLiteStubs.player("Zezima", 126);
        tracker.recordAttackedBy(pker, 100);

        assertFalse(tracker.mostLikelyKiller(101, false).isPresent());

        Engagement killer = require(tracker.mostLikelyKiller(101, true));
        assertEquals("Zezima", killer.getName());
        assertTrue(killer.isPlayer());
        assertNull(killer.getNpcId());
    }

    /** Trading a clanmate in the wilderness must not make them the killer. */
    @Test
    public void friendsAreNeverBlamed() {
        Player friend = RuneLiteStubs.friendlyPlayer("Buddy", 126);
        tracker.recordAttacking(friend, 100);
        assertFalse(tracker.mostLikelyKiller(101, true).isPresent());
    }

    @Test
    public void anActorThatDiedFirstIsNotBlamed() {
        NPC dagannoth = RuneLiteStubs.npc(1, 100, "Dagannoth Rex", 303);
        tracker.recordAttacking(dagannoth, 100);
        tracker.recordAttackedBy(dagannoth, 100);

        RuneLiteStubs.state(dagannoth).put("isDead", true);
        assertFalse(tracker.mostLikelyKiller(101, false).isPresent());
    }

    @Test
    public void forgetDropsAnActorAndClearWipesEverything() {
        NPC first = RuneLiteStubs.npc(1, 100, "Goblin", 2);
        NPC second = RuneLiteStubs.npc(2, 101, "Imp", 2);
        tracker.recordAttackedBy(first, 100);
        tracker.recordAttackedBy(second, 100);

        tracker.forget(first);
        assertEquals(1, tracker.size());

        tracker.clear();
        assertEquals(0, tracker.size());
    }

    /**
     * The whole point of snapshotting: the attribution has to survive the actor
     * leaving the scene, so it cannot read anything off the actor at death time.
     */
    @Test
    public void attributionSurvivesTheActorLosingItsIdentity() {
        NPC boss = RuneLiteStubs.npc(1, 11751, "The Whisperer", 480);
        tracker.recordAttackedBy(boss, 100);

        // The instance is torn down: the NPC still exists as an object but no
        // longer reports a name or a composition.
        RuneLiteStubs.state(boss).put("getName", null);
        RuneLiteStubs.state(boss).put("getTransformedComposition", null);
        RuneLiteStubs.state(boss).put("getComposition", null);

        Engagement killer = require(tracker.mostLikelyKiller(101, false));
        assertEquals("The Whisperer", killer.getName());
        assertEquals(Integer.valueOf(11751), killer.getNpcId());
    }

    /** A relog or hop resets the tick counter; the old history means nothing. */
    @Test
    public void historyFromBeforeATickCounterResetIsDiscarded() {
        NPC goblin = RuneLiteStubs.npc(1, 100, "Goblin", 2);
        tracker.recordAttackedBy(goblin, 5_000);
        assertFalse(tracker.mostLikelyKiller(12, false).isPresent());
    }

    @Test
    public void switchingTargetClosesThePreviousOutboundEngagement() {
        NPC first = RuneLiteStubs.npc(1, 100, "Goblin", 2);
        NPC second = RuneLiteStubs.npc(2, 101, "Imp", 2);

        tracker.recordAttacking(first, 100);
        tracker.recordAttacking(second, 102);

        // The first is now a finished engagement and ages out on the short
        // window; the second is still open and does not.
        int afterRecentWindow = 102 + RecentCombatTracker.RECENT_WINDOW_TICKS + 1;
        assertEquals("Imp", require(tracker.mostLikelyKiller(afterRecentWindow, false)).getName());
    }

    @Test
    public void nameIsStrippedOfMarkupAndNonBreakingSpaces() {
        assertEquals("Dark wizard", RecentCombatTracker.cleanName("<col=ff0000>Dark wizard</col>"));
        assertEquals("Elite Black Knight", RecentCombatTracker.cleanName("Elite Black Knight"));
        assertNull(RecentCombatTracker.cleanName("<col=ff0000></col>"));
        assertNull(RecentCombatTracker.cleanName("   "));
        assertNull(RecentCombatTracker.cleanName(null));
    }

    /** A player with no readable name cannot be named as a killer. */
    @Test
    public void namelessPlayersAreNotTracked() {
        Player nameless = RuneLiteStubs.player(null, 100);
        tracker.recordAttackedBy(nameless, 100);
        assertEquals(0, tracker.size());
    }

    private static Engagement require(Optional<Engagement> engagement) {
        assertTrue("expected a killer to be attributed", engagement.isPresent());
        return engagement.get();
    }
}

package io.droptracker.service;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

import java.awt.Image;
import java.awt.image.BufferedImage;
import java.util.HashMap;
import java.util.Map;
import java.util.function.Consumer;

import io.droptracker.models.PrivacyMode;
import io.droptracker.service.ScreenshotPrivacyService.CapturePlan;
import io.droptracker.testing.RuneLiteStubs;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.ui.DrawManager;
import org.junit.Before;
import org.junit.Test;

/**
 * Covers the capture coordination that keeps a player's privacy mode honest.
 *
 * <p>The bug these exist for: a Broken dragon hook is both a screenshot-worthy
 * drop and a collection log unlock, so two submissions asked for proof of the
 * same kill. Each hid the private chat, captured, then unhid it — and the first
 * one's unhide landed while the second was still waiting for its frame, so the
 * second screenshot went out with the DMs in it.
 */
public class ScreenshotPrivacyServiceTest {

    /** Split private chat on: the PM overlay interface is loaded. */
    private static final boolean SPLIT_CHAT_ON = true;

    private Client client;
    private CountingDrawManager drawManager;
    private ScreenshotPrivacyService service;

    private final Map<Integer, Widget> widgets = new HashMap<>();
    private int tick;

    /** What the chat looked like in the frame the client last handed over. */
    private boolean pmChatHiddenInFrame;
    private boolean transcriptHiddenInFrame;

    @Before
    public void setUp() {
        widgets.clear();
        tick = 0;

        client = RuneLiteStubs.stub(Client.class, "client");
        Map<String, Object> state = RuneLiteStubs.state(client);
        state.put("isResized", true);
        state.put("getGameState", GameState.LOGGED_IN);
        state.put("getTickCount", (RuneLiteStubs.Answer) args -> tick);
        state.put("getWidget", (RuneLiteStubs.Answer) args -> args.length == 1
            ? widgets.get((Integer) args[0])
            : null);

        drawManager = new CountingDrawManager();
        service = new ScreenshotPrivacyService(client, new InlineClientThread(), drawManager, null);
    }

    // --- the reported leak -------------------------------------------------

    @Test
    public void twoSubmissionsFromOneKillShareOneCapture() {
        givenChat(SPLIT_CHAT_ON);

        Capture drop = capture(PrivacyMode.HIDE_DMS);
        Capture clog = capture(PrivacyMode.HIDE_DMS);

        service.onBeforeRender();
        BufferedImage frame = renderFrame();

        assertEquals("one capture request for both submissions", 1, drawManager.requests);
        assertSame(frame, drop.image);
        assertSame(frame, clog.image);
        assertTrue("private chat was hidden in the captured frame", pmChatHiddenInFrame);
    }

    @Test
    public void aSubmissionArrivingJustAfterACaptureReusesIt() {
        givenChat(SPLIT_CHAT_ON);

        Capture drop = capture(PrivacyMode.HIDE_DMS);
        service.onBeforeRender();
        BufferedImage frame = renderFrame();

        Capture clog = capture(PrivacyMode.HIDE_DMS);

        assertEquals("no second capture requested", 1, drawManager.requests);
        assertSame(frame, drop.image);
        assertSame("collection log rode the drop's frame", frame, clog.image);
    }

    @Test
    public void theWholeCycleLeavesTheChatAsItFoundIt() {
        givenChat(SPLIT_CHAT_ON);
        Widget pmChat = widgets.get(InterfaceID.PmChat.CONTAINER);

        capture(PrivacyMode.HIDE_DMS);
        service.onBeforeRender();
        renderFrame();

        assertFalse("private chat put back after the capture", pmChat.isSelfHidden());
    }

    @Test
    public void aWidgetTheGameHadHiddenIsNotRevealed() {
        givenChat(SPLIT_CHAT_ON);
        Widget transcript = widgets.get(InterfaceID.Chatbox.CHATDISPLAY);
        transcript.setHidden(true);

        capture(PrivacyMode.HIDE_MESSAGES_AND_DMS);
        service.onBeforeRender();
        renderFrame();

        assertTrue("a transcript the game hid stays hidden", transcript.isSelfHidden());
    }

    // --- privacy correctness -----------------------------------------------

    @Test
    public void withSplitChatOffHidingDmsHidesTheTranscriptTheyLiveIn() {
        givenChat(!SPLIT_CHAT_ON);
        Widget transcript = widgets.get(InterfaceID.Chatbox.CHATDISPLAY);

        Capture shot = capture(PrivacyMode.HIDE_DMS);
        service.onBeforeRender();
        renderFrame();

        assertTrue("DMs are transcript lines with split chat off", transcriptHiddenInFrame);
        assertFalse("and the transcript comes back", transcript.isSelfHidden());
    }

    @Test
    public void aStricterRequestDoesNotRideALooserFrame() {
        givenChat(SPLIT_CHAT_ON);

        Capture openShot = capture(PrivacyMode.NONE);
        Capture privateShot = capture(PrivacyMode.HIDE_DMS);

        service.onBeforeRender();
        BufferedImage first = renderFrame();

        assertFalse("nothing hidden for the None-mode shot", pmChatHiddenInFrame);
        assertSame(first, openShot.image);
        assertNull("the DM-hiding request did not take the unhidden frame", privateShot.image);

        service.onBeforeRender();
        BufferedImage second = renderFrame();

        assertEquals(2, drawManager.requests);
        assertSame(second, privateShot.image);
        assertTrue("its own frame hid the private chat", pmChatHiddenInFrame);
    }

    @Test
    public void hidingTheWholeChatboxInResizableModeIsAPlainHide() {
        givenChat(SPLIT_CHAT_ON);
        Widget universe = widgets.get(InterfaceID.Chatbox.UNIVERSE);

        capture(PrivacyMode.HIDE_CHATBOX);
        service.onBeforeRender();

        assertTrue("chatbox hidden for the shot", universe.isSelfHidden());

        renderFrame();

        assertFalse("and restored afterwards", universe.isSelfHidden());
    }

    // --- never leave a submission hanging ----------------------------------

    @Test
    public void aCaptureThatNeverRendersGivesUpRatherThanBlockingForever() {
        givenChat(SPLIT_CHAT_ON);
        Widget pmChat = widgets.get(InterfaceID.PmChat.CONTAINER);

        Capture shot = capture(PrivacyMode.HIDE_DMS);
        service.onBeforeRender();

        // Frames stop arriving (minimised client, GPU stall); ticks keep coming.
        // One retry, then the submission is answered with no image at all.
        tick += 50;
        service.onGameTick();
        assertNull(shot.image);

        tick += 50;
        service.onGameTick();

        assertTrue("consumer was called", shot.delivered);
        assertNull("with no image rather than an unhidden one", shot.image);
        assertFalse("and the chat was put back", pmChat.isSelfHidden());
    }

    // --- plan coverage ------------------------------------------------------

    @Test
    public void aPlanCoversAnythingItHidesAtLeastAsMuchOf() {
        CapturePlan dmsOnly = new CapturePlan(true, false, false, false);
        CapturePlan dmsAndTranscript = new CapturePlan(true, true, false, false);
        CapturePlan wholeChatbox = new CapturePlan(true, false, true, false);

        assertTrue(dmsOnly.covers(CapturePlan.NOTHING));
        assertTrue(dmsAndTranscript.covers(dmsOnly));
        assertFalse(dmsOnly.covers(dmsAndTranscript));

        assertTrue("hiding the chatbox hides the transcript in it", wholeChatbox.transcript);
        assertTrue(wholeChatbox.covers(dmsAndTranscript));
        assertFalse(dmsAndTranscript.covers(wholeChatbox));
    }

    // --- harness ------------------------------------------------------------

    /**
     * @param splitChat whether the split private chat overlay exists; with the
     *                  option off the client never loads that interface
     */
    private void givenChat(boolean splitChat) {
        if (splitChat) {
            widgets.put(InterfaceID.PmChat.CONTAINER, widget());
        }
        widgets.put(InterfaceID.Chatbox.CHATDISPLAY, widget());
        widgets.put(InterfaceID.Chatbox.UNIVERSE, widget());
    }

    private Capture capture(PrivacyMode mode) {
        Capture capture = new Capture();
        service.capture(mode, capture);
        return capture;
    }

    /**
     * Draws a frame and hands it to whoever asked for one, as the client does.
     * The chat's state is read as the frame is produced, since that is what the
     * pixels would show - the service unhides again as soon as it has the image.
     */
    private BufferedImage renderFrame() {
        BufferedImage frame = new BufferedImage(4, 4, BufferedImage.TYPE_INT_ARGB);
        drawManager.processDrawComplete(() -> {
            pmChatHiddenInFrame = isHidden(InterfaceID.PmChat.CONTAINER);
            transcriptHiddenInFrame = isHidden(InterfaceID.Chatbox.CHATDISPLAY);
            return frame;
        });
        return frame;
    }

    private boolean isHidden(int componentId) {
        Widget widget = widgets.get(componentId);
        return widget != null && widget.isSelfHidden();
    }

    /** A widget stub whose hidden flag actually changes when it is set. */
    private static Widget widget() {
        Widget widget = RuneLiteStubs.stub(Widget.class, "widget");
        Map<String, Object> state = RuneLiteStubs.state(widget);
        state.put("isSelfHidden", false);
        state.put("isHidden", false);
        state.put("setHidden", (RuneLiteStubs.Answer) args -> {
            state.put("isSelfHidden", args[0]);
            state.put("isHidden", args[0]);
            return null;
        });
        return widget;
    }

    /** Records what the consumer was given. */
    private static final class Capture implements Consumer<BufferedImage> {

        private BufferedImage image;
        private boolean delivered;

        @Override
        public void accept(BufferedImage image) {
            this.image = image;
            this.delivered = true;
        }
    }

    /** The real queue-and-drain behaviour, plus a count of how often it was asked. */
    private static final class CountingDrawManager extends DrawManager {

        private int requests;

        @Override
        public void requestNextFrameListener(Consumer<Image> consumer) {
            requests++;
            super.requestNextFrameListener(consumer);
        }
    }

    /** Runs client-thread work inline, as it would when already on that thread. */
    private static final class InlineClientThread extends ClientThread {

        @Override
        public void invoke(Runnable runnable) {
            runnable.run();
        }

        @Override
        public void invokeLater(Runnable runnable) {
            runnable.run();
        }
    }
}

package io.droptracker.service;

import io.droptracker.models.CustomWebhookBody;
import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The chokepoint every submission passes through. Handlers already skip events
 * they cannot name; this is what stops a future path from quietly reintroducing
 * an unattributable submission.
 */
public class SubmissionIdentityGuardTest {

    private static CustomWebhookBody webhookWithName(String... playerNames) {
        CustomWebhookBody webhook = new CustomWebhookBody();
        for (String playerName : playerNames) {
            CustomWebhookBody.Embed embed = new CustomWebhookBody.Embed();
            embed.addField("type", "drop", true);
            embed.addField("player_name", playerName, true);
            embed.addField("acc_hash", "1234567890123456", true);
            webhook.getEmbeds().add(embed);
        }
        return webhook;
    }

    @Test
    public void passesAnIdentifiedSubmission() {
        assertFalse(SubmissionManager.hasUnidentifiedEmbed(webhookWithName("Wimi")));
    }

    @Test
    public void rejectsABlankName() {
        assertTrue(SubmissionManager.hasUnidentifiedEmbed(webhookWithName("")));
        assertTrue(SubmissionManager.hasUnidentifiedEmbed(webhookWithName("   ")));
        assertTrue(SubmissionManager.hasUnidentifiedEmbed(webhookWithName((String) null)));
    }

    // A drop is one embed per item: one nameless embed condemns the payload,
    // since they all describe the same event.
    @Test
    public void rejectsAPayloadWhereOnlyOneEmbedIsNameless() {
        assertTrue(SubmissionManager.hasUnidentifiedEmbed(webhookWithName("Wimi", "", "Wimi")));
    }

    // The adventure log names its identity field "player", not "player_name" —
    // it must not be caught by a guard aimed at a field it does not carry.
    @Test
    public void ignoresEmbedsWithoutAPlayerNameField() {
        CustomWebhookBody webhook = new CustomWebhookBody();
        CustomWebhookBody.Embed embed = new CustomWebhookBody.Embed();
        embed.addField("type", "adventure_log", true);
        embed.addField("player", "Wimi", true);
        webhook.getEmbeds().add(embed);
        assertFalse(SubmissionManager.hasUnidentifiedEmbed(webhook));
    }

    @Test
    public void toleratesEmptyAndNullPayloads() {
        assertFalse(SubmissionManager.hasUnidentifiedEmbed(null));
        assertFalse(SubmissionManager.hasUnidentifiedEmbed(new CustomWebhookBody()));
    }
}

package io.droptracker.testing;

import java.lang.reflect.InvocationHandler;
import java.lang.reflect.Method;
import java.lang.reflect.Proxy;
import java.util.ArrayList;
import java.util.EnumSet;
import java.util.HashMap;
import java.util.Iterator;
import java.util.List;
import java.util.Map;

import net.runelite.api.Client;
import net.runelite.api.IndexedObjectSet;
import net.runelite.api.NPC;
import net.runelite.api.NPCComposition;
import net.runelite.api.Player;
import net.runelite.api.WorldType;
import net.runelite.api.WorldView;
import net.runelite.api.widgets.Widget;

/**
 * JDK dynamic-proxy stand-ins for the RuneLite API interfaces.
 *
 * <p>The plugin has no mocking framework on the test classpath (JUnit 4 only),
 * so handler tests build their client, actors and world view out of proxies that
 * return type-appropriate defaults, with per-method overrides supplied through a
 * mutable map. Mutability matters here: killer attribution turns on an actor's
 * interaction changing between one tick and the next, which is exactly what a
 * fixed stub cannot express.
 */
public final class RuneLiteStubs {

    private RuneLiteStubs() {
    }

    /**
     * An override whose result depends on the call's arguments: a varp read
     * keyed by id, a cache table lookup keyed by row. Put one in a stub's
     * {@link #state} map under the method name.
     */
    @FunctionalInterface
    public interface Answer {
        Object answer(Object[] args);
    }

    /**
     * @return the mutable override map backing a stub, keyed by method name
     */
    public static Map<String, Object> state(Object stub) {
        return ((Handler) Proxy.getInvocationHandler(stub)).values;
    }

    public static <T> T stub(Class<T> type, String label) {
        Object proxy = Proxy.newProxyInstance(
                RuneLiteStubs.class.getClassLoader(), new Class<?>[] { type }, new Handler(label));
        return type.cast(proxy);
    }

    // --- actors ---------------------------------------------------------

    public static NPCComposition composition(int id, String name, int combatLevel, boolean attackable,
            boolean follower) {
        NPCComposition composition = stub(NPCComposition.class, "composition:" + name);
        Map<String, Object> state = state(composition);
        state.put("getId", id);
        state.put("getName", name);
        state.put("getCombatLevel", combatLevel);
        state.put("getActions", attackable ? new String[] { "Attack" } : new String[] { "Talk-to" });
        state.put("isFollower", follower);
        state.put("isInteractible", true);
        state.put("isMinimapVisible", true);
        state.put("getSize", 1);
        return composition;
    }

    /** An attackable NPC of the given combat level. */
    public static NPC npc(int index, int id, String name, int combatLevel) {
        return npc(index, id, name, combatLevel, true, false);
    }

    public static NPC npc(int index, int id, String name, int combatLevel, boolean attackable, boolean follower) {
        NPC npc = stub(NPC.class, "npc:" + name);
        Map<String, Object> state = state(npc);
        state.put("getIndex", index);
        state.put("getId", id);
        state.put("getName", name);
        state.put("getCombatLevel", combatLevel);
        NPCComposition composition = composition(id, name, combatLevel, attackable, follower);
        state.put("getComposition", composition);
        state.put("getTransformedComposition", composition);
        return npc;
    }

    public static Player player(String name, int combatLevel) {
        Player player = stub(Player.class, "player:" + name);
        Map<String, Object> state = state(player);
        state.put("getName", name);
        state.put("getCombatLevel", combatLevel);
        return player;
    }

    /** A player the local account is friends with (a bystander, not a killer). */
    public static Player friendlyPlayer(String name, int combatLevel) {
        Player player = player(name, combatLevel);
        state(player).put("isFriend", true);
        return player;
    }

    // --- world ----------------------------------------------------------

    public static WorldView worldView(List<? extends Player> players, List<? extends NPC> npcs) {
        WorldView worldView = stub(WorldView.class, "worldView");
        Map<String, Object> state = state(worldView);
        state.put("players", objectSet(players));
        state.put("npcs", objectSet(npcs));
        state.put("isInstance", false);
        return worldView;
    }

    public static <T> IndexedObjectSet<T> objectSet(List<T> items) {
        List<T> copy = new ArrayList<>(items);
        return new IndexedObjectSet<T>() {
            @Override
            public T byIndex(int index) {
                return copy.get(index);
            }

            @Override
            public Iterator<T> iterator() {
                return copy.iterator();
            }
        };
    }

    /** A widget that is present and visible — e.g. the PvP safe-zone indicator. */
    public static Widget visibleWidget() {
        Widget widget = stub(Widget.class, "widget");
        state(widget).put("isHidden", false);
        return widget;
    }

    /**
     * A client whose non-primitive returns are safe to call: an empty world type
     * set and an empty world view, both overridable per test.
     */
    public static Client client(Player localPlayer) {
        Client client = stub(Client.class, "client");
        Map<String, Object> state = state(client);
        state.put("getLocalPlayer", localPlayer);
        state.put("getWorldType", EnumSet.noneOf(WorldType.class));
        state.put("getTickCount", 0);
        WorldView worldView = worldView(new ArrayList<>(), new ArrayList<>());
        state.put("getTopLevelWorldView", worldView);
        if (localPlayer != null) {
            state(localPlayer).put("getWorldView", worldView);
        }
        return client;
    }

    /** Replaces the world view seen by both the client and the local player. */
    public static void setScene(Client client, Player localPlayer, List<? extends Player> players,
            List<? extends NPC> npcs) {
        WorldView worldView = worldView(players, npcs);
        state(client).put("getTopLevelWorldView", worldView);
        if (localPlayer != null) {
            state(localPlayer).put("getWorldView", worldView);
        }
    }

    private static final class Handler implements InvocationHandler {

        private final Map<String, Object> values = new HashMap<>();
        private final String label;

        private Handler(String label) {
            this.label = label;
        }

        @Override
        public Object invoke(Object proxy, Method method, Object[] args) {
            String name = method.getName();
            switch (name) {
                case "equals":
                    return proxy == args[0];
                case "hashCode":
                    return System.identityHashCode(proxy);
                case "toString":
                    return label;
                default:
                    break;
            }
            if (values.containsKey(name)) {
                Object value = values.get(name);
                if (value instanceof Answer) {
                    return ((Answer) value).answer(args == null ? new Object[0] : args);
                }
                return value;
            }
            return defaultValue(method.getReturnType());
        }

        private static Object defaultValue(Class<?> type) {
            if (!type.isPrimitive() || type == void.class) {
                return null;
            }
            if (type == boolean.class) {
                return Boolean.FALSE;
            }
            if (type == long.class) {
                return 0L;
            }
            if (type == double.class) {
                return 0d;
            }
            if (type == float.class) {
                return 0f;
            }
            if (type == char.class) {
                return (char) 0;
            }
            if (type == byte.class) {
                return (byte) 0;
            }
            if (type == short.class) {
                return (short) 0;
            }
            return 0;
        }
    }
}

package io.droptracker.ui;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.List;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import java.util.stream.Stream;

import org.junit.Test;

import static org.junit.Assert.assertTrue;

/**
 * Fails when panel code renders a character RuneLite's fonts cannot draw.
 * <p>
 * {@code FontManager}'s three fonts map ~247 codepoints and stop at U+2122.
 * They only ever displayed symbols above that by falling back to a system
 * font, and that fallback chain does not cover them on macOS — where the
 * panel showed missing-glyph boxes instead (reported 2026-08). Rather than
 * depend on a per-platform fallback we cannot test from CI, panel text stays
 * inside the fonts' own coverage and shapes are painted (see PanelIcons).
 * <p>
 * If this fails: paint the shape in {@code PanelIcons} instead of typing the
 * character, or pick one of the {@link #IN_FONT_EXTRAS} below.
 */
public class PanelGlyphCoverageTest {

    /**
     * Non-Latin-1 characters verified present in runescape.ttf,
     * runescape_small.ttf and runescape_bold.ttf.
     */
    private static final Set<Character> IN_FONT_EXTRAS = Set.of(
        '…', // …  horizontal ellipsis
        '—', // —  em dash
        '€', // €  euro sign
        '™'  // ™  trade mark
    );

    /** Matches a Java string literal, honouring escapes. */
    private static final Pattern STRING_LITERAL = Pattern.compile("\"((?:[^\"\\\\]|\\\\.)*)\"");
    private static final Pattern BLOCK_COMMENT = Pattern.compile("/\\*.*?\\*/", Pattern.DOTALL);
    private static final Pattern LINE_COMMENT = Pattern.compile("//[^\n]*");

    @Test
    public void panelStringsStayInsideTheBundledFontsCoverage() throws IOException {
        Path uiRoot = Paths.get("src/main/java/io/droptracker/ui");
        assertTrue("expected the UI sources at " + uiRoot.toAbsolutePath()
            + " — run this from the project root", Files.isDirectory(uiRoot));

        List<String> offenders = new ArrayList<>();
        try (Stream<Path> files = Files.walk(uiRoot)) {
            for (Path file : (Iterable<Path>) files.filter(p -> p.toString().endsWith(".java"))::iterator) {
                collectOffenders(file, offenders);
            }
        }

        assertTrue("panel text uses characters RuneLite's fonts cannot render "
            + "(they tofu on macOS) — paint them via PanelIcons instead:\n  "
            + String.join("\n  ", offenders), offenders.isEmpty());
    }

    private static void collectOffenders(Path file, List<String> offenders) throws IOException {
        // Comments are not rendered, so strip them before looking at literals.
        String source = new String(Files.readAllBytes(file), StandardCharsets.UTF_8);
        source = BLOCK_COMMENT.matcher(source).replaceAll("");
        source = LINE_COMMENT.matcher(source).replaceAll("");

        Matcher literal = STRING_LITERAL.matcher(source);
        while (literal.find()) {
            String value = literal.group(1);
            for (int i = 0; i < value.length(); i++) {
                char c = value.charAt(i);
                if (c < 0x100 || IN_FONT_EXTRAS.contains(c)) {
                    continue;
                }
                offenders.add(String.format("%s: U+%04X '%c' in \"%s\"",
                    file.getFileName(), (int) c, c, value));
            }
        }
    }
}

package io.droptracker.ui.admin;

import java.awt.*;
import java.util.*;
import java.util.List;

import javax.swing.*;

import com.google.gson.*;
import org.junit.Test;

import io.droptracker.models.api.GroupAdmin;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * The manager's form logic: which rows count as changed, what Save sends, and
 * the code boxes. Rendering is checked by eye; these pin the behaviour.
 */
public class GroupAdminUiTest {

    private static final Gson GSON = new Gson();

    private static final String SETTINGS = "{\"categories\":[{\"key\":\"drops\",\"label\":\"Drops\"}],"
        + "\"channels\":[{\"value\":\"1001\",\"label\":\"drops\"}],"
        + "\"fields\":["
        + "{\"key\":\"min\",\"label\":\"Minimum\",\"category\":\"drops\",\"type\":\"int\",\"value\":\"2500000\",\"min\":0},"
        + "{\"key\":\"img\",\"label\":\"Screenshots\",\"category\":\"drops\",\"type\":\"boolean\",\"value\":\"0\"},"
        + "{\"key\":\"chan\",\"label\":\"Channel\",\"category\":\"drops\",\"type\":\"channel\",\"value\":\"999\"},"
        + "{\"key\":\"list\",\"label\":\"Bosses\",\"category\":\"drops\",\"type\":\"bosslist\",\"value\":\"[1,2]\"},"
        + "{\"key\":\"other\",\"label\":\"Elsewhere\",\"category\":\"pvp\",\"type\":\"boolean\",\"value\":\"1\"}]}";

    private static SettingsForm form(int[] dirtyCalls) {
        GroupAdmin.Settings settings = GSON.fromJson(SETTINGS, GroupAdmin.Settings.class);
        return new SettingsForm(settings, settings.getCategories().get(0), () -> dirtyCalls[0]++, () -> {
        });
    }

    @Test
    public void aFreshFormHasNoChanges() {
        SettingsForm form = form(new int[1]);
        assertEquals(0, form.dirtyCount());
        assertTrue(form.changes().isEmpty());
        assertTrue(form.valid());
    }

    @Test
    public void onlyThisCategorysFieldsAreDrawn() {
        SettingsForm form = form(new int[1]);
        assertEquals(1, all(form, ToggleSwitch.class).size());
    }

    @Test
    public void groupedNumbersAreNotAChange() {
        // "2500000" shows as "2,500,000"; that alone must not light up Save.
        SettingsForm form = form(new int[1]);
        assertEquals("2,500,000", all(form, JTextField.class).get(0).getText());
        assertEquals(0, form.dirtyCount());
    }

    @Test
    public void changesCarryOnlyEditedKeysWithTypedValues() {
        int[] calls = new int[1];
        SettingsForm form = form(calls);
        all(form, JTextField.class).get(0).setText("10,000,000");
        flip(all(form, ToggleSwitch.class).get(0));

        Map<String, Object> changes = form.changes();
        assertEquals(new LinkedHashSet<>(Arrays.asList("min", "img")), changes.keySet());
        assertEquals(new JsonPrimitive(10_000_000L), changes.get("min"));
        assertEquals(new JsonPrimitive(true), changes.get("img"));
        assertEquals(2, form.dirtyCount());
        assertTrue(calls[0] > 0);
    }

    @Test
    public void undoingAnEditClearsIt() {
        SettingsForm form = form(new int[1]);
        JTextField min = all(form, JTextField.class).get(0);
        min.setText("1");
        min.setText("2,500,000");
        assertEquals(0, form.dirtyCount());
    }

    @Test
    public void anOutOfRangeNumberBlocksSave() {
        SettingsForm form = form(new int[1]);
        all(form, JTextField.class).get(0).setText("-5");
        assertFalse(form.valid());
        all(form, JTextField.class).get(0).setText("");
        assertTrue(form.valid());
        assertEquals(JsonNull.INSTANCE, form.changes().get("min") == null ? JsonNull.INSTANCE : form.changes().get("min"));
    }

    @Test
    public void aChannelTheBotCantSeeIsKeptNotCleared() {
        SettingsForm form = form(new int[1]);
        JComboBox<?> box = all(form, JComboBox.class).get(0);
        GroupAdmin.Choice selected = (GroupAdmin.Choice) box.getSelectedItem();
        assertEquals("999", selected.getValue());
        assertEquals(0, form.dirtyCount());
    }

    @Test
    public void unknownTypesAreReadOnly() {
        SettingsForm form = form(new int[1]);
        boolean link = false;
        for (JButton b : all(form, JButton.class)) {
            link |= "Edit on website".equals(b.getText());
        }
        assertTrue(link);
        assertFalse(form.changes().containsKey("list"));
    }

    @Test
    public void serverErrorsLandOnTheirRow() {
        SettingsForm form = form(new int[1]);
        form.showErrors(Collections.singletonMap("img", "Needs a drops channel first."));
        boolean shown = false;
        for (JLabel l : all(form, JLabel.class)) {
            shown |= "Needs a drops channel first.".equals(l.getText()) && l.isVisible();
        }
        assertTrue(shown);
    }

    @Test
    public void numberRules() {
        GroupAdmin.Field field = GSON.fromJson("{\"min\":0,\"max\":100}", GroupAdmin.Field.class);
        assertNull(SettingsForm.intIssue(new JsonPrimitive(50L), field));
        assertEquals("Must be at least 0.", SettingsForm.intIssue(new JsonPrimitive(-1L), field));
        assertEquals("Must be at most 100.", SettingsForm.intIssue(new JsonPrimitive(101L), field));
        assertEquals("Numbers only.", SettingsForm.intIssue(new JsonPrimitive("abc"), field));
        assertNull(SettingsForm.intIssue(JsonNull.INSTANCE, field));
    }

    @Test
    public void legacyBooleansRead() {
        assertTrue(SettingsForm.asBoolean(new JsonPrimitive("1")));
        assertTrue(SettingsForm.asBoolean(new JsonPrimitive(true)));
        assertFalse(SettingsForm.asBoolean(new JsonPrimitive("0")));
        assertFalse(SettingsForm.asBoolean(null));
    }

    @Test
    public void codeBoxesAssembleTheCode() throws Exception {
        CodeEntryPanel panel = new CodeEntryPanel(() -> {
        }, () -> {
        });
        assertNull(panel.code());
        panel.fill("123456789", 0);
        assertEquals("123-456-789", panel.code());
    }

    @Test
    public void aPastedCodeFillsEveryBox() throws Exception {
        CodeEntryPanel panel = new CodeEntryPanel(() -> {
        }, () -> {
        });
        all(panel, JTextField.class).get(0).setText("123-456-789");
        SwingUtilities.invokeAndWait(() -> {
        });
        assertEquals("123-456-789", panel.code());
    }

    @Test
    public void lettersNeverGetIn() {
        CodeEntryPanel panel = new CodeEntryPanel(() -> {
        }, () -> {
        });
        JTextField first = all(panel, JTextField.class).get(0);
        first.setText("1a2");
        assertEquals("12", first.getText());
    }

    @Test
    public void headerLine() {
        GroupAdmin.Group g = GSON.fromJson("{\"role\":\"owner\",\"member_count\":1,\"tier\":\"Supporter\"}",
            GroupAdmin.Group.class);
        assertEquals("Owner  ·  1 member  ·  Supporter", GroupAdminWindow.meta(g));
        assertEquals("1,204 members", GroupAdminWindow.plural(1204, "member"));
    }

    private static void flip(ToggleSwitch toggle) {
        // A real click (key events would be re-routed to the focus owner).
        toggle.dispatchEvent(new java.awt.event.MouseEvent(toggle, java.awt.event.MouseEvent.MOUSE_CLICKED,
            System.currentTimeMillis(), 0, 5, 5, 1, false));
    }

    private static <T> List<T> all(Component c, Class<T> type) {
        List<T> out = new ArrayList<>();
        if (type.isInstance(c)) {
            out.add(type.cast(c));
        }
        if (c instanceof Container) {
            for (Component k : ((Container) c).getComponents()) {
                out.addAll(all(k, type));
            }
        }
        return out;
    }
}

package io.droptracker.ui.components;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.function.Consumer;

import com.google.gson.Gson;
import org.junit.Test;

import io.droptracker.api.DeathMessageApi;
import io.droptracker.models.api.DeathMessages;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * The plugin's death message editor, driven headless with a stub API: what it
 * shows, what it refuses, and what it sends.
 */
public class DeathMessageEditorTest {

    private static final Gson GSON = new Gson();

    private static final String LOADED =
        "{\"player_name\":\"Iron Ron\",\"max_messages\":5,\"max_length\":150,"
            + "\"messages\":[\"{player_name} planked\"],"
            + "\"tokens\":[{\"token\":\"{player_name}\",\"help\":\"Your name\",\"sample\":\"Zezima\"},"
            + "{\"token\":\"{killer}\",\"help\":\"What killed you\",\"sample\":\"Vorkath\"}],"
            + "\"groups\":[{\"id\":5,\"name\":\"Clan\",\"allowed\":true,\"blocked\":false}]}";

    /** Answers synchronously, as if the network were instant. */
    private static final class StubApi extends DeathMessageApi {
        int fetches;
        String lastType;
        String loaded = LOADED;
        List<String> saved;
        String saveError;

        StubApi() {
            super(null, null, null, null, null);
        }

        @Override
        public void fetch(String playerName, long accountHash, String type, Consumer<Result> callback) {
            fetches++;
            lastType = type;
            callback.accept(Result.ok(GSON.fromJson(loaded, DeathMessages.class)));
        }

        @Override
        public void save(String playerName, long accountHash, String type, List<String> messages,
                         Consumer<Result> callback) {
            lastType = type;
            saved = new ArrayList<>(messages);
            if (saveError != null) {
                callback.accept(Result.failed(saveError));
                return;
            }
            DeathMessages reply = GSON.fromJson(LOADED, DeathMessages.class);
            String json = GSON.toJson(reply).replace("[\"{player_name} planked\"]", GSON.toJson(messages));
            callback.accept(Result.ok(GSON.fromJson(json, DeathMessages.class)));
        }
    }

    private static DeathMessageEditor editor(StubApi api, long hash) {
        DeathMessageEditor editor = new DeathMessageEditor(api, () -> hash, () -> "Iron Ron", () -> { }, () -> { });
        editor.load();
        return editor;
    }

    @Test
    public void loadingFillsTheBoxesAndSaysWhereItPosts() {
        StubApi api = new StubApi();
        DeathMessageEditor editor = editor(api, 42L);
        assertEquals(1, api.fetches);
        assertEquals("{player_name} planked", editor.fields().get(0).getText());
        assertEquals("", editor.fields().get(1).getText());
        assertTrue(editor.fields().get(0).isEditable());
        assertFalse("nothing changed yet", editor.saveButton().isEnabled());
        assertTrue(editor.groupsLabelText(), editor.groupsLabelText().contains("Posted in: "));
        assertTrue(editor.previewText(), editor.previewText().contains("Example: Iron Ron planked"));
    }

    @Test
    public void aRuleBreakIsShownAndCannotBeSaved() {
        DeathMessageEditor editor = editor(new StubApi(), 42L);
        editor.fields().get(1).setText("free gp at www.scam.com");
        assertFalse(editor.saveButton().isEnabled());
        assertTrue(editor.statusText(), editor.statusText().contains("Messages can't contain links."));
    }

    @Test
    public void aValidEditSavesWhatTheServerWillStore() {
        StubApi api = new StubApi();
        DeathMessageEditor editor = editor(api, 42L);
        editor.fields().get(2).setText("  {Killer} got {player_name} again  ");
        assertTrue(editor.saveButton().isEnabled());
        editor.clickSave();
        assertEquals(Arrays.asList("{player_name} planked", "{killer} got {player_name} again"), api.saved);
        assertTrue(editor.statusText(), editor.statusText().contains("Saved."));
        assertFalse("saved, so nothing is unsaved", editor.saveButton().isEnabled());
        assertEquals("{killer} got {player_name} again", editor.fields().get(1).getText());
    }

    @Test
    public void clearingEveryBoxClearsTheMessages() {
        StubApi api = new StubApi();
        DeathMessageEditor editor = editor(api, 42L);
        editor.fields().get(0).setText("");
        editor.clickSave();
        assertEquals(Collections.emptyList(), api.saved);
        assertTrue(editor.statusText(), editor.statusText().contains("Cleared."));
    }

    @Test
    public void aRefusedSaveShowsTheServersWords() {
        StubApi api = new StubApi();
        api.saveError = "You can save at most 5 messages.";
        DeathMessageEditor editor = editor(api, 42L);
        editor.fields().get(1).setText("{player_name} again");
        editor.clickSave();
        assertTrue(editor.statusText(), editor.statusText().contains("You can save at most 5 messages."));
        assertTrue("still editable after a refusal", editor.fields().get(1).isEditable());
    }

    @Test
    public void loggedOutThereIsNothingToEdit() {
        StubApi api = new StubApi();
        DeathMessageEditor editor = editor(api, -1L);
        assertEquals(0, api.fetches);
        assertFalse(editor.fields().get(0).isEditable());
        assertFalse(editor.saveButton().isEnabled());
        assertTrue(editor.statusText(), editor.statusText().contains("Log in first"));
    }

    @Test
    public void aPlaceholderIsAddedWhereTheCursorIs() {
        DeathMessageEditor editor = editor(new StubApi(), 42L);
        editor.fields().get(0).setCaretPosition(editor.fields().get(0).getText().length());
        editor.clickToken("{killer}");
        assertEquals("{player_name} planked {killer}", editor.fields().get(0).getText());
    }

    @Test
    public void namesEachClanWithItsState() {
        String text = DeathMessageEditor.groupsText(Arrays.asList(
            group("{\"id\":1,\"name\":\"Posting Clan\",\"allowed\":true,\"blocked\":false}"),
            group("{\"id\":2,\"name\":\"Quiet Clan\",\"allowed\":false,\"blocked\":false}"),
            group("{\"id\":3,\"name\":\"Strict Clan\",\"allowed\":true,\"blocked\":true}")));
        assertTrue(text, text.contains("Posted in: "));
        assertTrue(text.contains("Posting Clan</font>"));
        assertTrue(text.contains("Quiet Clan (not switched on)"));
        assertTrue(text.contains("Strict Clan (blocked by its leaders)"));
    }

    @Test
    public void noClansSaysSo() {
        assertTrue(DeathMessageEditor.groupsText(Collections.emptyList()).contains("isn't in any clans"));
    }

    @Test
    public void clanNamesCannotInjectMarkup() {
        String text = DeathMessageEditor.groupsText(Collections.singletonList(
            group("{\"id\":1,\"name\":\"<b>Bold</b> & co\",\"allowed\":true,\"blocked\":false}")));
        assertFalse(text, text.contains("<b>"));
        assertTrue(text.contains("&lt;b&gt;Bold&lt;/b&gt; &amp; co"));
    }

    private static DeathMessages.Group group(String json) {
        return GSON.fromJson(json, DeathMessages.Group.class);
    }

    private static javax.swing.JComboBox<?> typeBox(java.awt.Container root) {
        for (java.awt.Component c : root.getComponents()) {
            if (c instanceof javax.swing.JComboBox) {
                return (javax.swing.JComboBox<?>) c;
            }
            if (c instanceof java.awt.Container) {
                javax.swing.JComboBox<?> found = typeBox((java.awt.Container) c);
                if (found != null) {
                    return found;
                }
            }
        }
        return null;
    }

    @Test
    public void deathsAreTheDefaultType() {
        StubApi api = new StubApi();
        editor(api, 42L);
        assertEquals("death", api.lastType);
    }

    @Test
    public void pickingATypeLoadsItsMessagesAndPlaceholders() {
        StubApi api = new StubApi();
        DeathMessageEditor editor = editor(api, 42L);
        api.loaded = "{\"player_name\":\"Iron Ron\",\"messages\":[\"{player_name} pb {boss}\"],"
            + "\"tokens\":[{\"token\":\"{player_name}\",\"help\":\"Your name\",\"sample\":\"Zezima\"},"
            + "{\"token\":\"{boss}\",\"help\":\"The boss\",\"sample\":\"Vorkath\"}],"
            + "\"aliases\":{\"{npc_name}\":\"{boss}\"},\"groups\":[]}";
        typeBox(editor).setSelectedIndex(3);
        assertEquals(2, api.fetches);
        assertEquals("pb", api.lastType);
        assertEquals("{player_name} pb {boss}", editor.fields().get(0).getText());

        // The type's own placeholders and aliases are accepted; death's are not.
        editor.fields().get(1).setText("{player_name} {npc_name}");
        assertTrue(editor.saveButton().isEnabled());
        editor.fields().get(1).setText("{player_name} {killer}");
        assertFalse(editor.saveButton().isEnabled());
        assertTrue(editor.statusText(), editor.statusText().contains("Unknown placeholder"));

        editor.fields().get(1).setText("");
        editor.fields().get(0).setText("{player_name} got {boss}");
        editor.clickSave();
        assertEquals("pb", api.lastType);
    }
}

package io.droptracker.ui.overlays.popup;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import io.droptracker.DropTrackerConfig;
import io.droptracker.models.EventDisplayMode;
import io.droptracker.models.EventPopupCard;
import io.droptracker.models.EventPopupStyle;
import io.droptracker.models.api.EventNotification;
import io.droptracker.models.api.EventState;
import io.droptracker.service.EventNotificationService;
import io.droptracker.service.EventNotificationService.Toast;
import io.droptracker.util.ChatMessageUtil;
import org.junit.Test;

import javax.imageio.ImageIO;
import java.awt.Color;
import java.awt.GradientPaint;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.io.File;
import java.io.IOException;
import java.time.LocalDateTime;
import java.time.ZoneOffset;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * Paints every pop-up style for every kind of news, through every stage of
 * its animation, off-screen: nothing may throw, and every card must take up
 * real space. The cards come from the service's real renderer, so this also
 * pins that each notification type fills in its showcase card.
 *
 * <p>Set POPUP_GALLERY_DIR to also write the frames out as PNGs (and
 * POPUP_SPRITES_DIR to a folder of {@code <itemId>.png} icons to use real
 * item sprites) for eyeballing layouts without a game client.
 */
public class PopupRenderersTest {
    private static final long[] AGES = {0, 60, 140, 240, 360, 520, 800, 1600};

    private final Gson gson = new Gson();

    @Test
    public void everyKindRendersAStructuredCard() {
        Map<String, Toast> toasts = sampleToasts();
        assertEquals(12, toasts.size());
        for (Map.Entry<String, Toast> entry : toasts.entrySet()) {
            EventPopupCard card = entry.getValue().getCard();
            assertNotNull(entry.getKey() + " has no card", card);
            assertTrue(entry.getKey(), !card.getHeadline().isEmpty());
        }
        EventPopupCard tile = toasts.get("tile").getCard();
        assertEquals(EventPopupCard.Kind.TILE, tile.getKind());
        assertEquals("Bandos set", tile.getHeadline());
        assertEquals("2nd of 5", tile.getRightValue());
        // Empty corners filled from the event state: points, team, tiles done.
        assertEquals("+10", tile.getLeft2Value());
        assertEquals("Iron Eagles", tile.getRight2Value());
        assertEquals("2d 4h left", tile.getNote());
        EventPopupCard progress = toasts.get("progress").getCard();
        assertEquals(0.4f, progress.fraction(), 0.001f);
        assertEquals("2/5", progress.getRightValue());
        assertEquals("3", progress.getRight2Value());

        // No item in the envelope: the task's own icon from the event state.
        Toast kc = toasts.get("kc");
        assertEquals(null, kc.getIconItemId());
        assertEquals("npcdb/8061.png", kc.getIconPath());
        assertEquals("metrics/slayer.png", toasts.get("xp").getIconPath());
        // Board rolls find the next task by label.
        assertEquals(Integer.valueOf(19529), toasts.get("board").getIconItemId());
        assertEquals("25 pts", toasts.get("board").getCard().getLeft2Value());
        // Team news about your own team shows its icon; the lead card says where you stand.
        assertEquals(Integer.valueOf(12000), toasts.get("line").getIconItemId());
        EventPopupCard lead = toasts.get("lead").getCard();
        assertEquals("In the lead!", lead.getLeftValue());
        EventPopupCard start = toasts.get("start").getCard();
        assertEquals("Iron Eagles", start.getLeftValue());
        assertEquals("5", start.getRightValue());
        assertEquals("2d 4h", start.getRight2Value());
    }

    @Test
    public void everyStylePaintsEveryKindThroughItsAnimation() throws IOException {
        PopupRenderers renderers = new PopupRenderers(PopupRenderersTest::sprite, PopupRenderersTest::remote);
        Map<String, Toast> toasts = sampleToasts();
        String galleryDir = System.getenv("POPUP_GALLERY_DIR");

        for (EventPopupStyle style : EventPopupStyle.values()) {
            PopupRenderer renderer = renderers.popup(style);
            paintAll(renderer, "popup-" + style.name().toLowerCase(), renderer.preferredWidth(), toasts,
                galleryDir);
        }
    }

    @Test
    public void displayTypePicksTheStyle() {
        assertEquals(EventPopupStyle.BANNER, EventDisplayMode.POPUP.popupStyle());
        assertEquals(EventPopupStyle.SHOWCASE, EventDisplayMode.ENHANCED.popupStyle());
        assertEquals(EventPopupStyle.SHOWCASE, EventPopupStyle.parse("Showcase"));
        assertEquals(null, EventPopupStyle.parse("stone"));
    }

    private void paintAll(PopupRenderer renderer, String name, int width, Map<String, Toast> toasts,
                          String galleryDir) throws IOException {
        // Settled frame of every kind, stacked, plus an animation strip of the tile.
        List<BufferedImage> settled = new ArrayList<>();
        for (Map.Entry<String, Toast> entry : toasts.entrySet()) {
            Toast toast = entry.getValue();
            BufferedImage last = null;
            for (long age : AGES) {
                last = paint(renderer, toast, width, toast.getCreatedAt() + age);
            }
            // Deep into the fade: still paints, just faint.
            paint(renderer, toast, width, toast.getCreatedAt() + toast.lifetimeMs() - 100);
            settled.add(last);
        }
        if (galleryDir == null) {
            return;
        }
        File dir = new File(galleryDir);
        dir.mkdirs();
        ImageIO.write(stack(settled, width), "png", new File(dir, name + ".png"));
        List<BufferedImage> strip = new ArrayList<>();
        Toast tile = toasts.get("tile");
        for (long age : new long[]{40, 120, 200, 300, 450, 700, 1200}) {
            strip.add(paint(renderer, tile, width, tile.getCreatedAt() + age));
        }
        ImageIO.write(row(strip), "png", new File(dir, name + "-anim.png"));
    }

    /** One card painted over a stand-in game backdrop. */
    private static BufferedImage paint(PopupRenderer renderer, Toast toast, int width, long now) {
        int canvasW = width + 20;
        int canvasH = 190;
        BufferedImage image = new BufferedImage(canvasW, canvasH, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = image.createGraphics();
        g.setPaint(new GradientPaint(0, 0, new Color(0x4c, 0x5a, 0x3a), 0, canvasH, new Color(0x2a, 0x30, 0x22)));
        g.fillRect(0, 0, canvasW, canvasH);
        g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
        int height = renderer.draw(g, toast, 10, 10, width, now);
        g.dispose();
        long age = now - toast.getCreatedAt();
        assertTrue("height " + height + " at age " + age, height > 0 && height < canvasH - 10);
        return image;
    }

    private static BufferedImage stack(List<BufferedImage> images, int width) {
        int h = 0;
        for (BufferedImage image : images) {
            h += image.getHeight();
        }
        BufferedImage out = new BufferedImage(width + 20, h, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = out.createGraphics();
        int y = 0;
        for (BufferedImage image : images) {
            g.drawImage(image, 0, y, null);
            y += image.getHeight();
        }
        g.dispose();
        return out;
    }

    private static BufferedImage row(List<BufferedImage> images) {
        int w = 0;
        for (BufferedImage image : images) {
            w += image.getWidth();
        }
        BufferedImage out = new BufferedImage(w, images.get(0).getHeight(), BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = out.createGraphics();
        int x = 0;
        for (BufferedImage image : images) {
            g.drawImage(image, x, 0, null);
            x += image.getWidth();
        }
        g.dispose();
        return out;
    }

    /** A server icon from POPUP_SPRITES_DIR/<path> when given, else a stand-in blob. */
    private static BufferedImage remote(String path) {
        String dir = System.getenv("POPUP_SPRITES_DIR");
        if (dir != null) {
            try {
                BufferedImage image = ImageIO.read(new File(dir, path));
                if (image != null) {
                    return image;
                }
            } catch (IOException ignored) {
                // fall through to the stand-in
            }
        }
        return sprite(-1);
    }

    /** A real sprite from POPUP_SPRITES_DIR when given, else a stand-in blob. */
    private static BufferedImage sprite(int itemId) {
        String dir = System.getenv("POPUP_SPRITES_DIR");
        if (dir != null) {
            try {
                BufferedImage image = ImageIO.read(new File(dir, itemId + ".png"));
                if (image != null) {
                    return image;
                }
            } catch (IOException ignored) {
                // fall through to the stand-in
            }
        }
        BufferedImage image = new BufferedImage(36, 32, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = image.createGraphics();
        g.setColor(new Color(0x9a, 0x7b, 0x4f));
        g.fillOval(6, 4, 24, 24);
        g.setColor(Color.BLACK);
        g.drawOval(6, 4, 24, 24);
        g.dispose();
        return image;
    }

    /* ---------------- samples, through the real renderer ---------------- */

    private Map<String, Toast> sampleToasts() {
        EventNotificationService service = new EventNotificationService(
            new DropTrackerConfig() {
                @Override
                public void setPinnedEventId(int eventId) {
                }

                @Override
                public void setLastVersionNotified(String versionNotified) {
                }

                @Override
                public void setLastAccountName(String accountName) {
                }

                @Override
                public void setCustomApiEndpoint(String customApiEndpoint) {
                }

                @Override
                public void setLastAccountHash(String accountHash) {
                }
            }, null, new ChatMessageUtil(), null, null, null, null);
        service.setPreviewHudEntry(sampleEntry(), Long.MAX_VALUE);
        Map<String, String> samples = new LinkedHashMap<>();
        samples.put("tile", "event_completion|high|{\"task_id\":1,\"task_label\":\"Obtain Bandos tassets\","
            + "\"player_name\":\"Zezima\",\"received_item\":\"Bandos tassets\",\"icon_item_id\":11834,"
            + "\"points\":10,\"team_name\":\"Iron Eagles\",\"cell_idxs\":[6],\"cell_labels\":[\"Bandos set\"],"
            + "\"tiles_completed\":7,\"team_rank\":2,\"team_count\":5}");
        samples.put("complete", "event_completion|normal|{\"task_id\":2,\"task_label\":\"Obtain a Dragon warhammer\","
            + "\"player_name\":\"Zezima\",\"received_item\":\"Dragon warhammer\",\"icon_item_id\":13576,\"points\":5}");
        samples.put("progress", "event_task_progress|low|{\"task_id\":3,\"task_label\":\"Obtain 5 Abyssal whips\","
            + "\"player_name\":\"Lynx Titan\",\"received_item\":\"Abyssal whip\",\"icon_item_id\":4151,"
            + "\"progress\":2,\"target\":5}");
        samples.put("kc", "event_completion|normal|{\"task_id\":41,\"task_label\":\"Kill Vorkath 50 times\","
            + "\"player_name\":\"Zezima\",\"points\":15,\"team_name\":\"Iron Eagles\"}");
        samples.put("xp", "event_task_progress|low|{\"task_id\":42,\"task_label\":\"Gain 2M Slayer XP\","
            + "\"player_name\":\"Lynx Titan\",\"progress\":1300000,\"target\":2000000}");
        samples.put("lead", "event_lead_change|high|{\"team_name\":\"Iron Eagles\",\"team_score\":1240}");
        samples.put("line", "event_line|high|{\"team_name\":\"Iron Eagles\",\"bonus_points\":25}");
        samples.put("blackout", "event_blackout|high|{\"team_name\":\"Iron Eagles\",\"bonus_points\":100}");
        samples.put("start", "event_started|high|{}");
        samples.put("end", "event_ended|high|{}");
        samples.put("board", "event_board_turn|normal|{\"player_name\":\"Zezima\",\"dice_str\":\"4 + 2\","
            + "\"tile_to\":18,\"next_task_label\":\"Obtain any Zenyte jewel\"}");
        samples.put("roll", "event_board_roll_prompt|high|{\"coins_awarded\":3}");

        long now = System.currentTimeMillis();
        // What the server composes for each sample (services/plugin_display.py,
        // read from sampleEntry's side); regenerate the resource if that changes.
        JsonObject displays = gson.fromJson(new InputStreamReader(
            getClass().getResourceAsStream("/io/droptracker/popup-samples.json"), StandardCharsets.UTF_8),
            JsonObject.class);
        String endsAt = sampleEntry().getEvent().getEndsAt();
        Map<String, Toast> toasts = new LinkedHashMap<>();
        for (Map.Entry<String, String> sample : samples.entrySet()) {
            String[] parts = sample.getValue().split("\\|", 3);
            EventNotification n = gson.fromJson("{\"id\":\"" + sample.getKey() + "\",\"type\":\"" + parts[0]
                + "\",\"ts\":1,\"priority\":\"" + parts[1] + "\","
                + "\"display\":" + displays.get(sample.getKey()).toString().replace("ENDS_AT", endsAt) + ","
                + "\"event\":{\"id\":7,\"name\":\"Autumn Bingo\"},\"data\":" + parts[2] + "}",
                EventNotification.class);
            service.getToasts().clear();
            // A tile folding two more updates exercises the "+N more" badges too.
            assertTrue(sample.getKey(), service.previewNotification(n, null,
                "tile".equals(sample.getKey()) ? 2 : 0));
            toasts.put(sample.getKey(), service.getToasts().getFirst().pinned(null, now));
        }
        return toasts;
    }

    /** The /event_state entry the samples' event (id 7) reads its context from. */
    private EventState.Entry sampleEntry() {
        String endsAt = LocalDateTime.now(ZoneOffset.UTC).plusDays(2).plusHours(4).plusMinutes(1)
            .withNano(0).toString();
        return gson.fromJson("{\"event\":{\"id\":7,\"name\":\"Autumn Bingo\",\"kind\":\"bingo\","
            + "\"has_bingo\":true,\"ends_at\":\"" + endsAt + "\"},"
            + "\"team\":{\"id\":3,\"name\":\"Iron Eagles\",\"icon_item_id\":12000,\"score\":1240,"
            + "\"rank\":1,\"team_count\":5},"
            + "\"tasks_completed\":7,\"tasks_total\":25,"
            + "\"tasks\":[{\"id\":41,\"label\":\"Kill Vorkath 50 times\",\"points\":15,"
            + "\"icon_path\":\"npcdb/8061.png\"},"
            + "{\"id\":42,\"label\":\"Gain 2M Slayer XP\",\"points\":20,\"icon_path\":\"metrics/slayer.png\"},"
            + "{\"id\":43,\"label\":\"Obtain any Zenyte jewel\",\"points\":25,\"icon_item_id\":19529}]}",
            EventState.Entry.class);
    }
}

