package io.droptracker.util;

import org.junit.Test;

import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Set;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

/**
 * Exercises the name to id inversion in {@link ItemIDSearch#populate}, the
 * pure core of the (network-backed) item cache. populate() is
 * {@code @VisibleForTesting} and does not touch the injected OkHttpClient/Gson,
 * so it can be driven directly without a live client.
 */
public class ItemIDSearchTest {

    @Test
    public void invertsNameToIdMapping() {
        ItemIDSearch search = new ItemIDSearch();
        Map<Integer, String> namesById = new HashMap<>();
        namesById.put(4151, "Abyssal whip");
        namesById.put(11802, "Armadyl godsword");

        search.populate(namesById, new HashSet<>());

        assertEquals(Integer.valueOf(4151), search.findItemId("Abyssal whip"));
        assertEquals(Integer.valueOf(11802), search.findItemId("Armadyl godsword"));
    }

    @Test
    public void skipsNotedItemIds() {
        ItemIDSearch search = new ItemIDSearch();
        Map<Integer, String> namesById = new HashMap<>();
        namesById.put(4151, "Abyssal whip");
        namesById.put(4152, "Abyssal whip"); // noted variant, same name

        Set<Integer> notedIds = new HashSet<>();
        notedIds.add(4152);

        search.populate(namesById, notedIds);

        assertEquals(Integer.valueOf(4151), search.findItemId("Abyssal whip"));
    }

    @Test
    public void keepsEarliestIdWhenNamesCollide() {
        ItemIDSearch search = new ItemIDSearch();
        // Insertion order preserved so the "earliest id wins" contract is deterministic.
        Map<Integer, String> namesById = new LinkedHashMap<>();
        namesById.put(1, "Coins");
        namesById.put(2, "Coins");
        namesById.put(3, "Coins");

        search.populate(namesById, new HashSet<>());

        assertEquals(Integer.valueOf(1), search.findItemId("Coins"));
    }

    @Test
    public void returnsNullForUnknownItem() {
        ItemIDSearch search = new ItemIDSearch();
        search.populate(new HashMap<>(), new HashSet<>());
        assertNull(search.findItemId("Twisted bow"));
    }
}

package io.droptracker.util;

import net.runelite.client.callback.ClientThread;
import net.runelite.client.util.AsyncBufferedImage;
import org.junit.Before;
import org.junit.Test;

import javax.swing.SwingUtilities;
import java.awt.image.BufferedImage;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.function.BooleanSupplier;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

/**
 * The panel's item icons must never land on the game thread in one burst:
 * sprite renders are paced per frame and callbacks run on the EDT.
 */
public class ItemImageCacheTest {
    /** Runs queued work one "frame" at a time; re-queues suppliers that return false. */
    private static final class FrameClientThread extends ClientThread {
        private ArrayDeque<BooleanSupplier> queue = new ArrayDeque<>();

        @Override
        public void invokeLater(Runnable r) {
            queue.add(() -> {
                r.run();
                return true;
            });
        }

        @Override
        public void invokeLater(BooleanSupplier r) {
            queue.add(r);
        }

        void frame() {
            ArrayDeque<BooleanSupplier> now = queue;
            queue = new ArrayDeque<>();
            for (BooleanSupplier r : now) {
                if (!r.getAsBoolean()) {
                    queue.add(r);
                }
            }
        }

        boolean idle() {
            return queue.isEmpty();
        }
    }

    private FrameClientThread clientThread;
    private AtomicInteger renders;
    private ItemImageCache cache;

    @Before
    public void setUp() {
        clientThread = new FrameClientThread();
        renders = new AtomicInteger();
        cache = new ItemImageCache(id -> {
            renders.incrementAndGet();
            AsyncBufferedImage image = new AsyncBufferedImage(clientThread, 36, 32,
                BufferedImage.TYPE_INT_ARGB);
            image.loaded();
            return image;
        }, clientThread);
    }

    private static void flushEdt() throws Exception {
        SwingUtilities.invokeAndWait(() -> { });
    }

    @Test
    public void rendersAtMostAFewSpritesPerFrame() {
        for (int id = 1; id <= 10; id++) {
            assertNull(cache.get(id, null));
        }
        assertEquals("nothing renders at request time", 0, renders.get());

        clientThread.frame();
        assertEquals(ItemImageCache.LOADS_PER_FRAME, renders.get());
        clientThread.frame();
        assertEquals(2 * ItemImageCache.LOADS_PER_FRAME, renders.get());
        clientThread.frame();
        assertEquals(10, renders.get());
        clientThread.frame(); // stores the last batch
        assertTrue(clientThread.idle());
    }

    @Test
    public void callbacksRunOnTheEdtAndHitsSkipTheLoader() throws Exception {
        List<Boolean> onEdt = new ArrayList<>();
        cache.get(42, image -> onEdt.add(SwingUtilities.isEventDispatchThread()));
        cache.get(42, image -> onEdt.add(SwingUtilities.isEventDispatchThread()));

        clientThread.frame(); // render
        clientThread.frame(); // onLoaded re-posts to the client thread, then stores
        flushEdt();

        assertEquals("one render for two requests", 1, renders.get());
        assertEquals(2, onEdt.size());
        assertTrue(onEdt.get(0) && onEdt.get(1));

        BufferedImage hit = cache.get(42, image -> onEdt.add(false));
        assertNotNull(hit);
        assertSame(hit, cache.get(42, null));
        assertEquals(1, renders.get());
        assertTrue("a hit schedules nothing on the client thread", clientThread.idle());
    }
}

package io.droptracker.util;

import net.runelite.client.game.ItemStack;
import org.junit.Test;

import java.util.Arrays;
import java.util.Collections;
import java.util.List;

import static org.junit.Assert.assertEquals;

/**
 * Tests {@link ItemStacks#signature}: the raid chest re-loot dedup compares
 * the loot-room bundle against the bank collection chest bundle, so the
 * signature must be identical for the same items regardless of event order or
 * stack fragmentation, and must differ whenever ids or quantities differ.
 */
public class ItemStacksTest {

    @Test
    public void signatureIsOrderIndependent() {
        List<ItemStack> a = Arrays.asList(new ItemStack(565, 500), new ItemStack(22446, 1));
        List<ItemStack> b = Arrays.asList(new ItemStack(22446, 1), new ItemStack(565, 500));
        assertEquals(ItemStacks.signature(a), ItemStacks.signature(b));
    }

    @Test
    public void signatureConsolidatesSplitStacks() {
        List<ItemStack> split = Arrays.asList(new ItemStack(565, 300), new ItemStack(565, 200));
        List<ItemStack> whole = Collections.singletonList(new ItemStack(565, 500));
        assertEquals(ItemStacks.signature(whole), ItemStacks.signature(split));
    }

    @Test
    public void signatureDistinguishesQuantities() {
        String x = ItemStacks.signature(Collections.singletonList(new ItemStack(565, 500)));
        String y = ItemStacks.signature(Collections.singletonList(new ItemStack(565, 501)));
        assertEquals(false, x.equals(y));
    }

    @Test
    public void emptyBundleHasEmptySignature() {
        assertEquals("", ItemStacks.signature(Collections.emptyList()));
    }
}

package io.droptracker.util;

import java.util.Arrays;
import java.util.Collections;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * Locks the boss-name canonicalisation and multi-path detection that drive
 * {@code DropHandler}'s cross-handler duplicate-loot suppression. A regression
 * here would either re-introduce the Grotesque Guardians / Maggot King double
 * submissions or (worse) start de-duplicating ordinary AoE multi-kills.
 */
public class NpcUtilitiesCanonicalizeTest {

    @Test
    public void remapsSubNpcsToEncounterName() {
        assertEquals("Grotesque Guardians", NpcUtilities.canonicalizeSpecialSource("Dusk"));
        assertEquals("Royal Titans", NpcUtilities.canonicalizeSpecialSource("Branda the Fire Queen"));
        assertEquals("Royal Titans", NpcUtilities.canonicalizeSpecialSource("Eldric the Ice King"));
        assertEquals("The Corrupted Gauntlet", NpcUtilities.canonicalizeSpecialSource("Corrupted Hunllef"));
        assertEquals("The Gauntlet", NpcUtilities.canonicalizeSpecialSource("Crystalline Hunllef"));
    }

    @Test
    public void leavesOtherNamesUnchangedAndIsIdempotent() {
        assertEquals("Maggot King", NpcUtilities.canonicalizeSpecialSource("Maggot King"));
        assertEquals("Zulrah", NpcUtilities.canonicalizeSpecialSource("Zulrah"));
        // Applying it to an already-canonical name must be a no-op (both loot
        // paths canonicalise, so double application happens in practice).
        assertEquals("Grotesque Guardians", NpcUtilities.canonicalizeSpecialSource("Grotesque Guardians"));
        assertNull(NpcUtilities.canonicalizeSpecialSource(null));
    }

    @Test
    public void multiPathSourcesAreExactlyTheDoublingBosses() {
        // Canonical encounter names that can arrive via >1 loot event -> dedup on.
        assertTrue(NpcUtilities.isMultiPathLootSource("Grotesque Guardians"));
        assertTrue(NpcUtilities.isMultiPathLootSource("Royal Titans"));
        assertTrue(NpcUtilities.isMultiPathLootSource("The Gauntlet"));
        assertTrue(NpcUtilities.isMultiPathLootSource("The Corrupted Gauntlet"));
        assertTrue(NpcUtilities.isMultiPathLootSource("Maggot King"));
        assertTrue(NpcUtilities.isMultiPathLootSource("Araxxor"));
        assertTrue(NpcUtilities.isMultiPathLootSource("The Whisperer"));
    }

    /**
     * Mad Angel (Wyrmscraig, 2026-07-29) awards loot server-side. Until its ids
     * were listed here, {@code DropTrackerPlugin.onServerNpcLoot} returned early
     * and every drop was discarded — kills still registered (PBs landed) so the
     * gap was invisible from the outside. Every in-game variant must be covered,
     * or the quest kill (or the repeatable one) silently stops tracking loot.
     */
    @Test
    public void madAngelVariantsAreServerLootSources() {
        assertTrue(NpcUtilities.SERVER_LOOT_NPC_IDS.contains(NpcUtilities.MAD_ANGEL_QUEST_A));
        assertTrue(NpcUtilities.SERVER_LOOT_NPC_IDS.contains(NpcUtilities.MAD_ANGEL_QUEST_B));
        assertTrue(NpcUtilities.SERVER_LOOT_NPC_IDS.contains(NpcUtilities.MAD_ANGEL_POST_QUEST_A));
        assertTrue(NpcUtilities.SERVER_LOOT_NPC_IDS.contains(NpcUtilities.MAD_ANGEL_POST_QUEST_B));
    }

    /**
     * Mad Angel loot arrives on exactly one path (ServerNpcLoot), so it must not
     * be treated as multi-path: that dedup key is item-signature based, and a
     * boss with a 100% common drop would have back-to-back identical kills
     * suppressed as "duplicates".
     */
    @Test
    public void madAngelIsNotMultiPath() {
        assertFalse(NpcUtilities.isMultiPathLootSource("Mad Angel"));
    }

    /**
     * The published list layers over the compiled-in one; it never replaces it.
     * A backend that drops an id (or serves an older list than the build) must
     * not be able to switch off loot tracking for a boss this build already
     * knows about.
     */
    @Test
    public void publishedListAddsToCompiledInList() {
        NpcUtilities.setRemoteServerLootNpcIds(Arrays.asList(999001, 999002));
        assertTrue(NpcUtilities.isServerLootNpc(999001));
        assertTrue(NpcUtilities.isServerLootNpc(999002));
        // ...and everything compiled in still qualifies.
        assertTrue(NpcUtilities.isServerLootNpc(NpcUtilities.MAD_ANGEL_QUEST_B));
        assertFalse(NpcUtilities.isServerLootNpc(999003));
    }

    /**
     * A failed fetch returns null and an empty/garbage file parses to an empty
     * list. Either must leave the previous state untouched rather than wiping
     * it — otherwise an unreachable GitHub Pages would silently stop loot
     * tracking for every server-loot boss, which is the exact outage this
     * mechanism exists to prevent.
     */
    @Test
    public void failedOrEmptyFetchLeavesCompiledInListIntact() {
        NpcUtilities.setRemoteServerLootNpcIds(Collections.singletonList(999004));
        NpcUtilities.setRemoteServerLootNpcIds(null);
        assertTrue("null fetch must not clear the overlay", NpcUtilities.isServerLootNpc(999004));
        NpcUtilities.setRemoteServerLootNpcIds(Collections.emptyList());
        assertTrue("empty fetch must not clear the overlay", NpcUtilities.isServerLootNpc(999004));
        // The compiled-in ids survive regardless of what the backend serves.
        assertTrue(NpcUtilities.isServerLootNpc(NpcUtilities.MAD_ANGEL_POST_QUEST_A));
    }

    @Test
    public void ordinaryNpcsAreNotMultiPath() {
        // These fire one NpcLootReceived per death and are legitimately
        // multi-killed in a tick with identical loot; must NOT be de-duplicated.
        assertFalse(NpcUtilities.isMultiPathLootSource("Maniacal monkey"));
        assertFalse(NpcUtilities.isMultiPathLootSource("Hill Giant"));
        assertFalse(NpcUtilities.isMultiPathLootSource("Zulrah"));
        assertFalse(NpcUtilities.isMultiPathLootSource(null));
    }
}

package io.droptracker.util;

import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Pins which sources hold their screenshot back a game tick (issue #48).
 * Nightmare announces its loot the tick after the loot event, so capturing
 * the next frame immediately photographs the moment before the drop message
 * exists and the screenshot can't corroborate the drop.
 */
public class NpcUtilitiesDeferredScreenshotTest {

    @Test
    public void bothNightmareVariantsDeferTheirScreenshot() {
        assertTrue(NpcUtilities.needsDeferredScreenshot("Phosani's Nightmare"));
        assertTrue(NpcUtilities.needsDeferredScreenshot("The Nightmare"));
    }

    @Test
    public void ordinaryBossesCaptureImmediately() {
        // Deferring costs a tick of latency, so the set stays narrow.
        assertFalse(NpcUtilities.needsDeferredScreenshot("Zulrah"));
        assertFalse(NpcUtilities.needsDeferredScreenshot("Vorkath"));
        assertFalse(NpcUtilities.needsDeferredScreenshot("Theatre of Blood"));
        assertFalse(NpcUtilities.needsDeferredScreenshot("Grotesque Guardians"));
    }

    @Test
    public void unknownAndMissingSourcesCaptureImmediately() {
        // extractSourceName returns null when an embed carries no source
        // field; that must not blow up the capture path.
        assertFalse(NpcUtilities.needsDeferredScreenshot(null));
        assertFalse(NpcUtilities.needsDeferredScreenshot(""));
    }

    @Test
    public void matchesTheCanonicalNameTheDropEmbedActuallyCarries() {
        // DropHandler puts the canonicalised name in the embed's "source"
        // field, which is what the capture gate reads — so the set has to
        // hold post-canonicalisation spellings, not raw sub-NPC names.
        assertTrue(NpcUtilities.needsDeferredScreenshot(
            NpcUtilities.canonicalizeSpecialSource("The Nightmare")));
        assertTrue(NpcUtilities.needsDeferredScreenshot(
            NpcUtilities.canonicalizeSpecialSource("Phosani's Nightmare")));
    }
}

package io.droptracker.util;

import org.junit.Test;

import java.util.regex.Matcher;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * Tests the kill-count chat patterns used by {@link NpcUtilities#parseBoss}.
 * These drive KC attribution on every drop, so a broken group name silently
 * mis-tags submissions.
 */
public class NpcUtilitiesParseTest {

    @Test
    public void primaryMatchesKillCount() {
        Matcher m = NpcUtilities.PRIMARY_REGEX.matcher("Your Zulrah kill count is: 1,234");
        assertTrue(m.find());
        assertEquals("Zulrah", m.group("key"));
        assertEquals("kill", m.group("type"));
        assertEquals("1,234", m.group("value"));
    }

    @Test
    public void primaryMatchesMultiWordBoss() {
        Matcher m = NpcUtilities.PRIMARY_REGEX.matcher("Your Grotesque Guardians kill count is: 500");
        assertTrue(m.find());
        assertEquals("Grotesque Guardians", m.group("key"));
        assertEquals("500", m.group("value"));
    }

    @Test
    public void primaryMatchesChestAndCompletionAndSuccess() {
        Matcher chest = NpcUtilities.PRIMARY_REGEX.matcher("Your Barrows chest count is: 42");
        assertTrue(chest.find());
        assertEquals("Barrows", chest.group("key"));
        assertEquals("chest", chest.group("type"));

        Matcher completion = NpcUtilities.PRIMARY_REGEX.matcher("Your Gauntlet completion count is: 5");
        assertTrue(completion.find());
        assertEquals("completion", completion.group("type"));

        Matcher success = NpcUtilities.PRIMARY_REGEX.matcher("Your Wintertodt success count is: 300");
        assertTrue(success.find());
        assertEquals("success", success.group("type"));
    }

    @Test
    public void secondaryMatchesCompletedRaid() {
        Matcher m = NpcUtilities.SECONDARY_REGEX.matcher("Your completed Theatre of Blood count is: 5");
        assertTrue(m.find());
        assertEquals("completed", m.group("type"));
        assertEquals("Theatre of Blood", m.group("key"));
        assertEquals("5", m.group("value"));
    }

    @Test
    public void primaryDoesNotMatchUnrelatedMessages() {
        assertFalse(NpcUtilities.PRIMARY_REGEX.matcher("You have a funny feeling...").find());
        assertFalse(NpcUtilities.PRIMARY_REGEX.matcher("Your Attack level is now 70.").find());
    }

    // --- parsePrimaryBoss: only certain (boss,type) combinations are valid KC lines ---

    @Test
    public void primaryBossKeepsKillAndSuccessNamesVerbatim() {
        assertEquals("Zulrah", NpcUtilities.parsePrimaryBoss("Zulrah", "kill"));
        assertEquals("Wintertodt", NpcUtilities.parsePrimaryBoss("Wintertodt", "success"));
    }

    @Test
    public void primaryBossOnlyAcceptsBarrowsAndLunarChests() {
        assertEquals("Barrows", NpcUtilities.parsePrimaryBoss("Barrows", "chest"));
        assertEquals("Lunar chest", NpcUtilities.parsePrimaryBoss("Lunar", "chest"));
        // Any other "chest" source is not a tracked boss.
        assertNull(NpcUtilities.parsePrimaryBoss("Random", "chest"));
    }

    @Test
    public void primaryBossMapsGauntletCompletionToHunllef() {
        assertEquals("Crystalline Hunllef", NpcUtilities.parsePrimaryBoss("Gauntlet", "completion"));
        assertEquals("Corrupted Hunllef", NpcUtilities.parsePrimaryBoss("Corrupted Gauntlet", "completion"));
        assertNull(NpcUtilities.parsePrimaryBoss("Zulrah", "completion"));
    }

    // --- parseSecondary: raids + Wintertodt only ---

    @Test
    public void secondaryKeepsWintertodtAndRaids() {
        assertEquals("Wintertodt", NpcUtilities.parseSecondary("Wintertodt"));
        assertEquals("Theatre of Blood", NpcUtilities.parseSecondary("Theatre of Blood"));
        assertEquals("Theatre of Blood: Hard Mode",
                NpcUtilities.parseSecondary("Theatre of Blood: Hard Mode"));
    }

    @Test
    public void secondaryRejectsNonRaidNames() {
        assertNull(NpcUtilities.parseSecondary("Some Random Boss"));
        // "Your completed Fractured Archive count is: N" — without this the
        // raid's kill count was discarded and its loot went out with none.
        assertEquals("Fractured Archive", NpcUtilities.parseSecondary("Fractured Archive"));
    }
}

package io.droptracker.util;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * The plugin used to submit the literal name "Unknown" whenever the RSN was
 * unreadable. That string matches an empty Wise Old Man record, and adopting it
 * renamed whichever live account the submission resolved to — three weeks of one
 * player's drops, clogs, CAs and PBs were discarded in silence before it was
 * caught. These tests pin the replacement: resolve honestly, or return null so
 * the caller skips the submission.
 */
public class PlayerIdentityTest {

    private static final String HASH = "1234567890123456";

    @Test
    public void liveNameWins() {
        assertEquals("Beast_Owned", PlayerIdentity.resolve("Beast_Owned", HASH, "Someone Else", HASH));
    }

    @Test
    public void neverSubstitutesAPlaceholder() {
        assertNull(PlayerIdentity.resolve(null, HASH, null, null));
        assertNull(PlayerIdentity.resolve("", HASH, null, null));
        assertNull(PlayerIdentity.resolve("   ", HASH, "", HASH));
    }

    // The login window: the name has not arrived yet, but the account hash has,
    // and it matches the one the cached name was stored against.
    @Test
    public void fallsBackToTheCachedNameForTheSameAccount() {
        assertEquals("Wimi", PlayerIdentity.resolve(null, HASH, "Wimi", HASH));
        assertEquals("Wimi", PlayerIdentity.resolve("", HASH, "Wimi", " " + HASH + " "));
    }

    // The whole point of keying the fallback on the hash: after hopping to a
    // second account, the cached name belongs to the first one. Attributing a
    // drop to it would be the same class of bug as "Unknown".
    @Test
    public void refusesACachedNameFromADifferentAccount() {
        assertNull(PlayerIdentity.resolve(null, "9999999999999999", "Wimi", HASH));
    }

    // Logged out (-1) or no client at all (0): nothing to attribute an event to,
    // and both are strings the backend would try to match a player row against.
    @Test
    public void refusesACachedNameWithoutALoggedInAccount() {
        assertNull(PlayerIdentity.resolve(null, "-1", "Wimi", "-1"));
        assertNull(PlayerIdentity.resolve(null, "0", "Wimi", "0"));
        assertNull(PlayerIdentity.resolve(null, null, "Wimi", HASH));
        assertNull(PlayerIdentity.resolve(null, "", "Wimi", ""));
    }

    @Test
    public void usableAccountHashRejectsTheSentinels() {
        assertTrue(PlayerIdentity.isUsableAccountHash(HASH));
        assertFalse(PlayerIdentity.isUsableAccountHash("0"));
        assertFalse(PlayerIdentity.isUsableAccountHash("-1"));
        assertFalse(PlayerIdentity.isUsableAccountHash(" "));
        assertFalse(PlayerIdentity.isUsableAccountHash(null));
    }

    // "Unknown" is a legal RSN — a real player could be called that. The guard
    // keys on the name being absent, never on its spelling, so a player named
    // Unknown keeps submitting normally.
    @Test
    public void doesNotBlacklistTheNameItself() {
        assertEquals("Unknown", PlayerIdentity.resolve("Unknown", HASH, null, null));
        assertFalse(PlayerIdentity.isMissingName("Unknown"));
    }

    @Test
    public void missingNameCoversNullAndBlank() {
        assertTrue(PlayerIdentity.isMissingName(null));
        assertTrue(PlayerIdentity.isMissingName(""));
        assertTrue(PlayerIdentity.isMissingName("   "));
        assertFalse(PlayerIdentity.isMissingName("Wimi"));
    }
}

package io.droptracker.util;

import com.google.gson.Gson;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;

public class RegionNameRegistryTest {

    // Tests are not part of the shipped plugin jar, so constructing a plain
    // Gson here does not trip the plugin-hub instantiation check.
    private static final RegionNameRegistry REGISTRY = new RegionNameRegistry(new Gson());

    /**
     * region_names.json was extracted from the 397 region-carrying constants of
     * RuneLite's DiscordGameEventType, covering 974 distinct region ids. If the
     * resource is regenerated against a newer RuneLite these counts move, and
     * that should be a deliberate change rather than a silent one.
     */
    @Test
    public void registryCoversExpectedRegionCount() {
        assertEquals(974, REGISTRY.size());
    }

    @Test
    public void namesRaidRegions() {
        // Every region of a multi-region raid resolves to the same area.
        assertEquals("Theatre of Blood", REGISTRY.nameOf(12867));
        assertEquals("Theatre of Blood", REGISTRY.nameOf(13379));
        assertEquals("Chambers of Xeric", REGISTRY.nameOf(12889));
        assertEquals("Tombs of Amascut", REGISTRY.nameOf(14160));
    }

    @Test
    public void namesBossRegions() {
        assertEquals("Vorkath", REGISTRY.nameOf(9023));
        assertEquals("Cerberus", REGISTRY.nameOf(4883));
        assertEquals("Cerberus", REGISTRY.nameOf(5395));
    }

    @Test
    public void namesTheRegionTheEmbedEditorAdvertises() {
        // The custom-embed UI documents {location} with this exact sample.
        assertEquals("Catacombs of Kourend", REGISTRY.nameOf(6557));
    }

    @Test
    public void reportsAreaType() {
        assertEquals("RAIDS", REGISTRY.typeOf(12867));
        assertEquals("BOSSES", REGISTRY.typeOf(9023));
        assertEquals("DUNGEONS", REGISTRY.typeOf(6557));
        assertEquals("CITIES", REGISTRY.typeOf(12850));
        assertEquals("MINIGAMES", REGISTRY.typeOf(9043));
        assertEquals("REGIONS", REGISTRY.typeOf(12598));
    }

    @Test
    public void lookupExposesNameAndType() {
        RegionNameRegistry.Area area = REGISTRY.lookup(12598);
        assertNotNull(area);
        assertEquals("Grand Exchange", area.getName());
        assertEquals("REGIONS", area.getType());
    }

    @Test
    public void unmappedRegionResolvesToNull() {
        // Callers fall back to reporting the bare region id, so null is the
        // contract for "no name" rather than an empty string.
        assertNull(REGISTRY.lookup(0));
        assertNull(REGISTRY.nameOf(0));
        assertNull(REGISTRY.typeOf(0));
        assertNull(REGISTRY.nameOf(-1));
    }
}

package io.droptracker.util;

import org.junit.Test;

import static org.junit.Assert.assertEquals;

/**
 * Pins the event-progress number formatting. A regression here silently
 * mis-renders every HUD progress bar and panel "have / need" row.
 */
public class ValueFormatTest {

    @Test
    public void commasGroupsThousands() {
        assertEquals("500", ValueFormat.commas(500));
        assertEquals("9,999", ValueFormat.commas(9_999));
        assertEquals("10,000,000", ValueFormat.commas(10_000_000));
        assertEquals("0", ValueFormat.commas(0));
        assertEquals("-1,234", ValueFormat.commas(-1_234));
    }

    @Test
    public void abbrevLeavesSmallValuesGrouped() {
        // Below the 10K threshold, abbrev falls through to comma grouping.
        assertEquals("500", ValueFormat.abbrev(500));
        assertEquals("9,999", ValueFormat.abbrev(9_999));
    }

    @Test
    public void abbrevUsesThousandsSuffix() {
        assertEquals("10K", ValueFormat.abbrev(10_000));
        assertEquals("813.6K", ValueFormat.abbrev(813_636));
        assertEquals("100K", ValueFormat.abbrev(100_000));
    }

    @Test
    public void abbrevUsesMillionsSuffix() {
        assertEquals("1M", ValueFormat.abbrev(1_000_000));
        assertEquals("1.25M", ValueFormat.abbrev(1_250_000));
        assertEquals("10M", ValueFormat.abbrev(10_000_000));
    }

    @Test
    public void abbrevUsesBillionsSuffix() {
        assertEquals("1B", ValueFormat.abbrev(1_000_000_000L));
        assertEquals("2.15B", ValueFormat.abbrev(2_147_483_647L));
    }

    @Test
    public void abbrevHandlesNegativesByMagnitude() {
        assertEquals("-1M", ValueFormat.abbrev(-1_000_000));
        assertEquals("-2.5M", ValueFormat.abbrev(-2_500_000));
    }

    @Test
    public void progressGroupsWhenBothSidesAreSmall() {
        assertEquals("50 / 100", ValueFormat.progress(50, 100));
        assertEquals("0 / 99,999", ValueFormat.progress(0, 99_999));
    }

    @Test
    public void progressAbbreviatesWhenEitherSideIsLarge() {
        assertEquals("5 / 100K", ValueFormat.progress(5, 100_000));
        assertEquals("150K / 200K", ValueFormat.progress(150_000, 200_000));
        assertEquals("5M / 10M", ValueFormat.progress(5_000_000, 10_000_000));
    }
}

package io.droptracker.util;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class VersionUtilTest {

    @Test
    public void equalVersions() {
        assertEquals(0, VersionUtil.compare("5.4.0", "5.4.0"));
        assertEquals(0, VersionUtil.compare("5.4", "5.4.0"));
        assertEquals(0, VersionUtil.compare("v5.4.0", "5.4.0"));
    }

    @Test
    public void ordering() {
        assertTrue(VersionUtil.compare("5.4.0", "5.5.0") < 0);
        assertTrue(VersionUtil.compare("5.10.0", "5.9.9") > 0);
        assertTrue(VersionUtil.compare("4.9.9", "5.0.0") < 0);
        assertTrue(VersionUtil.compare("5.4.1", "5.4.0") > 0);
    }

    @Test
    public void isOlderThan() {
        assertTrue(VersionUtil.isOlderThan("5.4.0", "5.5.0"));
        assertFalse(VersionUtil.isOlderThan("5.5.0", "5.5.0"));
        assertFalse(VersionUtil.isOlderThan("5.6.0", "5.5.0"));
    }

    @Test
    public void malformedInputsAreSafe() {
        assertEquals(0, VersionUtil.compare(null, "0"));
        assertEquals(0, VersionUtil.compare("", "0"));
        assertTrue(VersionUtil.compare("abc", "1.0") < 0);
        assertEquals(0, VersionUtil.compare("5.x.0", "5.0.0"));
    }
}

package io.droptracker.util;

import java.util.EnumSet;
import net.runelite.api.WorldType;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The world_type tag the server routes submissions by. Anything not MAIN is
 * kept away from main-game data (api/routes/webhook.py).
 */
public class WorldTypesTest {

    @Test
    public void regularWorldsAreMain() {
        assertEquals("MAIN", WorldTypes.submissionName(EnumSet.noneOf(WorldType.class)));
        assertEquals("MAIN", WorldTypes.submissionName(EnumSet.of(WorldType.MEMBERS)));
        assertTrue(WorldTypes.isMainWorld(EnumSet.of(WorldType.MEMBERS, WorldType.SKILL_TOTAL)));
    }

    @Test
    public void pvpAndLmsWorldsPlayTheMainCharacter() {
        assertTrue(WorldTypes.isMainWorld(EnumSet.of(WorldType.MEMBERS, WorldType.PVP)));
        assertTrue(WorldTypes.isMainWorld(EnumSet.of(WorldType.MEMBERS, WorldType.PVP, WorldType.HIGH_RISK)));
        assertTrue(WorldTypes.isMainWorld(EnumSet.of(WorldType.LAST_MAN_STANDING)));
    }

    @Test
    public void hardcoreWorldsAreKeptApart() {
        assertEquals("HARDCORE_MAIN", WorldTypes.submissionName(EnumSet.of(WorldType.MEMBERS, WorldType.HARDCORE_MAIN)));
        assertFalse(WorldTypes.isMainWorld(EnumSet.of(WorldType.HARDCORE_MAIN)));
    }

    @Test
    public void betaWinsOverEverythingElse() {
        assertEquals("BETA_WORLD", WorldTypes.submissionName(EnumSet.of(WorldType.BETA_WORLD, WorldType.HARDCORE_MAIN)));
        assertEquals("BETA_WORLD", WorldTypes.submissionName(EnumSet.of(WorldType.BETA_WORLD, WorldType.SEASONAL)));
    }

    @Test
    public void temporaryWorldsAreNotMain() {
        assertEquals("SEASONAL", WorldTypes.submissionName(EnumSet.of(WorldType.MEMBERS, WorldType.SEASONAL)));
        assertEquals("DEADMAN", WorldTypes.submissionName(EnumSet.of(WorldType.DEADMAN, WorldType.SEASONAL)));
        assertFalse(WorldTypes.isMainWorld(EnumSet.of(WorldType.FRESH_START_WORLD)));
        assertFalse(WorldTypes.isMainWorld(EnumSet.of(WorldType.TOURNAMENT_WORLD)));
    }
}
